.wrapper {
  position: relative;
  display: flex;
  align-items: center;
}

.triggerBtn {
  width: var(--lumiverse-btn-icon);
  height: var(--lumiverse-btn-icon);
  display: flex;
  align-items: center;
  justify-content: center;
  background: none;
  border: none;
  color: var(--lumiverse-text-dim);
  border-radius: 6px;
  cursor: pointer;
  position: relative;
  transition: all var(--lumiverse-transition-fast);
}

.triggerBtn:hover,
.triggerBtnActive {
  color: var(--lumiverse-text);
  background: var(--lumiverse-fill-hover);
}

.badge {
  position: absolute;
  top: 3px;
  right: 3px;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--lumiverse-primary);
}

.popover {
  position: absolute;
  bottom: 100%;
  left: 50%;
  transform: translateX(-50%);
  z-index: 200;
  min-width: 220px;
  background: var(--lumiverse-fill);
  border: 1px solid var(--lumiverse-border);
  border-radius: 10px;
  padding: 10px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.3);
  margin-bottom: 6px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.popoverTitle {
