.wrapper {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.strip {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.thumbGrid {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 6px;
  max-width: 186px;
}

/* ── Individual thumb ── */
.thumb {
  position: relative;
  width: 36px;
  height: 36px;
  padding: 0;
  border: none;
  border-radius: 50%;
  background: none;
  cursor: pointer;
  flex-shrink: 0;
  outline: 2px solid transparent;
  outline-offset: 2px;
  transition:
    outline-color 0.2s ease,
    transform 0.15s ease;
}

.thumb:hover {
  transform: scale(1.1);
}

.thumb:active {
  transform: scale(0.94);
}

.thumbActive {
  outline-color: var(--lumiverse-primary, rgba(140, 130, 255, 0.85));
}

.thumbImg {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  object-fit: cover;
  display: block;
  border: 1.5px solid var(--lcs-glass-border, rgba(255, 255, 255, 0.08));
  filter: brightness(0.72) saturate(0.75);
  transition:
    filter 0.2s ease,
    border-color 0.2s ease;
}

.thumb:hover .thumbImg {
  filter: brightness(0.92) saturate(0.9);
  border-color: var(--lcs-glass-border-hover, rgba(255, 255, 255, 0.14));
}

.thumbActive .thumbImg {
  filter: none;
  border-color: var(--lumiverse-primary-040, rgba(140, 130, 255, 0.35));
}

.thumbFallback {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  background: var(--lumiverse-fill, rgba(255, 255, 255, 0.06));
  border: 1.5px solid var(--lcs-glass-border, rgba(255, 255, 255, 0.08));
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--lumiverse-text-dim, rgba(230, 230, 240, 0.3));
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
}

/* ── Overflow "+N" button ── */
.moreBtn {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 1.5px dashed var(--lcs-glass-border, rgba(255, 255, 255, 0.1));
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.03));
  color: var(--lumiverse-text-muted, rgba(230, 230, 240, 0.45));
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  letter-spacing: -0.03em;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition:
    background 0.15s ease,
    color 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease;
}

.moreBtn:hover {
  background: var(--lumiverse-fill, rgba(255, 255, 255, 0.06));
  color: var(--lumiverse-text, rgba(230, 230, 240, 0.88));
  border-color: var(--lumiverse-primary-040, rgba(140, 130, 255, 0.35));
  transform: scale(1.1);
}

/* ── Collapse chevron ── */
.collapseBtn {
  background: none;
  border: none;
  color: var(--lumiverse-text-dim, rgba(230, 230, 240, 0.25));
  cursor: pointer;
  padding: 1px 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  transition:
    color 0.15s ease,
    background 0.15s ease;
}

.collapseBtn:hover {
  color: var(--lumiverse-text-muted, rgba(230, 230, 240, 0.5));
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.03));
}

/* ── Responsive: narrow panel ── */
@media (min-width: 601px) and (max-width: 900px) {
  .thumbGrid {
    max-width: 144px;
  }

  .thumb,
  .moreBtn {
    width: 30px;
    height: 30px;
  }

  .moreBtn {
    font-size: calc(9px * var(--lumiverse-font-scale, 1));
  }

  .thumbImg {
    border-width: 1px;
  }

  .thumbFallback {
    font-size: calc(10px * var(--lumiverse-font-scale, 1));
    border-width: 1px;
  }
}

import { useState, useCallback, useMemo } from 'react'
import { useTranslation } from 'react-i18next'
import { motion } from 'motion/react'
import { ChevronUp } from 'lucide-react'
import { useStore } from '@/store'
import { imagesApi } from '@/api/images'
import LazyImage from '@/components/shared/LazyImage'
import styles from './AvatarSwitcherPopover.module.css'
import clsx from 'clsx'
import { applyChatAppearance } from '@/lib/chatAppearance'
import { PRIMARY_AVATAR_ENTRY_ID } from '@/lib/avatarBindings'
import { toast } from '@/lib/toast'

interface AlternateAvatarEntry {
  id: string
  image_id: string
  label: string
}

interface Props {
  chatId: string
  children: React.ReactNode
}

const THUMBS_PER_ROW = 4
const MAX_VISIBLE_COLLAPSED = THUMBS_PER_ROW * 2

export default function AvatarSwitcherPopover({ chatId, children }: Props) {
  const { t } = useTranslation('chat')
  const [expanded, setExpanded] = useState(false)

  const activeCharacterId = useStore((s) => s.activeCharacterId)
  const characters = useStore((s) => s.characters)
  const character = characters.find((c) => c.id === activeCharacterId)
  const activeAvatarId = useStore((s) => s.activeChatAvatarId)

  const alternates = useMemo(
    () => (character?.extensions?.alternate_avatars || []) as AlternateAvatarEntry[],
    [character?.extensions?.alternate_avatars],
  )

  const allAvatars = useMemo(() => {
    const list: { key: string; entryId: string; imageId: string | null; label: string }[] = []
    if (character?.image_id) {
      list.push({ key: 'primary', entryId: PRIMARY_AVATAR_ENTRY_ID, imageId: null, label: t('avatarSwitcher.primary') })
    }
    for (const entry of alternates) {
      list.push({ key: entry.id, entryId: entry.id, imageId: entry.image_id, label: entry.label })
    }
    return list
  }, [character?.image_id, alternates, t])

  const needsOverflow = allAvatars.length > MAX_VISIBLE_COLLAPSED
  const visibleAvatars = expanded
    ? allAvatars
    : needsOverflow
      ? allAvatars.slice(0, MAX_VISIBLE_COLLAPSED - 1)
      : allAvatars
  const overflowCount = allAvatars.length - (MAX_VISIBLE_COLLAPSED - 1)

  const handleSelect = useCallback(
    async (avatarEntryId: string) => {
      if (!character) return
      setExpanded(false)
      try {
        await applyChatAppearance(chatId, character, { type: 'avatar', avatar_entry_id: avatarEntryId })
      } catch (err) {
        console.error('[AvatarSwitcher] Failed to save:', err)
        toast.error(err instanceof Error ? err.message : 'Failed to change avatar')
      }
    },
    [character, chatId]
  )

  if (allAvatars.length < 2) return <>{children}</>

  return (
    <div className={styles.wrapper}>
      {children}

      <motion.div
        className={styles.strip}
        initial={{ opacity: 0, y: -4 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.25, delay: 0.15 }}
      >
        <div className={styles.thumbGrid}>
          {visibleAvatars.map((avatar) => {
            const isActive = avatar.imageId === null
              ? !activeAvatarId
              : activeAvatarId === avatar.imageId
            const src = avatar.imageId
              ? imagesApi.smallUrl(avatar.imageId)
              : character?.image_id
                ? imagesApi.smallUrl(character.image_id)
                : ''

            return (
              <button
                key={avatar.key}
                type="button"
                className={clsx(styles.thumb, isActive && styles.thumbActive)}
                onClick={() => handleSelect(avatar.entryId)}
                aria-label={avatar.label}
                aria-pressed={isActive}
                title={avatar.label}
              >
                <LazyImage
                  src={src}
                  alt={avatar.label}
                  className={styles.thumbImg}
                  fallback={
                    <div className={styles.thumbFallback}>
                      {avatar.label[0]?.toUpperCase()}
                    </div>
                  }
                />
              </button>
            )
          })}

          {needsOverflow && !expanded && (
            <button
              type="button"
              className={styles.moreBtn}
              onClick={() => setExpanded(true)}
              aria-label={t('avatarSwitcher.showMoreAvatars', { count: overflowCount })}
              title={t('avatarSwitcher.moreCount', { count: overflowCount })}
            >
              +{overflowCount}
            </button>
          )}
        </div>

        {expanded && needsOverflow && (
          <button
            type="button"
            className={styles.collapseBtn}
            onClick={() => setExpanded(false)}
            aria-label={t('avatarSwitcher.showFewer')}
          >
            <ChevronUp size={11} />
          </button>
        )}
      </motion.div>
    </div>
  )
}

