/* ── Bubble mode card ── */
.card {
  /* User-tunable bubble fill alpha. --lcs-bubble-opacity (set on :root by
     ChatView) scales the theme's glass fill toward transparent; at the default
     1 these resolve to the unmodified glass colors, so the look is unchanged. */
  --lcs-bubble-bg: color-mix(in srgb, var(--lcs-glass-bg) calc(var(--lcs-bubble-opacity, 1) * 100%), transparent);
  --lcs-bubble-bg-hover: color-mix(in srgb, var(--lcs-glass-bg-hover, rgba(24, 22, 36, 0.65)) calc(var(--lcs-bubble-opacity, 1) * 100%), transparent);
  --long-message-fade-color: var(--lcs-bubble-bg);
  display: flex;
  flex-shrink: 0;
  gap: 10px;
  position: relative;
  overflow: hidden;
  border-radius: var(--lcs-radius, 14px);
  padding: 0;
  border: none;
  contain: layout style paint;
  background:
    linear-gradient(145deg, rgba(255, 255, 255, 0.022) 0%, rgba(255, 255, 255, 0.007) 40%, rgba(255, 255, 255, 0.013) 100%),
    var(--lcs-bubble-bg);
  box-shadow: 0 0 0 0.5px var(--lcs-glass-border);
  backdrop-filter: none;
  transition:
    background var(--lcs-transition-fast),
    border-color var(--lcs-transition-fast),
    box-shadow 0.15s ease;
}

/* The normal card is paint-contained and clipped to keep its glass treatment
   cheap. Authored HTML islands and inline-card spacing shells need visual
   overflow for box/text shadows and transformed corners, so relax both clips
   only for cards containing either one. */
.card:has([data-lumiverse-html-island]),
.card:has([data-lumiverse-inline-html-card]) {
  overflow: visible;
  contain: layout style;
}

/* Hide accent bars */
.card::before {
  display: none;
}

/* Bottom specular highlight */
.card::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 12%;
  right: 12%;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.03), transparent);
  pointer-events: none;
  z-index: 2;
}

/* Character tint */
.character {
  flex-direction: row;
  background:
    linear-gradient(145deg, var(--lcs-glass-char-tint, rgba(100, 120, 255, 0.03)) 0%, transparent 40%),
    linear-gradient(145deg, rgba(255, 255, 255, 0.022) 0%, rgba(255, 255, 255, 0.007) 40%, rgba(255, 255, 255, 0.013) 100%),
    var(--lcs-bubble-bg);
}

/* User tint */
.user {
  flex-direction: row-reverse;
  background:
    linear-gradient(225deg, var(--lcs-glass-user-tint, rgba(255, 180, 100, 0.03)) 0%, transparent 40%),
    linear-gradient(145deg, rgba(255, 255, 255, 0.022) 0%, rgba(255, 255, 255, 0.007) 40%, rgba(255, 255, 255, 0.013) 100%),
    var(--lcs-bubble-bg);
}

/* Left-aligned user override — mirrors character layout */
.userLeft.user {
  flex-direction: row;
}

/* Virtualized rows only mount near the viewport, so avoid scroll-time DOM
   attribute toggles here. Toggling a public attribute let custom CSS change
   row size during measurement, which could feed back into virtualization.

   Heavy drop shadows are gated behind data-glass so that disabling glass
   effects (Theme > "Disable glass effects") also drops the expensive GPU
   shadow stack. The non-glass fallback is a hairline border shadow only. */
.card {
  box-shadow: 0 0 0 0.5px var(--lcs-glass-border);
}

:global([data-glass]) .card {
  box-shadow:
    0 0 0 0.5px var(--lcs-glass-border),
    0 2px 6px rgba(0, 0, 0, 0.2),
    0 8px 24px rgba(0, 0, 0, 0.12);
}

/* Only apply backdrop-filter when glass is enabled AND there's a non-solid
   background (image/video/scene). Blurring a solid color is pure GPU waste. */
:global([data-glass][data-chat-bg]) .card {
  backdrop-filter: blur(var(--lcs-glass-strong-blur, 12px)) saturate(1.2) var(--lcs-liquid-filter, );
}

.card.streaming {
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  box-shadow: 0 0 0 0.5px var(--lcs-glass-border) !important;
}

.streaming .avatarBg,
.streaming .avatarBgScrim {
  display: none !important;
}

.card:hover {
  box-shadow:
    0 0 0 0.5px var(--lcs-glass-border-hover, rgba(255, 255, 255, 0.1)),
    0 1px 2px rgba(0, 0, 0, 0.28);
  background:
    linear-gradient(145deg, rgba(255, 255, 255, 0.028) 0%, rgba(255, 255, 255, 0.01) 40%, rgba(255, 255, 255, 0.018) 100%),
    var(--lcs-bubble-bg-hover);
}

:global([data-glass]) .card:hover {
  box-shadow:
    0 0 0 0.5px var(--lcs-glass-border-hover, rgba(255, 255, 255, 0.1)),
    0 1px 2px rgba(0, 0, 0, 0.28),
    0 4px 16px rgba(0, 0, 0, 0.22),
    0 20px 56px rgba(0, 0, 0, 0.12),
    inset 0 0.5px 0 rgba(255, 255, 255, 0.06);
}

/* Light themes use a light hover fill fallback, so derive the bubble hover var
   from it instead of the dark default. */
:global([data-theme-mode='light']) .card {
  --lcs-bubble-bg-hover: color-mix(in srgb, var(--lcs-glass-bg-hover, rgba(255, 255, 255, 0.75)) calc(var(--lcs-bubble-opacity, 1) * 100%), transparent);
}

:global([data-theme-mode='light']) .card:hover {
  box-shadow:
    0 0 0 0.5px rgba(0, 0, 0, 0.06),
    0 1px 2px rgba(0, 0, 0, 0.04);
  background:
    linear-gradient(145deg, rgba(255, 255, 255, 0.06) 0%, rgba(255, 255, 255, 0.02) 40%, rgba(255, 255, 255, 0.04) 100%),
    var(--lcs-bubble-bg-hover);
}

:global([data-glass][data-theme-mode='light']) .card:hover {
  box-shadow:
    0 0 0 0.5px rgba(0, 0, 0, 0.06),
    0 1px 2px rgba(0, 0, 0, 0.04),
    0 4px 12px rgba(0, 0, 0, 0.05),
    inset 0 0.5px 0 rgba(255, 255, 255, 0.5);
}

/* Hide dissolving avatar background when user opts out */
:global([data-no-bubble-avatar-bg]) .avatarBg {
  display: none;
}

/* Disable bubble hover effects when user opts out */
:global([data-no-bubble-hover]) .card:hover {
  box-shadow: 0 0 0 0.5px var(--lcs-glass-border);
  background:
    linear-gradient(145deg, rgba(255, 255, 255, 0.022) 0%, rgba(255, 255, 255, 0.007) 40%, rgba(255, 255, 255, 0.013) 100%),
    var(--lcs-bubble-bg);
}

:global([data-glass][data-no-bubble-hover]) .card:hover {
  box-shadow:
    0 0 0 0.5px var(--lcs-glass-border),
    0 1px 2px rgba(0, 0, 0, 0.2),
    0 4px 16px rgba(0, 0, 0, 0.14),
    0 12px 48px rgba(0, 0, 0, 0.08);
}

:global([data-no-bubble-hover]) .card:hover .avatarBgImg {
  opacity: 0.28;
}

/* Hidden draft message — dimmed, darkened, dashed border */
.hidden {
  opacity: 0.4;
  border: 1px dashed var(--lumiverse-border);
  filter: brightness(0.6) saturate(0.5);
  transition:
    opacity var(--lcs-transition),
    filter var(--lcs-transition),
    background var(--lcs-transition-fast),
    border-color var(--lcs-transition-fast),
    box-shadow 0.15s ease;
}

.hidden:hover {
  opacity: 0.65;
  filter: brightness(0.75) saturate(0.7);
}

.hiddenBadge {
  color: rgba(255, 160, 80, 0.9);
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  font-size: calc(9px * var(--lumiverse-font-scale, 1));
}

/* Selection mode */
.selectMode {
  cursor: pointer;
  user-select: none;
}

.selected {
  outline: 2px solid var(--lumiverse-primary);
  outline-offset: -1px;
  opacity: 1 !important;
  filter: none !important;
}

/* Transient navigation highlight — greeting switch, deep-link scroll-to, etc. */
.highlight {
  animation: bubbleHighlightPulse 1600ms ease-out forwards;
}

@keyframes bubbleHighlightPulse {
  0% {
    outline: 2px solid transparent;
    outline-offset: 2px;
    box-shadow: 0 0 0 0 var(--lumiverse-primary-040, rgba(130, 100, 255, 0.4));
  }
  15% {
    outline: 2px solid var(--lumiverse-primary);
    outline-offset: 2px;
    box-shadow: 0 0 0 6px var(--lumiverse-primary-020, rgba(130, 100, 255, 0.2));
  }
  100% {
    outline: 2px solid transparent;
    outline-offset: 2px;
    box-shadow: 0 0 0 0 transparent;
  }
}

/* Streaming state — GPU optimization */
.streaming {
  will-change: opacity, transform;
  backdrop-filter: none;
}

:global([data-style-mode='extension-relaxed']) .streaming {
  will-change: opacity;
}

:global([data-style-mode='extension-relaxed']) .card {
  contain: style;
}

/* Allow card authored extension-relaxed content to render at arbitrary z levels,
  as long as they stay below the sidebars. */
:global([data-style-mode='extension-relaxed']) .bubble,
:global([data-style-mode='extension-relaxed']) .content {
  z-index: auto;
}

/* ── Bubble inner content ── */
.bubble {
  flex: 1;
  min-width: 0;
  max-width: 100%;
  padding: 0;
  display: flex;
  flex-direction: column;
  /* Must sit above .avatarBg (z-index: 0) so the dissolving portrait
     doesn't overlay the header, reasoning block, or other bubble content. */
  position: relative;
  z-index: 1;
}

/* ── Header ── */
.header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 20px 24px 0;
  gap: 12px;
  margin-bottom: 0;
}

.user .header {
  flex-direction: row-reverse;
}

.userLeft.user .header {
  flex-direction: row;
}

.headerLeft {
  display: flex;
  align-items: center;
  gap: 14px;
  min-width: 0;
  max-width: calc(100% - 180px);
}

.user .headerLeft {
  flex-direction: row-reverse;
  max-width: calc(100% - 155px);
}

.userLeft.user .headerLeft {
  flex-direction: row;
}

/* ── Avatar — 44px rounded-square ── */
.avatar {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  overflow: hidden;
  flex-shrink: 0;
  background: var(--lumiverse-fill-subtle);
  box-shadow:
    0 0 0 0.5px rgba(255, 255, 255, 0.08),
    0 2px 8px rgba(0, 0, 0, 0.3);
  border: none;
  position: relative;
  z-index: 1;
}

.avatarFallback {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: calc(16px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-primary-muted);
  background: var(--lumiverse-primary-010);
}

/* ── Name ── */
.name,
.nameChar,
.nameUser {
  font-size: calc(20px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  letter-spacing: -0.015em;
  line-height: 1.2;
  color: #fff;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.5);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

:global([data-theme-mode='dark']) .nameChar {
  color: var(--char-name-dark, var(--lumiverse-primary-text));
}

:global([data-theme-mode='light']) .nameChar {
  color: var(--char-name-light, var(--lumiverse-primary-text));
}

/* ── Meta wrap ── */
.metaWrap {
  display: flex;
  flex-direction: column;
  gap: 0;
  min-width: 0;
}

.user .metaWrap {
  align-items: flex-end;
}

.userLeft.user .metaWrap {
  align-items: flex-start;
}

.user .metaPill {
  align-self: flex-end;
}

/* The right-aligned user badge should remain a single line. The left-aligned
   option retains the general wrapping behavior for backwards compatibility. */
.user:not(.userLeft) .metaPill {
  flex-shrink: 0;
  flex-wrap: nowrap;
  max-width: none;
  white-space: nowrap;
}

.userLeft.user .metaPill {
  align-self: flex-start;
}

/* Meta pill — monospace badge */
.metaPill {
  position: relative;
  display: inline-flex;
  align-items: center;
  align-self: flex-start;
  margin-top: 5px;
  padding: 4px 10px;
  border-radius: 16px;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-family: ui-monospace, 'SF Mono', SFMono-Regular, 'Cascadia Code', Menlo, Consolas, monospace;
  color: var(--lumiverse-text);
  letter-spacing: 0.02em;
  flex-wrap: wrap;
  gap: 0;
  max-width: 100%;
  background: var(--lumiverse-fill-deepest);
  border: 1px solid var(--lumiverse-border);
  line-height: 1;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.5);
}

.metaSegment {
  display: inline-flex;
  align-items: center;
  white-space: nowrap;
}

/* metaPill blur removed — sits inside the card which already has 40px blur */

.metaPillTooltip {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 6px 10px;
  border-radius: 10px;
  background: var(--lumiverse-fill-deepest);
  border: 1px solid var(--lumiverse-border);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.6);
  white-space: nowrap;
  z-index: 9999;
  pointer-events: none;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-family: ui-monospace, 'SF Mono', SFMono-Regular, 'Cascadia Code', Menlo, Consolas, monospace;
  line-height: 1.3;
}

.tooltipRow {
  display: flex;
  justify-content: space-between;
  gap: 12px;
}

.tooltipLabel {
  color: var(--lumiverse-text-muted);
}

.tooltipValue {
  color: var(--lumiverse-text);
  font-variant-numeric: tabular-nums;
}

.metaDot {
  margin: 0 6px;
  opacity: 0.35;
}

/* ── Dissolving avatar background ── */
.avatarBg {
  position: absolute;
  top: 0;
  left: 0;
  width: 50%;
  height: 100%;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
  mask-image:
    linear-gradient(to right, black 0%, black 25%, transparent 90%),
    linear-gradient(to bottom, black 0%, black 55%, transparent 100%),
    linear-gradient(to top, black 0%, black 85%, transparent 100%);
  mask-composite: intersect;
  -webkit-mask-image:
    linear-gradient(to right, black 0%, black 25%, transparent 90%),
    linear-gradient(to bottom, black 0%, black 55%, transparent 100%),
    linear-gradient(to top, black 0%, black 85%, transparent 100%);
  -webkit-mask-composite: source-in;
}

.user .avatarBg {
  left: auto;
  right: 0;
  mask-image:
    linear-gradient(to left, black 0%, black 25%, transparent 90%),
    linear-gradient(to bottom, black 0%, black 55%, transparent 100%),
    linear-gradient(to top, black 0%, black 85%, transparent 100%);
  -webkit-mask-image:
    linear-gradient(to left, black 0%, black 25%, transparent 90%),
    linear-gradient(to bottom, black 0%, black 55%, transparent 100%),
    linear-gradient(to top, black 0%, black 85%, transparent 100%);
  -webkit-mask-composite: source-in;
}

.userLeft.user .avatarBg {
  left: 0;
  right: auto;
  mask-image:
    linear-gradient(to right, black 0%, black 25%, transparent 90%),
    linear-gradient(to bottom, black 0%, black 55%, transparent 100%),
    linear-gradient(to top, black 0%, black 85%, transparent 100%);
  mask-composite: intersect;
  -webkit-mask-image:
    linear-gradient(to right, black 0%, black 25%, transparent 90%),
    linear-gradient(to bottom, black 0%, black 55%, transparent 100%),
    linear-gradient(to top, black 0%, black 85%, transparent 100%);
  -webkit-mask-composite: source-in;
}

.avatarBgImg {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: top center;
  opacity: 0.28;
  transition: opacity 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}

.card:hover .avatarBgImg {
  opacity: 0.36;
}

.avatarBgScrim {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.character .avatarBgScrim {
  background: linear-gradient(
    to right,
    var(--lumiverse-bg, #0a0a0c) 0%,
    color-mix(in srgb, var(--lumiverse-bg, #0a0a0c) 70%, transparent) 50%,
    color-mix(in srgb, var(--lumiverse-bg, #0a0a0c) 45%, transparent) 100%
  );
}

.user .avatarBgScrim {
  background: linear-gradient(
    to left,
    var(--lumiverse-bg, #0a0a0c) 0%,
    color-mix(in srgb, var(--lumiverse-bg, #0a0a0c) 70%, transparent) 50%,
    color-mix(in srgb, var(--lumiverse-bg, #0a0a0c) 45%, transparent) 100%
  );
}

.userLeft.user .avatarBgScrim {
  background: linear-gradient(
    to right,
    var(--lumiverse-bg, #0a0a0c) 0%,
    color-mix(in srgb, var(--lumiverse-bg, #0a0a0c) 70%, transparent) 50%,
    color-mix(in srgb, var(--lumiverse-bg, #0a0a0c) 45%, transparent) 100%
  );
}

/* ── Content ── */
.content {
  position: relative;
  z-index: 1;
  padding: 16px 24px 22px;
}

.user .content {
  text-align: right;
}

.userLeft.user .content {
  text-align: left;
}

/* ── Actions pill — hover reveal ── */
.actionsPill {
  position: absolute;
  top: 20px;
  right: 24px;
  z-index: 5;
  opacity: 0;
}

.card:hover .actionsPill {
  opacity: 1;
}

/* Touch devices: keep actions visible for deliberate tapping */
@media (hover: none) {
  .actionsPill {
    opacity: 0.5;
  }
}

.user .actionsPill {
  left: 24px;
  right: auto;
}

.userLeft.user .actionsPill {
  right: 24px;
  left: auto;
}

/* ── Mobile breakpoints ── */
@media (max-width: 768px) {
  .card {
    border-radius: var(--lcs-radius, 14px);
    padding-top: 34px;
  }

  .header {
    padding: 12px 12px 0;
    gap: 8px;
  }

  .headerLeft {
    align-items: flex-start;
    max-width: 100%;
  }

  /* Actions occupy their own strip above the card at this breakpoint, so the
     desktop reservation would only squeeze the right-side metadata. */
  .user:not(.userLeft) .headerLeft {
    max-width: 100%;
  }

  .content {
    padding: 10px 12px 14px;
  }

  .avatar {
    width: 40px;
    height: 40px;
    border-radius: 10px;
  }

  .name {
    font-size: calc(18px * var(--lumiverse-font-scale, 1));
  }

  .metaPill {
    margin-top: 10px;
  }

  .actionsPill {
    top: 8px;
    right: 12px;
  }

  .user .actionsPill {
    left: 12px;
  }

  .userLeft.user .actionsPill {
    right: 12px;
    left: auto;
  }
}

@media (max-width: 480px) {
  .card {
    padding-top: 30px;
  }

  .header {
    padding: 10px 10px 0;
    gap: 6px;
  }

  .headerLeft {
    gap: 8px;
  }

  .content {
    padding: 8px 10px 12px;
  }

  .avatar {
    width: 36px;
    height: 36px;
    border-radius: 8px;
  }

  .name {
    font-size: calc(16px * var(--lumiverse-font-scale, 1));
  }

  .metaDot {
    margin: 0 4px;
  }

  .metaPill {
    margin-top: 9px;
    padding: 3px 8px;
  }

  .actionsPill {
    top: 6px;
    right: 10px;
  }

  .user .actionsPill {
    left: 10px;
  }

  .userLeft.user .actionsPill {
    right: 10px;
    left: auto;
  }
}

@container duo-chat (max-width: 768px) {
  .card { padding-top: 34px; }
  .header { padding: 12px 12px 0; gap: 8px; }
  .headerLeft,
  .user:not(.userLeft) .headerLeft {
    align-items: flex-start;
    max-width: 100%;
  }
  .content { padding: 10px 12px 14px; }
  .actionsPill { top: 8px; right: 12px; }
  .user .actionsPill { left: 12px; }
  .userLeft.user .actionsPill { right: 12px; left: auto; }
}

@media (hover: none) and (pointer: coarse) {
  .card,
  .hidden {
    transition: none;
  }

  .card,
  .card:hover,
  :global([data-no-bubble-hover]) .card:hover {
    box-shadow:
      0 0 0 0.5px var(--lcs-glass-border),
      0 1px 4px rgba(0, 0, 0, 0.18),
      0 6px 14px rgba(0, 0, 0, 0.08);
  }

  :global([data-glass][data-chat-bg]) .card {
    backdrop-filter: none;
  }

  .avatarBg {
    display: none;
  }

  .streaming {
    will-change: auto;
  }
}

/* Keep glass/shadows and artwork opacity stable during scroll. Rebuilding
   backdrop layers at gesture boundaries can flash WebKit's text raster.
   Rows are already virtualized; only suppress hover transition work here. */
:global([data-scrolling]) .card {
  transition: none !important;
}

:global([data-scrolling]) .avatarBgImg {
  transition: none !important;
}

