/* ── Floating input area — glassmorphic pill ── */
.container {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 8px 14px 10px;
  position: absolute;
  bottom: 12px;
  left: 12px;
  right: 12px;
  z-index: 20;
  background:
    radial-gradient(120% 85% at 50% -30%, color-mix(in srgb, var(--lumiverse-primary-020) 45%, transparent), transparent 58%),
    linear-gradient(180deg, color-mix(in srgb, var(--lumiverse-text) 6%, transparent), transparent 70%),
    var(--lumiverse-bg-elevated, rgba(28, 24, 38, 0.95));
  border: 1px solid var(--lumiverse-border);
  border-radius: var(--lcs-radius, 14px);
  /* Visible so the type field cannot be clipped by the glass pill or by
     extension nodes that used to share the input row. Corners still clip via
     child radii; drop overlay is inset-absolute. */
  overflow: visible;
  /* Paint containment plus a stacked overlay can produce stale WebRender tiles
     under Firefox's fractional CSS zoom. Layout/style containment retains the
     useful isolation without forcing the composer into its own paint surface. */
  contain: layout style;
  box-shadow: 0 4px 16px var(--lumiverse-fill-heavy);
  transition:
    opacity 180ms ease,
    transform 180ms ease,
    background var(--lcs-transition, 220ms cubic-bezier(0.4, 0, 0.2, 1)),
    border-color var(--lcs-transition, 220ms cubic-bezier(0.4, 0, 0.2, 1)),
    box-shadow var(--lcs-transition, 220ms cubic-bezier(0.4, 0, 0.2, 1)),
    border-radius var(--lcs-transition, 220ms cubic-bezier(0.4, 0, 0.2, 1)),
    bottom var(--lcs-transition, 220ms cubic-bezier(0.4, 0, 0.2, 1)),
    padding-bottom var(--lcs-transition, 220ms cubic-bezier(0.4, 0, 0.2, 1));
}

:global(html[data-ios-pwa]) .container,
:global(html[data-tauri-mobile='ios']) .container {
  /* Standalone iOS shells have no bottom safe-area padding, so position from
     the screen edge. Background fills to the bottom; extra padding-bottom
     keeps interactive content above the home indicator. When keyboard is
     open, move up and drop the safe-area padding (keyboard covers it).
     Viewport insets are rendered pixels; divide once for the body zoom. */
  bottom: calc(var(--app-keyboard-inset-bottom, 0px) / var(--lumiverse-ui-scale, 1));
  padding-bottom: calc(10px + max(0px, env(safe-area-inset-bottom, 0px) - var(--app-keyboard-inset-bottom, 0px)) / var(--lumiverse-ui-scale, 1));
}

/* Flatten beside either the Duo hinge or its native side status area.
   Status-area alignment also applies to the standard drawer layout. */
:global([data-duo-drawer-side='right'] [data-duo-chat]) .container,
:global(html[data-tauri-mobile='ios'][data-ios-composer-flat-edges~='right']) .container {
  --composer-right-edge-radius: 0px;
  right: 0;
  border-top-right-radius: 0;
  border-bottom-right-radius: 0;
}

:global([data-duo-drawer-side='left'] [data-duo-chat]) .container,
:global(html[data-tauri-mobile='ios'][data-ios-composer-flat-edges~='left']) .container {
  --composer-left-edge-radius: 0px;
  left: 0;
  border-top-left-radius: 0;
  border-bottom-left-radius: 0;
}

/* A Duo pane can be phone-sized while the complete WebView is wider. */
:global([data-duo-chat]) .textarea,
:global([data-duo-chat]) .textareaMirror {
  font-size: max(16px, calc(14px * var(--lumiverse-font-scale, 1)));
  padding: 8px 14px;
}

:global(html[data-pwa]:not([data-ios-pwa]):not([data-tauri-mobile='ios'])) .container,
:global(html[data-tauri-mobile='android']) .container {
  /* Chromium/Android PWA: .app is now edge-to-edge (no bottom padding), so
     pin the bar's glass to the screen edge and lift only its content above
     the gesture nav bar. Unlike iOS, Android sets
     interactive-widget=resizes-content (see main.tsx), so the dvh-sized
     shell shrinks above the keyboard and the bar rides up on its own — no
     --app-keyboard-inset-bottom lift needed. env(safe-area-inset-bottom)
     collapses to 0 when the keyboard hides the nav bar. Native Android's
     host reserves IME space in the WebView bounds for the same behavior. */
  bottom: 0;
  padding-bottom: calc(10px + env(safe-area-inset-bottom, 0px));
}

:global([data-glass]) .container {
  background:
    radial-gradient(120% 85% at 50% -30%, color-mix(in srgb, var(--lumiverse-primary-020) 45%, transparent), transparent 58%),
    linear-gradient(180deg, color-mix(in srgb, var(--lumiverse-text) 6%, transparent), transparent 70%),
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--lcs-glass-bg) 78%, var(--lumiverse-bg-elevated) 22%),
      color-mix(in srgb, var(--lcs-glass-bg) 70%, var(--lumiverse-bg) 30%)
    );
  border-color: var(--lcs-glass-border);
  backdrop-filter: blur(var(--lcs-glass-blur)) var(--lcs-liquid-filter, );
  box-shadow:
    0 14px 34px var(--lumiverse-fill-heavy),
    var(--lumiverse-highlight-inset),
    inset 0 -1px 0 var(--lcs-glass-border);
}

.container > :not([data-composer-formatting]) {
  position: relative;
}

/* ── Drag-and-drop overlay ── */
.dropOverlay {
  position: absolute;
  inset: 0;
  z-index: 5;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  pointer-events: none;
  border-radius: inherit;
  border: 1.5px dashed var(--lumiverse-primary, rgba(140, 120, 240, 0.9));
  background: color-mix(in srgb, var(--lumiverse-primary-020, rgba(140, 120, 240, 0.2)) 60%, var(--lumiverse-bg, rgba(28, 24, 38, 0.95)) 40%);
  color: var(--lumiverse-text, rgba(255, 255, 255, 0.92));
  font-size: 13px;
  font-weight: 600;
  backdrop-filter: blur(2px) var(--lcs-liquid-filter, );
}

/* ── Action bar — regenerate / continue / stop ── */
.actionBar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 2px;
  padding: 0 2px;
  min-width: 0;
}

.composerReorderUnit {
  display: contents;
}

.composerReorderUnit[data-toolbar-item-drag-handle] .actionBtn,
.composerReorderUnit .actionBtn {
  cursor: grab;
}

.composerReorderUnit .actionBtn:active:not([data-dragging]) {
  transform: scale(0.97);
}

.composerReorderUnit[data-dragging] .actionBtn,
.composerReorderUnit[data-dragging] .actionDivider {
  opacity: 1;
  cursor: grabbing;
  transform: scale(1.05) translateY(-2px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  outline: 2px solid var(--lumiverse-primary);
  z-index: 100;
  position: relative;
}

.actionBar button[aria-label='Customize composer'],
.composerCustomizeGear {
  cursor: pointer !important;
}

.extensionToolbar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 2px;
  min-width: 0;
}

.extensionToolbar:empty {
  display: none;
}

.actionDivider {
  width: 1px;
  height: 14px;
  background: var(--lumiverse-border, rgba(255, 255, 255, 0.08));
  flex-shrink: 0;
  margin: 0 2px;
}

.actionBtn {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 30px;
  height: 26px;
  border: none;
  border-radius: var(--lcs-radius-xs, 6px);
  background: transparent;
  color: var(--lumiverse-text-dim, rgba(230, 230, 240, 0.4));
  cursor: pointer;
  transition:
    color var(--lcs-transition-fast, 120ms cubic-bezier(0.4, 0, 0.2, 1)),
    background var(--lcs-transition-fast, 120ms cubic-bezier(0.4, 0, 0.2, 1));
  padding: 0;
}

.actionBtn:hover {
  color: var(--lumiverse-text, rgba(230, 230, 240, 0.92));
  background: var(--lumiverse-fill, rgba(255, 255, 255, 0.06));
}

.actionBtnActive {
  color: var(--lumiverse-text, rgba(230, 230, 240, 0.92));
  background: var(--lumiverse-fill, rgba(255, 255, 255, 0.08));
}

/* Persistent state indicator for buttons whose feature is "armed" — e.g.
 * an alternate-field selection is bound to the current chat. Distinct from
 * .actionBtnActive (which only highlights while the popover is open) so the
 * user can see at a glance that the chat has an active override even when
 * no popover is open. */
.actionBtnHasSelection {
  color: var(--lumiverse-primary, rgba(140, 130, 255, 0.95));
  background: color-mix(in srgb, var(--lumiverse-primary, #8c82ff) 12%, transparent);
}

.actionBtnHasSelection:hover {
  background: color-mix(in srgb, var(--lumiverse-primary, #8c82ff) 18%, transparent);
}

.badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 14px;
  height: 14px;
  border-radius: 999px;
  padding: 0 4px;
  font-size: calc(9px * var(--lumiverse-font-scale, 1));
  background: var(--lumiverse-primary, rgba(140, 130, 255, 0.9));
  color: var(--lumiverse-primary-contrast, #fff);
  margin-left: 2px;
}

.popoverSlot {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 250ms cubic-bezier(0.4, 0, 0.2, 1);
}

.popoverSlotOpen {
  grid-template-rows: 1fr;
}

.popoverSlotInner {
  min-height: 0;
  overflow: hidden;
}

.popover {
  border: 1px solid var(--lumiverse-border, rgba(255, 255, 255, 0.08));
  border-radius: 10px;
  background: var(--lumiverse-bg-elevated, rgba(35, 30, 48, 0.9));
  background: color-mix(in srgb, var(--lumiverse-bg-elevated) 88%, var(--lcs-glass-bg) 12%);
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px;
  max-height: min(240px, calc(35vh / var(--lumiverse-ui-scale, 1)));
  overflow-y: auto;
  animation: popover-fade 220ms cubic-bezier(0.4, 0, 0.2, 1) both;
  will-change: opacity, transform;
}

.popoverClosing {
  animation: popover-fade-out 200ms cubic-bezier(0.4, 0, 0.2, 1) both;
}

@keyframes popover-fade {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes popover-fade-out {
  from {
    opacity: 1;
    transform: translateY(0);
  }

  to {
    opacity: 0;
    transform: translateY(-4px);
  }
}

.popDivider {
  height: 1px;
  background: var(--lumiverse-border, rgba(147, 112, 219, 0.12));
  margin: 4px 0;
}

.popEmpty {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim, rgba(230, 230, 240, 0.4));
  padding: 6px;
}

.popRowBtn {
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: var(--lumiverse-text, rgba(230, 230, 240, 0.92));
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 6px 8px;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  text-align: left;
  cursor: pointer;
}

.popRowBtn:disabled {
  cursor: default;
  opacity: 0.55;
}

.personaMain {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.personaSearch {
  position: sticky;
  top: -8px;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 7px 8px;
  margin: -2px -2px 2px;
  border: 1px solid var(--lumiverse-border, rgba(255, 255, 255, 0.08));
  border-radius: 8px;
  background: var(--lumiverse-bg-elevated, rgba(35, 30, 48, 0.98));
  color: var(--lumiverse-text-dim);
}

.personaSearch input {
  flex: 1;
  min-width: 0;
  border: none;
  outline: none;
  background: transparent;
  color: var(--lumiverse-text);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
}

.personaSearch input::-webkit-search-cancel-button {
  display: none;
}

.personaSearch button {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2px;
  border: none;
  background: transparent;
  color: var(--lumiverse-text-dim);
  cursor: pointer;
}

.personaGroup {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.personaGroupHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 5px 7px 2px;
  color: var(--lumiverse-text-dim);
  font-size: calc(9px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.personaAvatar {
  width: 22px;
  height: 22px;
  border-radius: 999px;
  overflow: hidden;
  border: 1px solid var(--lumiverse-border, rgba(255, 255, 255, 0.12));
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.05));
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.personaAvatarImg {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.personaFallback {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  line-height: 1;
  color: var(--lumiverse-text-dim, rgba(230, 230, 240, 0.65));
  font-weight: 600;
}

.personaNameGroup {
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
}

.personaTitle {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim, rgba(230, 230, 240, 0.45));
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  line-height: 1.3;
}

@media (prefers-reduced-motion: reduce) {
  .container {
    transition: none;
  }

  .popoverSlot {
    transition: none;
  }

  .popover {
    animation: none;
  }
}

.popRowBtn:hover:not(:disabled) {
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.04));
  border-color: var(--lumiverse-border, rgba(255, 255, 255, 0.08));
}

.popRowBtnActive {
  border-color: var(--lumiverse-primary, rgba(140, 130, 255, 0.9));
}

.popMeta {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim, rgba(230, 230, 240, 0.4));
}

.popState {
  flex-shrink: 0;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text-dim, rgba(230, 230, 240, 0.4));
}

.popStateActive {
  color: var(--lumiverse-primary, rgba(140, 130, 255, 0.9));
}

.popLink {
  border: none;
  background: transparent;
  color: var(--lumiverse-primary, rgba(140, 130, 255, 0.9));
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  padding: 4px 6px;
  text-align: left;
  cursor: pointer;
}

.quickSet {
  border-top: 1px solid var(--lumiverse-border, rgba(255, 255, 255, 0.08));
  padding-top: 6px;
}

.quickSetName {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim, rgba(230, 230, 240, 0.45));
  padding: 2px 6px;
}

.addonPopoverHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim, rgba(230, 230, 240, 0.45));
  padding: 2px 6px;
}

.addonCreateToggle {
  width: 22px;
  height: 22px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--lumiverse-border, rgba(255, 255, 255, 0.08));
  border-radius: 6px;
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.04));
  color: var(--lumiverse-primary, rgba(140, 130, 255, 0.9));
  cursor: pointer;
}

.addonCreateForm {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 6px;
  border: 1px solid var(--lumiverse-border, rgba(255, 255, 255, 0.08));
  border-radius: 8px;
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.04));
}

.addonCreateInput,
.addonCreateTextarea {
  width: 100%;
  border: 1px solid var(--lumiverse-border, rgba(255, 255, 255, 0.08));
  border-radius: 7px;
  background: var(--lumiverse-bg, rgba(20, 18, 28, 0.7));
  color: var(--lumiverse-text, rgba(230, 230, 240, 0.92));
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  padding: 6px 8px;
  outline: none;
}

.addonCreateTextarea {
  resize: vertical;
  min-height: 58px;
}

.stopBtn {
  color: var(--lumiverse-danger, #ef4444);
}

.stopBtn:hover {
  color: #fff;
  background: var(--lumiverse-danger, #ef4444);
}

/* ── Attachment preview strip ── */
.attachmentStrip {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  padding: 0 2px;
}

.attachmentPreview {
  position: relative;
  display: inline-flex;
  align-items: center;
  border: 1px solid var(--lumiverse-border, rgba(255, 255, 255, 0.1));
  border-radius: var(--lcs-radius-xs, 6px);
  overflow: hidden;
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.04));
  max-height: 56px;
}

.attachmentThumb {
  display: block;
  width: 56px;
  height: 56px;
  object-fit: cover;
}

.attachmentLabel {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim, rgba(230, 230, 240, 0.65));
  padding: 4px 22px 4px 8px;
  max-width: 120px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.attachmentRemove {
  position: absolute;
  top: 2px;
  right: 2px;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  border: none;
  border-radius: 999px;
  background: var(--lumiverse-fill-deepest);
  color: #fff;
  cursor: pointer;
  padding: 0;
  transition: background var(--lcs-transition-fast, 120ms ease);
}

.attachmentRemove:hover {
  background: var(--lumiverse-danger, #ef4444);
}

/* ── Attach button ── */
.attachBtn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border: none;
  border-radius: var(--lcs-radius, 14px);
  background: transparent;
  color: var(--lumiverse-text-dim, rgba(230, 230, 240, 0.4));
  cursor: pointer;
  flex-shrink: 0;
  padding: 0;
  transition:
    color var(--lcs-transition-fast, 120ms ease),
    background var(--lcs-transition-fast, 120ms ease);
}

.attachBtn:hover {
  color: var(--lumiverse-text, rgba(230, 230, 240, 0.92));
  background: var(--lumiverse-fill, rgba(255, 255, 255, 0.06));
}

.attachBtn:disabled {
  opacity: 0.4;
  cursor: default;
}

.sttBtnActive {
  color: var(--lumiverse-primary-contrast, #fff);
  background: color-mix(in srgb, var(--lumiverse-danger, #ef4444) 82%, transparent);
}

.sttBtnActive:hover {
  color: var(--lumiverse-primary-contrast, #fff);
  background: color-mix(in srgb, var(--lumiverse-danger-hover, #dc2626) 88%, transparent);
}

.sttSpinner {
  animation: stt-spin 1s linear infinite;
}

@keyframes stt-spin {
  from {
    transform: rotate(0deg);
  }

  to {
    transform: rotate(360deg);
  }
}

/* ── Input row — textarea + send button ── */
.inputRow {
  display: flex;
  align-items: flex-end;
  gap: 8px;
  min-width: 0;
}

.inputToolsSlot {
  display: flex;
  align-items: flex-end;
  flex: 0 1 auto;
  min-width: 0;
  max-width: 28%;
  overflow: hidden;
}

.inputToolsSlot:empty {
  display: none;
}

.inputWrapper {
  flex: 1 1 auto;
  display: flex;
  align-items: flex-end;
  /* Large fonts and UI zoom can leave less than 8rem beside the buttons.
     Let the draft rewrap so the send button stays inside narrow panes. */
  min-width: 0;
  min-height: 40px;
  max-height: 180px;
  border-radius: var(--lcs-radius, 14px);
  border: none;
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.04));
  box-shadow: inset 0 0 0 1px var(--lumiverse-border, rgba(255, 255, 255, 0.08));
  transition:
    background var(--lcs-transition, 220ms cubic-bezier(0.4, 0, 0.2, 1)),
    box-shadow var(--lcs-transition, 220ms cubic-bezier(0.4, 0, 0.2, 1));
  overflow: hidden;
  position: relative;
}

.sttRecordingPanel {
  width: 100%;
  min-height: 72px;
  display: grid;
  grid-template-columns: minmax(96px, 0.72fr) minmax(120px, 1.3fr) minmax(112px, 0.72fr);
  align-items: center;
  gap: 14px;
  min-width: 0;
  padding: 10px 14px;
  border: 1px solid color-mix(in srgb, var(--lumiverse-danger, #ef4444) 24%, transparent);
  border-radius: var(--lcs-radius, 14px);
  background:
    radial-gradient(circle at var(--stt-glow-x, 14%) 50%, color-mix(in srgb, var(--lumiverse-danger, #ef4444) 30%, transparent), transparent 46%),
    linear-gradient(135deg, color-mix(in srgb, var(--lumiverse-danger, #ef4444) 16%, var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.04))), color-mix(in srgb, var(--lumiverse-primary, #8c82ff) 9%, var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.04))));
  color: var(--lumiverse-text, rgba(230, 230, 240, 0.92));
  box-shadow:
    inset 0 1px 0 color-mix(in srgb, white 10%, transparent),
    0 0 var(--stt-glow-size, 11px) color-mix(in srgb, var(--lumiverse-danger, #ef4444) 16%, transparent);
  cursor: pointer;
  transition:
    border-color 120ms ease,
    box-shadow 120ms ease,
    transform 120ms ease,
    background 120ms ease;
}

.sttRecordingPanel:hover:not(:disabled) {
  border-color: color-mix(in srgb, var(--lumiverse-danger, #ef4444) 34%, transparent);
  transform: translateY(-1px);
}

.sttRecordingPanel:disabled {
  cursor: progress;
}

.sttIndicatorProcessing {
  opacity: 0.82;
}

.sttRecordingStatus,
.sttRecordingHint {
  display: inline-flex;
  align-items: center;
  min-width: 0;
  gap: 7px;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  line-height: 1.2;
  font-weight: 650;
  white-space: nowrap;
}

.sttRecordingStatus {
  justify-content: flex-start;
}

.sttRecordingHint {
  justify-content: flex-end;
  color: var(--lumiverse-text-dim, rgba(230, 230, 240, 0.55));
  font-weight: 600;
}

.sttRecordingWave {
  display: inline-flex;
  align-items: flex-end;
  justify-content: center;
  gap: 3px;
  width: 100%;
  height: 44px;
  min-width: 0;
}

.sttIndicatorBar {
  flex: 1 1 0;
  max-width: 7px;
  min-width: 3px;
  height: var(--stt-bar-height, 5px);
  min-height: 3px;
  border-radius: 999px;
  background: linear-gradient(
    180deg,
    color-mix(in srgb, white 34%, var(--lumiverse-danger, #ef4444) 66%),
    color-mix(in srgb, var(--lumiverse-danger, #ef4444) 74%, var(--lumiverse-primary, #8c82ff) 26%)
  );
  box-shadow: 0 0 8px color-mix(in srgb, var(--lumiverse-danger, #ef4444) 30%, transparent);
  transform-origin: center bottom;
  animation: stt-wave 1100ms ease-in-out infinite;
  animation-delay: var(--stt-bar-delay, 0ms);
  transition: height 80ms linear, opacity 80ms linear, filter 80ms linear;
}

.sttIndicatorReactive .sttIndicatorBar {
  animation: none;
  opacity: var(--stt-bar-opacity, 0.55);
  filter: saturate(var(--stt-bar-saturate, 1));
}

@keyframes stt-wave {
  0%, 100% {
    transform: scaleY(0.55);
    opacity: 0.48;
  }

  50% {
    transform: scaleY(1.05);
    opacity: 1;
  }
}

/* Mirror layer that renders @mention pills behind the (transparent) textarea.
   Font / padding / line-height / wrap rules MUST stay locked to `.textarea`
   so wrapped glyphs land on the same x/y as the caret. Every text-metric
   property (kerning, ligatures, letter-spacing, tab-size, etc.) is pinned
   explicitly — UA defaults for <textarea> vs <div> differ on Android, and
   any divergence compounds across a line into visible caret drift. */
.textareaMirror {
  position: absolute;
  inset: 0;
  box-sizing: border-box;
  font-family: inherit;
  font-size: calc(14px * var(--lumiverse-font-scale, 1));
  font-weight: inherit;
  font-style: normal;
  font-variant-ligatures: none;
  font-variant-numeric: normal;
  font-feature-settings: normal;
  font-kerning: none;
  font-synthesis: none;
  line-height: 1.5;
  letter-spacing: normal;
  word-spacing: normal;
  text-indent: 0;
  text-rendering: auto;
  text-transform: none;
  tab-size: 4;
  -moz-tab-size: 4;
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
  padding: 9px 14px;
  color: transparent;
  -webkit-text-fill-color: transparent;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  word-break: normal;
  /* Reserve the same scrollbar gutter the textarea reserves so both wrap at
     identical content widths. scrollbar-width keeps the gutter deterministic
     across Firefox/Chromium; -webkit-scrollbar rules below hide the visible
     thumb so only the textarea's scrollbar is visible on Android/iOS. */
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-gutter: stable;
  scrollbar-width: thin;
  pointer-events: none;
  user-select: none;
  z-index: 0;
}

.textareaMirror::-webkit-scrollbar {
  width: 3px;
}

.textareaMirror::-webkit-scrollbar-thumb,
.textareaMirror::-webkit-scrollbar-track {
  background: transparent;
}

/* Pills must be layout-neutral — no padding, margin, or font-weight change
   (all of which would shift glyph advances and drift the caret). The extra
   breathing room around the text comes from `box-shadow`, which paints
   outside the border box without affecting layout. */
.mentionPill {
  background: color-mix(in srgb, var(--lumiverse-primary, rgba(140, 130, 255, 0.9)) 22%, transparent);
  border-radius: 4px;
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--lumiverse-primary, rgba(140, 130, 255, 0.9)) 22%, transparent);
}

.mentionPillMuted {
  background: color-mix(in srgb, var(--lumiverse-text-dim, rgba(230, 230, 240, 0.6)) 16%, transparent);
  border-radius: 4px;
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--lumiverse-text-dim, rgba(230, 230, 240, 0.6)) 16%, transparent);
}

.documentPill {
  background: color-mix(in srgb, var(--lumiverse-info, #42a5f5) 18%, transparent);
  border-radius: 4px;
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--lumiverse-info, #42a5f5) 18%, transparent);
}

.inputWrapper:focus-within {
  background: var(--lumiverse-fill, rgba(255, 255, 255, 0.06));
  box-shadow: inset 0 0 0 1px var(--lcs-glass-border-hover, var(--lumiverse-border-hover)),
    0 0 0 2px color-mix(in srgb, var(--lumiverse-border-hover) 55%, transparent);
}

.textarea {
  flex: 1;
  min-width: 0;
  resize: none;
  border: none;
  outline: none;
  background: transparent;
  color: var(--lumiverse-text, rgba(230, 230, 240, 0.92));
  -webkit-text-fill-color: var(--lumiverse-text, rgba(230, 230, 240, 0.92));
  caret-color: var(--lumiverse-text, rgba(230, 230, 240, 0.92));
  box-sizing: border-box;
  font-family: inherit;
  font-size: calc(14px * var(--lumiverse-font-scale, 1));
  font-weight: inherit;
  font-style: normal;
  font-variant-ligatures: none;
  font-variant-numeric: normal;
  font-feature-settings: normal;
  font-kerning: none;
  font-synthesis: none;
  line-height: 1.5;
  letter-spacing: normal;
  word-spacing: normal;
  text-indent: 0;
  text-rendering: auto;
  text-transform: none;
  tab-size: 4;
  -moz-tab-size: 4;
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
  padding: 9px 14px;
  min-height: 40px;
  max-height: 180px;
  overflow-y: auto;
  overflow-x: hidden;
  /* Match the mirror's gutter so wrap widths stay identical once the
     textarea grows past its max-height and a scrollbar appears. */
  scrollbar-gutter: stable;
  scrollbar-width: thin;
  position: relative;
  z-index: 1;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  word-break: normal;
  user-select: text;
  -webkit-user-select: text;
  -webkit-touch-callout: default;
}

.textarea::placeholder {
  color: var(--lumiverse-text-dim, rgba(230, 230, 240, 0.3));
  -webkit-text-fill-color: var(--lumiverse-text-dim, rgba(230, 230, 240, 0.3));
}

.textarea::selection {
  background: color-mix(in srgb, var(--lumiverse-primary, rgba(140, 130, 255, 0.9)) 35%, transparent);
}

.textarea:disabled {
  opacity: 0.5;
}

.textarea::-webkit-scrollbar {
  width: 3px;
}

.textarea::-webkit-scrollbar-thumb {
  background: var(--lcs-scrollbar-thumb, rgba(255, 255, 255, 0.15));
  border-radius: 4px;
}

/* ── Send / Stop button ── */
.sendBtnShell {
  position: relative;
  display: flex;
  align-self: stretch;
  width: 40px;
  min-height: 40px;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.sendBtn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border: none;
  border-radius: var(--lcs-radius, 14px);
  background: var(--lumiverse-primary, rgba(140, 130, 255, 0.9));
  color: var(--lumiverse-primary-contrast, #fff);
  cursor: pointer;
  flex-shrink: 0;
  position: relative;
  overflow: hidden;
  isolation: isolate;
  transition:
    background var(--lcs-transition-fast, 120ms cubic-bezier(0.4, 0, 0.2, 1)),
    transform var(--lcs-transition-fast, 120ms cubic-bezier(0.4, 0, 0.2, 1)),
    opacity var(--lcs-transition-fast, 120ms cubic-bezier(0.4, 0, 0.2, 1)),
    box-shadow var(--lcs-transition-fast, 120ms cubic-bezier(0.4, 0, 0.2, 1));
  font-size: calc(16px * var(--lumiverse-font-scale, 1));
  padding: 0;
  /* The send button owns a touch for the duration of a hold-to-queue gesture.
     Allowing panning here lets Android cancel the touch before its release. */
  touch-action: none;
  -webkit-tap-highlight-color: transparent;
  -webkit-touch-callout: none;
}

.sendBtn:hover {
  background: var(--lumiverse-primary-hover, rgba(160, 150, 255, 0.95));
  transform: scale(1.04);
}

.sendBtn:active {
  transform: scale(0.96);
}

.sendBtn:disabled {
  opacity: 0.35;
  cursor: default;
  transform: none;
}

.sendBtnIcon {
  position: relative;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.sendBtnSpinner {
  animation: stt-spin 0.9s linear infinite;
}

.sendBtnHoldTracking {
  background: color-mix(in srgb, var(--lumiverse-primary, rgba(140, 130, 255, 0.9)) 82%, var(--lumiverse-info, #42a5f5) 18%);
}

.sendBtnHoldTracking::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    color-mix(in srgb, white 24%, transparent),
    color-mix(in srgb, var(--lumiverse-info, #42a5f5) 68%, transparent)
  );
  transform: scaleX(0);
  transform-origin: left center;
  animation: send-btn-hold-fill var(--send-btn-hold-duration, 900ms) linear forwards;
  opacity: 0.28;
  z-index: 0;
}

.sendBtnHoldReady {
  background: color-mix(in srgb, var(--lumiverse-success, #22c55e) 78%, var(--lumiverse-primary, rgba(140, 130, 255, 0.9)) 22%);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--lumiverse-success, #22c55e) 38%, transparent);
  animation: send-btn-ready-pulse 1050ms ease-in-out infinite;
}

.sendBtnQueueing {
  background: color-mix(in srgb, var(--lumiverse-success, #22c55e) 84%, black 16%);
}

.sendBtnStop {
  background: var(--lumiverse-danger, #ef4444);
}

.sendBtnStop:hover {
  background: var(--lumiverse-danger-hover, #dc2626);
}

.mobileQueueHint {
  position: absolute;
  right: 0;
  bottom: calc(100% + 8px);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: max-content;
  max-width: min(210px, calc(100vw - 40px));
  padding: 6px 10px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--lumiverse-fill, rgba(15, 23, 42, 0.94)) 90%, transparent);
  border: 1px solid color-mix(in srgb, var(--lumiverse-border, rgba(255, 255, 255, 0.12)) 82%, transparent);
  color: var(--lumiverse-text, rgba(230, 230, 240, 0.92));
  box-shadow:
    0 10px 24px rgba(0, 0, 0, 0.28),
    inset 0 1px 0 color-mix(in srgb, white 10%, transparent);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  letter-spacing: 0.01em;
  text-align: center;
  line-height: 1.15;
  white-space: normal;
  pointer-events: none;
  z-index: 2;
  animation: mobile-queue-hint-enter 160ms ease;
}

.mobileQueueHintHolding {
  border-color: color-mix(in srgb, var(--lumiverse-primary, rgba(140, 130, 255, 0.9)) 42%, transparent);
}

.mobileQueueHintReady {
  border-color: color-mix(in srgb, var(--lumiverse-success, #22c55e) 55%, transparent);
  color: color-mix(in srgb, var(--lumiverse-success, #22c55e) 88%, white 12%);
}

.mobileQueueHintQueueing {
  border-color: color-mix(in srgb, var(--lumiverse-success, #22c55e) 46%, transparent);
  color: color-mix(in srgb, var(--lumiverse-success, #22c55e) 82%, white 18%);
}

@keyframes send-btn-hold-fill {
  from {
    transform: scaleX(0);
  }

  to {
    transform: scaleX(1);
  }
}

@keyframes send-btn-ready-pulse {
  0%, 100% {
    transform: scale(1);
  }

  50% {
    transform: scale(1.04);
  }
}

@keyframes mobile-queue-hint-enter {
  from {
    opacity: 0;
    transform: translateY(6px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* ── Extras popover ── */
.extrasSection {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.extrasDivider {
  height: 1px;
  background: var(--lumiverse-border, rgba(255, 255, 255, 0.08));
  margin: 4px 0;
}

.extrasExtHeader {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: rgb(45, 212, 191);
  padding: 2px 6px;
  padding-bottom: 3px;
  border-bottom: 1px solid rgba(45, 212, 191, 0.3);
  border-bottom: 1px solid color-mix(in srgb, rgb(45, 212, 191) 30%, var(--lumiverse-border));
}

.extrasExtBadge {
  font-size: calc(9px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  padding: 1px 5px;
  border-radius: 4px;
  background: rgba(45, 212, 191, 0.14);
  background: color-mix(in srgb, rgb(45, 212, 191) 14%, transparent);
  color: rgb(45, 212, 191);
  border: 1px solid rgba(45, 212, 191, 0.25);
  border: 1px solid color-mix(in srgb, rgb(45, 212, 191) 25%, transparent);
}

/* ── Responsive ── */
@media (min-width: 601px) {
  .popover {
    max-height: 320px;
  }
}

@media (pointer: coarse) {
  /* iOS/Android selection handles can be clipped when the focused textarea is
     nested inside rounded wrappers that hide overflow or use paint
     containment. Let the native selection UI escape while editing. */
  .container:focus-within {
    overflow: visible;
    contain: layout style;
  }

  .inputWrapper:focus-within {
    overflow: visible;
  }
}

@media (max-width: 600px) {
  .container {
    bottom: 8px;
    left: 8px;
    right: 8px;
    padding: 6px 10px 8px;
  }

  .actionBar {
    gap: 1px;
    padding: 0;
    max-width: 100%;
    min-width: 0;
    flex-wrap: nowrap;
    overflow-x: auto;
    overflow-y: hidden;
    scrollbar-width: none;
    -webkit-overflow-scrolling: touch;
  }

  .actionBar::-webkit-scrollbar {
    display: none;
  }

  .actionBtn {
    width: 28px;
    flex: 0 0 28px;
  }

  .actionBar :global([data-spindle-mount='chat_actions'] > *) {
    flex-shrink: 0;
  }

  :global(html[data-ios-pwa]) .container,
  :global(html[data-tauri-mobile='ios']) .container {
    bottom: calc(var(--app-keyboard-inset-bottom, 0px) / var(--lumiverse-ui-scale, 1));
    padding-bottom: calc(8px + max(0px, env(safe-area-inset-bottom, 0px) - var(--app-keyboard-inset-bottom, 0px)) / var(--lumiverse-ui-scale, 1));
  }

  :global(html[data-pwa]:not([data-ios-pwa]):not([data-tauri-mobile='ios'])) .container,
  :global(html[data-tauri-mobile='android']) .container {
    bottom: 0;
    padding-bottom: calc(8px + env(safe-area-inset-bottom, 0px));
  }

  /* Prevent iOS Safari auto-zoom on input focus (triggers when font-size < 16px).
     Compensate the taller line-height (16px × 1.5 = 24px) with reduced vertical
     padding so the textarea stays 40px — matching the buttons. */
  .textarea,
  .textareaMirror {
    font-size: max(16px, calc(14px * var(--lumiverse-font-scale, 1)));
    padding: 8px 14px;
  }

  .inputRow {
    gap: 4px;
  }

  .sttRecordingPanel {
    grid-template-columns: 1fr;
    gap: 8px;
    min-height: 86px;
    padding: 10px 12px;
  }

  .sttRecordingStatus,
  .sttRecordingHint {
    justify-content: center;
  }

  .sttRecordingHint {
    font-size: calc(11px * var(--lumiverse-font-scale, 1));
  }

  .sttRecordingWave {
    height: 38px;
  }
}

/* ── Composer action-bar customizer (InputAreaCustomizeModal) ── */
.customizeModal {
  width: min(560px, calc(100vw - 32px));
  padding: 0;
  overflow: hidden;
  box-shadow:
    var(--lumiverse-shadow-xl),
    0 0 40px var(--lumiverse-primary-020);
}

.customizeHeader {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 22px 24px 16px;
  border-bottom: 1px solid var(--lumiverse-border);
}

.customizeTitle {
  margin: 0;
  color: var(--lumiverse-text);
  font-size: calc(16px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  letter-spacing: -0.01em;
}

.customizeSubtitle {
  margin: 6px 0 0;
  color: var(--lumiverse-text-dim);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  line-height: 1.45;
}

.customizeBody {
  display: flex;
  flex-direction: column;
  gap: 12px;
  max-height: min(64vh, 640px);
  padding: 16px 24px 20px;
  overflow-y: auto;
}

.customizeSectionHeader {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.customizeSectionTitle {
  margin: 0;
  color: var(--lumiverse-text-secondary, var(--lumiverse-text-muted));
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.customizeSectionDescription {
  margin: 0;
  color: var(--lumiverse-text-dim);
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
  line-height: 1.45;
}

.customizeSearchField {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-top: 3px;
  padding: 7px 9px;
  border: 1px solid var(--lumiverse-border);
  border-radius: var(--lumiverse-radius);
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text-dim);
}

.customizeSearchField:focus-within {
  border-color: var(--lumiverse-primary);
  box-shadow: 0 0 0 1px var(--lumiverse-primary);
}

.customizeSearchField svg {
  flex-shrink: 0;
}

.customizeSearchField input {
  width: 100%;
  min-width: 0;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--lumiverse-text);
  font: inherit;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
}

.customizeSearchField input::placeholder {
  color: var(--lumiverse-text-dim);
}

.customizeList {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.customizeEmptyState {
  margin: 0;
  padding: 16px 12px;
  border: 1px dashed var(--lumiverse-border);
  border-radius: var(--lumiverse-radius-lg);
  color: var(--lumiverse-text-dim);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  text-align: center;
}

.customizeRow {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 11px;
  border: 1px solid var(--lumiverse-border);
  border-radius: var(--lumiverse-radius-lg);
  background: var(--lumiverse-surface-raised);
  touch-action: manipulation;
}

.customizeRowDisabled {
  opacity: 0.58;
}

.customizeRowDragging {
  z-index: 5;
  background: color-mix(in srgb, var(--lumiverse-primary) 8%, var(--lumiverse-surface-raised));
  box-shadow:
    var(--lumiverse-shadow-md),
    0 0 0 1px var(--lumiverse-primary);
}

.customizeDragHandle {
  display: inline-flex;
  flex-shrink: 0;
  width: 22px;
  height: 30px;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: none;
  border-radius: var(--lumiverse-radius-sm);
  background: transparent;
  color: var(--lumiverse-text-dim);
  cursor: grab;
  touch-action: none;
  user-select: none;
}

.customizeDragHandle:hover:not(:disabled) {
  background: var(--lumiverse-primary-015);
  color: var(--lumiverse-text);
}

.customizeDragHandle:active:not(:disabled) {
  cursor: grabbing;
}

.customizeDragHandle:disabled {
  opacity: 0.3;
  cursor: default;
}

.customizeIconWrap {
  display: inline-flex;
  flex-shrink: 0;
  width: 32px;
  height: 32px;
  align-items: center;
  justify-content: center;
  border-radius: var(--lumiverse-radius-md);
  background: var(--lumiverse-primary-015);
  color: var(--lumiverse-primary);
}

.customizeCopy {
