  border-top: 1px solid var(--lumiverse-border);
}

.customizeResetButton,
.customizeDoneButton {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 34px;
  padding: 0 16px;
  border-radius: var(--lumiverse-radius);
  font: inherit;
  font-size: calc(12.5px * var(--lumiverse-font-scale, 1));
