}

.customizeResetButton {
  border: 1px solid var(--lumiverse-border);
  background: transparent;
  color: var(--lumiverse-text-muted);
}

.customizeResetButton:hover {
  background: var(--lumiverse-fill-hover);
  color: var(--lumiverse-text);
}

.customizeDoneButton {
  border: 1px solid transparent;
  background: var(--lumiverse-primary);
  color: var(--lumiverse-primary-contrast, #fff);
  font-weight: 600;
}

.customizeDragHandle:focus-visible,
.customizeResetButton:focus-visible,
.customizeDoneButton:focus-visible {
  outline: 2px solid var(--lumiverse-primary);
  outline-offset: 2px;
}

@media (max-width: 720px) {
  .customizeBody {
    max-height: min(70vh, 720px);
    padding-left: 14px;
    padding-right: 14px;
  }

  .customizeHeader,
  .customizeFooter {
    padding-left: 14px;
    padding-right: 14px;
  }
}

