      // the global preset save coordinator.
      const hydrated = binding
        ? unmarshalPreset(preset)
        : presetSaveCoordinator.hydrate(
            unmarshalPreset(preset),
            presetSaveCoordinator.beginHydration(presetId, 'prompt-variables'),
