  // While hidden for mobile edit, the RO below cannot observe a display:none
  // element, so --lcs-input-safe-zone would freeze at the pre-edit (potentially
  // tall) value and leave a void under the message list. Override directly.
  useLayoutEffect(() => {
    if (!hideForMobileEdit) return
    const parent = containerRef.current?.parentElement
    if (!parent) return
    const root = document.documentElement
    let syncRaf = 0

    const syncHiddenEditSafeZone = () => {
      const rootStyle = getComputedStyle(root)
      const keyboardInset = parseFloat(rootStyle.getPropertyValue('--app-keyboard-inset-bottom')) || 0
      const zones = composeChatSafeZones(16, 0, renderedPxToLayoutPx(keyboardInset))
      parent.style.setProperty('--lcs-composer-safe-zone', `${Math.round(zones.composerSafeZone)}px`)
      parent.style.setProperty('--lcs-input-safe-zone', `${Math.round(zones.inputSafeZone)}px`)
    }

    const scheduleHiddenEditSafeZoneSync = () => {
      if (syncRaf) cancelAnimationFrame(syncRaf)
      syncRaf = requestAnimationFrame(() => {
        syncRaf = 0
        syncHiddenEditSafeZone()
      })
    }

    const rootObserver = new MutationObserver(scheduleHiddenEditSafeZoneSync)
    rootObserver.observe(root, { attributes: true, attributeFilter: ['style'] })

    syncHiddenEditSafeZone()
    window.addEventListener('resize', scheduleHiddenEditSafeZoneSync)
    window.visualViewport?.addEventListener('resize', scheduleHiddenEditSafeZoneSync)
    window.visualViewport?.addEventListener('scroll', scheduleHiddenEditSafeZoneSync)

    return () => {
      rootObserver.disconnect()
      if (syncRaf) cancelAnimationFrame(syncRaf)
      window.removeEventListener('resize', scheduleHiddenEditSafeZoneSync)
      window.visualViewport?.removeEventListener('resize', scheduleHiddenEditSafeZoneSync)
      window.visualViewport?.removeEventListener('scroll', scheduleHiddenEditSafeZoneSync)
      parent.style.removeProperty('--lcs-composer-safe-zone')
      parent.style.removeProperty('--lcs-input-safe-zone')
    }
  }, [hideForMobileEdit])

  // ResizeObserver — set --lcs-input-safe-zone on parent so scroll padding stays in sync
  useLayoutEffect(() => {
    if (hideForMobileEdit) return
    const el = containerRef.current
    if (!el) return
    const parent = el.parentElement
    if (!parent) return
    const root = document.documentElement
    const loreMount = el.querySelector<HTMLElement>('[data-spindle-mount="chat_composer_above"]')
    const popoverSlot = el.querySelector<HTMLElement>('[data-composer-popover]')
    const formattingBar = el.querySelector<HTMLElement>('[data-composer-formatting]')

    const measureLoreHeight = () => {
      if (!loreMount) return 0
      const children = Array.from(loreMount.children) as HTMLElement[]
      if (children.length === 0) return Math.max(0, loreMount.offsetHeight)
      return children.reduce((height, child) => {
        const renderedHeight = renderedPxToLayoutPx(child.getBoundingClientRect().height)
        return height + Math.max(0, renderedHeight, child.offsetHeight)
      }, 0)
    }

    const update = () => {
      const loreHeight = measureLoreHeight()
      const h = measureComposerHeight(el, popoverSlot)
      const formattingHeight = formattingBar ? renderedPxToLayoutPx(formattingBar.getBoundingClientRect().height) + 8 : 0
      const composerHeight = Math.max(0, h - loreHeight) + formattingHeight + 8
      // Use the animated position, so list padding and composer move together.
      // Zero is valid for edge-to-edge PWA composers.
      const measuredBottom = parseFloat(getComputedStyle(el).bottom)
      const bottomOffset = Number.isFinite(measuredBottom) ? measuredBottom : 12
      const zones = composeChatSafeZones(composerHeight, loreHeight, bottomOffset)
      const publish = (name: string, value: number) => {
        const next = `${Math.round(value)}px`
        if (parent.style.getPropertyValue(name) !== next) parent.style.setProperty(name, next)
      }
      publish('--lcs-composer-safe-zone', zones.composerSafeZone)
      publish('--lcs-input-safe-zone', zones.inputSafeZone)
    }

    const ro = new ResizeObserver(update)
    ro.observe(el)
    if (formattingBar) ro.observe(formattingBar)
    if (loreMount) ro.observe(loreMount)
    const stopObservingMotion = observeComposerMotion(el, update)
    update()

    // On iOS PWA, the virtual keyboard changes `bottom` via CSS variable but
    // doesn't change the element's size — ResizeObserver alone won't catch it.
    // Mirror root style writes as well because some focus transitions only
    // update --app-keyboard-inset-bottom after our own JS sync path.
    let vpFrame = 0
    const onViewportResize = () => {
      // Run after main.tsx's syncViewportVars (also uses requestAnimationFrame)
      cancelAnimationFrame(vpFrame)
      vpFrame = requestAnimationFrame(update)
    }
    // Root writes already contain main.tsx's latest inset. Measure before
    // paint, including when reduced motion makes the bottom change instant.
    const rootObserver = new MutationObserver(update)
    rootObserver.observe(root, { attributes: true, attributeFilter: ['style'] })
    window.addEventListener('resize', onViewportResize)
    window.visualViewport?.addEventListener('resize', onViewportResize)
    window.visualViewport?.addEventListener('scroll', onViewportResize)

    return () => {
      ro.disconnect()
      stopObservingMotion()
      cancelAnimationFrame(vpFrame)
      rootObserver.disconnect()
      window.removeEventListener('resize', onViewportResize)
      window.visualViewport?.removeEventListener('resize', onViewportResize)
      window.visualViewport?.removeEventListener('scroll', onViewportResize)
      parent.style.removeProperty('--lcs-composer-safe-zone')
      parent.style.removeProperty('--lcs-input-safe-zone')
    }
  }, [hideForMobileEdit, showComposerFormattingBar, showSTTIndicator])

  // Document-level Escape to stop generation
