    return 'sent'
  }, [text, chatId, draft, acknowledgeDraft, resizeTextarea, finalizeRegexSelections, t])

  const handleQueueMessage = useCallback(async () => {
    if (sendingRef.current || isGeneratingInChat) return
    sendingRef.current = true
