                    disabled={manuallyActiveGuideCount === 0}
                  >
                    <span>{t('quickMenu.disableAllGuidedGenerations')}</span>
                    <span className={styles.popMeta}>{t('quickMenu.activeCount', { count: activeGuideCount })}</span>
