              </button>
            </div>
          ) : (
            <div className={styles.sendBtnShell}>
              {mobileQueueHint ? (
                <span
                  className={clsx(
                    styles.mobileQueueHint,
                    mobileQueueHoldState === 'holding' && styles.mobileQueueHintHolding,
                    mobileQueueHoldState === 'armed' && styles.mobileQueueHintReady,
                    mobileQueueHoldState === 'queueing' && styles.mobileQueueHintQueueing
                  )}
                  aria-live="polite"
                >
                  {mobileQueueHint}
                </span>
              ) : null}
              <button
                type="button"
                className={clsx(
                  styles.sendBtn,
                  mobileQueueHoldState === 'holding' && styles.sendBtnHoldTracking,
                  mobileQueueHoldState === 'armed' && styles.sendBtnHoldReady,
                  mobileQueueHoldState === 'queueing' && styles.sendBtnQueueing
                )}
                onClick={handleSendClick}
                onPointerDown={handleSendPointerDown}
                onPointerUp={handleSendPointerUp}
                onPointerCancel={handleSendPointerCancel}
                disabled={isGeneratingInChat || isSavingMessage}
                style={sendButtonStyle}
                title={sendButtonTitle}
                aria-label={sendButtonAriaLabel}
                aria-busy={isSavingMessage || undefined}
              >
                <span className={styles.sendBtnIcon}>
                  {isSavingMessage || mobileQueueHoldState === 'queueing' ? (
                    <LoaderCircle size={16} className={styles.sendBtnSpinner} />
                  ) : mobileQueueHoldState === 'holding' || mobileQueueHoldState === 'armed' ? (
                    <IconPlaylistAdd size={18} />
                  ) : (
                    <Send size={16} />
                  )}
                </span>
              </button>
            </div>
          )}
          <span data-spindle-mount="chat_input_tools_right" data-spindle-scope={`chat:${chatId}:input-tools-right`} className={styles.inputToolsSlot} />
        </div>
      )}
      <span data-spindle-mount="chat_composer_below" data-spindle-scope={`chat:${chatId}:composer-below`} style={{ display: 'contents' }} />
    </div>
  )
}

export default function InputArea(props: InputAreaProps) {
  return useSpindleComponentOverride('InputArea', InputAreaNative, props)
}

