.attachments {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding: 4px 0 2px;
}

.attachmentsUser {
  justify-content: flex-end;
}

/* ── User-sent images — prominent shared-media card ── */
.imageThumbUser {
  display: block;
  overflow: hidden;
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.04));
  cursor: pointer;
  padding: 0;
  border: 1px solid var(--lumiverse-border, rgba(255, 255, 255, 0.1));
  border-radius: var(--lcs-radius, 14px);
  max-width: 240px;
  max-height: 240px;
  transition:
    border-color var(--lcs-transition-fast, 120ms ease),
    box-shadow var(--lcs-transition-fast, 120ms ease),
    transform var(--lcs-transition-fast, 120ms ease);
}

.imageThumbUser:hover {
  border-color: var(--lumiverse-primary-040, rgba(140, 130, 255, 0.4));
  transform: scale(1.02);
}

:global([data-glass]) .imageThumbUser {
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.25);
}

:global([data-glass]) .imageThumbUser:hover {
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.35);
}

.imageThumbUser img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  max-width: 240px;
  max-height: 240px;
}

/* ── Assistant images — compact thumbnail that opens in lightbox ── */
.inlineImageBtn {
  display: block;
  overflow: hidden;
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.04));
  cursor: pointer;
  padding: 0;
  border: 1px solid var(--lumiverse-border, rgba(255, 255, 255, 0.1));
  border-radius: var(--lcs-radius, 14px);
  max-width: 240px;
  max-height: 240px;
  transition:
    border-color var(--lcs-transition-fast, 120ms ease),
    box-shadow var(--lcs-transition-fast, 120ms ease),
    transform var(--lcs-transition-fast, 120ms ease);
}

.inlineImageBtn:hover {
  border-color: var(--lumiverse-primary-040, rgba(140, 130, 255, 0.4));
  transform: scale(1.02);
}

:global([data-glass]) .inlineImageBtn {
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.25);
}

:global([data-glass]) .inlineImageBtn:hover {
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.35);
}

.inlineImageWrap {
  overflow: hidden;
  width: 100%;
  height: 100%;
}

.inlineImage {
  display: block;
  border-radius: var(--lcs-radius-sm, 8px);
}

.videoAttachment {
  display: block;
  width: min(100%, 360px);
  max-height: 280px;
  background: #000;
  border: 1px solid var(--lumiverse-border, rgba(255, 255, 255, 0.1));
  border-radius: var(--lcs-radius, 14px);
}

/* ── Mobile: scale images down ── */
@media (max-width: 480px) {
  .imageThumbUser,
  .inlineImageBtn {
    max-width: 180px;
    max-height: 180px;
  }

  .imageThumbUser img {
    max-width: 180px;
    max-height: 180px;
  }

  .videoAttachment {
    width: min(100%, 280px);
    max-height: 220px;
  }
}

/* Explicit presentation preferences override thumbnail frames, including LazyImage's inline sizing. */
.imageRow {
  width: 100%;
  min-width: 0;
}

.customPresentation .imageThumbUser,
.customPresentation .inlineImageBtn {
  margin-left: var(--chat-image-margin-left, 0);
  margin-right: var(--chat-image-margin-right, auto);
}

.customSize .imageThumbUser,
.customSize .inlineImageBtn {
  width: var(--chat-image-width) !important;
  max-width: 100%;
  max-height: none;
  aspect-ratio: auto !important;
}

.customSize .imageThumbUser > div,
.customSize .inlineImageWrap {
  height: auto !important;
}

.customSize img {
  display: block;
  width: 100% !important;
  max-width: 100%;
  height: auto !important;
  max-height: var(--chat-image-max-height) !important;
  object-fit: contain;
  object-position: var(--chat-image-object-position, left) !important;
}

sources.src/components/chat/MessageAttachments.t:
import { useState, useCallback, useMemo, type CSSProperties, type SyntheticEvent } from 'react'
import { useTranslation } from 'react-i18next'
import { Trash2 } from 'lucide-react'
import type { MessageAttachment } from '@/types/api'
import { imagesApi } from '@/api/images'
import { messagesApi } from '@/api/chats'
import { chatImagePresentationStyle, DEFAULT_CHAT_IMAGE_TARGETS } from '@/lib/chatImagePresentation'
import { useStore } from '@/store'
import { useLongPress } from '@/hooks/useLongPress'
import ContextMenu, { type ContextMenuEntry, type ContextMenuPos } from '@/components/shared/ContextMenu'
import ImageLightbox from '@/components/shared/ImageLightbox'
import LazyImage from '@/components/shared/LazyImage'
import { dispatchMessageContentLayout } from '@/lib/message-content-layout'
import styles from './MessageAttachments.module.css'
import clsx from 'clsx'

interface MessageAttachmentsProps {
  attachments: MessageAttachment[]
  isUser?: boolean
  /** Chat + message ids enable per-image actions (Remove image). Omit to render in read-only mode. */
  chatId?: string
  messageId?: string
}

function getImageFrameStyle(att: MessageAttachment): CSSProperties | undefined {
  if (!att.width || !att.height) return undefined
  const scale = Math.min(1, 240 / att.width, 240 / att.height)

  return {
    aspectRatio: `${att.width} / ${att.height}`,
    width: Math.max(1, Math.round(att.width * scale)),
    maxWidth: '100%',
  }
}

function getLocalImageUrl(att: MessageAttachment): string {
  return imagesApi.url(att.image_id)
}

function getLocalImagePreviewUrl(att: MessageAttachment): string {
  // Inline message art is capped around 240 CSS px. The 700px tier remains
  // sharp at high device-pixel ratios without decoding an arbitrary-size
  // original inside every mounted message row.
  return imagesApi.largeUrl(att.image_id)
}

function getRelayPreviewUrl(att: MessageAttachment): string | null {
  return typeof att.relay_preview_url === 'string' && att.relay_preview_url.startsWith('data:image/')
    ? att.relay_preview_url
    : null
}

export default function MessageAttachments({ attachments, isUser, chatId, messageId }: MessageAttachmentsProps) {
  const { t } = useTranslation('chat')
  const [lightboxSrc, setLightboxSrc] = useState<string | null>(null)
  const [lightboxFallbackSrc, setLightboxFallbackSrc] = useState<string | null>(null)
  const [lightboxImageId, setLightboxImageId] = useState<string | null>(null)
  const [contextMenuPos, setContextMenuPos] = useState<ContextMenuPos | null>(null)
  const [targetImageId, setTargetImageId] = useState<string | null>(null)
  const size = useStore(s => s.chatImageSize ?? 'default')
  const alignment = useStore(s => s.chatImageAlignment ?? 'left')
  const targets = useStore(s => s.chatImageTargets ?? DEFAULT_CHAT_IMAGE_TARGETS)
  const customSize = !!chatId && !!messageId && targets.attachments && size !== 'default'
  const customPresentation = !!chatId && !!messageId && targets.attachments && (customSize || alignment !== 'left')
  const messageContextMenuEnabled = useStore((s) => s.messageContextMenuEnabled ?? true)
  const addToast = useStore((s) => s.addToast)

  const canActOnImage = messageContextMenuEnabled && !!chatId && !!messageId
  const closeLightbox = useCallback(() => {
    setLightboxSrc(null)
    setLightboxFallbackSrc(null)
    setLightboxImageId(null)
  }, [])
  const openLightbox = useCallback((att: MessageAttachment) => {
    setLightboxImageId(att.image_id)
    setLightboxSrc(getLocalImageUrl(att))
    setLightboxFallbackSrc(getRelayPreviewUrl(att))
  }, [])
  const notifyImageLayout = useCallback((event: SyntheticEvent<HTMLImageElement>) => {
    dispatchMessageContentLayout(event.currentTarget)
  }, [])
  const closeContextMenu = useCallback(() => {
    setContextMenuPos(null)
    setTargetImageId(null)
  }, [])

  const openImageMenu = useCallback((imageId: string, pos: ContextMenuPos) => {
    setTargetImageId(imageId)
    setContextMenuPos(pos)
  }, [])

  const removeAttachment = useCallback(async () => {
    if (!chatId || !messageId || !targetImageId) return
    closeContextMenu()
    try {
      // Drive the same-tab UI off the HTTP response so the bubble refreshes the
      // instant the request resolves. The backend also broadcasts MESSAGE_EDITED
      // over WS, which keeps other tabs / clients in sync as a defensive
      // parallel update.
      const updated = await messagesApi.removeAttachment(chatId, messageId, targetImageId)
      if (updated) {
        useStore.getState().updateMessage(messageId, updated)
      }
    } catch (err: any) {
      addToast({ type: 'error', title: t('attachments.couldNotRemoveImage'), message: err?.body?.error || err?.message || 'Unknown error' })
    }
  }, [addToast, chatId, closeContextMenu, messageId, targetImageId, t])

  // Removes the image currently shown in the lightbox. Throws on failure so the
  // lightbox surfaces its own error toast (the thumbnail context-menu path uses
  // removeAttachment above, which toasts here instead).
  const deleteLightboxImage = useCallback(async () => {
    if (!chatId || !messageId || !lightboxImageId) return
    const updated = await messagesApi.removeAttachment(chatId, messageId, lightboxImageId)
    if (updated) useStore.getState().updateMessage(messageId, updated)
  }, [chatId, messageId, lightboxImageId])

  const longPress = useLongPress({
    onLongPress: (pos) => {
      // Long-press fires for the most-recently armed image (set in onTouchStart below).
      if (!canActOnImage) return
      const armed = longPressTargetRef.current
      if (!armed) return
      openImageMenu(armed, pos)
    },
  })

  // Track which image started the touch so the long-press callback knows the target.
  // (useLongPress doesn't pass the event target through.)
  const longPressTargetRef = useMemo(() => ({ current: null as string | null }), [])

  const onImageTouchStart = useCallback((imageId: string) => (e: React.TouchEvent) => {
    longPressTargetRef.current = imageId
    longPress.onTouchStart(e)
  }, [longPress, longPressTargetRef])

  const onImageContextMenu = useCallback((imageId: string) => (e: React.MouseEvent) => {
    if (!canActOnImage) return
    e.preventDefault()
    e.stopPropagation()
    openImageMenu(imageId, { x: e.clientX, y: e.clientY })
  }, [canActOnImage, openImageMenu])

  const contextMenuItems: ContextMenuEntry[] = useMemo(() => [
    {
      key: 'remove-image',
      label: t('attachments.removeImage'),
      icon: <Trash2 size={14} />,
      danger: true,
      onClick: () => { void removeAttachment() },
    },
  ], [removeAttachment, t])

  // Audio attachments are rendered by the separate MessageAudioSlot
  // component as a sibling of MessageAttachments — keeping it out of the
  // flex-wrap row here means the slot can collapse to 0 height (without
  // dragging this wrapper's padding along) when there's no audio.
  const visualMedia = attachments.filter((a) => a.type === 'image' || a.type === 'video')

  if (visualMedia.length === 0) return null

  return (
    <>
      <div
        className={clsx(styles.attachments, isUser && styles.attachmentsUser, customPresentation && styles.customPresentation, customSize && styles.customSize)}
        style={customPresentation ? chatImagePresentationStyle(size, alignment) : undefined}
      >
        {visualMedia.map((att) => {
          if (att.type === 'video') return (
            <video
              key={att.image_id}
              src={getLocalImageUrl(att)}
              className={styles.videoAttachment}
              controls
              preload="metadata"
              playsInline
              title={att.original_filename}
              onLoadedMetadata={(event) => dispatchMessageContentLayout(event.currentTarget)}
              onContextMenu={onImageContextMenu(att.image_id)}
              onTouchStart={canActOnImage ? onImageTouchStart(att.image_id) : undefined}
              onTouchMove={canActOnImage ? longPress.onTouchMove : undefined}
              onTouchEnd={canActOnImage ? longPress.onTouchEnd : undefined}
            />
          )
          const image = isUser ? (
            <button
              key={att.image_id}
              type="button"
              className={styles.imageThumbUser}
              style={getImageFrameStyle(att)}
              onClick={() => openLightbox(att)}
              onContextMenu={onImageContextMenu(att.image_id)}
              onTouchStart={canActOnImage ? onImageTouchStart(att.image_id) : undefined}
              onTouchMove={canActOnImage ? longPress.onTouchMove : undefined}
              onTouchEnd={canActOnImage ? longPress.onTouchEnd : undefined}
              title={att.original_filename}
            >
              <LazyImage
                src={customSize ? getLocalImageUrl(att) : getLocalImagePreviewUrl(att)}
                alt={att.original_filename}
                style={{ objectFit: 'contain' }}
                spinnerSize={18}
                onLoad={notifyImageLayout}
                onError={notifyImageLayout}
                fallback={getRelayPreviewUrl(att) ? (
                  <LazyImage
                    src={getRelayPreviewUrl(att)}
                    alt={att.original_filename}
                    style={{ objectFit: 'contain' }}
                    spinnerSize={18}
                    onLoad={notifyImageLayout}
                    onError={notifyImageLayout}
                  />
                ) : null}
              />
            </button>
          ) : (
            <button
              key={att.image_id}
              type="button"
              className={styles.inlineImageBtn}
              style={getImageFrameStyle(att)}
              onClick={() => openLightbox(att)}
              onContextMenu={onImageContextMenu(att.image_id)}
              onTouchStart={canActOnImage ? onImageTouchStart(att.image_id) : undefined}
              onTouchMove={canActOnImage ? longPress.onTouchMove : undefined}
              onTouchEnd={canActOnImage ? longPress.onTouchEnd : undefined}
            >
              <LazyImage
                src={customSize ? getLocalImageUrl(att) : getLocalImagePreviewUrl(att)}
                alt={att.original_filename}
                className={styles.inlineImage}
                style={att.width && att.height
                  ? { objectFit: 'contain' }
                  : { objectFit: 'contain', width: 'auto', height: 'auto', maxWidth: '100%', maxHeight: '240px' }
                }
                containerClassName={styles.inlineImageWrap}
                spinnerSize={20}
                onLoad={notifyImageLayout}
                onError={notifyImageLayout}
                fallback={getRelayPreviewUrl(att) ? (
                  <LazyImage
                    src={getRelayPreviewUrl(att)}
                    alt={att.original_filename}
                    className={styles.inlineImage}
                    style={att.width && att.height
                      ? { objectFit: 'contain' }
                      : { objectFit: 'contain', width: 'auto', height: 'auto', maxWidth: '100%', maxHeight: '240px' }
                    }
                    containerClassName={styles.inlineImageWrap}
                    spinnerSize={20}
                    onLoad={notifyImageLayout}
                    onError={notifyImageLayout}
                  />
                ) : null}
              />
            </button>
          )
          return customPresentation
            ? <div key={att.image_id} className={styles.imageRow}>{image}</div>
            : image
        })}
      </div>

      <ImageLightbox
        src={lightboxSrc}
        fallbackSrc={lightboxFallbackSrc}
        onClose={closeLightbox}
        onDelete={canActOnImage ? deleteLightboxImage : undefined}
      />
      <ContextMenu position={contextMenuPos} items={contextMenuItems} onClose={closeContextMenu} />
    </>
  )
}

