/* ── Wrapper: hosts the load-in animation so the player can grow into
   place from 0-height instead of popping into the message and shoving
   surrounding content. Uses grid-template-rows: 0fr → 1fr which is the
   only pure-CSS way to animate height: 0 → auto.
   Browsers without grid-template-rows animation (older Safari) get an
   instant height jump but still see the opacity+scale fade.            */

.wrapper {
  display: grid;
  grid-template-rows: 1fr;
}

.wrapperInner {
  /* `min-height: 0` lets the grid track shrink past content size during
     the animation. We intentionally do NOT set overflow:hidden here at
     base — that was clipping the volume popover after the animation
     finished, making volume controls inaccessible. Overflow is clipped
     only while the load-in animation is running (see .wrapperFresh
     selector below) so the popover renders freely in static state.   */
  min-height: 0;
}

.wrapperFresh {
  /* `both` keeps the end-state styles applied while we wait for
     onAnimationEnd to flip animationDone — avoids a one-frame snap-back
     to the from-state at the end of the run. */
  animation: ttsAudioLoadIn 280ms cubic-bezier(0.2, 0.7, 0.2, 1) both;
}

.wrapperExiting {
  /* Reverse of the load-in animation. Slightly shorter (220ms) so the
     departure feels snappier than the arrival — common UX pattern that
     keeps removal from feeling like a drawn-out fade. */
  animation: ttsAudioLoadOut 220ms cubic-bezier(0.4, 0, 0.6, 1) both;
}

.wrapperFresh .wrapperInner,
.wrapperExiting .wrapperInner {
  /* Clip while the height is animating in either direction. Once the
     animation lands and the class is removed, overflow returns to
     visible so the volume popover isn't clipped by the wrapper. */
  overflow: hidden;
}

@keyframes ttsAudioLoadIn {
  from {
    grid-template-rows: 0fr;
    opacity: 0;
    transform: scale(0.96);
  }
  to {
    grid-template-rows: 1fr;
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes ttsAudioLoadOut {
  from {
    grid-template-rows: 1fr;
    opacity: 1;
    transform: scale(1);
  }
  to {
    grid-template-rows: 0fr;
    opacity: 0;
    transform: scale(0.96);
  }
}

@media (prefers-reduced-motion: reduce) {
  /* Respect the reduce-motion preference — collapse the animations to
     short fades so the player still distinguishes its arrival/departure
     without doing the scale/height movement. */
  .wrapperFresh {
    animation: ttsAudioLoadInReduced 120ms ease-out both;
  }

  .wrapperExiting {
    animation: ttsAudioLoadOutReduced 120ms ease-out both;
  }

  @keyframes ttsAudioLoadInReduced {
    from { opacity: 0; }
    to { opacity: 1; }
  }

  @keyframes ttsAudioLoadOutReduced {
    from { opacity: 1; }
    to { opacity: 0; }
  }
}

.player {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 32px;
  padding: 0 8px 0 4px;
  min-width: 220px;
  max-width: 360px;
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.04));
  border: 1px solid var(--lumiverse-border, rgba(255, 255, 255, 0.08));
  border-radius: 999px;
  color: var(--lumiverse-text, rgba(230, 230, 240, 0.92));
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  user-select: none;
  -webkit-user-select: none;
  position: relative;
  transition:
    border-color var(--lcs-transition-fast, 120ms ease),
    background var(--lcs-transition-fast, 120ms ease);
}

.player:hover {
  border-color: var(--lumiverse-primary-040, rgba(140, 130, 255, 0.4));
}

.playerUser {
  align-self: flex-end;
}

/* While a save-first regen is in flight: visually de-emphasize the
   controls so the regenerating overlay reads as the foreground state.
   We don't disable pointer events on the controls — the user might
   still want to click Cancel via the bubble's TTS button — but they
   aren't intended to be the primary interaction target right now. */
.playerRegenerating .playBtn,
.playerRegenerating .slider,
.playerRegenerating .time,
.playerRegenerating .volumeBtn,
.playerRegenerating .downloadBtn,
.playerRegenerating .deleteBtn {
  opacity: 0.35;
  transition: opacity var(--lcs-transition-fast, 120ms ease);
}

.regenOverlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  /* Match the pill's rounded corners so the overlay doesn't appear to
     bleed outside the player. */
  border-radius: inherit;
  /* Transparent — we want the dimmed controls visible underneath so the
     regen feels in-place rather than masked. */
  pointer-events: none;
  color: var(--lumiverse-text, rgba(230, 230, 240, 0.92));
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
}

.regenSpinner {
  animation: ttsAudioSpin 800ms linear infinite;
  color: var(--lumiverse-primary, #9370db);
}

.regenLabel {
  font-weight: 500;
  letter-spacing: 0.01em;
}

@keyframes ttsAudioSpin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

@media (prefers-reduced-motion: reduce) {
  .regenSpinner {
    /* Hold the spinner static rather than churning; the label still
       communicates the in-flight state. */
    animation: none;
  }
}

.playBtn,
.volumeBtn,
.volumeMuteBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  padding: 0;
  border: none;
  border-radius: 50%;
  background: var(--lumiverse-primary, #9370db);
  color: var(--lumiverse-on-primary, #fff);
  cursor: pointer;
  flex-shrink: 0;
  transition:
    background var(--lcs-transition-fast, 120ms ease),
    transform var(--lcs-transition-fast, 120ms ease);
}

.playBtn:hover,
.volumeBtn:hover,
.volumeMuteBtn:hover {
  background: var(--lumiverse-primary-hover, color-mix(in srgb, var(--lumiverse-primary, #9370db) 88%, white));
}

.playBtn:active,
.volumeBtn:active {
  transform: scale(0.94);
}

.volumeBtn,
.volumeMuteBtn {
  background: transparent;
  color: var(--lumiverse-text-dim, rgba(230, 230, 240, 0.6));
  width: 22px;
  height: 22px;
}

.volumeBtn:hover,
.volumeMuteBtn:hover {
  background: var(--lumiverse-fill-strong, rgba(255, 255, 255, 0.08));
  color: var(--lumiverse-text, rgba(230, 230, 240, 0.92));
}

/* Secondary download/delete actions at the trailing edge. */
.downloadBtn,
.deleteBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  padding: 0;
  border: none;
  border-radius: 50%;
  background: transparent;
  color: var(--lumiverse-text-dim, rgba(230, 230, 240, 0.45));
  cursor: pointer;
  flex-shrink: 0;
  transition:
    background var(--lcs-transition-fast, 120ms ease),
    color var(--lcs-transition-fast, 120ms ease),
    transform var(--lcs-transition-fast, 120ms ease);
}

.downloadBtn:hover:not(:disabled),
.downloadBtn:focus-visible:not(:disabled) {
  background: var(--lumiverse-fill-strong, rgba(255, 255, 255, 0.08));
  color: var(--lumiverse-primary, #9370db);
}

.deleteBtn:hover:not(:disabled),
.deleteBtn:focus-visible:not(:disabled) {
  background: color-mix(in srgb, var(--lumiverse-danger, #ef4444) 18%, transparent);
  color: var(--lumiverse-danger, #ef4444);
}

.downloadBtn:active:not(:disabled),
.deleteBtn:active:not(:disabled) {
  transform: scale(0.94);
}

.downloadBtn:disabled,
.deleteBtn:disabled {
  cursor: default;
  opacity: 0.35;
}

/* ── Shared slider base ─────────────────────────────────────────────────
   Both seek and volume use native <input type="range"> so we inherit
   keyboard (arrow keys / Home / End), screen reader announcements
   (aria-valuenow surfaced as a percentage automatically), and the
   browser's native touch handling — no custom pointer event plumbing.

   The visible track is rendered via a linear-gradient that splits at
   --progress (a CSS custom property the component updates via inline
   style). This is the cross-browser way to draw a "filled" portion in
   WebKit, since ::-webkit-slider-runnable-track has no ::progress
   pseudo. Firefox additionally supports ::-moz-range-progress which we
   set separately below for a crisper fill.                              */

.slider {
  -webkit-appearance: none;
  appearance: none;
  background: transparent;
  cursor: pointer;
  margin: 0;
  padding: 0;
  /* The input height is the pointer hit zone — keep it ~18px so finger
     and mouse pointers both have comfortable target without making the
     player taller. The visible track is much thinner (4px). */
  height: 18px;
  --progress: 0%;
}

.slider:focus {
  outline: none;
}

.slider:focus-visible {
  /* Keyboard-only focus ring — pointer interactions don't show it so
     it doesn't add visual noise when scrubbing with a mouse. */
  outline: 2px solid var(--lumiverse-primary, #9370db);
  outline-offset: 3px;
  border-radius: 4px;
}

/* WebKit / Blink / new Edge track */
.slider::-webkit-slider-runnable-track {
  height: 4px;
  border-radius: 2px;
  background: linear-gradient(
    to right,
    var(--lumiverse-primary, #9370db) 0,
    var(--lumiverse-primary, #9370db) var(--progress),
    var(--lumiverse-fill-strong, rgba(255, 255, 255, 0.18)) var(--progress),
    var(--lumiverse-fill-strong, rgba(255, 255, 255, 0.18)) 100%
  );
}

/* WebKit / Blink / new Edge thumb */
.slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--lumiverse-primary, #9370db);
  /* Half-thumb shift up so the thumb centers on the 4px track. */
  margin-top: -4px;
  border: none;
  box-shadow: 0 0 0 2px var(--lumiverse-surface, rgba(20, 20, 28, 0.85));
  transition: transform var(--lcs-transition-fast, 120ms ease);
}

.slider:hover::-webkit-slider-thumb,
.slider:active::-webkit-slider-thumb {
  transform: scale(1.18);
}

/* Firefox track + progress + thumb */
.slider::-moz-range-track {
  height: 4px;
  border-radius: 2px;
  background: var(--lumiverse-fill-strong, rgba(255, 255, 255, 0.18));
}

.slider::-moz-range-progress {
  height: 4px;
  border-radius: 2px;
  background: var(--lumiverse-primary, #9370db);
}

.slider::-moz-range-thumb {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--lumiverse-primary, #9370db);
  border: none;
  box-shadow: 0 0 0 2px var(--lumiverse-surface, rgba(20, 20, 28, 0.85));
  transition: transform var(--lcs-transition-fast, 120ms ease);
}

.slider:hover::-moz-range-thumb,
.slider:active::-moz-range-thumb {
  transform: scale(1.18);
}

/* Seek slider takes the remaining horizontal space. */
.sliderSeek {
  flex: 1 1 auto;
  min-width: 60px;
}

/* Volume slider in the popover has a fixed compact width. */
.sliderVolume {
  width: 96px;
}

.time {
  flex-shrink: 0;
  font-variant-numeric: tabular-nums;
  color: var(--lumiverse-text-dim, rgba(230, 230, 240, 0.55));
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  min-width: 70px;
  text-align: right;
}

.volumeWrap {
  position: relative;
  flex-shrink: 0;
}

.volumePopover {
  position: absolute;
  bottom: calc(100% + 6px);
  right: -4px;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  background: var(--lumiverse-surface-raised, rgba(28, 28, 38, 0.98));
  border: 1px solid var(--lumiverse-border, rgba(255, 255, 255, 0.1));
  border-radius: 999px;
  box-shadow: 0 6px 24px rgba(0, 0, 0, 0.4);
  z-index: 50;
}

@media (max-width: 480px) {
  .player {
    min-width: 180px;
    max-width: 100%;
  }

  .time {
    min-width: 64px;
  }

  .sliderVolume {
    width: 80px;
  }
}

sources.src/components/chat/MessageAudioPlayer.t:
import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  useSyncExternalStore,
  type CSSProperties,
} from 'react'
import { Download, Loader2, Play, Pause, Trash2, Volume2, VolumeX } from 'lucide-react'
import { triggerBlobDownload } from '@/lib/downloads'
import { toast } from '@/lib/toast'
import {
  consumeFreshMarker,
  isRegenerating,
  subscribeRegenerating,
} from '@/lib/ttsPersistence'
import {
  speak,
  stop as stopTTSEngine,
  getActiveMessageId,
  getPlaybackSession,
  subscribeActiveMessage,
  trackTTSAudioElement,
} from '@/lib/ttsAudio'
import styles from './MessageAudioPlayer.module.css'
import clsx from 'clsx'

interface MessageAudioPlayerProps {
  /** URL of the audio file. Bound directly to <audio src>. */
  src: string
  /** Original filename, used for the player tooltip and audio download. */
  title?: string
  /** Start a preview opened by a user gesture; ordinary message playback is unchanged. */
  autoPlay?: boolean
  /** Tagged onto the root so chat-bubble layout can flip alignment. */
  isUser?: boolean
  /**
   * The id of the message this player is attached to. Used to consume any
   * fresh-attachment marker the TTS pipeline left for us — if present, the
   * player runs its load-in animation and (when the marker carries
   * autoPlay=true) starts playback after the animation finishes.
   */
  messageId?: string
  /**
   * When flipped to true, the player pauses playback and runs its load-in
   * animation in reverse (height 1fr → 0fr, opacity 1 → 0). Once the
   * animation finishes, onExited fires so the parent can actually drop the
   * player from the tree. Used by MessageAudioPresence to animate audio
   * attachments out instead of letting them pop, which is the layout-shift
   * source the chat virtualizer was translating into visible scroll jumps.
   */
  exiting?: boolean
  /** Called once the exit animation completes. No-op if exiting is false. */
  onExited?: () => void
  /**
   * Optional delete affordance. When provided, the player renders a tiny
   * trash icon at the trailing edge that fires this callback on click.
   * The parent owns the actual deletion + any confirmation flow — the
   * player just surfaces the button. Omit to hide the delete control
   * (e.g. read-only message views).
   */
  onDelete?: () => void
}

function formatTime(seconds: number): string {
  if (!Number.isFinite(seconds) || seconds < 0) return '0:00'
  const total = Math.floor(seconds)
  const m = Math.floor(total / 60)
  const s = total % 60
  return `${m}:${s.toString().padStart(2, '0')}`
}

/**
 * Minimal custom audio player for TTS attachments. Uses one HTMLAudioElement
 * under the hood — no Web Audio decoding, no segment scheduling — because
 * the file is already a single muxed MP3. Both the seek and volume sliders
 * are native <input type="range"> so keyboard, screen-reader, and touch
 * support come for free; the visual styling (thin track, fill that splits
 * at the current value) is painted via CSS on the standard pseudo-elements.
 */
export default function MessageAudioPlayer({
  src,
  title,
  autoPlay = false,
  isUser,
  messageId,
  exiting = false,
  onExited,
  onDelete,
}: MessageAudioPlayerProps) {
  const audioRef = useRef<HTMLAudioElement | null>(null)
  const volumePopoverRef = useRef<HTMLDivElement | null>(null)
  const volumeButtonRef = useRef<HTMLButtonElement | null>(null)

  const [isPlaying, setIsPlaying] = useState(false)
  const [duration, setDuration] = useState(0)
  const [currentTime, setCurrentTime] = useState(0)
  const [volumeOpen, setVolumeOpen] = useState(false)
  const [volume, setVolume] = useState(1)
  const [muted, setMuted] = useState(false)
  const [downloading, setDownloading] = useState(false)

  // Mount-time consumption of the fresh-attachment marker. We use a lazy
  // initializer so the consume() side effect only fires once across React's
  // potential double-invocation in Strict Mode. Once consumed, the marker
  // can't fire again even if the player remounts (e.g. user scrolled out
  // and back) — that's the right behavior, the load-in animation belongs
  // to the moment the audio first attached, not to every render.
  const [freshMarker] = useState(() =>
    messageId ? consumeFreshMarker(messageId) : null,
  )
  const isFresh = !!freshMarker
  // The wrapper element holds the load-in animation classes. We strip the
  // freshly-attached class after the animation ends so it doesn't replay
  // when the parent re-renders for other reasons.
  const [animationDone, setAnimationDone] = useState(!isFresh)
  const shouldAutoPlay = !!freshMarker?.autoPlay

  const volumePopoverOpenedAt = useRef(0)

  // Track whether this src change is the very first one (mount) so the
  // src-change useEffect doesn't double-trigger autoplay alongside the
  // mount-time fresh-marker consumption.
  const isFirstSrcRef = useRef(true)

  // ── Regenerating observation ────────────────────────────────────────────
  // Subscribe to the regenerating registry so the player can pause + show
  // an overlay while a save-first regen is in flight for this message.
  // The player stays mounted throughout — that's the whole point of using
  // a flag instead of optimistically stripping the attachment from the
  // store (which would unmount the player and cause the layout shift the
  // chat virtualizer turns into a visible scroll jump).
  const regenerating = useSyncExternalStore(
    subscribeRegenerating,
    () => (messageId ? isRegenerating(messageId) : false),
    () => false,
  )

  // ── Engine playback observation ─────────────────────────────────────────
  // True while the shared Web Audio engine is speaking THIS message — either
  // the autoplay-policy fallback below or a pipeline fallback (e.g. save
  // failure during regen). The play button doubles as Stop in that state so
  // the widget never looks idle while its audio is audibly playing.
  const enginePlaying = useSyncExternalStore(
    subscribeActiveMessage,
    () => (messageId ? getActiveMessageId() === messageId : false),
    () => false,
  )

  // Autoplay fallback: HTMLAudioElement.play() without a recent user gesture
  // is rejected by autoplay policy in some browsers (Safari/iOS always by
  // default, Chrome in hidden tabs) — and by the time a generation + synth
  // round-trip finishes, the send gesture is long expired. The Web Audio
  // engine doesn't have that problem: its AudioContext is unlocked once by
  // the app-level primer and stays unlocked, which is exactly how pre-widget
  // auto-play worked. Fetch the saved file and route it through the engine
  // so the user still hears the message; `enginePlaying` keeps the button
  // state coherent.
  const playViaEngineFallback = useCallback((owner = getPlaybackSession()) => {
    if (!messageId) return
    if (getPlaybackSession() !== owner) return
    fetch(src, { credentials: 'include' })
      .then((res) => {
        if (!res.ok) throw new Error(`audio fetch failed: ${res.status}`)
        return res.arrayBuffer()
      })
      .then((buffer) => {
        if (getPlaybackSession() !== owner) return
        speak(buffer, messageId)
      })
      .catch((err) => {
        console.warn('[MessageAudioPlayer] engine fallback failed:', err)
      })
  }, [src, messageId])

  // ── HTMLAudioElement event wiring ───────────────────────────────────────
  useEffect(() => {
    const el = audioRef.current
    if (!el) return

    const onLoaded = () => setDuration(Number.isFinite(el.duration) ? el.duration : 0)
    const onTime = () => setCurrentTime(el.currentTime)
    const onPlay = () => setIsPlaying(true)
    const onPause = () => setIsPlaying(false)
    const onEnded = () => setIsPlaying(false)
    const onVolume = () => {
      setVolume(el.volume)
      setMuted(el.muted)
    }

    el.addEventListener('loadedmetadata', onLoaded)
    el.addEventListener('durationchange', onLoaded)
    el.addEventListener('timeupdate', onTime)
    el.addEventListener('play', onPlay)
    el.addEventListener('playing', onPlay)
    el.addEventListener('pause', onPause)
    el.addEventListener('ended', onEnded)
    el.addEventListener('volumechange', onVolume)
    const untrack = trackTTSAudioElement(el)

    return () => {
      untrack()
      el.removeEventListener('loadedmetadata', onLoaded)
      el.removeEventListener('durationchange', onLoaded)
      el.removeEventListener('timeupdate', onTime)
      el.removeEventListener('play', onPlay)
      el.removeEventListener('playing', onPlay)
      el.removeEventListener('pause', onPause)
      el.removeEventListener('ended', onEnded)
      el.removeEventListener('volumechange', onVolume)
    }
  }, [])

  // Reset state when the src changes (e.g. user regenerated the TTS).
  // Also consume any fresh-attachment marker on src change so a regen that
  // swaps audio A → B can auto-play through the same (still-mounted)
  // player. The first-src guard skips this on mount because mount-time
  // autoplay is already wired through the load-in animation's
  // onAnimationEnd handler — without the guard, both paths would fire
  // play() and the second call would be a no-op but the first would skip
  // the animation wait.
  useEffect(() => {
    setCurrentTime(0)
    setIsPlaying(false)

    if (isFirstSrcRef.current) {
      isFirstSrcRef.current = false
      return
    }
    if (!messageId) return
    const marker = consumeFreshMarker(messageId)
    if (!marker?.autoPlay || (marker.playbackSession !== undefined && marker.playbackSession !== getPlaybackSession())) return
    // The audio element's src is React-bound, so by the time this effect
    // runs the new URL is already on the element. play() awaits whatever
    // loading is needed before it can actually start.
    const el = audioRef.current
    if (!el) return
    const owner = getPlaybackSession()
    void el.play().catch((err) => {
      console.warn('[MessageAudioPlayer] autoplay-on-src-change rejected:', err)
      if ((err as any)?.name === 'NotAllowedError') playViaEngineFallback(owner)
    })
  }, [src, messageId, playViaEngineFallback])

  // Pause whenever we enter the regenerating state. The audio attachment
  // hasn't actually changed yet at this point (the backend save hasn't
  // returned), but the user has explicitly asked to regenerate so we
  // shouldn't keep streaming the about-to-be-replaced file.
  useEffect(() => {
    if (!regenerating) return
    const el = audioRef.current
    if (el && !el.paused) el.pause()
  }, [regenerating])

  // ── Volume popover outside-close (Android-safe) ─────────────────────────
  useEffect(() => {
    if (!volumeOpen) return
    const onPointer = (e: PointerEvent) => {
      // 100ms guard so the click that opened the popover doesn't immediately
      // close it via the same event chain. Matches the codebase convention
      // documented in CLAUDE.md for popovers/dropdowns.
      if (Date.now() - volumePopoverOpenedAt.current < 100) return
      const target = e.target as Node | null
      if (!target) return
      if (volumePopoverRef.current?.contains(target)) return
      if (volumeButtonRef.current?.contains(target)) return
      setVolumeOpen(false)
    }
    document.addEventListener('pointerdown', onPointer)
    return () => document.removeEventListener('pointerdown', onPointer)
  }, [volumeOpen])

  // ── Actions ─────────────────────────────────────────────────────────────
  const downloadAudio = useCallback(async () => {
    if (downloading || regenerating || exiting) return
    setDownloading(true)
    try {
      const response = await fetch(src, { credentials: 'include' })
      if (!response.ok) throw new Error(`Audio download failed: ${response.status}`)
      await triggerBlobDownload(await response.blob(), title || 'audio')
    } catch {
      toast.error('Could not download saved audio')
    } finally {
      setDownloading(false)
    }
  }, [src, title, downloading, regenerating, exiting])

  const togglePlay = useCallback(() => {
    // Engine owns playback (autoplay-policy fallback or pipeline fallback)
    // → the button acts as Stop for it.
    if (messageId && getActiveMessageId() === messageId) {
      stopTTSEngine()
      return
    }
    const el = audioRef.current
    if (!el) return
    if (el.paused || el.ended) {
      // Preempt any engine playback (including other messages') so widget
      // and engine audio never overlap.
      stopTTSEngine()
      void el.play().catch((err) => {
        console.warn('[MessageAudioPlayer] play() rejected:', err)
      })
    } else {
      el.pause()
    }
  }, [messageId])

  useEffect(() => {
    if (!autoPlay) return
    const el = audioRef.current
    if (!el) return
    stopTTSEngine()
    void el.play().catch((err) => {
      console.warn('[MessageAudioPlayer] preview playback rejected:', err)
    })
    return () => el.pause()
  }, [autoPlay, src])

  const toggleMute = useCallback(() => {
    const el = audioRef.current
    if (!el) return
    el.muted = !el.muted
  }, [])

  const openVolume = useCallback(() => {
    volumePopoverOpenedAt.current = Date.now()
    setVolumeOpen((v) => !v)
  }, [])

  // ── Seek + volume input handlers ────────────────────────────────────────
  // Native <input type="range"> fires onChange on every value change
  // (drag, click-to-jump, keyboard arrows). We seek the audio element on
  // every change and update local state so the slider's filled-portion
  // gradient (--progress CSS var) stays in sync without lag.
  const onSeekChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const el = audioRef.current
    if (!el) return
    const next = Number(e.target.value)
    if (!Number.isFinite(next)) return
    el.currentTime = next
    setCurrentTime(next)
  }, [])

  const onVolumeChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const el = audioRef.current
    if (!el) return
    const next = Math.max(0, Math.min(1, Number(e.target.value)))
    if (!Number.isFinite(next)) return
    el.volume = next
    // Nudging volume above 0 implicitly unmutes — matches the platform
    // convention of every other media player. The volumechange listener
    // syncs the React state for the icon.
    if (next > 0 && el.muted) el.muted = false
  }, [])

  // Display values for the slider fill. The seek slider needs a non-zero
  // max while duration is still loading (otherwise the input is rendered
  // disabled by some browsers), so we clamp to 1 before metadata lands.
  const seekMax = duration > 0 ? duration : 1
  const seekProgressPct = useMemo(() => {
    if (duration <= 0) return 0
    return Math.max(0, Math.min(100, (currentTime / duration) * 100))
  }, [currentTime, duration])

  const displayVolume = muted ? 0 : volume
  const volumeProgressPct = displayVolume * 100

  // Pause playback as soon as the parent flags us as exiting — don't keep
  // audio coming out of a shrinking element. Effect (not callback) so that
  // a transition exiting=false→true triggers the pause regardless of which
  // render the prop change arrives in.
  useEffect(() => {
    if (!exiting) return
    const el = audioRef.current
    if (el && !el.paused) el.pause()
    // If the engine fallback is speaking this message's audio, stop it too —
    // the attachment is going away, ghost audio shouldn't outlive it.
    if (messageId && getActiveMessageId() === messageId) stopTTSEngine()
  }, [exiting, messageId])

  // ── Wrapper animation lifecycle ─────────────────────────────────────────
  // Two animations can run on the wrapper: load-in (.wrapperFresh) and
  // exit (.wrapperExiting). Both end via this single handler — we
  // disambiguate by checking which class is active. The exit handler
  // notifies the parent so it can finally drop us from the tree; the
  // load-in handler clears the .fresh class and (when the fresh marker
  // requested it) kicks off playback. We wait until the load-in finishes
  // before starting audio so playback isn't disconnected from the
  // arrival animation.
  const onWrapperAnimationEnd = useCallback((e: React.AnimationEvent<HTMLDivElement>) => {
    // animationend bubbles — only react to the wrapper's own load-in/exit
    // animations, not child animations (custom CSS themes can animate
    // anything inside the bubble, which would otherwise end the load-in
    // early or fire a spurious onExited).
    if (e.target !== e.currentTarget) return
    if (exiting) {
      onExited?.()
      return
    }
    if (animationDone) return
    setAnimationDone(true)
    if (!shouldAutoPlay || (freshMarker.playbackSession !== undefined && freshMarker.playbackSession !== getPlaybackSession())) return
    const el = audioRef.current
    if (!el) return
    const owner = getPlaybackSession()
    void el.play().catch((err) => {
      // Browser autoplay policy blocks unmuted HTMLAudioElement playback
      // without a recent user gesture (Safari/iOS by default, Chrome in
      // hidden tabs) — and the send gesture has long expired by the time
      // generation + synthesis complete. Route the audio through the
      // gesture-primed Web Audio engine instead so auto-play still sounds.
      console.warn('[MessageAudioPlayer] autoplay rejected:', err)
      if ((err as any)?.name === 'NotAllowedError') playViaEngineFallback(owner)
    })
  }, [exiting, onExited, animationDone, shouldAutoPlay, freshMarker, playViaEngineFallback])

  return (
    <div
      className={clsx(
        styles.wrapper,
        // Exit takes precedence: if the parent is animating us out, we're
        // not also playing the load-in. Avoids the visual oddity of an
        // arrival-then-departure flicker on a fast add-then-regen race.
        exiting
          ? styles.wrapperExiting
          : isFresh && !animationDone && styles.wrapperFresh,
      )}
      onAnimationEnd={onWrapperAnimationEnd}
    >
      <div className={styles.wrapperInner}>
        <div
          className={clsx(
            styles.player,
            isUser && styles.playerUser,
            regenerating && styles.playerRegenerating,
          )}
          title={title}
          role="group"
          aria-label="Audio playback"
          aria-busy={regenerating || undefined}
        >
          <button
            type="button"
            className={styles.playBtn}
            onClick={togglePlay}
            aria-label={isPlaying || enginePlaying ? 'Pause' : 'Play'}
            aria-pressed={isPlaying || enginePlaying}
          >
            {isPlaying || enginePlaying ? <Pause size={14} /> : <Play size={14} />}
          </button>

          <input
            type="range"
            className={clsx(styles.slider, styles.sliderSeek)}
            min={0}
            max={seekMax}
            step={0.01}
            value={Math.min(currentTime, seekMax)}
            onChange={onSeekChange}
            disabled={duration <= 0}
            aria-label="Seek"
            // --progress drives the linear-gradient fill on the track
            // pseudo-element. Cast via CSSProperties since CSS vars aren't
            // in the standard React style typings.
            style={{ ['--progress' as any]: `${seekProgressPct}%` } as CSSProperties}
          />

          <span className={styles.time}>
            {formatTime(currentTime)} / {formatTime(duration)}
          </span>

          <div className={styles.volumeWrap}>
            <button
              ref={volumeButtonRef}
              type="button"
              className={styles.volumeBtn}
              onClick={openVolume}
              aria-label="Volume"
              aria-haspopup="true"
              aria-expanded={volumeOpen}
            >
              {displayVolume === 0 ? <VolumeX size={14} /> : <Volume2 size={14} />}
            </button>
            {volumeOpen && (
              <div ref={volumePopoverRef} className={styles.volumePopover} role="dialog">
                <button
                  type="button"
                  className={styles.volumeMuteBtn}
                  onClick={toggleMute}
                  aria-label={muted ? 'Unmute' : 'Mute'}
                >
                  {muted ? <VolumeX size={12} /> : <Volume2 size={12} />}
                </button>
                <input
                  type="range"
                  className={clsx(styles.slider, styles.sliderVolume)}
                  min={0}
                  max={1}
                  step={0.01}
                  value={displayVolume}
                  onChange={onVolumeChange}
                  aria-label="Volume level"
                  style={{ ['--progress' as any]: `${volumeProgressPct}%` } as CSSProperties}
                />
              </div>
            )}
          </div>

          <button
            type="button"
            className={styles.downloadBtn}
            onClick={downloadAudio}
            aria-label="Download saved audio"
            title={downloading ? 'Downloading saved audio…' : 'Download saved audio'}
            aria-busy={downloading || undefined}
            disabled={downloading || regenerating || exiting}
          >
            {downloading ? <Loader2 size={12} className={styles.regenSpinner} /> : <Download size={12} />}
          </button>

          {onDelete && (
            <button
              type="button"
              className={styles.deleteBtn}
              onClick={onDelete}
              aria-label="Delete saved audio"
              title="Delete saved audio"
              disabled={regenerating}
            >
              <Trash2 size={12} />
            </button>
          )}

          <audio
            ref={audioRef}
            preload="metadata"
            src={src}
          />

          {/* Regenerating overlay — covers the player pill while a save-first
              regen is in flight. Keeps the row height stable (zero layout
              shift) while still giving the user visible feedback that their
              regen click took effect. Pointer-events: none on the dim layer
              so the spinner doesn't intercept clicks; the underlying
              controls are aria-busy anyway. */}
          {regenerating && (
            <div className={styles.regenOverlay} role="status" aria-live="polite">
              <Loader2 size={14} className={styles.regenSpinner} />
              <span className={styles.regenLabel}>Regenerating…</span>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

