    const LAYOUT_MEASURE_DEBOUNCE_MS = 80
    let layoutTimer = 0
    let settleTimer = 0
    let pendingRow: HTMLElement | null = null
    const revealQueue = createMessageRowRevealQueue((row, height) => {
      // This batch runs after commit, when TanStack has written any pending
      // prepend anchor. Rebasing in a child ref would erase that anchor.
      syncNativeScrollOffset(rowVirtualizer)
      rowVirtualizer.resizeItem(Number(row.dataset.virtualIndex), height)
    }, {
      beforeResize() {
        coldDisplayAnchorIndexRef.current = null
        if (isPinnedRef.current) return
        const viewport = el.getBoundingClientRect()
        for (const row of el.querySelectorAll<HTMLElement>('[data-item-type="message"]')) {
          if (row.hasAttribute(MESSAGE_ROW_MEASURING_ATTRIBUTE) || row.querySelector('[data-display-pending]')) continue
          const rect = row.getBoundingClientRect()
          if (rect.bottom <= viewport.top || rect.top >= viewport.bottom) continue
          coldDisplayAnchorIndexRef.current = Number(row.dataset.virtualIndex)
          break
        }
      },
      afterResize() { coldDisplayAnchorIndexRef.current = null },
    })
    // Effect replay or a streaming-state change can replace a queued batch.
    // Adopt its still-mounted rows so an equal-height completion cannot stay
    // hidden waiting for a ResizeObserver notification that will never fire.
    for (const row of el.querySelectorAll<HTMLElement>(`[${MESSAGE_ROW_MEASURING_ATTRIBUTE}]`)) {
      revealQueue.schedule(row)
    }

    const handleMessageContentLayout = (event: Event) => {
      const target = event.target
      pendingRow = target instanceof Element
        ? target.closest<HTMLElement>('[data-virtual-index]')
        : null

      // Finalized messages can re-render after the first bottom landing when
      // display regexes, HTML islands, or widgets finish their async work.
      // Keep the load session alive only if the user is still at the tail.
      if (!isStreaming) extendInitialBottomPin()

      if (pendingRow && shouldPreserveScrollAnchorForLayout(event)) {
        const messageId = pendingRow.dataset.messageId
        if (messageId) {
          programmaticReflowUntilByMessageIdRef.current.set(
            messageId,
            performance.now() + PROGRAMMATIC_CONTENT_REFLOW_SETTLE_MS,
          )
        }
      }

      if (pendingRow && isMessageDisplayReadyLayout(event)) revealQueue.schedule(pendingRow)

      // Debounce the burst of layout events fired during streaming/content
      // changes so we don't re-measure the same row multiple times per frame.
      if (layoutTimer) window.clearTimeout(layoutTimer)
      layoutTimer = window.setTimeout(() => {
        layoutTimer = 0
        const row = pendingRow
        pendingRow = null
        if (row && el.contains(row)) {
          rowVirtualizer.measureElement(row)
        } else {
          measureMountedRows()
        }

        // End anchoring and the iOS content-size observer follow growing rows.
        // recoverTailVoid remains a safety net for drifting measurements.
        if (recoverTailVoid()) return
        if (settleTimer) window.clearTimeout(settleTimer)
        settleTimer = window.setTimeout(() => {
          settleTimer = 0
          recoverTailVoid()
        }, LAYOUT_MEASURE_DEBOUNCE_MS)
      }, LAYOUT_MEASURE_DEBOUNCE_MS)
    }

    el.addEventListener(MESSAGE_CONTENT_LAYOUT_EVENT, handleMessageContentLayout)
    return () => {
      revealQueue.dispose()
      el.removeEventListener(MESSAGE_CONTENT_LAYOUT_EVENT, handleMessageContentLayout)
      if (layoutTimer) window.clearTimeout(layoutTimer)
      if (settleTimer) window.clearTimeout(settleTimer)
    }
  }, [extendInitialBottomPin, isStreaming, measureMountedRows, recoverTailVoid, rowVirtualizer, syncNativeScrollOffset])

  return (
    <div
      data-component="MessageList"
      className={styles.list}
      ref={scrollRef}
      onScroll={handleScroll}
      onWheel={handleWheel}
      onPointerDown={handlePointerDown}
      onTouchStart={handleTouchStart}
      onTouchMove={handleTouchMove}
      onTouchEnd={handleTouchEnd}
      onTouchCancel={handleTouchEnd}
      data-chat-scroll="true"
      data-group-chat={isGroupChat || undefined}
    >
      <span data-spindle-mount="chat_stream_before" data-spindle-scope={`chat:${chatId}:stream-before`} style={{ display: 'contents' }} />
      {isGroupChat && <GroupChatMemberBar chatId={chatId} />}
      {!hasRows && (
        <span data-spindle-mount="chat_empty_state" data-spindle-scope={`chat:${chatId}:empty`} style={{ display: 'contents' }} />
      )}
      <div
        ref={rowVirtualizer.containerRef}
        className={styles.virtualSpace}
      >
        {virtualItems.map((virtualRow) => {
          const item = virtualListItems[virtualRow.index]
          if (!item) return null

          let content: ReactNode = null
          let messageId: string | undefined
          let messageIndex: number | undefined
          let measureKey: string | undefined

          switch (item.type) {
            case 'loadingOlder':
              content = <div className={styles.loadingOlder}>{t('messageList.loadingOlder')}</div>
              break
            case 'message':
              messageId = item.message.id
              messageIndex = item.messageIndex
              measureKey = item.measureKey
              content = (
                <MessageCard
                  message={item.message}
                  chatId={chatId}
                  depth={visibleMessages.length - 1 - item.messageIndex}
                  findQuery={findQuery}
                />
              )
              break
            case 'progressBar':
              content = <GroupChatProgressBar />
              break
            case 'error':
              content = (
                <div className={styles.errorBubble}>
                  <span className={styles.errorLabel}>{t('messageList.generationFailed')}</span> {item.error}
                </div>
              )
              break
            case 'messageFooter':
              content = <div data-spindle-mount="message_footer" />
              break
            case 'bottom':
              content = <div ref={bottomRef} />
              break
          }

          return (
            <VirtualRow
              key={virtualRow.key}
              virtualIndex={virtualRow.index}
              estimatedHeight={virtualRow.size}
              itemType={item.type}
              messageIndex={messageIndex}
              messageId={messageId}
              measureKey={measureKey}
              styleMode={styleMode}
              measureElement={rowVirtualizer.measureElement}
            >
              {content}
            </VirtualRow>
          )
        })}
      </div>
      <span data-spindle-mount="chat_stream_after" data-spindle-scope={`chat:${chatId}:stream-after`} style={{ display: 'contents' }} />
    </div>
  )
}

interface VirtualRowProps {
  virtualIndex: number
  estimatedHeight: number
  itemType: VirtualListItem['type']
  messageIndex?: number
  messageId?: string
  measureKey?: string
  styleMode?: 'bounded' | 'extension-relaxed'
  measureElement: (el: Element | null) => void
  children: ReactNode
}

const VirtualRow = memo(function VirtualRow({ virtualIndex, estimatedHeight, itemType, messageIndex, messageId, measureKey, styleMode, measureElement, children }: VirtualRowProps) {
  const elRef = useRef<HTMLDivElement>(null)

  useLayoutEffect(() => {
    const el = elRef.current
    if (!el) return

    let pendingRaf = 0
    const measure = () => {
      measureElement(el)
    }

    const scheduleMeasure = () => {
      if (pendingRaf) return
      pendingRaf = requestAnimationFrame(() => {
        pendingRaf = 0
        measure()
      })
    }

    // Initial measure during commit, before paint.
    // Rely on TanStack's ResizeObserver (via measureElement) and the
    // MESSAGE_CONTENT_LAYOUT_EVENT dispatched by MessageContent for ongoing
    // size changes. The MutationObserver that was here fired on every token
    // during streaming and caused a measurement storm.
    // A deferred ResizeObserver notification must not expose a new row's
    // header at its estimated position before the body has been measured.
    el.setAttribute(MESSAGE_ROW_MEASURING_ATTRIBUTE, '')
    measure()
    if (el.hasAttribute(MESSAGE_ROW_MEASURING_ATTRIBUTE) && !el.querySelector('[data-display-pending]')) {
      // Cache hits can mount while TanStack skips synchronous scroll-time
      // measurements. Complete those in the same pre-paint batch as async
      // display results, rather than leaving a blank row for an extra frame.
      dispatchMessageContentLayout(el, { displayReady: true })
    }

    el.addEventListener('load', scheduleMeasure, true)
    el.addEventListener('error', scheduleMeasure, true)

    return () => {
      if (pendingRaf) cancelAnimationFrame(pendingRaf)
      el.removeEventListener('load', scheduleMeasure, true)
      el.removeEventListener('error', scheduleMeasure, true)
      measureElement(null)
    }
  }, [measureElement])

  const relaxed = styleMode === 'extension-relaxed'
  return (
    <div
      ref={elRef}
      data-virtual-index={virtualIndex}
      data-item-type={itemType}
      data-index={virtualIndex}
      data-message-index={messageIndex}
      data-message-id={messageId}
      data-measure-key={measureKey}
      data-style-mode={relaxed ? 'extension-relaxed' : undefined}
      className={styles.virtualRow}
      style={{ '--message-row-estimated-height': `${estimatedHeight}px` } as CSSProperties}
    >
      {messageId && (
        <span
          data-spindle-mount="message_context_menu"
          data-spindle-scope={`message:${messageId}:context-menu`}
          style={{ display: 'contents' }}
        />
      )}
      {children}
    </div>
  )
})

