import { Copy, Eye, EyeOff, Trash2, X, CheckSquare, Square } from 'lucide-react'
import { useTranslation } from 'react-i18next'
import { useMessageSelect } from '@/hooks/useMessageSelect'
import { useStore } from '@/store'
import styles from './MessageSelectBar.module.css'
import clsx from 'clsx'

interface MessageSelectBarProps {
  chatId: string
}

export default function MessageSelectBar({ chatId }: MessageSelectBarProps) {
  const { t } = useTranslation('chat')
  const { t: tc } = useTranslation('common')
  const {
    selectedCount,
    totalCount,
    hasHiddenSelected,
    hasVisibleSelected,
    exitSelectMode,
    selectAllMessages,
    clearMessageSelection,
    bulkCopy,
    bulkHide,
    bulkDelete,
  } = useMessageSelect(chatId)

  const openModal = useStore((s) => s.openModal)

  const allSelected = selectedCount === totalCount && totalCount > 0

  const handleDelete = () => {
    openModal('confirm', {
      title: t('messageSelect.deleteTitle'),
      message: t('messageSelect.deleteMessage', { count: selectedCount }),
      variant: 'danger',
      confirmText: tc('actions.delete'),
      onConfirm: bulkDelete,
    })
  }

  return (
    <div
      className={styles.bar}
      data-component="MessageSelectBar"
      role="group"
      aria-label={t('messageSelect.toolbar')}
    >
      <div className={styles.left}>
        <button
          type="button"
          className={styles.selectToggle}
          onClick={allSelected ? clearMessageSelection : selectAllMessages}
          title={allSelected ? t('messageSelect.deselectAll') : t('messageSelect.selectAll')}
          aria-label={allSelected ? t('messageSelect.deselectAll') : t('messageSelect.selectAll')}
          aria-pressed={allSelected}
        >
          {allSelected ? <CheckSquare size={14} /> : <Square size={14} />}
        </button>
        <span className={styles.count} role="status">
          {t('messageSelect.selectedCount', { selected: selectedCount, total: totalCount })}
        </span>
      </div>
      <div className={styles.actions}>
        <button
          type="button"
          className={styles.actionBtn}
          onClick={bulkCopy}
          disabled={selectedCount === 0}
          title={t('messageActions.copy')}
          aria-label={t('messageActions.copy')}
        >
          <Copy size={13} />
          <span className={styles.actionLabel}>{t('messageActions.copy')}</span>
        </button>
        {hasVisibleSelected && (
          <button
            type="button"
            className={clsx(styles.actionBtn, styles.hideBtn)}
            onClick={() => bulkHide(true)}
            disabled={selectedCount === 0}
            aria-label={t('messageActions.hide')}
          >
            <EyeOff size={13} />
            <span className={styles.actionLabel}>{t('messageActions.hide')}</span>
          </button>
        )}
        {hasHiddenSelected && (
          <button
            type="button"
            className={clsx(styles.actionBtn, styles.unhideBtn)}
            onClick={() => bulkHide(false)}
            disabled={selectedCount === 0}
            aria-label={t('messageActions.unhide')}
          >
            <Eye size={13} />
            <span className={styles.actionLabel}>{t('messageActions.unhide')}</span>
          </button>
        )}
        <button
          type="button"
          className={clsx(styles.actionBtn, styles.deleteBtn)}
          onClick={handleDelete}
          disabled={selectedCount === 0}
          aria-label={tc('actions.delete')}
        >
          <Trash2 size={13} />
          <span className={styles.actionLabel}>{tc('actions.delete')}</span>
        </button>
        <button
          type="button"
          className={clsx(styles.actionBtn, styles.cancelBtn)}
          onClick={exitSelectMode}
          aria-label={tc('actions.cancel')}
        >
          <X size={13} />
          <span className={styles.actionLabel}>{tc('actions.cancel')}</span>
        </button>
      </div>
    </div>
  )
}

sources.src/components/chat/MessageSelectCheckbo:
.checkbox {
  flex-shrink: 0;
  width: 16px;
  height: 16px;
  margin: 0;
  cursor: pointer;
  accent-color: var(--lumiverse-primary);
}

.checkbox:focus-visible {
  outline: 2px solid var(--lumiverse-primary);
  outline-offset: 2px;
}

import { useTranslation } from 'react-i18next'
import styles from './MessageSelectCheckbox.module.css'

interface MessageSelectCheckboxProps {
  /** The message's position as the meta pill shows it, so the spoken name and
   *  the visible "#N" agree. */
  index: number
  name: string
  content: string
  checked: boolean
  onToggle?: (e: React.MouseEvent) => void
}

/** Enough of the message to tell two of them apart while tabbing, short enough
 *  that the checked state still arrives quickly. */
const PREVIEW_CHARS = 60

/**
 * The per-message selection control. Select mode used to be a click handler on
 * the message card plus an outline class, which leaves nothing for a screen
 * reader: no focus stop, no role, no checked state. A real checkbox carries all
 * three, and `aria-label` names it after the message it belongs to.
 */
export default function MessageSelectCheckbox({
  index, name, content, checked, onToggle,
}: MessageSelectCheckboxProps) {
  const { t } = useTranslation('chat')

  const preview = content.replace(/\s+/g, ' ').trim().slice(0, PREVIEW_CHARS)
  const label = preview
    ? t('messageSelect.selectMessagePreview', { index, name, preview })
    : t('messageSelect.selectMessage', { index, name })

  return (
    <input
      type="checkbox"
      className={styles.checkbox}
      checked={checked}
      aria-label={label}
      onChange={(event) => {
        // One callback serves both the card's own click and this checkbox: it
        // reads only `shiftKey`, and React routes checkbox onChange through the
        // native click, so range selection still works from here.
        onToggle?.(event.nativeEvent as unknown as React.MouseEvent)
      }}
      // The card toggles selection on click too; without this the click would
      // bubble up and undo what the checkbox just did.
      onClick={(event) => event.stopPropagation()}
    />
  )
}

