/* ── Minimal mode card — glassmorphic ── */
.card {
  --long-message-fade-color: var(--lcs-glass-bg);
  display: flex;
  flex-shrink: 0;
  gap: 10px;
  padding: 12px;
  border-radius: var(--lcs-radius);
  background: var(--lcs-glass-bg);
  border: 1px solid var(--lcs-glass-border);
  backdrop-filter: none;
  position: relative;
  transition:
    background var(--lcs-transition-fast),
    border-color var(--lcs-transition-fast),
    box-shadow var(--lcs-transition-fast);
}

/* Only apply backdrop-filter when glass is enabled AND there's a non-solid background.
   Message rows are virtualized, so mounted cards are already near the viewport;
   keeping this static avoids style/measurement feedback loops while scrolling. */
:global([data-glass][data-chat-bg]) .card {
  backdrop-filter: blur(var(--lcs-glass-blur)) var(--lcs-liquid-filter, );
}

/* Accent bar — positioned via ::before */
.card::before {
  content: '';
  position: absolute;
  top: 8px;
  bottom: 8px;
  width: 3px;
  border-radius: 2px;
  pointer-events: none;
}

/* Character accent — purple, left */
.character::before {
  left: 0;
  background: linear-gradient(180deg, var(--lumiverse-primary-050), var(--lumiverse-primary-020));
  box-shadow: 0 0 8px var(--lumiverse-primary-015);
}

/* User accent — orange, right */
.user::before {
  right: 0;
  background: linear-gradient(180deg, rgba(255, 165, 0, 0.8), rgba(255, 165, 0, 0.4));
  box-shadow: 0 0 8px rgba(255, 165, 0, 0.25);
}

.card:hover {
  background: var(--lumiverse-bg-elevated);
  border-color: var(--lumiverse-border);
}

:global([data-glass]) .card:hover {
  box-shadow: 0 0 16px var(--lumiverse-primary-010);
}

:global([data-theme-mode='light']) .card:hover {
  border-color: var(--lumiverse-fill-subtle);
}

:global([data-glass][data-theme-mode='light']) .card:hover {
  box-shadow: 0 0 12px rgba(0, 0, 0, 0.04);
}

/* Reuse the Bubble-mode opt-out attribute so the shared chat hover/tap
   highlight setting also keeps Minimal rows at their base fill. */
:global([data-no-bubble-hover]) .card:hover {
  background: var(--lcs-glass-bg);
  border-color: var(--lcs-glass-border);
  box-shadow: none;
}

:global([data-glass][data-no-bubble-hover]) .card:hover {
  box-shadow: none;
}

/* Hidden draft message — dimmed, darkened, dashed border */
.hidden {
  opacity: 0.4;
  border-style: dashed;
  border-color: var(--lumiverse-border);
  filter: brightness(0.6) saturate(0.5);
  transition:
    opacity var(--lcs-transition),
    filter var(--lcs-transition),
    background var(--lcs-transition-fast),
    border-color var(--lcs-transition-fast),
    box-shadow var(--lcs-transition-fast);
}

.hidden:hover {
  opacity: 0.65;
  filter: brightness(0.75) saturate(0.7);
}

/* Selection mode */
.selectMode {
  cursor: pointer;
  user-select: none;
}

.selected {
  outline: 2px solid var(--lumiverse-primary);
  outline-offset: -1px;
  opacity: 1 !important;
  filter: none !important;
}

/* Transient navigation highlight — greeting switch, deep-link scroll-to, etc. */
.highlight {
  animation: minimalHighlightPulse 1600ms ease-out forwards;
}

@keyframes minimalHighlightPulse {
  0% {
    outline: 2px solid transparent;
    outline-offset: 2px;
    box-shadow: 0 0 0 0 var(--lumiverse-primary-040, rgba(130, 100, 255, 0.4));
  }
  15% {
    outline: 2px solid var(--lumiverse-primary);
    outline-offset: 2px;
    box-shadow: 0 0 0 6px var(--lumiverse-primary-020, rgba(130, 100, 255, 0.2));
  }
  100% {
    outline: 2px solid transparent;
    outline-offset: 2px;
    box-shadow: 0 0 0 0 transparent;
  }
}

/* Streaming state — GPU optimization */
.streaming {
  will-change: opacity, transform;
  backdrop-filter: none;
}

/* ── Layout ── */
.user {
  flex-direction: row-reverse;
}

.character {
  flex-direction: row;
}

.avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  overflow: hidden;
  flex-shrink: 0;
  border: 1px solid var(--lumiverse-border);
}

.avatarFallback {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: calc(16px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-primary-muted);
  background: var(--lumiverse-primary-010);
}

.bubble {
  flex: 1;
  min-width: 0;
  max-width: 85%;
}

.header {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 4px;
}

.name {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
}

/* ── Meta pill ── */
.metaPill {
  position: relative;
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  max-width: 100%;
  padding: 2px 8px;
  border-radius: 12px;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-family: ui-monospace, 'SF Mono', SFMono-Regular, 'Cascadia Code', Menlo, Consolas, monospace;
  color: var(--lumiverse-text-muted);
  letter-spacing: 0.02em;
  background: var(--lumiverse-fill-deepest);
  border: 1px solid var(--lumiverse-border);
  line-height: 1;
}

/* User metadata sits on the right side of the row. Keep the badge itself as
   one unit; the wrapping header can still move the whole pill below the name
   when horizontal space is tight. */
.user .metaPill {
  flex-shrink: 0;
  flex-wrap: nowrap;
  max-width: none;
  white-space: nowrap;
}

.metaSegment {
  display: inline-flex;
  align-items: center;
  white-space: nowrap;
}

.metaDot {
  margin: 0 4px;
  opacity: 0.35;
}

.hiddenBadge {
  color: rgba(255, 160, 80, 0.9);
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  font-size: calc(8px * var(--lumiverse-font-scale, 1));
}

.metaPillTooltip {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 6px 10px;
  border-radius: 10px;
  background: var(--lumiverse-fill-deepest);
  border: 1px solid var(--lumiverse-border);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.6);
  white-space: nowrap;
  z-index: 9999;
  pointer-events: none;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-family: ui-monospace, 'SF Mono', SFMono-Regular, 'Cascadia Code', Menlo, Consolas, monospace;
  line-height: 1.3;
}

.tooltipRow {
  display: flex;
  justify-content: space-between;
  gap: 12px;
}

.tooltipLabel {
  color: var(--lumiverse-text-muted);
}

.tooltipValue {
  color: var(--lumiverse-text);
  font-variant-numeric: tabular-nums;
}

.nameUser {
  color: rgba(255, 165, 0, 0.85);
}

.nameChar {
  color: var(--lumiverse-primary-text);
}

:global([data-theme-mode='dark']) .nameChar {
  color: var(--char-name-dark, var(--lumiverse-primary-text));
}

:global([data-theme-mode='light']) .nameChar {
  color: var(--char-name-light, var(--lumiverse-primary-text));
}

@media (max-width: 600px) {
  .bubble {
    max-width: 100%;
  }

  .card {
    padding: 10px;
    gap: 8px;
  }
}

@media (max-width: 480px) {
  .card {
    padding: 8px;
    gap: 6px;
  }
}

/* ── Actions wrapper ── */
.actionsWrap {
  flex-shrink: 0;
  align-self: flex-start;
  opacity: 0;
  transition: opacity var(--lumiverse-transition-fast);
}

.card:hover .actionsWrap {
  opacity: 1;
}

/* Touch devices: keep actions visible for deliberate tapping */
@media (hover: none) {
  .actionsWrap {
    opacity: 0.5;
  }
}

/* ── Mobile: pull actions out of flex flow ── */
@media (max-width: 768px) {
  .card {
    padding-top: 38px;
  }

  .bubble {
    max-width: 100%;
  }

  .avatar {
    width: 38px;
    height: 38px;
  }

  .header {
    flex-direction: column;
    align-items: flex-start;
    gap: 4px;
    margin-bottom: 6px;
  }

  .name {
    font-size: calc(13px * var(--lumiverse-font-scale, 1));
  }

  .actionsWrap {
    position: absolute;
    top: 6px;
    right: 6px;
    z-index: 3;
  }

  .user .actionsWrap {
    left: auto;
    right: 52px;
  }
}

@media (max-width: 480px) {
  .card {
    padding-top: 34px;
  }

  .avatar {
    width: 34px;
    height: 34px;
  }

  .name {
    font-size: calc(14px * var(--lumiverse-font-scale, 1));
  }
}

/* The unfolded window is wide, while an individual chat pane is still narrow. */
@container duo-chat (max-width: 768px) {
  .card { padding-top: 38px; }
  .bubble { max-width: 100%; }
  .header {
    flex-direction: column;
    align-items: flex-start;
    gap: 4px;
    margin-bottom: 6px;
  }
  .actionsWrap {
    position: absolute;
    top: 6px;
    right: 6px;
    z-index: 3;
  }
  .user .actionsWrap { left: auto; right: 52px; }
}

@media (hover: none) and (pointer: coarse) {
  .card,
  .hidden {
    transition: none;
  }

  .card,
  .card:hover {
    box-shadow: none;
  }

  :global([data-glass][data-chat-bg]) .card {
    backdrop-filter: none;
  }

  .streaming {
    will-change: auto;
  }
}

/* Preserve backdrop layers across gesture boundaries, including on WebKit. */
:global([data-scrolling]) .card {
  transition: none !important;
}

