  display: inline-flex;
  padding: 4px 11px;
  background: var(--lumiverse-fill-heavy);
  border: 1px solid var(--lumiverse-border);
  border-radius: 20px;
  font-family: ui-monospace, 'SF Mono', SFMono-Regular, 'Cascadia Code', Menlo, Consolas, monospace;
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
  letter-spacing: 0.02em;
  color: var(--lumiverse-text-dim, rgba(255, 255, 255, 0.5));
  line-height: 1;
  transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

.bubble .toggle:hover {
  background: var(--lumiverse-fill-deepest);
  border-color: var(--lumiverse-border);
}

:global([data-theme-mode='light']) .bubble .toggle {
  background: var(--lumiverse-fill-subtle);
  border-color: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text-muted);
}

:global([data-theme-mode='light']) .bubble .toggle:hover {
  background: var(--lumiverse-fill-subtle);
  border-color: var(--lumiverse-fill);
}

.bubble .body {
  margin-top: 10px;
  padding: 10px 14px;
  background: var(--lumiverse-fill-heavy);
  border-radius: 10px;
  border: 1px solid var(--lumiverse-border);
  border-top: 1px solid var(--lumiverse-border);
  font-family: ui-monospace, 'SF Mono', SFMono-Regular, 'Cascadia Code', Menlo, Consolas, monospace;
  font-size: calc(12.5px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim, rgba(255, 255, 255, 0.45));
}

:global([data-theme-mode='light']) .bubble .body {
  background: var(--lumiverse-fill-subtle);
  border-color: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text-muted);
}

@media (max-width: 768px) {
