/* ── Animations ── */

@keyframes loom-weave {
  0%, 100% {
    opacity: 0.6;
    background-position: 0% 50%;
  }
  50% {
    opacity: 1;
    background-position: 100% 50%;
  }
}

@keyframes loom-shimmer {
  0% { left: -100%; }
  100% { left: 150%; }
}

@keyframes pulse-glow {
  0%, 100% { box-shadow: 0 0 15px var(--lumiverse-primary-050); }
  50% { box-shadow: 0 0 25px var(--lumiverse-primary-muted); }
}

/* ═══════════════════════════════════════════════
