  border-radius: 16px;
  border: 1px solid var(--lumiverse-primary-020);
  background: var(--lumiverse-fill-subtle);
  background-size: 200% 200%;
  animation: loom-weave 8s ease-in-out infinite;
  position: relative;
  overflow: hidden;
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}

.socialCard:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 20px var(--lumiverse-primary-015);
}

/* Shimmer overlay */
.socialCard::after {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 50%;
  height: 100%;
  background: linear-gradient(90deg, transparent, var(--lumiverse-primary-010), transparent);
  animation: loom-shimmer 8s ease-in-out infinite;
  pointer-events: none;
}

/* Accent line at top */
.socialCard::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--lumiverse-primary-muted), var(--lumiverse-primary-050), transparent);
