        <div className={styles.whisperHeader}>
          <span className={styles.whisperName}>{displayName} whispers...</span>
        </div>
        <div
          className={styles.whisperText}
          dangerouslySetInnerHTML={{ __html: safeContent }}
        />
      </div>
    </div>
  )
}

