  cursor: pointer;
}

.modelGridButton span {
  min-width: 0;
  overflow-wrap: anywhere;
  white-space: normal;
}

.modelGridButton:hover,
.modelGridButtonActive {
  border-color: var(--lcs-glass-border-hover);
  color: var(--lumiverse-text);
  background: color-mix(in srgb, var(--lcs-glass-bg) 70%, var(--lumiverse-fill-hover) 30%);
}

.modelTile:hover,
.modelButtonActive {
  border-color: var(--lcs-glass-border-hover);
  color: var(--lumiverse-text);
  background: color-mix(in srgb, var(--lcs-glass-bg) 70%, var(--lumiverse-fill-hover) 30%);
}

.panelFooter {
  min-height: 36px;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 12px;
  padding-top: 8px;
  border-top: 1px solid var(--lcs-glass-border);
  color: var(--lumiverse-text-dim);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
}

.panelFooter button {
  min-width: 0;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border: 0;
  background: transparent;
  color: var(--lumiverse-text-muted);
  cursor: pointer;
}

.panelFooter button:first-child {
  justify-self: start;
}

.panelFooter button:last-child {
  justify-self: end;
}

.panelFooter button:hover {
  color: var(--lumiverse-text);
}

.panelFooter span {
  white-space: nowrap;
}

.empty {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 52px;
  color: var(--lumiverse-text-dim);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
}

.spinner {
  animation: pickerSpin 0.8s linear infinite;
}

.columnResizer {
  align-self: stretch;
  width: 8px;
  min-height: 0;
  border-radius: 999px;
  cursor: ew-resize;
  touch-action: none;
}

.columnResizer:hover {
  background: var(--lumiverse-fill-hover);
  box-shadow: inset 0 0 0 1px var(--lcs-glass-border-hover);
}

@keyframes pickerSpin {
  to { transform: rotate(360deg); }
}

@media (max-width: 720px) {
  .frame {
    max-width: calc(100vw - 16px);
  }
}

@container (max-width: 760px) {
  .splitBody,
  .fullBody {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: minmax(180px, 1fr) minmax(180px, 1fr);
    row-gap: var(--connections-section-gap);
  }

  .fullBody {
    grid-template-rows: minmax(150px, auto) minmax(180px, 1fr) minmax(180px, 1fr);
  }

  .columnResizer {
    display: none;
  }

  .panelFooter {
    grid-template-columns: 1fr auto;
  }

  .panelFooter span {
    display: none;
  }
}

@container (max-width: 460px) {
  .modelsGrid {
    grid-template-columns: minmax(0, 1fr);
  }

  .panelFooter {
    display: flex;
    justify-content: space-between;
  }
}

