/*
 * Every `--lumiverse-*` read in this file is bare on purpose.
 *
 * This stylesheet used to read five custom properties that were defined nowhere
 * (`--lumiverse-border-subtle`, `--lumiverse-surface`, `--lumiverse-surface-raised`,
 * `--lumiverse-input-bg`, `--lumiverse-primary-soft`), each with a hard-coded Tailwind
 * slate fallback. The token never resolved, the fallback always won, and the theme engine
 * could not touch a pixel of the homepage — which is why it looked like a different
 * product from the rest of the app. The tokens are real now, so the fallbacks are gone.
 * Do not reintroduce them: a fallback here silently re-disconnects this surface.
 *
 * Same rule for radii. `theme/engine.ts` recomputes `--lumiverse-radius-*` from the user's
 * radius-scale setting, so a literal `border-radius: 10px` opts out of that setting.
 */

.library {
  display: grid;
  gap: 12px;
  position: relative;
  left: 50%;
  width: calc((100vw / var(--lumiverse-ui-scale, 1)) - 48px);
  max-width: none;
  transform: translateX(-50%);
  margin-bottom: 18px;
  padding: 14px;
  border: 1px solid var(--lumiverse-border-subtle);
  border-radius: var(--lumiverse-radius-lg);
  background: color-mix(in srgb, var(--lumiverse-surface) 88%, transparent);
}

.header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.header h2,
.preview h3 {
  margin: 0;
  color: var(--lumiverse-text);
}

.header p,
.preview p {
  margin: 4px 0 0;
  color: var(--lumiverse-text-muted);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
}

/* Matches the search-field idiom used by the lorebook toolbar and workspace. */
.searchField {
  display: inline-flex;
  align-items: center;
  flex: 0 1 auto;
  margin-left: auto;
  gap: 7px;
  width: min(280px, 45vw);
  border: 1px solid var(--lumiverse-border);
  border-radius: var(--lumiverse-radius-md);
  background: var(--lumiverse-input-bg);
  color: var(--lumiverse-text-muted);
  padding: 0 11px;
}

.searchField:focus-within {
  border-color: var(--lumiverse-primary-muted);
}

.search {
  flex: 1 1 auto;
  min-width: 0;
  border: 0;
  background: transparent;
  color: var(--lumiverse-text);
  padding: 9px 0;
  font-family: inherit;
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
}

.search:focus {
  outline: none;
}

/* Chrome comes from the shared `Button`; this only holds layout. */
.settingsBtn {
  flex: 0 0 auto;
}

.filters {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.filter,
.filterActive {
  border: 1px solid var(--lumiverse-border-subtle);
  border-radius: 999px;
  background: transparent;
  color: var(--lumiverse-text-muted);
  padding: 7px 10px;
  cursor: pointer;
}

.filterActive {
  background: var(--lumiverse-primary-soft);
  color: var(--lumiverse-text);
}

.filter:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}

.select {
  border: 1px solid var(--lumiverse-border-subtle);
  border-radius: var(--lumiverse-radius-md);
  background: var(--lumiverse-input-bg);
  color: var(--lumiverse-text);
  padding: 7px 9px;
}

.state {
  color: var(--lumiverse-text-muted);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
}

.body {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 16px;
  align-items: start;
  max-width: 100%;
  overflow: hidden;
}

.body[data-panel-open='true'] {
  grid-template-columns: minmax(0, 1fr) minmax(
    0,
    min(
      var(--homepage-preview-layout-width, var(--homepage-panel-width, 420px)),
      calc((100vw / var(--lumiverse-ui-scale, 1)) - 48px)
    )
  );
}

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, var(--character-card-width, 170px)), 1fr));
  gap: var(--character-grid-gap, 10px);
  min-width: 0;
}

.grid[data-view-mode='single'],
.grid[data-view-mode='list'] {
  grid-template-columns: minmax(0, 1fr);
}

.grid[data-view-mode='single'] .card,
.grid[data-view-mode='single'] .cardSelected {
  max-width: var(--character-card-width, 170px);
}

.grid[data-view-mode='list'] .card,
.grid[data-view-mode='list'] .cardSelected {
  flex-direction: row;
  align-items: stretch;
  min-height: 76px;
}

.grid[data-view-mode='list'] .imageFrame {
  flex: 0 0 76px;
  width: 76px;
  height: 76px;
  min-height: 76px;
}

.grid[data-view-mode='list'] .cardFooter,
.grid[data-view-mode='list'] .card[data-footer-mode='compact'] .cardFooter,
.grid[data-view-mode='list'] .cardSelected[data-footer-mode='compact'] .cardFooter {
  position: static;
  inset: auto;
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  max-height: none;
  padding: 8px 10px;
  overflow: visible;
  border: 0;
  border-left: 1px solid var(--lumiverse-border-subtle);
}

.grid > .state {
  grid-column: 1 / -1;
  min-width: 0;
}

/*
 * Infinite-scroll furniture. Both span the full grid row (`1 / -1`) so they never get
 * mistaken for a card slot and squeezed into the auto-fill track.
 */
.loadingMore {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 0;
  color: var(--lumiverse-text-muted);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
}

/*
 * Zero-height trip wire. The IntersectionObserver uses a 400px rootMargin, so this is
 * detected well before it scrolls into view; giving it height would only add dead space.
 */
.sentinel {
  grid-column: 1 / -1;
  height: 1px;
  pointer-events: none;
}

.card,
.cardSelected {
  position: relative;
  display: flex;
  flex-direction: column;
  text-align: left;
  border: 1px solid var(--lumiverse-border-subtle);
  border-radius: var(--lumiverse-radius-md);
  background: var(--lumiverse-card-bg);
  color: inherit;
  padding: 0;
  overflow: hidden;
  cursor: pointer;
  min-width: 0;
  transition:
    border-color var(--lumiverse-transition-fast),
    transform var(--lumiverse-transition-fast),
    box-shadow var(--lumiverse-transition-fast);
}

.card:hover,
.card:focus-visible,
.cardSelected {
  border-color: var(--lumiverse-primary);
  box-shadow: 0 14px 34px color-mix(in srgb, var(--lumiverse-primary) 18%, transparent);
  transform: translateY(-1px);
}

.card:disabled,
.cardSelected:disabled {
  cursor: progress;
  opacity: 0.82;
}

.imageFrame {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  height: var(--character-image-height, 226px);
  min-height: var(--character-image-height, 226px);
  overflow: hidden;
  background: var(--lumiverse-card-image-bg);
}

.card img,
.cardSelected img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--lumiverse-transition-fast);
}

.card:hover img,
.cardSelected:hover img {
  transform: scale(1.025);
}

.cardFooter {
  display: grid;
  align-content: start;
  gap: 4px;
  min-height: 72px;
  padding: 9px 10px 10px;
  border-top: 1px solid var(--lumiverse-border-subtle);
}

.card[data-footer-mode='compact'] .cardFooter,
.cardSelected[data-footer-mode='compact'] .cardFooter {
  position: absolute;
  inset: auto 8px 8px;
  z-index: 1;
  min-height: 0;
  /* The JS-supplied budget is in unscaled px; the text inside it grows with the user's
     font-size setting, so the budget has to grow with it or the tags clip. */
  max-height: calc(var(--character-footer-max-height, 68px) * var(--lumiverse-font-scale, 1));
  gap: 5px;
  padding: 0;
  overflow: hidden;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
}

.card[data-footer-mode='compact'][data-name-background='true'] .cardName,
.cardSelected[data-footer-mode='compact'][data-name-background='true'] .cardName {
  justify-self: start;
  max-width: 100%;
  padding: 2px 7px 3px;
  border-radius: var(--lumiverse-radius-sm);
  background: var(--lumiverse-scene-text-scrim);
  box-shadow: 0 1px 8px rgba(0, 0, 0, 0.45);
}

.card[data-footer-mode='spacious'] .cardFooter,
.cardSelected[data-footer-mode='spacious'] .cardFooter {
  min-height: 92px;
  gap: 6px;
}

.cardName {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 700;
  color: var(--lumiverse-text);
  line-height: 1.15;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.9), 0 0 10px rgba(0, 0, 0, 0.65);
}

.cardMeta {
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--lumiverse-text-muted);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
}

.cardDescription {
  display: -webkit-box;
  overflow: hidden;
  color: var(--lumiverse-text-muted);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  line-height: 1.3;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.tags {
  display: flex;
  flex-wrap: wrap;
  align-content: flex-start;
  width: 100%;
  min-width: 0;
  max-width: 100%;
  gap: 4px;
  overflow: hidden;
  max-height: calc(var(--character-tags-max-height, 20px) * var(--lumiverse-font-scale, 1));
  margin-top: 1px;
  box-sizing: border-box;
}

.tag,
.tagOverflow {
  flex: 0 0 auto;
  height: calc(20px * var(--lumiverse-font-scale, 1));
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  border: 1px solid;
  border-radius: var(--lumiverse-radius-sm);
  padding: 2px 6px;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  line-height: calc(14px * var(--lumiverse-font-scale, 1));
  box-sizing: border-box;
}

/*
 * `--tag-rgb` is an inline `var(--lumiverse-tag-N)` reference set by the component — a raw
 * `R, G, B` triple, never a painted colour. Keeping the paint here (rather than as an
 * inline `background`) is what lets a Custom-CSS override actually win.
 */
.tag {
  border-color: rgba(var(--tag-rgb), 0.3);
  background: rgba(var(--tag-rgb), 0.15);
  color: color-mix(in srgb, rgb(var(--tag-rgb)) 70%, var(--lumiverse-text));
}

.card[data-footer-mode='compact'] .tag,
.card[data-footer-mode='compact'] .tagOverflow,
.cardSelected[data-footer-mode='compact'] .tag,
.cardSelected[data-footer-mode='compact'] .tagOverflow {
  font-weight: 700;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.75);
  filter: saturate(1.2) brightness(1.08);
  box-shadow:
    var(--lumiverse-highlight-inset),
    0 1px 5px rgba(0, 0, 0, 0.35);
}

/* Over artwork the chips need to read as solid, so alpha climbs from 0.15/0.3 to 0.72/0.9. */
.card[data-footer-mode='compact'] .tag,
.cardSelected[data-footer-mode='compact'] .tag {
  border-color: rgba(var(--tag-rgb), 0.9);
  background: rgba(var(--tag-rgb), 0.72);
  color: var(--lumiverse-text);
}

.tagOverflow {
  flex: 0 0 auto;
  border-color: var(--lumiverse-border-subtle);
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text-muted);
}

.preview {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
  gap: 6px;
  min-width: 0;
  max-width: 100%;
  border: 1px solid var(--lumiverse-border-subtle);
  border-radius: var(--lumiverse-radius-lg);
  background:
    radial-gradient(circle at 50% -10%, color-mix(in srgb, var(--lumiverse-primary) 13%, transparent), transparent 42%),
    var(--lumiverse-surface-raised);
  padding: 10px 10px 62px;
  box-shadow: var(--lumiverse-shadow-xl);
  overflow: hidden;
}

.previewBody {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  align-content: start;
  gap: 6px;
  min-width: 0;
  min-height: 0;
  max-width: 100%;
  overflow-x: hidden;
  overflow-y: auto;
}

.previewMetadata {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  align-content: start;
  gap: 6px;
  min-width: 0;
}

.preview[data-pinned='true'] {
  position: fixed;
  top: 108px;
  right: 24px;
  bottom: auto;
  /* Stacking ladder (theme/variables.css): this is a page-level pinned panel, so it must
     clear the chat docks but stay under ViewportDrawer (9992) and every modal above it. */
  z-index: var(--z-homepage-preview-panel, 9990);
  width: min(
    var(--homepage-preview-auto-width, var(--homepage-panel-width, 420px)),
    calc((100vw / var(--lumiverse-ui-scale, 1)) - 48px)
  );
  max-height: calc(100dvh - 126px);
}

.preview[data-pinned='false'] {
  position: relative;
  top: auto;
}

.resizeHandle {
  position: absolute;
  inset: 0 auto 0 -7px;
  width: 14px;
  cursor: ew-resize;
  touch-action: none;
}

.previewControls {
  display: flex;
  justify-content: flex-end;
  gap: 6px;
}

/*
 * Deliberately not the shared `Button`: `Button size="icon-sm"` pins 28px, which would keep
 * these below the touch-target bump `variables.css` applies at ≤600px. The token does grow.
 */
.previewControls button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--lumiverse-btn-icon-sm);
  height: var(--lumiverse-btn-icon-sm);
  border: 1px solid var(--lumiverse-border-subtle);
  border-radius: var(--lumiverse-radius);
  background: transparent;
  color: var(--lumiverse-text-muted);
  cursor: pointer;
}

.previewControls button:focus-visible {
  outline: 2px solid var(--lumiverse-primary);
  outline-offset: 2px;
}

.previewImageFrame {
  position: relative;
  display: block;
  width: min(100%, var(--homepage-preview-image-width, 100%));
  margin-inline: auto;
  min-width: 0;
  max-width: 100%;
  height: auto;
  overflow: hidden;
  isolation: isolate;
  background: var(--lumiverse-card-image-bg);
  border-radius: var(--lumiverse-radius-md);
}

.previewImageFrame::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 1;
  background: var(--lumiverse-fill-hover);
  pointer-events: none;
}

.previewImageFrame > img {
  position: relative;
  display: block;
  width: 100% !important;
  height: auto !important;
  min-width: 0 !important;
  min-height: 0 !important;
  max-width: 100% !important;
  max-height: 100% !important;
  transform: none !important;
  z-index: 2;
}

.imageHeightControl {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  min-width: 0;
  max-width: 100%;
  color: var(--lumiverse-text-muted);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-variant-numeric: tabular-nums;
}

.imageHeightControl input {
  width: 100%;
  min-width: 0;
  max-width: 100%;
}

.previewHeader {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 10px;
}

.previewHeader > div {
  min-width: 0;
}

.previewHeader h3,
.previewHeader p {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Chrome comes from the shared `Button`; this only holds layout. */
.editBtn {
  align-self: start;
}

.previewTags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

/*
 * One rule, not two. `.previewTags span` used to be declared here and again ~300 lines
 * further down, so editing either half missed the other.
 */
.previewTags span {
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
  gap: 4px;
  height: 24px;
  max-width: 100%;
  overflow: hidden;
  border: 1px solid var(--lumiverse-border-subtle);
  border-radius: 999px;
  padding: 4px 8px;
  box-sizing: border-box;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--lumiverse-text-muted);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
}

.previewTags .previewTag {
  border-color: rgba(var(--tag-rgb), 0.3);
  background: rgba(var(--tag-rgb), 0.15);
  color: color-mix(in srgb, rgb(var(--tag-rgb)) 70%, var(--lumiverse-text));
}

.previewSection {
  display: grid;
  gap: 7px;
  min-width: 0;
  max-width: 100%;
}

.previewSection h4 {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  color: var(--lumiverse-text);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
}

.previewSection p {
  margin: 0;
}

.previewSection > *,
.lastChat > * {
  min-width: 0;
  max-width: 100%;
}

.lorebooks {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  min-width: 0;
  max-width: 100%;
  max-height: 28px;
  overflow: hidden;
}

.lorebooks button,
.lastChat {
  border: 1px solid var(--lumiverse-border-subtle);
  border-radius: var(--lumiverse-radius);
  padding: 7px 9px;
  color: var(--lumiverse-text-muted);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
}

.lorebooks button {
  min-width: 0;
  max-width: 100%;
  background: var(--lumiverse-fill-subtle);
  cursor: pointer;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.lorebooks button:hover {
  color: var(--lumiverse-text);
  border-color: var(--lumiverse-border);
}

.lastChat {
  display: grid;
  gap: 4px;
  min-width: 0;
  max-width: 100%;
  min-height: 0;
  max-height: 68px;
  overflow: hidden;
}

.lastChat strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--lumiverse-text);
}

.lastChat p {
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

/* Chrome comes from the shared `Button`; this only holds placement. */
.openChatBtn {
  position: absolute;
  inset: auto 12px 12px;
  z-index: 4;
  width: auto;
}

@media (max-width: 760px) {
  .header {
    grid-template-columns: 1fr;
  }

  .body {
    grid-template-columns: 1fr;
    width: 100%;
    min-width: 0;
    overflow: hidden;
  }

  .body[data-panel-open='true'] {
    grid-template-columns: minmax(0, 1fr);
  }

  .header {
    display: grid;
  }

  .searchField {
    width: 100%;
  }

  .settingsBtn {
    width: 100%;
  }

  .library {
    grid-template-columns: minmax(0, 1fr);
    padding: 12px;
    left: auto;
    width: 100%;
    min-width: 0;
    max-width: 100%;
    transform: none;
  }

  .grid[data-view-mode='grid'] {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: var(--character-grid-gap, 10px);
  }

  .grid[data-view-mode='single'] .card,
  .grid[data-view-mode='single'] .cardSelected {
    max-width: none;
  }

  .previewControls {
    position: relative;
    top: auto;
    z-index: 10;
  }

  .previewControls button {
    min-width: 44px;
    min-height: 44px;
  }

  .preview[data-pinned] {
    position: fixed;
    inset-block-start: calc(64px + env(safe-area-inset-top));
    inset-block-end: auto;
    left: 50%;
    right: auto;
    z-index: var(--z-homepage-preview-panel, 9990);
    width: min(
      var(--homepage-preview-auto-width, var(--homepage-panel-width, 420px)),
      calc((100vw / var(--lumiverse-ui-scale, 1)) - 24px)
    );
    max-width: calc((100vw / var(--lumiverse-ui-scale, 1)) - 24px);
    max-height: calc(100dvh - 76px - env(safe-area-inset-top) - env(safe-area-inset-bottom));
    transform: translateX(-50%);
    background-color: var(--lumiverse-bg-deep, #0a0812);
    overflow: hidden;
    isolation: isolate;
  }

  .previewBackdrop {
    position: absolute;
    inset: 0;
    z-index: 0;
    overflow: hidden;
    border-radius: inherit;
    pointer-events: none;
  }

  .previewBackdropGlow {
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
  }

  .previewBackdropViewportLayer {
    position: absolute;
    pointer-events: none;
  }

  .preview[data-pinned]::after {
    content: '';
    position: absolute;
    inset: 0;
    z-index: 1;
    border-radius: inherit;
    pointer-events: none;
    background-image: var(--homepage-preview-grid-image, none);
    background-position: var(--homepage-preview-grid-position, 0 0);
    background-size: var(--homepage-preview-grid-size, auto);
    background-repeat: var(--homepage-preview-grid-repeat, repeat);
    opacity: var(--homepage-preview-grid-opacity, 0);
  }

  .previewBody {
    position: relative;
    z-index: 2;
  }

  .resizeHandle {
    display: none;
  }

  .grid[data-view-mode='grid'] .imageFrame,
  .grid[data-view-mode='single'] .imageFrame {
    height: min(var(--character-image-height, 226px), 62vw);
    min-height: min(var(--character-image-height, 226px), 62vw);
  }
}

.previewDescription {
  display: -webkit-box;
  overflow: hidden;
  color: var(--lumiverse-text-muted);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  line-height: 1.4;
  white-space: pre-wrap;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 4;
}

