import { useEffect, useRef, useState } from 'react'
import { getTauriMobilePlatform, isMacTauriWebView, isTauriDesktop } from '@/lib/desktopWebView'
import { useIOSMediaImage } from '@/hooks/useIOSMediaImage'
import { useImageDecodeReveal } from '@/hooks/useImageDecodeReveal'

interface HomepageLibraryCardImageProps {
  src: string
  alt: string
}

/**
 * Keep the unvirtualized library memory-bounded by withholding image requests
 * until their cards approach the viewport in every Tauri shell. macOS adds a
 * mounted synchronous-decode and paint guard for WKWebView; Windows and Linux
 * retain asynchronous decoding. This avoids materializing all 60 card bitmaps
 * and compositor copies at once.
 */
export default function HomepageLibraryCardImage({ src, alt }: HomepageLibraryCardImageProps) {
  const tauriDesktop = isTauriDesktop()
  const requiresMountedDecode = isMacTauriWebView()
  const [shouldRequest, setShouldRequest] = useState(() => !tauriDesktop)
  const imageRef = useRef<HTMLImageElement>(null)
  const nativeImage = useIOSMediaImage(shouldRequest ? src : null, imageRef, tauriDesktop ? 'eager' : 'lazy')
  const presentation = useImageDecodeReveal(nativeImage.src, imageRef)
  const fade = getTauriMobilePlatform() !== 'android'

  useEffect(() => {
    if (!tauriDesktop || shouldRequest) return
    const image = imageRef.current
    if (!image || typeof IntersectionObserver === 'undefined') {
      setShouldRequest(true)
      return
    }

    const observer = new IntersectionObserver(([entry]) => {
      if (!entry.isIntersecting) return
      setShouldRequest(true)
      observer.disconnect()
    }, { rootMargin: '320px 0px' })
    observer.observe(image)
    return () => observer.disconnect()
  }, [shouldRequest, tauriDesktop])

  const hidden = tauriDesktop && (
    !shouldRequest || (requiresMountedDecode && !presentation.ready)
  )

  return (
    <img
      ref={imageRef}
      src={nativeImage.src}
      alt={alt}
      loading={tauriDesktop ? 'eager' : 'lazy'}
      decoding={requiresMountedDecode ? 'sync' : tauriDesktop ? 'async' : undefined}
      data-image-decoded={fade ? presentation.ready : undefined}
      onLoad={event => { if (fade) presentation.reveal(event.currentTarget) }}
      onError={() => { presentation.cancel(); nativeImage.retryOriginal() }}
      style={{ visibility: hidden ? 'hidden' : 'visible', ...(fade ? {
        opacity: presentation.ready ? 1 : 0,
        transition: 'opacity 0.2s ease, transform var(--lazy-image-transform-transition, 0ms)',
      } : {}) }}
    />
  )
}

sources.src/components/landing/LandingPage.modul:
.page {
  display: flex;
  flex-direction: column;
  height: 100%;
}

.container {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
  background: transparent;
}

.container::-webkit-scrollbar {
  width: 6px;
}

.container::-webkit-scrollbar-track {
  background: transparent;
}

.container::-webkit-scrollbar-thumb {
  background: var(--lcs-scrollbar-thumb, rgba(255, 255, 255, 0.15));
  border-radius: 3px;
}

.container::-webkit-scrollbar-thumb:hover {
  background: var(--lcs-scrollbar-thumb-hover, rgba(255, 255, 255, 0.25));
}

/* Ambient background */
.bg {
  position: fixed;
  inset: 0;
  height: var(--app-scaled-viewport-height, calc(100vh / var(--lumiverse-ui-scale, 1)));
  width: var(--app-scaled-viewport-width, calc(100vw / var(--lumiverse-ui-scale, 1)));
  z-index: 1;
  pointer-events: none;
  overflow: hidden;
}

/* Static glows — no animation. Three animated compositor layers with large
   radial gradients were consuming ~50% GPU on high-DPI displays even with
   transform-only keyframes. Static placement is visually equivalent. */
.bgGlow {
  position: absolute;
  border-radius: 50%;
  pointer-events: none;
  background: radial-gradient(circle at center, var(--lumiverse-primary-015) 0%, var(--lumiverse-primary-010) 45%, transparent 72%);
}

.bgGlow1 {
  width: 600px;
  height: 600px;
  top: -200px;
  left: -100px;
  opacity: 0.22;
}

.bgGlow2 {
  width: 500px;
  height: 500px;
  bottom: -150px;
  right: -100px;
  opacity: 0.2;
}

.bgGlow3 {
  width: 400px;
  height: 400px;
  left: calc(50% - 200px);
  top: 40%;
  opacity: 0.16;
}

/* Grid pattern — uses opacity instead of mask-image. A full-viewport
   mask-image forces the compositor to maintain a large alpha texture
   on every frame. A static low-opacity grid is nearly free. */
.grid {
  position: fixed;
  inset: 0;
  height: var(--app-scaled-viewport-height, calc(100vh / var(--lumiverse-ui-scale, 1)));
  width: var(--app-scaled-viewport-width, calc(100vw / var(--lumiverse-ui-scale, 1)));
  z-index: 1;
  pointer-events: none;
  background-image:
    linear-gradient(var(--lumiverse-primary-010) 1px, transparent 1px),
    linear-gradient(90deg, var(--lumiverse-primary-010) 1px, transparent 1px);
  background-size: 60px 60px;
  opacity: 0.4;
}

/* Let the desktop backdrop be the visual texture in translucent mode. */
:global(html[data-tauri-desktop][data-desktop-background]) .grid {
  display: none;
}

/* Content */
.content {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  min-height: 100%;
  padding: 24px 32px;
  max-width: 1400px;
  margin: 0 auto;
  width: 100%;
  box-sizing: border-box;
}

/* Default to a readable desktop measure. The user can opt into the expanded
   gallery from the chats toolbar when they want to use a wide display. */
.contentExpanded {
  max-width: none;
}

/* Header */
.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 0 12px;
  margin-bottom: 16px;
}

.landingToolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 20px;
}

.landingTabs {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex: 0 0 auto;
}

.landingTabLabel {
  white-space: nowrap;
}

.landingSearch {
  /* Allow the search field to yield space to the fixed-width toolbar actions
     at high UI scales and narrow viewports. Without this, its intrinsic
     minimum width can push the hidden-items button off screen. */
  flex: 1 1 0;
  min-width: 0;
}

.hiddenManagerBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--lumiverse-btn-icon, 34px);
  height: var(--lumiverse-btn-icon, 34px);
  flex: 0 0 auto;
  padding: 0;
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text-dim);
  cursor: pointer;
  transition: color var(--lumiverse-transition-fast), background var(--lumiverse-transition-fast), border-color var(--lumiverse-transition-fast);
}

.hiddenManagerBtn:hover,
.hiddenManagerBtn:focus-visible {
  color: var(--lumiverse-primary);
  border-color: var(--lumiverse-primary-050);
  background: var(--lumiverse-primary-010);
  outline: none;
}

.galleryWidthBtnActive {
  color: var(--lumiverse-primary);
  border-color: var(--lumiverse-primary-050);
  background: var(--lumiverse-primary-010);
}

.logo {
  display: flex;
  align-items: center;
  gap: 14px;
}

.headerActions {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.tempChatWrap {
  position: relative;
}

.tempChatMenu {
  position: absolute;
  top: calc(100% + 6px);
  right: 0;
  z-index: 30;
  min-width: 220px;
  padding: 4px;
  border-radius: 12px;
  background: var(--lumiverse-bg-elevated, var(--lumiverse-bg));
  border: 1px solid var(--lumiverse-border);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35);
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.tempChatMenuItem {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  padding: 8px 10px;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: var(--lumiverse-text);
  text-align: left;
  cursor: pointer;
  transition: background var(--lumiverse-transition-fast);
}

.tempChatMenuItem:hover {
  background: var(--lumiverse-primary-015);
}

.tempChatMenuLabel {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
}

.tempChatMenuHint {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 240px;
}

.accountBtn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 7px 12px;
  border-radius: 999px;
  background: var(--lumiverse-primary-010);
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text-muted);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  letter-spacing: 0.01em;
  cursor: pointer;
  transition:
    color var(--lumiverse-transition-fast),
    border-color var(--lumiverse-transition-fast),
    background var(--lumiverse-transition-fast);
}

.accountBtn svg {
  opacity: 0.7;
  transition: opacity var(--lumiverse-transition-fast), color var(--lumiverse-transition-fast);
}

.accountBtn:hover {
  color: var(--lumiverse-text);
  border-color: var(--lumiverse-primary-050);
  background: var(--lumiverse-primary-015);
}

.accountBtn:disabled {
  opacity: 0.5;
  cursor: default;
  pointer-events: none;
}

.accountBtn:hover svg {
  opacity: 1;
  color: var(--lumiverse-primary);
}

.accountName {
  max-width: 180px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

@media (max-width: 600px) {
  .accountName {
    display: none;
  }
  .accountBtn {
    padding: 7px 9px;
  }
}

.logoIcon {
  position: relative;
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 14px;
  background: var(--lumiverse-primary-010);
  border: 1px solid var(--lumiverse-primary-020);
}

.logoGlow {
  position: absolute;
  inset: -6px;
  border-radius: 18px;
  background: radial-gradient(circle, var(--lumiverse-primary-020) 0%, transparent 70%);
  opacity: 0.6;
  pointer-events: none;
}

.logoText h1 {
  font-size: calc(24px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  color: var(--lumiverse-text);
  letter-spacing: -0.02em;
}

.taglineBtn {
  display: inline-flex;
  align-items: center;
  gap: 0;
  background: none;
  border: none;
  padding: 0;
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
  cursor: pointer;
  transition: color 0.2s ease;
}

.taglineBtn svg {
  opacity: 0;
  transform: translateX(-4px);
  transition: opacity 0.2s ease, transform 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

.taglineBtn:hover {
  color: var(--lumiverse-primary);
  gap: 6px;
}

.taglineBtn:hover svg {
  opacity: 1;
  transform: translateX(0);
}

/* Main */
.main {
  flex: 1;
}

/* Grid */
.gridCards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 20px;
}

.compactList {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 320px), 1fr));
  gap: 12px;
  align-items: start;
}

.virtualChats {
  position: relative;
  width: 100%;
}

.virtualRow {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  box-sizing: border-box;
}

.routeLeaving {
  pointer-events: none;
  /* One temporary compositor layer for the whole landing surface keeps the
     header, toolbar, search controls, and cards in the same route transition. */
  will-change: transform, opacity;
  backface-visibility: hidden;
  transform-origin: 50% 50%;
}

.routeEntering {
  /* Removed by onAnimationComplete so the full landing surface does not keep
     a large GPU layer allocated while idle. */
  will-change: transform, opacity;
  backface-visibility: hidden;
  transform-origin: 50% 50%;
}

/* Card tilt wrapper — handles 3D tilt separately from framer-motion entry */
.cardTilt {
  perspective: 800px;
  transform-style: preserve-3d;
  transition: transform 400ms cubic-bezier(0.22, 1, 0.36, 1);
}

.cardTilt:hover {
  z-index: 10;
  will-change: transform;
}

.cardTilt.tilting {
  transition: transform 100ms ease-out;
  transform:
    rotateX(calc(var(--pointer-y, 0) * -9deg))
    rotateY(calc(var(--pointer-x, 0) * 9deg))
    scale3d(1.04, 1.04, 1.04);
}

.cardTilt.mobileMotionTilting {
  transition: transform 180ms ease-out;
  transform:
    rotateX(calc(var(--pointer-y, 0) * -4deg))
    rotateY(calc(var(--pointer-x, 0) * 4deg))
    scale3d(1.015, 1.015, 1.015);
}

/* Card — uses CSS animation for entry (no lingering inline styles that
   would promote every card to its own compositor layer). */
.card {
  position: relative;
  transform-style: preserve-3d;
  border-radius: 16px;
  overflow: hidden;
  background: var(--lumiverse-card-bg);
  border: 1px solid var(--lumiverse-border);
  box-shadow: var(--lumiverse-shadow-sm);
  transition:
    box-shadow 300ms cubic-bezier(0.22, 1, 0.36, 1),
    border-color 200ms ease;
}

.cardEntry {
  animation: cardEntry 0.35s cubic-bezier(0.22, 1, 0.36, 1) both;
}

@keyframes cardEntry {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
}

.card:hover {
  border-color: var(--lumiverse-primary-020);
  box-shadow:
    0 14px 28px rgba(0, 0, 0, 0.35),
    0 4px 10px rgba(0, 0, 0, 0.2),
    0 0 24px var(--lumiverse-primary-010);
}

/* Mouse-tracking radial shine. The gradient itself never changes, so the
   browser rasterizes it once; pointer movement only composites this oversized
   texture with translate3d rather than repainting a gradient every frame. */
.cardShine {
  position: absolute;
  inset: -25%;
  z-index: 3;
  pointer-events: none;
  opacity: 0;
  background: radial-gradient(
    circle at 50% 50%,
    rgba(255, 255, 255, 0.10) 0%,
    rgba(255, 255, 255, 0.03) 23%,
    transparent 40%
  );
  transform: translate3d(
    calc(var(--pointer-x, 0) * 33.333%),
    calc(var(--pointer-y, 0) * 33.333%),
    0
  );
  transition: opacity 300ms ease;
}

.card:hover .cardShine {
  opacity: 1;
}

.cardTilt.tilting .cardShine,
.cardTilt.mobileMotionTilting .cardShine {
  will-change: transform, opacity;
  backface-visibility: hidden;
}

/* Image zoom on card hover */
.cardImage img,
.cardImage picture img,
.listAvatar img,
.listAvatar picture img,
.mosaicCell img,
.mosaicCell picture img {
  --lazy-image-transform-transition: 500ms cubic-bezier(0.22, 1, 0.36, 1);
}

.card:hover .cardImage img:not(.perspectiveLayer),
.card:hover .cardImage picture img:not(.perspectiveLayer),
.listItem:hover .listAvatar img,
.listItem:hover .listAvatar picture img {
  transform: scale(1.06);
  will-change: transform;
}

/* Parallax — the image participates in the card's tilt but sits on a
   nearer depth layer. We fake that in 2D by (a) translating in the
   direction of the tilt so it follows the rotation's screen-space
   shift, and (b) counter-rotating a fraction of the card's rotation.
   A plane that rotates less than its container reads as closer to
   the viewer, which is the "shifts perspective with the tilt" feel.
   --pointer-x / --pointer-y (-1..1) are set on .cardTilt by the mouse
   handlers and drive both effects from the same source.

   The scale during tilt has to exceed (translate + rotation edge offset)
   / half-container-width on every side, or the corner of the image
   uncovers its container and the card/cell background bleeds through.
   Mosaic cells are ~half the width of a single-card image, so their
   translate is scaled down to keep relative intensity in line with
   single cards (otherwise the same 8px shift reads twice as strong
   in a collage). */
.cardTilt.tilting .cardImage img:not(.perspectiveLayer),
.cardTilt.tilting .cardImage picture img:not(.perspectiveLayer),
.cardTilt.tilting .cardAvatarFallback {
  --lazy-image-transform-transition: 120ms ease-out;
  transition: transform 120ms ease-out;
  transform:
    translate3d(calc(var(--pointer-x, 0) * 8px), calc(var(--pointer-y, 0) * 8px), 0)
    rotateX(calc(var(--pointer-y, 0) * 1.5deg))
    rotateY(calc(var(--pointer-x, 0) * -1.5deg))
    scale(1.14);
  will-change: transform;
}

.cardTilt.tilting .mosaicCell img,
.cardTilt.tilting .mosaicCell picture img {
  --lazy-image-transform-transition: 120ms ease-out;
  transform:
    translate3d(calc(var(--pointer-x, 0) * 4px), calc(var(--pointer-y, 0) * 4px), 0)
    rotateX(calc(var(--pointer-y, 0) * 1deg))
    rotateY(calc(var(--pointer-x, 0) * -1deg))
    scale(1.14);
  will-change: transform;
}

.perspectiveStack {
  isolation: isolate;
  background: var(--lumiverse-bg-deep);
  transform-style: preserve-3d;
}

.perspectiveLayer {
  --lazy-image-transform-transition: 500ms cubic-bezier(0.22, 1, 0.36, 1);
  --layer-origin-x: 0px;
  --layer-origin-y: 0px;
  --layer-origin-depth: 0px;
  --layer-origin-tilt-x: 0deg;
  --layer-origin-tilt-y: 0deg;
  --layer-mouse-x: 0px;
  --layer-mouse-y: 0px;
  --layer-mouse-depth: 0px;
  --layer-mouse-tilt-x: 0deg;
  --layer-mouse-tilt-y: 0deg;
  --layer-hover-depth: 0px;
  --layer-hover-depth-target: 0px;
  --layer-hover-scale: var(--layer-scale);
  --layer-motion-x: 0px;
  --layer-motion-y: 0px;
  --layer-motion-depth: 0px;
  --layer-tilt-amount: 0deg;
  --layer-tilt-amount-neg: 0deg;
  --layer-scale: var(--layer-base-scale, 1);
  position: absolute;
  inset: -12% -8%;
  width: 116%;
  height: 124%;
  max-width: none;
  max-height: none;
  object-fit: cover;
  transform-origin: 50% 50%;
  user-select: none;
  pointer-events: none;
  transform:
    translate3d(
      calc(var(--layer-origin-x) + var(--layer-mouse-x)),
      calc(var(--layer-origin-y) + var(--layer-mouse-y)),
      calc(var(--layer-origin-depth) + var(--layer-hover-depth) + var(--layer-mouse-depth))
    )
    rotateX(calc(var(--layer-origin-tilt-x) + var(--layer-mouse-tilt-x)))
    rotateY(calc(var(--layer-origin-tilt-y) + var(--layer-mouse-tilt-y)))
    scale(var(--layer-scale));
  transition: transform 500ms cubic-bezier(0.22, 1, 0.36, 1);
}

.perspectiveStack .cardImageOverlay {
  z-index: 3;
}

.card:hover .perspectiveLayer,
.cardTilt.mobileMotionTilting .perspectiveLayer {
  --layer-hover-depth: var(--layer-hover-depth-target);
  --layer-scale: var(--layer-hover-scale);
}

.cardTilt.tilting .perspectiveLayer {
  --lazy-image-transform-transition: 120ms ease-out;
  transition: transform 120ms ease-out;
  will-change: transform;
}

.cardTilt.tilting .perspectiveLayer {
  --layer-mouse-x: calc(var(--pointer-x, 0) * var(--layer-motion-x));
  --layer-mouse-y: calc(var(--pointer-y, 0) * var(--layer-motion-y));
  --layer-mouse-depth: calc(var(--pointer-y, 0) * var(--layer-motion-depth));
  --layer-mouse-tilt-x: calc(var(--pointer-y, 0) * var(--layer-tilt-amount));
  --layer-mouse-tilt-y: calc(var(--pointer-x, 0) * var(--layer-tilt-amount-neg));
}

@media (prefers-reduced-motion: reduce) {
  .cardTilt,
  .cardTilt.tilting,
  .cardTilt.mobileMotionTilting {
    perspective: none;
    transform: none !important;
    transform-style: flat;
  }
  .card,
  .cardTilt.tilting .card,
  .cardTilt.mobileMotionTilting .card {
    transform-style: flat;
  }
  .cardImage img,
  .cardImage picture img,
  .listAvatar img,
  .listAvatar picture img,
  .mosaicCell img,
  .mosaicCell picture img {
    --lazy-image-transform-transition: 0ms;
    transition: none;
    will-change: auto;
  }
  .card:hover .cardImage img:not(.perspectiveLayer),
  .card:hover .cardImage picture img:not(.perspectiveLayer),
  .listItem:hover .listAvatar img,
  .listItem:hover .listAvatar picture img,
  .cardTilt.tilting .cardImage img:not(.perspectiveLayer),
  .cardTilt.tilting .cardImage picture img:not(.perspectiveLayer),
  .cardTilt.mobileMotionTilting .cardImage img:not(.perspectiveLayer),
  .cardTilt.mobileMotionTilting .cardImage picture img:not(.perspectiveLayer),
  .cardTilt.tilting .mosaicCell img,
  .cardTilt.tilting .mosaicCell picture img,
  .cardTilt.mobileMotionTilting .mosaicCell img,
  .cardTilt.mobileMotionTilting .mosaicCell picture img,
  .cardTilt.tilting .perspectiveLayer,
  .cardTilt.mobileMotionTilting .perspectiveLayer,
  .cardTilt.tilting .cardAvatarFallback,
  .cardTilt.mobileMotionTilting .cardAvatarFallback {
    transform: none;
  }
  .cardShine {
    display: none;
  }
}

/* Suppress hover effects while scrolling */
.container[data-scrolling] .cardTilt {
  pointer-events: none;
}

/* Disable all card hover/tilt/shine transforms while scrolling to keep the
   compositor layer tree as small as possible during the scroll gesture. */
.container[data-scrolling] .cardTilt {
  perspective: none;
  transform-style: flat;
}

.container[data-scrolling] .cardTilt .card {
  transform-style: flat;
}

.container[data-scrolling] .cardShine {
  display: none;
}

.container[data-scrolling] .card,
.container[data-scrolling] .listItem {
  transition: none;
  animation: none;
}

.container[data-scrolling] .cardImage img,
.container[data-scrolling] .cardImage picture img,
.container[data-scrolling] .listAvatar img,
.container[data-scrolling] .listAvatar picture img,
.container[data-scrolling] .mosaicCell img,
.container[data-scrolling] .mosaicCell picture img {
  --lazy-image-transform-transition: 0ms;
  /* Decode completion can happen during the gesture. Keep its opacity fade
     while preventing hover/tilt transforms from animating during scrolling. */
  transition-property: opacity !important;
  will-change: auto;
  transform: none !important;
}

.container[data-scrolling] .cardAvatarFallback {
  transition: none !important;
  will-change: auto;
  transform: none !important;
}

.container[data-scrolling] .cardTilt.tilting .perspectiveLayer,
.container[data-scrolling] .cardTilt.mobileMotionTilting .perspectiveLayer {
  --lazy-image-transform-transition: 0ms;
  will-change: auto;
  transform: none !important;
}

.container[data-scrolling] .perspectiveStack {
  transform-style: flat;
}

.cardBtn {
  position: relative;
  display: flex;
  flex-direction: column;
  width: 100%;
  transform-style: preserve-3d;
  cursor: pointer;
  background: none;
  border: none;
  padding: 0;
  text-align: left;
  color: inherit;
}

.cardImage {
  position: relative;
  aspect-ratio: 3 / 4;
  overflow: hidden;
  background: var(--lumiverse-card-bg);
  transform-style: preserve-3d;
}

.cardImageOverlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, var(--lumiverse-bg-deep) 0%, transparent 60%);
}

.cardContent {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 12px 14px;
  z-index: 1;
}

.cardName {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: calc(14px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  margin: 0;
}

.cardName svg,
.listName svg {
  flex-shrink: 0;
  color: var(--lumiverse-primary-muted);
}

.cardName span,
.listName span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.favoriteCard,
.favoriteListItem {
  border-color: var(--lumiverse-primary-030);
}

.cardMeta {
  display: flex;
  align-items: center;
  gap: 6px;
}

.chatCountBadge {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-primary-muted);
  background: var(--lumiverse-primary-015);
  border: 1px solid var(--lumiverse-primary-020);
  padding: 1px 6px;
  border-radius: 20px;
  letter-spacing: 0.02em;
  white-space: nowrap;
}

.cardTime {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
}

.cardAvatarFallback {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: calc(48px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  color: var(--lumiverse-primary-muted);
  background: var(--lumiverse-primary-010);
  transition: transform 500ms cubic-bezier(0.22, 1, 0.36, 1);
}

.card:hover .cardAvatarFallback {
  transform: scale(1.06);
}

.listAvatarFallback {
  font-size: calc(20px * var(--lumiverse-font-scale, 1));
}

.deleteBtn {
  position: absolute;
  top: 8px;
  right: 8px;
  z-index: 2;
  width: var(--lumiverse-btn-icon);
  height: var(--lumiverse-btn-icon);
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: rgba(10, 10, 14, 0.72);
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text-dim);
  cursor: pointer;
  opacity: 0;
  transition: opacity var(--lumiverse-transition-fast), color var(--lumiverse-transition-fast);
}

.card:hover .deleteBtn,
.card:focus-within .deleteBtn {
  opacity: 1;
}

.deleteBtn:hover {
  color: var(--lumiverse-danger);
  border-color: var(--lumiverse-danger-020);
}

/* Shift changes the hovered/focused card's action to remove-from-recent. It
   must not reveal the action on every mounted card just because Shift is down. */
.card:hover .deleteBtnShift,
.card:focus-within .deleteBtnShift {
  opacity: 1;
  color: var(--lumiverse-primary);
  border-color: var(--lumiverse-primary-030);
  background: rgba(10, 10, 14, 0.85);
}

.deleteBtnShift:hover {
  color: var(--lumiverse-primary-hover);
  border-color: var(--lumiverse-primary-050);
}

/* ---- Group Chat Card ---- */
.groupCard {
  border-color: var(--lumiverse-primary-020);
}

.groupCard:hover {
  border-color: var(--lumiverse-primary-050);
  box-shadow:
    0 14px 28px rgba(0, 0, 0, 0.35),
    0 4px 10px rgba(0, 0, 0, 0.2),
    0 0 28px var(--lumiverse-primary-015);
}

.groupCard .cardBtn {
  position: relative;
}

.groupCard .cardContent {
  z-index: 3;
}

.groupMosaic {
  display: grid;
  gap: 2px;
  width: 100%;
  height: 100%;
}

.groupMosaic2 {
  grid-template-columns: 1fr 1fr;
}

.groupMosaic3 {
  grid-template-columns: 1.5fr 1fr;
  grid-template-rows: 1fr 1fr;
}

.groupMosaic3 .mosaicCell:first-child {
  grid-row: 1 / -1;
}

.groupMosaic4 {
  grid-template-columns: 1.4fr 1fr;
  grid-template-rows: 1.4fr 1fr;
}

.mosaicCell {
  overflow: hidden;
  min-height: 0;
  position: relative;
}

.mosaicCell img,
.mosaicCell picture img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.mosaicFallback {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--lumiverse-primary-muted);
  background: var(--lumiverse-primary-010);
}

/* Overlay sits outside the grid so it isn't a grid item */
.groupOverlay {
  position: absolute;
  inset: 0;
  z-index: 2;
  background: linear-gradient(to top, var(--lumiverse-bg-deep) 0%, transparent 55%);
  pointer-events: none;
}

.groupMeta {
  display: flex;
  align-items: center;
  gap: 8px;
}

.groupBadge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-primary-muted);
  background: var(--lumiverse-primary-015);
  border: 1px solid var(--lumiverse-primary-020);
  padding: 2px 7px;
  border-radius: 20px;
  letter-spacing: 0.02em;
  white-space: nowrap;
}

.listItem {
  position: relative;
  border-radius: 18px;
  overflow: hidden;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--lumiverse-primary) 4%, transparent), transparent 45%),
    var(--lumiverse-card-bg);
  border: 1px solid var(--lumiverse-border);
  box-shadow: var(--lumiverse-shadow-sm);
  transition:
    border-color var(--lumiverse-transition-fast),
    box-shadow var(--lumiverse-transition-fast),
    transform var(--lumiverse-transition-fast);
}

.listItemEntry {
  animation: cardEntry 0.28s cubic-bezier(0.22, 1, 0.36, 1) both;
}

.listItem:hover {
  transform: translateY(-1px);
  border-color: var(--lumiverse-primary-020);
  box-shadow:
    0 14px 30px rgba(0, 0, 0, 0.22),
    0 0 22px var(--lumiverse-primary-010);
}

.listItemGroup {
  border-color: var(--lumiverse-primary-020);
}

.listBtn {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 14px;
  width: 100%;
  padding: 14px;
  background: none;
  border: none;
  color: inherit;
  text-align: left;
  cursor: pointer;
}

.listAvatar {
  width: 56px;
  height: 56px;
  min-width: 56px;
  border-radius: 16px;
  overflow: hidden;
  background: var(--lumiverse-primary-010);
  border: 1px solid var(--lumiverse-primary-020);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
}

.listAvatar img,
.listAvatar picture img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.listBody {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.listTopRow,
.listBottomRow {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.listName {
  display: flex;
  align-items: center;
  gap: 5px;
  margin: 0;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: calc(14px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
}

.listTime {
  flex-shrink: 0;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
}

.listSubtitle {
  margin: 0;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
}

.listMeta {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}

.listStatusPill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 20px;
  padding: 1px 8px;
  border-radius: 999px;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  letter-spacing: 0.02em;
  color: var(--lumiverse-text-dim);
  background: var(--lumiverse-fill-subtle);
  border: 1px solid color-mix(in srgb, var(--lumiverse-border) 85%, transparent);
  white-space: nowrap;
}

.listDeleteBtn {
  position: absolute;
  top: 10px;
  right: 10px;
  z-index: 2;
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  background: color-mix(in srgb, var(--lumiverse-bg-deep) 74%, transparent);
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text-dim);
  cursor: pointer;
  opacity: 0;
  transition:
    opacity var(--lumiverse-transition-fast),
    color var(--lumiverse-transition-fast),
    border-color var(--lumiverse-transition-fast);
}

.listItem:hover .listDeleteBtn,
.listItem:focus-within .listDeleteBtn {
  opacity: 1;
}

.listDeleteBtn:hover {
  color: var(--lumiverse-danger);
  border-color: var(--lumiverse-danger-020);
}

.listItem:hover .listDeleteBtnShift,
.listItem:focus-within .listDeleteBtnShift {
  opacity: 1;
  color: var(--lumiverse-primary);
  border-color: var(--lumiverse-primary-030);
  background: color-mix(in srgb, var(--lumiverse-bg-deep) 92%, transparent);
}

.listDeleteBtnShift:hover {
  color: var(--lumiverse-primary-hover);
  border-color: var(--lumiverse-primary-050);
}

.listSkeleton {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 14px;
  padding: 14px;
  border-radius: 18px;
  background: var(--lumiverse-card-bg);
  border: 1px solid var(--lumiverse-border);
}

.listSkeletonAvatar {
  width: 56px;
  height: 56px;
  border-radius: 16px;
  background: linear-gradient(90deg, rgba(255, 255, 255, 0.02) 25%, rgba(255, 255, 255, 0.06) 50%, rgba(255, 255, 255, 0.02) 75%);
  background-size: 200% 100%;
  animation: lumiverseShimmer 1.5s ease-in-out infinite;
}

.listSkeletonBody {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.listSkeletonTitle,
.listSkeletonMeta {
  border-radius: 4px;
  background: var(--lumiverse-fill-subtle);
}

.listSkeletonTitle {
  width: 72%;
  height: 14px;
}

.listSkeletonMeta {
  width: 46%;
  height: 10px;
}

/* Skeleton */
.skeletonCard {
  border-radius: 16px;
  overflow: hidden;
  background: var(--lumiverse-card-bg);
  border: 1px solid var(--lumiverse-border);
}

.skeletonImage {
  aspect-ratio: 3 / 4;
  background: linear-gradient(90deg, rgba(255, 255, 255, 0.02) 25%, rgba(255, 255, 255, 0.06) 50%, rgba(255, 255, 255, 0.02) 75%);
  background-size: 200% 100%;
  animation: lumiverseShimmer 1.5s ease-in-out infinite;
}

.skeletonContent {
  padding: 12px 14px;
}

.skeletonTitle {
  height: 14px;
  width: 70%;
  border-radius: 4px;
  background: var(--lumiverse-fill-subtle);
  margin-bottom: 6px;
}

.skeletonMeta {
  height: 10px;
  width: 40%;
  border-radius: 4px;
  background: var(--lumiverse-fill-subtle);
}

/* Empty & Error */
.emptyState {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 80px 20px;
  text-align: center;
}

.emptyIcon {
  color: var(--lumiverse-primary-muted);
  margin-bottom: 20px;
  opacity: 0.5;
}

.emptyState h3 {
  font-size: calc(20px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
  margin-bottom: 8px;
}

.emptyState p {
  font-size: calc(14px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
}

.errorState {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 80px 20px;
  gap: 16px;
  color: var(--lumiverse-text-muted);
}

.primaryBtn {
  padding: 10px 24px;
  border-radius: 10px;
  background: linear-gradient(135deg, var(--lumiverse-primary), var(--lumiverse-primary-hover));
  border: 1px solid var(--lumiverse-primary-050);
  color: var(--lumiverse-primary-contrast, #fff);
  font-weight: 600;
  font-size: calc(14px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
}

/* Infinite scroll sentinel */
.loadMoreSentinel {
  display: flex;
  justify-content: center;
  padding: 24px 0;
  min-height: 60px;
}

.loadingMore {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
}

@media (max-width: 600px) {
  .header {
    padding-bottom: 4px;
    margin-bottom: 8px;
  }

  .landingToolbar {
    margin-bottom: 14px;
  }

  /* The Suite adds the Characters tab beside native Chats. Keep the two tabs
     compact so the chat search remains a useful, tappable width. The label is
     visually hidden rather than removed so each tab retains its accessible
     name. */
  .landingTabsWithSuite .landingTabLabel {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
  }

  /* Gallery width only changes the desktop/tablet layout. */
  .galleryWidthBtn {
    display: none;
  }

  .content {
    padding: 16px;
  }
  .gridCards {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px;
  }
  .compactList {
    grid-template-columns: 1fr;
  }
  .listBtn {
    gap: 12px;
    padding: 12px;
  }
  .listAvatar,
  .listSkeletonAvatar {
    width: 52px;
    height: 52px;
    min-width: 52px;
  }
  .listTopRow,
  .listBottomRow {
    align-items: flex-start;
    flex-direction: column;
  }
  .listTime,
  .listMeta {
    flex-shrink: 1;
  }
}

@media (max-width: 364px) {
  .gridCards {
    grid-template-columns: 1fr;
  }
}

