                <span className={styles.groupBadge} style={{ color: 'var(--lumiverse-accent, #6366f1)' }} title="Multiplayer">
                  <Gamepad2 size={10} strokeWidth={2} />
                </span>
              )}
              {isGroup ? (
                <span className={styles.groupBadge}>
                  <Users size={10} strokeWidth={2} />
                  {item.group_character_ids!.length}
                </span>
              ) : item.chat_count > 1 ? (
                <span className={styles.chatCountBadge}>
                  <MessageSquare size={10} strokeWidth={2} />
                  {item.chat_count}
                </span>
              ) : (
                <span className={styles.listStatusPill}>{t('active')}</span>
              )}
            </div>
          </div>
        </div>
      </button>
    </div>
  )
})

interface VirtualizedChatRowsProps {
  items: GroupedRecentChat[]
  layoutMode: 'cards' | 'compact'
  virtualColumns: number
  virtualGap: number
  virtualRowEstimate: number
  virtualScrollMargin: number | null
  mainWidth: number
  fontScale: number
  initialSnapshot: LandingPageSnapshot | null
  snapshotRef: Ref<LandingVirtualizerHandle>
  scrollRef: RefObject<HTMLDivElement | null>
  initialPageSize: number
  animateInitialEntries: boolean
  eagerImages: boolean
  shiftPressed: boolean
  onContainerChange: (node: HTMLDivElement | null) => void
  onChatClick: (item: GroupedRecentChat) => void
  onDeleteChat: (item: GroupedRecentChat) => void
  onDeleteAllChats: (item: GroupedRecentChat) => void
  onRemoveFromRecent: (item: GroupedRecentChat) => void
  onOpenContextMenu: (item: GroupedRecentChat, position: ContextMenuPos) => void
}

/**
 * Owns the row measurements while VirtualGrid preserves entry identity across
 * responsive column changes. Card/list switches use separate lifecycles because
 * their image tiers and height measurements differ.
 */
function VirtualizedChatRows({
  items,
  layoutMode,
  virtualColumns,
  virtualGap,
  virtualRowEstimate,
  virtualScrollMargin,
  mainWidth,
  fontScale,
  initialSnapshot,
  snapshotRef,
  scrollRef,
  initialPageSize,
  animateInitialEntries,
  eagerImages,
  shiftPressed,
  onContainerChange,
  onChatClick,
  onDeleteChat,
  onDeleteAllChats,
  onRemoveFromRecent,
  onOpenContextMenu,
}: VirtualizedChatRowsProps) {
  const prefetchImages = useImagePrefetch()
  const virtualRowCount = Math.ceil(items.length / virtualColumns)
  const characters = useStore((state) => state.characters)
  const rowKeys = useMemo(() => Array.from({ length: virtualRowCount }, (_, index) => {
    const start = index * virtualColumns
    return JSON.stringify(items.slice(start, start + virtualColumns).map(getRecentChatKey))
  }), [items, virtualColumns, virtualRowCount])
  const { virtualizer: chatVirtualizer, scrollMargin } = useLandingVirtualizer({
    geometry: {
      layout: layoutMode, width: mainWidth, columns: virtualColumns, gap: virtualGap,
      rowEstimate: virtualRowEstimate, uiScale: getUiScale(), fontScale, viewportWidth: window.innerWidth,
    },
    rowKeys,
    scrollRef,
    scrollMargin: virtualScrollMargin,
    savedSnapshot: initialSnapshot?.virtualRows,
    initialOffset: initialSnapshot?.scrollTop,
    snapshotRef,
  })

  const virtualItems = chatVirtualizer.getVirtualItems()
  const visibleStart = virtualItems.length > 0 ? virtualItems[0].index : -1
  const visibleEnd = virtualItems.length > 0 ? virtualItems[virtualItems.length - 1].index : -1

  useEffect(() => {
    if (visibleStart < 0 || visibleEnd < 0 || items.length === 0) {
      prefetchImages([])
      return
    }
    const startRow = Math.max(0, visibleStart - PREFETCH_ROWS)
    const endRow = Math.min(virtualRowCount - 1, visibleEnd + PREFETCH_ROWS)
    const startItem = startRow * virtualColumns
    const endItem = Math.min(items.length, (endRow + 1) * virtualColumns)
    const urls = getItemAvatarUrls(
      items.slice(startItem, endItem),
      characters,
      layoutMode === 'compact' ? 'compact' : 'card',
    )
    prefetchImages(urls)
  }, [characters, items, layoutMode, visibleEnd, visibleStart, virtualColumns, virtualRowCount, prefetchImages])

  const Entry = layoutMode === 'compact' ? ChatListItem : ChatCard

  return (
    <motion.div
      className={styles.virtualChats}
      data-component="LandingPageChats"
      data-layout-columns={virtualColumns}
      data-spindle-mount="landing_recent_chats"
      data-spindle-scope="landing:recent-chats"
      ref={onContainerChange}
      style={{ height: chatVirtualizer.getTotalSize() }}
      variants={containerVariants}
      initial={animateInitialEntries ? 'hidden' : false}
      animate="visible"
      exit="exit"
    >
      <VirtualGrid
        items={items}
        rows={virtualItems}
        columns={virtualColumns}
        gap={virtualGap}
        scrollMargin={scrollMargin}
        className={styles.virtualRow}
        measureElement={chatVirtualizer.measureElement}
        getItemKey={getRecentChatKey}
        renderItem={(item, index) => (
          <Entry
            item={item}
            animateEntry={animateInitialEntries && index < initialPageSize}
            eagerImages={eagerImages}
            shiftPressed={shiftPressed}
            onClick={onChatClick}
            onDeleteChat={onDeleteChat}
            onDeleteAllChats={onDeleteAllChats}
            onRemoveFromRecent={onRemoveFromRecent}
            onOpenContextMenu={onOpenContextMenu}
          />
        )}
      />
    </motion.div>
  )
}

