            isGroupChat: true,
            groupCharacterIds,
          })
          return
        }
        navigateToChat(item.latest_chat_id)
        return
      }

      if (item.chat_count === 1) {
        navigateToChat(item.latest_chat_id)
        return
      }

      openModal('chatPicker', {
        characterId: item.character_id,
        characterName: item.character_name,
        onSelect: (chatId: string) => navigateToChat(chatId)
      })
