              title={t('logOutTitle')}
            >
              <span className={styles.accountName}>{accountLabel}</span>
              <LogOut size={13} strokeWidth={1.5} />
            </button>
          </div>
        </header>

        <div className={styles.landingToolbar} data-component="LandingPageTabs" data-spindle-mount="landing_toolbar">
          {suiteLandingTabsReady && (
            <div className={clsx(styles.landingTabs, styles.landingTabsWithSuite)} role="tablist" aria-label="Landing views">
              {availableLandingTabs.map((tab) => {
                const selected = activeLandingTab === tab
                return (
                  <button key={tab} id={landingPageTabId(tab)} type="button" role="tab" data-landing-tab={tab}
                    aria-selected={selected} aria-controls={landingPageTabPanelId(tab)} tabIndex={selected ? 0 : -1}
                    onClick={() => handleLandingTabChange(tab)}
                    onKeyDown={(event) => {
                      const next = resolveTabArrowKey(event.key, tab, availableLandingTabs)
                      if (!next) return
                      event.preventDefault()
                      handleLandingTabChange(next)
                      window.requestAnimationFrame(() => document.getElementById(landingPageTabId(next))?.focus())
                    }}
                    style={{ display: 'inline-flex', alignItems: 'center', gap: 6, padding: '7px 10px', border: '1px solid var(--lumiverse-border)', borderRadius: 8, background: selected ? 'var(--lumiverse-primary-010)' : 'transparent', color: selected ? 'var(--lumiverse-text)' : 'var(--lumiverse-text-muted)', cursor: 'pointer' }}
                  >
                    {tab === 'characters' ? <Users size={14} strokeWidth={1.5} /> : <MessageSquare size={14} strokeWidth={1.5} />}
                    <span className={styles.landingTabLabel}>{tab === 'characters' ? 'Characters' : 'Chats'}</span>
                  </button>
                )
              })}
            </div>
          )}
          {activeLandingTab === 'chats' && !chatsSurfaceReady && <>
          <SearchField
            value={searchQuery}
            onChange={setSearchQuery}
            placeholder={t('searchPlaceholder')}
            clearLabel={tc('actions.clear')}
            className={styles.landingSearch}
          />
          <SortControl
            options={[
              { value: 'recent', label: t('sort.recent') },
              { value: 'name', label: t('sort.name') },
              { value: 'created', label: t('sort.created') },
            ]}
            value={sortField}
            onChange={handleSortFieldChange}
            direction={sortDirection}
            onToggleDirection={() => setSortDirection((direction) => direction === 'asc' ? 'desc' : 'asc')}
            title={t('sort.title')}
            ascendingTitle={t('sort.ascending')}
            descendingTitle={t('sort.descending')}
            dropdownAlign="end"
          />
          <button
            type="button"
            className={styles.hiddenManagerBtn}
            onClick={() => openModal('hiddenFromHome')}
            title={t('hiddenFromHome.title')}
            aria-label={t('hiddenFromHome.title')}
          >
            <EyeOff size={15} strokeWidth={1.5} />
          </button>
          <button
            type="button"
            className={clsx(styles.hiddenManagerBtn, styles.galleryWidthBtn, effectiveGalleryWidth === 'expanded' && styles.galleryWidthBtnActive)}
            onClick={() => {
              const next = effectiveGalleryWidth === 'expanded' ? 'compact' : 'expanded'
              setSnapshotGalleryWidth(null)
              setSetting('landingPageGalleryWidth', next)
            }}
            title={effectiveGalleryWidth === 'expanded' ? t('galleryWidth.compact') : t('galleryWidth.expanded')}
            aria-label={effectiveGalleryWidth === 'expanded' ? t('galleryWidth.compact') : t('galleryWidth.expanded')}
            aria-pressed={effectiveGalleryWidth === 'expanded'}
          >
            {effectiveGalleryWidth === 'expanded'
              ? <Minimize2 size={15} strokeWidth={1.5} />
              : <Maximize2 size={15} strokeWidth={1.5} />}
          </button>
          </>}
        </div>

        <main className={styles.main} ref={mainRef} data-component="LandingPageMain" data-spindle-mount="landing_main">
          <span data-spindle-mount="landing_hero" data-spindle-scope="landing:hero" style={{ display: 'contents' }} />
          <div id={landingPageTabPanelId('characters')} role={suiteLandingTabsReady ? 'tabpanel' : undefined}
            aria-labelledby={suiteLandingTabsReady ? landingPageTabId('characters') : undefined}
            data-component="LandingPageCharacterPanel" data-spindle-mount="landing_characters" data-spindle-scope="landing:characters"
            hidden={activeLandingTab !== 'characters' || !homepageSurfaceReady} />
          <div id={landingPageTabPanelId('chats')} role={suiteLandingTabsReady ? 'tabpanel' : undefined}
            aria-labelledby={suiteLandingTabsReady ? landingPageTabId('chats') : undefined}
            data-component="LandingPageChatsPanel" data-spindle-mount="landing_chats"
            hidden={activeLandingTab !== 'chats' || !chatsSurfaceReady} />
          <AnimatePresence mode="wait">
            {activeLandingTab === 'characters' || chatsSurfaceReady ? null : !settingsLoaded || (loading && items.length === 0) ? (
              <motion.div
                key={`loading-${skeletonLayout}`}
                className={skeletonLayout === 'compact' ? styles.compactList : styles.gridCards}
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
              >
                {Array.from({ length: skeletonCount }).map((_, i) => (
                  skeletonLayout === 'compact'
                    ? <SkeletonListItem key={i} index={i} />
                    : <SkeletonCard key={i} index={i} />
                ))}
              </motion.div>
            ) : error && items.length === 0 ? (
              <motion.div key="error" className={styles.errorState} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }}>
                <p>{t('loadFailed')}</p>
                <button onClick={fetchChats} className={styles.primaryBtn} type="button">{t('tryAgain')}</button>
              </motion.div>
            ) : items.length === 0 ? (
              <EmptyState key="empty" filtered={Boolean(debouncedSearchQuery)} />
            ) : (
              <VirtualizedChatRows
                key={virtualLayout}
                items={items}
                layoutMode={virtualLayout}
                virtualColumns={virtualColumns}
                virtualGap={virtualGap}
                virtualRowEstimate={virtualRowEstimate}
                virtualScrollMargin={virtualScrollMargin}
                mainWidth={mainWidth}
                fontScale={fontScale}
                initialSnapshot={virtualRestoreSnapshot}
                snapshotRef={bindVirtualSnapshot}
                scrollRef={scrollRef}
                initialPageSize={chatPageSizeRef.current}
                animateInitialEntries={animateInitialEntries}
                eagerImages={hasRestoredChatReturn}
                shiftPressed={shiftPressed}
                onContainerChange={handleVirtualContainerChange}
                onChatClick={handleChatClick}
                onDeleteChat={handleDeleteChat}
                onDeleteAllChats={handleDeleteAllChats}
                onRemoveFromRecent={handleRemoveFromRecent}
                onOpenContextMenu={handleOpenContextMenu}
              />
            )}
          </AnimatePresence>

          {activeLandingTab === 'chats' && !chatsSurfaceReady && hasMore && (
            <div ref={sentinelRef} className={styles.loadMoreSentinel}>
              {loadingMore && (
                <div className={styles.loadingMore}>
                  <Spinner size={16} />
                  <span>{t('loadingMore')}</span>
                </div>
              )}
            </div>
          )}
          <span data-spindle-mount="landing_footer" data-spindle-scope="landing:footer" style={{ display: 'contents' }} />
        </main>
      </motion.div>
    </div>
    <GuideViewer
        isOpen={guidesOpen}
        onClose={() => setGuidesOpen(false)}
        guide={FULL_GUIDES}
        title="Lumiverse Guides"
        searchable
    />
    <ContextMenu
      position={contextMenu?.position ?? null}
      items={contextMenuItems}
      onClose={() => setContextMenu(null)}
    />
  </div>
)
}

export default function LandingPage() {
  return useSpindleComponentOverride('LandingPageShell', LandingPageNative, {})
}

sources.src/components/lore-indicator/LoreIndica:
.floatingRoot {
  position: fixed;
  z-index: 10010;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  max-width: calc(100vw - 24px);
  font-size: var(--lore-text-size, 12px);
  color: var(--lumiverse-text);
}

.floatingRoot button,
.composerRoot button,
.panel button,
.panel input,
.config button,
.config input,
.config select {
  font: inherit;
}

.v2Wrap {
  position: relative;
  display: inline-flex;
  align-items: center;
}

.compactTrigger,
.paletteTrigger,
.stripItem {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  min-height: 26px;
  padding: 4px 8px;
  color: var(--lumiverse-primary-text, var(--lumiverse-primary));
  background: color-mix(in srgb, var(--lumiverse-bg-elevated, var(--lumiverse-bg)) 90%, transparent);
  border: 1px solid var(--lumiverse-border);
  border-radius: 7px;
  cursor: pointer;
}

.compactTrigger svg,
.paletteTrigger svg,
.stripItem svg {
  width: var(--lore-icon-size, 16px);
  height: var(--lore-icon-size, 16px);
}

.compactTrigger {
  min-width: 54px;
  min-height: 42px;
  padding: 7px 10px;
  cursor: grab;
  touch-action: none;
}

.compactTrigger:active {
  cursor: grabbing;
}

.dragHandle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  min-width: 24px;
  height: 28px;
  padding: 0;
  color: var(--lumiverse-text-dim);
  cursor: grab;
  touch-action: none;
  background: var(--lumiverse-bg-elevated, var(--lumiverse-bg));
  border: 1px solid var(--lumiverse-border);
  border-radius: 7px;
}

.dragHandle:active,
.paletteDragBar:active {
  cursor: grabbing;
}

/* The V4 root is a plain flex child of its host dock. It must fill the host's inline
   size rather than shrink to fit: the popovers below anchor on it with left/right 0,
   so a shrink-to-fit root would collapse them to the strip's own ~200px width. */
.composerRoot {
  position: relative;
  display: flex;
  align-items: center;
  width: 100%;
  min-width: 0;
}

.strip {
  display: flex;
  flex: 1 1 auto;
  align-items: center;
  min-width: 0;
  max-width: min(70vw, 920px);
  overflow-x: auto;
  scrollbar-width: none;
}

.strip::-webkit-scrollbar {
  display: none;
}

.stripItem {
  flex: 0 0 auto;
  min-height: 24px;
  padding: 2px 6px;
  color: var(--lumiverse-text-muted);
  background: transparent;
  border-color: transparent;
}

.stripItem:hover {
  color: var(--lumiverse-text);
  border-color: var(--lumiverse-border);
  background: var(--lumiverse-fill-hover);
}

/* Type counts carry the same colour language as entry badges. */
.stripItem[data-activation='constant'] {
  color: #f6b73c;
}

.stripItem[data-activation='sticky'] {
  color: #f48fb1;
}

.stripItem[data-activation='keyword'] {
  color: #78adff;
}

.stripItem[data-activation='vector'] {
  color: #bb94ff;
}

.chevronOpen {
  transform: rotate(180deg);
}

.panel,
.compactPanel,
.config {
  color: var(--lumiverse-text);
  background: var(--lumiverse-bg-elevated, var(--lumiverse-bg));
  border: 1px solid var(--lumiverse-border);
  box-shadow: var(--lumiverse-shadow-xl, 0 20px 60px rgba(0, 0, 0, 0.55));
}

.panel {
  width: 100%;
  height: 100%;
  overflow: hidden;
  border-radius: 10px;
}

.compactPopover {
  position: fixed;
  z-index: 10011;
  font-size: var(--lore-text-size, 12px);
}

.compactPanel {
  display: flex;
  width: 100%;
  height: 100%;
  overflow: hidden;
  flex-direction: column;
  border-radius: 9px;
}

/* Opens upward out of the dock. `z-index: 1` only has to beat the strip beside it —
   the dock itself owns the app-level claim, so no competing literal lives here. */
.v4PanelPopover,
.v4ConfigPopover {
  position: absolute;
  bottom: 100%;
  left: 0;
  right: 0;
  z-index: 1;
  display: flex;
  flex-direction: column;
  margin-bottom: 8px;
  max-height: min(560px, calc(100vh - 180px));
  font-size: var(--lore-text-size, 12px);
}

/* Let the panel shrink under the max-height so it scrolls internally
   instead of overflowing the dock. */
.v4PanelPopover > *,
.v4ConfigPopover > * {
  flex: 1 1 auto;
  min-height: 0;
}

.expandedPanel {
  max-height: 100%;
}

.panelHeader {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 10px;
  padding: 10px 13px;
  border-bottom: 1px solid var(--lumiverse-border);
}

.panelHeaderIcon {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 8px;
  background: color-mix(in srgb, var(--lumiverse-primary) 14%, transparent);
  color: var(--lumiverse-primary-text, var(--lumiverse-primary));
}

.panelHeaderIdentity {
  display: flex;
  flex: 1;
  min-width: 0;
  flex-direction: column;
  gap: 2px;
}

.panelHeaderIdentity strong {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: calc(var(--lore-text-size, 12px) + 1.5px);
  font-weight: 650;
}

.panelHeaderBadge {
  display: inline-flex;
  min-width: 20px;
  align-items: center;
  justify-content: center;
  padding: 1px 6px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--lumiverse-primary) 18%, transparent);
  color: var(--lumiverse-primary-text, var(--lumiverse-primary));
  font-size: calc(var(--lore-text-size, 12px) - 1px);
  font-variant-numeric: tabular-nums;
  font-weight: 700;
}

.panelHeaderIdentity span {
  overflow: hidden;
  color: var(--lumiverse-text-dim);
  font-size: calc(var(--lore-text-size, 12px) - 1px);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.panelHeaderAction {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 5px;
  padding: 5px 9px;
  color: var(--lumiverse-text-muted);
  background: var(--lumiverse-fill-subtle, var(--lumiverse-fill));
  border: 1px solid var(--lumiverse-border);
  border-radius: 7px;
  cursor: pointer;
}

.panelHeaderAction:hover {
  color: var(--lumiverse-text);
  background: var(--lumiverse-fill-hover);
}

/* ── Activation-type filter chips (V4 strip panel + V5 palette) ── */
.paletteControls {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  padding: 0 12px;
}

.paletteControls .searchBox {
  flex: 1 1 220px;
  margin: 10px 0;
}

.typeChips {
  display: flex;
  flex: 0 0 auto;
  flex-wrap: wrap;
  gap: 5px;
  padding: 8px 12px;
}

.paletteControls .typeChips {
  padding: 0;
}

.typeChip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 9px;
  color: var(--lumiverse-text-muted);
  background: var(--lumiverse-fill-subtle, var(--lumiverse-fill));
  border: 1px solid transparent;
  border-radius: 999px;
  cursor: pointer;
  font-size: calc(var(--lore-text-size, 12px) - 1px);
}

.typeChip b {
  font-variant-numeric: tabular-nums;
  opacity: 0.72;
}

.typeChip:hover {
  border-color: var(--lumiverse-border);
  color: var(--lumiverse-text);
}

.typeChip[data-active] {
  border-color: var(--lumiverse-border);
  background: var(--lumiverse-fill-hover);
  color: var(--lumiverse-text);
}

.typeChip[data-activation='constant'][data-active] {
  border-color: color-mix(in srgb, #f59e0b 45%, transparent);
  background: color-mix(in srgb, #f59e0b 14%, transparent);
}

.typeChip[data-activation='sticky'][data-active] {
  border-color: color-mix(in srgb, #ec4899 45%, transparent);
  background: color-mix(in srgb, #ec4899 14%, transparent);
}

.typeChip[data-activation='keyword'][data-active] {
  border-color: color-mix(in srgb, #3b82f6 45%, transparent);
  background: color-mix(in srgb, #3b82f6 14%, transparent);
}

.typeChip[data-activation='vector'][data-active] {
  border-color: color-mix(in srgb, #8b5cf6 45%, transparent);
  background: color-mix(in srgb, #8b5cf6 14%, transparent);
}

.moreEntries {
  display: block;
  width: 100%;
  margin-top: 2px;
  padding: 5px 8px;
  color: var(--lumiverse-text-dim);
  text-align: left;
  background: transparent;
  border: 1px dashed var(--lumiverse-border);
  border-radius: 6px;
  cursor: pointer;
  font-size: calc(var(--lore-text-size, 12px) - 1px);
}

.moreEntries:hover {
  color: var(--lumiverse-text);
  background: var(--lumiverse-fill-hover);
}

.paletteFooter {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
  padding: 7px 13px;
  border-top: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text-dim);
  font-size: calc(var(--lore-text-size, 12px) - 1px);
}

.paletteFooter span {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.paletteFooter kbd {
  display: inline-flex;
  min-width: 18px;
  align-items: center;
  justify-content: center;
  padding: 1px 4px;
  background: var(--lumiverse-fill);
  border: 1px solid var(--lumiverse-border);
  border-radius: 4px;
  font-family: inherit;
  font-size: calc(var(--lore-text-size, 12px) - 2px);
}

.compactHeader {
  display: flex;
  flex: 0 0 auto;
  min-height: 34px;
  align-items: center;
  gap: 8px;
  padding: 5px 8px;
  border-bottom: 1px solid var(--lumiverse-border);
}

.compactHeader > strong {
  font-size: calc(var(--lore-text-size, 12px) + 1px);
  font-weight: 650;
}

.compactHeader > svg {
  color: var(--lumiverse-text-dim);
}

.compactDisplayToggle {
  display: inline-flex;
  width: 24px;
  height: 24px;
  align-items: center;
  justify-content: center;
  padding: 0;
  color: var(--lumiverse-text-muted);
  cursor: pointer;
  background: transparent;
  border: 0;
  border-radius: 4px;
}

.compactDisplayToggle:hover {
  color: var(--lumiverse-text);
  background: var(--lumiverse-fill-hover);
}

.compactTypeCount {
  font-size: calc(var(--lore-text-size, 12px) - 1px);
  font-variant-numeric: tabular-nums;
}

.compactTypeCount[data-activation='constant'] {
  color: #f6b73c;
}

.compactTypeCount[data-activation='sticky'] {
  color: #f48fb1;
}

.compactTypeCount[data-activation='keyword'] {
  color: #78adff;
}

.compactTypeCount[data-activation='vector'] {
  color: #bb94ff;
}

.compactPasses {
  flex: 1;
  color: var(--lumiverse-text-dim);
  text-align: right;
}

.searchBox {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 10px 12px;
  padding: 7px 10px;
  background: var(--lumiverse-input-bg, var(--lumiverse-fill));
  border: 1px solid var(--lumiverse-border);
  border-radius: 7px;
}

.searchBox input {
  flex: 1;
  min-width: 0;
  color: var(--lumiverse-text);
  background: transparent;
  border: 0;
  outline: 0;
}

.panelBody {
  display: grid;
  grid-template-columns: minmax(260px, 0.9fr) minmax(300px, 1.1fr);
  min-height: 0;
}

.palettePanel {
  display: flex;
  min-height: 0;
  flex-direction: column;
}

.palettePanel .panelBody {
  flex: 1;
  min-height: 0;
}

.expandedBody {
  flex: 1;
  min-height: 0;
  overflow: auto;
}

.expandedPanel {
  display: flex;
  max-height: 100%;
  min-height: 0;
  flex-direction: column;
}

.expandedBody .entryList {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  align-content: start;
  gap: 2px;
  border-right: 0;
}

.expandedBody .bookGroup {
  margin: 6px;
  padding: 7px 8px 8px;
  align-self: start;
  background: color-mix(in srgb, var(--lumiverse-fill) 26%, transparent);
  border: 1px solid var(--lumiverse-border);
  border-radius: 9px;
}

.compactList {
  flex: 1 1 auto;
  min-height: 0;
  overflow: hidden;
}

.compactEntries {
  display: grid;
  grid-template-columns: repeat(var(--compact-columns, 1), minmax(0, 1fr));
  grid-auto-flow: column;
  grid-template-rows: repeat(var(--compact-rows, 1), minmax(0, 1fr));
  gap: 2px;
  height: 100%;
  padding: 5px;
}

.compactEntry {
  display: grid;
  grid-template-columns: 15px minmax(0, 1fr) auto;
  align-items: center;
  gap: 5px;
  width: 100%;
  min-height: 0;
  padding: 2px 5px;
  color: var(--lumiverse-text);
  text-align: left;
  cursor: pointer;
  background: color-mix(in srgb, var(--lumiverse-fill) 38%, transparent);
  border: 1px solid transparent;
  border-radius: 6px;
}

.compactEntry[data-book-display='first-only'] {
  grid-template-columns: 15px minmax(0, 1fr) minmax(36px, 54px) auto;
}

.compactEntry[data-book-display='markers'] {
  grid-template-columns: 15px minmax(0, 1fr) 20px auto;
}

.compactBookHeading {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 5px;
  padding: 2px 7px;
  color: var(--lumiverse-text-muted);
  background: color-mix(in srgb, var(--lumiverse-fill) 72%, transparent);
  border-top: 1px solid var(--lumiverse-border);
  border-bottom: 1px solid color-mix(in srgb, var(--lumiverse-border) 55%, transparent);
}

.compactBookHeading:first-child {
  border-top-color: transparent;
}

.compactBookHeading svg {
  flex: 0 0 auto;
  color: var(--lumiverse-primary-text, var(--lumiverse-primary));
}

.compactBookHeading strong {
  min-width: 0;
  overflow: hidden;
  font-size: calc(var(--lore-text-size, 12px) - 1px);
  font-weight: 650;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.compactEntry:hover {
  background: var(--lumiverse-fill-hover);
  border-color: var(--lumiverse-border);
}

.compactEntryName {
  min-width: 0;
  overflow: hidden;
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.compactTypeMarker {
  display: inline-flex;
  width: 15px;
  height: 15px;
  align-items: center;
  justify-content: center;
  font-size: calc(var(--lore-text-size, 12px) - 2px);
  font-weight: 700;
  line-height: 1;
  border-radius: 3px;
}

.compactTypeMarker[data-activation='constant'] {
  color: #f6b73c;
  background: color-mix(in srgb, #f59e0b 16%, transparent);
}

.compactTypeMarker[data-activation='sticky'] {
  color: #f48fb1;
  background: color-mix(in srgb, #ec4899 16%, transparent);
}

