import { useCallback, useEffect, useMemo, useRef, useState, type SetStateAction } from 'react'
import { createPortal } from 'react-dom'
import {
  ArrowDown,
  ArrowUp,
  BookOpen,
  ChevronDown,
  GripHorizontal,
  KeyRound,
  Pin,
  Search,
  Settings2,
  X,
} from 'lucide-react'
import { useStore } from '@/store'
import {
  DEFAULT_LORE_INDICATOR_SETTINGS,
  normalizeLoreIndicatorEntryTypeAppearance,
} from '@/lib/uiProductivityDefaults'
import { layoutElementSize, layoutViewportSize, toLayoutDelta } from '@/lib/zoomLayerGeometry'
import type { LoreIndicatorSettings } from '@/types/store'
import LoreIndicatorPanel, { openLoreEntry } from './LoreIndicatorPanel'
import { LumiverseSuiteGate } from '@/lib/spindle/LumiverseSuiteGate'
import {
  clampLoreFloatingPosition,
  clampLoreRect,
  formatCompactNumber,
  getConfiguredV4Items,
  getFloatingPanelPosition,
  matchesKeybind,
  type LoreItemId,
  type LorePoint,
  type LoreRect,
} from './utils'
import styles from './LoreIndicator.module.css'

const FLOATING_POSITION_KEY = 'lumiverse:lore-indicator:floating-position'
const V5_RECT_KEY = 'lumiverse:lore-indicator:v5-rect'

const ITEM_LABELS: Record<LoreItemId, string> = {
  'active-count': 'Active',
  'token-estimate': 'Tokens',
  passes: 'Passes',
  constant: 'Constant',
  keyword: 'Keyword',
  vector: 'Vector',
  lorebooks: 'Lorebooks',
  search: 'Search',
  grouping: 'Grouping',
}

/**
 * COORDINATE SPACE — read this before changing any number below.
 *
 * `theme/reset.css:187` applies `body > * { zoom: var(--lumiverse-ui-scale, 1) }`. V2's floating
 * root lives under `#root` and V5's palette is portalled to `document.body`; both are inside a
 * zoom layer, so two spaces are in play (see `@/lib/zoomLayerGeometry` for the measurements):
 *
 *   rendered px — `window.innerWidth/innerHeight`, `getBoundingClientRect()`, `event.clientX/Y`
 *   layout px   — `offsetWidth/offsetHeight`, and every `left/top/width/height` this file writes
 *                 into an inline `style` or persists to localStorage
 *
 * **This file speaks layout px throughout.** Rendered-px readings are converted at the boundary
 * they enter through and never again. Everything downstream — `floatingPosition`, `paletteRect`,
 * `viewport`, `compactPanelSize`, the two `localStorage` keys — is layout px.
 *
 * That is also why `layoutElementSize()` measures the trigger. This file used to read the *same*
 * element with `offsetWidth` in one place and `getBoundingClientRect()` in two others; those APIs
 * disagree by exactly the scale factor (measured: 72 vs 115.19 at scale 1.6), so the file
 * contradicted itself. `gBCR().width / scale === offsetWidth` at every scale, so one helper
 * serves all three sites. Do not "simplify" it back to either raw API.
 *
 * The pure helpers in `./utils` are unit-agnostic — they clamp in whatever space they are handed.
 * Do not push the conversion down into them.
 */

/** Size assumed for the V2/V5 trigger before it has been laid out. Layout px, like everything else. */
const FLOATING_FALLBACK_SIZE = { width: 72, height: 32 }

function readStoredPoint(): LorePoint {
  if (typeof window === 'undefined') return { x: 18, y: 96 }
  try {
    const parsed = JSON.parse(window.localStorage.getItem(FLOATING_POSITION_KEY) || '')
    return typeof parsed?.x === 'number' && typeof parsed?.y === 'number'
      ? parsed
      : { x: 18, y: 96 }
  } catch {
    return { x: 18, y: 96 }
  }
}

function readStoredPaletteRect(): LoreRect {
  const viewport = layoutViewportSize()
  const fallback = {
    width: Math.min(960, viewport.width - 32),
    height: Math.min(660, viewport.height - 32),
    x: Math.max(16, (viewport.width - Math.min(960, viewport.width - 32)) / 2),
    y: Math.max(16, (viewport.height - Math.min(660, viewport.height - 32)) / 2),
  }
  if (typeof window === 'undefined') return fallback
  try {
    const parsed = JSON.parse(window.localStorage.getItem(V5_RECT_KEY) || '')
    if (['x', 'y', 'width', 'height'].every((key) => typeof parsed?.[key] === 'number')) {
      return clampLoreRect(parsed, viewport)
    }
  } catch {
    // Use centered defaults.
  }
  return fallback
}

interface LoreIndicatorProps {
  open?: boolean
  onOpenChange?: (open: boolean) => void
}

export default function LoreIndicator(props: LoreIndicatorProps = {}) {
  return <LumiverseSuiteGate><LoreIndicatorSurface {...props} /></LumiverseSuiteGate>
}

function LoreIndicatorSurface({ open: controlledOpen, onOpenChange }: LoreIndicatorProps) {
  const entries = useStore((state) => state.activatedWorldInfo)
  const storedSettings = useStore((state) => state.loreIndicatorSettings)
  const settings = useMemo(() => ({
    ...storedSettings,
    entryTypeAppearance: normalizeLoreIndicatorEntryTypeAppearance(storedSettings.entryTypeAppearance),
  }), [storedSettings])
  const setSetting = useStore((state) => state.setSetting)
  const [localOpen, setLocalOpen] = useState(false)
  const open = controlledOpen ?? localOpen
  const setOpen = useCallback((next: SetStateAction<boolean>) => {
    if (controlledOpen === undefined) {
      setLocalOpen((current) => {
        const resolved = typeof next === 'function' ? next(current) : next
        onOpenChange?.(resolved)
        return resolved
      })
      return
    }
    const resolved = typeof next === 'function' ? next(controlledOpen) : next
    if (resolved !== controlledOpen) onOpenChange?.(resolved)
  }, [controlledOpen, onOpenChange])
  const [configOpen, setConfigOpen] = useState(false)
  const [viewport, setViewport] = useState(layoutViewportSize)
  const [floatingPosition, setFloatingPosition] = useState(readStoredPoint)
  const [paletteRect, setPaletteRect] = useState(readStoredPaletteRect)
  const floatingRef = useRef<HTMLDivElement>(null)
  const paletteRef = useRef<HTMLDivElement>(null)
  const hoverCloseTimer = useRef<number | null>(null)
  const suppressCompactClick = useRef(false)

  const updateSettings = (patch: Partial<LoreIndicatorSettings>) => {
    setSetting('loreIndicatorSettings', { ...settings, ...patch })
  }

  useEffect(() => {
    const onResize = () => {
      const nextViewport = layoutViewportSize()
      setViewport(nextViewport)
      setFloatingPosition((point) => clampLoreFloatingPosition(
        point,
        layoutElementSize(floatingRef.current, FLOATING_FALLBACK_SIZE),
        nextViewport,
      ))
      setPaletteRect((rect) => clampLoreRect(rect, nextViewport))
    }
    onResize()
    window.addEventListener('resize', onResize)
    return () => window.removeEventListener('resize', onResize)
  }, [])

  useEffect(() => {
    if (!settings.enabled || settings.variant !== 'v5-command-palette' || !settings.v5Keybind.trim()) return
    const onKeyDown = (event: KeyboardEvent) => {
      if (!matchesKeybind(event, settings.v5Keybind)) return
      event.preventDefault()
      setOpen(true)
    }
    document.addEventListener('keydown', onKeyDown)
    return () => document.removeEventListener('keydown', onKeyDown)
  }, [setOpen, settings.enabled, settings.variant, settings.v5Keybind])

  useEffect(() => {
    if (!open) return
    const onEscape = (event: KeyboardEvent) => {
      if (event.key === 'Escape') setOpen(false)
    }
    document.addEventListener('keydown', onEscape)
    return () => document.removeEventListener('keydown', onEscape)
  }, [open, setOpen])

  useEffect(() => () => {
    if (hoverCloseTimer.current != null) window.clearTimeout(hoverCloseTimer.current)
  }, [])

  const clampFloating = useCallback((point: LorePoint) => clampLoreFloatingPosition(
    point,
    layoutElementSize(floatingRef.current, FLOATING_FALLBACK_SIZE),
    layoutViewportSize(),
  ), [])

  const beginFloatingDrag = (event: React.PointerEvent<HTMLButtonElement>, clickCompatible = false) => {
    if (!clickCompatible) event.preventDefault()
    const pointerStart = { x: event.clientX, y: event.clientY }
    const positionStart = floatingPosition
    let moved = false
    const onMove = (moveEvent: PointerEvent) => {
      const clientDx = moveEvent.clientX - pointerStart.x
      const clientDy = moveEvent.clientY - pointerStart.y
      // The 4px slop stays in rendered px on purpose: it asks whether the user's hand moved,
      // which is a physical question, not a layout one.
      if (!moved && Math.hypot(clientDx, clientDy) < 4) return
      moved = true
      if (clickCompatible) suppressCompactClick.current = true
      const delta = toLayoutDelta(clientDx, clientDy)
      setFloatingPosition(clampFloating({
        x: positionStart.x + delta.x,
        y: positionStart.y + delta.y,
      }))
    }
    const onUp = () => {
      window.removeEventListener('pointermove', onMove)
      window.removeEventListener('pointerup', onUp)
      setFloatingPosition((point) => {
        const next = clampFloating(point)
        window.localStorage.setItem(FLOATING_POSITION_KEY, JSON.stringify(next))
        return next
      })
    }
    window.addEventListener('pointermove', onMove)
    window.addEventListener('pointerup', onUp)
  }

  const cancelHoverClose = () => {
    if (hoverCloseTimer.current != null) {
      window.clearTimeout(hoverCloseTimer.current)
      hoverCloseTimer.current = null
    }
  }

  const scheduleHoverClose = () => {
    if (settings.v2ActivationMode !== 'hover') return
    cancelHoverClose()
    hoverCloseTimer.current = window.setTimeout(() => setOpen(false), 120)
  }

  if (!settings.enabled) return null

  const commonStyle = {
    '--lore-icon-size': `${settings.iconSize}px`,
    '--lore-text-size': `${settings.textSize}px`,
  } as React.CSSProperties

  // The V4 strip renders in place, as a plain child of whatever dock ChatView mounts
  // this component into. It deliberately knows nothing about that host.
  if (settings.variant === 'v4-bottom-strip') {
    return (
      <V4Strip
        style={commonStyle}
        settings={settings}
        open={open}
        configOpen={configOpen}
        setOpen={setOpen}
        setConfigOpen={setConfigOpen}
        updateSettings={updateSettings}
      />
    )
  }

  const compactAvailableHeight = Math.max(240, viewport.height - 24)
  const compactRowsPerColumn = Math.max(1, Math.floor((compactAvailableHeight - 71) / 24))
  const compactMaxColumns = Math.max(1, Math.floor((viewport.width - 24) / 240))
  const compactBookCount = settings.v2BookDisplay === 'grouped'
    ? new Set(entries.map((entry) => entry.bookName || entry.bookId)).size
    : 0
  const compactItemCount = entries.length + compactBookCount
  const compactColumns = Math.min(
    compactMaxColumns,
    Math.max(1, Math.ceil(compactItemCount / compactRowsPerColumn)),
  )
  const compactRows = Math.max(1, Math.ceil(compactItemCount / compactColumns))
  const compactPanelSize = {
    width: Math.min(viewport.width - 24, Math.max(360, compactColumns * 240)),
    height: Math.min(compactAvailableHeight, 71 + compactRows * 24),
  }
  const compactPanelPosition = getFloatingPanelPosition(
    floatingPosition,
    layoutElementSize(floatingRef.current, FLOATING_FALLBACK_SIZE),
    compactPanelSize,
    viewport,
  )

  return (
    <>
      <div
        ref={floatingRef}
        className={styles.floatingRoot}
        style={{ ...commonStyle, left: floatingPosition.x, top: floatingPosition.y }}
        data-variant={settings.variant}
      >
        {settings.variant !== 'v2-compact' && (
          <button type="button" className={styles.dragHandle} onPointerDown={beginFloatingDrag} aria-label="Move lore indicator">
            <GripHorizontal size={14} />
          </button>
        )}

        {settings.variant === 'v2-compact' ? (
          <div
            className={styles.v2Wrap}
            onMouseEnter={() => {
              cancelHoverClose()
              if (settings.v2ActivationMode === 'hover') setOpen(true)
            }}
            onMouseLeave={scheduleHoverClose}
          >
            <button
              type="button"
              className={styles.compactTrigger}
              onPointerDown={(event) => beginFloatingDrag(event, true)}
              onClick={() => {
                if (suppressCompactClick.current) {
                  suppressCompactClick.current = false
                  return
                }
                setOpen((value) => !value)
              }}
              title="Activated lore"
            >
              <BookOpen size={settings.iconSize} />
              <span>{entries.length}</span>
            </button>
          </div>
        ) : (
          <button type="button" className={styles.paletteTrigger} onClick={() => setOpen(true)} title={settings.v5Keybind || 'Open activated lore'}>
            <BookOpen size={settings.iconSize} />
            <span>{entries.length}</span>
          </button>
        )}
      </div>

      {open && settings.variant === 'v2-compact' && createPortal(
        <div
          className={styles.compactPopover}
          style={{
            ...commonStyle,
            left: compactPanelPosition.x,
            top: compactPanelPosition.y,
            width: compactPanelSize.width,
            height: compactPanelSize.height,
            '--compact-columns': compactColumns,
            '--compact-rows': compactRows,
          } as React.CSSProperties}
          onMouseEnter={cancelHoverClose}
          onMouseLeave={scheduleHoverClose}
        >
          <LoreIndicatorPanel
            mode="compact"
            onNavigate={() => setOpen(false)}
            onMovePointerDown={beginFloatingDrag}
            onHide={() => setOpen(false)}
          />
        </div>,
        document.body,
      )}

      {open && settings.variant === 'v5-command-palette' && createPortal(
        <div className={styles.paletteLayer}>
          <div
            ref={paletteRef}
            className={styles.paletteDialog}
            style={{
              ...commonStyle,
              left: paletteRect.x,
              top: paletteRect.y,
              width: paletteRect.width,
              height: paletteRect.height,
            }}
          >
            <div
              className={styles.paletteDragBar}
              onPointerDown={(event) => beginPaletteDrag(event, paletteRect, setPaletteRect)}
            >
              <GripHorizontal size={15} />
              <span>Activated Lore</span>
              <button type="button" onPointerDown={(event) => event.stopPropagation()} onClick={() => setOpen(false)} aria-label="Close lore command palette">
                <X size={17} />
              </button>
            </div>
            <div className={styles.paletteContent}>
              <LoreIndicatorPanel mode="palette" onNavigate={() => setOpen(false)} />
            </div>
            <button
              type="button"
              className={styles.resizeHandle}
              aria-label="Resize lore command palette"
              onPointerDown={(event) => beginPaletteResize(event, paletteRect, setPaletteRect)}
            />
          </div>
        </div>,
        document.body,
      )}
    </>
  )
}

function persistPaletteRect(rect: LoreRect) {
  window.localStorage.setItem(V5_RECT_KEY, JSON.stringify(rect))
}

function beginPaletteDrag(
  event: React.PointerEvent<HTMLDivElement>,
  startRect: LoreRect,
  setRect: React.Dispatch<React.SetStateAction<LoreRect>>,
) {
  if ((event.target as HTMLElement).closest('button')) return
  event.preventDefault()
  const start = { x: event.clientX, y: event.clientY }
  const onMove = (moveEvent: PointerEvent) => {
    const delta = toLayoutDelta(moveEvent.clientX - start.x, moveEvent.clientY - start.y)
    setRect(clampLoreRect({
      ...startRect,
      x: startRect.x + delta.x,
      y: startRect.y + delta.y,
    }, layoutViewportSize()))
  }
  const onUp = () => {
    window.removeEventListener('pointermove', onMove)
    window.removeEventListener('pointerup', onUp)
    setRect((rect) => {
      const next = clampLoreRect(rect, layoutViewportSize())
      persistPaletteRect(next)
      return next
    })
  }
  window.addEventListener('pointermove', onMove)
  window.addEventListener('pointerup', onUp)
}

function beginPaletteResize(
  event: React.PointerEvent<HTMLButtonElement>,
  startRect: LoreRect,
  setRect: React.Dispatch<React.SetStateAction<LoreRect>>,
) {
  event.preventDefault()
  const start = { x: event.clientX, y: event.clientY }
  const onMove = (moveEvent: PointerEvent) => {
    const delta = toLayoutDelta(moveEvent.clientX - start.x, moveEvent.clientY - start.y)
    setRect(clampLoreRect({
      ...startRect,
      width: startRect.width + delta.x,
      height: startRect.height + delta.y,
    }, layoutViewportSize()))
  }
  const onUp = () => {
    window.removeEventListener('pointermove', onMove)
    window.removeEventListener('pointerup', onUp)
    setRect((rect) => {
      const next = clampLoreRect(rect, layoutViewportSize())
      persistPaletteRect(next)
      return next
    })
  }
  window.addEventListener('pointermove', onMove)
  window.addEventListener('pointerup', onUp)
}

function V4Strip({
  style,
  settings,
  open,
  configOpen,
  setOpen,
  setConfigOpen,
  updateSettings,
}: {
  style?: React.CSSProperties
  settings: LoreIndicatorSettings
  open: boolean
  configOpen: boolean
  setOpen: React.Dispatch<React.SetStateAction<boolean>>
  setConfigOpen: React.Dispatch<React.SetStateAction<boolean>>
  updateSettings: (patch: Partial<LoreIndicatorSettings>) => void
}) {
  const entries = useStore((state) => state.activatedWorldInfo)
  const stats = useStore((state) => state.worldInfoStats)

  const counts = useMemo(() => ({
    constant: entries.filter((entry) => entry.activationType === 'constant').length,
    keyword: entries.filter((entry) => entry.activationType === 'keyword').length,
    vector: entries.filter((entry) => entry.activationType === 'vector').length,
    lorebooks: new Set(entries.map((entry) => entry.bookId)).size,
  }), [entries])

  const values: Record<LoreItemId, string> = {
    'active-count': String(entries.length),
    'token-estimate': formatCompactNumber(stats?.estimatedTokens ?? 0),
    passes: String(stats?.recursionPassesUsed ?? 0),
    constant: String(counts.constant),
    keyword: String(counts.keyword),
    vector: String(counts.vector),
    lorebooks: String(counts.lorebooks),
    search: '',
    grouping: '',
  }
  const icons: Record<LoreItemId, React.ReactNode> = {
    'active-count': <BookOpen />,
    'token-estimate': <span>#</span>,
    passes: <span aria-hidden="true">△</span>,
    constant: <Pin />,
    keyword: <KeyRound />,
    vector: <Search />,
    lorebooks: <BookOpen />,
    search: <Search />,
    grouping: <span aria-hidden="true">≡</span>,
  }
  const items = getConfiguredV4Items(settings).filter((item) => item.visible && !item.removed)
  const activationForItem = (id: LoreItemId) =>
    id === 'constant' || id === 'keyword' || id === 'vector' ? id : undefined

  return (
    <div className={styles.composerRoot} style={style}>
      <div className={styles.strip} style={{ gap: settings.v4Spacing }}>
        {items.map((item) => (
          <button
            type="button"
            key={item.id}
            className={styles.stripItem}
            data-activation={activationForItem(item.id as LoreItemId)}
            onClick={() => setOpen((value) => !value)}
            title={`${values[item.id as LoreItemId]} ${ITEM_LABELS[item.id as LoreItemId]}`.trim()}
          >
            {icons[item.id as LoreItemId]}
            {item.mode === 'iconText' && <span>{values[item.id as LoreItemId]} {ITEM_LABELS[item.id as LoreItemId]}</span>}
          </button>
        ))}
        <button type="button" className={styles.stripItem} onClick={() => setConfigOpen((value) => !value)} title="Configure lore indicator">
          <Settings2 />
        </button>
        <button type="button" className={styles.stripItem} onClick={() => setOpen((value) => !value)} title="Toggle activated lore">
          <ChevronDown className={open ? styles.chevronOpen : undefined} />
        </button>
      </div>

      {/* Both popovers are absolutely positioned siblings of the strip, opening upward
          inside this root. Nothing crosses the `body > * { zoom }` boundary, so there is
          no UI-scale drift to compensate for. */}
      {open && (
        <div className={styles.v4PanelPopover}>
          <LoreIndicatorPanel
            mode="expanded"
            activateOnClick
            groupBy={settings.v4GroupBy ?? 'lorebook'}
            previewCount={settings.v4BookPreviewCount ?? 4}
            onOpenFullView={(entry) => {
              setOpen(false)
              if (entry) {
                openLoreEntry(entry)
                return
              }
              useStore.getState().openDrawer('lorebook')
            }}
          />
        </div>
      )}

      {configOpen && (
        <div className={styles.v4ConfigPopover}>
          <LoreIndicatorConfig settings={settings} updateSettings={updateSettings} onClose={() => setConfigOpen(false)} />
        </div>
      )}
    </div>
  )
}

function LoreIndicatorConfig({
  settings,
  updateSettings,
  onClose,
}: {
  settings: LoreIndicatorSettings
  updateSettings: (patch: Partial<LoreIndicatorSettings>) => void
  onClose: () => void
}) {
  const items = getConfiguredV4Items(settings)
  const [draggedId, setDraggedId] = useState<string | null>(null)
  const patchItems = (nextItems: typeof items) => updateSettings({
    v4Items: nextItems.map((item, order) => ({ ...item, order })),
  })
  const move = (index: number, delta: number) => {
    const target = index + delta
    if (target < 0 || target >= items.length) return
    const next = [...items]
    ;[next[index], next[target]] = [next[target], next[index]]
    patchItems(next)
  }
  const dropBefore = (targetId: string) => {
    if (!draggedId || draggedId === targetId) return
    const next = items.filter((item) => item.id !== draggedId)
    const dragged = items.find((item) => item.id === draggedId)
    const targetIndex = next.findIndex((item) => item.id === targetId)
    if (!dragged || targetIndex < 0) return
    next.splice(targetIndex, 0, dragged)
    patchItems(next)
    setDraggedId(null)
  }

  return (
    <div className={styles.config}>
      <div className={styles.configHeader}><strong>Lore Indicator</strong><button type="button" onClick={onClose}><X size={15} /></button></div>
      <label>Item spacing <input type="range" min="2" max="24" value={settings.v4Spacing} onChange={(event) => updateSettings({ v4Spacing: Number(event.target.value) })} /></label>
      <label>
        Group entries by
        <select
          value={settings.v4GroupBy ?? 'lorebook'}
          onChange={(event) => updateSettings({ v4GroupBy: event.target.value as LoreIndicatorSettings['v4GroupBy'] })}
        >
          <option value="lorebook">Lorebook</option>
          <option value="type">Activation type</option>
          <option value="none">No grouping</option>
        </select>
      </label>
      <label>
        Entries before “more”
        <input
          type="number"
          min="1"
          max="50"
          value={settings.v4BookPreviewCount ?? 4}
          onChange={(event) => updateSettings({ v4BookPreviewCount: Math.max(1, Number(event.target.value) || 1) })}
        />
      </label>
      <div className={styles.configItems}>
        {items.map((item, index) => (
          <div
            key={item.id}
            className={styles.configItem}
            draggable
            onDragStart={() => setDraggedId(item.id)}
            onDragEnd={() => setDraggedId(null)}
            onDragOver={(event) => event.preventDefault()}
            onDrop={() => dropBefore(item.id)}
          >
            <input
              type="checkbox"
              checked={item.visible && !item.removed}
              onChange={(event) => patchItems(items.map((current) => current.id === item.id ? { ...current, visible: event.target.checked, removed: false } : current))}
            />
            <span>{ITEM_LABELS[item.id as LoreItemId]}</span>
            <select value={item.mode} onChange={(event) => patchItems(items.map((current) => current.id === item.id ? { ...current, mode: event.target.value as 'icon' | 'iconText' } : current))}>
              <option value="iconText">Icon + text</option>
              <option value="icon">Icon only</option>
            </select>
            <button type="button" onClick={() => move(index, -1)} disabled={index === 0}><ArrowUp size={12} /></button>
            <button type="button" onClick={() => move(index, 1)} disabled={index === items.length - 1}><ArrowDown size={12} /></button>
            <button type="button" onClick={() => patchItems(items.map((current) => current.id === item.id ? { ...current, removed: true, visible: false } : current))}>Remove</button>
          </div>
        ))}
      </div>
      <div className={styles.resetRow}>
        <button
          type="button"
          onClick={() => updateSettings({
            v4Items: DEFAULT_LORE_INDICATOR_SETTINGS.v4Items.map((item) => ({ ...item })),
            v4Spacing: DEFAULT_LORE_INDICATOR_SETTINGS.v4Spacing,
            v4GroupBy: DEFAULT_LORE_INDICATOR_SETTINGS.v4GroupBy,
            v4BookPreviewCount: DEFAULT_LORE_INDICATOR_SETTINGS.v4BookPreviewCount,
          })}
        >
          Reset strip
        </button>
      </div>
    </div>
  )
}

import { useEffect, useMemo, useRef, useState } from 'react'
import {
  BookOpen,
  CaseSensitive,
  Clock,
  ExternalLink,
  EyeOff,
  GripVertical,
  KeyRound,
  PanelRightOpen,
  Pin,
  Search,
  Shapes,
  Sparkles,
} from 'lucide-react'
import { useStore } from '@/store'
import { normalizeLoreIndicatorEntryTypeAppearance } from '@/lib/uiProductivityDefaults'
import { launchLorebookEditor } from '@/lib/lorebookLauncher'
import type { ActivatedWorldInfoEntry } from '@/types/api'
import type { LoreIndicatorGroupBy } from '@/types/store'
import {
  buildLoreScanText,
  formatCompactNumber,
  getActivationContext,
  getLastScannedSentence,
  searchLoreEntries,
  type LoreActivationContext,
} from './utils'
import styles from './LoreIndicator.module.css'

interface LoreIndicatorPanelProps {
  mode?: 'compact' | 'expanded' | 'palette'
  onNavigate?: () => void
  onMovePointerDown?: (event: React.PointerEvent<HTMLButtonElement>) => void
  onHide?: () => void
  /** V4 only: how the expanded grid groups entries. */
  groupBy?: LoreIndicatorGroupBy
  /** V4 only: entries listed per group before the "+N more" affordance. */
  previewCount?: number
  onOpenFullView?: (entry: ActivatedWorldInfoEntry | null) => void
  /**
   * Open the entry in the editor on a single click instead of selecting it.
   * The V4 popover has no detail pane, so clicking through is the only useful
   * action there; the drawer's Activated Lore tab keeps select-then-double-click.
   */
  activateOnClick?: boolean
}

const TYPE_ICONS = {
  constant: Pin,
  sticky: Clock,
  keyword: KeyRound,
  vector: Search,
}

const CONFIGURED_ICONS = {
  pin: Pin,
  key: KeyRound,
  search: Search,
  book: BookOpen,
  sparkles: Sparkles,
}

const ACTIVATION_TYPES = ['constant', 'sticky', 'keyword', 'vector'] as const
type ActivationType = (typeof ACTIVATION_TYPES)[number]
const TYPE_LABELS: Record<ActivationType, string> = {
  constant: 'Constant',
  sticky: 'Sticky',
  keyword: 'Keyword',
  vector: 'Vector',
}

function normalizeActivationType(value: unknown): ActivationType {
  return ACTIVATION_TYPES.includes(value as ActivationType) ? value as ActivationType : 'keyword'
}

const COMPACT_TYPE_DISPLAY_KEY = 'lumiverse:lore-indicator:v2-type-display'

function readCompactTypeDisplay(): 'letters' | 'icons' {
  if (typeof window === 'undefined') return 'letters'
  return window.localStorage.getItem(COMPACT_TYPE_DISPLAY_KEY) === 'icons' ? 'icons' : 'letters'
}

function getCompactBookLabel(bookName: string) {
  const withoutTimestamp = bookName.replace(/\s+-\s+\d{4}-\d{2}-\d{2}.*$/, '').trim()
  if (/^ltm\b/i.test(withoutTimestamp)) return 'LTM'
  const parts = withoutTimestamp.split(/\s+-\s+/).filter(Boolean)
  const label = parts.length > 1 ? parts.at(-1)! : withoutTimestamp
  return label.replace(/^the\s+/i, '').trim() || bookName
}

function getCompactBookMarker(bookName: string) {
  const words = getCompactBookLabel(bookName).split(/\s+/).filter(Boolean)
  return words.slice(0, 2).map((word) => word[0]).join('').toUpperCase() || 'B'
}

export function openNativeLoreEntry(entry: ActivatedWorldInfoEntry): void {
  const state = useStore.getState()
  state.setPendingWorldBookEditId(entry.bookId)
  state.setPendingWorldBookEditEntryId(entry.id)
  state.openDrawer('lorebook')
}

export function openLoreEntry(entry: ActivatedWorldInfoEntry): void {
  if (launchLorebookEditor({ bookId: entry.bookId, entryId: entry.id })) return
  openNativeLoreEntry(entry)
}

/**
 * Text the activation scan ran against. The payload carries no per-entry
 * excerpt, so the trigger sentence is derived from the generation query plus the
 * most recent messages.
 */
export function useLoreScanText(): string {
  const queryPreview = useStore((state) => state.worldInfoStats?.queryPreview)
  const messages = useStore((state) => state.messages)
  return useMemo(() => buildLoreScanText(queryPreview, messages), [messages, queryPreview])
}

export default function LoreIndicatorPanel({
  mode = 'expanded',
  onNavigate,
  onMovePointerDown,
  onHide,
  groupBy = 'lorebook',
  previewCount = 4,
  onOpenFullView,
  activateOnClick = false,
}: LoreIndicatorPanelProps) {
  const entries = useStore((state) => state.activatedWorldInfo)
  const stats = useStore((state) => state.worldInfoStats)
  const tokenBudget = useStore((state) => state.worldInfoSettings.maxTokenBudget)
  const storedSettings = useStore((state) => state.loreIndicatorSettings)
  const settings = useMemo(() => ({
    ...storedSettings,
    entryTypeAppearance: normalizeLoreIndicatorEntryTypeAppearance(storedSettings.entryTypeAppearance),
  }), [storedSettings])
  const editorSettings = useStore((state) => state.lorebookEditorSettings)
  const scanText = useLoreScanText()
  const [query, setQuery] = useState('')
  const [typeFilter, setTypeFilter] = useState<'all' | ActivationType>('all')
  const [expandedGroups, setExpandedGroups] = useState<string[]>([])
  const [selectedId, setSelectedId] = useState<string | null>(entries[0]?.id ?? null)
  const [compactTypeDisplay, setCompactTypeDisplay] = useState(readCompactTypeDisplay)
  const panelRef = useRef<HTMLDivElement | null>(null)
  const compact = mode === 'compact'

  const contexts = useMemo(
    () => new Map<string, LoreActivationContext>(
      entries.map((entry) => [entry.id, getActivationContext(entry, scanText)]),
    ),
    [entries, scanText],
  )

  const filteredEntries = useMemo(() => {
    const searched = searchLoreEntries(entries, query)
    return typeFilter === 'all'
      ? searched
      : searched.filter((entry) => entry.activationType === typeFilter)
  }, [entries, query, typeFilter])
  const visibleEntries = filteredEntries
  const selected = visibleEntries.find((entry) => entry.id === selectedId) ?? visibleEntries[0] ?? null
  const counts = useMemo(() => ({
    constant: entries.filter((entry) => entry.activationType === 'constant').length,
    sticky: entries.filter((entry) => entry.activationType === 'sticky').length,
    keyword: entries.filter((entry) => entry.activationType === 'keyword').length,
    vector: entries.filter((entry) => entry.activationType === 'vector').length,
  }), [entries])

  useEffect(() => {
    if (selected && selected.id !== selectedId) setSelectedId(selected.id)
  }, [selected, selectedId])

  // Arrow-key navigation and Enter/⌘Enter shortcuts for the V5 palette.
  //
  // Scoped to the palette subtree: the palette layer does not block pointer
  // events, so a document-wide listener would swallow Enter in the chat composer
  // while the palette happened to be open.
  useEffect(() => {
    if (mode !== 'palette') return
    const onKeyDown = (event: KeyboardEvent) => {
      if (visibleEntries.length === 0) return
      const target = event.target as Node | null
      if (!target || !panelRef.current?.contains(target)) return
      if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
        event.preventDefault()
        const index = visibleEntries.findIndex((entry) => entry.id === selected?.id)
        const next = event.key === 'ArrowDown'
          ? Math.min(visibleEntries.length - 1, index + 1)
          : Math.max(0, index - 1)
        setSelectedId(visibleEntries[next]?.id ?? null)
        return
      }
      if (event.key === 'Enter' && selected) {
        event.preventDefault()
        if ((event.metaKey || event.ctrlKey) && editorSettings.loreIndicatorActionEnabled) {
          if (!launchLorebookEditor({
            bookId: selected.bookId,
            entryId: selected.id,
            preferredTarget: 'half',
            source: 'half_editor',
          })) {
            openNativeLoreEntry(selected)
          }
        } else {
          openLoreEntry(selected)
        }
        onNavigate?.()
      }
    }
    document.addEventListener('keydown', onKeyDown)
    return () => document.removeEventListener('keydown', onKeyDown)
  }, [
    editorSettings.loreIndicatorActionEnabled,
    mode,
    onNavigate,
    selected,
    visibleEntries,
  ])

  const groups = useMemo(() => {
    const grouped = new Map<string, ActivatedWorldInfoEntry[]>()
    for (const entry of visibleEntries) {
      const label = mode === 'expanded' && groupBy === 'type'
        ? TYPE_LABELS[normalizeActivationType(entry.activationType)]
        : mode === 'expanded' && groupBy === 'none'
          ? 'Activated entries'
          : entry.bookName || entry.bookId
      grouped.set(label, [...(grouped.get(label) ?? []), entry])
    }
    return [...grouped.entries()]
  }, [groupBy, mode, visibleEntries])

  const navigate = (entry: ActivatedWorldInfoEntry) => {
    openLoreEntry(entry)
    onNavigate?.()
  }

  const openHalfEditor = (entry: ActivatedWorldInfoEntry) => {
    if (!launchLorebookEditor({
      bookId: entry.bookId,
      entryId: entry.id,
      preferredTarget: 'half',
      source: 'half_editor',
    })) {
      openNativeLoreEntry(entry)
    }
    onNavigate?.()
  }

  const panelClassName = compact
    ? styles.compactPanel
    : mode === 'palette'
      ? `${styles.panel} ${styles.palettePanel}`
      : `${styles.panel} ${styles.expandedPanel}`

  const typeFilterRow = (
    <div className={styles.typeChips} role="group" aria-label="Filter by activation type">
      <button
        type="button"
        className={styles.typeChip}
        data-active={typeFilter === 'all' || undefined}
        aria-pressed={typeFilter === 'all'}
        onClick={() => setTypeFilter('all')}
      >
        All<b>{entries.length}</b>
      </button>
      {ACTIVATION_TYPES.map((type) => {
        const appearance = settings.entryTypeAppearance[type]
        const Icon = CONFIGURED_ICONS[appearance.icon as keyof typeof CONFIGURED_ICONS] ?? TYPE_ICONS[type]
        return (
          <button
            key={type}
            type="button"
            className={styles.typeChip}
            data-activation={type}
            data-active={typeFilter === type || undefined}
            aria-pressed={typeFilter === type}
            onClick={() => setTypeFilter(type)}
          >
            <Icon size={12} style={{ color: appearance.color }} />
            {TYPE_LABELS[type]}<b>{counts[type]}</b>
          </button>
        )
      })}
    </div>
  )

  return (
    <div
      ref={panelRef}
      className={panelClassName}
      data-panel-mode={mode}
      style={{
        '--lore-icon-size': `${settings.iconSize}px`,
        '--lore-text-size': `${settings.textSize}px`,
      } as React.CSSProperties}
    >
      {compact ? (
        <div className={styles.compactHeader}>
          <strong>Lore {entries.length}</strong>
          <span className={styles.compactTypeCount} data-activation="constant">Constant {counts.constant}</span>
          <span className={styles.compactTypeCount} data-activation="sticky">Sticky {counts.sticky}</span>
          <span className={styles.compactTypeCount} data-activation="keyword">Keyword {counts.keyword}</span>
          <span className={styles.compactTypeCount} data-activation="vector">Vector {counts.vector}</span>
          <span className={styles.compactPasses}>{stats?.recursionPassesUsed ?? 0} passes</span>
          <button
            type="button"
            className={styles.compactDisplayToggle}
            onClick={() => {
              const next = compactTypeDisplay === 'letters' ? 'icons' : 'letters'
              setCompactTypeDisplay(next)
              window.localStorage.setItem(COMPACT_TYPE_DISPLAY_KEY, next)
            }}
            title={compactTypeDisplay === 'letters' ? 'Use type icons' : 'Use type letters'}
            aria-label={compactTypeDisplay === 'letters' ? 'Use type icons' : 'Use type letters'}
          >
            {compactTypeDisplay === 'letters' ? <Shapes size={14} /> : <CaseSensitive size={15} />}
          </button>
        </div>
      ) : (
        <div className={styles.panelHeader}>
          <span className={styles.panelHeaderIcon}><BookOpen size={16} /></span>
          <div className={styles.panelHeaderIdentity}>
            <strong>
              Activated Lore
              <b className={styles.panelHeaderBadge}>{entries.length}</b>
            </strong>
            <span>
              Last generation
              {' • '}
              {formatCompactNumber(stats?.estimatedTokens ?? 0)} tokens
              {' • '}
              {stats?.recursionPassesUsed ?? 0} {stats?.recursionPassesUsed === 1 ? 'pass' : 'passes'}
            </span>
          </div>
          {mode === 'expanded' && onOpenFullView && (
            <button type="button" className={styles.panelHeaderAction} onClick={() => onOpenFullView(selected)}>
              <ExternalLink size={13} /> Open full view
            </button>
          )}
        </div>
      )}

      {mode === 'palette' && (
        <div className={styles.paletteControls}>
          <label className={styles.searchBox}>
            <Search size={14} />
            <input
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              placeholder="Search entries, books, triggers..."
              autoFocus
            />
          </label>
          {typeFilterRow}
        </div>
      )}

      {mode === 'expanded' && typeFilterRow}

      <div className={compact ? styles.compactList : mode === 'palette' ? styles.panelBody : styles.expandedBody}>
        {compact ? (
          <div className={styles.compactEntries}>
            {(settings.v2BookDisplay === 'grouped'
              ? groups.flatMap(([bookName, bookEntries]) => [
                  { kind: 'book' as const, bookName, id: `book:${bookName}` },
                  ...bookEntries.map((entry) => ({ kind: 'entry' as const, entry, id: entry.id })),
                ])
              : visibleEntries.map((entry) => ({ kind: 'entry' as const, entry, id: entry.id })))
              .map((item, index, items) => {
              if (item.kind === 'book') {
                return (
                  <div key={item.id} className={styles.compactBookHeading} title={item.bookName}>
                    <BookOpen size={11} />
                    <strong>{getCompactBookLabel(item.bookName)}</strong>
                  </div>
                )
              }

              const entry = item.entry
              const activationType = normalizeActivationType(entry.activationType)
              const appearance = settings.entryTypeAppearance[activationType]
              const TypeIcon = CONFIGURED_ICONS[appearance.icon as keyof typeof CONFIGURED_ICONS] ?? TYPE_ICONS[activationType]
              const triggerPhrase = contexts.get(entry.id)?.exactTriggerPhrase ?? null
              const entryName = entry.comment || 'Unnamed entry'
              const bookName = entry.bookName || entry.bookId
              const compactBookLabel = getCompactBookLabel(bookName)
              const previousItem = index > 0 ? items[index - 1] : null
              const previousEntry = previousItem?.kind === 'entry'
                ? previousItem.entry
                : null
              const showFirstOnlyBook = settings.v2BookDisplay === 'first-only'
                && (!previousEntry || (previousEntry.bookName || previousEntry.bookId) !== bookName)
              const activationMarker = entry.activationType === 'constant'
                ? 'C'
                : entry.activationType === 'sticky'
                  ? 'S'
                  : entry.activationType === 'keyword'
                    ? 'K'
                    : 'V'
              const activationDetail = entry.activationType === 'vector' && entry.score != null
                ? ` / score ${entry.score.toFixed(2)}`
                : entry.activationType === 'keyword' && triggerPhrase
                  ? ` / trigger "${triggerPhrase}"`
                  : ''
              return (
                <button
                  type="button"
                  key={entry.id}
                  className={styles.compactEntry}
                  data-activation={entry.activationType}
                  data-book-display={settings.v2BookDisplay}
                  onClick={() => navigate(entry)}
                  title={`${entryName} / ${bookName} / ${entry.activationType}${activationDetail}`}
                >
                  <span
                    className={styles.compactTypeMarker}
                    data-activation={entry.activationType}
                    data-display={compactTypeDisplay}
                  >
                    {compactTypeDisplay === 'icons'
                      ? <TypeIcon size={11} style={{ color: appearance.color }} />
                      : activationMarker}
                  </span>
                  <strong className={styles.compactEntryName}>{entryName}</strong>
                  {settings.v2BookDisplay === 'first-only' && (
                    <span
                      className={styles.compactBookChip}
                      data-empty={!showFirstOnlyBook || undefined}
                      title={showFirstOnlyBook ? bookName : undefined}
                    >
                      {showFirstOnlyBook ? compactBookLabel : ''}
                    </span>
                  )}
                  {settings.v2BookDisplay === 'markers' && (
                    <span className={styles.compactBookMarker} title={bookName}>{getCompactBookMarker(bookName)}</span>
                  )}
                  {settings.visibleMetadata.includes('tokens') && (
                    <strong className={styles.compactEntryTokens}>{formatCompactNumber(entry.estimatedTokens)}</strong>
                  )}
                </button>
              )
            })}
            {visibleEntries.length === 0 && <div className={styles.empty}>No activated lore entries.</div>}
          </div>
        ) : (
          <div className={styles.entryList}>
            {groups.map(([groupName, groupEntries]) => {
              const expanded = mode !== 'expanded' || expandedGroups.includes(groupName)
              const shown = expanded ? groupEntries : groupEntries.slice(0, Math.max(1, previewCount))
              const hidden = groupEntries.length - shown.length
              return (
                <section key={groupName} className={styles.bookGroup}>
                  <div className={styles.bookHeading}>
                    <BookOpen size={14} />
                    <span title={groupName}>{settings.visibleMetadata.includes('book') ? groupName : 'Activated entries'}</span>
                    <b>{groupEntries.length}</b>
                  </div>
                  {shown.map((entry) => {
                    const activationType = normalizeActivationType(entry.activationType)
                    const appearance = settings.entryTypeAppearance[activationType]
                    const TypeIcon = CONFIGURED_ICONS[appearance.icon as keyof typeof CONFIGURED_ICONS] ?? TYPE_ICONS[activationType]
                    const triggerPhrase = contexts.get(entry.id)?.exactTriggerPhrase ?? null
                    return (
                      <button
                        type="button"
                        key={entry.id}
                        className={entry.id === selected?.id ? styles.entryActive : styles.entry}
                        data-activation={entry.activationType}
                        onClick={() => activateOnClick ? navigate(entry) : setSelectedId(entry.id)}
                        onDoubleClick={() => navigate(entry)}
                      >
                        <TypeIcon size={settings.iconSize} style={{ color: appearance.color }} />
                        <span className={styles.entryIdentity}>
                          <strong>{entry.comment || 'Unnamed entry'}</strong>
                          <small>
                            {settings.visibleMetadata.includes('type') && (
                              <span className={styles.typeLabel} data-activation={entry.activationType}>{entry.activationType}</span>
                            )}
                            {settings.visibleMetadata.includes('trigger') && triggerPhrase ? ` / trigger: "${triggerPhrase}"` : ''}
                            {entry.score != null ? ` / ${entry.score.toFixed(2)}` : ''}
                          </small>
                        </span>
                        {settings.visibleMetadata.includes('tokens') && (
                          <span className={styles.entryTokens}>{formatCompactNumber(entry.estimatedTokens)}</span>
                        )}
                      </button>
                    )
                  })}
                  {hidden > 0 && (
                    <button
                      type="button"
                      className={styles.moreEntries}
                      onClick={() => setExpandedGroups((current) => [...current, groupName])}
                    >
                      + {hidden} more {hidden === 1 ? 'entry' : 'entries'}
                    </button>
                  )}
                </section>
              )
            })}
            {visibleEntries.length === 0 && <div className={styles.empty}>No activated lore matches this search.</div>}
          </div>
        )}

        {mode === 'palette' && selected && (
          <ActivationDetail
            entry={selected}
            context={contexts.get(selected.id) ?? getActivationContext(selected, scanText)}
            scanText={scanText}
            showHalfEditor={editorSettings.loreIndicatorActionEnabled}
            onHalfEditor={() => openHalfEditor(selected)}
            onOpen={() => navigate(selected)}
          />
        )}
      </div>

      {mode === 'palette' && settings.v5ShowShortcutHints !== false && (
        <div className={styles.paletteFooter}>
          <span><kbd>↑</kbd><kbd>↓</kbd> Navigate</span>
          <span><kbd>↵</kbd> Open</span>
          {editorSettings.loreIndicatorActionEnabled && <span><kbd>Ctrl</kbd><kbd>↵</kbd> Half editor</span>}
          <span><kbd>esc</kbd> Close</span>
        </div>
      )}

      {compact && (
        <div className={styles.compactFooter}>
          <div className={styles.compactTokenMetric}>
            <strong>
              {formatCompactNumber(stats?.estimatedTokens ?? 0)}
              {tokenBudget > 0 ? ` / ${formatCompactNumber(tokenBudget)}` : ''}
            </strong>
            <span className={styles.compactProgress} aria-hidden="true">
              <span
                style={{
                  width: `${tokenBudget > 0
                    ? Math.min(100, ((stats?.estimatedTokens ?? 0) / tokenBudget) * 100)
                    : 100}%`,
                }}
              />
            </span>
          </div>
          <div className={styles.compactActions}>
            {onMovePointerDown && (
              <button type="button" onPointerDown={onMovePointerDown} title="Drag to move" aria-label="Drag to move">
                <GripVertical size={14} />
              </button>
            )}
            {onHide && (
              <button type="button" onClick={onHide} title="Hide" aria-label="Hide">
                <EyeOff size={14} />
              </button>
            )}
            {selected && editorSettings.loreIndicatorActionEnabled && (
              <button type="button" onClick={() => openHalfEditor(selected)} title="Half-Screen Lorebook Editor" aria-label="Half-Screen Lorebook Editor">
                <PanelRightOpen size={14} />
              </button>
            )}
          </div>
        </div>
      )}
    </div>
  )
}

function ActivationDetail({
  entry,
  context,
  scanText,
  showHalfEditor,
  onHalfEditor,
  onOpen,
}: {
  entry: ActivatedWorldInfoEntry
  context: LoreActivationContext
  scanText: string
  showHalfEditor: boolean
  onHalfEditor: () => void
  onOpen: () => void
}) {
  const activation = entry.activationType === 'vector'
    ? `Vector match${entry.score != null ? ` / ${entry.score.toFixed(3)}` : ''}`
    : entry.activationType === 'constant'
      ? 'Constant entry'
      : entry.activationType === 'sticky'
        ? 'Sticky entry'
        : `Keyword match${context.exactTriggerPhrase ? ` / "${context.exactTriggerPhrase}"` : ''}`

  // Only the sentence the key appeared in — never the whole scanned message.
  const triggerSentence = entry.activationType === 'constant'
    ? null
    : entry.activationType === 'sticky'
      ? null
    : context.triggeringExcerpt ?? (entry.activationType === 'vector' ? getLastScannedSentence(scanText) : null)
  const triggerSentenceNote = entry.activationType === 'constant'
    ? 'This entry is always active, so no sentence triggered it.'
    : entry.activationType === 'sticky'
      ? 'This entry was kept active by sticky activation, so no sentence triggered it.'
    : entry.activationType === 'vector'
      ? 'Semantic activation has no literal trigger; showing the closing sentence of the scanned context.'
      : 'No scanned sentence contained a configured key.'

  return (
    <aside className={styles.detail}>
      <div className={styles.detailTitle}>
        <div>
          <strong>{entry.comment || 'Unnamed entry'}</strong>
          <span>{entry.bookName || entry.bookId}</span>
        </div>
        <div className={styles.detailActions}>
          {showHalfEditor && <button type="button" onClick={onHalfEditor}>Half editor</button>}
          <button type="button" onClick={onOpen}>Open entry</button>
        </div>
      </div>
      <dl>
        <dt>Activation</dt>
        <dd><span className={styles.typeLabel} data-activation={entry.activationType}>{activation}</span></dd>

        {context.exactTriggerPhrase && (
          <>
            <dt>Exact trigger phrase</dt>
            <dd className={styles.traceQuote}>&quot;{context.exactTriggerPhrase}&quot;</dd>
          </>
        )}

        {(context.matchedPrimaryKeys.length > 0 || context.matchedSecondaryKeys.length > 0) && (
          <>
            <dt>Matched keys</dt>
            <dd>
              {context.matchedPrimaryKeys.length > 0 && <div>Primary: {context.matchedPrimaryKeys.join(', ')}</div>}
              {context.matchedSecondaryKeys.length > 0 && <div>Secondary: {context.matchedSecondaryKeys.join(', ')}</div>}
            </dd>
          </>
        )}

        {entry.activationType === 'keyword' && context.matchedPrimaryKeys.length === 0 && context.configuredPrimaryKeys.length > 0 && (
          <>
            <dt>Configured primary keys</dt>
            <dd>{context.configuredPrimaryKeys.join(', ')} <span className={styles.unavailable}>(exact matched key unavailable)</span></dd>
          </>
        )}

        <dt>Matched because</dt>
        <dd>
          {context.matchedBecause
          ?? (entry.activationType === 'constant'
            ? 'This entry is configured as always active.'
            : entry.activationType === 'sticky'
              ? 'This entry was retained by sticky activation.'
            : entry.activationType === 'vector'
                ? `Semantic similarity activated this entry${entry.score != null ? ` with score ${entry.score.toFixed(3)}` : ''}.`
                : 'Keyword activation was reported; the payload did not include a match explanation.')}
        </dd>

        {context.matchedContentPreview && (
          <>
            <dt>Matched content preview</dt>
            <dd className={styles.tracePreview}>{context.matchedContentPreview}</dd>
          </>
        )}

        {context.whyActivated && (
          <>
            <dt>Why it activated</dt>
            <dd>{context.whyActivated}</dd>
          </>
        )}

        <dt>Triggering sentence</dt>
        <dd className={triggerSentence ? styles.tracePreview : styles.unavailable}>
          {triggerSentence ?? triggerSentenceNote}
        </dd>

        <dt>Source lorebook</dt>
        <dd>{entry.bookName || entry.bookId}</dd>

        <dt>Trace order</dt>
        <dd>#{entry.activationOrder + 1}{entry.firstTriggeredForBook ? ' / first triggered for book' : ''}</dd>

        <dt>Exact placement</dt>
        <dd>Position {entry.position} / Depth {entry.depth} / Priority {entry.priority} / {entry.preventRecursion ? 'Non-recursive' : 'Recursive'}</dd>

        <dt>Estimated size</dt>
        <dd>{formatCompactNumber(entry.estimatedTokens)} tokens</dd>
      </dl>
    </aside>
  )
}

sources.src/components/lore-indicator/utils.ts:
import type { ActivatedWorldInfoEntry } from '../../types/api'
import type { LoreIndicatorSettings } from '../../types/store'

export interface LorePoint {
  x: number
  y: number
}

export interface LoreRect extends LorePoint {
  width: number
  height: number
}

export interface LoreActivationContext {
  exactTriggerPhrase: string | null
  matchedPrimaryKeys: string[]
  matchedSecondaryKeys: string[]
  configuredPrimaryKeys: string[]
  matchedBecause: string | null
  matchedContentPreview: string | null
  whyActivated: string | null
  triggeringExcerpt: string | null
}

export const LORE_ITEM_IDS = [
  'active-count',
  'token-estimate',
  'passes',
  'constant',
  'keyword',
  'vector',
  'lorebooks',
  'search',
  'grouping',
] as const

export type LoreItemId = typeof LORE_ITEM_IDS[number]

function firstString(...values: unknown[]): string | null {
  for (const value of values) {
    if (typeof value === 'string' && value.trim()) return value.trim()
  }
  return null
}

function stringList(value: unknown): string[] {
  if (Array.isArray(value)) {
    return value.filter((item): item is string => typeof item === 'string' && Boolean(item.trim())).map((item) => item.trim())
  }
  const single = firstString(value)
  return single ? [single] : []
}

export function formatCompactNumber(value: unknown): string {
  const normalized = typeof value === 'number' && Number.isFinite(value) ? value : 0
  if (normalized < 1_000) return String(normalized)
  if (normalized < 1_000_000) return `${(normalized / 1_000).toFixed(normalized >= 10_000 ? 0 : 1).replace(/\.0$/, '')}k`
  return `${(normalized / 1_000_000).toFixed(1).replace(/\.0$/, '')}m`
}

export function getExactTriggerPhrase(entry: ActivatedWorldInfoEntry): string | null {
  return firstString(
    entry.triggerPhrase,
    entry.matchedPhrase,
    entry.matchedKey,
    entry.matchedTrigger,
    entry.trigger,
  )
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

/**
 * Split scanned text into sentences. Keeps quoted dialogue together and treats
 * hard line breaks as boundaries, which is how roleplay messages read.
 */
export function splitSentences(text: string): string[] {
  return text
    .split(/\n+/)
    .flatMap((line) => line.split(/(?<=[.!?…]["'”’)\]]?)\s+/))
    .map((sentence) => sentence.trim())
    .filter(Boolean)
}

/**
 * Locate the single sentence a key actually matched in.
 *
 * The activation payload carries no trigger phrase or excerpt, so the panel used
 * to fall back to the entire generation query — printing the whole message under
 * "triggering sentence". Deriving the sentence here keeps that field honest.
 */
export function findTriggeringSentence(
  sourceText: string | null | undefined,
  phrases: string[],
): { sentence: string; phrase: string } | null {
  if (!sourceText?.trim()) return null
  const candidates = phrases.map((phrase) => phrase.trim()).filter(Boolean)
  if (candidates.length === 0) return null

  for (const sentence of splitSentences(sourceText)) {
    for (const phrase of candidates) {
      // Word-boundary match where the key is word-like, substring otherwise, so
      // regex-style and punctuation keys still resolve.
      const pattern = /^[\w\s'-]+$/.test(phrase)
        ? new RegExp(`(^|[^\\w])${escapeRegExp(phrase)}([^\\w]|$)`, 'i')
        : new RegExp(escapeRegExp(phrase), 'i')
      if (pattern.test(sentence)) return { sentence, phrase }
    }
  }
  return null
}

/**
 * Builds the corpus the activation scan actually ran against.
 *
 * `activatedWorldInfo` is emitted while the prompt is assembled, so by the time the
 * panel renders, the chat already contains the reply that activation produced.
 * Including it would let a key match text that was never scanned and report it as
 * the trigger, so trailing non-user messages are dropped.
 */
export function buildLoreScanText(
  queryPreview: string | null | undefined,
  messages: Array<{ content: string; is_user: boolean }>,
  historyDepth = 4,
): string {
  let end = messages.length
  while (end > 0 && !messages[end - 1].is_user) end -= 1
  const scanned = messages.slice(Math.max(0, end - historyDepth), end)
  return [queryPreview ?? '', ...scanned.map((message) => message.content)]
    .filter(Boolean)
    .join('\n')
}

/** Last sentence of the scanned text — the closest thing a vector hit has to a trigger. */
export function getLastScannedSentence(sourceText: string | null | undefined): string | null {
  if (!sourceText?.trim()) return null
  return splitSentences(sourceText).at(-1) ?? null
}

export function getActivationContext(
  entry: ActivatedWorldInfoEntry,
  sourceText?: string | null,
): LoreActivationContext {
  const reportedPhrase = getExactTriggerPhrase(entry)
  const reportedPrimaryKeys = stringList(entry.matchedPrimaryKeys ?? entry.matchedKey)
  const configuredPrimaryKeys = stringList(entry.keys)
  const reportedExcerpt = firstString(entry.triggeringSentence, entry.messageExcerpt, entry.contextExcerpt)

  const derived = entry.activationType === 'keyword' && !reportedExcerpt
    ? findTriggeringSentence(sourceText, reportedPhrase ? [reportedPhrase, ...configuredPrimaryKeys] : configuredPrimaryKeys)
    : null

  return {
    exactTriggerPhrase: reportedPhrase ?? derived?.phrase ?? null,
    matchedPrimaryKeys: reportedPrimaryKeys.length > 0
      ? reportedPrimaryKeys
      : derived ? [derived.phrase] : [],
    matchedSecondaryKeys: stringList(entry.matchedSecondaryKeys),
    configuredPrimaryKeys,
    matchedBecause: firstString(entry.matchedBecause, entry.matchReason),
    matchedContentPreview: firstString(entry.matchedContentPreview, entry.contentPreview),
    whyActivated: firstString(entry.whyActivated),
    triggeringExcerpt: reportedExcerpt ?? derived?.sentence ?? null,
  }
}

export function clampLoreFloatingPosition(
  point: LorePoint,
  surface: { width: number; height: number },
  viewport: { width: number; height: number },
  margin = 12,
): LorePoint {
  return {
    x: Math.min(Math.max(margin, point.x), Math.max(margin, viewport.width - surface.width - margin)),
    y: Math.min(Math.max(margin, point.y), Math.max(margin, viewport.height - surface.height - margin)),
  }
}

export function clampLoreRect(
  rect: LoreRect,
  viewport: { width: number; height: number },
  minimum = { width: 560, height: 360 },
  margin = 16,
): LoreRect {
  const width = Math.min(Math.max(minimum.width, rect.width), Math.max(minimum.width, viewport.width - margin * 2))
  const height = Math.min(Math.max(minimum.height, rect.height), Math.max(minimum.height, viewport.height - margin * 2))
  return {
    width,
    height,
    x: Math.min(Math.max(margin, rect.x), Math.max(margin, viewport.width - width - margin)),
    y: Math.min(Math.max(margin, rect.y), Math.max(margin, viewport.height - height - margin)),
  }
}

export function getFloatingPanelPosition(
  anchor: LorePoint,
  control: { width: number; height: number },
  panel: { width: number; height: number },
  viewport: { width: number; height: number },
  margin = 12,
  gap = 8,
): LorePoint {
  const preferredTop = anchor.y + control.height + gap
  const top = preferredTop + panel.height <= viewport.height - margin
    ? preferredTop
    : anchor.y - panel.height - gap
  return clampLoreFloatingPosition(
    { x: anchor.x, y: top },
    panel,
    viewport,
    margin,
  )
}

export function clampLorePanelHeight(height: number, viewportHeight: number, margin = 42): number {
  const maxHeight = Math.max(320, viewportHeight - margin * 2)
  return Math.min(Math.max(320, height), maxHeight)
}

export function getConfiguredV4Items(settings: LoreIndicatorSettings) {
  const existing = new Map(settings.v4Items.map((item) => [item.id, item]))
  return LORE_ITEM_IDS.map((id, index) => existing.get(id) ?? {
    id,
    visible: true,
    removed: false,
    mode: 'iconText' as const,
    order: index,
  }).sort((a, b) => a.order - b.order)
}

export function matchesKeybind(event: KeyboardEvent, keybind: string): boolean {
  const parts = keybind.split('+').map((part) => part.trim().toLowerCase()).filter(Boolean)
  if (parts.length === 0) return false
  const key = parts.at(-1)
  if (!key || event.key.toLowerCase() !== key) return false
  return (
    event.ctrlKey === parts.includes('ctrl') &&
    event.metaKey === parts.includes('meta') &&
    event.altKey === parts.includes('alt') &&
    event.shiftKey === parts.includes('shift')
  )
}

export function searchLoreEntries(entries: ActivatedWorldInfoEntry[], query: string) {
  const normalized = query.trim().toLowerCase()
  if (!normalized) return entries
  return entries.filter((entry) => {
    const context = getActivationContext(entry)
    return [
      entry.comment,
      entry.bookName,
      entry.bookId,
      entry.activationType,
      entry.source,
      entry.keys.join(' '),
      context.exactTriggerPhrase,
      context.matchedPrimaryKeys.join(' '),
      context.matchedSecondaryKeys.join(' '),
      context.matchedBecause,
      context.matchedContentPreview,
      context.whyActivated,
      context.triggeringExcerpt,
      entry.score?.toString(),
      entry.priority.toString(),
    ].some((value) => value?.toLowerCase().includes(normalized))
  })
}

