.modal {
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5),
    0 0 40px var(--lumiverse-primary-020);
}

.closeBtnPos {
  top: 16px;
  right: 16px;
  z-index: 10;
}

/* ── Header ── */
.header {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 6px;
  padding: 24px 28px 16px;
  border-bottom: 1px solid var(--lumiverse-border);
  flex-shrink: 0;
  padding-right: 64px; /* Make room for the absolute positioned closeBtn */
}

.title {
  margin: 0;
  font-size: calc(18px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  color: var(--lumiverse-text);
  letter-spacing: -0.01em;
}

.count {
  margin-left: 0;
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  font-variant-numeric: tabular-nums;
  padding: 2px 8px;
  border-radius: 8px;
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.04));
  align-self: flex-start;
}

.headerActions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.deleteAllBtn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-danger);
  background: transparent;
  border: 1px solid var(--lumiverse-danger-020);
  border-radius: 8px;
  padding: 2px 8px;
  cursor: pointer;
  transition: background var(--lumiverse-transition-fast), border-color var(--lumiverse-transition-fast);
}

.deleteAllBtn:hover {
  background: var(--lumiverse-danger-015);
  border-color: var(--lumiverse-danger);
}

/* ── List ── */
.list {
  padding: 20px 28px 28px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: calc(60vh / var(--lumiverse-ui-scale, 1));
  scrollbar-width: thin;
  scrollbar-color: var(--lumiverse-fill-subtle) transparent;
}

.list::-webkit-scrollbar { width: 4px; }
.list::-webkit-scrollbar-track { background: transparent; }
.list::-webkit-scrollbar-thumb {
  background: var(--lumiverse-fill-subtle);
  border-radius: 4px;
}

/* ── Chat Card ── */
.card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 14px 16px 14px 18px;
  border-radius: var(--lcs-radius-sm, 8px);
  border: 1px solid var(--lcs-glass-border, rgba(255, 255, 255, 0.06));
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.03));
  cursor: pointer;
  text-align: left;
  color: inherit;
  font: inherit;
  transition:
    background var(--lcs-transition, 220ms cubic-bezier(0.4, 0, 0.2, 1)),
    border-color var(--lcs-transition, 220ms cubic-bezier(0.4, 0, 0.2, 1)),
    box-shadow var(--lcs-transition, 220ms cubic-bezier(0.4, 0, 0.2, 1)),
    transform var(--lcs-transition, 220ms cubic-bezier(0.4, 0, 0.2, 1));
  animation: greetingEnter 280ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

/* Left accent bar */
.card::before {
  content: '';
  position: absolute;
  left: 0;
  top: 8px;
  bottom: 8px;
  width: 3px;
  border-radius: 2px;
  background: var(--lumiverse-fill, rgba(255, 255, 255, 0.06));
  transition:
    background var(--lcs-transition, 220ms cubic-bezier(0.4, 0, 0.2, 1)),
    box-shadow var(--lcs-transition, 220ms cubic-bezier(0.4, 0, 0.2, 1));
}

.card:hover {
  background: var(--lumiverse-fill, rgba(255, 255, 255, 0.06));
  border-color: var(--lumiverse-border);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.12);
  transform: translateX(2px);
}

.card:focus-visible {
  outline: 2px solid var(--lumiverse-primary-050);
  outline-offset: 2px;
}

.card:hover::before {
  background: var(--lumiverse-text-dim, rgba(230, 230, 240, 0.3));
}

.card:active {
  transform: translateX(2px) scale(0.995);
}

/* ── Active chat card (Most Recent) ── */
.cardActive {
  border-color: var(--lumiverse-primary-050);
  background:
    linear-gradient(135deg, var(--lumiverse-primary-010) 0%, transparent 50%),
    var(--lumiverse-primary-010);
  box-shadow:
    0 0 0 0.5px var(--lumiverse-primary-020),
    inset 0 0.5px 0 rgba(255, 255, 255, 0.04);
}

.cardActive::before {
  background: linear-gradient(
    180deg,
    var(--lumiverse-primary) 0%,
    var(--lumiverse-primary-050) 100%
  );
  box-shadow: 0 0 8px var(--lumiverse-primary-020);
}

.cardActive:hover {
  border-color: var(--lumiverse-primary-050);
}

.cardActive:hover::before {
  box-shadow: 0 0 12px var(--lumiverse-primary-050);
}

/* ── New Chat Special Card ── */
.newChatCard {
  flex-direction: row;
  align-items: center;
  gap: 12px;
  border-style: dashed;
  border-color: var(--lumiverse-primary-050);
  background: var(--lumiverse-primary-010);
  margin-bottom: 8px;
}

.newChatCard::before {
  display: none;
}

.newChatCard:hover {
  background: var(--lumiverse-primary-015);
  border-color: var(--lumiverse-primary);
  transform: translateY(-2px);
}

.newChatIcon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--lumiverse-btn-icon);
  height: var(--lumiverse-btn-icon);
  border-radius: 6px;
  background: var(--lumiverse-primary);
  color: var(--lumiverse-primary-contrast, #fff);
}

.newChatCard .cardLabel {
  color: var(--lumiverse-primary-text);
}

/* ── Fresh Chat Card (memory-isolated) ── */
.freshChatCard {
  flex-direction: row;
  align-items: center;
  gap: 12px;
  border-style: dashed;
  border-color: var(--lumiverse-border-hover, rgba(255, 255, 255, 0.12));
  background: transparent;
  margin-bottom: 12px;
}

.freshChatCard::before {
  display: none;
}

.freshChatCard:hover {
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.04));
  border-color: var(--lumiverse-text-dim);
  transform: translateY(-1px);
}

.freshChatIcon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--lumiverse-btn-icon-sm, 28px);
  height: var(--lumiverse-btn-icon-sm, 28px);
  border-radius: 6px;
  background: var(--lumiverse-fill, rgba(255, 255, 255, 0.06));
  color: var(--lumiverse-text-dim);
  flex-shrink: 0;
}

.freshChatCard:hover .freshChatIcon {
  color: var(--lumiverse-text);
}

.freshChatHeader {
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
}

.freshChatCard .cardLabel {
  color: var(--lumiverse-text-muted, var(--lumiverse-text));
  font-weight: 600;
}

.freshChatSubtitle {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  font-weight: 400;
  letter-spacing: 0.01em;
}


/* ── Card innards ── */
.cardHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex: 1;
  min-width: 0;
}

.cardTitleRow {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 1;
  min-width: 0;
}

.cardLabel {
  font-size: calc(13.5px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
  letter-spacing: 0.01em;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.openChatBtn {
  padding: 0;
  border: none;
  background: transparent;
  text-align: left;
  cursor: pointer;
}

.openChatBtn::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
}

.openChatBtn:focus-visible {
  outline: none;
}

.openChatBtn:focus-visible::after {
  outline: 2px solid var(--lumiverse-primary);
  outline-offset: 2px;
}

.activeBadge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 9px;
  border-radius: 10px;
  background: var(--lumiverse-primary-015);
  color: var(--lumiverse-primary-text);
  font-size: calc(10.5px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  letter-spacing: 0.02em;
  flex-shrink: 0;
}

.cardPreview {
  margin: 4px 0 0;
}

.previewText {
  margin: 0 0 6px;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  line-height: 1.4;
  color: var(--lumiverse-text-dim);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  text-overflow: ellipsis;
}

.metaRow {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
}

.metaItem {
  display: flex;
  align-items: center;
  gap: 4px;
}

/* ── Context Menu ── */
.menuBtn {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--lumiverse-btn-icon-sm);
  height: var(--lumiverse-btn-icon-sm);
  border-radius: 6px;
  background: transparent;
  color: var(--lumiverse-text-dim);
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
  opacity: 0;
}

.card:hover .menuBtn,
.card:focus-within .menuBtn,
.cardActive .menuBtn {
  opacity: 1;
}

.menuBtn:hover,
.menuBtn:focus-visible,
.menuBtnActive {
  background: var(--lumiverse-fill);
  color: var(--lumiverse-text);
  opacity: 1 !important;
}

@media (hover: none) {
  .menuBtn {
    opacity: 1;
  }
}

.editInput {
  position: relative;
  z-index: 1;
  flex: 1;
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border-hover);
  color: var(--lumiverse-text);
  font-size: calc(13.5px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  padding: 2px 6px;
  border-radius: 4px;
  outline: none;
  min-width: 0;
}

.editInput:focus {
  border-color: var(--lumiverse-primary-050);
}

/* ── Staggered entrance animation ── */
@keyframes greetingEnter {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

