.main {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  min-width: 0;
}

/* ── Tab bar ─────────────────────────────────────────────────────────── */

.tabBar {
  display: flex;
  align-items: center;
  justify-content: space-between;
