  gap: 4px;
  background: transparent;
  border: 1px solid transparent;
  color: var(--lumiverse-text-dim);
  padding: 4px 8px;
  border-radius: var(--lumiverse-radius-sm);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
}

.panelToggleBtn:hover {
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text);
}

.panelToggleBtnActive {
  background: var(--lumiverse-fill);
  color: var(--lumiverse-text);
  border-color: var(--lumiverse-border);
}

/* ── Editor ──────────────────────────────────────────────────────────── */

.editorContentRow {
  flex: 1;
  display: flex;
  flex-direction: row;
  min-height: 0;
  overflow: hidden;
}

.editorMain {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.editorSidebar {
  width: 280px;
  min-width: 280px;
  border-left: 1px solid var(--lumiverse-border);
  display: flex;
  flex-direction: column;
  background: var(--lumiverse-bg);
}

.editorContainer {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
}

/* ── Status bar ──────────────────────────────────────────────────────── */

.statusBar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 5px 16px;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  border-top: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-bg);
  flex-shrink: 0;
}

.statusValid {
  color: var(--lumiverse-success);
}

.statusError {
  color: var(--lumiverse-danger);
  max-width: 55%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.statusEmpty {
  color: var(--lumiverse-text-hint);
}

.statusRight {
  display: flex;
  align-items: center;
  gap: 12px;
}

.shortcutHint {
  font-family: var(--lumiverse-font-mono);
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  padding: 1px 5px;
  border-radius: 3px;
  background: var(--lumiverse-fill-light);
  color: var(--lumiverse-text-dim);
}

.tsxNotice {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 10px 16px;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  background: var(--lumiverse-fill-subtle);
  border-bottom: 1px solid var(--lumiverse-border);
  line-height: 1.4;
}

.tsxNoticeIcon {
  flex-shrink: 0;
  color: var(--lumiverse-warning);
}

.tsxComponentLabel {
  font-family: var(--lumiverse-font-mono);
  font-weight: 600;
  color: var(--lumiverse-primary);
}

.emptyTsx {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--lumiverse-text-hint);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  padding: 24px;
  text-align: center;
  line-height: 1.5;
}

/* ── Mobile: sidebar collapses to top sheet ──────────────────────────── */

.mobileToggle {
  display: none;
}

