.modal {
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5), 0 0 40px var(--lumiverse-primary-015);
}

/* ── Header ── */
.header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 20px 24px 16px;
  border-bottom: 1px solid var(--lumiverse-border, rgba(255, 255, 255, 0.08));
  flex-shrink: 0;
}

.headerTitle {
  margin: 0;
  font-size: calc(18px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text, rgba(230, 230, 240, 0.92));
}

.closeBtn {
  margin-left: auto;
}

/* ── Scrollable body ── */
.body {
  flex: 1;
  overflow-y: auto;
  padding: 16px 24px 24px;
}

.body::-webkit-scrollbar {
  width: 5px;
}

.body::-webkit-scrollbar-thumb {
  background: var(--lumiverse-fill);
  border-radius: 4px;
}

/* ── Messages ── */
/*
 * Bounded scroll container for the virtualised messages list.
 * The fixed height gives @tanstack/react-virtual a stable scroll parent
 * and lets it render only ~10–20 cards at a time even for 600+ message chats.
 */
.messagesCollapsibleBody {
  padding: 8px 12px 12px;
  height: clamp(360px, calc(62vh / var(--lumiverse-ui-scale, 1)), 720px);
  display: grid;
  grid-template-columns: minmax(260px, 340px) minmax(0, 1fr);
  gap: 12px;
}

.messagesScroll {
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  border-radius: 10px;
  border: 1px solid var(--lumiverse-border, rgba(255, 255, 255, 0.06));
  background: var(--lumiverse-fill-subtle);
  padding: 8px;
}

.messagesScroll::-webkit-scrollbar {
  width: 5px;
}

.messagesScroll::-webkit-scrollbar-thumb {
  background: var(--lumiverse-fill);
  border-radius: 4px;
}

.messageRow {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 8px;
  width: 100%;
  text-align: left;
  padding: 10px 12px;
  border: 1px solid var(--lumiverse-border, rgba(255, 255, 255, 0.06));
  border-radius: 8px;
  background: transparent;
  cursor: pointer;
  transition: border-color 120ms ease, background 120ms ease, box-shadow 120ms ease;
}

.messageRow:hover {
  background: var(--lumiverse-fill);
}

.messageRowClipBoundary {
  border-color: rgba(255, 171, 0, 0.48);
  background:
    linear-gradient(90deg, rgba(255, 171, 0, 0.11), rgba(255, 171, 0, 0.03) 44%, transparent),
    transparent;
  box-shadow: inset 3px 0 0 rgba(255, 171, 0, 0.72);
}

.messageRowClipBoundary:hover {
  background:
    linear-gradient(90deg, rgba(255, 171, 0, 0.14), rgba(255, 171, 0, 0.05) 44%, transparent),
    var(--lumiverse-fill);
}

.messageRowActive {
  border-color: var(--lumiverse-primary, #9370db);
  background: var(--lumiverse-primary-010);
  box-shadow: inset 0 0 0 1px var(--lumiverse-primary-015);
}

.messageRowClipBoundary.messageRowActive {
  background:
    linear-gradient(90deg, rgba(255, 171, 0, 0.12), rgba(255, 171, 0, 0.04) 44%, transparent),
    var(--lumiverse-primary-010);
  box-shadow:
    inset 3px 0 0 rgba(255, 171, 0, 0.78),
    inset 0 0 0 1px var(--lumiverse-primary-015);
}

.messageRowHeader {
  display: flex;
  align-items: center;
  gap: 8px;
}

.roleBadge {
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-weight: 600;
}

.messagePreview {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  line-height: 1.45;
  color: var(--lumiverse-text-dim, rgba(230, 230, 240, 0.58));
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.messageIndex {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim, rgba(230, 230, 240, 0.3));
}

.messageClipBadge {
  flex: 0 1 auto;
  min-width: 0;
  padding: 2px 6px;
  border: 1px solid rgba(255, 171, 0, 0.3);
  border-radius: 999px;
  color: #ffab00;
  background: rgba(255, 171, 0, 0.08);
  font-size: calc(9px * var(--lumiverse-font-scale, 1));
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.messageReasoningBadge {
  padding: 2px 6px;
  border: 1px solid rgba(147, 112, 219, 0.28);
  border-radius: 999px;
  background: var(--lumiverse-primary-010);
  color: var(--lumiverse-primary, #9370db);
  font-size: calc(9px * var(--lumiverse-font-scale, 1));
  line-height: 1.2;
  white-space: nowrap;
}

.messagePartBadge {
  padding: 2px 6px;
  border: 1px solid rgba(91, 192, 222, 0.24);
  border-radius: 999px;
  background: rgba(91, 192, 222, 0.1);
  color: rgba(146, 219, 241, 0.92);
  font-size: calc(9px * var(--lumiverse-font-scale, 1));
  line-height: 1.2;
  white-space: nowrap;
}

.messageMeta {
  margin-left: auto;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim, rgba(230, 230, 240, 0.4));
  white-space: nowrap;
}

.messageInspector {
  min-height: 0;
  display: flex;
  flex-direction: column;
  border-radius: 10px;
  border: 1px solid var(--lumiverse-border, rgba(255, 255, 255, 0.06));
  background: var(--lumiverse-fill-subtle);
  overflow: hidden;
}

.messageInspectorHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 12px;
  border-bottom: 1px solid var(--lumiverse-border, rgba(255, 255, 255, 0.06));
}

.messageInspectorTitleRow {
  display: flex;
  align-items: center;
  gap: 8px;
}

.mobileBackButton {
  display: none;
  align-items: center;
  gap: 4px;
  padding: 4px 8px;
  border: 1px solid var(--lumiverse-border, rgba(255, 255, 255, 0.08));
  border-radius: 999px;
  background: transparent;
  color: var(--lumiverse-text-dim, rgba(230, 230, 240, 0.72));
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  cursor: pointer;
}

.messageInspectorMeta {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim, rgba(230, 230, 240, 0.45));
  white-space: nowrap;
}

.messageInspectorContent {
  flex: 1;
  min-height: 0;
  padding: 12px;
  overflow: auto;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.messageInspectorSection {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.messageInspectorLabel {
  margin: 0;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--lumiverse-text-dim, rgba(230, 230, 240, 0.5));
}

.messageInspectorText {
  margin: 0;
  padding: 10px 12px;
  border: 1px solid var(--lumiverse-border, rgba(255, 255, 255, 0.06));
  border-radius: 8px;
  background: var(--lumiverse-fill);
  font-family: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', monospace;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  line-height: 1.6;
  color: var(--lumiverse-text, rgba(230, 230, 240, 0.85));
  white-space: pre-wrap;
  word-break: break-word;
}

.inlineExpandButton {
  align-self: flex-start;
  margin-top: 4px;
  padding: 2px 6px;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  border-radius: 4px;
  border: 1px solid var(--lumiverse-border, rgba(255, 255, 255, 0.08));
  background: transparent;
  color: var(--lumiverse-text-dim, rgba(230, 230, 240, 0.6));
  cursor: pointer;
  transition: background 120ms ease, color 120ms ease;
}

.inlineExpandButton:hover {
  background: var(--lumiverse-fill);
  color: var(--lumiverse-text, rgba(230, 230, 240, 0.92));
}

.chunkPreview {
  display: block;
  font-family: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', monospace;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  line-height: 1.5;
  color: var(--lumiverse-text-dim, rgba(230, 230, 240, 0.5));
  white-space: pre-wrap;
  word-break: break-word;
}

/* ── Collapsible sections ── */
.collapsible {
  margin-bottom: 8px;
  border-radius: 10px;
  border: 1px solid var(--lumiverse-border, rgba(255, 255, 255, 0.06));
  background: var(--lumiverse-fill-subtle);
  overflow: auto;
}

.collapsibleHeader {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 10px 12px;
  border: none;
  background: transparent;
  color: var(--lumiverse-text, rgba(230, 230, 240, 0.85));
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  cursor: pointer;
  transition: background 120ms ease;
}

.collapsibleHeader:hover {
  background: var(--lumiverse-fill-subtle);
}

.collapsibleTitleText {
  min-width: 0;
}

.clippedInlineLabel {
  color: #ffab00;
}

.chevron {
  transition: transform 200ms ease;
  color: var(--lumiverse-text-dim, rgba(230, 230, 240, 0.4));
}

.chevronOpen {
  transform: rotate(90deg);
}

.collapsibleBody {
  padding: 0 12px 12px;
  max-height: 400px;
  overflow-y: auto;
}

/* ── Breakdown entries ── */
.breakdownSummary {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  margin-bottom: 6px;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-primary, #9370db);
}

.breakdownList {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.breakdownEntry {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  border-radius: 6px;
  background: var(--lumiverse-fill-subtle);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  min-height: 30px;
}

.breakdownLabel {
  color: var(--lumiverse-text, rgba(230, 230, 240, 0.85));
  font-weight: 500;
  flex-shrink: 0;
}

.breakdownSource {
  color: var(--lumiverse-text-dim, rgba(230, 230, 240, 0.4));
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  flex-shrink: 0;
}

.breakdownRole {
  display: inline-flex;
  align-items: center;
  padding: 1px 6px;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  border-radius: 4px;
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text-muted, rgba(255, 255, 255, 0.4));
  flex-shrink: 0;
}

.breakdownCacheHint {
  display: inline-flex;
  align-items: center;
  padding: 1px 6px;
  border-radius: 999px;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  flex-shrink: 0;
}

.breakdownCacheHintCached {
  background: rgba(217, 119, 87, 0.12);
  color: rgba(217, 119, 87, 0.92);
}

.breakdownCacheHintMiss {
  background: rgba(255, 255, 255, 0.04);
  color: var(--lumiverse-text-dim, rgba(230, 230, 240, 0.4));
}

.breakdownTokens {
  margin-left: auto;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-primary, #9370db);
  font-weight: 500;
  white-space: nowrap;
  flex-shrink: 0;
}

/* ── Parameters JSON ── */
.parametersJson {
  font-family: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', monospace;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  line-height: 1.6;
  color: var(--lumiverse-text, rgba(230, 230, 240, 0.85));
  white-space: pre-wrap;
  word-break: break-word;
}

/* ── Assistant prefill ── */
.prefillSection {
  margin-bottom: 8px;
  border-radius: 10px;
  border: 1px solid var(--lumiverse-primary-015);
  background: var(--lumiverse-primary-010);
  padding: 10px 12px;
}

.prefillLabel {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--lumiverse-primary, #9370db);
  margin: 0 0 6px;
}

.prefillContent {
  font-family: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', monospace;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  line-height: 1.6;
  color: var(--lumiverse-text, rgba(230, 230, 240, 0.85));
  white-space: pre-wrap;
}

/* ── Raw view ── */
.rawView {
  font-family: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', monospace;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  line-height: 1.5;
  color: var(--lumiverse-text, rgba(230, 230, 240, 0.85));
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border, rgba(255, 255, 255, 0.06));
  border-radius: 10px;
  padding: 12px;
  margin: 0;
  white-space: pre-wrap;
  word-break: break-word;
}

/* ── Footer ── */
.footer {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 24px;
  border-top: 1px solid var(--lumiverse-border, rgba(255, 255, 255, 0.08));
  flex-shrink: 0;
}

.footerTotal {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
  font-variant-numeric: tabular-nums;
}

.footerMax {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
}

.footerSpacer {
  flex: 1;
}

/* ── Responsive ── */
@media (max-width: 600px) {
  .modal {
    max-width: 100%;
    max-height: calc(95vh / var(--lumiverse-ui-scale, 1));
  }

  .body {
    padding: 12px 16px 16px;
  }

  .header {
    padding: 16px;
  }

  .messagesCollapsibleBody {
    display: block;
    height: clamp(420px, calc(72vh / var(--lumiverse-ui-scale, 1)), 760px);
  }

  .messagesScroll,
  .messageInspector {
    height: 100%;
  }

  .messageInspector {
    display: none;
  }

  .messagesMobileInspectorVisible .messagesScroll {
    display: none;
  }

  .messagesMobileInspectorVisible .messageInspector {
    display: flex;
  }

  .messageInspectorHeader {
    align-items: flex-start;
    flex-direction: column;
  }

  .messageInspectorMeta {
    margin-left: 0;
    white-space: normal;
  }

  .messageRowHeader {
    align-items: center;
    flex-direction: row;
  }

  .messageMeta {
    margin-left: auto;
    white-space: nowrap;
  }

  .mobileBackButton {
    display: inline-flex;
  }

  .footer {
    flex-wrap: wrap;
    gap: 10px;
    padding: 12px 16px;
  }

  .footerSpacer {
    display: none;
  }
}


/* ── Find ── */
.findBar {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 12px;
  padding: 7px 8px;
  border: 1px solid var(--lumiverse-border, rgba(255, 255, 255, 0.08));
  border-radius: 8px;
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.025));
}

.findBarIcon {
  flex: 0 0 auto;
  color: var(--lumiverse-text-muted);
}

.findInput {
  min-width: 0;
  flex: 1 1 auto;
  padding: 5px 7px;
  border: 1px solid transparent;
  border-radius: 5px;
  outline: none;
  background: transparent;
  color: var(--lumiverse-text);
  font: inherit;
}

.findInput:focus {
  border-color: var(--lumiverse-primary-040, rgba(147, 112, 219, 0.4));
  background: var(--lumiverse-bg-darker, rgba(0, 0, 0, 0.2));
}

.findCounter {
  flex: 0 0 auto;
  min-width: 42px;
  color: var(--lumiverse-text-muted);
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.findMark {
  padding: 0 1px;
  border-radius: 2px;
  background: var(--lumiverse-primary-020, rgba(147, 112, 219, 0.2));
  color: inherit;
}

.findMarkCurrent {
  padding: 0 1px;
  border-radius: 2px;
  background: var(--lumiverse-primary-060, rgba(147, 112, 219, 0.6));
  color: var(--lumiverse-text, #fff);
  outline: 1px solid var(--lumiverse-primary, #9370db);
}

sources.src/components/modals/DryRunModal.tsx:
import { useEffect, useMemo, useRef, useState } from 'react'
import { useTranslation } from 'react-i18next'
import { useVirtualizer } from '@tanstack/react-virtual'
import { ChevronLeft, ChevronRight, ChevronUp, ChevronDown, Check, Code, Copy, Search, X } from 'lucide-react'
import { CloseButton } from '@/components/shared/CloseButton'
import { Badge } from '@/components/shared/Badge'
import { Button } from '@/components/shared/FormComponents'
import { ModalShell } from '@/components/shared/ModalShell'
import { useStore } from '@/store'
import type { DryRunResponse, DryRunMessage } from '@/api/generate'
import { copyTextToClipboard } from '@/lib/clipboard'
import { dryRunToRawPromptInput, formatRawPrompt, type RawPromptView } from '@/lib/formatRawPrompt'
import { findExpandedTextMatches } from '@/lib/expandedTextSearch'
import i18n from '@/i18n'
import { getAnthropicBreakdownCacheHints, getAnthropicCacheUsageSummary } from '@/lib/anthropic-breakdown-cache'
import { getNanoGptCacheUsageSummary } from '@/lib/nanogpt-breakdown-cache'
import { getOpenAiCompatibleCacheUsageSummary } from '@/lib/openai-compatible-breakdown-cache'
import styles from './DryRunModal.module.css'
import clsx from 'clsx'

const ROLE_COLOR: Record<string, 'warning' | 'info' | 'primary'> = {
  system: 'warning',
  user: 'info',
  assistant: 'primary',
}

// Auto-collapse the messages section above this count to keep the modal snappy on open.
const MESSAGES_AUTO_COLLAPSE_THRESHOLD = 50
// Fixed-height rows keep the list stable even when prompt content is huge.
const MESSAGE_ROW_HEIGHT = 68
const MESSAGE_PREVIEW_CAP = 220
// Memory chunk previews are clipped to this many characters by default.
const CHUNK_PREVIEW_CAP = 500

function normalizePreviewText(text?: string): string {
  if (!text) return ''
  return text.replace(/\s+/g, ' ').trim()
}

function getContentPartBadges(message: DryRunMessage): string[] {
  return (message.contentParts ?? [])
    .filter((part) => part.count > 0)
    .map((part) => `${part.type} x${part.count}`)
}

function summarizeMessage(message: DryRunMessage): string {
  const normalized = normalizePreviewText(message.content) || normalizePreviewText(message.reasoning)
  if (!normalized) return i18n.t('shared.emptyMessage', { ns: 'modals' })
  return normalized.length > MESSAGE_PREVIEW_CAP
    ? `${normalized.slice(0, MESSAGE_PREVIEW_CAP - 1)}…`
    : normalized
}

function countLines(content: string): number {
  if (!content) return 0
  return content.split(/\r\n|\r|\n/).length
}

interface MessageListItemProps {
  msg: DryRunMessage
  index: number
  selected: boolean
  clipBoundary: boolean
  clipBoundaryLabel?: string
  onSelect: () => void
}

function MessageListItem({ msg, index, selected, clipBoundary, clipBoundaryLabel, onSelect }: MessageListItemProps) {
  const { t: ts } = useTranslation('modals', { keyPrefix: 'shared' })
  const { t } = useTranslation('modals', { keyPrefix: 'dryRun' })
  const preview = summarizeMessage(msg)
  const lineCount = countLines(msg.content)
  const hasReasoning = normalizePreviewText(msg.reasoning).length > 0
  const contentPartBadges = getContentPartBadges(msg)

  return (
    <button
      type="button"
      className={clsx(
        styles.messageRow,
        clipBoundary && styles.messageRowClipBoundary,
        selected && styles.messageRowActive,
      )}
      onClick={onSelect}
    >
      <div className={styles.messageRowHeader}>
        <Badge color={ROLE_COLOR[msg.role] ?? 'neutral'} size="sm" className={styles.roleBadge}>
          {msg.role}
        </Badge>
        <span className={styles.messageIndex}>#{index + 1}</span>
        {clipBoundary && clipBoundaryLabel && (
          <span className={styles.messageClipBadge}>{clipBoundaryLabel}</span>
        )}
        {hasReasoning && (
          <span className={styles.messageReasoningBadge}>{t('reasoning')}</span>
        )}
        {contentPartBadges.map((badge) => (
          <span key={badge} className={styles.messagePartBadge}>{badge}</span>
        ))}
        <span className={styles.messageMeta}>
          {ts('chars', { count: msg.content.length })}
          {lineCount > 0 && ` • ${ts('lines', { count: lineCount })}`}
        </span>
      </div>
      <div className={styles.messagePreview}>{preview}</div>
    </button>
  )
}

interface ChunkPreviewProps {
  text: string
}

function ChunkPreview({ text }: ChunkPreviewProps) {
  const { t: ts } = useTranslation('modals', { keyPrefix: 'shared' })
  const [expanded, setExpanded] = useState(false)
  const needsToggle = text.length > CHUNK_PREVIEW_CAP
  const display = expanded || !needsToggle ? text : text.slice(0, CHUNK_PREVIEW_CAP) + '…'
  return (
    <>
      <span className={styles.chunkPreview}>{display}</span>
      {needsToggle && (
        <button
          type="button"
          className={styles.inlineExpandButton}
          onClick={() => setExpanded((e) => !e)}
        >
          {expanded ? ts('showLess') : ts('showFull', { count: text.length })}
        </button>
      )}
    </>
  )
}

interface VirtualizedMessagesProps {
  messages: DryRunMessage[]
  selectedIndex: number
  clipBoundaryIndex: number
  clipBoundaryLabel?: string
  scrollTick: number
  onSelect: (index: number) => void
}

function VirtualizedMessages({ messages, selectedIndex, clipBoundaryIndex, clipBoundaryLabel, scrollTick, onSelect }: VirtualizedMessagesProps) {
  const parentRef = useRef<HTMLDivElement>(null)

  const virtualizer = useVirtualizer({
    count: messages.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => MESSAGE_ROW_HEIGHT,
    overscan: 10,
  })

  useEffect(() => {
    if (scrollTick <= 0 || messages.length === 0) return
    virtualizer.scrollToIndex(selectedIndex, { align: 'center' })
  }, [messages.length, scrollTick, selectedIndex, virtualizer])

  return (
    <div ref={parentRef} className={styles.messagesScroll}>
      <div
        style={{
          height: virtualizer.getTotalSize(),
          position: 'relative',
          width: '100%',
        }}
      >
        {virtualizer.getVirtualItems().map((virtualRow) => {
          const msg = messages[virtualRow.index]
          return (
            <div
              key={virtualRow.key}
              style={{
                position: 'absolute',
                top: 0,
                left: 0,
                right: 0,
                transform: `translateY(${virtualRow.start}px)`,
                paddingBottom: 8,
              }}
            >
              <MessageListItem
                msg={msg}
                index={virtualRow.index}
                selected={selectedIndex === virtualRow.index}
                clipBoundary={virtualRow.index === clipBoundaryIndex}
                clipBoundaryLabel={clipBoundaryLabel}
                onSelect={() => onSelect(virtualRow.index)}
              />
            </div>
          )
        })}
      </div>
    </div>
  )
}

export default function DryRunModal() {
  const { t } = useTranslation('modals', { keyPrefix: 'dryRun' })
  const { t: ts } = useTranslation('modals', { keyPrefix: 'shared' })
  const { t: tf } = useTranslation('modals', { keyPrefix: 'promptItemizer' })
  const modalProps = useStore((s) => s.modalProps) as DryRunResponse
  const closeModal = useStore((s) => s.closeModal)

  const { messages, breakdown, parameters, assistantPrefill, model, provider, tokenCount, chatHistoryTokens, worldInfoStats, memoryStats, databankStats, contextClipStats } = modalProps

  const [messagesOpen, setMessagesOpen] = useState(
    messages.length <= MESSAGES_AUTO_COLLAPSE_THRESHOLD,
  )
  const [breakdownOpen, setBreakdownOpen] = useState(false)
  const [paramsOpen, setParamsOpen] = useState(false)
  const [wiStatsOpen, setWiStatsOpen] = useState(false)
  const [memStatsOpen, setMemStatsOpen] = useState(false)
  const [databankStatsOpen, setDatabankStatsOpen] = useState(false)
  // Auto-open the budget section when clipping is in a problem state so
  // users discover why their chat history is missing without hunting.
  const [budgetOpen, setBudgetOpen] = useState(
    Boolean(contextClipStats?.budgetInvalid) || (contextClipStats?.messagesDropped ?? 0) > 0,
  )
  const [rawView, setRawView] = useState<'off' | RawPromptView>('off')
  const [copied, setCopied] = useState(false)
  const [selectedMessageIndex, setSelectedMessageIndex] = useState(0)
  const [mobileInspectorOpen, setMobileInspectorOpen] = useState(false)
  const [findOpen, setFindOpen] = useState(false)
  const [findQuery, setFindQuery] = useState('')
  const [findMatchIndex, setFindMatchIndex] = useState(0)
  const [findNavTick, setFindNavTick] = useState(0)
  const findInputRef = useRef<HTMLInputElement>(null)
  const bodyRef = useRef<HTMLDivElement>(null)
  const inspectorContentRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    setSelectedMessageIndex((prev) => {
      if (messages.length === 0) return 0
      return Math.min(prev, messages.length - 1)
    })
  }, [messages.length])

  useEffect(() => {
    if (!messagesOpen) setMobileInspectorOpen(false)
  }, [messagesOpen])

  const rawInput = useMemo(() => dryRunToRawPromptInput(modalProps), [modalProps])
  const rawText = useMemo(
    () => (rawView === 'off' ? '' : formatRawPrompt(rawInput, rawView)),
    [rawInput, rawView],
  )

  const handleCopy = () => {
    const text = formatRawPrompt(rawInput, rawView === 'json' ? 'json' : 'text')
    copyTextToClipboard(text).catch(console.error)
    setCopied(true)
    setTimeout(() => setCopied(false), 1500)
  }

  const cycleRawView = () => {
    setRawView((v) => (v === 'off' ? 'text' : v === 'text' ? 'json' : 'off'))
  }

  const rawButtonLabel = rawView === 'off' ? ts('raw') : rawView === 'text' ? ts('json') : ts('visual')

  type DryRunFindMatch =
    | { kind: 'message'; messageIndex: number; field: 'content' | 'reasoning'; start: number; end: number }
    | { kind: 'raw'; start: number; end: number }

  const messageFindMatches = useMemo<DryRunFindMatch[]>(() => {
    const query = findQuery.trim()
    if (!query) return []
    const matches: DryRunFindMatch[] = []
    messages.forEach((message, messageIndex) => {
      for (const range of findExpandedTextMatches(message.content ?? '', query)) {
        matches.push({ kind: 'message', messageIndex, field: 'content', start: range.start, end: range.end })
      }
      for (const range of findExpandedTextMatches(message.reasoning ?? '', query)) {
        matches.push({ kind: 'message', messageIndex, field: 'reasoning', start: range.start, end: range.end })
      }
    })
    return matches
  }, [findQuery, messages])

  const rawFindMatches = useMemo<DryRunFindMatch[]>(() => {
    const query = findQuery.trim()
    if (!query || rawView === 'off' || !rawText) return []
    return findExpandedTextMatches(rawText, query).map((range) => ({
      kind: 'raw' as const,
      start: range.start,
      end: range.end,
    }))
  }, [findQuery, rawText, rawView])

  const findMatches = rawView === 'off' ? messageFindMatches : rawFindMatches
  const currentFindMatchIndex = findMatches.length === 0
    ? 0
    : Math.min(findMatchIndex, findMatches.length - 1)
  const currentFindMatch = findMatches[currentFindMatchIndex] ?? null

  const goToFindMatch = (nextIndex: number) => {
    if (findMatches.length === 0) return
    const wrapped = ((nextIndex % findMatches.length) + findMatches.length) % findMatches.length
    const match = findMatches[wrapped]
    setFindMatchIndex(wrapped)
    if (match.kind === 'message') {
      setMessagesOpen(true)
      setSelectedMessageIndex(match.messageIndex)
      setMobileInspectorOpen(true)
    }
    setFindNavTick((tick) => tick + 1)
  }

  useEffect(() => {
    setFindMatchIndex(0)
  }, [rawView])

  // Ctrl/Cmd+F opens the same find affordance used by Prompt Breakdown.
  useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      if ((event.ctrlKey || event.metaKey) && (event.key === 'f' || event.key === 'F')) {
        event.preventDefault()
        setFindOpen(true)
        requestAnimationFrame(() => findInputRef.current?.focus())
      }
    }
    document.addEventListener('keydown', onKey, true)
    return () => document.removeEventListener('keydown', onKey, true)
  }, [])

  // Explicit navigation controls both panes: the virtualizer centers the
  // selected message on the left, then this centers the active mark on the
  // right (or in Raw/JSON's body scroller).
  useEffect(() => {
    if (!findOpen || !findQuery.trim() || !currentFindMatch || findNavTick <= 0) return
    const frame = requestAnimationFrame(() => {
      const container = currentFindMatch.kind === 'message'
        ? inspectorContentRef.current
        : bodyRef.current
      const mark = container?.querySelector<HTMLElement>('[data-dry-find-current="true"]')
      if (!container || !mark) return
      const containerRect = container.getBoundingClientRect()
      const markRect = mark.getBoundingClientRect()
      const top = container.scrollTop
        + (markRect.top - containerRect.top)
        - ((container.clientHeight - markRect.height) / 2)
      container.scrollTo({ top: Math.max(0, top), behavior: 'smooth' })
    })
    return () => cancelAnimationFrame(frame)
  }, [currentFindMatch, findNavTick, findOpen, findQuery])

  const highlightMessageFindMatches = (
    text: string,
    messageIndex: number,
    field: 'content' | 'reasoning',
  ) => {
    const query = findQuery.trim()
    if (!query) return text
    const ranges = findExpandedTextMatches(text, query)
    if (ranges.length === 0) return text
    const nodes = []
    let cursor = 0
    ranges.forEach((range, index) => {
      if (range.start > cursor) nodes.push(text.slice(cursor, range.start))
      const isCurrent = currentFindMatch?.kind === 'message'
        && currentFindMatch.messageIndex === messageIndex
        && currentFindMatch.field === field
        && currentFindMatch.start === range.start
        && currentFindMatch.end === range.end
      nodes.push(
        <mark
          key={index}
          className={isCurrent ? styles.findMarkCurrent : styles.findMark}
          data-dry-find-current={isCurrent ? 'true' : undefined}
        >
          {text.slice(range.start, range.end)}
        </mark>,
      )
      cursor = range.end
    })
    if (cursor < text.length) nodes.push(text.slice(cursor))
    return nodes
  }

  const highlightRawFindMatches = (text: string) => {
    const query = findQuery.trim()
    if (!query) return text
    const ranges = findExpandedTextMatches(text, query)
    if (ranges.length === 0) return text
    const nodes = []
    let cursor = 0
    ranges.forEach((range, index) => {
      if (range.start > cursor) nodes.push(text.slice(cursor, range.start))
      const isCurrent = currentFindMatch?.kind === 'raw'
        && currentFindMatch.start === range.start
        && currentFindMatch.end === range.end
      nodes.push(
        <mark
          key={index}
          className={isCurrent ? styles.findMarkCurrent : styles.findMark}
          data-dry-find-current={isCurrent ? 'true' : undefined}
        >
          {text.slice(range.start, range.end)}
        </mark>,
      )
      cursor = range.end
    })
    if (cursor < text.length) nodes.push(text.slice(cursor))
    return nodes
  }

  // Memoise derived values so toggling a sibling section doesn't re-serialise
  // potentially large payloads on every render.
  const tokenBreakdown = useMemo(
    () => tokenCount?.breakdown || [],
    [tokenCount],
  )
  const breakdownCacheHints = useMemo(
    () => getAnthropicBreakdownCacheHints({ provider, parameters, breakdown }),
    [provider, parameters, breakdown],
  )
  const anthropicCacheUsage = useMemo(
    () => getAnthropicCacheUsageSummary(provider, modalProps.usage),
    [provider, modalProps.usage],
  )
  const nanoGptCacheUsage = useMemo(
    () => getNanoGptCacheUsageSummary(provider, modalProps.usage),
    [provider, modalProps.usage],
  )
  const openAiCompatibleCacheUsage = useMemo(
    () => getOpenAiCompatibleCacheUsageSummary(provider, modalProps.usage),
    [provider, modalProps.usage],
  )

  const parametersJson = useMemo(
    () => JSON.stringify(parameters, null, 2),
    [parameters],
  )

  const databankRetrievalStateLabel = useMemo(() => {
    const state = databankStats?.retrievalState
    if (!state) return null
    return t(`retrieval.${state}`)
  }, [databankStats?.retrievalState, t])

  const selectedMessage = messages[selectedMessageIndex] ?? null
  const selectedMessageLineCount = selectedMessage ? countLines(selectedMessage.content) : 0
  const selectedMessageHasReasoning =
    normalizePreviewText(selectedMessage?.reasoning).length > 0
  const selectedMessageContentPartBadges = selectedMessage
    ? getContentPartBadges(selectedMessage)
    : []
  const clippedMessagesText = contextClipStats?.enabled && contextClipStats.messagesDropped > 0
    ? t('clipped', { count: contextClipStats.messagesDropped }).trim()
    : ''
  const clippedMessagesSeparator = clippedMessagesText.match(/^[,，、]\s*/)?.[0] ?? ', '
  const clippedMessagesLabel = clippedMessagesText.replace(/^[,，、]\s*/, '').trim()
  const clipBoundaryIndex = useMemo(() => {
    if (!contextClipStats?.enabled || contextClipStats.messagesDropped <= 0 || messages.length === 0) return -1
    const firstKeptHistoryIndex = messages.findIndex((msg) => msg.__chatHistorySource)
    return firstKeptHistoryIndex >= 0 ? firstKeptHistoryIndex : 0
  }, [contextClipStats?.enabled, contextClipStats?.messagesDropped, messages])
  const clipBoundaryLabel = clipBoundaryIndex >= 0
    ? t('clipBoundaryMarker', { defaultValue: 'first kept after clip' })
    : undefined

  const handleSelectMessage = (index: number) => {
    setSelectedMessageIndex(index)
    setMobileInspectorOpen(true)
  }

  return (
    <ModalShell isOpen={true} onClose={closeModal} maxWidth="clamp(340px, 94vw, min(1100px, var(--lumiverse-content-max-width, 1100px)))" className={styles.modal}>
          {/* Header */}
          <div className={styles.header}>
            <h3 className={styles.headerTitle}>{t('title')}</h3>
            <Badge color="primary">
              {provider} / {model}
            </Badge>
            <CloseButton onClick={closeModal} variant="solid" className={styles.closeBtn} />
          </div>

          {/* Scrollable body */}
          <div ref={bodyRef} className={styles.body}>
            {findOpen && (
              <div className={styles.findBar}>
                <Search size={12} className={styles.findBarIcon} />
                <input
                  ref={findInputRef}
                  className={styles.findInput}
                  value={findQuery}
                  placeholder={tf('findPlaceholder')}
                  onChange={(event) => {
                    setFindQuery(event.target.value)
                    setFindMatchIndex(0)
                  }}
                  onKeyDown={(event) => {
                    if (event.key === 'Enter') {
                      event.preventDefault()
                      goToFindMatch(event.shiftKey
                        ? currentFindMatchIndex - 1
                        : currentFindMatchIndex + 1)
                    } else if (event.key === 'Escape') {
                      event.preventDefault()
                      setFindOpen(false)
                    }
                  }}
                />
                <span className={styles.findCounter}>
                  {findQuery.trim()
                    ? findMatches.length > 0
                      ? String(currentFindMatchIndex + 1) + '/' + String(findMatches.length)
                      : tf('noMatches')
                    : ''}
                </span>
                <Button
                  variant="ghost"
                  size="sm"
                  icon={<ChevronUp size={12} />}
                  disabled={findMatches.length === 0}
                  onClick={() => goToFindMatch(currentFindMatchIndex - 1)}
                  aria-label={tf('findPrevious')}
                />
                <Button
                  variant="ghost"
                  size="sm"
                  icon={<ChevronDown size={12} />}
                  disabled={findMatches.length === 0}
                  onClick={() => goToFindMatch(currentFindMatchIndex + 1)}
                  aria-label={tf('findNext')}
                />
                <Button
                  variant="ghost"
                  size="sm"
                  icon={<X size={12} />}
                  onClick={() => setFindOpen(false)}
                  aria-label={tf('closeFind')}
                />
              </div>
            )}
            {rawView !== 'off' ? (
              <pre className={styles.rawView}>
                {findOpen ? highlightRawFindMatches(rawText) : rawText}
              </pre>
            ) : (
              <>
            {/* Messages — collapsible + virtualised so 600+ message chats stay responsive */}
            <div className={styles.collapsible}>
              <button
                type="button"
                className={styles.collapsibleHeader}
                onClick={() => setMessagesOpen((o) => !o)}
              >
                <ChevronRight
                  size={14}
                  className={clsx(styles.chevron, messagesOpen && styles.chevronOpen)}
                />
                <span className={styles.collapsibleTitleText}>
                  {t('messages')} ({messages.length}
                  {clippedMessagesLabel && (
                    <>
                      {clippedMessagesSeparator}
                      <span className={styles.clippedInlineLabel}>{clippedMessagesLabel}</span>
                    </>
                  )}
                  )
                </span>
              </button>
              {messagesOpen && messages.length > 0 && (
                <div
                  className={clsx(
                    styles.messagesCollapsibleBody,
                    mobileInspectorOpen && styles.messagesMobileInspectorVisible,
                  )}
                >
                  <VirtualizedMessages
                    messages={messages}
                    selectedIndex={selectedMessageIndex}
                    clipBoundaryIndex={clipBoundaryIndex}
                    clipBoundaryLabel={clipBoundaryLabel}
                    scrollTick={findNavTick}
                    onSelect={handleSelectMessage}
                  />
                  <div className={styles.messageInspector}>
                    {selectedMessage && (
                      <>
                        <div className={styles.messageInspectorHeader}>
                          <div className={styles.messageInspectorTitleRow}>
                            <button
                              type="button"
                              className={styles.mobileBackButton}
                              onClick={() => setMobileInspectorOpen(false)}
                            >
                              <ChevronLeft size={14} />
                              {t('messages')}
                            </button>
                            <Badge color={ROLE_COLOR[selectedMessage.role] ?? 'neutral'} size="sm" className={styles.roleBadge}>
                              {selectedMessage.role}
                            </Badge>
                            <span className={styles.messageIndex}>#{selectedMessageIndex + 1}</span>
                            {selectedMessageContentPartBadges.map((badge) => (
                              <span key={badge} className={styles.messagePartBadge}>{badge}</span>
                            ))}
                          </div>
                          <span className={styles.messageInspectorMeta}>
                            {ts('chars', { count: selectedMessage.content.length })}
                            {selectedMessageLineCount > 0 && ` • ${ts('lines', { count: selectedMessageLineCount })}`}
                          </span>
                        </div>
                        <div ref={inspectorContentRef} className={styles.messageInspectorContent}>
                          <div className={styles.messageInspectorSection}>
                            <p className={styles.messageInspectorLabel}>{t('content')}</p>
                            <pre className={styles.messageInspectorText}>
                              {findOpen && selectedMessage.content
                                ? highlightMessageFindMatches(selectedMessage.content, selectedMessageIndex, 'content')
                                : selectedMessage.content || ts('emptyMessage')}
                            </pre>
                          </div>
                          {selectedMessageHasReasoning && (
                            <div className={styles.messageInspectorSection}>
                              <p className={styles.messageInspectorLabel}>{t('reasoning')}</p>
                              <pre className={styles.messageInspectorText}>
                                {findOpen
                                  ? highlightMessageFindMatches(selectedMessage.reasoning ?? '', selectedMessageIndex, 'reasoning')
                                  : selectedMessage.reasoning}
                              </pre>
                            </div>
                          )}
                        </div>
                      </>
                    )}
                  </div>
                </div>
              )}
            </div>

            {/* Assistant prefill */}
            {assistantPrefill && (
              <div className={styles.prefillSection}>
                <p className={styles.prefillLabel}>{t('assistantPrefill')}</p>
                <div className={styles.prefillContent}>{assistantPrefill}</div>
              </div>
            )}

            {/* Breakdown */}
            {breakdown.length > 0 && (
              <div className={styles.collapsible}>
                <button
                  type="button"
                  className={styles.collapsibleHeader}
                  onClick={() => setBreakdownOpen((o) => !o)}
                >
                  <ChevronRight
                    size={14}
                    className={clsx(styles.chevron, breakdownOpen && styles.chevronOpen)}
                  />
                  {t('assemblyBreakdown', { count: breakdown.length })}
                </button>
                {breakdownOpen && (
                  <div className={styles.collapsibleBody}>
                    {tokenCount && (
                      <div className={styles.breakdownSummary}>
                        <span>{t('totalTokens', { count: tokenCount.total_tokens })}</span>
                        {chatHistoryTokens != null && chatHistoryTokens > 0 && (
                          <span className={styles.breakdownSource}>{t('chatHistoryTokens', { count: chatHistoryTokens })}</span>
                        )}
                        {tokenCount.tokenizer_name && (
                          <span className={styles.breakdownSource}>{t('viaTokenizer', { name: tokenCount.tokenizer_name })}</span>
                        )}
                        {anthropicCacheUsage && (
                          <span className={styles.breakdownSource}>
                            {t('cacheReadWrite', {
                              read: anthropicCacheUsage.cacheReadInputTokens.toLocaleString(),
                              write: anthropicCacheUsage.cacheCreationInputTokens.toLocaleString(),
                            })}
                            {anthropicCacheUsage.cacheCreation5mInputTokens > 0 && t('cache5m', { count: anthropicCacheUsage.cacheCreation5mInputTokens })}
                            {anthropicCacheUsage.cacheCreation1hInputTokens > 0 && t('cache1h', { count: anthropicCacheUsage.cacheCreation1hInputTokens })}
                          </span>
                        )}
                        {nanoGptCacheUsage && (
                          <span className={styles.breakdownSource}>
                            {[
                              nanoGptCacheUsage.cacheReadInputTokens > 0 && `read ${nanoGptCacheUsage.cacheReadInputTokens.toLocaleString()}`,
                              nanoGptCacheUsage.cacheCreationInputTokens > 0 && `write ${nanoGptCacheUsage.cacheCreationInputTokens.toLocaleString()}`,
                              nanoGptCacheUsage.cachedTokensOpenAiStyle > 0 && `cached ${nanoGptCacheUsage.cachedTokensOpenAiStyle.toLocaleString()}`,
                            ].filter(Boolean).join(' • ')}
                          </span>
                        )}
                        {openAiCompatibleCacheUsage && (
                          <span className={styles.breakdownSource}>
                            {provider === 'openrouter' ? t('openRouterCache') : t('openAiCache')}
                            {' • '}
                            {[
                              openAiCompatibleCacheUsage.cacheReadInputTokens > 0 && `read ${openAiCompatibleCacheUsage.cacheReadInputTokens.toLocaleString()}`,
                              openAiCompatibleCacheUsage.cacheCreationInputTokens > 0 && `write ${openAiCompatibleCacheUsage.cacheCreationInputTokens.toLocaleString()}`,
                              openAiCompatibleCacheUsage.cachedTokens > 0 && `cached ${openAiCompatibleCacheUsage.cachedTokens.toLocaleString()}`,
                            ].filter(Boolean).join(' • ')}
                          </span>
                        )}
                      </div>
                    )}
                      <div className={styles.breakdownList}>
                        {breakdown.map((entry, i) => {
                          const tokens = tokenBreakdown[i]?.tokens
                          const cacheHint = breakdownCacheHints[i]
                          return (
                            <div key={i} className={styles.breakdownEntry}>
                              <span className={styles.breakdownLabel}>{entry.name}</span>
                              {entry.extensionName && (
                                <span className={styles.breakdownRole}>{entry.extensionName}</span>
                              )}
                              <span className={styles.breakdownSource}>{entry.type}</span>
                              {entry.role && (
                                <span className={styles.breakdownRole}>{entry.role}</span>
                             )}
                              {cacheHint && (
                                <span
                                  className={clsx(
                                    styles.breakdownCacheHint,
                                    cacheHint.kind === 'cached'
                                      ? styles.breakdownCacheHintCached
                                      : styles.breakdownCacheHintMiss,
                                  )}
                                  title={cacheHint.label}
                                >
                                  {cacheHint.kind === 'cached' ? t('cached') : t('uncached')}
                                </span>
                              )}
                             {tokens != null && (
                               <span className={styles.breakdownTokens}>
                                 {ts('tokens', { count: tokens })}
                               </span>
                            )}
                          </div>
                        )
                      })}
                    </div>
                  </div>
                )}
              </div>
            )}

            {/* World Info Stats */}
            {worldInfoStats && (
              <div className={styles.collapsible}>
                <button
                  type="button"
                  className={styles.collapsibleHeader}
                  onClick={() => setWiStatsOpen((o) => !o)}
                >
                  <ChevronRight
                    size={14}
                    className={clsx(styles.chevron, wiStatsOpen && styles.chevronOpen)}
                  />
                  {t('worldInfoSection', {
                    activated: worldInfoStats.totalActivated,
                    evicted: worldInfoStats.evictedByBudget > 0
                      ? t('worldInfoEvicted', { count: worldInfoStats.evictedByBudget })
                      : '',
                  })}
                </button>
                {wiStatsOpen && (
                  <div className={styles.collapsibleBody}>
                    <div className={styles.breakdownList}>
                      <div className={styles.breakdownEntry}>
                        <span className={styles.breakdownLabel}>{t('wi.totalCandidates')}</span>
                        <span className={styles.breakdownTokens}>{worldInfoStats.totalCandidates}</span>
                      </div>
                      <div className={styles.breakdownEntry}>
                        <span className={styles.breakdownLabel}>{t('wi.keywordActivated')}</span>
                        <span className={styles.breakdownTokens}>{worldInfoStats.keywordActivated}</span>
                      </div>
                      <div className={styles.breakdownEntry}>
                        <span className={styles.breakdownLabel}>{t('wi.vectorActivated')}</span>
                        <span className={styles.breakdownTokens}>{worldInfoStats.vectorActivated}</span>
                      </div>
                      <div className={styles.breakdownEntry}>
                        <span className={styles.breakdownLabel}>{t('wi.activatedFinal')}</span>
                        <span className={styles.breakdownTokens}>{worldInfoStats.totalActivated}</span>
                      </div>
                      <div className={styles.breakdownEntry}>
                        <span className={styles.breakdownLabel}>{t('wi.activatedBeforeBudget')}</span>
                        <span className={styles.breakdownTokens}>{worldInfoStats.activatedBeforeBudget}</span>
                      </div>
                      <div className={styles.breakdownEntry}>
                        <span className={styles.breakdownLabel}>{t('wi.activatedAfterBudget')}</span>
                        <span className={styles.breakdownTokens}>{worldInfoStats.activatedAfterBudget}</span>
                      </div>
                      {worldInfoStats.evictedByBudget > 0 && (
                        <div className={styles.breakdownEntry}>
                          <span className={styles.breakdownLabel}>{t('wi.evictedByBudget')}</span>
                          <span className={styles.breakdownTokens} style={{ color: '#ffab00' }}>
                            {worldInfoStats.evictedByBudget}
                          </span>
                        </div>
                      )}
                      {worldInfoStats.evictedByMinPriority > 0 && (
                        <div className={styles.breakdownEntry}>
                          <span className={styles.breakdownLabel}>{t('wi.belowMinPriority')}</span>
                          <span className={styles.breakdownTokens} style={{ color: '#ffab00' }}>
                            {worldInfoStats.evictedByMinPriority}
                          </span>
                        </div>
                      )}
                      <div className={styles.breakdownEntry}>
                        <span className={styles.breakdownLabel}>{t('wi.estimatedTokens')}</span>
                        <span className={styles.breakdownTokens}>{worldInfoStats.estimatedTokens.toLocaleString()}</span>
                      </div>
                      <div className={styles.breakdownEntry}>
                        <span className={styles.breakdownLabel}>{t('wi.recursionPasses')}</span>
                        <span className={styles.breakdownTokens}>{worldInfoStats.recursionPassesUsed}</span>
                      </div>
                      {worldInfoStats.queryPreview && (
                        <div className={styles.breakdownEntry} style={{ flexDirection: 'column', alignItems: 'flex-start', gap: 4 }}>
                          <span className={styles.breakdownLabel}>{t('wi.vectorQueryPreview')}</span>
                          <span className={styles.breakdownSource} style={{ whiteSpace: 'pre-wrap', maxHeight: 80, overflow: 'auto', fontSize: 11 }}>
                            {worldInfoStats.queryPreview}
                          </span>
                        </div>
                      )}
                    </div>
                  </div>
                )}
              </div>
            )}

            {/* Memory Stats */}
            {memoryStats && memoryStats.enabled && (
              <div className={styles.collapsible}>
                <button
                  type="button"
                  className={styles.collapsibleHeader}
                  onClick={() => setMemStatsOpen((o) => !o)}
                >
                  <ChevronRight
                    size={14}
                    className={clsx(styles.chevron, memStatsOpen && styles.chevronOpen)}
                  />
                  {t('memorySection', {
                    retrieved: memoryStats.chunksRetrieved,
                    pending: memoryStats.chunksPending > 0
                      ? t('memoryPending', { count: memoryStats.chunksPending })
