                      </div>
                      <div className={styles.breakdownEntry}>
                        <span className={styles.breakdownLabel}>{t('budget.historyAfter')}</span>
                        <span className={styles.breakdownTokens}>
                          {t('budget.tokens', { count: contextClipStats.chatHistoryTokensAfter })}
