.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 18px;
  border-bottom: 1px solid var(--lumiverse-border);
  flex-shrink: 0;
  background: var(--lumiverse-fill-subtle, rgba(0, 0, 0, 0.06));
}

.headerLeft {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.headerIcon {
  color: var(--lumiverse-info, #42a5f5);
  flex-shrink: 0;
  filter: drop-shadow(0 0 4px color-mix(in srgb, var(--lumiverse-info, #42a5f5) 20%, transparent));
}

.title {
  font-size: calc(14px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* -- Body -- */
.body {
  flex: 1;
  overflow-y: auto;
  padding: 14px 18px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.empty {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  text-align: center;
  padding: 24px 12px;
}

/* -- Add-on card -- */
.addonCard {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 12px;
  border: 1px solid var(--lumiverse-border);
  border-left: 3px solid var(--lumiverse-info, #42a5f5);
  border-radius: 10px;
  background: var(--lumiverse-fill, rgba(0, 0, 0, 0.12));
  transition:
    border-color var(--lumiverse-transition-fast),
    box-shadow var(--lumiverse-transition-fast);
}

.addonCard:hover {
  border-color: var(--lumiverse-border-hover);
  border-left-color: var(--lumiverse-info, #42a5f5);
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.15);
}

.addonTopRow {
  display: flex;
  align-items: center;
  gap: 8px;
}

.globalIndicator {
  width: 22px;
  height: 22px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 5px;
  background: color-mix(in srgb, var(--lumiverse-info, #42a5f5) 12%, transparent);
  color: var(--lumiverse-info, #42a5f5);
  flex-shrink: 0;
}

/* -- Inputs -- */
.addonLabelInput {
  flex: 1;
  min-width: 0;
  background: var(--lumiverse-input-bg, rgba(0, 0, 0, 0.2));
  border: 1px solid var(--lumiverse-border);
  border-radius: 6px;
  padding: 5px 10px;
  font-size: calc(12.5px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  color: var(--lumiverse-text);
  outline: none;
  transition:
    border-color var(--lumiverse-transition-fast),
    box-shadow var(--lumiverse-transition-fast);
}

.addonLabelInput:focus {
  border-color: var(--lumiverse-info, #42a5f5);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--lumiverse-info, #42a5f5) 10%, transparent);
}

.addonActionBtn {
  width: 26px;
  height: 26px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--lumiverse-text-dim);
  cursor: pointer;
  flex-shrink: 0;
  transition: all var(--lumiverse-transition-fast);
  padding: 0;
}

.addonActionBtn:hover {
  color: var(--lumiverse-text);
  border-color: var(--lumiverse-border);
  background: var(--lumiverse-fill-subtle);
}

.addonDeleteBtn:hover {
  color: var(--lumiverse-error);
  border-color: var(--lumiverse-error);
  background: color-mix(in srgb, var(--lumiverse-error) 8%, transparent);
}

.addonContent {
  width: 100%;
  background: var(--lumiverse-input-bg, rgba(0, 0, 0, 0.2));
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  padding: 8px 10px;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text);
  resize: vertical;
  min-height: 48px;
  outline: none;
  font-family: inherit;
  line-height: 1.5;
  transition:
    border-color var(--lumiverse-transition-fast),
    box-shadow var(--lumiverse-transition-fast);
}

.addonContent:focus {
  border-color: var(--lumiverse-info, #42a5f5);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--lumiverse-info, #42a5f5) 10%, transparent);
}

/* -- Footer -- */
.footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 18px;
  border-top: 1px solid var(--lumiverse-border);
  flex-shrink: 0;
  background: var(--lumiverse-fill-subtle, rgba(0, 0, 0, 0.06));
}

.addonCount {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
}

import { useState, useEffect, useCallback, useRef } from 'react'
import { useTranslation } from 'react-i18next'
import { Plus, Check, Trash2, Copy, Globe } from 'lucide-react'
import { ModalShell } from '@/components/shared/ModalShell'
import { CloseButton } from '@/components/shared/CloseButton'
import { Button } from '@/components/shared/FormComponents'
import ConfirmationModal from '@/components/shared/ConfirmationModal'
import { useStore } from '@/store'
import { globalAddonsApi } from '@/api/global-addons'
import { toast } from '@/lib/toast'
import { ExpandableTextarea } from '@/components/shared/ExpandedTextEditor'
import type { GlobalAddon } from '@/types/api'
import styles from './GlobalAddonsLibraryModal.module.css'
import clsx from 'clsx'

export default function GlobalAddonsLibraryModal() {
  const { t } = useTranslation('modals', { keyPrefix: 'globalAddons' })
  const { t: tc } = useTranslation('common')
  const closeModal = useStore((s) => s.closeModal)

  const [addons, setAddons] = useState<GlobalAddon[]>([])
  const [loading, setLoading] = useState(true)
  const [deleteTarget, setDeleteTarget] = useState<GlobalAddon | null>(null)
  const saveTimers = useRef<Map<string, ReturnType<typeof setTimeout>>>(new Map())

  useEffect(() => {
    globalAddonsApi.list({ limit: 200, offset: 0 })
      .then((res) => setAddons(res.data))
      .catch(() => toast.error(t('loadFailed')))
      .finally(() => setLoading(false))
  }, [t])

  const debouncedUpdate = useCallback((id: string, input: Partial<{ label: string; content: string }>) => {
    const existing = saveTimers.current.get(id)
    if (existing) clearTimeout(existing)
    saveTimers.current.set(id, setTimeout(async () => {
      try {
        const updated = await globalAddonsApi.update(id, input)
        setAddons((prev) => prev.map((a) => a.id === id ? updated : a))
      } catch {
        toast.error(t('saveFailed'))
      }
      saveTimers.current.delete(id)
    }, 300))
  }, [t])

  const handleAdd = useCallback(async () => {
    try {
      const addon = await globalAddonsApi.create({ label: '', content: '', sort_order: addons.length })
      setAddons((prev) => [...prev, addon])
    } catch {
      toast.error(t('createFailed'))
    }
  }, [addons.length, t])

  const handleDelete = useCallback(async (id: string) => {
    setDeleteTarget(null)
    try {
      await globalAddonsApi.delete(id)
      setAddons((prev) => prev.filter((a) => a.id !== id))
    } catch {
      toast.error(t('deleteFailed'))
    }
  }, [t])

  const handleDuplicate = useCallback(async (id: string) => {
    try {
      const addon = await globalAddonsApi.duplicate(id)
      setAddons((prev) => [...prev, addon])
    } catch {
      toast.error(t('duplicateFailed'))
    }
  }, [t])

  const handleLabelChange = useCallback((id: string, label: string) => {
    setAddons((prev) => prev.map((a) => a.id === id ? { ...a, label } : a))
    debouncedUpdate(id, { label })
  }, [debouncedUpdate])

  const handleContentChange = useCallback((id: string, content: string) => {
    setAddons((prev) => prev.map((a) => a.id === id ? { ...a, content } : a))
    debouncedUpdate(id, { content })
  }, [debouncedUpdate])

  return (
    <ModalShell isOpen={true} onClose={closeModal} maxWidth={580} className={styles.modal}>
      {/* Header */}
      <div className={styles.header}>
        <div className={styles.headerLeft}>
          <Globe size={15} className={styles.headerIcon} />
          <span className={styles.title}>{t('title')}</span>
        </div>
        <CloseButton onClick={closeModal} size="sm" />
      </div>

      {/* Body */}
      <div className={styles.body}>
        {loading && <div className={styles.empty}>{t('loading')}</div>}
        {!loading && addons.length === 0 && (
          <div className={styles.empty}>{t('empty')}</div>
        )}
        {addons.map((addon) => (
          <div key={addon.id} className={styles.addonCard}>
            <div className={styles.addonTopRow}>
              <div className={styles.globalIndicator}>
                <Globe size={11} />
              </div>
              <input
                type="text"
                className={styles.addonLabelInput}
                value={addon.label}
                onChange={(e) => handleLabelChange(addon.id, e.target.value)}
                placeholder={t('namePlaceholder')}
              />
              <button
                type="button"
                className={styles.addonActionBtn}
                onClick={() => handleDuplicate(addon.id)}
                title={t('duplicateTitle')}
              >
                <Copy size={13} />
              </button>
              <button
                type="button"
                className={clsx(styles.addonActionBtn, styles.addonDeleteBtn)}
                onClick={() => setDeleteTarget(addon)}
                title={t('deleteTitle')}
              >
                <Trash2 size={13} />
              </button>
            </div>
            <ExpandableTextarea
              className={styles.addonContent}
              value={addon.content}
              onChange={(v) => handleContentChange(addon.id, v)}
              title={addon.label || t('contentTitle')}
              placeholder={t('contentPlaceholder')}
              rows={2}
            />
          </div>
        ))}
      </div>

      {/* Footer */}
      <div className={styles.footer}>
        <Button variant="primary" icon={<Plus size={13} />} onClick={handleAdd}>
          {t('addButton')}
        </Button>
        <span className={styles.addonCount}>
          {t('addonCount', { count: addons.length })}
        </span>
      </div>

      {deleteTarget && (
        <ConfirmationModal
          isOpen={true}
          title={t('deleteConfirmTitle')}
          message={deleteTarget.label
            ? t('deleteConfirmMessage', { name: deleteTarget.label })
            : t('deleteConfirmMessageUnnamed')}
          variant="danger"
          confirmText={tc('actions.delete')}
          onConfirm={() => { void handleDelete(deleteTarget.id) }}
          onCancel={() => setDeleteTarget(null)}
        />
      )}
    </ModalShell>
  )
}

