.modal {
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5),
    0 0 40px var(--lumiverse-primary-020);
}

.closeBtnPos {
  top: 16px;
  right: 16px;
  z-index: 10;
}

/* ── Header ── */
.header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 22px 24px 16px;
  padding-right: 64px;
  border-bottom: 1px solid var(--lumiverse-border);
  flex-shrink: 0;
}

.title {
  margin: 0;
  font-size: calc(16px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  color: var(--lumiverse-text);
  letter-spacing: -0.01em;
}

.count {
  margin-left: auto;
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  font-variant-numeric: tabular-nums;
  padding: 2px 8px;
  border-radius: 8px;
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.04));
}

/* ── List ── */
.list {
  padding: 16px 24px 24px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-height: calc(60vh / var(--lumiverse-ui-scale, 1));
  scrollbar-width: thin;
  scrollbar-color: var(--lumiverse-fill-subtle) transparent;
}

.list::-webkit-scrollbar { width: 4px; }
.list::-webkit-scrollbar-track { background: transparent; }
.list::-webkit-scrollbar-thumb {
  background: var(--lumiverse-fill-subtle);
  border-radius: 4px;
}

/* ── Greeting Card ── */
.card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 13px 16px 13px 18px;
  border-radius: var(--lcs-radius-sm, 8px);
  border: 1px solid var(--lcs-glass-border, rgba(255, 255, 255, 0.06));
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.03));
  cursor: pointer;
  text-align: left;
  color: inherit;
  font: inherit;
  transition:
    background var(--lcs-transition, 220ms cubic-bezier(0.4, 0, 0.2, 1)),
    border-color var(--lcs-transition, 220ms cubic-bezier(0.4, 0, 0.2, 1)),
    box-shadow var(--lcs-transition, 220ms cubic-bezier(0.4, 0, 0.2, 1)),
    transform var(--lcs-transition, 220ms cubic-bezier(0.4, 0, 0.2, 1));
  animation: greetingEnter 280ms cubic-bezier(0.16, 1, 0.3, 1) both;
  isolation: isolate;
}

.cardBanner {
  position: absolute;
  z-index: -1;
  top: 0;
  left: 0;
  bottom: 0;
  width: 58%;
  overflow: hidden;
  border-radius: inherit;
  pointer-events: none;
  opacity: 0.62;
  -webkit-mask-image: linear-gradient(to right, #000 0%, rgba(0, 0, 0, 0.3) 70%, transparent 100%);
  mask-image: linear-gradient(to right, #000 0%, rgba(0, 0, 0, 0.3) 70%, transparent 100%);
}

.cardBanner::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to bottom, rgba(0, 0, 0, 0.08), rgba(0, 0, 0, 0.48));
}

.cardBanner img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: saturate(0.9) brightness(0.78);
}

/* Left accent bar */
.card::before {
  content: '';
  position: absolute;
  left: 0;
  top: 8px;
  bottom: 8px;
  width: 3px;
  border-radius: 2px;
  background: var(--lumiverse-fill, rgba(255, 255, 255, 0.06));
  transition:
    background var(--lcs-transition, 220ms cubic-bezier(0.4, 0, 0.2, 1)),
    box-shadow var(--lcs-transition, 220ms cubic-bezier(0.4, 0, 0.2, 1));
}

.card:hover {
  background: var(--lumiverse-fill, rgba(255, 255, 255, 0.06));
  border-color: var(--lumiverse-border);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.12);
  transform: translateX(2px);
}

.card:hover::before {
  background: var(--lumiverse-text-dim, rgba(230, 230, 240, 0.3));
}

.card:active {
  transform: translateX(2px) scale(0.995);
}

/* ── Active greeting card ── */
.cardActive {
  border-color: var(--lumiverse-primary-050);
  background:
    linear-gradient(135deg, var(--lumiverse-primary-010) 0%, transparent 50%),
    var(--lumiverse-primary-010);
  box-shadow:
    0 0 0 0.5px var(--lumiverse-primary-020),
    inset 0 0.5px 0 rgba(255, 255, 255, 0.04);
}

.cardActive::before {
  background: linear-gradient(
    180deg,
    var(--lumiverse-primary) 0%,
    var(--lumiverse-primary-050) 100%
  );
  box-shadow: 0 0 8px var(--lumiverse-primary-020);
}

.cardActive:hover {
  border-color: var(--lumiverse-primary-050);
}

.cardActive:hover::before {
  box-shadow: 0 0 12px var(--lumiverse-primary-050);
}

/* ── Card innards ── */
.cardHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
}

.cardLabel {
  font-size: calc(12.5px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
  letter-spacing: 0.01em;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.badgeRow {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}

.activeBadge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 9px;
  border-radius: 10px;
  background: var(--lumiverse-primary-015);
  color: var(--lumiverse-primary-text);
  font-size: calc(10.5px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  letter-spacing: 0.02em;
}

.mediaBadge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border-radius: 10px;
  background: var(--lumiverse-fill, rgba(255, 255, 255, 0.06));
  color: var(--lumiverse-text-dim);
  font-size: calc(10.5px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  letter-spacing: 0.02em;
}

.cardPreview {
  font-size: calc(12.5px * var(--lumiverse-font-scale, 1));
  line-height: 1.5;
  color: var(--lumiverse-text-dim);
  margin: 2px 0 0;
  font-style: italic;
  word-break: break-word;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* ── Staggered entrance animation ── */
@keyframes greetingEnter {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

import { useEffect, useRef } from 'react'
import { useTranslation } from 'react-i18next'
import { Check, Image as ImageIcon } from 'lucide-react'
import { CloseButton } from '@/components/shared/CloseButton'
import { ModalShell } from '@/components/shared/ModalShell'
import { getGreetingTitle } from '@/lib/greetingMetadata'
import { containsGreetingImageMarkup, getGreetingCellImageUrl } from '@/lib/greetingImage'
import type { Character } from '@/types/api'
import styles from './GreetingPickerModal.module.css'
import clsx from 'clsx'

interface GreetingPickerModalProps {
  character: Character
  activeContent?: string
  activeGreetingIndex?: number
  onSelect: (greetingIndex: number) => void
  onCancel: () => void
}

export default function GreetingPickerModal({
  character,
  activeContent,
  activeGreetingIndex,
  onSelect,
  onCancel,
}: GreetingPickerModalProps) {
  const { t } = useTranslation('modals')

  const greetings = [
    {
      label: getGreetingTitle(character.extensions, 0) || t('greetingPicker.defaultGreeting'),
      content: character.first_mes,
    },
    ...(character.alternate_greetings || []).map((g, i) => ({
      label: getGreetingTitle(character.extensions, i + 1)
        || t('greetingPicker.greetingNumber', { number: i + 2 }),
      content: g,
    })),
  ]

  const activeIndex = activeContent !== undefined
    ? typeof activeGreetingIndex === 'number'
      && Number.isInteger(activeGreetingIndex)
      && greetings[activeGreetingIndex]?.content === activeContent
      ? activeGreetingIndex
      : greetings.findIndex((g) => g.content === activeContent)
    : -1

  const listRef = useRef<HTMLDivElement>(null)
  const activeCardRef = useRef<HTMLButtonElement>(null)
  useEffect(() => {
    if (activeIndex < 0) return
    const list = listRef.current
    const card = activeCardRef.current
    if (!list || !card) return
    const target = card.offsetTop - (list.clientHeight - card.clientHeight) / 2
    list.scrollTop = Math.max(0, target)
  }, [activeIndex])

  return (
    <ModalShell isOpen onClose={onCancel} maxWidth={620} maxHeight="80vh" className={styles.modal}>
      <CloseButton onClick={onCancel} variant="solid" position="absolute" className={styles.closeBtnPos} />

      <div className={styles.header}>
        <h3 className={styles.title}>{t('greetingPicker.title')}</h3>
        <span className={styles.count}>{t('greetingPicker.count', { count: greetings.length })}</span>
      </div>

      <div ref={listRef} className={styles.list}>
        {greetings.map((g, i) => {
          const isActive = i === activeIndex
          const hasImage = containsGreetingImageMarkup(g.content)
          const backgroundUrl = getGreetingCellImageUrl(character, i, g.content)
          return (
            <button
              key={i}
              ref={isActive ? activeCardRef : undefined}
              type="button"
              className={clsx(styles.card, isActive && styles.cardActive)}
              onClick={() => onSelect(i)}
              style={{ animationDelay: `${Math.min(i * 40, 200)}ms` }}
            >
              {backgroundUrl && (
                <div className={styles.cardBanner} aria-hidden="true">
                  <img src={backgroundUrl} alt="" loading="lazy" />
                </div>
              )}
              <div className={styles.cardHeader}>
                <span className={styles.cardLabel}>{g.label}</span>
                <span className={styles.badgeRow}>
                  {hasImage && (
                    <span className={styles.mediaBadge}>
                      <ImageIcon size={10} />
                      {t('greetingPicker.image')}
                    </span>
                  )}
                  {isActive && (
                    <span className={styles.activeBadge}>
                      <Check size={10} />
                      {t('greetingPicker.active')}
                    </span>
                  )}
                </span>
              </div>
              <div className={styles.cardPreview}>{g.content}</div>
            </button>
          )
        })}
      </div>
    </ModalShell>
  )
}

