.selectedPills {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 12px;
  min-height: 32px;
}

.pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 10px 4px 4px;
  border-radius: 20px;
  background: var(--lumiverse-primary-010);
  border: 1px solid var(--lumiverse-primary-020);
  color: var(--lumiverse-text);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
  transition: all 180ms ease;
}

.pill:hover {
  background: var(--lumiverse-primary-015);
  border-color: var(--lumiverse-primary-050);
}

.pillAvatar {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  object-fit: cover;
  background: var(--lumiverse-bg-dark);
}

.pillAvatarFallback {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--lumiverse-bg-dark);
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text-dim);
}

.pillRemove {
  margin-left: 2px;
  opacity: 0.5;
}

/* ── Search ── */
.searchBar {
  position: relative;
  margin-bottom: 12px;
}

.searchInput {
  width: 100%;
  padding: 8px 34px 8px 32px;
  border-radius: 8px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-bg-dark);
  color: var(--lumiverse-text);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  outline: none;
  transition: border-color 180ms ease;
}

.searchInput:focus {
  border-color: var(--lumiverse-primary-050);
}

.searchIcon {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--lumiverse-text-dim);
  pointer-events: none;
}

.searchClear {
  position: absolute;
  right: 8px;
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  padding: 0;
  border: none;
  border-radius: 5px;
  background: transparent;
  color: var(--lumiverse-text-dim);
  cursor: pointer;
}

.searchClear:hover {
  background: var(--lumiverse-fill-hover);
  color: var(--lumiverse-text);
}

/* ── Character grid for selection ── */
.charGrid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(100px, 1fr));
  gap: 8px;
  padding-bottom: 12px;
}

.charItem {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 10px 6px;
  border-radius: 10px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.02));
  cursor: pointer;
  transition: all 180ms ease;
  text-align: center;
}

.charItem:hover {
  background: var(--lumiverse-fill, rgba(255, 255, 255, 0.06));
  border-color: var(--lumiverse-border);
}

.charItemSelected {
  border-color: var(--lumiverse-primary-050);
  background: var(--lumiverse-primary-010);
  box-shadow: 0 0 0 1px var(--lumiverse-primary-020);
}

.charAvatar {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  object-fit: cover;
  background: var(--lumiverse-bg-dark);
}

.charAvatarFallback {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--lumiverse-bg-dark);
  font-size: calc(18px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text-dim);
}

.charName {
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text);
  font-weight: 500;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.checkMark {
  position: absolute;
  top: 4px;
  right: 4px;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--lumiverse-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--lumiverse-primary-contrast, #fff);
}

/* ── Greeting selection (Step 2) ── */
.greetingList {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding-bottom: 12px;
}

.greetingCard {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 12px 16px 12px 18px;
  border-radius: 8px;
  border: 1px solid var(--lcs-glass-border, rgba(255, 255, 255, 0.06));
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.03));
  cursor: pointer;
  text-align: left;
  color: inherit;
  font: inherit;
  transition: all 200ms ease;
  isolation: isolate;
}

.greetingBanner {
  position: absolute;
  z-index: -1;
  top: 0;
  left: 0;
  bottom: 0;
  width: 58%;
  overflow: hidden;
  border-radius: inherit;
  pointer-events: none;
  opacity: 0.62;
  -webkit-mask-image: linear-gradient(to right, #000 0%, rgba(0, 0, 0, 0.3) 70%, transparent 100%);
  mask-image: linear-gradient(to right, #000 0%, rgba(0, 0, 0, 0.3) 70%, transparent 100%);
}

.greetingBanner::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to bottom, rgba(0, 0, 0, 0.08), rgba(0, 0, 0, 0.48));
}

.greetingBanner img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: saturate(0.9) brightness(0.78);
}

.greetingCard::before {
  content: '';
  position: absolute;
  left: 0;
  top: 8px;
  bottom: 8px;
  width: 3px;
  border-radius: 2px;
  background: var(--lumiverse-fill, rgba(255, 255, 255, 0.06));
  transition: all 200ms ease;
}

.greetingCard:hover {
  background: var(--lumiverse-fill, rgba(255, 255, 255, 0.06));
  border-color: var(--lumiverse-border);
}

.greetingCardActive {
  border-color: var(--lumiverse-primary-050);
  background: var(--lumiverse-primary-010);
}

.greetingCardActive::before {
  background: var(--lumiverse-primary);
}

.greetingCharName {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
}

.greetingLabel {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  font-weight: 500;
}

.greetingPreview {
  font-size: calc(12.5px * var(--lumiverse-font-scale, 1));
  line-height: 1.5;
  color: var(--lumiverse-text-dim);
  font-style: italic;
  word-break: break-word;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* ── Settings (Step 3) ── */
.settingsSection {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding-bottom: 12px;
}

.fieldGroup {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.fieldLabel {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
  letter-spacing: 0.01em;
}

.fieldHint {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  line-height: 1.45;
}

.fieldInput {
  width: 100%;
  padding: 8px 12px;
  border-radius: 8px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-bg-dark);
  color: var(--lumiverse-text);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  outline: none;
  transition: border-color 180ms ease;
}

.fieldInput:focus {
  border-color: var(--lumiverse-primary-050);
}

.impersonationModeOptions {
  display: grid;
  grid-template-columns: 1fr;
  gap: 6px;
}

.impersonationModeOption {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  width: 100%;
  padding: 9px 11px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.02));
  color: var(--lumiverse-text);
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: border-color 160ms ease, background 160ms ease;
}

.impersonationModeOption:hover {
  border-color: var(--lumiverse-primary-050);
  background: var(--lumiverse-fill-hover, rgba(255, 255, 255, 0.05));
}

.impersonationModeOptionActive {
  border-color: var(--lumiverse-primary-050);
  background: var(--lumiverse-primary-010);
  box-shadow: 0 0 0 1px var(--lumiverse-primary-020);
}

.impersonationModeTitle {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
}

.impersonationModeDescription {
  font-size: calc(10.5px * var(--lumiverse-font-scale, 1));
  line-height: 1.35;
  color: var(--lumiverse-text-dim);
}

.talkSlider {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  border-radius: 8px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.02));
}

.talkAvatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  object-fit: cover;
  background: var(--lumiverse-bg-dark);
  flex-shrink: 0;
}

.talkAvatarFallback {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--lumiverse-bg-dark);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text-dim);
  flex-shrink: 0;
}

.talkName {
  font-size: calc(12.5px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text);
  font-weight: 500;
  min-width: 60px;
}

.talkRange {
  flex: 1;
  height: 4px;
  accent-color: var(--lumiverse-primary);
}

.talkValue {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  font-variant-numeric: tabular-nums;
  min-width: 28px;
  text-align: right;
}

/* ── Footer ── */
.footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 12px 24px 16px;
  border-top: 1px solid var(--lumiverse-border);
  flex-shrink: 0;
}

.emptyState {
  text-align: center;
  padding: 24px;
  color: var(--lumiverse-text-dim);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
}

import { useState, useEffect, useCallback, useMemo } from 'react'
import { useTranslation } from 'react-i18next'
import { X, Search, Check } from 'lucide-react'
import { useNavigate } from 'react-router'
import { CloseButton } from '@/components/shared/CloseButton'
import { Button } from '@/components/shared/FormComponents'
import { ModalShell } from '@/components/shared/ModalShell'
import { useStore } from '@/store'
import { chatsApi } from '@/api/chats'
import { charactersApi } from '@/api/characters'
import { useCharacterCatalog } from '@/hooks/useCharacterCatalog'
import { getCharacterAvatarThumbUrl } from '@/lib/avatarUrls'
import type { GroupResponseOrder } from '@/lib/groupResponseOrder'
import Pagination from '@/components/shared/Pagination'
import type { Character } from '@/types/api'
import styles from './GroupChatCreatorModal.module.css'
import clsx from 'clsx'
import { clearSearchOnEscape } from '@/lib/clearableSearch'
import { getGreetingTitle } from '@/lib/greetingMetadata'
import { getGreetingCellImageUrl } from '@/lib/greetingImage'
import { toast } from '@/lib/toast'
import { readAccountEpoch } from '@/lib/shared-read'

type Step = 'characters' | 'greeting' | 'settings'
type GroupCardMode = 'swap' | 'merge_ignore_muted' | 'merge'
type GroupLorebookMode = 'follow_card_mode' | 'active_character' | 'all_unmuted' | 'all'

interface GreetingOption {
  characterId: string
  characterName: string
  greetingIndex: number
  label: string
  content: string
  backgroundImageUrl: string | null
}

export default function GroupChatCreatorModal() {
  const { t } = useTranslation('modals', { keyPrefix: 'groupChatCreator' })
  const { t: tg } = useTranslation('modals', { keyPrefix: 'greetingPicker' })
  const { t: tc } = useTranslation('common')

  const navigate = useNavigate()
  const closeModal = useStore((s) => s.closeModal)
  const modalProps = useStore((s) => s.modalProps) as {
    initialCharacterIds?: string[]
    deleteChatIdAfterCreate?: string
  } | null
  const characters = useStore((s) => s.characters)
  const catalog = useCharacterCatalog()
  const [step, setStep] = useState<Step>('characters')
  const [selectedIds, setSelectedIds] = useState<string[]>(modalProps?.initialCharacterIds ?? [])
  const [search, setSearch] = useState('')
  const [selectedGreeting, setSelectedGreeting] = useState<{ characterId: string; greetingIndex: number } | null>(null)
  const [groupName, setGroupName] = useState('')
  const [talkativenessOverrides, setTalkativenessOverrides] = useState<Record<string, number>>({})
  const [groupCardMode, setGroupCardMode] = useState<GroupCardMode>('swap')
  const [groupLorebookMode, setGroupLorebookMode] = useState<GroupLorebookMode>('follow_card_mode')
  const [groupResponseOrder, setGroupResponseOrder] = useState<GroupResponseOrder>('sequential')
  const [scenarioMode, setScenarioMode] = useState<'individual' | 'member' | 'custom'>('individual')
  const [scenarioMemberId, setScenarioMemberId] = useState<string>('')
  const [scenarioCustom, setScenarioCustom] = useState('')
  const [creating, setCreating] = useState(false)
  const [charPage, setCharPage] = useState(1)
  const CHARS_PER_PAGE = 50

  const selectedCharacters = useMemo(
    () => selectedIds.map((id) => characters.find((c) => c.id === id)).filter(Boolean) as Character[],
    [selectedIds, characters]
  )

  useEffect(() => {
    const missing = selectedIds.filter(id => !characters.some(character => character.id === id))
    if (missing.length === 0) return
    const controller = new AbortController()
    const epoch = readAccountEpoch()
    const revision = useStore.getState().characterIndexRevision
    void (async () => {
      for (let offset = 0; offset < missing.length; offset += 100) {
        const ids = missing.slice(offset, offset + 100)
        const items = await charactersApi.getBatch(ids, { signal: controller.signal })
        if (controller.signal.aborted || readAccountEpoch() !== epoch) return
        for (const item of items) {
          if (!useStore.getState().characters.some(character => character.id === item.id)
            && (useStore.getState().characterIndexChanges[item.id] ?? 0) <= revision) {
            useStore.getState().updateCharacter(item.id, item)
          }
        }
        const found = new Set(items.map(item => item.id))
        if (items.length < ids.length) setSelectedIds(previous => previous.filter(id => !ids.includes(id) || found.has(id)))
      }
    })().catch(error => {
      if (!controller.signal.aborted) {
        toast.error(error instanceof Error ? error.message : String(error))
        setSelectedIds(previous => previous.filter(id => !missing.includes(id)))
      }
    })
    return () => controller.abort()
  }, [selectedIds, characters])

  const filteredCharacters = useMemo(() => {
    if (!search.trim()) return catalog
    const q = search.toLowerCase()
    return catalog.filter(
      (c) => c.name.toLowerCase().includes(q) || c.tags?.some((t) => t.toLowerCase().includes(q))
    )
  }, [catalog, search])

  // Reset page when search changes
  useEffect(() => {
    setCharPage(1)
  }, [search])

  const charTotalPages = Math.max(1, Math.ceil(filteredCharacters.length / CHARS_PER_PAGE))
  const safeCharPage = Math.min(charPage, charTotalPages)
  const paginatedChars = useMemo(() => {
    const start = (safeCharPage - 1) * CHARS_PER_PAGE
    return filteredCharacters.slice(start, start + CHARS_PER_PAGE)
  }, [filteredCharacters, safeCharPage])

  // Auto-generate group name from selected characters
  useEffect(() => {
    if (selectedCharacters.length >= 2) {
      const names = selectedCharacters.map((c) => c.name)
      setGroupName(names.join(', '))
    }
  }, [selectedCharacters])

  // Initialize talkativeness from character defaults
  useEffect(() => {
    const overrides: Record<string, number> = {}
    for (const char of selectedCharacters) {
      if (!(char.id in talkativenessOverrides)) {
        overrides[char.id] = char.talkativeness ?? 0.5
      }
    }
    if (Object.keys(overrides).length > 0) {
      setTalkativenessOverrides((prev) => ({ ...prev, ...overrides }))
    }
  }, [selectedCharacters, talkativenessOverrides])

  const greetingOptions = useMemo<GreetingOption[]>(() => {
    const options: GreetingOption[] = []
    for (const char of selectedCharacters) {
      if (char.first_mes) {
        options.push({
          characterId: char.id,
          characterName: char.name,
          greetingIndex: 0,
          label: getGreetingTitle(char.extensions, 0) || t('defaultGreeting'),
          content: char.first_mes,
          backgroundImageUrl: getGreetingCellImageUrl(char, 0, char.first_mes),
        })
      }
      if (char.alternate_greetings) {
        char.alternate_greetings.forEach((g, i) => {
          if (g) {
            options.push({
              characterId: char.id,
              characterName: char.name,
              greetingIndex: i + 1,
              label: getGreetingTitle(char.extensions, i + 1)
                || tg('greetingNumber', { number: i + 2 }),
              content: g,
              backgroundImageUrl: getGreetingCellImageUrl(char, i + 1, g),
            })
          }
        })
      }
    }
    return options
  }, [selectedCharacters, t, tg])

  // Auto-select first greeting when entering step 2
  useEffect(() => {
    if (step === 'greeting' && !selectedGreeting && greetingOptions.length > 0) {
      setSelectedGreeting({
        characterId: greetingOptions[0].characterId,
        greetingIndex: greetingOptions[0].greetingIndex,
      })
    }
  }, [step, selectedGreeting, greetingOptions])

  const toggleCharacter = useCallback((id: string) => {
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id]
    )
  }, [])

  const handleCreate = useCallback(async () => {
    if (creating || selectedIds.length < 2) return
    setCreating(true)
    try {
      const chat = await chatsApi.createGroup({
        character_ids: selectedIds,
        name: groupName || undefined,
        greeting_character_id: selectedGreeting?.characterId,
        greeting_index: selectedGreeting?.greetingIndex,
      })
      // Build extra metadata (talkativeness + scenario override)
      const extraMeta: Record<string, any> = {}
      if (Object.keys(talkativenessOverrides).length > 0) {
        extraMeta.talkativeness_overrides = talkativenessOverrides
      }
      if (groupCardMode !== 'swap') {
        extraMeta.group_card_mode = groupCardMode
      }
      if (groupLorebookMode !== 'follow_card_mode') {
        extraMeta.group_lorebook_mode = groupLorebookMode
      }
      if (groupResponseOrder !== 'sequential') {
        extraMeta.group_response_order = groupResponseOrder
      }
      if (scenarioMode !== 'individual') {
        extraMeta.group_scenario_override = {
          mode: scenarioMode,
          ...(scenarioMode === 'member' && scenarioMemberId ? { member_character_id: scenarioMemberId } : {}),
          ...(scenarioMode === 'custom' ? { content: scenarioCustom } : {}),
        }
      }
      if (Object.keys(extraMeta).length > 0) {
        await chatsApi.update(chat.id, {
          metadata: {
            ...chat.metadata,
            group: true,
            character_ids: selectedIds,
            ...extraMeta,
          },
        })
      }
      closeModal()
      navigate(`/chat/${chat.id}`)
      if (modalProps?.deleteChatIdAfterCreate) {
        void chatsApi.delete(modalProps.deleteChatIdAfterCreate).catch((err) => {
          console.error('[GroupChatCreator] Failed to delete previous chat after creating a new one:', err)
        })
      }
    } catch (err) {
      console.error('[GroupChatCreator] Failed to create group chat:', err)
    } finally {
      setCreating(false)
    }
  }, [creating, selectedIds, groupName, selectedGreeting, talkativenessOverrides, groupCardMode, groupLorebookMode, groupResponseOrder, scenarioMode, scenarioMemberId, scenarioCustom, closeModal, modalProps?.deleteChatIdAfterCreate, navigate])

  const canProceed =
    step === 'characters'
      ? selectedIds.length >= 2 && selectedCharacters.length === selectedIds.length
      : step === 'greeting'
        ? selectedGreeting !== null
        : true

  const handleNext = () => {
    if (step === 'characters') setStep('greeting')
    else if (step === 'greeting') setStep('settings')
    else handleCreate()
  }

  const handleBack = () => {
    if (step === 'greeting') setStep('characters')
    else if (step === 'settings') setStep('greeting')
  }

  const stepLabel = step === 'characters' ? t('step1of3') : step === 'greeting' ? t('step2of3') : t('step3of3')
  const stepTitle =
    step === 'characters'
      ? t('selectCharacters')
      : step === 'greeting'
        ? t('chooseGreeting')
        : t('groupSettings')

  return (
    <ModalShell isOpen={true} onClose={closeModal} maxWidth="clamp(340px, 94vw, min(760px, var(--lumiverse-content-max-width, 760px)))" className={styles.modal}>
          <CloseButton onClick={closeModal} variant="solid" position="absolute" />

          <div className={styles.header}>
            <h3 className={styles.title}>{stepTitle}</h3>
            <span className={styles.stepIndicator}>{stepLabel}</span>
          </div>

          <div className={styles.body}>
            {/* Step 1: Select Characters */}
            {step === 'characters' && (
              <>
                {selectedCharacters.length > 0 && (
                  <div className={styles.selectedPills}>
                    {selectedCharacters.map((char) => (
                      <button
                        key={char.id}
                        type="button"
                        className={styles.pill}
                        onClick={() => toggleCharacter(char.id)}
                      >
                        {char.avatar_path || char.image_id ? (
                          <img
                            src={getCharacterAvatarThumbUrl(char) || undefined}
                            alt={char.name}
                            className={styles.pillAvatar}
                          />
                        ) : (
                          <span className={styles.pillAvatarFallback}>
                            {char.name[0]?.toUpperCase()}
                          </span>
                        )}
                        <span>{char.name}</span>
                        <X size={10} className={styles.pillRemove} />
                      </button>
                    ))}
                  </div>
                )}

                <div className={styles.searchBar}>
                  <Search size={14} className={styles.searchIcon} />
                  <input
                    type="text"
                    className={styles.searchInput}
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                    onKeyDown={(e) => clearSearchOnEscape(e, search, () => setSearch(''))}
                    placeholder={t('searchPlaceholder')}
                  />
                  {search && (
                    <button type="button" className={styles.searchClear} onClick={() => setSearch('')} aria-label={tc('actions.clear')}>
                      <X size={13} />
                    </button>
                  )}
                </div>

                <div className={styles.charGrid}>
                  {paginatedChars.map((char) => {
                    const isSelected = selectedIds.includes(char.id)
                    return (
                      <button
                        key={char.id}
                        type="button"
                        className={clsx(styles.charItem, isSelected && styles.charItemSelected)}
                        onClick={() => toggleCharacter(char.id)}
                      >
                        {char.avatar_path || char.image_id ? (
                          <img
                            src={getCharacterAvatarThumbUrl(char) || undefined}
                            alt={char.name}
                            className={styles.charAvatar}
                            loading="lazy"
                          />
                        ) : (
                          <span className={styles.charAvatarFallback}>
                            {char.name[0]?.toUpperCase()}
                          </span>
                        )}
                        <span className={styles.charName}>{char.name}</span>
                      </button>
                    )
                  })}
                  {filteredCharacters.length === 0 && (
                    <div className={styles.emptyState}>{t('noCharactersFound')}</div>
                  )}
                </div>
                <Pagination
                  currentPage={safeCharPage}
                  totalPages={charTotalPages}
                  onPageChange={setCharPage}
                  totalItems={filteredCharacters.length}
                />
              </>
            )}

            {/* Step 2: Choose Greeting */}
            {step === 'greeting' && (
              <div className={styles.greetingList}>
                {greetingOptions.length === 0 && (
                  <div className={styles.emptyState}>{t('noGreetings')}</div>
                )}
                {greetingOptions.map((opt, i) => {
                  const isActive =
                    selectedGreeting?.characterId === opt.characterId &&
                    selectedGreeting?.greetingIndex === opt.greetingIndex
                  return (
                    <button
                      key={`${opt.characterId}-${opt.greetingIndex}`}
                      type="button"
                      className={clsx(styles.greetingCard, isActive && styles.greetingCardActive)}
                      onClick={() =>
                        setSelectedGreeting({
                          characterId: opt.characterId,
                          greetingIndex: opt.greetingIndex,
                        })
                      }
                    >
                      {opt.backgroundImageUrl && (
                        <div className={styles.greetingBanner} aria-hidden="true">
                          <img src={opt.backgroundImageUrl} alt="" loading="lazy" />
                        </div>
                      )}
                      <div style={{ display: 'flex', alignItems: 'center', gap: 8, justifyContent: 'space-between' }}>
                        <div>
                          <span className={styles.greetingCharName}>{opt.characterName}</span>
                          {' '}
                          <span className={styles.greetingLabel}>— {opt.label}</span>
                        </div>
                        {isActive && <Check size={14} style={{ color: 'var(--lumiverse-primary)' }} />}
                      </div>
                      <div className={styles.greetingPreview}>{opt.content}</div>
                    </button>
                  )
                })}
              </div>
            )}

            {/* Step 3: Group Settings */}
            {step === 'settings' && (
              <div className={styles.settingsSection}>
                <div className={styles.fieldGroup}>
                  <label className={styles.fieldLabel}>{t('groupName')}</label>
                  <input
                    type="text"
                    className={styles.fieldInput}
                    value={groupName}
                    onChange={(e) => setGroupName(e.target.value)}
                    placeholder={t('groupNamePlaceholder')}
                  />
                </div>

                <div className={styles.fieldGroup}>
                  <label className={styles.fieldLabel}>{t('characterCardMacros')}</label>
                  <select
                    className={styles.fieldInput}
                    value={groupCardMode}
                    onChange={(e) => setGroupCardMode(e.target.value as GroupCardMode)}
                  >
                    <option value="swap">{t('cardModeSwap')}</option>
                    <option value="merge_ignore_muted">{t('cardModeMergeUnmuted')}</option>
                    <option value="merge">{t('cardModeMerge')}</option>
                  </select>
                  <div style={{ fontSize: 'calc(11px * var(--lumiverse-font-scale, 1))', color: 'var(--lumiverse-text-dim)', lineHeight: 1.45 }}>
                    {t('cardMacrosHint')}
                  </div>
                </div>

                <div className={styles.fieldGroup}>
                  <label className={styles.fieldLabel}>{t('groupLorebooks')}</label>
                  <select
                    className={styles.fieldInput}
                    value={groupLorebookMode}
                    onChange={(e) => setGroupLorebookMode(e.target.value as GroupLorebookMode)}
                  >
                    <option value="follow_card_mode">{t('lorebookModeFollow')}</option>
                    <option value="active_character">{t('lorebookModeActive')}</option>
                    <option value="all_unmuted">{t('lorebookModeAllUnmuted')}</option>
                    <option value="all">{t('lorebookModeAll')}</option>
                  </select>
                  <div style={{ fontSize: 'calc(11px * var(--lumiverse-font-scale, 1))', color: 'var(--lumiverse-text-dim)', lineHeight: 1.45 }}>
                    {t('groupLorebooksHint')}
                  </div>
                </div>

                <div className={styles.fieldGroup}>
                  <label className={styles.fieldLabel}>{t('groupResponseOrder')}</label>
                  <select
                    className={styles.fieldInput}
                    value={groupResponseOrder}
                    onChange={(e) => setGroupResponseOrder(e.target.value as GroupResponseOrder)}
                  >
                    <option value="sequential">{t('responseOrderSequential')}</option>
                    <option value="random">{t('responseOrderRandom')}</option>
                  </select>
                  <div style={{ fontSize: 'calc(11px * var(--lumiverse-font-scale, 1))', color: 'var(--lumiverse-text-dim)', lineHeight: 1.45 }}>
                    {t('groupResponseOrderHint')}
                  </div>
                </div>

                <div className={styles.fieldGroup}>
                  <label className={styles.fieldLabel}>{t('groupScenario')}</label>
                  <select
                    className={styles.fieldInput}
                    value={scenarioMode === 'member' ? `member:${scenarioMemberId}` : scenarioMode}
                    onChange={(e) => {
                      const val = e.target.value
                      if (val === 'individual') {
                        setScenarioMode('individual')
                        setScenarioMemberId('')
                      } else if (val === 'custom') {
                        setScenarioMode('custom')
                        setScenarioMemberId('')
                      } else if (val.startsWith('member:')) {
                        setScenarioMode('member')
                        setScenarioMemberId(val.slice(7))
                      }
                    }}
                  >
                    <option value="individual">{t('scenarioIndividual')}</option>
                    {selectedCharacters.map((char) => (
                      <option key={char.id} value={`member:${char.id}`}>
                        {t('scenarioFromMemberNamed', { name: char.name })}
                      </option>
                    ))}
                    <option value="custom">{t('scenarioCustom')}</option>
                  </select>
                  {scenarioMode === 'custom' && (
                    <textarea
                      className={styles.fieldInput}
                      value={scenarioCustom}
                      onChange={(e) => setScenarioCustom(e.target.value)}
                      placeholder={t('scenarioPlaceholder')}
                      rows={4}
                      style={{ resize: 'vertical', marginTop: 8 }}
                    />
                  )}
                </div>

                <div className={styles.fieldGroup}>
                  <label className={styles.fieldLabel}>{t('talkativeness')}</label>
                  {selectedCharacters.map((char) => (
                    <div key={char.id} className={styles.talkSlider}>
                      {char.avatar_path || char.image_id ? (
                        <img
                          src={getCharacterAvatarThumbUrl(char) || undefined}
                          alt={char.name}
                          className={styles.talkAvatar}
                        />
                      ) : (
                        <span className={styles.talkAvatarFallback}>
                          {char.name[0]?.toUpperCase()}
                        </span>
                      )}
                      <span className={styles.talkName}>{char.name}</span>
                      <input
                        type="range"
                        min="0"
                        max="1"
                        step="0.05"
                        value={talkativenessOverrides[char.id] ?? 0.5}
                        onChange={(e) =>
                          setTalkativenessOverrides((prev) => ({
                            ...prev,
                            [char.id]: parseFloat(e.target.value),
                          }))
                        }
                        className={styles.talkRange}
                      />
                      <span className={styles.talkValue}>
                        {(talkativenessOverrides[char.id] ?? 0.5).toFixed(2)}
                      </span>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>

          <div className={styles.footer}>
            <Button
              variant="ghost"
              onClick={step === 'characters' ? closeModal : handleBack}
            >
              {step === 'characters' ? tc('actions.cancel') : t('back')}
            </Button>
            <Button
              variant="primary"
              onClick={handleNext}
              disabled={!canProceed || creating}
            >
              {step === 'settings' ? (creating ? t('creating') : t('createGroupChat')) : t('next')}
            </Button>
          </div>
    </ModalShell>
  )
}

