.empty, .loading { display: grid; min-height: 150px; place-items: center; color: var(--lumiverse-text-dim); font-size: calc(13px * var(--lumiverse-font-scale, 1)); text-align: center; }
.footer { display: flex; justify-content: flex-end; padding: 12px 24px; border-top: 1px solid var(--lumiverse-border); }
@media (max-width: 600px) { .header, .toolbar, .list, .footer { padding-left: 16px; padding-right: 16px; } }

import { useCharacterCatalog } from '@/hooks/useCharacterCatalog'
import { useCallback, useEffect, useMemo, useState } from 'react'
import { useTranslation } from 'react-i18next'
import { EyeOff, MessageSquare, Search, UserRound } from 'lucide-react'
import { Button } from '@/components/shared/FormComponents'
import { CloseButton } from '@/components/shared/CloseButton'
import { ModalShell } from '@/components/shared/ModalShell'
import { Spinner } from '@/components/shared/Spinner'
import { chatsApi } from '@/api/chats'
import { charactersApi } from '@/api/characters'
import { useStore } from '@/store'
import { toast } from '@/lib/toast'
import type { HiddenRecentChat } from '@/types/api'
import { formatRelativeTime } from '@/lib/formatRelativeTime'
import styles from './HiddenFromHomeModal.module.css'
import clsx from 'clsx'

type Tab = 'characters' | 'chats'

export default function HiddenFromHomeModal() {
  const { t } = useTranslation('landing')
  const { t: tc } = useTranslation('common')
  const closeModal = useStore((s) => s.closeModal)
  const characters = useCharacterCatalog()
  const hiddenCharacterIds = useStore((s) => s.landingHiddenCharacterIds)
  const setSetting = useStore((s) => s.setSetting)
  const [tab, setTab] = useState<Tab>('characters')
  const [query, setQuery] = useState('')
  const [hiddenChats, setHiddenChats] = useState<HiddenRecentChat[]>([])
  const [resolvedCharacterNames, setResolvedCharacterNames] = useState<Record<string, string>>({})
  const [loadingChats, setLoadingChats] = useState(true)
  const [restoringId, setRestoringId] = useState<string | null>(null)

  const loadHiddenChats = useCallback(async () => {
    try {
      setLoadingChats(true)
      setHiddenChats(await chatsApi.listHiddenFromRecent())
    } catch (error) {
      console.error('[HiddenFromHome] Failed to load hidden chats:', error)
      toast.error(t('hiddenFromHome.loadFailed'))
    } finally {
      setLoadingChats(false)
    }
  }, [t])

  useEffect(() => {
    loadHiddenChats()
  }, [loadHiddenChats])

  useEffect(() => {
    const knownCharacterIds = new Set(characters.map((character) => character.id))
    const missingIds = hiddenCharacterIds.filter((id) => (
      !knownCharacterIds.has(id) && !Object.hasOwn(resolvedCharacterNames, id)
    ))
    if (missingIds.length === 0) return

    let cancelled = false
    Promise.allSettled(missingIds.map(async (id) => {
      const character = await charactersApi.get(id)
      return [id, character.name] as const
    })).then((results) => {
      if (cancelled) return
      const names = results.flatMap((result) => result.status === 'fulfilled' ? [result.value] : [])
      if (names.length === 0) return
      setResolvedCharacterNames((current) => ({ ...current, ...Object.fromEntries(names) }))
    })

    return () => { cancelled = true }
  }, [characters, hiddenCharacterIds, resolvedCharacterNames])

  const hiddenCharacters = useMemo(() => hiddenCharacterIds.map((id) => {
    const character = characters.find((item) => item.id === id)
    return { id, name: character?.name || resolvedCharacterNames[id] || t('hiddenFromHome.missingCharacter') }
  }), [characters, hiddenCharacterIds, resolvedCharacterNames, t])

  const normalizedQuery = query.trim().toLocaleLowerCase()
  const visibleCharacters = useMemo(() => hiddenCharacters.filter((character) => (
    !normalizedQuery || character.name.toLocaleLowerCase().includes(normalizedQuery)
  )), [hiddenCharacters, normalizedQuery])
  const visibleChats = useMemo(() => hiddenChats.filter((chat) => {
    if (!normalizedQuery) return true
    return chat.name.toLocaleLowerCase().includes(normalizedQuery)
      || chat.character_name.toLocaleLowerCase().includes(normalizedQuery)
  }), [hiddenChats, normalizedQuery])

  const restoreCharacter = useCallback((id: string) => {
    setSetting('landingHiddenCharacterIds', hiddenCharacterIds.filter((item) => item !== id))
  }, [hiddenCharacterIds, setSetting])

  const restoreChat = useCallback(async (id: string) => {
    try {
      setRestoringId(id)
      await chatsApi.patchMetadata(id, { hidden_from_recent: false })
      setHiddenChats((chats) => chats.filter((chat) => chat.id !== id))
    } catch (error) {
      console.error('[HiddenFromHome] Failed to restore chat:', error)
      toast.error(t('hiddenFromHome.restoreFailed'))
    } finally {
      setRestoringId(null)
    }
  }, [t])

  const restoreAll = useCallback(async () => {
    if (tab === 'characters') {
      setSetting('landingHiddenCharacterIds', [])
      return
    }
    try {
      setRestoringId('all')
      await Promise.all(hiddenChats.map((chat) => chatsApi.patchMetadata(chat.id, { hidden_from_recent: false })))
      setHiddenChats([])
    } catch (error) {
      console.error('[HiddenFromHome] Failed to restore all chats:', error)
      toast.error(t('hiddenFromHome.restoreFailed'))
      loadHiddenChats()
    } finally {
      setRestoringId(null)
    }
  }, [hiddenChats, loadHiddenChats, setSetting, tab, t])

  const count = tab === 'characters' ? hiddenCharacters.length : hiddenChats.length

  return (
    <ModalShell isOpen onClose={closeModal} maxWidth={620} maxHeight="80vh" className={styles.modal}>
      <CloseButton onClick={closeModal} variant="solid" position="absolute" />
      <header className={styles.header}>
        <div className={styles.titleRow}>
          <EyeOff size={18} />
          <h2>{t('hiddenFromHome.title')}</h2>
        </div>
        <p>{t('hiddenFromHome.description')}</p>
      </header>

      <div className={styles.tabs} role="tablist" aria-label={t('hiddenFromHome.title')}>
        <button type="button" role="tab" aria-selected={tab === 'characters'} className={clsx(styles.tab, tab === 'characters' && styles.tabActive)} onClick={() => setTab('characters')}>
          <UserRound size={14} /> {t('hiddenFromHome.characters', { count: hiddenCharacters.length })}
        </button>
        <button type="button" role="tab" aria-selected={tab === 'chats'} className={clsx(styles.tab, tab === 'chats' && styles.tabActive)} onClick={() => setTab('chats')}>
          <MessageSquare size={14} /> {t('hiddenFromHome.chats', { count: hiddenChats.length })}
        </button>
      </div>

      <div className={styles.toolbar}>
        <label className={styles.search}>
          <Search size={14} />
          <input value={query} onChange={(event) => setQuery(event.target.value)} placeholder={t('hiddenFromHome.search')} />
        </label>
        {count > 0 && <Button variant="ghost" size="sm" onClick={restoreAll} disabled={restoringId !== null}>{t('hiddenFromHome.restoreAll')}</Button>}
      </div>

      <div className={styles.list}>
        {tab === 'characters' && (visibleCharacters.length === 0 ? (
          <EmptyState text={t('hiddenFromHome.noCharacters')} />
        ) : visibleCharacters.map((character) => (
          <div className={styles.row} key={character.id}>
            <span className={styles.rowIcon}><UserRound size={16} /></span>
            <span className={styles.rowText}><strong>{character.name}</strong><small>{t('hiddenFromHome.characterHint')}</small></span>
            <Button variant="ghost" size="sm" onClick={() => restoreCharacter(character.id)}>{t('hiddenFromHome.restore')}</Button>
          </div>
        )))}

        {tab === 'chats' && (loadingChats ? (
          <div className={styles.loading}><Spinner size={20} /></div>
        ) : visibleChats.length === 0 ? (
          <EmptyState text={t('hiddenFromHome.noChats')} />
        ) : visibleChats.map((chat) => (
          <div className={styles.row} key={chat.id}>
            <span className={styles.rowIcon}><MessageSquare size={16} /></span>
            <span className={styles.rowText}>
              <strong>{chat.name || t('hiddenFromHome.unnamedChat')}</strong>
              <small>{chat.is_group ? t('groupChat') : chat.character_name} · {formatRelativeTime(chat.updated_at)}</small>
            </span>
            <Button variant="ghost" size="sm" onClick={() => restoreChat(chat.id)} disabled={restoringId !== null}>{restoringId === chat.id ? <Spinner size={14} /> : t('hiddenFromHome.restore')}</Button>
          </div>
        )))}
      </div>

      <footer className={styles.footer}><Button variant="ghost" onClick={closeModal}>{tc('actions.close')}</Button></footer>
    </ModalShell>
  )
}

function EmptyState({ text }: { text: string }) {
  return <div className={styles.empty}>{text}</div>
}

.modal {
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5),
    0 0 40px var(--lumiverse-primary-020);
}

.header {
  padding: 20px 24px 14px;
  border-bottom: 1px solid var(--lumiverse-border);
}

.title {
  margin: 0;
  font-size: calc(15px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  color: var(--lumiverse-text);
  letter-spacing: -0.01em;
}

.subtitle {
  margin: 4px 0 0;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
  line-height: 1.4;
}

.body {
  padding: 14px 24px 20px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  overflow-y: auto;
}

.fieldGroup {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.label {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.dropZone {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 120px;
  padding: 16px;
  border-radius: var(--lcs-radius-sm, 8px);
  border: 2px dashed var(--lumiverse-border);
  background: var(--lumiverse-bg-dark);
  color: var(--lumiverse-text-muted);
  font-size: calc(12.5px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
  transition: border-color var(--lumiverse-transition-fast),
    background var(--lumiverse-transition-fast);
}

.dropZone:hover,
.dropZoneActive {
  border-color: var(--lumiverse-primary-050, rgba(147, 112, 219, 0.5));
  background: var(--lumiverse-primary-005, rgba(147, 112, 219, 0.05));
}

.dropZoneHint {
  text-align: center;
  line-height: 1.4;
}

.hiddenInput {
  display: none;
}

.preview {
  max-width: 100%;
  max-height: 180px;
  border-radius: var(--lcs-radius-sm, 8px);
  object-fit: contain;
}

.clearBtn {
  position: absolute;
  top: 6px;
  right: 6px;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: none;
  background: var(--lumiverse-bg-darker);
  color: var(--lumiverse-text-muted);
  font-size: 13px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background var(--lumiverse-transition-fast);
}

.clearBtn:hover {
  background: var(--lumiverse-danger, #f87171);
  color: #fff;
}

.textarea {
  width: 100%;
  min-height: 80px;
  max-height: 200px;
  padding: 12px 14px;
  border-radius: var(--lcs-radius-sm, 8px);
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-bg-dark);
  color: var(--lumiverse-text);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  line-height: 1.5;
  resize: vertical;
  font-family: inherit;
  transition: border-color var(--lumiverse-transition-fast);
}

.textarea:focus {
  outline: none;
  border-color: var(--lumiverse-primary-050, rgba(147, 112, 219, 0.5));
}

.outputWrap {
  position: relative;
}

.outputArea {
  width: 100%;
  min-height: 100px;
  max-height: 240px;
  padding: 12px 14px;
  border-radius: var(--lcs-radius-sm, 8px);
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-bg-darker);
  color: var(--lumiverse-text);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  line-height: 1.5;
  resize: vertical;
  font-family: inherit;
}

.outputArea:focus {
  outline: none;
  border-color: var(--lumiverse-primary-050, rgba(147, 112, 219, 0.5));
}

.copyBtn {
  position: absolute;
  top: 8px;
  right: 8px;
  padding: 4px 10px;
  border-radius: var(--lcs-radius-sm, 8px);
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-bg-dark);
  color: var(--lumiverse-text-muted);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
}

.copyBtn:hover {
  background: var(--lumiverse-bg-darker);
  color: var(--lumiverse-text);
}

.actions {
  display: flex;
  align-items: center;
  gap: 8px;
  justify-content: flex-end;
  flex-wrap: wrap;
}

.btn {
  padding: 8px 18px;
  border-radius: var(--lcs-radius-sm, 8px);
  font-size: calc(12.5px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  cursor: pointer;
  border: 1px solid var(--lumiverse-border);
  transition: all var(--lumiverse-transition-fast);
}

.btnCancel {
  background: transparent;
  color: var(--lumiverse-text-muted);
}

.btnCancel:hover {
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.04));
  color: var(--lumiverse-text);
}

.btnSubmit {
  background: var(--lumiverse-primary-015, rgba(147, 112, 219, 0.15));
  color: var(--lumiverse-primary-text, #c4b5fd);
  border-color: var(--lumiverse-primary-020, rgba(147, 112, 219, 0.2));
}

.btnSubmit:hover {
  background: var(--lumiverse-primary-025, rgba(147, 112, 219, 0.25));
  border-color: var(--lumiverse-primary-050, rgba(147, 112, 219, 0.5));
}

.btnSubmit:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.error {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-danger, #f87171);
  margin: 0;
}

.avatarRow {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 6px;
}

.avatarBtn {
  padding: 5px 12px;
  border-radius: var(--lcs-radius-sm, 8px);
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-bg-dark);
  color: var(--lumiverse-text-dim);
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
}

.avatarBtn:hover {
  background: var(--lumiverse-primary-015, rgba(147, 112, 219, 0.15));
  color: var(--lumiverse-primary-text, #c4b5fd);
  border-color: var(--lumiverse-primary-020, rgba(147, 112, 219, 0.2));
}

.avatarBtn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.presetRow {
  display: flex;
  gap: 8px;
  align-items: center;
}

.presetSelect {
  flex: 1;
}

import { useCallback, useEffect, useRef, useState } from 'react'
import { ModalShell } from '@/components/shared/ModalShell'
import { useStore } from '@/store'
import { imageGenApi } from '@/api/image-gen'
import { copyTextToClipboard } from '@/lib/clipboard'
import { getCharacterAvatarUrl, getPersonaAvatarUrl } from '@/lib/avatarUrls'
import type { ImageGenPromptPreset } from '@/types/store'
import styles from './ImageCaptionModal.module.css'

const ACCEPTED_TYPES = ['image/png', 'image/jpeg', 'image/webp', 'image/gif']
const MAX_SIZE_BYTES = 20 * 1024 * 1024
const PROMPT_COMMIT_DELAY_MS = 500

async function fetchImageAsBase64(url: string): Promise<{ data: string; mime: string }> {
  const res = await fetch(url, { credentials: 'include' })
  if (!res.ok) throw new Error(`Failed to fetch image: ${res.status}`)
  const blob = await res.blob()
  const mime = blob.type || 'image/png'
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.onload = () => {
      const dataUrl = reader.result as string
      resolve({ data: dataUrl.slice(dataUrl.indexOf(',') + 1), mime })
    }
    reader.onerror = () => reject(new Error('Failed to read image data'))
    reader.readAsDataURL(blob)
  })
}

export default function ImageCaptionModal() {
  const activeModal = useStore((s) => s.activeModal)
  const closeModal = useStore((s) => s.closeModal)
  const promptPresets = useStore((s) => s.imageGeneration?.promptPresets || [])
  const savedPrompt = useStore((s) => s.imageGeneration?.captionPrompt || '')
  const setImageGenSettings = useStore((s) => s.setImageGenSettings)
  const activeCharacterId = useStore((s) => s.activeCharacterId)
  const characters = useStore((s) => s.characters)
  const activePersonaId = useStore((s) => s.activePersonaId)
  const personas = useStore((s) => s.personas)

  const activeCharacter = activeCharacterId ? characters.find((c) => c.id === activeCharacterId) : null
  const activePersona = activePersonaId ? personas.find((p) => p.id === activePersonaId) : null
  const hasCharacterAvatar = !!(activeCharacter?.image_id || activeCharacter?.avatar_path)
  const hasPersonaAvatar = !!(activePersona?.image_id || (activePersona as any)?.avatar_path)

  const isOpen = activeModal === 'imageCaptioner'

  const [imageData, setImageData] = useState<string | null>(null)
  const [imageMime, setImageMime] = useState<string>('image/png')
  const [prompt, setPrompt] = useState(savedPrompt)
  const [selectedPresetId, setSelectedPresetId] = useState<string | null>(null)
  const [caption, setCaption] = useState('')
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [copied, setCopied] = useState(false)
  const fileInputRef = useRef<HTMLInputElement>(null)
  const [dragOver, setDragOver] = useState(false)
  const [loadingAvatar, setLoadingAvatar] = useState(false)
  const promptRef = useRef(savedPrompt)
  const savedPromptRef = useRef(savedPrompt)
  const promptCommitTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  savedPromptRef.current = savedPrompt

  const captioningPresets = promptPresets.filter(
    (p: ImageGenPromptPreset) => p.kind === 'captioning',
  )

  useEffect(() => {
    if (!isOpen) return
    setImageData(null)
    setImageMime('image/png')
    promptRef.current = savedPromptRef.current
    setPrompt(savedPromptRef.current)
    setSelectedPresetId(null)
    setCaption('')
    setError(null)
    setBusy(false)
    setCopied(false)
  }, [isOpen])

  const commitPrompt = useCallback((nextPrompt: string) => {
    if (nextPrompt === savedPromptRef.current) return
    savedPromptRef.current = nextPrompt
    setImageGenSettings({ captionPrompt: nextPrompt })
  }, [setImageGenSettings])

  const flushPromptCommit = useCallback(() => {
    if (promptCommitTimerRef.current !== null) {
      clearTimeout(promptCommitTimerRef.current)
      promptCommitTimerRef.current = null
    }
    commitPrompt(promptRef.current)
  }, [commitPrompt])

  const updatePrompt = useCallback((nextPrompt: string) => {
    promptRef.current = nextPrompt
    setPrompt(nextPrompt)
    if (promptCommitTimerRef.current !== null) clearTimeout(promptCommitTimerRef.current)
    promptCommitTimerRef.current = setTimeout(() => {
      promptCommitTimerRef.current = null
      commitPrompt(nextPrompt)
    }, PROMPT_COMMIT_DELAY_MS)
  }, [commitPrompt])

  // A close can happen before the debounce expires (including Escape or a
  // backdrop click), so flush the latest local draft before this modal unmounts.
  useEffect(() => () => flushPromptCommit(), [flushPromptCommit])

  const handleClose = useCallback(() => {
    flushPromptCommit()
    closeModal()
  }, [closeModal, flushPromptCommit])

  const loadFile = useCallback((file: File) => {
    if (!ACCEPTED_TYPES.includes(file.type)) {
      setError(`Unsupported format: ${file.type}. Use PNG, JPEG, WebP, or GIF.`)
      return
    }
    if (file.size > MAX_SIZE_BYTES) {
      setError('Image exceeds 20 MB limit.')
      return
    }
    setError(null)
    const reader = new FileReader()
    reader.onload = () => {
      const dataUrl = reader.result as string
      const commaIdx = dataUrl.indexOf(',')
      setImageData(dataUrl.slice(commaIdx + 1))
      setImageMime(file.type)
    }
    reader.readAsDataURL(file)
  }, [])

  const onDrop = useCallback(
    (e: React.DragEvent) => {
      e.preventDefault()
      setDragOver(false)
      const file = e.dataTransfer.files?.[0]
      if (file) loadFile(file)
    },
    [loadFile],
  )

  // Listen for paste at the document level while the modal is open. The modal is
  // portalled to document.body and nothing inside it is autofocused, so a fresh
  // Ctrl+V dispatches to document.body — an ancestor of the modal — and never
  // reaches an onPaste on the modal's own DOM. A document listener catches the
  // paste regardless of focus, mirroring the always-focused chat input textarea.
  useEffect(() => {
    if (!isOpen) return
    const handlePaste = (e: ClipboardEvent) => {
      const items = e.clipboardData?.items
      if (!items) return
      for (const item of items) {
        if (item.type.startsWith('image/')) {
          const file = item.getAsFile()
          if (file) {
            e.preventDefault()
            loadFile(file)
            return
          }
        }
      }
    }
    document.addEventListener('paste', handlePaste)
    return () => document.removeEventListener('paste', handlePaste)
  }, [isOpen, loadFile])

  const loadAvatar = useCallback(async (kind: 'character' | 'persona') => {
    const url = kind === 'character'
      ? getCharacterAvatarUrl(activeCharacter)
      : getPersonaAvatarUrl(activePersona)
    if (!url) return
    setLoadingAvatar(true)
    setError(null)
    try {
      const { data, mime } = await fetchImageAsBase64(url)
      setImageData(data)
      setImageMime(mime)
      setCaption('')
    } catch (err: any) {
      setError(err?.message || `Failed to load ${kind} avatar`)
    } finally {
      setLoadingAvatar(false)
    }
  }, [activeCharacter, activePersona])

  const generate = async () => {
    if (!imageData) return
    flushPromptCommit()
    setBusy(true)
    setError(null)
    setCopied(false)
    try {
      const preset = selectedPresetId
        ? captioningPresets.find((p) => p.id === selectedPresetId)
        : null
      const res = await imageGenApi.caption({
        image: imageData,
        mimeType: imageMime,
        prompt: prompt.trim() || preset?.prompt || undefined,
        presetId: selectedPresetId,
        parserConnectionId: preset?.parserConnectionId,
        parserModel: preset?.parserModel,
        parserParameters: preset?.parserParameters,
      })
      setCaption(res.caption)
    } catch (err: any) {
      setError(err?.body?.error || err?.message || 'Captioning failed')
    } finally {
      setBusy(false)
    }
  }

  const doCopy = async () => {
    if (!caption) return
    await copyTextToClipboard(caption)
    setCopied(true)
    setTimeout(() => setCopied(false), 2000)
  }

  if (!isOpen) return null

  return (
    <ModalShell isOpen={isOpen} onClose={handleClose} maxWidth={560} maxHeight="90vh" className={styles.modal}>
      <div className={styles.header}>
        <h3 className={styles.title}>Image Captioner</h3>
        <p className={styles.subtitle}>
          Upload an image and generate descriptive tags or captions using your parser model.
        </p>
      </div>

      <div className={styles.body}>
        {/* Image upload / drop zone */}
        <div className={styles.fieldGroup}>
          <label className={styles.label}>Image</label>
          <div
            className={`${styles.dropZone} ${dragOver ? styles.dropZoneActive : ''}`}
            onClick={() => fileInputRef.current?.click()}
            onDragOver={(e) => { e.preventDefault(); setDragOver(true) }}
            onDragLeave={() => setDragOver(false)}
            onDrop={onDrop}
          >
            {imageData ? (
              <>
                <img
                  src={`data:${imageMime};base64,${imageData}`}
                  alt="Preview"
                  className={styles.preview}
                />
                <button
                  type="button"
                  className={styles.clearBtn}
                  onClick={(e) => { e.stopPropagation(); setImageData(null); setCaption('') }}
                  title="Remove image"
                >
                  &times;
                </button>
              </>
            ) : (
              <span className={styles.dropZoneHint}>
                {loadingAvatar ? 'Loading avatar...' : 'Drop an image here, click to browse, or paste from clipboard'}
              </span>
            )}
            <input
              ref={fileInputRef}
              type="file"
              accept={ACCEPTED_TYPES.join(',')}
              className={styles.hiddenInput}
              onChange={(e) => {
                const file = e.target.files?.[0]
                if (file) loadFile(file)
                e.target.value = ''
              }}
            />
          </div>
          {(hasCharacterAvatar || hasPersonaAvatar) && !imageData && (
            <div className={styles.avatarRow}>
              {hasCharacterAvatar && (
                <button
                  type="button"
                  className={styles.avatarBtn}
                  onClick={() => loadAvatar('character')}
                  disabled={loadingAvatar}
                >
                  Use {activeCharacter?.name || 'Character'} Avatar
                </button>
              )}
              {hasPersonaAvatar && (
                <button
                  type="button"
                  className={styles.avatarBtn}
                  onClick={() => loadAvatar('persona')}
                  disabled={loadingAvatar}
                >
                  Use {activePersona?.name || 'Persona'} Avatar
                </button>
              )}
            </div>
          )}
        </div>

        {/* Prompt */}
        <div className={styles.fieldGroup}>
          <label className={styles.label}>Prompt</label>
          {captioningPresets.length > 0 && (
            <div className={styles.presetRow}>
              <select
                className={styles.presetSelect}
                value={selectedPresetId || ''}
                onChange={(e) => {
                  const id = e.target.value || null
                  setSelectedPresetId(id)
                  if (id) {
                    const p = captioningPresets.find((pr) => pr.id === id)
                    if (p) updatePrompt(p.prompt)
                  }
                }}
              >
                <option value="">No preset</option>
                {captioningPresets.map((p) => (
                  <option key={p.id} value={p.id}>{p.name}</option>
                ))}
              </select>
            </div>
          )}
          <textarea
            className={styles.textarea}
            value={prompt}
            onChange={(e) => updatePrompt(e.target.value)}
            placeholder="Describe this image in detail using concise image-generation tags..."
            rows={3}
          />
        </div>

        {/* Output */}
        {(caption || busy) && (
          <div className={styles.fieldGroup}>
            <label className={styles.label}>Caption</label>
            <div className={styles.outputWrap}>
              <textarea
                className={styles.outputArea}
                value={busy ? 'Generating caption...' : caption}
                onChange={(e) => setCaption(e.target.value)}
                readOnly={busy}
                rows={4}
              />
              {caption && !busy && (
                <button type="button" className={styles.copyBtn} onClick={doCopy}>
                  {copied ? 'Copied!' : 'Copy'}
                </button>
              )}
            </div>
          </div>
        )}

        {error && <p className={styles.error}>{error}</p>}

        <div className={styles.actions}>
          <button type="button" className={`${styles.btn} ${styles.btnCancel}`} onClick={handleClose} disabled={busy}>
            Close
          </button>
          <button
            type="button"
            className={`${styles.btn} ${styles.btnSubmit}`}
            onClick={generate}
            disabled={busy || !imageData}
          >
            {busy ? 'Captioning...' : caption ? 'Re-caption' : 'Generate Caption'}
          </button>
        </div>
      </div>
    </ModalShell>
  )
}

