/* ── Card grid ── */
.cardGrid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(90px, 1fr));
  gap: 8px;
  padding: 10px;
}

.card {
  position: relative;
  border-radius: var(--lumiverse-radius);
  overflow: hidden;
  cursor: pointer;
  border: 2px solid transparent;
  background: var(--lumiverse-fill-subtle);
  padding: 0;
  font-family: inherit;
  text-align: center;
  transition: border-color var(--lumiverse-transition-fast), box-shadow var(--lumiverse-transition-fast);
}

.card:hover {
  border-color: var(--lumiverse-border-hover);
}

.cardSelected {
  border-color: var(--lumiverse-primary);
  box-shadow: 0 0 0 1px var(--lumiverse-primary);
}

.cardImage {
  position: relative;
  aspect-ratio: 1;
  background: var(--lumiverse-fill);
  overflow: hidden;
}

.cardImg {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.cardPlaceholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: calc(22px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text-dim);
  background: linear-gradient(135deg, var(--lumiverse-primary-010), var(--lumiverse-fill));
}

.cardCheck {
  position: absolute;
  top: 5px;
  right: 5px;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--lumiverse-primary);
  color: var(--lumiverse-primary-contrast, #fff);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transform: scale(0.7);
  transition: opacity var(--lumiverse-transition-fast), transform var(--lumiverse-transition-fast);
}

.cardCheckVisible {
  opacity: 1;
  transform: scale(1);
}

.cardName {
  padding: 6px 4px;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  color: var(--lumiverse-text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ── Footer ── */
.footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 20px;
  border-top: 1px solid var(--lumiverse-border, rgba(255, 255, 255, 0.08));
  flex-shrink: 0;
}

.footerCount {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
}

.doneBtn {
  padding: 8px 20px;
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
