.modal {
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5),
    0 0 40px var(--lumiverse-primary-020);
}

/* ── Header ── */
.header {
  display: flex;
  align-items: flex-start;
  flex-direction: column;
  gap: 4px;
  padding: 22px 24px 16px;
  border-bottom: 1px solid var(--lumiverse-border);
  flex-shrink: 0;
}

.headerLeft {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.title {
  margin: 0;
  font-size: calc(16px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  color: var(--lumiverse-text);
  letter-spacing: -0.01em;
}

.subtitle {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  font-weight: 400;
}

/* ── Toolbar ── */
.toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 24px;
  border-bottom: 1px solid var(--lumiverse-border);
  flex-shrink: 0;
}

.searchWrap {
  position: relative;
  flex: 1;
}

.searchInput {
  width: 100%;
  padding: 8px 34px 8px 32px;
  border-radius: 8px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-bg-dark);
  color: var(--lumiverse-text);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  outline: none;
  transition: border-color 180ms ease;
}

.searchInput:focus {
  border-color: var(--lumiverse-primary-050);
}

.searchIcon {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--lumiverse-text-dim);
  pointer-events: none;
}

.searchClear {
  position: absolute;
  right: 8px;
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  padding: 0;
  border: none;
  border-radius: 5px;
  background: transparent;
  color: var(--lumiverse-text-dim);
  cursor: pointer;
}

.searchClear:hover {
  background: var(--lumiverse-fill-hover);
  color: var(--lumiverse-text);
}

.bulkModeBtn {
  border-color: var(--lumiverse-border) !important;
}

.bulkModeBtnActive {
  color: var(--lumiverse-primary) !important;
  background: var(--lumiverse-primary-010) !important;
  border-color: var(--lumiverse-primary-050) !important;
}

/* ── Bulk selection ── */
.bulkBar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 9px 24px;
  border-bottom: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-primary-010);
  flex-shrink: 0;
}

.bulkSummary,
.bulkActions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.bulkSelectAll {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 0;
  border: none;
  background: transparent;
  color: var(--lumiverse-primary);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
}

.bulkCount {
  color: var(--lumiverse-text-dim);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  white-space: nowrap;
}

.bulkActionBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 5px 9px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 7px;
  background: var(--lumiverse-bg-dark);
  color: var(--lumiverse-text-dim);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
  transition: all 180ms ease;
}

.bulkActionBtn:hover:not(:disabled) {
  color: var(--lumiverse-text);
  border-color: var(--lumiverse-primary-050);
  background: var(--lumiverse-fill);
}

.bulkDeleteBtn:hover:not(:disabled) {
  color: var(--lumiverse-danger, #ef4444);
  border-color: color-mix(in srgb, var(--lumiverse-danger, #ef4444) 55%, var(--lumiverse-border));
}

.bulkSelectAll:disabled,
.bulkActionBtn:disabled {
  opacity: 0.45;
  cursor: default;
}

/* .sortBtn — migrated to shared Button component */

/* ── Body ── */
.body {
  padding: 12px 24px 8px;
  overflow-y: auto;
  flex: 1;
  min-height: 0;
  scrollbar-width: thin;
  scrollbar-color: var(--lumiverse-fill-subtle) transparent;
}

.body::-webkit-scrollbar { width: 4px; }
.body::-webkit-scrollbar-track { background: transparent; }
.body::-webkit-scrollbar-thumb {
  background: var(--lumiverse-fill-subtle);
  border-radius: 4px;
}

/* ── Chat card ── */
.card {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border-radius: 10px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.02));
  margin-bottom: 8px;
  transition: all 180ms ease;
}

.card:hover {
  background: var(--lumiverse-fill, rgba(255, 255, 255, 0.05));
  border-color: var(--lumiverse-border);
}

.cardActive {
  border-color: var(--lumiverse-primary-050);
  background: var(--lumiverse-primary-010);
}

.cardActive:hover {
  background: var(--lumiverse-primary-015);
}

.cardSelectable {
  cursor: pointer;
}

.cardSelected,
.cardSelected:hover {
  border-color: var(--lumiverse-primary-050);
  background: var(--lumiverse-primary-015);
}

.selectionBtn {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 22px;
  height: 22px;
  padding: 0;
  border: none;
  border-radius: 5px;
  background: transparent;
  color: var(--lumiverse-primary);
  cursor: pointer;
}

.selectionBtn:hover {
  background: var(--lumiverse-primary-010);
}

.cardIcon {
  flex-shrink: 0;
  color: var(--lumiverse-text-dim);
}

.cardIconActive {
  color: var(--lumiverse-primary);
}

.cardInfo {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.cardName {
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cardPreview {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cardMeta {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
}

.cardMetaItem {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.activeBadge {
  display: inline-flex;
  align-items: center;
  padding: 2px 7px;
  border-radius: 6px;
  background: var(--lumiverse-primary-010);
  border: 1px solid var(--lumiverse-primary-050);
  color: var(--lumiverse-primary);
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}

.cardActions {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
}

/* .actionBtn, .actionBtnDanger — migrated to shared Button component */

/* Color override for primary hover (applied via className on shared Button) */
.actionBtnPrimary:hover {
  background: var(--lumiverse-primary-010) !important;
  color: var(--lumiverse-primary) !important;
  border-color: var(--lumiverse-primary-050) !important;
}

/* ── Inline rename input ── */
.editInput {
  width: 100%;
  padding: 4px 8px;
  border-radius: 6px;
  border: 1px solid var(--lumiverse-primary-050);
  background: var(--lumiverse-bg-dark);
  color: var(--lumiverse-text);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  outline: none;
}

/* ── Empty + Loading states ── */
.empty {
  text-align: center;
  padding: 32px 16px;
  color: var(--lumiverse-text-dim);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
}

.loading {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px 16px;
  color: var(--lumiverse-text-dim);
  gap: 8px;
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
}

/* ── New chat button ── */
.newChatBtn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  padding: 10px 16px;
  margin: 4px 0 8px;
  border-radius: 8px;
  border: 1px dashed var(--lumiverse-primary-050);
  background: var(--lumiverse-primary-010);
  color: var(--lumiverse-text);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  cursor: pointer;
  transition: all 180ms ease;
}

.newChatBtn:hover {
  background: var(--lumiverse-primary-015);
  border-style: solid;
}

.newChatBtn svg {
  color: var(--lumiverse-primary);
}

@media (max-width: 480px) {
  .toolbar {
    flex-wrap: wrap;
  }

  .searchWrap {
    flex-basis: 100%;
  }

  .bulkBar {
    align-items: stretch;
    flex-direction: column;
  }

  .bulkSummary {
    justify-content: space-between;
  }

  .bulkActions > button {
    flex: 1;
  }
}

