.modal {
  box-shadow:
    var(--lumiverse-shadow-xl),
    0 0 40px var(--lumiverse-primary-010);
}

/* -- Header -- */
.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 18px;
  border-bottom: 1px solid var(--lumiverse-border);
  flex-shrink: 0;
  background: var(--lumiverse-fill-subtle, rgba(0, 0, 0, 0.06));
}

.headerLeft {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.headerIcon {
  color: var(--lumiverse-primary);
  flex-shrink: 0;
  filter: drop-shadow(0 0 4px var(--lumiverse-primary-020));
}

.title {
  font-size: calc(14px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* -- Body -- */
.body {
  flex: 1;
  overflow-y: auto;
  padding: 14px 18px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.empty {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  text-align: center;
  padding: 24px 12px;
}

/* -- Section headers -- */
.sectionHeader {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  padding: 4px 0 2px;
}

.sectionIconPersona {
  color: var(--lumiverse-primary);
}

.sectionIconGlobal {
  color: var(--lumiverse-info, #42a5f5);
}

.manageLibraryBtn {
  margin-left: auto;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  color: var(--lumiverse-info, #42a5f5);
  background: none;
  border: none;
  cursor: pointer;
  padding: 2px 6px;
  border-radius: 4px;
  text-transform: none;
  letter-spacing: normal;
  transition: all var(--lumiverse-transition-fast);
}

.manageLibraryBtn:hover {
  background: color-mix(in srgb, var(--lumiverse-info, #42a5f5) 10%, transparent);
}

.emptySection {
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  font-style: italic;
  padding: 6px 4px;
}

.sectionHint {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  padding: 0 4px 2px;
}

.sectionDivider {
  height: 1px;
  background: var(--lumiverse-border);
  margin: 6px 0;
}

.sectionAddRow {
  display: flex;
  align-items: center;
  padding: 2px 0;
}

.sectionAddBtn {
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
}

/* -- Add-on card -- */
.addonCard {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 12px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 10px;
  background: var(--lumiverse-fill, rgba(0, 0, 0, 0.12));
  transition:
    border-color var(--lumiverse-transition-fast),
    box-shadow var(--lumiverse-transition-fast);
}

.addonCard:hover {
  border-color: var(--lumiverse-border-hover);
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.15);
}

.addonCardGlobal {
  border-left: 3px solid var(--lumiverse-info, #42a5f5);
}

.addonCardGlobal:hover {
  border-left-color: var(--lumiverse-info, #42a5f5);
}

.addonCardDisabled {
  opacity: 0.55;
}

.addonTopRow {
  display: flex;
  align-items: center;
  gap: 8px;
}

.addonAvatarControls {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  flex-shrink: 0;
}

.addonAvatarThumb {
  width: 26px;
  height: 26px;
  object-fit: cover;
  border-radius: 5px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-fill-subtle, rgba(0, 0, 0, 0.06));
}

.avatarFileInput {
  display: none;
}

.addonAvatarBtn {
  width: 26px;
  height: 26px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 1px solid transparent;
  border-radius: 6px;
  background: transparent;
  color: var(--lumiverse-text-dim);
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
}

.addonAvatarBtn:hover:not(:disabled) {
  color: var(--lumiverse-primary);
  border-color: var(--lumiverse-primary);
  background: var(--lumiverse-primary-010);
}

.addonAvatarBtn:disabled {
  opacity: 0.45;
  cursor: wait;
}

.addonAvatarRemoveBtn:hover:not(:disabled) {
  color: var(--lumiverse-error);
  border-color: var(--lumiverse-error);
  background: color-mix(in srgb, var(--lumiverse-error) 8%, transparent);
}

/* -- Drag handle --
 * touch-action: none lets dnd-kit's TouchSensor own the gesture.
 * -webkit-touch-callout / user-select: none stop iOS & Android from popping
 * the native "Copy/Share" callout on press-and-hold of the handle, which
 * would otherwise race with dnd-kit's hold-to-drag activation.
 */
.addonDragHandle {
  width: 20px;
  height: 26px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: none;
  background: transparent;
  color: var(--lumiverse-text-dim);
  cursor: grab;
  flex-shrink: 0;
  padding: 0;
  border-radius: 4px;
  transition: color var(--lumiverse-transition-fast), background var(--lumiverse-transition-fast);
  touch-action: none;
  -webkit-touch-callout: none;
  -webkit-user-select: none;
  user-select: none;
}

.addonDragHandle:hover {
  color: var(--lumiverse-text);
  background: var(--lumiverse-fill-subtle, rgba(0, 0, 0, 0.06));
}

.addonDragHandle:active {
  cursor: grabbing;
}

/* -- Toggle checkbox -- */
.addonToggle {
  width: 26px;
  height: 26px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-input-bg, rgba(0, 0, 0, 0.2));
  color: var(--lumiverse-text-dim);
  cursor: pointer;
  flex-shrink: 0;
  transition: all var(--lumiverse-transition-fast);
  padding: 0;
}

.addonToggle:hover {
  border-color: var(--lumiverse-primary);
  color: var(--lumiverse-primary);
}

.addonToggleActive {
  background: var(--lumiverse-primary);
  border-color: var(--lumiverse-primary);
  color: var(--lumiverse-primary-contrast, #fff);
  box-shadow: 0 0 8px var(--lumiverse-primary-020);
}

.addonToggleActiveGlobal {
  background: var(--lumiverse-info, #42a5f5);
  border-color: var(--lumiverse-info, #42a5f5);
  color: #fff;
  box-shadow: 0 0 8px color-mix(in srgb, var(--lumiverse-info, #42a5f5) 20%, transparent);
}

/* -- Global addon display -- */
.globalIndicator {
  width: 18px;
  height: 18px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 4px;
  background: color-mix(in srgb, var(--lumiverse-info, #42a5f5) 12%, transparent);
  color: var(--lumiverse-info, #42a5f5);
  flex-shrink: 0;
}

.globalAddonLabel {
  flex: 1;
  min-width: 0;
  font-size: calc(12.5px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  color: var(--lumiverse-text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.globalAddonPreview {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  line-height: 1.5;
  padding: 4px 6px;
  background: var(--lumiverse-fill-subtle, rgba(0, 0, 0, 0.06));
  border-radius: 6px;
  white-space: pre-wrap;
  word-break: break-word;
}

.detachBtn {
  width: 26px;
  height: 26px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--lumiverse-text-dim);
  cursor: pointer;
  flex-shrink: 0;
  transition: all var(--lumiverse-transition-fast);
  padding: 0;
}

.detachBtn:hover {
  color: var(--lumiverse-warning, #f59e0b);
  border-color: var(--lumiverse-warning, #f59e0b);
  background: color-mix(in srgb, var(--lumiverse-warning, #f59e0b) 8%, transparent);
}

/* -- Inputs -- */
.addonLabelInput {
  flex: 1;
  min-width: 0;
  background: var(--lumiverse-input-bg, rgba(0, 0, 0, 0.2));
  border: 1px solid var(--lumiverse-border);
  border-radius: 6px;
  padding: 5px 10px;
  font-size: calc(12.5px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  color: var(--lumiverse-text);
  outline: none;
  transition:
    border-color var(--lumiverse-transition-fast),
    box-shadow var(--lumiverse-transition-fast);
}

.addonLabelInput:focus {
  border-color: var(--lumiverse-primary);
  box-shadow: 0 0 0 2px var(--lumiverse-primary-010);
}

.addonDeleteBtn {
  width: 26px;
  height: 26px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--lumiverse-text-dim);
  cursor: pointer;
  flex-shrink: 0;
  transition: all var(--lumiverse-transition-fast);
  padding: 0;
}

.addonDeleteBtn:hover {
  color: var(--lumiverse-error);
  border-color: var(--lumiverse-error);
  background: color-mix(in srgb, var(--lumiverse-error) 8%, transparent);
}

.addonContent {
  width: 100%;
  background: var(--lumiverse-input-bg, rgba(0, 0, 0, 0.2));
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  padding: 8px 10px;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text);
  resize: vertical;
  min-height: 48px;
  outline: none;
  font-family: inherit;
  line-height: 1.5;
  transition:
    border-color var(--lumiverse-transition-fast),
    box-shadow var(--lumiverse-transition-fast);
}

.addonContent:focus {
  border-color: var(--lumiverse-primary);
  box-shadow: 0 0 0 2px var(--lumiverse-primary-010);
}

/* -- Outlet placement -- */
.outletRow {
  display: flex;
  align-items: center;
  gap: 8px;
}

.outletLabel {
  flex: 0 0 auto;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
}

.outletInput {
  flex: 1;
  min-width: 0;
  background: var(--lumiverse-input-bg, rgba(0, 0, 0, 0.2));
  border: 1px solid var(--lumiverse-border);
  border-radius: 6px;
  padding: 5px 8px;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text);
  outline: none;
}

.outletInput:focus {
  border-color: var(--lumiverse-primary);
  box-shadow: 0 0 0 2px var(--lumiverse-primary-010);
}

.outletHint {
  margin-top: -3px;
  font-size: calc(10.5px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
}

/* -- Attach picker popover -- */
.attachWrapper {
  position: relative;
}

.attachPopover {
  position: absolute;
  bottom: 100%;
  left: 0;
  min-width: 220px;
  max-height: 200px;
  overflow-y: auto;
  background: var(--lumiverse-bg-elevated, rgba(35, 30, 48, 0.95));
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  box-shadow: var(--lumiverse-shadow-lg, 0 8px 32px rgba(0, 0, 0, 0.3));
  padding: 4px;
  margin-bottom: 4px;
  z-index: 10;
}

.attachPopoverItem {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 7px 10px;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: var(--lumiverse-text);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
  text-align: left;
  transition: background var(--lumiverse-transition-fast);
}

.attachPopoverItem:hover {
  background: var(--lumiverse-fill-subtle);
}

.attachPopoverIcon {
  color: var(--lumiverse-info, #42a5f5);
  flex-shrink: 0;
}

/* -- Footer -- */
.footer {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 10px 18px;
  border-top: 1px solid var(--lumiverse-border);
  flex-shrink: 0;
  background: var(--lumiverse-fill-subtle, rgba(0, 0, 0, 0.06));
}

.addonCount {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
}

import { useState, useEffect, useCallback, useRef } from 'react'
import { useTranslation } from 'react-i18next'
import { Plus, Check, Trash2, Globe, Link2, Unlink, GripVertical, ImagePlus, ImageOff } from 'lucide-react'
import { IconPlaylistAdd } from '@tabler/icons-react'
import {
  MouseSensor,
  TouchSensor,
  KeyboardSensor,
  closestCenter,
  useSensor,
  useSensors,
  type DragEndEvent,
} from '@dnd-kit/core'
import {
  SortableContext,
  arrayMove,
  sortableKeyboardCoordinates,
  useSortable,
  verticalListSortingStrategy,
} from '@dnd-kit/sortable'
import { DndContext, useScaledSortableStyle } from '@/lib/dndUiScale'
import { ModalShell } from '@/components/shared/ModalShell'
import { CloseButton } from '@/components/shared/CloseButton'
import { Button } from '@/components/shared/FormComponents'
import { useStore } from '@/store'
import { personasApi } from '@/api/personas'
import { globalAddonsApi } from '@/api/global-addons'
import { imagesApi } from '@/api/images'
import { toast } from '@/lib/toast'
import { ExpandableTextarea } from '@/components/shared/ExpandedTextEditor'
import type { Persona, PersonaAddon, GlobalAddon, AttachedGlobalAddon } from '@/types/api'
import styles from './PersonaAddonsModal.module.css'
import { uuidv7 } from '@/lib/uuid'
import clsx from 'clsx'

interface PersonaMetadataSave {
  metadata: Record<string, any>
  addonRevision: number
  attachedRevision: number
  failureMessage: string
}

function mergePersonaAddonDraft(serverAddons: PersonaAddon[], localAddons: PersonaAddon[]): PersonaAddon[] {
  const serverById = new Map(serverAddons.map((addon) => [addon.id, addon]))
  return localAddons.map((localAddon) => {
    const serverAddon = serverById.get(localAddon.id)
    if (!serverAddon) return localAddon
    return {
      ...serverAddon,
      ...localAddon,
      // Avatar fields are changed by their dedicated endpoints, so retain the
      // server's result while preserving fields editable in this modal.
      avatar_image_id: serverAddon.avatar_image_id,
      avatar_crop_image_id: serverAddon.avatar_crop_image_id,
    }
  })
}

function mergeAttachedAddonDraft(
  serverRefs: AttachedGlobalAddon[],
  localRefs: AttachedGlobalAddon[],
): AttachedGlobalAddon[] {
  const serverById = new Map(serverRefs.map((ref) => [ref.id, ref]))
  return localRefs.map((localRef) => {
    const serverRef = serverById.get(localRef.id)
    if (!serverRef) return localRef
    return {
      ...serverRef,
      ...localRef,
      avatar_image_id: serverRef.avatar_image_id,
      avatar_crop_image_id: serverRef.avatar_crop_image_id,
    }
  })
}

export default function PersonaAddonsModal() {
  const { t } = useTranslation('modals', { keyPrefix: 'personaAddons' })
  const { t: tc } = useTranslation('common')

  const modalProps = useStore((s) => s.modalProps)
  const closeModal = useStore((s) => s.closeModal)
  const openModal = useStore((s) => s.openModal)
  const updatePersonaInStore = useStore((s) => s.updatePersona)

  const personaId = modalProps?.personaId as string
  const personaName = modalProps?.personaName as string | undefined

  const [addons, setAddons] = useState<PersonaAddon[]>([])
  const [loading, setLoading] = useState(true)
  const saveTimer = useRef<ReturnType<typeof setTimeout>>(undefined)
  const metadataRef = useRef<Record<string, any>>({})
  const addonsRef = useRef<PersonaAddon[]>([])
  const attachedRefsRef = useRef<AttachedGlobalAddon[]>([])
  const addonRevisionRef = useRef(0)
  const attachedRevisionRef = useRef(0)
  const pendingSaveRef = useRef<PersonaMetadataSave | null>(null)
  const saveInFlightRef = useRef(false)
  const flushMetadataSaveRef = useRef<() => void>(() => {})

  // Global add-on state
  const [allGlobalAddons, setAllGlobalAddons] = useState<GlobalAddon[]>([])
  const [attachedRefs, setAttachedRefs] = useState<AttachedGlobalAddon[]>([])
  const [showAttachPicker, setShowAttachPicker] = useState(false)
  const [avatarOperationAddonId, setAvatarOperationAddonId] = useState<string | null>(null)

  const adoptPersona = useCallback((persona: Persona, saved?: PersonaMetadataSave) => {
    const serverMetadata = persona.metadata || {}
    const serverAddons: PersonaAddon[] = Array.isArray(serverMetadata.addons) ? serverMetadata.addons : []
    const serverAttachedRefs: AttachedGlobalAddon[] = Array.isArray(serverMetadata.attached_global_addons)
      ? serverMetadata.attached_global_addons
      : []

    // A request may finish after the user has resumed typing. In that case its
    // payload is an acknowledged server snapshot, not the current UI value.
    // Overlay only the newer local draft so React never writes stale content
    // into the controlled textarea (which also moves the native caret).
    const nextAddons = saved && saved.addonRevision !== addonRevisionRef.current
      ? mergePersonaAddonDraft(serverAddons, addonsRef.current)
      : serverAddons
    const nextAttachedRefs = saved && saved.attachedRevision !== attachedRevisionRef.current
      ? mergeAttachedAddonDraft(serverAttachedRefs, attachedRefsRef.current)
      : serverAttachedRefs
    const nextMetadata = {
      ...serverMetadata,
      addons: nextAddons,
      attached_global_addons: nextAttachedRefs,
    }

    metadataRef.current = nextMetadata
    addonsRef.current = nextAddons
    attachedRefsRef.current = nextAttachedRefs
    setAddons(nextAddons)
    setAttachedRefs(nextAttachedRefs)
    updatePersonaInStore(personaId, { ...persona, metadata: nextMetadata })
  }, [personaId, updatePersonaInStore])

  const flushMetadataSave = useCallback(() => {
    if (saveInFlightRef.current) return
    const pending = pendingSaveRef.current
    if (!pending) return

    pendingSaveRef.current = null
    saveInFlightRef.current = true
    void personasApi.update(personaId, { metadata: pending.metadata })
      .then((updated) => adoptPersona(updated, pending))
      .catch(() => toast.error(pending.failureMessage))
      .finally(() => {
        saveInFlightRef.current = false
        // Coalesce edits made during the request, then write them only after
        // the preceding snapshot is acknowledged. This prevents out-of-order
        // PUTs from leaving stale content on the server.
        if (pendingSaveRef.current) flushMetadataSaveRef.current()
      })
  }, [adoptPersona, personaId])
  flushMetadataSaveRef.current = flushMetadataSave

  const scheduleMetadataSave = useCallback((failureMessage: string, delay: number) => {
    clearTimeout(saveTimer.current)
    saveTimer.current = setTimeout(() => {
      pendingSaveRef.current = {
        metadata: { ...metadataRef.current },
        addonRevision: addonRevisionRef.current,
        attachedRevision: attachedRevisionRef.current,
        failureMessage,
      }
      flushMetadataSaveRef.current()
    }, delay)
  }, [])

  // Load persona data + global addons
  useEffect(() => {
    if (!personaId) return
    Promise.all([
      personasApi.get(personaId),
      globalAddonsApi.list({ limit: 200, offset: 0 }),
    ])
      .then(([p, globalRes]) => {
        adoptPersona(p)
        setAllGlobalAddons(globalRes.data)
      })
      .catch(() => toast.error(t('loadFailed')))
      .finally(() => setLoading(false))
  }, [personaId, t, adoptPersona])

  // Debounced save helper for persona-specific addons
  const persistAddons = useCallback(() => {
    scheduleMetadataSave(t('saveFailed'), 300)
  }, [scheduleMetadataSave, t])

  // Save helper for attached global addon refs
  const persistAttachedRefs = useCallback(() => {
    scheduleMetadataSave(t('saveAttachmentFailed'), 0)
  }, [scheduleMetadataSave, t])

  const commitAddons = useCallback((next: PersonaAddon[]) => {
    addonRevisionRef.current += 1
    addonsRef.current = next
    metadataRef.current = { ...metadataRef.current, addons: next }
    setAddons(next)
    persistAddons()
  }, [persistAddons])

  const commitAttachedRefs = useCallback((next: AttachedGlobalAddon[]) => {
    attachedRevisionRef.current += 1
    attachedRefsRef.current = next
    metadataRef.current = { ...metadataRef.current, attached_global_addons: next }
    setAttachedRefs(next)
    persistAttachedRefs()
  }, [persistAttachedRefs])

  const handleUploadAddonAvatar = useCallback(async (addonId: string, file: File) => {
    if (avatarOperationAddonId) return
    clearTimeout(saveTimer.current)
    setAvatarOperationAddonId(addonId)
    try {
      adoptPersona(await personasApi.uploadAddonAvatar(personaId, addonId, file))
    } catch {
      toast.error(t('avatarUploadFailed'))
    } finally {
      setAvatarOperationAddonId(null)
    }
  }, [avatarOperationAddonId, personaId, adoptPersona, t])

  const handleRemoveAddonAvatar = useCallback(async (addonId: string) => {
    if (avatarOperationAddonId) return
    clearTimeout(saveTimer.current)
    setAvatarOperationAddonId(addonId)
    try {
      adoptPersona(await personasApi.deleteAddonAvatar(personaId, addonId))
    } catch {
      toast.error(t('avatarRemoveFailed'))
    } finally {
      setAvatarOperationAddonId(null)
    }
  }, [avatarOperationAddonId, personaId, adoptPersona, t])

  // Persona-specific addon handlers
  const handleAdd = useCallback(() => {
    const newAddon: PersonaAddon = {
      id: uuidv7(),
      label: '',
      content: '',
      enabled: true,
      sort_order: addons.length,
    }
    const next = [...addons, newAddon]
    commitAddons(next)
  }, [addons, commitAddons])

  const handleToggle = useCallback((id: string) => {
    const next = addons.map((a) => a.id === id ? { ...a, enabled: !a.enabled } : a)
    commitAddons(next)
  }, [addons, commitAddons])

  const handleDelete = useCallback((id: string) => {
    const next = addons.filter((a) => a.id !== id)
    commitAddons(next)
  }, [addons, commitAddons])

  const handleLabelChange = useCallback((id: string, label: string) => {
    const next = addons.map((a) => a.id === id ? { ...a, label } : a)
    commitAddons(next)
  }, [addons, commitAddons])

  const handleContentChange = useCallback((id: string, content: string) => {
    const next = addons.map((a) => a.id === id ? { ...a, content } : a)
    commitAddons(next)
  }, [addons, commitAddons])

  const handleOutletNameChange = useCallback((id: string, outlet_name: string) => {
    const next = addons.map((a) => a.id === id ? { ...a, outlet_name } : a)
    commitAddons(next)
  }, [addons, commitAddons])

  // Drag-to-reorder for persona-specific addons. `sort_order` is also re-stamped
  // so the backend MacroEnv resolves them in the visual order.
  const sensors = useSensors(
    useSensor(MouseSensor, { activationConstraint: { distance: 4 } }),
    useSensor(TouchSensor, { activationConstraint: { delay: 150, tolerance: 5 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates }),
  )

  const handleDragEnd = useCallback((event: DragEndEvent) => {
    const { active, over } = event
    if (!over || active.id === over.id) return
    const oldIndex = addons.findIndex((a) => a.id === active.id)
    const newIndex = addons.findIndex((a) => a.id === over.id)
    if (oldIndex < 0 || newIndex < 0) return
    const moved = arrayMove(addons, oldIndex, newIndex)
    const next = moved.map((a, i) => ({ ...a, sort_order: i }))
    commitAddons(next)
  }, [addons, commitAddons])

  // Global addon handlers
  const handleAttachGlobal = useCallback((globalAddonId: string) => {
    const next = [...attachedRefs, { id: globalAddonId, enabled: true }]
    commitAttachedRefs(next)
    setShowAttachPicker(false)
  }, [attachedRefs, commitAttachedRefs])

  const handleDetachGlobal = useCallback((globalAddonId: string) => {
    const next = attachedRefs.filter((a) => a.id !== globalAddonId)
    commitAttachedRefs(next)
  }, [attachedRefs, commitAttachedRefs])

  const handleToggleGlobal = useCallback((globalAddonId: string) => {
    const next = attachedRefs.map((a) => a.id === globalAddonId ? { ...a, enabled: !a.enabled } : a)
    commitAttachedRefs(next)
  }, [attachedRefs, commitAttachedRefs])

  // Resolved global addons (attached refs joined with full data)
  const attachedGlobalAddons = attachedRefs
    .map((ref) => {
      const addon = allGlobalAddons.find((g) => g.id === ref.id)
      return addon ? { ...addon, ...ref } : null
    })
    .filter(Boolean) as (GlobalAddon & { enabled: boolean })[]

  // Unattached global addons for the picker
  const attachedIds = new Set(attachedRefs.map((a) => a.id))
  const unattachedGlobalAddons = allGlobalAddons.filter((g) => !attachedIds.has(g.id))

  if (!personaId) return null

  return (
    <ModalShell isOpen={true} onClose={closeModal} maxWidth={580} className={styles.modal}>
      {/* Header */}
      <div className={styles.header}>
        <div className={styles.headerLeft}>
          <IconPlaylistAdd size={16} className={styles.headerIcon} />
          <span className={styles.title}>
            {personaName ? t('titleWithPersona', { name: personaName }) : t('title')}
          </span>
        </div>
        <CloseButton onClick={closeModal} size="sm" />
      </div>

      {/* Body */}
      <div className={styles.body}>
        {loading && <div className={styles.empty}>{t('loading')}</div>}

        {!loading && (
          <>
            {/* ── Section 1: Persona-Specific Add-Ons ── */}
            <div className={styles.sectionHeader}>
              <IconPlaylistAdd size={13} className={styles.sectionIconPersona} />
              <span>{t('personaSectionDefault')}</span>
            </div>
            <div className={styles.sectionHint}>
              {t('personaSectionHint')}
            </div>

            {addons.length === 0 && (
              <div className={styles.emptySection}>
                {t('personaEmpty')}
              </div>
            )}

            <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
              <SortableContext items={addons.map((a) => a.id)} strategy={verticalListSortingStrategy}>
                {addons.map((addon) => (
                  <SortableAddonRow
                    key={addon.id}
                    addon={addon}
                    onToggle={handleToggle}
                    onDelete={handleDelete}
                    onLabelChange={handleLabelChange}
                    onContentChange={handleContentChange}
                    onOutletNameChange={handleOutletNameChange}
                    onUploadAvatar={handleUploadAddonAvatar}
                    onRemoveAvatar={handleRemoveAddonAvatar}
                    avatarBusy={avatarOperationAddonId === addon.id}
                  />
                ))}
              </SortableContext>
            </DndContext>

            <div className={styles.sectionAddRow}>
              <Button variant="ghost" icon={<Plus size={13} />} onClick={handleAdd} className={styles.sectionAddBtn}>
                {t('addPersonaAddon')}
              </Button>
            </div>

            {/* ── Divider ── */}
            <div className={styles.sectionDivider} />

            {/* ── Section 2: Global Add-Ons ── */}
            <div className={styles.sectionHeader}>
              <Globe size={13} className={styles.sectionIconGlobal} />
              <span>{t('globalSection')}</span>
              <button
                type="button"
                className={styles.manageLibraryBtn}
                onClick={() => openModal('globalAddonsLibrary')}
              >
                {t('manageLibrary')}
              </button>
            </div>

            {attachedGlobalAddons.length === 0 && (
              <div className={styles.emptySection}>
                {t('globalEmpty')}
              </div>
            )}

            {attachedGlobalAddons.map((addon) => (
              <div key={addon.id} className={clsx(styles.addonCard, styles.addonCardGlobal, !addon.enabled && styles.addonCardDisabled)}>
                <div className={styles.addonTopRow}>
                  <button
                    type="button"
                    className={clsx(styles.addonToggle, addon.enabled && styles.addonToggleActiveGlobal)}
                    onClick={() => handleToggleGlobal(addon.id)}
                    title={addon.enabled ? t('disableAddon') : t('enableAddon')}
                  >
                    <Check size={13} />
                  </button>
                  <div className={styles.globalIndicator}>
                    <Globe size={10} />
                  </div>
                  <span className={styles.globalAddonLabel}>{addon.label || t('untitledGlobal')}</span>
                  <AddonAvatarControl
                    addon={addon}
                    onUpload={handleUploadAddonAvatar}
                    onRemove={handleRemoveAddonAvatar}
                    busy={avatarOperationAddonId === addon.id}
                  />
                  <button
                    type="button"
                    className={styles.detachBtn}
                    onClick={() => handleDetachGlobal(addon.id)}
                    title={t('detachTitle')}
                  >
                    <Unlink size={13} />
                  </button>
                </div>
                {addon.content && (
                  <div className={styles.globalAddonPreview}>
                    {addon.content.length > 200 ? addon.content.slice(0, 200) + '...' : addon.content}
                  </div>
                )}
              </div>
            ))}

            {/* Attach picker */}
            <div className={styles.sectionAddRow}>
              <div className={styles.attachWrapper}>
                <Button
                  variant="ghost"
                  icon={<Link2 size={13} />}
                  onClick={() => setShowAttachPicker((p) => !p)}
                  className={styles.sectionAddBtn}
                  disabled={unattachedGlobalAddons.length === 0}
                >
                  {t('attachGlobalAddon')}
                </Button>
                {showAttachPicker && unattachedGlobalAddons.length > 0 && (
                  <div className={styles.attachPopover}>
                    {unattachedGlobalAddons.map((g) => (
                      <button
                        key={g.id}
                        type="button"
                        className={styles.attachPopoverItem}
                        onClick={() => handleAttachGlobal(g.id)}
                      >
                        <Globe size={11} className={styles.attachPopoverIcon} />
                        <span>{g.label || t('untitled')}</span>
                      </button>
                    ))}
                  </div>
                )}
              </div>
            </div>
          </>
        )}
      </div>

      {/* Footer */}
      <div className={styles.footer}>
        <span className={styles.addonCount}>
          {addons.length} persona{addons.length !== 1 ? '' : ''} / {attachedGlobalAddons.length} global
          {' '}&middot;{' '}
          {addons.filter((a) => a.enabled).length + attachedGlobalAddons.filter((a) => a.enabled).length} active
        </span>
      </div>
    </ModalShell>
  )
}

interface SortableAddonRowProps {
  addon: PersonaAddon
  onToggle: (id: string) => void
  onDelete: (id: string) => void
  onLabelChange: (id: string, label: string) => void
  onContentChange: (id: string, content: string) => void
  onOutletNameChange: (id: string, outletName: string) => void
  onUploadAvatar: (id: string, file: File) => Promise<void>
  onRemoveAvatar: (id: string) => Promise<void>
  avatarBusy: boolean
}

function SortableAddonRow({
  addon,
  onToggle,
  onDelete,
  onLabelChange,
  onContentChange,
  onOutletNameChange,
  onUploadAvatar,
  onRemoveAvatar,
  avatarBusy,
}: SortableAddonRowProps) {
  const { t } = useTranslation('modals', { keyPrefix: 'personaAddons' })

  const { attributes, listeners, setNodeRef: setSortableRef, transform, transition, isDragging } = useSortable({ id: addon.id })
  const { setNodeRef, style: scaledStyle } = useScaledSortableStyle({ setNodeRef: setSortableRef, transform, transition, isDragging })
  const style = {
    ...scaledStyle,
    opacity: isDragging ? 0.6 : undefined,
    zIndex: isDragging ? 1 : undefined,
  }

  return (
    <div
      ref={setNodeRef}
      style={style}
      className={clsx(styles.addonCard, !addon.enabled && styles.addonCardDisabled)}
    >
      <div className={styles.addonTopRow}>
        <button
          type="button"
          className={styles.addonDragHandle}
          title={t('dragTitle')}
          aria-label={t('dragAria')}
          tabIndex={-1}
          onContextMenu={(e) => e.preventDefault()}
          {...attributes}
          {...listeners}
        >
          <GripVertical size={13} />
        </button>
        <button
          type="button"
          className={clsx(styles.addonToggle, addon.enabled && styles.addonToggleActive)}
          onClick={() => onToggle(addon.id)}
          title={addon.enabled ? t('disableAddon') : t('enableAddon')}
        >
          <Check size={13} />
        </button>
        <input
          type="text"
          className={styles.addonLabelInput}
          value={addon.label}
          onChange={(e) => onLabelChange(addon.id, e.target.value)}
          placeholder={t('namePlaceholder')}
        />
        <AddonAvatarControl
          addon={addon}
          onUpload={onUploadAvatar}
          onRemove={onRemoveAvatar}
          busy={avatarBusy}
        />
        <button
          type="button"
          className={styles.addonDeleteBtn}
          onClick={() => onDelete(addon.id)}
          title={t('deleteTitle')}
        >
          <Trash2 size={13} />
        </button>
      </div>
      <ExpandableTextarea
        className={styles.addonContent}
        value={addon.content}
        onChange={(v) => onContentChange(addon.id, v)}
        title={addon.label || t('addonContent')}
        placeholder={t('contentPlaceholder')}
        rows={2}
      />
      <div className={styles.outletRow}>
        <label className={styles.outletLabel} htmlFor={`persona-addon-outlet-${addon.id}`}>
          {t('outletLabel')}
        </label>
        <input
          id={`persona-addon-outlet-${addon.id}`}
          type="text"
          className={styles.outletInput}
          value={addon.outlet_name ?? ''}
          onChange={(e) => onOutletNameChange(addon.id, e.target.value)}
          placeholder={t('outletPlaceholder')}
          autoCapitalize="none"
          spellCheck={false}
        />
      </div>
      {addon.outlet_name?.trim() && (
        <div className={styles.outletHint}>
          {t('outletHint', { macro: `{{persona_outlet::${addon.outlet_name.trim()}}}` })}
        </div>
      )}
    </div>
  )
}

type AddonAvatar = Pick<PersonaAddon, 'id' | 'avatar_image_id' | 'avatar_crop_image_id'>

function AddonAvatarControl({
  addon,
  onUpload,
  onRemove,
  busy,
}: {
  addon: AddonAvatar
  onUpload: (id: string, file: File) => Promise<void>
  onRemove: (id: string) => Promise<void>
  busy: boolean
}) {
  const { t } = useTranslation('modals', { keyPrefix: 'personaAddons' })
  const inputRef = useRef<HTMLInputElement>(null)
  const imageId = addon.avatar_crop_image_id || addon.avatar_image_id

  return (
    <span className={styles.addonAvatarControls}>
      {imageId && <img className={styles.addonAvatarThumb} src={imagesApi.smallUrl(imageId)} alt="" />}
      <input
        ref={inputRef}
        type="file"
        accept="image/*"
        className={styles.avatarFileInput}
        onChange={(event) => {
          const file = event.target.files?.[0]
          event.currentTarget.value = ''
          if (file) void onUpload(addon.id, file)
        }}
      />
      <button
        type="button"
        className={styles.addonAvatarBtn}
        onClick={() => inputRef.current?.click()}
        disabled={busy}
        title={imageId ? t('replaceAvatar') : t('setAvatar')}
      >
        <ImagePlus size={13} />
      </button>
      {imageId && (
        <button
          type="button"
          className={clsx(styles.addonAvatarBtn, styles.addonAvatarRemoveBtn)}
          onClick={() => void onRemove(addon.id)}
          disabled={busy}
          title={t('removeAvatar')}
        >
          <ImageOff size={13} />
        </button>
      )}
    </span>
  )
}

sources.src/components/modals/PromptItemizerModa:
.modal {
  --prompt-itemizer-modal-max-height: min(760px, calc(88vh / var(--lumiverse-ui-scale, 1)));

  max-height: var(--prompt-itemizer-modal-max-height);
}

.header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 18px;
  border-bottom: 1px solid var(--lumiverse-border);
  flex-shrink: 0;
}

.title {
  font-size: calc(14px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
  margin: 0;
  flex: 1;
}

.headerBadge {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: 4px;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text-muted);
}

.body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  padding: 16px 18px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.body > * {
  flex-shrink: 0;
}

/* Stacked bar */
.stackedBar {
  display: flex;
  height: 20px;
  border-radius: 4px;
  overflow: hidden;
  background: var(--lumiverse-fill-subtle);
}

.stackedBarSegment {
  height: 100%;
  min-width: 2px;
  transition: opacity var(--lumiverse-transition-fast);
}

.stackedBarSegment:hover {
  opacity: 0.8;
}

/* Legend */
.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.legendItem {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
}

.legendDot {
  width: 8px;
  height: 8px;
  border-radius: 2px;
  flex-shrink: 0;
}

.legendTokens {
  font-variant-numeric: tabular-nums;
  color: var(--lumiverse-text);
  font-weight: 500;
}

.cacheSummary {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
}

.cacheSummaryMetric {
  display: inline-flex;
  align-items: center;
  padding: 2px 6px;
  border-radius: 999px;
  background: rgba(217, 119, 87, 0.08);
  color: rgba(217, 119, 87, 0.92);
}

/* Accordion */
.accordion {
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  overflow: auto;
}

.accordionHeader {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  background: var(--lumiverse-fill-subtle);
  border: none;
  width: 100%;
  text-align: left;
  cursor: pointer;
  color: var(--lumiverse-text);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  transition: background var(--lumiverse-transition-fast);
}

.accordionHeader:hover {
  background: var(--lumiverse-border);
}

.accordionDot {
  width: 6px;
  height: 6px;
  border-radius: 2px;
  flex-shrink: 0;
}

.accordionTokens {
  margin-left: auto;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-variant-numeric: tabular-nums;
  color: var(--lumiverse-text-muted);
}

.accordionChevron {
  color: var(--lumiverse-text-dim);
  transition: transform var(--lumiverse-transition-fast);
}

.accordionChevronOpen {
  transform: rotate(90deg);
}

.accordionBody {
  border-top: 1px solid var(--lumiverse-border);
  max-height: 400px;
  overflow-y: auto;
}

/* Entry list */
.entryList {
  display: flex;
  flex-direction: column;
}

.entryRow {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 12px;
  border: none;
  border-bottom: 1px solid var(--lumiverse-border);
  background: transparent;
  cursor: pointer;
  text-align: left;
  color: var(--lumiverse-text);
}

.entryRow:last-child {
  border-bottom: none;
}

.entryRow:hover {
  background: var(--lumiverse-fill-subtle);
}

.entryRowActive {
  background: var(--lumiverse-primary-010);
}

.entryMetrics {
  display: flex;
  align-items: baseline;
  gap: 10px;
  flex-shrink: 0;
}

.tokenName {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  flex-wrap: wrap;
}

.tokenColor {
  width: 6px;
  height: 6px;
  border-radius: 2px;
  flex-shrink: 0;
}

.tokenRole {
  display: inline-flex;
  padding: 0 4px;
  border-radius: 3px;
  font-size: calc(9px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
}

.roleSystem { background: rgba(96, 165, 250, 0.15); color: rgb(96, 165, 250); }
.roleUser { background: var(--lumiverse-success-015); color: var(--lumiverse-success); }
.roleAssistant { background: rgba(251, 191, 36, 0.15); color: rgb(251, 191, 36); }

.tokenCount {
  text-align: right;
  font-variant-numeric: tabular-nums;
  font-weight: 500;
  white-space: nowrap;
}

.cacheHint {
  display: inline-flex;
  align-items: center;
  padding: 1px 6px;
  border-radius: 999px;
  font-size: calc(9px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
}

.cacheHintCached {
  background: rgba(217, 119, 87, 0.12);
  color: rgba(217, 119, 87, 0.92);
}

.cacheHintMiss {
  background: rgba(255, 255, 255, 0.04);
  color: var(--lumiverse-text-dim);
}

.tokenPct {
  text-align: right;
  font-variant-numeric: tabular-nums;
  color: var(--lumiverse-text-dim);
  width: 50px;
}

/* Footer */
.footer {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 18px;
  border-top: 1px solid var(--lumiverse-border);
  flex-shrink: 0;
}

.footerTotal {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
  font-variant-numeric: tabular-nums;
}

.footerMax {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
}

.footerSpacer {
  flex: 1;
}

/* .footerBtn — migrated to shared Button component */

/* Sidecar divider */
.sidecarDivider {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #e05daa;
  border-top: 1px solid var(--lumiverse-border);
  margin-top: 4px;
}

/* Raw view caveat banner */
.rawCaveat {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  line-height: 1.5;
  color: var(--lumiverse-text-muted);
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
  border-radius: 6px;
  padding: 8px 10px;
  margin-bottom: 8px;
}

.entryInspector {
  display: flex;
  flex-direction: column;
  min-height: 220px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  background: var(--lumiverse-fill-subtle);
  overflow: hidden;
}

.entryInspectorHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 12px;
  border-bottom: 1px solid var(--lumiverse-border);
}

.entryInspectorTitleWrap {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}

.entryInspectorEyebrow {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
