  color: var(--lumiverse-text-muted);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  line-height: 1.5;
}

.messageInspectorList {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 12px;
  overflow: auto;
}

.messageInspectorNotice {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  line-height: 1.5;
  color: var(--lumiverse-text-muted);
  background: var(--lumiverse-fill);
  border: 1px solid var(--lumiverse-border);
  border-radius: 6px;
  padding: 8px 10px;
}

.messageCard {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 12px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.08);
}

.messageCardHeader {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.messageCardIndex {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
}

.messageCardMeta {
  margin-left: auto;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  white-space: nowrap;
}

.messageCardPreview {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  line-height: 1.45;
  color: var(--lumiverse-text-muted);
}

.messageCardContent {
  margin: 0;
  font-family: 'JetBrains Mono', 'Fira Code', monospace;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  line-height: 1.55;
  color: var(--lumiverse-text-muted);
  white-space: pre-wrap;
  word-break: break-word;
}

/* Raw view */
.rawView {
  font-family: 'SF Mono', 'Fira Code', monospace;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  line-height: 1.5;
  color: var(--lumiverse-text-muted);
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
  border-radius: 6px;
  padding: 12px;
  white-space: pre-wrap;
  word-break: break-word;
  max-height: 400px;
  overflow-y: auto;
}

/* Loading state */
.loading {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px;
  color: var(--lumiverse-text-muted);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
}

.empty {
  composes: loading;
  font-style: italic;
}

@media (max-width: 600px) {
  .modal {
    --prompt-itemizer-modal-max-height: calc(
      var(--app-scaled-viewport-height, 100dvh)
      - max(
        40px,
        calc((env(safe-area-inset-top, 0px) * 2) + 24px),
        calc((env(safe-area-inset-bottom, 0px) * 2) + 24px)
      )
    );
  }

  .entryRow,
  .entryInspectorHeader {
    align-items: flex-start;
    flex-direction: column;
  }

