    gap: 8px;
  }
}

/* Find-in-prompt bar and inspector match highlighting */
.findBar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 10px;
  margin-bottom: 12px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
