.modal {
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5),
    0 0 40px var(--lumiverse-primary-020);
}

/* ── Header ── */
.header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 20px 24px 14px;
  border-bottom: 1px solid var(--lumiverse-border);
  flex-shrink: 0;
}

.title {
  margin: 0;
  font-size: calc(15px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  color: var(--lumiverse-text);
  letter-spacing: -0.01em;
}

.subtitle {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  margin: 0;
  padding: 0 24px;
  padding-top: 12px;
  line-height: 1.5;
}

/* ── Body ── */
.body {
  padding: 12px 24px 20px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.textarea {
  width: 100%;
  min-height: 100px;
  max-height: 200px;
  padding: 12px 14px;
  border-radius: var(--lcs-radius-sm, 8px);
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-bg-dark);
  color: var(--lumiverse-text);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  line-height: 1.5;
  resize: vertical;
  font-family: inherit;
  transition: border-color var(--lumiverse-transition-fast);
}

.textarea::placeholder {
  color: var(--lumiverse-text-dim);
}

.textarea:focus {
  outline: none;
  border-color: var(--lumiverse-primary-050, rgba(147, 112, 219, 0.5));
}

/* ── Actions ── */
.actions {
  display: flex;
  align-items: center;
  gap: 8px;
  justify-content: flex-end;
}

.btn {
  padding: 8px 18px;
  border-radius: var(--lcs-radius-sm, 8px);
  font-size: calc(12.5px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  cursor: pointer;
  border: 1px solid var(--lumiverse-border);
  transition: all var(--lumiverse-transition-fast);
}

.btnCancel {
  background: transparent;
  color: var(--lumiverse-text-muted);
}

.btnCancel:hover {
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.04));
  color: var(--lumiverse-text);
}

.btnSkip {
  background: var(--lumiverse-bg-dark);
  color: var(--lumiverse-text-dim);
}

.btnSkip:hover {
  background: var(--lumiverse-bg-darker);
  color: var(--lumiverse-text);
}

.btnSubmit {
  background: var(--lumiverse-primary-015, rgba(147, 112, 219, 0.15));
  color: var(--lumiverse-primary-text, #c4b5fd);
  border-color: var(--lumiverse-primary-020, rgba(147, 112, 219, 0.2));
}

.btnSubmit:hover {
  background: var(--lumiverse-primary-025, rgba(147, 112, 219, 0.25));
  border-color: var(--lumiverse-primary-050, rgba(147, 112, 219, 0.5));
}

.btnSubmit:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* ── Mobile ── */
@media (max-width: 480px) {
  .modal {
    border-radius: 14px 14px 0 0;
  }

  .header {
    padding: 16px 18px 12px;
  }

  .subtitle {
    padding: 10px 18px 0;
  }

  .body {
    padding: 10px 18px 18px;
  }

  .textarea {
    min-height: 80px;
  }

  .actions {
    flex-direction: column-reverse;
  }

  .actions .btn {
    width: 100%;
    text-align: center;
  }
}

import { MessageSquareText } from 'lucide-react'
import { useTranslation } from 'react-i18next'
import { InputPromptModal } from '@/components/shared/InputPromptModal'
import { Toggle } from '@/components/shared/Toggle'
import { useStore } from '@/store'

interface RegenFeedbackModalProps {
  onSubmit: (feedback: string) => void
  onSaveDraft: (feedback: string) => void
  onSkip: () => void
  onCancel: () => void
  defaultValue?: string
}

const PREVIOUS_GENERATION_TAG =
  '[REJECTED MESSAGE: The last message was rejected due to quality issues. The feedback regarding the quality of this message will follow it. Previous message for reference: {{regeneratedMessage}}]'

export default function RegenFeedbackModal({
  onSubmit,
  onSaveDraft,
  onSkip,
  onCancel,
  defaultValue,
}: RegenFeedbackModalProps) {
  const { t } = useTranslation('modals')
  const regenFeedback = useStore((s) => s.regenFeedback)
  const setSetting = useStore((s) => s.setSetting)

  const setIncludePreviousGeneration = (checked: boolean) => {
    setSetting('regenFeedback', { ...regenFeedback, includePreviousGeneration: checked })
  }

  const handleSubmit = (feedback: string) => {
    onSaveDraft(feedback)
    if (regenFeedback.includePreviousGeneration) {
      onSubmit(`${PREVIOUS_GENERATION_TAG}\n\n${feedback}`)
    } else {
      onSubmit(feedback)
    }
  }

  const handleSkip = () => {
    onSaveDraft('')
    onSkip()
  }

  return (
    <InputPromptModal
      isOpen={true}
      title={t('regenFeedback.title')}
      message={t('regenFeedback.message')}
      placeholder={t('regenFeedback.placeholder')}
      defaultValue={defaultValue}
      multiline
      submitLabel={t('regenFeedback.submit')}
      secondaryLabel={t('regenFeedback.skip')}
      onSubmit={handleSubmit}
      onSecondary={handleSkip}
      onCancel={onCancel}
      icon={<MessageSquareText size={16} />}
      footer={
        <Toggle.Checkbox
          checked={regenFeedback.includePreviousGeneration}
          onChange={setIncludePreviousGeneration}
          label={t('regenFeedback.usePreviousGeneration')}
        />
      }
    />
  )
}

