}

.actionType {
  display: flex;
  min-width: 270px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 7px;
  overflow: hidden;
}

.actionTitleRow > .field {
  flex: 1;
}

/* ── Targeting: 2-column grid ────────────────── */

.targetCols {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
