  min-width: 0;
}

.inlineToggle {
  white-space: nowrap;
  padding-bottom: 6px;
}

/* ── Preset Cards ────────────────────────────── */

.presetGrid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: 5px;
}

.presetCard {
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding: 6px 9px;
  border-radius: 6px;
  border: 1px solid var(--lumiverse-border);
  background: transparent;
  cursor: pointer;
  text-align: left;
  transition: all var(--lumiverse-transition-fast);
