.presetCard:hover {
  border-color: var(--lumiverse-primary);
  background: var(--lumiverse-primary-010);
}

.presetName {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  color: var(--lumiverse-text);
}

.presetDesc {
  font-size: calc(9px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  opacity: 0.7;
}

/* ── Live Test ───────────────────────────────── */

.testSection {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.testInput {
  width: 100%;
  min-width: 0;
  padding: 7px 10px;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-family: var(--lumiverse-mono, monospace);
  border-radius: 7px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text);
  outline: none;
  resize: vertical;
  min-height: 44px;
}

.testInput:focus {
  border-color: var(--lumiverse-primary);
}

.testResultArea {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.testOutput {
  padding: 8px 10px;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-family: var(--lumiverse-mono, monospace);
  border-radius: 7px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-surface);
  color: var(--lumiverse-text);
  min-height: 36px;
  white-space: pre-wrap;
  word-break: break-word;
}

.testMeta {
  display: flex;
  gap: 8px;
  align-items: center;
}

.matchBadge {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  padding: 1px 7px;
  border-radius: 4px;
  background: var(--lumiverse-primary);
  color: var(--lumiverse-primary-fg, #fff);
}

.testError {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-danger, #ef4444);
}

.testHint {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  opacity: 0.6;
  text-align: center;
  padding: 6px;
}

/* ── Footer ──────────────────────────────────── */

.footer {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  padding: 10px 18px;
  border-top: 1px solid var(--lumiverse-border);
  flex-shrink: 0;
}

@media (max-width: 600px) {
  .modal {
    max-height: calc(var(--app-scaled-viewport-height, 100dvh) - 24px);
  }

  .header {
    padding: 12px 14px;
  }

  .body {
    padding: 14px;
    gap: 14px;
  }

  .targetCols {
    grid-template-columns: minmax(0, 1fr);
  }

  .placementGrid {
    gap: 6px;
  }

  .placementChip,
  .segmentedBtn {
    padding-top: 7px;
    padding-bottom: 7px;
  }

  .identityRow,
  .advancedRow,
  .actionCardHeader,
  .actionTitleRow {
    flex-direction: column;
    align-items: stretch;
  }

  .actionType {
    min-width: 0;
  }

  .removeActionButton {
    align-self: flex-end;
  }

  .identityRow .field,
  .advancedRow .field {
    flex-basis: auto;
  }

  .findHeader {
    align-items: flex-start;
  }

  .fieldLabel {
    flex-wrap: wrap;
  }

  .tokenBar {
    overflow-x: auto;
    flex-wrap: nowrap;
    padding-bottom: 2px;
  }

  .tokenChip,
  .tokenDivider {
    flex-shrink: 0;
  }

  .footer {
    padding: 10px 14px;
  }
}

