  backdrop-filter: blur(var(--lcs-glass-soft-blur, 6px)) var(--lcs-liquid-filter, );
  border-color: var(--lcs-glass-border);
  box-shadow: var(--lumiverse-shadow-xl);
}

.dropdown::-webkit-scrollbar {
  width: 8px;
}

.dropdown::-webkit-scrollbar-thumb {
  background: var(--lcs-scrollbar-thumb, rgba(255, 255, 255, 0.12));
  border-radius: 4px;
}

.group + .group {
  margin-top: 2px;
}

.groupLabel {
  padding: 6px 10px 4px;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--lumiverse-text-dim);
}

.item {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 7px 10px;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: var(--lumiverse-text);
  text-align: left;
  cursor: pointer;
  transition: background 0.1s ease;
}

.itemActive {
  background: var(--lumiverse-primary-020);
}

.itemIcon {
  display: flex;
  align-items: center;
  flex-shrink: 0;
  color: var(--lumiverse-text-muted);
}

.itemActive .itemIcon {
  color: var(--lumiverse-primary);
}

.itemTitle {
  flex: 1;
  min-width: 0;
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
