.empty {
  padding: 22px 16px;
  text-align: center;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
}

@media (max-width: 600px) {
  .container {
    margin: 0 10px;
    max-width: none;
  }

  .dropdown {
    max-height: min(60vh, 360px);
  }
}

