.modal {
  --worldbook-footer-height: 0px;
  max-height: calc(85vh / var(--lumiverse-ui-scale, 1));
}

/*
 * Enhanced workspace overlay. ResizablePanelFrame is position:fixed / z-index 50;
 * this backdrop is the stacking context that lifts the whole editor above
 * --z-quick-toolbar-floating (10005). Stay under LoreIndicator (10010). 10012
 * is forbidden by lore-indicator tests.
 */
.backdrop {
  position: fixed;
  inset: 0;
  z-index: 10006;
  display: flex;
  align-items: center;
  justify-content: center;
  isolation: isolate;
  background: var(--lumiverse-modal-backdrop, rgba(3, 5, 9, 0.72));
}

.fullscreen {
  position: fixed;
  inset: 0;
  width: calc(100vw / var(--lumiverse-ui-scale, 1));
  height: var(--app-scaled-viewport-height, calc(100dvh / var(--lumiverse-ui-scale, 1)));
  max-height: none;
  border-radius: 0;
  z-index: 10006;
}

.modal.fullscreen {
  z-index: 10006;
  /* Start below the desktop/PWA titlebar (0px in a browser tab). Two classes so
     this outranks the floating panel's own top/height. */
  top: var(--app-window-controls-overlay-top, 0px);
  height: calc(var(--app-scaled-viewport-height, calc(100dvh / var(--lumiverse-ui-scale, 1))) - var(--app-window-controls-overlay-top, 0px));
}

.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;
  border-bottom: 1px solid var(--lumiverse-border);
  flex-shrink: 0;
}

.title {
  font-size: calc(16px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
}

.headerActions {
  display: flex;
  align-items: center;
  gap: 6px;
}

.fullscreenBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  padding: 0;
  border: 1px solid var(--lumiverse-border);
  border-radius: 6px;
  background: transparent;
  color: var(--lumiverse-text-muted);
  cursor: pointer;
}

.fullscreenBtn:hover {
  border-color: var(--lumiverse-primary);
  color: var(--lumiverse-primary);
}


/* ── Two-panel layout ── */
.body {
  display: flex;
  flex: 1;
  overflow: hidden;
  min-height: 0;
}

/* ── Left panel: book list ── */
.sidebar {
  width: 240px;
  flex-shrink: 0;
  border-right: 1px solid var(--lumiverse-border);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.sidebarHeader {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 10px 8px;
  border-bottom: 1px solid var(--lumiverse-border);
}

.sidebarSearchRow {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
}

.searchInput {
  flex: 1;
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
  border-radius: 6px;
  padding: 5px 8px;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text);
  outline: none;
  min-width: 0;
}

.searchInput:focus {
  border-color: var(--lumiverse-primary);
}

.searchClear {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  padding: 0;
  border: 1px solid var(--lumiverse-border);
  border-radius: 6px;
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text-dim);
  cursor: pointer;
}

.searchClear:hover {
  background: var(--lumiverse-fill-hover);
  color: var(--lumiverse-text);
}

.sidebarControlRow {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
}

.sidebarSelect {
  min-width: 0;
  flex: 1;
  padding: 5px 7px;
  border-radius: 6px;
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
}

.sidebarSelect:focus {
  outline: none;
  border-color: var(--lumiverse-primary);
}

.sidebarPageSizeSelect {
  flex: 0 0 calc(54px * var(--lumiverse-font-scale, 1));
}

.sidebarIconBtn {
  width: calc(28px * var(--lumiverse-font-scale, 1));
  height: calc(28px * var(--lumiverse-font-scale, 1));
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 1px;
  border-radius: 6px;
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text-muted);
  cursor: pointer;
  flex-shrink: 0;
  transition: all var(--lumiverse-transition-fast);
}

.sidebarIconBtn:hover,
.sidebarIconBtnActive {
  border-color: var(--lumiverse-primary);
  color: var(--lumiverse-primary);
  background: var(--lumiverse-primary-light);
}

.newBookBtn {
  width: var(--lumiverse-btn-icon);
  height: var(--lumiverse-btn-icon);
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  background: var(--lumiverse-primary);
  border: none;
  color: var(--lumiverse-primary-contrast, #fff);
  cursor: pointer;
  flex-shrink: 0;
  transition: opacity var(--lumiverse-transition-fast);
}

.newBookBtn:hover {
  opacity: 0.85;
}

.bookList {
  flex: 1;
  overflow-y: auto;
  padding: 6px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.bookItem {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 7px 8px;
  border-radius: 8px;
  background: transparent;
  border: none;
  color: var(--lumiverse-text-muted);
  font-size: calc(12.5px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
  text-align: left;
  width: 100%;
  transition: all var(--lumiverse-transition-fast);
}

.bookItem:hover {
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text);
}

.bookItemActive {
  background: var(--lumiverse-primary-light);
  color: var(--lumiverse-primary);
}

.bookItemSelected {
  background: var(--lumiverse-primary-light);
  color: var(--lumiverse-primary);
}

.bookName {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bookCheckbox {
  width: calc(14px * var(--lumiverse-font-scale, 1));
  height: calc(14px * var(--lumiverse-font-scale, 1));
  accent-color: var(--lumiverse-primary);
  flex-shrink: 0;
}

.bookActions {
  display: flex;
  align-items: center;
  gap: 2px;
  flex-shrink: 0;
}

.bookExportBtn,
.bookDeleteBtn {
  width: 20px;
  height: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 4px;
  background: transparent;
  border: none;
  color: var(--lumiverse-text-dim);
  cursor: pointer;
  opacity: 0;
  flex-shrink: 0;
  transition: all var(--lumiverse-transition-fast);
}

.bookItem:hover .bookExportBtn,
.bookItem:hover .bookDeleteBtn,
.bookExportBtn:focus-visible,
.bookDeleteBtn:focus-visible {
  opacity: 1;
}

.bookExportBtn:hover {
  color: var(--lumiverse-primary);
}

.bookDeleteBtn:hover {
  color: var(--lumiverse-error);
}

.bookPagination {
  flex-shrink: 0;
  padding: 6px;
  border-top: 1px solid var(--lumiverse-border);
}

.bulkBar {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 8px 10px;
  border-bottom: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-fill-subtle);
}

.bulkSelectionRow {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.bulkToggle {
  width: calc(26px * var(--lumiverse-font-scale, 1));
  height: calc(26px * var(--lumiverse-font-scale, 1));
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  background: var(--lumiverse-surface);
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text-muted);
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
}

.bulkToggle:hover:not(:disabled) {
  border-color: var(--lumiverse-primary);
  color: var(--lumiverse-primary);
}

.bulkToggle:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.bulkCount {
  flex: 1;
  min-width: 0;
  color: var(--lumiverse-text-muted);
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  text-align: right;
}

.bulkActions {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.bulkActionBtn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 5px 8px;
  border-radius: 6px;
  background: var(--lumiverse-surface);
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
}

.bulkActionBtn:hover:not(:disabled) {
  border-color: var(--lumiverse-primary);
  color: var(--lumiverse-primary);
}

.bulkActionBtn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.bulkDeleteBtn:hover:not(:disabled) {
  border-color: var(--lumiverse-error);
  color: var(--lumiverse-error);
}

.bulkFolderDropdown {
  flex: 1 1 100%;
  min-width: 0;
}

.bulkFolderDropdown > button {
  min-height: calc(30px * var(--lumiverse-font-scale, 1));
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
}

.sourceBadge {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  border-radius: 4px;
  background: color-mix(in srgb, var(--lumiverse-primary) 12%, transparent);
  color: var(--lumiverse-primary);
  flex-shrink: 0;
  pointer-events: auto;
}

.sourceBadge::after {
  content: attr(data-tooltip);
  position: absolute;
  right: 0;
  bottom: calc(100% + 6px);
  max-width: 200px;
  padding: 5px 9px;
  border-radius: 6px;
  background: var(--lumiverse-gradient-modal, linear-gradient(135deg, rgba(35, 30, 48, 0.98), rgba(20, 17, 28, 0.98)));
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  white-space: nowrap;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.3);
  z-index: 200;
  opacity: 0;
  pointer-events: none;
  transform: translateY(4px);
  transition: opacity 0.15s ease, transform 0.15s ease;
}

.sourceBadge:hover::after {
  opacity: 1;
  transform: translateY(0);
  transition-delay: 0.3s;
}

/* ── Right panel: book content ── */
.content {
  flex: 1;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.contentScroll {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 16px 20px 0;
  overscroll-behavior-y: contain;
  -webkit-overflow-scrolling: touch;
  scroll-padding-block: 16px calc(16px + max(var(--worldbook-footer-height, 0px), var(--app-keyboard-inset-bottom, 0px)));
}

.contentFooter {
  flex-shrink: 0;
  background: var(--lumiverse-bg-deep);
  border-top: 1px solid color-mix(in srgb, var(--lumiverse-border) 55%, transparent);
  padding: 8px 20px calc(16px + var(--worldbook-footer-safe-bottom, env(safe-area-inset-bottom, 0px)));
  overflow-x: auto;
  overscroll-behavior-x: contain;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}

.contentFooter::-webkit-scrollbar {
  display: none;
}

.contentFooter:empty {
  display: none;
}

/* Match the docked panel behavior so the footer stays behind the on-screen
   keyboard instead of sliding upward with the focused field. */
:global(html[data-resizes-content]) .contentFooter,
:global(html[data-ios-pwa]) .contentFooter {
  margin-bottom: calc(-1 * var(--app-keyboard-inset-bottom, 0px));
}

.emptyState {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--lumiverse-text-dim);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  font-style: italic;
}

/* ── Book header fields ── */
.bookFields {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--lumiverse-border);
}

.fieldRow {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.fieldLabel {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  color: var(--lumiverse-text-muted);
}

.fieldInput {
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
  border-radius: 6px;
  padding: 6px 10px;
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text);
  outline: none;
  transition: border-color var(--lumiverse-transition-fast);
}

.fieldInput:focus {
  border-color: var(--lumiverse-primary);
}

/* Avoid iOS browser zoom when editing a lorebook in the pop-out modal. */
@media (pointer: coarse) {
  .fieldInput {
    font-size: max(16px, calc(13px * var(--lumiverse-font-scale, 1)));
  }
}

/* ── Entry list ── */
.entryListHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.entryListTitle {
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
}

.entrySortRow {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 8px;
}

.entrySortSelect {
  flex: 1;
  min-width: 0;
  padding: 6px 8px;
  border-radius: 6px;
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text);
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
}

.entrySortSelect:focus {
  outline: none;
  border-color: var(--lumiverse-primary);
}

.entrySortDirBtn {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 6px 8px;
  border-radius: 6px;
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text);
  cursor: pointer;
  flex-shrink: 0;
  transition: all var(--lumiverse-transition-fast);
}

.entrySortDirBtn:hover {
  border-color: var(--lumiverse-primary-050);
  color: var(--lumiverse-primary);
}

.entrySearch {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 8px;
  padding: 7px 10px;
  border-radius: 8px;
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
}

.entrySearch:focus-within {
  border-color: var(--lumiverse-primary);
}

.entrySearchIcon {
  color: var(--lumiverse-text-dim);
  flex-shrink: 0;
}

.entrySearchInput {
  flex: 1;
  min-width: 0;
  background: transparent;
  border: none;
  color: var(--lumiverse-text);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  outline: none;
}

.entrySearchInput::placeholder {
  color: var(--lumiverse-text-dim);
}

.newEntryBtn {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 4px 10px;
  border-radius: 6px;
  background: var(--lumiverse-primary);
  border: none;
  color: var(--lumiverse-primary-contrast, #fff);
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
  transition: opacity var(--lumiverse-transition-fast);
}

.newEntryBtn:hover {
  opacity: 0.85;
}

.secondaryBtn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 6px 12px;
  border-radius: 6px;
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text);
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
  transition: border-color var(--lumiverse-transition-fast), background var(--lumiverse-transition-fast), opacity var(--lumiverse-transition-fast);
}

.secondaryBtn:hover {
  border-color: var(--lumiverse-primary);
  background: var(--lumiverse-primary-light);
}

.primaryActionBtn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 6px 12px;
  border-radius: 8px;
  border: 1px solid transparent;
  background: var(--lumiverse-primary);
  color: var(--lumiverse-primary-contrast, #fff);
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
  transition: opacity var(--lumiverse-transition-fast);
}

.primaryActionBtn:hover {
  opacity: 0.9;
}

.primaryActionBtn:disabled,
.secondaryBtn:disabled,
.newEntryBtn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.bulkDialogBody {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 20px;
}

.bulkDialogTitle {
  margin: 0;
  color: var(--lumiverse-text);
  font-size: calc(16px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
}

.bulkDialogText {
  margin: 0;
  color: var(--lumiverse-text-muted);
  font-size: calc(12.5px * var(--lumiverse-font-scale, 1));
  line-height: 1.5;
}

.exportFormatOptions {
  display: grid;
  grid-template-columns: 1fr;
  gap: 8px;
}

.exportFormatOption {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 9px 10px;
  border-radius: 8px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
}

.exportFormatOption:hover,
.exportFormatOptionActive {
  border-color: var(--lumiverse-primary);
  background: var(--lumiverse-primary-light);
}

.exportFormatOption input {
  accent-color: var(--lumiverse-primary);
}

.bulkDialogActions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}

.vectorSummary {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 12px;
  border-radius: 10px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-fill-subtle);
}

.vectorSummaryTitle {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.vectorSummaryGrid {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 12px;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text);
}

.vectorSummaryGrid span {
  padding: 4px 8px;
  border-radius: 999px;
  background: var(--lumiverse-bg);
  border: 1px solid var(--lumiverse-border);
}

.bulkSemanticToggle {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 10px;
  border-radius: 8px;
  background: var(--lumiverse-bg);
  border: 1px solid var(--lumiverse-border);
  cursor: pointer;
}

.bulkSemanticToggle:hover,
.bulkSemanticToggle:focus-within {
  border-color: var(--lumiverse-primary);
}

.bulkSemanticCheckbox {
  margin-top: 2px;
  accent-color: var(--lumiverse-primary);
  cursor: pointer;
  flex-shrink: 0;
}

.bulkSemanticBody {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.bulkSemanticTitle {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
  line-height: 1.4;
}

.bulkSemanticMeta,
.bulkSemanticHint {
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
  line-height: 1.45;
}

.bookActionRow {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px 10px;
  padding-top: 2px;
}

.vectorStatusText {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
}

.entryList {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.entryRow {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 10px 12px;
  border-radius: 8px;
  background: color-mix(in srgb, var(--lumiverse-primary) 5%, var(--lumiverse-fill-subtle));
  border: 1px solid color-mix(in srgb, var(--lumiverse-primary) 8%, transparent);
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
}

.entryRow:hover {
  background: color-mix(in srgb, var(--lumiverse-primary) 8%, var(--lumiverse-fill-subtle));
  border-color: color-mix(in srgb, var(--lumiverse-primary) 15%, transparent);
}

.entryRowActive,
.entryRowActive:hover {
  border-color: var(--lumiverse-primary-050);
  background: var(--lumiverse-primary-015);
  border-radius: 8px 8px 0 0;
  border-bottom-color: transparent;
}

.entryRowDisabled {
  opacity: 0.5;
}

.entryTop {
  display: flex;
  align-items: center;
  gap: 6px;
}

.entryComment {
  flex: 1;
  font-size: calc(12.5px * var(--lumiverse-font-scale, 1));
  font-weight: 550;
  color: var(--lumiverse-text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}

.entryMeta {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
}

.entryBadge {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  padding: 1px 7px;
  border-radius: 4px;
  line-height: 1.5;
  white-space: nowrap;
}

.badgeConstant {
  background: rgba(245, 158, 11, 0.14);
  color: rgba(245, 178, 51, 0.9);
}

.badgeVector {
  background: rgba(34, 197, 94, 0.14);
  color: rgba(74, 207, 124, 0.9);
}

.badgeTrigger {
  background: var(--lumiverse-fill);
  color: var(--lumiverse-text-dim);
}

.entryMetaItem {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  padding: 1px 6px;
  border-radius: 4px;
  background: var(--lumiverse-fill);
  line-height: 1.5;
  white-space: nowrap;
}

.entryToggle {
  flex-shrink: 0;
}

.entryDeleteBtn {
  width: 20px;
  height: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 4px;
  background: transparent;
  border: none;
  color: var(--lumiverse-text-dim);
  cursor: pointer;
  opacity: 0;
  flex-shrink: 0;
  transition: all var(--lumiverse-transition-fast);
}

.entryRow:hover .entryDeleteBtn {
  opacity: 1;
}

.entryDeleteBtn:hover {
  color: var(--lumiverse-error);
}

.entryEmptyState {
  padding: 24px 12px;
  text-align: center;
  color: var(--lumiverse-text-dim);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  font-style: italic;
}

@media (max-width: 640px) {
  .contentScroll { padding: 8px 10px 0; }
  .contentFooter { padding: 0; }
}
.sidebarHidden { display: none; }
.mobileBooks { width: 100%; flex: 1; border-right: none; }
.workspaceScroll { display: flex; flex-direction: column; overflow: hidden; padding-top: 8px; }
.selectedBookHeader { display: flex; flex-shrink: 0; align-items: center; justify-content: space-between; gap: 8px; padding-bottom: 8px; border-bottom: 1px solid var(--lumiverse-border); }
.selectedBookHeader > div { display: flex; flex-direction: column; min-width: 0; }
.selectedBookHeader strong { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: calc(13px * var(--lumiverse-font-scale, 1)); }
.selectedBookHeader span { color: var(--lumiverse-text-muted); font-size: calc(11px * var(--lumiverse-font-scale, 1)); }
.bookFields[hidden] { display: none; }
.bookFields { flex-shrink: 0; max-height: 45%; overflow-y: auto; padding: 10px 0; }
.vectorTools summary { cursor: pointer; color: var(--lumiverse-text-muted); font-size: calc(12px * var(--lumiverse-font-scale, 1)); }

.nativeModal { height: calc(85dvh / var(--lumiverse-ui-scale, 1)); }
.nativeModal.nativeFullscreen {
  --worldbook-keyboard-clearance: calc(var(--app-keyboard-inset-bottom, 0px) / var(--lumiverse-ui-scale, 1));
  height: 100%;
  max-height: none;
  border-radius: 0;
  /* Body zoom scales the modal; hardware insets must stay in viewport pixels. */
  padding-top: calc(var(--worldbook-safe-top, var(--app-interactive-safe-top, env(safe-area-inset-top, 0px))) / var(--lumiverse-ui-scale, 1));
  padding-right: calc(var(--worldbook-safe-right, env(safe-area-inset-right, 0px)) / var(--lumiverse-ui-scale, 1));
  padding-bottom: calc(max(0px, var(--worldbook-safe-bottom, env(safe-area-inset-bottom, 0px)) - var(--app-keyboard-inset-bottom, 0px)) / var(--lumiverse-ui-scale, 1));
  padding-left: calc(var(--worldbook-safe-left, env(safe-area-inset-left, 0px)) / var(--lumiverse-ui-scale, 1));
  --worldbook-footer-safe-bottom: 0px;
}

/* The fullscreen frame already extends behind the keyboard. Its footer must
   not enlarge the editing pane a second time when the viewport gets shorter. */
.nativeModal.nativeFullscreen .contentFooter { margin-bottom: 0; }

.bookWorkspace { display: flex; flex: 1; min-width: 0; min-height: 0; }
.bookWorkspace[hidden] { display: none; }

@media (min-width: 801px) { .nativeModal .sidebar { width: 200px; flex-basis: 200px; } }

.selectedBookHeader[hidden] { display: none; }

import { useState, useEffect, useLayoutEffect, useCallback, useRef, useMemo, type KeyboardEvent } from 'react'
import { Trans, useTranslation } from 'react-i18next'
import { Plus, Trash2, BookOpen, Upload, User, FileUp, Search, Download, ArrowUp, ArrowDown, ArrowUpDown, CheckSquare, Square, X, Maximize2, Minimize2, PanelLeft } from 'lucide-react'
import { CloseButton } from '@/components/shared/CloseButton'
import { ModalShell } from '@/components/shared/ModalShell'
import { useStore } from '@/store'
import { worldBooksApi } from '@/api/world-books'
import ConfirmationModal from '@/components/shared/ConfirmationModal'
import ImportWorldBookModal, { type WorldBookImportResult } from './ImportWorldBookModal'
import PostImportWorldBookModal from '@/components/shared/PostImportWorldBookModal'
import WorldBookDiagnosticsModal from '@/components/panels/world-book/WorldBookDiagnosticsModal'
import { formatWorldBookReindexStatus } from '@/lib/worldBookVectorization'
import WorldBookEntriesSection from '@/components/shared/WorldBookEntriesSection'
import FolderDropdown from '@/components/shared/FolderDropdown'
import WorldBookColumnHandle from '@/components/shared/WorldBookColumnHandle'
import { useFolders } from '@/hooks/useFolders'
import { useWorldBookListLiveSync } from '@/hooks/useWorldBookListLiveSync'
import Pagination from '@/components/shared/Pagination'
import { triggerBlobDownload } from '@/lib/downloads'
import { upsertById } from '@/lib/worldBookList'
import { toast } from '@/lib/toast'
import { scheduleMicrotask } from '@/lib/schedule-microtask'
import type { WorldBook, WorldBookVectorSummary } from '@/types/api'
import type { WorldBookExportFormat } from '@/api/world-books'

import styles from './WorldBookEditorModal.module.css'
import clsx from 'clsx'
import { clearSearchOnEscape } from '@/lib/clearableSearch'
import useIsMobile from '@/hooks/useIsMobile'

const BOOK_SORT_OPTIONS = [
  { value: 'updated', labelKey: 'sortRecent' },
  { value: 'name', labelKey: 'sortName' },
] as const

const BOOK_PAGE_SIZE_OPTIONS = [10, 25, 50, 100, 'all'] as const

const BOOK_EXPORT_FORMAT_OPTIONS = [
  { value: 'lumiverse', labelKey: 'exportFormatLumiverse' },
  { value: 'character_book', labelKey: 'exportFormatCharacterBook' },
  { value: 'sillytavern', labelKey: 'exportFormatSillyTavern' },
] as const

type BookSortBy = (typeof BOOK_SORT_OPTIONS)[number]['value']
type BookSortDir = 'asc' | 'desc'
type BookPageSize = (typeof BOOK_PAGE_SIZE_OPTIONS)[number]

function getBlobFilename(blob: Blob): string | null {
  return typeof File !== 'undefined' && blob instanceof File && blob.name ? blob.name : null
}

export default function WorldBookEditorModal() {
  const { t } = useTranslation('modals', { keyPrefix: 'worldBookEditor' })
  const { t: tp } = useTranslation('panels', { keyPrefix: 'worldBookPanel' })
  const { t: tc } = useTranslation('common')
  const closeModal = useStore((s) => s.closeModal)
  const modalProps = useStore((s) => s.modalProps)
  const activeChatId = useStore((s) => s.activeChatId)
  const [fullscreen, setFullscreen] = useState(false)
  const isMobile = useIsMobile()
  const workspace = fullscreen || isMobile
  const [booksCollapsed, setBooksCollapsed] = useState(() => {
    try { return localStorage.getItem('lumiverse.worldBook.booksCollapsed') === 'true' } catch { return false }
  })
  const [mobileBooksOpen, setMobileBooksOpen] = useState(false)
  const [bookSettingsOpen, setBookSettingsOpen] = useState(false)
  const [editingEntry, setEditingEntry] = useState(false)
  const [booksWidth, setBooksWidth] = useState(200)
  const booksToggleRef = useRef<HTMLButtonElement>(null)
  const [entryCount, setEntryCount] = useState(0)
  const toggleBooks = () => {
    if (isMobile) setMobileBooksOpen(current => !current)
    else setBooksCollapsed(current => {
      try { localStorage.setItem('lumiverse.worldBook.booksCollapsed', String(!current)) } catch { /* Local preferences may be unavailable. */ }
      return !current
    })
  }

  // Book list state
  const [books, setBooks] = useState<WorldBook[]>([])
  const [searchFilter, setSearchFilter] = useState('')
  const [selectedBookId, setSelectedBookId] = useState<string | null>(
    (modalProps.bookId as string) || null
  )

  const [visitedBooks, setVisitedBooks] = useState<string[]>([])
  const activeBookRef = useRef(selectedBookId)
  activeBookRef.current = selectedBookId
  useEffect(() => { if (selectedBookId) setVisitedBooks(current => current.includes(selectedBookId) ? current : [...current, selectedBookId]); setMobileBooksOpen(false); setBookSettingsOpen(false) }, [selectedBookId])
  const [sortBy, setSortBy] = useState<BookSortBy>('updated')
  const [sortDir, setSortDir] = useState<BookSortDir>('desc')
  const [pageSize, setPageSize] = useState<BookPageSize>(50)
  const [page, setPage] = useState(1)
  const [selectMode, setSelectMode] = useState(false)
  const [selectedIds, setSelectedIds] = useState<Set<string>>(() => new Set())

  // Book editing state
  const [bookName, setBookName] = useState('')
  const [bookDescription, setBookDescription] = useState('')
  const [bookFolder, setBookFolder] = useState('')
  const [vectorSummary, setVectorSummary] = useState<WorldBookVectorSummary | null>(null)
  const {
    folders,
    createFolder,
    renameFolder: renameStoredFolder,
    deleteFolder: deleteStoredFolder,
  } = useFolders('worldBookFolders', books)

  const [postImportBook, setPostImportBook] = useState<WorldBook | null>(null)

  // Confirmation modals
  const [deleteBookConfirm, setDeleteBookConfirm] = useState<string | null>(null)
  const [bulkDeleteConfirm, setBulkDeleteConfirm] = useState<string[] | null>(null)
  const [bulkExportIds, setBulkExportIds] = useState<string[] | null>(null)
  const [bulkExportFormat, setBulkExportFormat] = useState<WorldBookExportFormat>('lumiverse')
  const [bulkActionPending, setBulkActionPending] = useState(false)
  const [deleteFolderConfirm, setDeleteFolderConfirm] = useState<string | null>(null)
  const [folderActionPending, setFolderActionPending] = useState(false)
  const [showImport, setShowImport] = useState(false)
  const [convertPreview, setConvertPreview] = useState<{
    total: number; eligible: number; keys_retained?: number; constant_skipped: number
    already_vectorized: number; empty_skipped: number; disabled_skipped: number
  } | null>(null)
  const [showDiagnosticsModal, setShowDiagnosticsModal] = useState(false)

  // Debounce refs
  const bookNameTimer = useRef<ReturnType<typeof setTimeout>>(undefined)
  const bookDescTimer = useRef<ReturnType<typeof setTimeout>>(undefined)
  const contentRootRef = useRef<HTMLDivElement>(null)
  const contentScrollRef = useRef<HTMLDivElement>(null)
  const [paginationContainer, setPaginationContainer] = useState<HTMLDivElement | null>(null)

  useLayoutEffect(() => {
    const root = contentRootRef.current
    if (!root) return

    const syncFooterHeight = () => {
      const footerHeight = paginationContainer?.childElementCount
        ? Math.round(paginationContainer.getBoundingClientRect().height)
        : 0
      root.style.setProperty('--worldbook-footer-height', `${footerHeight}px`)
    }

    syncFooterHeight()
    if (!paginationContainer || typeof ResizeObserver === 'undefined') {
      return () => {
        root.style.removeProperty('--worldbook-footer-height')
      }
    }

    const observer = new ResizeObserver(syncFooterHeight)
    observer.observe(paginationContainer)

    return () => {
      observer.disconnect()
      root.style.removeProperty('--worldbook-footer-height')
    }
  }, [paginationContainer])

  // Load books
  const loadBooks = useCallback(async () => {
    try {
      const res = await worldBooksApi.list({ limit: 1000 })
      setBooks(res.data)
    } catch {}
  }, [])

  useEffect(() => {
    loadBooks()
  }, [loadBooks])

  // Live-sync the book list with changes from other tabs/devices or Spindle.
  const { markLocalBookEdit } = useWorldBookListLiveSync({
    selectedBookId,
    setBooks,
    onSelectedBookDeleted: () => setSelectedBookId(null),
    refreshBooks: loadBooks,
  })

  const loadVectorSummary = useCallback(async (bookId: string) => {
    try {
      const summary = await worldBooksApi.getVectorSummary(bookId)
      if (activeBookRef.current === bookId) setVectorSummary(summary)
    } catch {
      if (activeBookRef.current === bookId) setVectorSummary(null)
    }
  }, [])

  useEffect(() => {
    if (selectedBookId) {
      loadVectorSummary(selectedBookId)
      const book = books.find((b) => b.id === selectedBookId)
      if (book) {
        setBookName(book.name)
        setBookDescription(book.description)
        setBookFolder(book.folder || '')
      }
      setShowDiagnosticsModal(false)
    } else {
      setVectorSummary(null)
      setShowDiagnosticsModal(false)
    }
  }, [selectedBookId, books, loadVectorSummary])

  // Filtered, sorted, and paginated books
  const filteredSortedBooks = useMemo(() => {
    const q = searchFilter.trim().toLowerCase()
    const visible = q
      ? books.filter((b) => b.name.toLowerCase().includes(q))
      : [...books]

    return visible.sort((a, b) => {
      const comparison = sortBy === 'name'
        ? a.name.localeCompare(b.name, undefined, { sensitivity: 'base' })
        : a.updated_at - b.updated_at
      return sortDir === 'asc' ? comparison : -comparison
    })
  }, [books, searchFilter, sortBy, sortDir])

  const totalBookPages = pageSize === 'all'
    ? 1
    : Math.max(1, Math.ceil(filteredSortedBooks.length / pageSize))
  const currentBookPage = Math.min(page, totalBookPages)
  const visibleBooks = useMemo(() => {
    if (pageSize === 'all') return filteredSortedBooks
    const start = (currentBookPage - 1) * pageSize
    return filteredSortedBooks.slice(start, start + pageSize)
  }, [filteredSortedBooks, currentBookPage, pageSize])
  const visibleBookIds = useMemo(() => visibleBooks.map((book) => book.id), [visibleBooks])
  const allVisibleBooksSelected = visibleBookIds.length > 0
    && visibleBookIds.every((id) => selectedIds.has(id))

  useEffect(() => {
    if (page > totalBookPages) setPage(totalBookPages)
  }, [page, totalBookPages])

  useEffect(() => {
    setSelectedIds((current) => {
      if (current.size === 0) return current
      const bookIds = new Set(books.map((book) => book.id))
      let changed = false
      const next = new Set<string>()
      current.forEach((id) => {
        if (bookIds.has(id)) next.add(id)
        else changed = true
      })
      return changed ? next : current
    })
  }, [books])

  // Book CRUD
  const handleCreateBook = useCallback(async () => {
    try {
      const book = await worldBooksApi.create({ name: t('newBookName') })
      setBooks((prev) => upsertById(prev, book))
      setSelectedBookId(book.id)
    } catch {}
  }, [t])

  const handleDeleteBook = useCallback(
    async (id: string) => {
      try {
        await worldBooksApi.delete(id)
        setBooks((prev) => prev.filter((b) => b.id !== id))
        if (selectedBookId === id) {
          setSelectedBookId(null)
        }
      } catch {}
    },
    [selectedBookId]
  )

  const handleSearchChange = useCallback((value: string) => {
    setSearchFilter(value)
    setPage(1)
  }, [])

  const handleSortByChange = useCallback((value: BookSortBy) => {
    setSortBy(value)
    setPage(1)
  }, [])

  const handleToggleSortDir = useCallback(() => {
    setSortDir((current) => (current === 'asc' ? 'desc' : 'asc'))
    setPage(1)
  }, [])

  const handlePageSizeChange = useCallback((value: string) => {
    setPageSize(value === 'all' ? 'all' : Number(value) as BookPageSize)
    setPage(1)
  }, [])

  const handleToggleSelectMode = useCallback(() => {
    setSelectMode((current) => {
      if (current) setSelectedIds(new Set())
      return !current
    })
  }, [])

  const handleToggleBookSelection = useCallback((bookId: string) => {
    setSelectedIds((current) => {
      const next = new Set(current)
      if (next.has(bookId)) next.delete(bookId)
      else next.add(bookId)
      return next
    })
  }, [])

  const handleSelectAllVisible = useCallback(() => {
    setSelectedIds((current) => {
      const next = new Set(current)
      const deselectVisible = visibleBookIds.length > 0 && visibleBookIds.every((id) => current.has(id))
      for (const id of visibleBookIds) {
        if (deselectVisible) next.delete(id)
        else next.add(id)
      }
      return next
    })
  }, [visibleBookIds])

  const handleBookRowActivate = useCallback((bookId: string) => {
    if (selectMode) {
      handleToggleBookSelection(bookId)
      return
    }
    setSelectedBookId(bookId)
    setMobileBooksOpen(false)
  }, [handleToggleBookSelection, selectMode])

  const handleBookRowKeyDown = useCallback((e: KeyboardEvent<HTMLDivElement>, bookId: string) => {
    if (e.key !== 'Enter' && e.key !== ' ') return
    e.preventDefault()
    handleBookRowActivate(bookId)
  }, [handleBookRowActivate])

  const handleDownloadBook = useCallback(async (book: WorldBook) => {
    try {
      await worldBooksApi.downloadWorldBook(book.id, book.name)
    } catch {}
  }, [])

  const handleBulkDelete = useCallback(async (ids: string[]) => {
    if (ids.length === 0) return
    setBulkActionPending(true)
    try {
      const result = await worldBooksApi.bulkDelete(ids)
      const deletedIds = new Set(result.deleted)
      setBooks((prev) => prev.filter((book) => !deletedIds.has(book.id)))
      setSelectedBookId((current) => (current && deletedIds.has(current) ? null : current))
      setSelectedIds(new Set())
      setBulkDeleteConfirm(null)
    } catch {
    } finally {
      setBulkActionPending(false)
    }
  }, [])

  const handleBulkExport = useCallback(async () => {
    if (!bulkExportIds || bulkExportIds.length === 0) return
    setBulkActionPending(true)
    try {
      const blob = await worldBooksApi.bulkExport(bulkExportIds, bulkExportFormat)
      await triggerBlobDownload(blob, getBlobFilename(blob) || 'world-books.zip')
      setBulkExportIds(null)
    } catch {
    } finally {
      setBulkActionPending(false)
    }
  }, [bulkExportFormat, bulkExportIds])

  const handleBulkMoveFolder = useCallback(async (folder: string) => {
    const ids = Array.from(selectedIds)
    if (ids.length === 0 || bulkActionPending) return
    const trimmed = folder.trim()
    const movedIds = new Set(ids)
    setBulkActionPending(true)
    if (selectedBookId && movedIds.has(selectedBookId)) markLocalBookEdit()
    try {
      await worldBooksApi.bulkMoveFolder(ids, trimmed)
      setBooks((prev) =>
        prev.map((book) => (movedIds.has(book.id) ? { ...book, folder: trimmed } : book))
      )
      setBookFolder((current) => (selectedBookId && movedIds.has(selectedBookId) ? trimmed : current))
      setSelectedIds(new Set())
    } catch {
    } finally {
      setBulkActionPending(false)
    }
  }, [bulkActionPending, markLocalBookEdit, selectedBookId, selectedIds])

  const handleRenameFolder = useCallback(async (oldName: string, newName: string) => {
    const source = oldName.trim()
    const target = newName.trim()
    if (!source || !target || source === target) return

    if (bookFolder === source) markLocalBookEdit()
    try {
      const result = await worldBooksApi.renameFolder(source, target)
      const updatedById = new Map(result.updated.map((book) => [book.id, book]))
      setBooks((previous) => previous.map((book) => updatedById.get(book.id) ?? book))
      setBookFolder((current) => (current === source ? target : current))
      renameStoredFolder(source, target)
      toast.success(t('renamedFolderSuccess', { name: target, count: result.count }))
    } catch (err: any) {
      toast.error(err.body?.error || err.message || t('renameFolderFailed'))
      throw err
    }
  }, [bookFolder, markLocalBookEdit, renameStoredFolder, t])

  const handleDeleteFolder = useCallback(async (name: string) => {
    const folder = name.trim()
    if (!folder || folderActionPending) return

    setFolderActionPending(true)
    if (bookFolder === folder) markLocalBookEdit()
    try {
      const result = await worldBooksApi.deleteFolder(folder)
      const updatedById = new Map(result.updated.map((book) => [book.id, book]))
      setBooks((previous) => previous.map((book) => updatedById.get(book.id) ?? book))
      setBookFolder((current) => (current === folder ? '' : current))
      deleteStoredFolder(folder)
      setDeleteFolderConfirm(null)
      toast.success(t('deletedFolderSuccess', { name: folder, count: result.count }))
    } catch (err: any) {
      toast.error(err.body?.error || err.message || t('deleteFolderFailed'))
    } finally {
      setFolderActionPending(false)
    }
  }, [bookFolder, deleteStoredFolder, folderActionPending, markLocalBookEdit, t])

  const handleBookNameChange = useCallback(
    (value: string) => {
      markLocalBookEdit()
      setBookName(value)
      clearTimeout(bookNameTimer.current)
      bookNameTimer.current = setTimeout(() => {
        if (selectedBookId && value.trim()) {
          worldBooksApi.update(selectedBookId, { name: value.trim() })
          setBooks((prev) =>
            prev.map((b) => (b.id === selectedBookId ? { ...b, name: value.trim() } : b))
          )
        }
      }, 400)
    },
    [selectedBookId, markLocalBookEdit]
  )

  const handleBookDescChange = useCallback(
    (value: string) => {
      markLocalBookEdit()
      setBookDescription(value)
      clearTimeout(bookDescTimer.current)
      bookDescTimer.current = setTimeout(() => {
        if (selectedBookId) {
          worldBooksApi.update(selectedBookId, { description: value })
        }
      }, 400)
    },
    [selectedBookId, markLocalBookEdit]
  )

  const handleBookFolderChange = useCallback(
    (value: string) => {
      markLocalBookEdit()
      const trimmed = value.trim()
      setBookFolder(trimmed)
      if (selectedBookId) {
        worldBooksApi.update(selectedBookId, { folder: trimmed })
        setBooks((prev) =>
          prev.map((b) => (b.id === selectedBookId ? { ...b, folder: trimmed } : b))
        )
      }
    },
    [selectedBookId, markLocalBookEdit]
  )

  const [vectorStatus, setVectorStatus] = useState<string | null>(null)
  const [reindexing, setReindexing] = useState(false)

  const handleReindexVectors = useCallback(async () => {
    if (!selectedBookId || reindexing) return
    try {
      setReindexing(true)
      setVectorStatus(t('reindexing'))
      const result = await worldBooksApi.reindexVectors(selectedBookId, {
        onProgress: (p) => {
          setVectorStatus(t('reindexProgress', { status: formatWorldBookReindexStatus(p) }))
        },
      })
      const finalStatus = formatWorldBookReindexStatus(result)
      setVectorStatus(t('doneStatus', { status: finalStatus }))
      await loadVectorSummary(selectedBookId)
    } catch {
      setVectorStatus(t('reindexFailed'))
    } finally {
      setReindexing(false)
    }
  }, [selectedBookId, reindexing, loadVectorSummary, t])

  const handleConvertToVectorizedPreview = useCallback(async () => {
    if (!selectedBookId) return
    try {
      const preview = await worldBooksApi.getConvertToVectorizedPreview(selectedBookId)
      setConvertPreview(preview)
    } catch {
      setVectorStatus(t('previewFailed'))
    }
  }, [selectedBookId, t])

  const handleConvertToVectorized = useCallback(async () => {
    if (!selectedBookId) return
    setConvertPreview(null)
    try {
      setReindexing(true)
      const result = await worldBooksApi.convertToVectorized(selectedBookId)
      setVectorSummary(result.summary)
      setVectorStatus(t('convertedCount', { count: result.converted }))
      const reindexResult = await worldBooksApi.reindexVectors(selectedBookId, {
        onProgress: (p) => {
          setVectorStatus(t('reindexProgress', { status: formatWorldBookReindexStatus(p) }))
        },
      })
      const finalStatus = formatWorldBookReindexStatus(reindexResult)
      setVectorStatus(t('doneStatus', { status: finalStatus }))
      await loadVectorSummary(selectedBookId)
    } catch {
      setVectorStatus(t('convertFailed'))
    } finally {
      setReindexing(false)
    }
  }, [selectedBookId, loadVectorSummary, t])

  const handleDiagnostics = useCallback(() => {
    if (!selectedBookId || !activeChatId) return
    setShowDiagnosticsModal(true)
  }, [selectedBookId, activeChatId])

  const handleImport = useCallback((result: WorldBookImportResult) => {
    setBooks((prev) => upsertById(prev, result.world_book))
    setSelectedBookId(result.world_book.id)
    setShowImport(false)
    setPostImportBook(result.world_book)
  }, [])

  return (
    <>
    <ModalShell isOpen={true} onClose={closeModal} fullscreen={workspace} maxWidth="clamp(340px, 92vw, min(1160px, var(--lumiverse-content-max-width, 1160px)))" zIndex={10001} className={clsx(styles.modal, styles.nativeModal, workspace && styles.nativeFullscreen)}>
        <div className={styles.header}>
          <button type="button" ref={booksToggleRef} className={styles.fullscreenBtn} onClick={toggleBooks} aria-label={isMobile ? 'Books' : booksCollapsed ? 'Show books' : 'Hide books'} aria-expanded={isMobile ? mobileBooksOpen : !booksCollapsed}><PanelLeft size={15} /></button>
          <h2 className={styles.title}>{t('modalTitle')}</h2>
          <div className={styles.headerActions}>
            {!isMobile && <button
              type="button"
              className={styles.fullscreenBtn}
              onClick={() => setFullscreen(current => !current)}
              title={fullscreen ? "Restore window" : "Maximize editor"}
              aria-label={fullscreen ? "Restore window" : "Maximize editor"}
              aria-pressed={fullscreen}
            >
              {fullscreen ? <Minimize2 size={15} /> : <Maximize2 size={15} />}
            </button>}
            <CloseButton onClick={closeModal} />
          </div>
        </div>

        <div className={styles.body}>
          {/* Left panel: Book list */}
          <div className={clsx(styles.sidebar, isMobile && styles.mobileBooks, (isMobile ? selectedBookId && !mobileBooksOpen : booksCollapsed) && styles.sidebarHidden)} aria-label="Books" style={!isMobile ? { width: booksWidth, flexBasis: booksWidth } : undefined}>
            <div className={styles.sidebarHeader}>
              <div className={styles.sidebarSearchRow}>
                <input
                  type="text"
                  className={styles.searchInput}
                  placeholder={t('searchPlaceholder')}
                  value={searchFilter}
                  onChange={(e) => handleSearchChange(e.target.value)}
                  onKeyDown={(e) => clearSearchOnEscape(e, searchFilter, () => handleSearchChange(''))}
                />
                {searchFilter && (
                  <button
                    type="button"
                    className={styles.searchClear}
                    onClick={() => handleSearchChange('')}
                    aria-label={tc('actions.clear')}
                  >
                    <X size={13} />
                  </button>
                )}
                <button
                  type="button"
                  className={styles.newBookBtn}
                  onClick={handleCreateBook}
                  title={t('createTitle')}
                >
                  <Plus size={14} />
                </button>
                <button
                  type="button"
                  className={styles.newBookBtn}
                  onClick={() => setShowImport(true)}
                  title={t('importTitle')}
                >
                  <Upload size={14} />
                </button>
              </div>
              <div className={styles.sidebarControlRow}>
                <select
                  className={styles.sidebarSelect}
                  value={sortBy}
                  onChange={(e) => handleSortByChange(e.target.value as BookSortBy)}
                  title={t('sortBy')}
                >
                  {BOOK_SORT_OPTIONS.map((option) => (
                    <option key={option.value} value={option.value}>{t(option.labelKey)}</option>
                  ))}
                </select>
                <select
                  className={clsx(styles.sidebarSelect, styles.sidebarPageSizeSelect)}
                  value={String(pageSize)}
                  onChange={(e) => handlePageSizeChange(e.target.value)}
                  title={t('pageSize')}
                >
                  {BOOK_PAGE_SIZE_OPTIONS.map((option) => (
                    <option key={String(option)} value={String(option)}>
                      {option === 'all' ? t('pageSizeAll') : t(`pageSize${option}`)}
                    </option>
                  ))}
                </select>
                <button
                  type="button"
                  className={styles.sidebarIconBtn}
                  onClick={handleToggleSortDir}
                  title={sortDir === 'asc' ? t('sortAsc') : t('sortDesc')}
                  aria-label={sortDir === 'asc' ? t('sortAsc') : t('sortDesc')}
                >
                  {sortDir === 'asc' ? <ArrowUp size={12} /> : <ArrowDown size={12} />}
                  <ArrowUpDown size={9} />
                </button>
                <button
                  type="button"
                  className={clsx(styles.sidebarIconBtn, selectMode && styles.sidebarIconBtnActive)}
                  onClick={handleToggleSelectMode}
                  title={selectMode ? t('exitSelectMode') : t('selectMode')}
                  aria-label={selectMode ? t('exitSelectMode') : t('selectMode')}
                  aria-pressed={selectMode}
                >
                  {selectMode ? <CheckSquare size={13} /> : <Square size={13} />}
                </button>
              </div>
            </div>

            {selectMode && (
              <div className={styles.bulkBar}>
                <div className={styles.bulkSelectionRow}>
                  <button
                    type="button"
                    className={styles.bulkToggle}
                    onClick={handleSelectAllVisible}
                    disabled={visibleBookIds.length === 0}
                    title={allVisibleBooksSelected ? t('deselectVisible') : t('selectAllVisible')}
                    aria-label={allVisibleBooksSelected ? t('deselectVisible') : t('selectAllVisible')}
                  >
                    {allVisibleBooksSelected ? <CheckSquare size={14} /> : <Square size={14} />}
