          </div>

          {!isMobile && !booksCollapsed && <WorldBookColumnHandle label="Resize books column" width={booksWidth} defaultWidth={200} min={140} max={320} collapseBelow={100} onResize={setBooksWidth} onCollapse={() => { toggleBooks(); scheduleMicrotask(() => booksToggleRef.current?.focus()) }} />}
          {/* Right panel: Book content */}
          <div ref={contentRootRef} className={clsx(styles.content, isMobile && (mobileBooksOpen || !selectedBookId) && styles.sidebarHidden)}>
            <div ref={contentScrollRef} className={clsx(styles.contentScroll, styles.workspaceScroll)}>
              {selectedBookId ? (
                <>
                  <div className={styles.selectedBookHeader} hidden={isMobile && editingEntry}>
                    <div><strong>{bookName}</strong><span>{entryCount} entries · {bookFolder || 'Unfiled'}{vectorSummary?.pending ? ` · ${vectorSummary.pending} vectors pending` : ''}{vectorSummary?.error ? ` · ${vectorSummary.error} vector errors` : ''}</span></div>
                    <button type="button" className={styles.secondaryBtn} aria-expanded={bookSettingsOpen} onClick={() => setBookSettingsOpen(current => !current)}>Book settings</button>
                  </div>
                  {/* Book name & description */}
                  <div className={styles.bookFields} hidden={!bookSettingsOpen || (isMobile && editingEntry)}>
                    <div className={styles.fieldRow}>
                      <label className={styles.fieldLabel}>{tp('name')}</label>
                      <input
                        type="text"
                        className={styles.fieldInput}
                        value={bookName}
                        onChange={(e) => handleBookNameChange(e.target.value)}
                      />
                    </div>
                    <div className={styles.fieldRow}>
                      <label className={styles.fieldLabel}>{tp('description')}</label>
                      <input
                        type="text"
                        className={styles.fieldInput}
                        value={bookDescription}
                        onChange={(e) => handleBookDescChange(e.target.value)}
                      />
                    </div>
                    <div className={styles.fieldRow}>
                      <label className={styles.fieldLabel}>{tp('folder')}</label>
                      <FolderDropdown
                        folders={folders}
                        selectedFolder={bookFolder}
                        onSelect={handleBookFolderChange}
                        onCreateFolder={createFolder}
                        onRenameFolder={handleRenameFolder}
                        onDeleteFolder={setDeleteFolderConfirm}
                      />
                    </div>
                    <details className={styles.vectorTools} open={vectorSummary?.pending || vectorSummary?.error ? true : undefined}>
                      <summary>Vector search: {vectorSummary?.enabled ? `${vectorSummary.enabled} enabled` : 'Off'}</summary>
                    {vectorSummary && (
                      <div className={styles.vectorSummary}>
                        <div className={styles.vectorSummaryTitle}>{tp('vectorStatusTitle')}</div>
                        <div className={styles.vectorSummaryGrid}>
                          <span>{tp('vectorEnabled', { count: vectorSummary.enabled })}</span>
                          <span>{tp('vectorNonEmpty', { enabled: vectorSummary.enabled_non_empty, total: vectorSummary.non_empty })}</span>
                          <span>{tp('vectorIndexed', { count: vectorSummary.indexed })}</span>
                          <span>{tp('vectorPending', { count: vectorSummary.pending })}</span>
                          <span>{tp('vectorErrors', { count: vectorSummary.error })}</span>
                        </div>
                      </div>
                    )}
                    <div className={styles.bookActionRow}>
                      <button
                        type="button"
                        className={styles.secondaryBtn}
                        onClick={handleReindexVectors}
                        disabled={reindexing}
                      >
                        {reindexing ? tp('reindexing') : t('reindexButton')}
                      </button>
                      <button
                        type="button"
                        className={styles.secondaryBtn}
                        onClick={handleConvertToVectorizedPreview}
                        disabled={reindexing}
                      >
                        {tp('convertToVectorized')}
                      </button>
                      <button
                        type="button"
                        className={styles.secondaryBtn}
                        onClick={handleDiagnostics}
                        disabled={!activeChatId}
                      >
                        <Search size={12} />
                        {t('diagnoseCurrentChat')}
                      </button>
                      {vectorStatus && (
                        <span className={styles.vectorStatusText}>{vectorStatus}</span>
                      )}
                    </div>
                    </details>
                  </div>

                  {visitedBooks.filter(id => books.some(book => book.id === id)).map(id => <div key={id} className={styles.bookWorkspace} hidden={id !== selectedBookId}>
                    <WorldBookEntriesSection books={books} selectedBookId={id} active={id === selectedBookId} onDetailViewChange={id === selectedBookId ? setEditingEntry : undefined} presentation="workspace" onEntryCount={id === selectedBookId ? setEntryCount : undefined} onRefreshVectorSummary={loadVectorSummary} />
                  </div>)}
                </>
              ) : (
                <div className={styles.emptyState}>
                  {t('selectOrCreate')}
                </div>
              )}
            </div>
            <div ref={setPaginationContainer} className={styles.contentFooter} />
          </div>
        </div>
    </ModalShell>

      {/* Delete book confirmation */}
      {deleteBookConfirm && (
        <ConfirmationModal
          isOpen={true}
          title={t('deleteBookTitle')}
          message={t('deleteBookMessage')}
          variant="danger"
          confirmText={tc('actions.delete')}
          onConfirm={async () => {
            await handleDeleteBook(deleteBookConfirm)
            setDeleteBookConfirm(null)
          }}
          onCancel={() => setDeleteBookConfirm(null)}
        />
      )}

      {/* Bulk delete confirmation */}
      {bulkDeleteConfirm && (
        <ConfirmationModal
          isOpen={true}
          title={t('bulkDeleteTitle')}
          message={t('bulkDeleteConfirmMessage', { count: bulkDeleteConfirm.length })}
          variant="danger"
          confirmText={tc('actions.delete')}
          loading={bulkActionPending}
          loadingText={t('bulkActionPending')}
          onConfirm={() => void handleBulkDelete(bulkDeleteConfirm)}
          onCancel={() => {
            if (!bulkActionPending) setBulkDeleteConfirm(null)
          }}
        />
      )}

      {deleteFolderConfirm && (
        <ConfirmationModal
          isOpen={true}
          title={t('deleteFolderTitle')}
          message={t('deleteFolderMessage', { name: deleteFolderConfirm })}
          variant="danger"
          confirmText={tc('actions.delete')}
          loading={folderActionPending}
          loadingText={t('bulkActionPending')}
          onConfirm={() => void handleDeleteFolder(deleteFolderConfirm)}
          onCancel={() => {
            if (!folderActionPending) setDeleteFolderConfirm(null)
          }}
        />
      )}

      {/* Bulk export format picker */}
      {bulkExportIds && (
        <ModalShell
          isOpen={true}
          onClose={() => {
            if (!bulkActionPending) setBulkExportIds(null)
          }}
          maxWidth="420px"
          zIndex={10003}
        >
          <div className={styles.bulkDialogBody}>
            <h3 className={styles.bulkDialogTitle}>{t('bulkExportTitle')}</h3>
            <p className={styles.bulkDialogText}>
              {t('bulkExportMessage', { count: bulkExportIds.length })}
            </p>
            <div className={styles.exportFormatOptions}>
              {BOOK_EXPORT_FORMAT_OPTIONS.map((option) => (
                <label
                  key={option.value}
                  className={clsx(
                    styles.exportFormatOption,
                    bulkExportFormat === option.value && styles.exportFormatOptionActive,
                  )}
                >
                  <input
                    type="radio"
                    name="world-book-bulk-export-format"
                    value={option.value}
                    checked={bulkExportFormat === option.value}
                    onChange={() => setBulkExportFormat(option.value)}
                    disabled={bulkActionPending}
                  />
                  <span>{t(option.labelKey)}</span>
                </label>
              ))}
            </div>
            <div className={styles.bulkDialogActions}>
              <button
                type="button"
                className={styles.secondaryBtn}
                onClick={() => setBulkExportIds(null)}
                disabled={bulkActionPending}
              >
                {tc('actions.cancel')}
              </button>
              <button
                type="button"
                className={styles.primaryActionBtn}
                onClick={() => void handleBulkExport()}
                disabled={bulkActionPending}
              >
                {bulkActionPending ? t('bulkActionPending') : t('bulkExportConfirm')}
              </button>
            </div>
          </div>
        </ModalShell>
      )}

      {/* Import modal */}
      {showImport && (
        <ImportWorldBookModal
          onImport={handleImport}
          onClose={() => setShowImport(false)}
        />
      )}

      {postImportBook && (
        <PostImportWorldBookModal
          book={postImportBook}
          onClose={() => setPostImportBook(null)}
        />
      )}

      {/* Convert to vectorized confirmation */}
      {convertPreview && (
        <ConfirmationModal
          isOpen={true}
          title={t('convertTitle')}
          message={
            convertPreview.eligible === 0
              ? t('convertNoneEligible')
              : (
                <>
                  <p>
                    <Trans
                      i18nKey="modals:worldBookEditor.convertConfirm"
                      values={{
                        count: convertPreview.eligible,
                        entryWord: convertPreview.eligible === 1 ? t('entry') : t('entries'),
                      }}
                      components={{ strong: <strong /> }}
                    />
                  </p>
                  <ul style={{ textAlign: 'left', margin: '8px 0', paddingLeft: '20px', fontSize: 'calc(12px * var(--lumiverse-font-scale, 1))', opacity: 0.8 }}>
                    {convertPreview.constant_skipped > 0 && (
                      <li>{t('constantSkipped', {
                        count: convertPreview.constant_skipped,
                        entryWord: convertPreview.constant_skipped === 1 ? t('entry') : t('entries'),
                      })}</li>
                    )}
                    {(convertPreview.keys_retained ?? 0) > 0 && (
                      <li>{t('keysRetained', {
                        count: convertPreview.keys_retained ?? 0,
                        entryWord: convertPreview.keys_retained === 1 ? t('entry') : t('entries'),
                      })}</li>
                    )}
                    {convertPreview.already_vectorized > 0 && (
                      <li>{t('alreadySkipped', {
                        count: convertPreview.already_vectorized,
                        entryWord: convertPreview.already_vectorized === 1 ? t('entry') : t('entries'),
                      })}</li>
                    )}
                    {convertPreview.empty_skipped > 0 && (
                      <li>{t('emptySkipped', {
                        count: convertPreview.empty_skipped,
                        entryWord: convertPreview.empty_skipped === 1 ? t('entry') : t('entries'),
                      })}</li>
                    )}
                    {convertPreview.disabled_skipped > 0 && (
                      <li>{t('disabledSkipped', {
                        count: convertPreview.disabled_skipped,
                        entryWord: convertPreview.disabled_skipped === 1 ? t('entry') : t('entries'),
                      })}</li>
                    )}
                  </ul>
                </>
              )
          }
          variant="safe"
          confirmText={convertPreview.eligible > 0 ? t('convertConfirmButton') : tp('ok')}
          onConfirm={convertPreview.eligible > 0 ? handleConvertToVectorized : () => setConvertPreview(null)}
          onCancel={() => setConvertPreview(null)}
        />
      )}

      {/* Diagnostics modal */}
      {showDiagnosticsModal && selectedBookId && activeChatId && (
        <WorldBookDiagnosticsModal
          book={books.find((b) => b.id === selectedBookId)!}
          chatId={activeChatId}
          onClose={() => setShowDiagnosticsModal(false)}
        />
      )}
    </>
  )
}

sources.src/components/modals/regexImportBatch.t:
export interface RegexImportResult {
  imported: number
  skipped: number
  errors: string[]
}

type ImportPayload = (payload: unknown) => Promise<RegexImportResult>

function getImportErrorMessage(error: unknown, fallback: string): string {
  if (!error || typeof error !== 'object') return fallback

  const body = 'body' in error ? error.body : undefined
  if (body && typeof body === 'object' && 'error' in body && typeof body.error === 'string') {
    return body.error
  }
  if ('message' in error && typeof error.message === 'string') return error.message
  return fallback
}

/**
 * Parse and import every selected file in a deterministic order. Files are
 * submitted separately so top-level import options (such as folders) remain
 * scoped to the JSON file that declared them.
 */
export async function importRegexFiles(
  files: readonly File[],
  importPayload: ImportPayload,
  messages: { invalidJson: string; importFailed: string },
): Promise<RegexImportResult> {
  const batchResult: RegexImportResult = { imported: 0, skipped: 0, errors: [] }

  for (const file of files) {
    let payload: unknown
    try {
      payload = JSON.parse(await file.text())
    } catch {
      batchResult.errors.push(`${file.name}: ${messages.invalidJson}`)
      continue
    }

    try {
      const result = await importPayload(payload)
      batchResult.imported += result.imported
      batchResult.skipped += result.skipped
      batchResult.errors.push(...result.errors.map((error) => `${file.name}: ${error}`))
    } catch (error) {
      batchResult.errors.push(`${file.name}: ${getImportErrorMessage(error, messages.importFailed)}`)
    }
  }

  return batchResult
}

