.panel {
  display: flex;
  flex-direction: column;
  gap: 0;
  padding-bottom: 8px;
}

/* Loading / empty */

.center {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 48px 16px;
  text-align: center;
  color: var(--lumiverse-text-muted);
}

.center svg {
  opacity: 0.35;
}

.centerTitle {
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  color: var(--lumiverse-text-muted);
  margin: 0;
}

.centerHint {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  margin: 0;
  line-height: 1.5;
}

/* Root node */

.root {
  display: flex;
  flex-direction: column;
  gap: 0;
}

/* Tree item (node + its children) */

.treeItem {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0;
}

/* Horizontal arm — only on items nested inside .children */
.children > .treeItem::before {
  content: '';
  position: absolute;
  left: -17px;
  top: 19px;
  width: 13px;
  height: 1px;
  background: var(--lumiverse-border-hover);
}

/* Node card */

.node {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 10px;
  border-radius: 8px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-bg-elevated);
  cursor: pointer;
  transition:
    border-color 0.15s ease,
    background 0.15s ease,
    box-shadow 0.15s ease,
    transform 0.15s ease;
  text-align: left;
  width: 100%;
}

.node:hover {
  border-color: var(--lumiverse-border-hover);
  background: var(--lumiverse-fill-subtle);
  transform: translateY(-1px);
  box-shadow: var(--lumiverse-shadow-sm);
}

.nodeCurrent {
  border-color: var(--lumiverse-primary-050);
  background: var(--lumiverse-primary-010);
  box-shadow:
    0 0 0 1px var(--lumiverse-primary-020),
    var(--lumiverse-shadow-sm);
}

.nodeCurrent:hover {
  border-color: var(--lumiverse-primary);
  background: var(--lumiverse-primary-010);
}

.nodeIcon {
  flex-shrink: 0;
  width: 24px;
  height: 24px;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text-muted);
}

.nodeCurrent .nodeIcon {
  background: var(--lumiverse-primary-020);
  color: var(--lumiverse-primary);
}

.nodeBody {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.nodeName {
  font-size: calc(12.5px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  color: var(--lumiverse-text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1.3;
}

.nodeCurrent .nodeName {
  color: var(--lumiverse-primary);
}

.nodeMeta {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  line-height: 1.3;
}

.branchPreview {
  display: flex;
  align-items: flex-start;
  gap: 4px;
  font-size: calc(10.5px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-hint);
  line-height: 1.35;
  margin-top: 1px;
}

.branchPreview > svg {
  flex-shrink: 0;
  margin-top: 1px;
  opacity: 0.6;
}

.branchPreview > span {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.nodeCurrentBadge {
  flex-shrink: 0;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--lumiverse-primary);
  background: var(--lumiverse-primary-020);
  border-radius: 4px;
  padding: 2px 6px;
}

/* Children container */

.children {
  margin-left: 12px;
  padding-left: 17px;
  border-left: 1px solid var(--lumiverse-border);
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 6px;
  padding-bottom: 2px;
}

/* Linear fork chains (single child) and depths past the width budget render
   flush: children align at the parent's indent instead of staircasing, so node
   cards never get pushed off-screen (where overflow-x: hidden would clip them).
   Rules come after .children so the equal-specificity overrides win on cascade. */
.childrenFlush {
  margin-left: 0;
  padding-left: 0;
  border-left: none;
}

.childrenFlush > .treeItem::before {
  display: none;
}

/* Hint at bottom */

.hint {
  margin-top: 20px;
  padding: 10px 12px;
  border-radius: 8px;
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  line-height: 1.5;
  display: flex;
  align-items: flex-start;
  gap: 8px;
}

.hint svg {
  flex-shrink: 0;
  margin-top: 1px;
  opacity: 0.6;
}

