import styles from './CharacterBrowser.module.css'

function CharacterSkeletons({ viewMode }: { viewMode: CharacterViewMode }) {
  if (viewMode === 'list') {
    return (
      <div className={styles.skeletonList}>
        {Array.from({ length: 8 }).map((_, i) => (
