.profileShell {
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-height: 100%;
}

.viewTabs {
  position: sticky;
  top: -12px;
  z-index: 4;
  isolation: isolate;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin: -12px -12px 0;
  padding: 12px 12px 10px;
  background:
    linear-gradient(
      180deg,
      color-mix(in srgb, var(--lumiverse-bg-deep, var(--lumiverse-bg)) 96%, var(--lumiverse-primary) 4%) 0%,
      color-mix(in srgb, var(--lumiverse-bg-deep, var(--lumiverse-bg)) 94%, var(--lumiverse-primary) 6%) 62%,
      color-mix(in srgb, var(--lumiverse-bg-deep, var(--lumiverse-bg)) 96%, var(--lumiverse-primary) 4%) 100%
    );
}

/* Keep the tint behind the complete tab control, then blend it into the
 * profile content without a hard divider. */
.viewTabs::after {
  content: '';
  position: absolute;
  z-index: 0;
  right: 0;
  bottom: -48px;
  left: 0;
  height: 48px;
  pointer-events: none;
  background: linear-gradient(
    180deg,
    color-mix(in srgb, var(--lumiverse-bg-deep, var(--lumiverse-bg)) 96%, var(--lumiverse-primary) 4%) 0%,
    transparent 100%
  );
}

:global([data-glass]) .viewTabs {
  backdrop-filter: blur(var(--lcs-glass-soft-blur, 10px)) var(--lcs-liquid-filter, );
}

.viewTab {
  position: relative;
  z-index: 1;
  appearance: none;
  border: 1px solid var(--lumiverse-primary-015, rgba(255, 255, 255, 0.08));
  background: color-mix(in srgb, var(--lumiverse-primary) 4%, transparent);
  color: var(--lumiverse-text-dim);
  border-radius: 999px;
  padding: 9px 14px;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  letter-spacing: 0.01em;
  cursor: pointer;
  transition:
    background var(--lumiverse-transition-fast),
    border-color var(--lumiverse-transition-fast),
    color var(--lumiverse-transition-fast),
    box-shadow var(--lumiverse-transition-fast);
}

.viewTab:hover {
  color: var(--lumiverse-text);
  border-color: var(--lumiverse-primary-030, rgba(255, 255, 255, 0.16));
  background: color-mix(in srgb, var(--lumiverse-primary) 10%, transparent);
}

.viewTabActive {
  color: var(--lumiverse-primary-text, var(--lumiverse-text));
  background: color-mix(in srgb, var(--lumiverse-primary) 18%, transparent);
  border-color: var(--lumiverse-primary-050, var(--lumiverse-primary));
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--lumiverse-primary) 28%, transparent);
}

.profile {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.creatorNotesView {
  display: flex;
  flex-direction: column;
  gap: 14px;
  margin: 0 -12px;
}

.creatorNotesHeader {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 0 14px;
}

.creatorNotesEyebrow {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--lumiverse-primary);
}

.creatorNotesTitle {
  margin: 0;
  font-size: calc(18px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  color: var(--lumiverse-text);
  letter-spacing: -0.015em;
}

.creatorNotesCreator {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
}

.creatorNotesHelper {
  margin: 0;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  line-height: 1.5;
  color: var(--lumiverse-text-muted);
}

.creatorNotesSurface {
  --prose-image-max-width: min(100%, 720px);
  --prose-image-max-height: min(72vh, 960px);
  padding: 16px 14px calc(24px + env(safe-area-inset-bottom, 0px));
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--lumiverse-primary) 7%, transparent) 0%, transparent 16%),
    color-mix(in srgb, var(--lumiverse-bg-panel, var(--lumiverse-bg)) 92%, black 8%);
  border-top: 1px solid var(--lumiverse-primary-015, rgba(255, 255, 255, 0.08));
  border-bottom: 1px solid var(--lumiverse-primary-015, rgba(255, 255, 255, 0.08));
  min-height: 100%;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.03);
}

:global([data-glass]) .creatorNotesSurface {
  backdrop-filter: blur(var(--lcs-glass-soft-blur, 8px)) var(--lcs-liquid-filter, );
}

.hero {
  display: flex;
  flex-direction: column;
  margin: -12px -12px 0;
  position: relative;
}

.heroImage {
  width: 100%;
  aspect-ratio: 2 / 3;
  overflow: hidden;
  mask-image: linear-gradient(to bottom, black 55%, rgba(0, 0, 0, 0.5) 75%, transparent 95%);
  -webkit-mask-image: linear-gradient(to bottom, black 55%, rgba(0, 0, 0, 0.5) 75%, transparent 95%);
  pointer-events: none;
}

.heroImage * {
  pointer-events: none;
}

.heroMeta {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 2px 12px 12px;
  margin-top: -45%;
  position: relative;
  z-index: 1;
  --hero-dominant: var(--lumiverse-primary);
  /* Fallbacks before JS applies — derived from the theme's own text color */
  --hero-contrast-shifted: var(--lumiverse-text);
  --hero-contrast-muted-shifted: var(--lumiverse-text-muted);
  --hero-contrast-name-shifted: var(--lumiverse-text);
  --hero-name-scrim: transparent;
  --hero-text-scrim: rgba(0, 0, 0, 0.28);
  --hero-ambient: var(--hero-ambient-dark, none);
}

:global([data-theme-mode='dark']) .heroMeta {
  --hero-contrast-shifted: var(--hero-contrast-dark, var(--lumiverse-text));
  --hero-contrast-muted-shifted: var(--hero-contrast-muted-dark, var(--lumiverse-text-muted));
  --hero-contrast-name-shifted: var(--hero-contrast-name-dark, var(--hero-contrast-shifted));
  --hero-name-scrim: var(--hero-name-scrim-dark, transparent);
  --hero-text-scrim: var(--hero-text-scrim-dark, rgba(0, 0, 0, 0.28));
}

:global([data-theme-mode='light']) .heroMeta {
  --hero-contrast-shifted: var(--hero-contrast-light, var(--lumiverse-text));
  --hero-contrast-muted-shifted: var(--hero-contrast-muted-light, var(--lumiverse-text-muted));
  --hero-contrast-name-shifted: var(--hero-contrast-name-light, var(--hero-contrast-shifted));
  --hero-name-scrim: var(--hero-name-scrim-light, transparent);
  --hero-text-scrim: var(--hero-text-scrim-light, rgba(255, 255, 255, 0.35));
  --hero-ambient: var(--hero-ambient-light, none);
}

.avatarFallback {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: calc(56px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  color: var(--lumiverse-primary-muted);
  background: var(--lumiverse-primary-010);
}

.name {
  margin: 0;
  position: relative;
  isolation: isolate;
  font-size: calc(22px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  text-align: center;
  /* The name sits highest in the hero overlay, over the least-faded image —
   * it gets its own band-specific contrast color. */
  color: var(--hero-contrast-name-shifted);
}

.name::before {
  content: '';
  position: absolute;
  z-index: -1;
  inset: -2px -8px;
  border-radius: 6px;
  background: var(--hero-name-scrim);
  pointer-events: none;
}

.creator {
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  text-align: center;
  color: var(--hero-contrast-muted-shifted);
}

.editBtn {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 5px 14px;
  border-radius: 8px;
  background: color-mix(in srgb, var(--hero-text-scrim) 72%, transparent);
  border: 1px solid color-mix(in srgb, var(--hero-contrast-shifted) 28%, transparent);
  color: var(--hero-contrast-muted-shifted);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  cursor: pointer;
  margin-top: 4px;
  transition: all var(--lumiverse-transition-fast);
}

.editBtn:hover {
  background: color-mix(in srgb, var(--hero-text-scrim) 90%, transparent);
  color: var(--hero-contrast-shifted);
  border-color: color-mix(in srgb, var(--hero-contrast-shifted) 44%, transparent);
}

.tags {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  justify-content: center;
  margin-top: 4px;
}

.tag {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  padding: 2px 8px;
  border-radius: 6px;
  background: color-mix(in srgb, var(--hero-dominant) 18%, var(--hero-text-scrim) 82%);
  color: var(--hero-contrast-shifted);
  border: 1px solid color-mix(in srgb, var(--hero-contrast-shifted) 24%, transparent);
}

.tagMore {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  padding: 2px 10px;
  border-radius: 6px;
  background: color-mix(in srgb, var(--hero-text-scrim) 68%, transparent);
  color: var(--hero-contrast-muted-shifted);
  border: 1px solid color-mix(in srgb, var(--hero-contrast-shifted) 20%, transparent);
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
}

.tagMore:hover {
  background: color-mix(in srgb, var(--hero-text-scrim) 82%, transparent);
  color: var(--hero-contrast-shifted);
  border-color: color-mix(in srgb, var(--hero-contrast-shifted) 34%, transparent);
}

.fieldContent {
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  line-height: 1.6;
  color: var(--lumiverse-text-muted);
  word-break: break-word;
}

.fieldContent > :first-child {
  margin-top: 0;
}

.fieldContent > :last-child {
  margin-bottom: 0;
}

.fieldContent p {
  margin: 0 0 8px;
}

.fieldContent ul,
.fieldContent ol {
  margin: 0 0 8px;
  padding-left: 20px;
  list-style-position: outside;
}

.fieldContent ul li {
  list-style: disc;
  margin: 2px 0;
}

.fieldContent ol li {
  list-style: decimal;
  margin: 2px 0;
}

.fieldContent code {
