  white-space: pre;
}

.fieldContent pre code {
  background: transparent;
  padding: 0;
  border-radius: 0;
}

.fieldContent h1,
.fieldContent h2,
.fieldContent h3,
.fieldContent h4,
.fieldContent h5,
.fieldContent h6 {
