  padding: 2px 10px;
  border-left: 2px solid var(--lumiverse-border);
  color: var(--lumiverse-text-dim);
}

.fieldContent strong {
  font-weight: 600;
  color: var(--lumiverse-text);
}

.fieldContent em {
  font-style: italic;
}

.placeholder {
  font-style: italic;
  color: var(--lumiverse-text-dim);
}

.empty, .loading {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 60px 20px;
  gap: 12px;
