  text-align: center;
}

/* ─── Group Chat Profile ─────────────────────────────────────────── */

.groupProfile {
  display: flex;
  flex-direction: column;
}

/* Contained mosaic — normal flow, rounded, no absolute/negative-margin tricks */
.groupMosaic {
  display: grid;
