}

.profileBar {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 8px;
  padding: 10px 12px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 10px;
  background: var(--lumiverse-fill-subtle, var(--lumiverse-fill));
}

.profileHeader {
  display: flex;
