  margin: 2px 0;
}

/* ── Tools section ────────────────────────────────── */

.toolsSection {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.toolsSectionHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.assignToolsBtn {
  padding: 3px 10px;
  border-radius: 5px;
  border: 1px solid var(--lumiverse-primary);
  background: transparent;
  color: var(--lumiverse-primary);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
}

.assignToolsBtn:hover {
  background: color-mix(in srgb, var(--lumiverse-primary) 12%, transparent);
}

/* Tool pills */
.toolPills {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.toolPill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 9px;
  border-radius: 6px;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  background: color-mix(in srgb, var(--lumiverse-primary) 14%, transparent);
  color: var(--lumiverse-primary);
  border: 1px solid color-mix(in srgb, var(--lumiverse-primary) 25%, transparent);
}

.toolPillExtension {
  composes: toolPill;
  background: color-mix(in srgb, rgb(45, 212, 191) 14%, transparent);
  color: rgb(45, 212, 191);
  border-color: color-mix(in srgb, rgb(45, 212, 191) 25%, transparent);
}

.toolPillRemove {
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--lumiverse-btn-icon-xs);
  height: var(--lumiverse-btn-icon-xs);
  border-radius: 50%;
  border: none;
  background: transparent;
  color: var(--lumiverse-primary);
  cursor: pointer;
  opacity: 0.5;
  transition: opacity var(--lumiverse-transition-fast);
}

.toolPillRemove:hover {
  opacity: 1;
}

.toolHistoryControls {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 8px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  background: color-mix(in srgb, var(--lumiverse-bg) 70%, transparent);
}

.toolHistoryRow {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.toolHistoryInfo {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.toolHistoryName {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text-muted);
}

.toolHistoryHint {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
}

.noTools {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  font-style: italic;
}

/* Inline tool picker */
.toolPickerInline {
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  padding: 10px;
  background: var(--lumiverse-bg);
}

/* Helper text */
.memberHelperText {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  line-height: 1.5;
  color: var(--lumiverse-text-dim);
  padding: 8px 10px;
  background: color-mix(in srgb, var(--lumiverse-fill) 60%, transparent);
  border-radius: 6px;
  border-left: 2px solid var(--lumiverse-border);
}

/* ── Member Add Form ──────────────────────────────── */

.memberForm {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 12px;
  border: 1px dashed color-mix(in srgb, var(--lumiverse-primary) 40%, var(--lumiverse-border));
  border-radius: 10px;
  background: color-mix(in srgb, var(--lumiverse-fill-subtle) 80%, transparent);
}

.formActions {
  display: flex;
  gap: 8px;
  padding-top: 4px;
}

.btnPrimary,
.btnSecondary {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 7px 14px;
  border-radius: 7px;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
  border: 1px solid var(--lumiverse-border);
}

.btnPrimary {
  background: var(--lumiverse-primary);
  color: var(--lumiverse-primary-text);
  border-color: var(--lumiverse-primary);
}

.btnPrimary:hover {
  filter: brightness(1.1);
}

.btnPrimary:disabled {
  opacity: 0.4;
  pointer-events: none;
}

.btnSecondary {
  background: var(--lumiverse-fill);
  color: var(--lumiverse-text-muted);
}

.btnSecondary:hover {
  background: var(--lumiverse-fill-hover);
  color: var(--lumiverse-text);
}

/* ── Add Buttons Row ─────────────────────────────── */

.addButtons {
  display: flex;
  gap: 8px;
}

.addBtn {
  flex: 1;
  border-style: dashed;
}

/* ── Add Dropdown ────────────────────────────────── */

.addDropdown {
  border: 1px solid var(--lumiverse-border);
  border-radius: 10px;
  background: var(--lumiverse-fill);
  overflow: hidden;
}

.addDropdownHeader {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 10px;
  border-bottom: 1px solid var(--lumiverse-border);
}

.addSearchWrapper {
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 1;
  padding: 5px 8px;
  border-radius: 6px;
  background: var(--lumiverse-bg);
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text-dim);
}

.addSearchInput {
  flex: 1;
  border: none;
  background: transparent;
  color: var(--lumiverse-text);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  outline: none;
}

.addSearchInput::placeholder {
  color: var(--lumiverse-text-dim);
}

.addSearchClear {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  border: none;
  background: transparent;
  color: var(--lumiverse-text-dim);
  cursor: pointer;
  border-radius: 50%;
}

.addSearchClear:hover {
  color: var(--lumiverse-text);
}

.addDropdownClose {
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--lumiverse-btn-icon);
  height: var(--lumiverse-btn-icon);
  border-radius: 6px;
  border: none;
  background: transparent;
  color: var(--lumiverse-text-dim);
  cursor: pointer;
}

.addDropdownClose:hover {
  background: var(--lumiverse-fill-hover);
  color: var(--lumiverse-text);
}

.addDropdownList {
  max-height: 240px;
  overflow-y: auto;
  padding: 4px;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
}

.addDropdownEmpty {
  padding: 20px 12px;
  text-align: center;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
}

.addDropdownItem {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 8px 10px;
  border: none;
  border-radius: 7px;
  background: transparent;
  cursor: pointer;
  text-align: left;
  color: var(--lumiverse-text);
  transition: background var(--lumiverse-transition-fast);
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}

.addDropdownItem:hover {
  background: var(--lumiverse-fill-hover);
}

.addDropdownItem:active {
  background: var(--lumiverse-fill-hover);
}

.addDropdownAvatar {
  flex-shrink: 0;
  width: 32px;
  height: 32px;
  border-radius: 6px;
  background: color-mix(in srgb, var(--lumiverse-primary) 12%, var(--lumiverse-fill));
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--lumiverse-primary);
  overflow: hidden;
}

.addDropdownAvatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.addDropdownInfo {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.addDropdownName {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.addDropdownPack {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.addDropdownPlus {
  flex-shrink: 0;
  color: var(--lumiverse-primary);
  opacity: 0.5;
  transition: opacity var(--lumiverse-transition-fast);
}

.addDropdownItem:hover .addDropdownPlus {
  opacity: 1;
}

/* ── Tool Selector (checklist) ────────────────────── */

.toolSelector {
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-height: 220px;
  overflow-y: auto;
  padding: 2px 0;
}

.toolCategory {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.toolCategoryLabel {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--lumiverse-text-dim);
  padding-bottom: 3px;
  border-bottom: 1px solid var(--lumiverse-border);
}

.toolCategoryLabelExt {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: rgb(45, 212, 191);
  padding-bottom: 3px;
  border-bottom: 1px solid color-mix(in srgb, rgb(45, 212, 191) 30%, var(--lumiverse-border));
}

.toolExtBadge {
  font-size: calc(9px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  padding: 1px 5px;
  border-radius: 4px;
  background: color-mix(in srgb, rgb(45, 212, 191) 14%, transparent);
  color: rgb(45, 212, 191);
  border: 1px solid color-mix(in srgb, rgb(45, 212, 191) 25%, transparent);
}

.toolCheckbox {
  padding: 3px 2px;
  border-radius: 4px;
  transition: background var(--lumiverse-transition-fast);
}

.toolCheckbox:hover {
  background: var(--lumiverse-fill-hover);
}

/* ── Loading / Empty ──────────────────────────────── */

.loadingItems {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  padding: 8px 0;
}

.emptyState {
  text-align: center;
  padding: 20px 12px;
  color: var(--lumiverse-text-dim);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
}

