  padding: 0 0 8px;
}

.row {
  display: flex;
  align-items: center;
  gap: 4px;
}

/* Selector dropdown trigger */
.selectorWrap {
  position: relative;
  flex: 1;
  min-width: 0;
}

.selector {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 6px 10px;
  border-radius: var(--lumiverse-radius-sm, 5px);
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
  transition: border-color var(--lumiverse-transition-fast, 120ms),
    background var(--lumiverse-transition-fast, 120ms);
}

.selector:hover {
  border-color: var(--lumiverse-border-hover);
  background: var(--lumiverse-fill-hover);
}

.selectorLabel {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.chevron {
  flex-shrink: 0;
  transition: transform 150ms ease;
}

.chevronOpen {
  transform: rotate(180deg);
}

/* Dropdown list */
.dropdown {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  right: 0;
  z-index: 100;
  max-height: 200px;
  overflow-y: auto;
  background: var(--lumiverse-bg-elevated);
  border: 1px solid var(--lumiverse-border);
  border-radius: var(--lumiverse-radius, 8px);
  box-shadow: var(--lumiverse-shadow-sm, 0 2px 8px rgba(0, 0, 0, 0.2));
  padding: 4px;
}

:global([data-glass]) .dropdown {
  background: color-mix(in srgb, var(--lumiverse-bg-deep) 80%, transparent);
  backdrop-filter: blur(var(--lcs-glass-blur, 8px)) var(--lcs-liquid-filter, );
  box-shadow: var(--lumiverse-shadow-md, 0 8px 24px rgba(0, 0, 0, 0.4));
}

.dropdownItem {
  display: block;
  width: 100%;
  padding: 6px 8px;
  border: none;
  background: transparent;
  color: var(--lumiverse-text);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  text-align: left;
  border-radius: 4px;
  cursor: pointer;
  transition: background 80ms;
}

.dropdownItem:hover {
  background: var(--lumiverse-fill-hover);
}

.dropdownItemActive {
  color: var(--lumiverse-primary);
  font-weight: 600;
  background: var(--lumiverse-primary-010);
}

.dropdownEmpty {
  padding: 8px;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  text-align: center;
}

/* Save flow */
.saveBtn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 6px;
  background: transparent;
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text-dim);
  cursor: pointer;
  flex-shrink: 0;
  transition: all var(--lumiverse-transition-fast, 120ms);
}

.saveBtn:hover {
  color: var(--lumiverse-primary);
  border-color: var(--lumiverse-primary);
  background: var(--lumiverse-primary-010);
}

.saveRow {
  display: flex;
  align-items: center;
  gap: 2px;
  flex: 1;
}

.saveInput {
  flex: 1;
  padding: 4px 8px;
  border-radius: 4px;
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  outline: none;
}

.saveInput:focus {
  border-color: var(--lumiverse-primary);
}

.saveConfirm,
.saveCancel {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border-radius: 4px;
  background: transparent;
  border: none;
  cursor: pointer;
  color: var(--lumiverse-text-dim);
}

.saveConfirm:hover { color: var(--lumiverse-primary); }
.saveCancel:hover { color: var(--lumiverse-danger, #dc3c3c); }
.saveConfirm:disabled { opacity: 0.3; cursor: not-allowed; }

/* Menu */
.menuWrap {
  position: relative;
}

.menuBtn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 6px;
  background: transparent;
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text-dim);
  cursor: pointer;
  flex-shrink: 0;
  transition: all var(--lumiverse-transition-fast, 120ms);
}

.menuBtn:hover {
  color: var(--lumiverse-text);
  background: var(--lumiverse-fill-subtle);
}

.menu {
  position: absolute;
  top: calc(100% + 4px);
  right: 0;
  z-index: 100;
  min-width: 160px;
  background: var(--lumiverse-bg-elevated);
  border: 1px solid var(--lumiverse-border);
  border-radius: var(--lumiverse-radius-md, 10px);
  box-shadow: var(--lumiverse-shadow-sm, 0 2px 8px rgba(0, 0, 0, 0.2));
  padding: 4px;
}

:global([data-glass]) .menu {
  background: color-mix(in srgb, var(--lumiverse-bg-deep) 80%, transparent);
  backdrop-filter: blur(var(--lcs-glass-blur, 8px)) var(--lcs-liquid-filter, );
  box-shadow: var(--lumiverse-shadow-md, 0 8px 24px rgba(0, 0, 0, 0.4));
}

.menuItem {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  padding: 6px 8px;
  border: none;
  background: transparent;
  color: var(--lumiverse-text);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  text-align: left;
  border-radius: 4px;
  cursor: pointer;
  transition: background 80ms;
}

.menuItem:hover {
  background: var(--lumiverse-fill-hover);
}

.menuItemDanger {
  color: var(--lumiverse-danger, #dc3c3c);
}

.menuItemDanger:hover {
  background: rgba(220, 60, 60, 0.1);
}

/* Rename inline */
.renameRow {
  display: flex;
  align-items: center;
  gap: 2px;
  width: 100%;
}

.renameInput {
  flex: 1;
  padding: 2px 6px;
  border-radius: 3px;
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-primary);
  color: var(--lumiverse-text);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  outline: none;
}

.renameBtn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  border: none;
  background: transparent;
  cursor: pointer;
  color: var(--lumiverse-text-dim);
  border-radius: 3px;
}

.renameBtn:hover {
  color: var(--lumiverse-text);
  background: var(--lumiverse-fill-subtle);
}

