import { useState, useEffect, useCallback, useRef } from 'react'
import { useTranslation } from 'react-i18next'
import { Save, ChevronDown, MoreVertical, RefreshCw, Trash2, Link, Unlink, Pencil, Check, X } from 'lucide-react'
import { useStore } from '@/store'
import { loadoutsApi } from '@/api/loadouts'
import ConfirmationModal from '@/components/shared/ConfirmationModal'
import { toast } from '@/lib/toast'
import type { Loadout, LoadoutBinding } from '@/api/loadouts'
import styles from './LoadoutSelector.module.css'
import clsx from 'clsx'

export default function LoadoutSelector() {
  const { t } = useTranslation('panels')
  const loadouts = useStore((s) => s.loadouts)
  const activeLoadoutId = useStore((s) => s.activeLoadoutId)
  const loadLoadouts = useStore((s) => s.loadLoadouts)
  const createLoadout = useStore((s) => s.createLoadout)
  const updateLoadout = useStore((s) => s.updateLoadout)
  const deleteLoadout = useStore((s) => s.deleteLoadout)
  const applyLoadout = useStore((s) => s.applyLoadout)
  const setActiveLoadoutId = useStore((s) => s.setActiveLoadoutId)
  const activeChatId = useStore((s) => s.activeChatId)
  const activeCharacterId = useStore((s) => s.activeCharacterId)

  const [dropdownOpen, setDropdownOpen] = useState(false)
  const [menuOpen, setMenuOpen] = useState(false)
  const [saving, setSaving] = useState(false)
  const [saveName, setSaveName] = useState('')
  const [renaming, setRenaming] = useState<string | null>(null)
  const [renameName, setRenameName] = useState('')
  const [confirmDelete, setConfirmDelete] = useState(false)
  const [chatBinding, setChatBinding] = useState<LoadoutBinding | null>(null)
  const [charBinding, setCharBinding] = useState<LoadoutBinding | null>(null)

  const dropdownRef = useRef<HTMLDivElement>(null)
  const menuRef = useRef<HTMLDivElement>(null)

  // Load loadouts on mount
  useEffect(() => { loadLoadouts() }, [loadLoadouts])

  // Load bindings when chat/character changes
  useEffect(() => {
    if (activeChatId) {
      loadoutsApi.getChatBinding(activeChatId).then(setChatBinding).catch(() => setChatBinding(null))
    } else {
      setChatBinding(null)
    }
  }, [activeChatId])

  useEffect(() => {
    if (activeCharacterId) {
      loadoutsApi.getCharacterBinding(activeCharacterId).then(setCharBinding).catch(() => setCharBinding(null))
    } else {
      setCharBinding(null)
    }
  }, [activeCharacterId])

  // Close dropdowns on outside click
  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) setDropdownOpen(false)
      if (menuRef.current && !menuRef.current.contains(e.target as Node)) setMenuOpen(false)
    }
    document.addEventListener('mousedown', handler)
    return () => document.removeEventListener('mousedown', handler)
  }, [])

  const activeLoadout = loadouts.find((l) => l.id === activeLoadoutId)

  const handleSelect = useCallback(async (loadout: Loadout) => {
    setDropdownOpen(false)
    await applyLoadout(loadout.id)
    toast.success(t('loadoutSelector.applied', { name: loadout.name }))
  }, [applyLoadout, t])

  const handleSelectCustom = useCallback(() => {
    setDropdownOpen(false)
    setActiveLoadoutId(null)
  }, [setActiveLoadoutId])

  const handleSave = useCallback(async () => {
    if (!saveName.trim()) return
    const loadout = await createLoadout(saveName.trim())
    if (loadout) {
      toast.success(t('loadoutSelector.saved', { name: loadout.name }))
      setActiveLoadoutId(loadout.id)
    }
    setSaving(false)
    setSaveName('')
  }, [saveName, createLoadout, setActiveLoadoutId, t])

  const handleRecapture = useCallback(async () => {
    if (!activeLoadoutId) return
    await updateLoadout(activeLoadoutId, { recapture: true })
    toast.success(t('loadoutSelector.recaptured'))
    setMenuOpen(false)
  }, [activeLoadoutId, updateLoadout, t])

  const handleDelete = useCallback(async () => {
    if (!activeLoadoutId) return
    const name = activeLoadout?.name
    setConfirmDelete(false)
    await deleteLoadout(activeLoadoutId)
    toast.success(t('loadoutSelector.deleted', { name }))
  }, [activeLoadoutId, activeLoadout, deleteLoadout, t])

  const handleRename = useCallback(async () => {
    if (!renaming || !renameName.trim()) return
    await updateLoadout(renaming, { name: renameName.trim() })
    setRenaming(null)
    setRenameName('')
    setMenuOpen(false)
  }, [renaming, renameName, updateLoadout])

  const handleBindChat = useCallback(async () => {
    if (!activeChatId || !activeLoadoutId) return
    try {
      const binding = await loadoutsApi.setChatBinding(activeChatId, activeLoadoutId)
      setChatBinding(binding)
      toast.success(t('loadoutSelector.boundChat'))
    } catch {
      toast.error(t('loadoutSelector.bindFailed'))
    }
    setMenuOpen(false)
  }, [activeChatId, activeLoadoutId, t])

  const handleUnbindChat = useCallback(async () => {
    if (!activeChatId) return
    try {
      await loadoutsApi.deleteChatBinding(activeChatId)
      setChatBinding(null)
      toast.success(t('loadoutSelector.unboundChat'))
    } catch {
      toast.error(t('loadoutSelector.unbindFailed'))
    }
    setMenuOpen(false)
  }, [activeChatId, t])

  const handleBindCharacter = useCallback(async () => {
    if (!activeCharacterId || !activeLoadoutId) return
    try {
      const binding = await loadoutsApi.setCharacterBinding(activeCharacterId, activeLoadoutId)
      setCharBinding(binding)
      toast.success(t('loadoutSelector.boundCharacter'))
    } catch {
      toast.error(t('loadoutSelector.bindFailed'))
    }
    setMenuOpen(false)
  }, [activeCharacterId, activeLoadoutId, t])

  const handleUnbindCharacter = useCallback(async () => {
    if (!activeCharacterId) return
    try {
      await loadoutsApi.deleteCharacterBinding(activeCharacterId)
      setCharBinding(null)
      toast.success(t('loadoutSelector.unboundCharacter'))
    } catch {
      toast.error(t('loadoutSelector.unbindFailed'))
    }
    setMenuOpen(false)
  }, [activeCharacterId, t])

  return (
    <div className={styles.container}>
      <div className={styles.row}>
        {/* Dropdown selector */}
        <div className={styles.selectorWrap} ref={dropdownRef}>
          <button
            type="button"
            className={styles.selector}
            onClick={() => setDropdownOpen(!dropdownOpen)}
          >
            <span className={styles.selectorLabel}>
              {activeLoadout ? activeLoadout.name : t('loadoutSelector.custom')}
            </span>
            <ChevronDown size={12} className={clsx(styles.chevron, dropdownOpen && styles.chevronOpen)} />
          </button>

          {dropdownOpen && (
            <div className={styles.dropdown}>
              <button
                type="button"
                className={clsx(styles.dropdownItem, !activeLoadoutId && styles.dropdownItemActive)}
                onClick={handleSelectCustom}
              >
                {t('loadoutSelector.custom')}
              </button>
              {loadouts.map((loadout) => (
                <button
                  key={loadout.id}
                  type="button"
                  className={clsx(styles.dropdownItem, activeLoadoutId === loadout.id && styles.dropdownItemActive)}
                  onClick={() => handleSelect(loadout)}
                >
                  {renaming === loadout.id ? (
                    <div className={styles.renameRow} onClick={(e) => e.stopPropagation()}>
                      <input
                        className={styles.renameInput}
                        value={renameName}
                        onChange={(e) => setRenameName(e.target.value)}
                        onKeyDown={(e) => { if (e.key === 'Enter') handleRename(); if (e.key === 'Escape') setRenaming(null) }}
                        autoFocus
                      />
                      <button type="button" className={styles.renameBtn} onClick={handleRename}><Check size={11} /></button>
                      <button type="button" className={styles.renameBtn} onClick={() => setRenaming(null)}><X size={11} /></button>
                    </div>
                  ) : (
                    loadout.name
                  )}
                </button>
              ))}
              {loadouts.length === 0 && (
                <div className={styles.dropdownEmpty}>{t('loadoutSelector.noSaved')}</div>
              )}
            </div>
          )}
        </div>

        {/* Save button */}
        {saving ? (
          <div className={styles.saveRow}>
            <input
              className={styles.saveInput}
              value={saveName}
              onChange={(e) => setSaveName(e.target.value)}
              onKeyDown={(e) => { if (e.key === 'Enter') handleSave(); if (e.key === 'Escape') { setSaving(false); setSaveName('') } }}
              placeholder={t('loadoutSelector.namePlaceholder')}
              autoFocus
            />
            <button type="button" className={styles.saveConfirm} onClick={handleSave} disabled={!saveName.trim()}>
              <Check size={12} />
            </button>
            <button type="button" className={styles.saveCancel} onClick={() => { setSaving(false); setSaveName('') }}>
              <X size={12} />
            </button>
          </div>
        ) : (
          <button
            type="button"
            className={styles.saveBtn}
            onClick={() => setSaving(true)}
            title={t('loadoutSelector.saveTitle')}
          >
            <Save size={12} />
          </button>
        )}

        {/* Menu button (only when a loadout is active) */}
        {activeLoadoutId && (
          <div className={styles.menuWrap} ref={menuRef}>
            <button
              type="button"
              className={styles.menuBtn}
              onClick={() => setMenuOpen(!menuOpen)}
            >
              <MoreVertical size={12} />
            </button>

            {menuOpen && (
              <div className={styles.menu}>
                <button type="button" className={styles.menuItem} onClick={() => {
                  setRenaming(activeLoadoutId)
                  setRenameName(activeLoadout?.name || '')
                  setMenuOpen(false)
                  setDropdownOpen(true)
                }}>
                  <Pencil size={11} /> {t('loadoutSelector.rename')}
                </button>
                <button type="button" className={styles.menuItem} onClick={handleRecapture}>
                  <RefreshCw size={11} /> {t('loadoutSelector.recapture')}
                </button>
                {activeChatId && (
                  chatBinding?.loadout_id === activeLoadoutId ? (
                    <button type="button" className={styles.menuItem} onClick={handleUnbindChat}>
                      <Unlink size={11} /> {t('loadoutSelector.unbindChat')}
                    </button>
                  ) : (
                    <button type="button" className={styles.menuItem} onClick={handleBindChat}>
                      <Link size={11} /> {t('loadoutSelector.bindChat')}
                    </button>
                  )
                )}
                {activeCharacterId && (
                  charBinding?.loadout_id === activeLoadoutId ? (
                    <button type="button" className={styles.menuItem} onClick={handleUnbindCharacter}>
                      <Unlink size={11} /> {t('loadoutSelector.unbindCharacter')}
                    </button>
                  ) : (
                    <button type="button" className={styles.menuItem} onClick={handleBindCharacter}>
                      <Link size={11} /> {t('loadoutSelector.bindCharacter')}
                    </button>
                  )
                )}
                <button type="button" className={clsx(styles.menuItem, styles.menuItemDanger)} onClick={() => { setMenuOpen(false); setConfirmDelete(true) }}>
                  <Trash2 size={11} /> {t('loadoutSelector.delete')}
                </button>
              </div>
            )}
          </div>
        )}
      </div>

      {confirmDelete && (
        <ConfirmationModal
          isOpen={true}
          title={t('loadoutSelector.deleteConfirmTitle')}
          message={t('loadoutSelector.deleteConfirmMessage', { name: activeLoadout?.name })}
          variant="danger"
          confirmText={t('loadoutSelector.delete')}
          onConfirm={() => { void handleDelete() }}
          onCancel={() => setConfirmDelete(false)}
        />
      )}
    </div>
  )
}

sources.src/components/panels/LoomBuilder.module:
/* ============================================================================
   LAYOUT
   ============================================================================ */

.layout {
  display: flex;
  flex-direction: column;
  background: var(--lumiverse-bg-deep);
  color: var(--lumiverse-text);
  height: 100%;
  max-height: 100%;
  min-height: 0;
}

.layoutCompact {
  height: 100%;
}

/* ============================================================================
   HEADER & TOOLBAR
   ============================================================================ */

.header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  background: var(--lumiverse-bg-deep);
  border-bottom: 1px solid var(--lumiverse-border);
  flex-shrink: 0;
}

.title {
  margin: 0;
  font-size: calc(16px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  white-space: nowrap;
}

.toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--lumiverse-border);
  flex-shrink: 0;
  background: var(--lumiverse-fill-medium, rgba(0, 0, 0, 0.15));
  position: relative;
  z-index: 10;
  flex-wrap: wrap;
  container-type: inline-size;
}

.presetSelector {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 1 1 220px;
  min-width: 0;
}

.presetSelect {
  flex: 1;
  min-width: 0;
}

.toolbarActions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 0 0 auto;
}

.extensionToolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 40px;
  padding: 6px 14px;
  border-bottom: 1px solid var(--lumiverse-border);
  flex-shrink: 0;
}

.extensionToolbar > div {
  min-width: 0;
}

.extensionTabBar {
  display: flex;
  gap: 4px;
  padding: 6px 14px 0;
  border-bottom: 1px solid var(--lumiverse-border);
  overflow-x: auto;
  flex-shrink: 0;
}

.extensionTab {
  appearance: none;
  border: 0;
  border-bottom: 2px solid transparent;
  background: transparent;
  color: var(--lumiverse-text-muted);
  padding: 8px 10px;
  font: inherit;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  white-space: nowrap;
  cursor: pointer;
}

.extensionTab:hover {
  color: var(--lumiverse-text);
}

.extensionTabActive {
  color: var(--lumiverse-primary);
  border-bottom-color: var(--lumiverse-primary);
}

.extensionTabContent {
  flex: 1;
  min-height: 0;
  overflow: auto;
  padding: 14px;
}

.searchToggle {
  flex-shrink: 0;
}

.searchToggleActive {
  color: var(--lumiverse-primary);
  border-color: var(--lumiverse-primary-020);
  background: var(--lumiverse-primary-010);
}

/* Keep the preset selector usable in narrow sidebars. The bulk action remains
   discoverable through its icon and tooltip, while its text returns when the
   toolbar has enough room for both controls. */
@container (max-width: 620px) {
  .categoryToggle {
    width: 36px;
    justify-content: center;
    gap: 0;
    padding-inline: 0;
  }

  .categoryToggle .toolbarButtonLabel {
    display: none;
  }
}

@container (max-width: 440px) {
  .searchToggle {
    width: 36px;
    justify-content: center;
    gap: 0;
    padding-inline: 0;
  }

  .searchToggle .toolbarButtonLabel {
    display: none;
  }
}

.searchBarRow {
  flex: 1 0 100%;
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.searchField {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 1;
  min-width: 0;
  padding: 8px 10px;
  border-radius: 10px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-input-bg, rgba(0, 0, 0, 0.2));
  transition: border-color var(--lumiverse-transition-fast), box-shadow var(--lumiverse-transition-fast);
}

.searchField:focus-within {
  border-color: var(--lumiverse-primary-muted);
  box-shadow: 0 0 0 3px var(--lumiverse-primary-010);
}

.searchIcon {
  color: var(--lumiverse-text-dim);
  flex-shrink: 0;
}

.searchInput {
  width: 100%;
  min-width: 0;
  border: none;
  background: transparent;
  color: var(--lumiverse-text);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  line-height: 1.4;
  outline: none;
  font-family: inherit;
  -webkit-appearance: none;
}

.searchInput::placeholder {
  color: var(--lumiverse-text-dim);
}

.searchClear {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  padding: 0;
  border-radius: 999px;
  color: var(--lumiverse-text-dim);
  flex-shrink: 0;
  transition: background var(--lumiverse-transition-fast), color var(--lumiverse-transition-fast);
}

.searchClear:hover {
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.05));
  color: var(--lumiverse-text);
}

.searchMeta {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  white-space: nowrap;
  flex-shrink: 0;
}

.presetCoverHeader {
  position: relative;
  min-height: clamp(96px, 17vw, 142px);
  overflow: hidden;
  flex-shrink: 0;
  isolation: isolate;
  border-bottom: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-bg-deep);
}

.presetCoverHeader::before,
.presetCoverHeader::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
}

.presetCoverHeader::before {
  background:
    linear-gradient(90deg, var(--lumiverse-bg-deep) 0%, color-mix(in srgb, var(--lumiverse-bg-deep) 76%, transparent) 34%, transparent 100%),
    radial-gradient(70% 120% at 18% 42%, color-mix(in srgb, var(--lumiverse-primary) 18%, transparent), transparent 68%);
}

.presetCoverHeader::after {
  background: linear-gradient(180deg, transparent 38%, color-mix(in srgb, var(--lumiverse-bg-deep) 68%, transparent) 72%, var(--lumiverse-bg-deep) 100%);
}

.presetCoverImage {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  filter: brightness(0.66) saturate(0.82) contrast(0.96);
  transform: scale(1.025);
}

.presetCoverContent {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  gap: 5px;
  min-height: clamp(96px, 17vw, 142px);
  max-width: 720px;
  padding: 26px 16px 14px;
}

.presetCoverBadgeRow {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.presetCoverBadge {
  display: inline-flex;
  align-items: center;
  padding: 2px 7px;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, var(--lumiverse-primary) 28%, transparent);
  background: color-mix(in srgb, var(--lumiverse-bg-deep) 66%, transparent);
  color: color-mix(in srgb, var(--lumiverse-primary) 78%, var(--lumiverse-text));
  font-size: calc(9px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.presetCoverTitle {
  margin: 0;
  max-width: min(560px, 100%);
  color: var(--lumiverse-text);
  font-size: calc(18px * var(--lumiverse-font-scale, 1));
  line-height: 1.08;
  font-weight: 700;
  letter-spacing: -0.03em;
  text-shadow: 0 2px 14px rgba(0, 0, 0, 0.42);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.presetCoverDescription {
  margin: 0;
  max-width: min(620px, 100%);
  color: var(--lumiverse-text-muted);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  line-height: 1.4;
  text-shadow: 0 1px 10px rgba(0, 0, 0, 0.5);
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
}

/* ============================================================================
   GUIDE VIEWER - EXTENSION
   ============================================================================ */

.extensionTabRow {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.extensionTabRow .extensionTabBar {
  flex: 1;
  min-width: 0;
}

.extensionGuideButton {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;

  width: 28px;
  height: 28px;
  padding: 0;

  border: 0;
  border-radius: 6px;
  background: transparent;

  color: var(--lumiverse-text-dim);
  opacity: 0.42;
  cursor: pointer;

  transition:
    opacity 120ms ease,
    color 120ms ease,
    background 120ms ease;
}

.extensionGuideButton:hover {
  opacity: 1;
  color: var(--lumiverse-text);
  background: var(--lumiverse-fill-subtle);
}

/* ============================================================================
   SCROLL AREA
   ============================================================================ */

.scrollArea {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  padding: 0 0 calc(24px + env(safe-area-inset-bottom, 0px));
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
}

.blockList {
  padding: 10px;
}

/* ============================================================================
   FORM ELEMENTS
   ============================================================================ */

.form {
  display: flex;
  flex-direction: column;
  gap: 16px;
  max-width: 800px;
  margin: 0 auto;
  width: 100%;
  padding: 12px 14px;
}

.formGroup {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.label {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.input {
  padding: 9px 12px;
  background: var(--lumiverse-input-bg, rgba(0, 0, 0, 0.2));
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  color: var(--lumiverse-text);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  outline: none;
  font-family: inherit;
  transition: border-color var(--lumiverse-transition-fast), box-shadow var(--lumiverse-transition-fast);
}

.input:focus {
  border-color: var(--lumiverse-primary-muted);
  box-shadow: 0 0 0 3px var(--lumiverse-primary-010);
}

.textarea {
  padding: 12px;
  background: var(--lumiverse-input-bg, rgba(0, 0, 0, 0.2));
  border: 1px solid var(--lumiverse-border);
  border-radius: 10px;
  color: var(--lumiverse-text);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  font-family: var(--lumiverse-font-mono, monospace);
  min-height: 180px;
  resize: vertical;
  outline: none;
  line-height: 1.6;
  transition: border-color var(--lumiverse-transition-fast), box-shadow var(--lumiverse-transition-fast);
}

.textarea:focus {
  border-color: var(--lumiverse-primary-muted);
  box-shadow: 0 0 0 3px var(--lumiverse-primary-010);
}

.select {
  padding: 9px 12px;
  background: var(--lumiverse-input-bg, rgba(0, 0, 0, 0.2));
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  color: var(--lumiverse-text);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  outline: none;
  cursor: pointer;
  transition: border-color var(--lumiverse-transition-fast), box-shadow var(--lumiverse-transition-fast);
}

.select:focus {
  border-color: var(--lumiverse-primary-muted);
  box-shadow: 0 0 0 3px var(--lumiverse-primary-010);
}

/* ============================================================================
   BLOCK LIST ITEMS
   ============================================================================ */

.item {
  display: flex;
  align-items: center;
  padding: 8px 10px;
  background: var(--lumiverse-fill, rgba(0, 0, 0, 0.15));
  border: 1px solid var(--lumiverse-border-neutral, rgba(128, 128, 128, 0.10));
  border-radius: 10px;
  margin-bottom: 4px;
  transition: all var(--lumiverse-transition-fast);
  gap: 6px;
}

.item:hover {
  background: var(--lumiverse-fill-medium, rgba(0, 0, 0, 0.2));
  border-color: var(--lumiverse-border-neutral-hover, rgba(128, 128, 128, 0.2));
}

.itemDragging {
  opacity: 0.6;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.25);
  border-color: var(--lumiverse-primary-muted);
  background: var(--lumiverse-fill-strong, rgba(0, 0, 0, 0.25));
}

.rootDropSlotWrap {
  position: relative;
  height: 0;
  margin: 0;
  overflow: visible;
}

.rootDropSlot {
  position: absolute;
  left: 0;
  right: 0;
  top: -9px;
  z-index: 2;
  height: 18px;
  opacity: 0;
  border-radius: 8px;
  border: 1px dashed transparent;
  background: transparent;
  transition: opacity var(--lumiverse-transition-fast), background var(--lumiverse-transition-fast), border-color var(--lumiverse-transition-fast);
}

.rootDropSlotActive {
  opacity: 1;
  border: 1px dashed var(--lumiverse-border-neutral, rgba(128, 128, 128, 0.16));
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.03));
}

.rootDropSlotOver {
  border-color: var(--lumiverse-primary-muted);
  background: var(--lumiverse-primary-010);
  box-shadow: inset 0 0 0 1px var(--lumiverse-primary-020);
}

.rootDropSlotAppendArmed {
  opacity: 1;
  border-color: var(--lumiverse-primary);
  background: color-mix(in srgb, var(--lumiverse-primary) 24%, transparent);
  animation: rootDropAppendFlash 0.6s steps(2, jump-none) infinite;
}

@keyframes rootDropAppendFlash {
  0%, 100% {
    border-color: var(--lumiverse-primary);
    background: color-mix(in srgb, var(--lumiverse-primary) 34%, transparent);
    box-shadow: inset 0 0 0 1px var(--lumiverse-primary), 0 0 0 3px color-mix(in srgb, var(--lumiverse-primary) 26%, transparent);
  }

  50% {
    border-color: color-mix(in srgb, var(--lumiverse-primary) 35%, transparent);
    background: color-mix(in srgb, var(--lumiverse-primary) 8%, transparent);
    box-shadow: inset 0 0 0 1px transparent, 0 0 0 0 transparent;
  }
}

.itemIndented {
  margin-left: 14px;
  border-left: 2px solid var(--lumiverse-primary-020);
  border-top-left-radius: 2px;
  border-bottom-left-radius: 2px;
}

.itemDisabled {
  opacity: 0.4;
}

.marker {
  background: var(--lumiverse-primary-light);
  border-color: var(--lumiverse-primary-015);
  border-style: dashed;
  opacity: 0.5;
}

.marker:hover {
  opacity: 0.8;
  border-color: var(--lumiverse-primary-020);
}

/* ============================================================================
   CATEGORY ACCORDION
   ============================================================================ */

.categoryHeader {
  background: var(--lumiverse-fill-medium, rgba(0, 0, 0, 0.2));
  border-color: var(--lumiverse-border-neutral, rgba(128, 128, 128, 0.15));
  cursor: pointer;
  user-select: none;
  margin-bottom: 3px;
  margin-top: 8px;
  border-radius: 10px;
}

.categoryHeader:hover {
  background: var(--lumiverse-fill-strong, rgba(0, 0, 0, 0.25));
}

.categoryMeta {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  cursor: pointer;
}

.categoryName {
  flex: 1 1 auto;
  min-width: 0;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--lumiverse-text-muted);
}

.categoryNameText {
  min-width: 0;
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.categoryCount {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  flex-shrink: 0;
}

.categoryMetaBadges {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
  white-space: nowrap;
}

/* ============================================================================
   BADGES
   ============================================================================ */

.badge {
  font-size: calc(9px * var(--lumiverse-font-scale, 1));
  padding: 2px 7px;
  border-radius: 10px;
  text-transform: uppercase;
  font-weight: 600;
  letter-spacing: 0.3px;
  flex-shrink: 0;
}

.badgeSystem {
  background: rgba(59, 130, 246, 0.12);
  color: #60a5fa;
  border: 1px solid rgba(59, 130, 246, 0.1);
}

.badgeUser {
  background: rgba(16, 185, 129, 0.12);
  color: #34d399;
  border: 1px solid rgba(16, 185, 129, 0.1);
}

.badgeAssistant {
  background: var(--lumiverse-warning-015);
  color: var(--lumiverse-warning);
  border: 1px solid var(--lumiverse-warning-015);
}

.badgeUserAppend {
  background: rgba(16, 185, 129, 0.2);
  color: #34d399;
  border: 1px solid rgba(16, 185, 129, 0.25);
}

.badgeAssistantAppend {
  background: var(--lumiverse-warning-020);
  color: var(--lumiverse-warning);
  border: 1px solid var(--lumiverse-warning-020);
}

.badgeMarker {
  background: var(--lumiverse-primary-010);
  color: var(--lumiverse-primary);
  border: 1px solid var(--lumiverse-primary-010);
}

.triggerBadge {
  font-size: calc(8px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  padding: 1px 4px;
  border-radius: 6px;
  background: var(--lumiverse-primary-010);
  color: var(--lumiverse-primary-muted);
  line-height: 1;
  border: 1px solid var(--lumiverse-primary-010);
}

.groupBadge {
  font-size: calc(8px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  padding: 1px 5px;
  border-radius: 999px;
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.05));
  color: var(--lumiverse-text-dim);
  border: 1px solid var(--lumiverse-border);
  line-height: 1.2;
  flex-shrink: 0;
  white-space: nowrap;
}

/* ============================================================================
   BUTTONS
   ============================================================================ */


.dragHandle {
  padding: 8px 4px;
  border-radius: 6px;
  background: transparent;
  border: none;
  color: var(--lumiverse-text-dim);
  cursor: grab;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  touch-action: none;
  margin: -2px 0;
  opacity: 0.5;
  transition: opacity var(--lumiverse-transition-fast);
}

.item:hover .dragHandle {
  opacity: 1;
}

.dragHandleDisabled {
  cursor: default;
  opacity: 0.18;
}

.item:hover .dragHandleDisabled {
  opacity: 0.28;
}

.btn {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 7px 12px;
  border-radius: 8px;
  border: 1px solid var(--lumiverse-border);
  background: transparent;
  color: var(--lumiverse-text-muted);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  cursor: pointer;
  white-space: nowrap;
  transition: all var(--lumiverse-transition-fast);
}

.btn:hover {
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.05));
  color: var(--lumiverse-text);
}

.btnPrimary {
  background: var(--lumiverse-primary);
  color: var(--lumiverse-primary-contrast, #fff);
  border-color: var(--lumiverse-primary);
}

.btnPrimary:hover {
  opacity: 0.9;
  background: var(--lumiverse-primary);
  color: var(--lumiverse-primary-contrast, #fff);
}

.btnDanger {
  background: var(--lumiverse-danger, #ef4444);
  color: var(--lumiverse-primary-contrast, #fff);
  border-color: var(--lumiverse-danger, #ef4444);
}

.btnSmall {
  padding: 5px 10px;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
}

.blockNameIconSealed {
  color: color-mix(in srgb, var(--lumiverse-primary) 75%, var(--lumiverse-text));
}

.sealedBlockPanel {
  border: 1px dashed color-mix(in srgb, var(--lumiverse-border) 86%, var(--lumiverse-text-dim));
  border-radius: 10px;
  background: color-mix(in srgb, var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.04)) 64%, transparent);
  overflow: hidden;
}

.sealedBlockPanelActive {
  border-style: solid;
  border-color: color-mix(in srgb, var(--lumiverse-primary) 42%, var(--lumiverse-border));
  background: color-mix(in srgb, var(--lumiverse-primary) 7%, transparent);
}

.sealedBlockReveal {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 9px 11px;
  border: 0;
  background: transparent;
  color: var(--lumiverse-text-muted);
  font: inherit;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
}

.sealedBlockReveal:hover {
  color: var(--lumiverse-text);
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.05));
}

.sealedBlockRevealCopy {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  font-weight: 600;
}

.sealedBlockChevron {
  flex-shrink: 0;
  transition: transform var(--lumiverse-transition-fast);
}

.sealedBlockChevronOpen {
  transform: rotate(180deg);
}

.sealedBlockBody {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 0 11px 11px;
}

.sealedBlockText {
  margin: 0;
  color: var(--lumiverse-text-dim);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  line-height: 1.45;
}

.sealedBlockArmRow {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 9px 10px;
  border-radius: 8px;
  border: 1px solid color-mix(in srgb, var(--lumiverse-primary) 28%, var(--lumiverse-border));
  color: var(--lumiverse-text);
  background: color-mix(in srgb, var(--lumiverse-primary) 6%, transparent);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  line-height: 1.35;
  cursor: pointer;
}

.sealedBlockArmRow input {
  margin-top: 1px;
}

.sealedBlockArmRowDisabled {
  opacity: 0.55;
  cursor: not-allowed;
}

/* ── Configure prompt variables action ── */
.variablesAction {
  padding: 12px 12px 10px;
}

.variablesBtn {
  width: 100%;
  justify-content: center;
  border-color: var(--lumiverse-primary-020, var(--lumiverse-primary-light));
  color: var(--lumiverse-text);
}

.variablesBtn:hover {
  background: var(--lumiverse-primary-light);
  border-color: var(--lumiverse-primary);
}

.variablesBtn svg {
  color: var(--lumiverse-primary);
  flex-shrink: 0;
}

/* ============================================================================
   EMPTY STATE
   ============================================================================ */

.emptyState {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 48px 20px;
  text-align: center;
  color: var(--lumiverse-text-dim);
  gap: 10px;
}

/* ============================================================================
   MACRO INSERTER
   ============================================================================ */

.macroPanel {
  border: 1px solid var(--lumiverse-border);
  border-radius: 10px;
  background: var(--lumiverse-bg-elevated);
  max-height: 200px;
  overflow-y: auto;
  box-shadow: var(--lumiverse-shadow-sm);
}

.macroSearch {
  padding: 8px;
  border-bottom: 1px solid var(--lumiverse-border);
}

.macroSearchInner {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 10px;
  background: var(--lumiverse-input-bg, rgba(0, 0, 0, 0.2));
  border-radius: 8px;
  border: 1px solid transparent;
  transition: border-color var(--lumiverse-transition-fast);
}

.macroSearchInner:focus-within {
  border-color: var(--lumiverse-primary-020);
}

.macroSearchInput {
  border: none;
  padding: 2px;
  background: transparent;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  width: 100%;
  color: var(--lumiverse-text);
  outline: none;
}

.macroGroup {
  padding: 6px 0;
}

.macroGroupTitle {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text-dim);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 4px 12px;
}

.macroItem {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 5px 12px;
  cursor: pointer;
  border-radius: 6px;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  margin: 0 4px;
  transition: background var(--lumiverse-transition-fast);
}

.macroItem:hover {
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.05));
}

.macroSyntax {
  font-family: var(--lumiverse-font-mono, monospace);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-primary);
}

.macroDesc {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  margin-left: 8px;
  text-align: right;
}

/* ============================================================================
   DROPDOWN MENU
   ============================================================================ */

.dropdownMenu {
  position: absolute;
  background: var(--lumiverse-gradient-modal, linear-gradient(135deg, rgba(35, 30, 48, 0.98), rgba(20, 17, 28, 0.98)));
  border: 1px solid var(--lumiverse-border);
  border-radius: 12px;
  padding: 4px;
  min-width: 220px;
  z-index: 100;
  box-shadow: var(--lumiverse-shadow-lg);
  max-height: 360px;
  overflow-y: auto;
}

.menuButton {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 8px 12px;
  background: transparent;
  border: none;
  color: var(--lumiverse-text);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
  border-radius: 8px;
  text-align: left;
  transition: background var(--lumiverse-transition-fast);
}

.menuButton:hover {
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.06));
}

.menuButtonDanger {
  color: var(--lumiverse-danger, #ef4444);
}

.menuButtonDanger:hover {
  background: var(--lumiverse-danger-015);
}

.sectionLabel {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--lumiverse-text-dim);
  padding: 8px 12px 4px;
}

.menuDivider {
  border: none;
  border-top: 1px solid var(--lumiverse-border);
  margin: 4px 8px;
}

/* ============================================================================
   POST HISTORY NOTE
   ============================================================================ */

.postHistoryNote {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-warning);
  padding: 6px 10px;
  background: rgba(245, 158, 11, 0.06);
  border-radius: 8px;
  border: 1px solid var(--lumiverse-warning-015);
  margin-top: 6px;
}

/* ============================================================================
   ACCORDION SECTIONS (Generation, Prompt Behavior, Completion, Advanced)
   ============================================================================ */

.accordionSection {
  border-bottom: 1px solid var(--lumiverse-border);
}

.accordionHeader {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  cursor: pointer;
  user-select: none;
  transition: background var(--lumiverse-transition-fast);
}

.accordionHeader:hover {
  background: var(--lumiverse-fill, rgba(0, 0, 0, 0.12));
}

.accordionHeaderActive {
  background: var(--lumiverse-primary-light);
}

.accordionHeaderActive:hover {
  background: var(--lumiverse-primary-015);
}

.accordionTitle {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: var(--lumiverse-text-muted);
  flex: 1;
}

.accordionBadge {
  font-size: calc(9px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  padding: 1px 6px;
  border-radius: 10px;
  background: var(--lumiverse-primary);
  color: var(--lumiverse-primary-contrast, #fff);
  min-width: 14px;
  text-align: center;
}

.accordionBody {
  padding: 10px 14px 14px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  background: var(--lumiverse-fill-subtle, rgba(0, 0, 0, 0.08));
}

.accordionBodyGen {
  padding: 6px 14px 14px;
  gap: 2px;
}

/* ============================================================================
   SAMPLER SLIDER
   ============================================================================ */

.sliderRow {
  padding: 6px 0 4px;
}

.sliderHeader {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 6px;
}

.sliderToggle {
  gap: 6px;
}

.sliderLabel {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  letter-spacing: 0.2px;
}

.sliderLabelSet {
  color: var(--lumiverse-text);
}

.sliderLabelUnset {
  color: var(--lumiverse-text-dim);
}

.sliderInput {
  width: 72px;
  padding: 3px 6px;
  border-radius: 6px;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-family: var(--lumiverse-font-mono, monospace);
  text-align: right;
  outline: none;
  -moz-appearance: textfield;
  transition: border-color var(--lumiverse-transition-fast), box-shadow var(--lumiverse-transition-fast);
}

.sliderInput::-webkit-outer-spin-button,
.sliderInput::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

.sliderInputSet {
  background: var(--lumiverse-input-bg, rgba(0, 0, 0, 0.2));
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text);
}

.sliderInputSet:focus {
  border-color: var(--lumiverse-primary-muted);
  box-shadow: 0 0 0 2px var(--lumiverse-primary-010);
}

.sliderInputUnset {
  background: transparent;
  border: 1px solid transparent;
  color: var(--lumiverse-text-dim);
}

/* Slider track / fill / thumb styles moved to shared/RangeSlider.module.css */

/* ============================================================================
   SETTINGS FIELDS
   ============================================================================ */

.settingsField {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.settingsFieldLabel {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
}

.settingsFieldLabelDefault {
  color: var(--lumiverse-text-muted);
}

.settingsFieldLabelModified {
  color: var(--lumiverse-text);
}

.settingsInput {
  width: 100%;
  padding: 6px 10px;
  box-sizing: border-box;
  background: var(--lumiverse-input-bg, rgba(0, 0, 0, 0.2));
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  color: var(--lumiverse-text);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  outline: none;
  transition: border-color var(--lumiverse-transition-fast), box-shadow var(--lumiverse-transition-fast);
}

.settingsInput:focus {
  border-color: var(--lumiverse-primary-muted);
  box-shadow: 0 0 0 2px var(--lumiverse-primary-010);
}

.settingsTextarea {
  width: 100%;
  min-height: 48px;
  padding: 8px 10px;
  box-sizing: border-box;
  background: var(--lumiverse-input-bg, rgba(0, 0, 0, 0.2));
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  color: var(--lumiverse-text);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-family: var(--lumiverse-font-mono, monospace);
  line-height: 1.5;
  resize: vertical;
  outline: none;
  transition: border-color var(--lumiverse-transition-fast), box-shadow var(--lumiverse-transition-fast);
}

.settingsTextarea:focus {
  border-color: var(--lumiverse-primary-muted);
  box-shadow: 0 0 0 2px var(--lumiverse-primary-010);
}

.settingsHint {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
}

.resetBtn {
  padding: 2px 6px;
  border-radius: 6px;
  background: transparent;
  border: 1px solid rgba(128, 128, 128, 0.15);
  color: var(--lumiverse-text-dim);
  font-size: calc(9px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 3px;
  transition: all var(--lumiverse-transition-fast);
}

.resetBtn:hover {
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.05));
  color: var(--lumiverse-text-muted);
  border-color: var(--lumiverse-border);
}

.samplerHeader {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 0 2px;
}

.samplerLabel {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--lumiverse-text-dim);
  flex: 1;
}


.jsonError {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-danger, #ef4444);
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 4px 0;
}

/* ============================================================================
   STOP STRINGS
   ============================================================================ */

.stopStringTag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 8px;
  border-radius: 10px;
  background: var(--lumiverse-fill-subtle, rgba(0, 0, 0, 0.1));
  border: 1px solid var(--lumiverse-border-neutral, rgba(128, 128, 128, 0.12));
  color: var(--lumiverse-text);
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-family: var(--lumiverse-font-mono, monospace);
}

.stopStringRemove {
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  color: var(--lumiverse-text-dim);
  display: flex;
  transition: color var(--lumiverse-transition-fast);
}

.stopStringRemove:hover {
  color: var(--lumiverse-danger, #ef4444);
}

/* ============================================================================
   CONNECTION PROFILE
   ============================================================================ */

.connectionProfile {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px 8px;
}

.connectionSource {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text-muted);
}

.connectionDot {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  opacity: 0.4;
}

.connectionModel {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ============================================================================
   PRESET PROFILE BINDINGS
   ============================================================================ */

.profileBar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  border-bottom: 1px solid var(--lumiverse-border);
  flex-wrap: wrap;
}

.profileLabel {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text-dim);
  text-transform: uppercase;
  letter-spacing: 0.4px;
  flex-shrink: 0;
}

.profileBtnGroup {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-wrap: wrap;
}

.profileBtn {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 3px 8px;
  border-radius: 6px;
  border: 1px solid var(--lumiverse-border);
  background: transparent;
  color: var(--lumiverse-text-dim);
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  cursor: pointer;
  white-space: nowrap;
  transition: all var(--lumiverse-transition-fast);
}

.profileBtn:hover:not(:disabled) {
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.05));
  color: var(--lumiverse-text-muted);
}

.profileBtn:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.profileBtnActive {
  background: var(--lumiverse-primary-010, rgba(139, 92, 246, 0.1));
  border-color: var(--lumiverse-primary-muted, rgba(139, 92, 246, 0.35));
  color: var(--lumiverse-primary);
}

.profileBtnActive:hover:not(:disabled) {
  background: var(--lumiverse-primary-010, rgba(139, 92, 246, 0.15));
  color: var(--lumiverse-primary);
}

.profileBtnDismiss {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-left: 2px;
  padding: 1px 2px;
  border-radius: 3px;
  opacity: 0.5;
  transition: all var(--lumiverse-transition-fast);
  cursor: pointer;
}

.profileBtnDismiss:hover {
  opacity: 1;
  background: var(--lumiverse-danger-010, rgba(239, 68, 68, 0.12));
  color: var(--lumiverse-danger, #ef4444);
}

.profileSourceBadge {
  font-size: calc(9px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-primary);
  opacity: 0.8;
  margin-left: auto;
  flex-shrink: 0;
}

/* ============================================================================
   CONTEXT METER (stubbed)
   ============================================================================ */

.contextMeter {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  border-bottom: 1px solid var(--lumiverse-border);
  transition: background var(--lumiverse-transition-fast);
}

.contextMeter:hover {
  background: var(--lumiverse-fill-subtle);
}

.contextBar {
  display: flex;
  height: 8px;
  border-radius: 3px;
  overflow: hidden;
  background: var(--lumiverse-fill-subtle);
  flex: 1;
  max-width: 160px;
}

.contextBarSegment {
  height: 100%;
  min-width: 1px;
}

.contextLabel {
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

/* ============================================================================
   CREATE PRESET MODAL
   ============================================================================ */

/* ── Preset Name Modal (create / rename) ── */

.presetManagerModal {
  height: min(780px, 90vh);
  min-height: min(620px, 86vh);
  box-shadow: 0 25px 60px -14px rgba(0, 0, 0, 0.58),
    0 0 44px var(--lumiverse-primary-015);
}

.presetManagerHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 20px 22px 16px;
  border-bottom: 1px solid var(--lumiverse-border);
  flex: 0 0 auto;
}

.presetManagerTitle {
  margin: 0;
  color: var(--lumiverse-text);
  font-size: calc(18px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  letter-spacing: -0.02em;
}

.presetManagerSubtitle {
  margin: 4px 0 0;
  color: var(--lumiverse-text-muted);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
}

.presetManagerClose {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  padding: 0;
  border: 1px solid transparent;
  border-radius: 9px;
  background: transparent;
  color: var(--lumiverse-text-muted);
  cursor: pointer;
}

.presetManagerClose:hover {
  color: var(--lumiverse-text);
  border-color: var(--lumiverse-border);
  background: var(--lumiverse-fill-subtle);
}

.presetManagerToolbar {
  display: flex;
  align-items: center;
  flex: 0 0 auto;
  flex-wrap: wrap;
  gap: 8px;
  padding: 12px 22px;
  border-bottom: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.025));
}

.presetManagerToolbarPrimary,
.presetManagerBulkActions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.presetManagerBulkActions {
  margin-left: auto;
  justify-content: flex-end;
}

.presetManagerToolbarSelecting .presetManagerBulkActions {
  flex-basis: 100%;
  width: 100%;
  margin-left: 0;
  justify-content: flex-start;
}

.presetManagerAction,
.presetManagerPrimaryAction,
.presetManagerDangerAction {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 34px;
  padding: 7px 12px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 9px;
  background: transparent;
  color: var(--lumiverse-text-muted);
  font: inherit;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  white-space: nowrap;
  cursor: pointer;
}

.presetManagerAction:disabled,
.presetManagerDangerAction:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.presetManagerAction:hover {
  color: var(--lumiverse-text);
  background: var(--lumiverse-fill-subtle);
}

.presetManagerSelectModeActive {
  color: var(--lumiverse-primary-text, #c4b5fd);
  border-color: var(--lumiverse-primary-050, rgba(147, 112, 219, 0.5));
  background: var(--lumiverse-primary-015, rgba(147, 112, 219, 0.15));
}

.presetManagerPrimaryAction {
  color: var(--lumiverse-primary-text, #c4b5fd);
  border-color: var(--lumiverse-primary-025, rgba(147, 112, 219, 0.25));
  background: var(--lumiverse-primary-015, rgba(147, 112, 219, 0.15));
}

.presetManagerPrimaryAction:hover {
  background: var(--lumiverse-primary-025, rgba(147, 112, 219, 0.25));
}

.presetManagerDangerAction {
  color: var(--lumiverse-danger, #f87171);
  border-color: color-mix(in srgb, var(--lumiverse-danger, #f87171) 24%, var(--lumiverse-border));
  background: color-mix(in srgb, var(--lumiverse-danger, #f87171) 7%, transparent);
}

.presetManagerDangerAction:hover:not(:disabled) {
  background: color-mix(in srgb, var(--lumiverse-danger, #f87171) 13%, transparent);
}

.presetManagerSelectAll {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 34px;
  padding: 7px 10px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: var(--lumiverse-text-muted);
  font: inherit;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  white-space: nowrap;
  cursor: pointer;
}

.presetManagerSelectAll:hover:not(:disabled) {
  color: var(--lumiverse-text);
  background: var(--lumiverse-fill-subtle);
}

.presetManagerSelectAll:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.presetManagerSelectedCount {
  padding: 4px 8px;
  border-radius: 999px;
  background: var(--lumiverse-primary-010, rgba(147, 112, 219, 0.1));
  color: var(--lumiverse-primary-text, #c4b5fd);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 650;
  white-space: nowrap;
}

.presetManagerGrid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  grid-auto-rows: minmax(202px, max-content);
  align-content: start;
  flex: 1 1 auto;
  gap: 14px;
  min-height: 0;
  padding: 18px 22px 24px;
  overflow-y: auto;
  overscroll-behavior: contain;
}

.presetManagerCard {
  position: relative;
  z-index: 0;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 202px;
  overflow: visible;
  border: 1px solid var(--lumiverse-border);
  border-radius: 13px;
  background: var(--lumiverse-bg-dark, rgba(0, 0, 0, 0.18));
  cursor: pointer;
  user-select: none;
  -webkit-touch-callout: none;
  transition: border-color var(--lumiverse-transition-fast), transform var(--lumiverse-transition-fast), box-shadow var(--lumiverse-transition-fast);
}

.presetManagerCard:hover {
  transform: translateY(-1px);
  border-color: var(--lumiverse-primary-025, rgba(147, 112, 219, 0.25));
}

.presetManagerCardActive {
  border-color: var(--lumiverse-primary-050, rgba(147, 112, 219, 0.5));
  box-shadow: 0 0 0 1px var(--lumiverse-primary-010, rgba(147, 112, 219, 0.1));
}

.presetManagerCardSelected {
  border-color: var(--lumiverse-primary-050, rgba(147, 112, 219, 0.5));
  box-shadow: 0 0 0 2px var(--lumiverse-primary-015, rgba(147, 112, 219, 0.15));
}

.presetManagerMedia {
  position: relative;
  display: grid;
  place-items: center;
  width: 100%;
  height: 132px;
  min-height: 132px;
  flex: 0 0 132px;
  overflow: hidden;
  border-bottom: 1px solid var(--lumiverse-border);
  border-radius: 12px 12px 0 0;
  background: linear-gradient(145deg, var(--lumiverse-primary-010, rgba(147, 112, 219, 0.1)), var(--lumiverse-fill-medium, rgba(0, 0, 0, 0.15)));
  color: var(--lumiverse-text-dim);
}

.presetManagerMediaSelectable {
  cursor: pointer;
}

.presetManagerCoverFallback {
  opacity: 0.32;
}

.presetManagerCoverImage {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.presetManagerActiveBadge {
  position: absolute;
  top: 9px;
  left: 9px;
  z-index: 1;
  padding: 4px 8px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--lumiverse-bg-deep) 82%, transparent);
  color: var(--lumiverse-primary-text, #ddd6fe);
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  backdrop-filter: blur(8px) var(--lcs-liquid-filter, );
}

.presetManagerCardSelect {
  position: absolute;
  top: 9px;
  right: 9px;
  z-index: 2;
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  cursor: pointer;
}

.presetManagerCardSelect input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
}

.presetManagerCardSelect span {
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border: 1px solid color-mix(in srgb, var(--lumiverse-text-muted) 50%, transparent);
  border-radius: 6px;
  background: color-mix(in srgb, var(--lumiverse-bg-deep) 82%, transparent);
  color: transparent;
  backdrop-filter: blur(8px) var(--lcs-liquid-filter, );
  transition: border-color var(--lumiverse-transition-fast), background var(--lumiverse-transition-fast), color var(--lumiverse-transition-fast);
}

.presetManagerCardSelect:hover span,
.presetManagerCardSelect input:focus-visible + span {
  border-color: var(--lumiverse-primary-050, rgba(147, 112, 219, 0.5));
}

.presetManagerCardSelect input:checked + span {
  border-color: var(--lumiverse-primary);
  background: var(--lumiverse-primary);
  color: var(--lumiverse-primary-contrast, #fff);
}

.presetManagerCardBody {
  position: relative;
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  justify-content: center;
  min-height: 68px;
  padding: 10px 10px 11px 12px;
  border-radius: 0 0 12px 12px;
  background: var(--lumiverse-bg-dark, rgba(0, 0, 0, 0.18));
}

.presetManagerCardTitleRow {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.presetManagerCardName {
  display: block;
  flex: 1 1 auto;
  min-width: 0;
  padding: 0;
  overflow: hidden;
  border: 0;
  background: transparent;
  color: var(--lumiverse-text);
  font: inherit;
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  font-weight: 650;
  text-align: left;
  text-overflow: ellipsis;
  white-space: nowrap;
  cursor: pointer;
}

.presetManagerCard:hover .presetManagerCardName {
  color: var(--lumiverse-primary-text, #c4b5fd);
}

.presetManagerCardMeta {
  display: block;
  margin-top: 3px;
  color: var(--lumiverse-text-dim);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
}


.presetManagerEmpty {
  grid-column: 1 / -1;
  display: grid;
  place-items: center;
  min-height: 260px;
  color: var(--lumiverse-text-muted);
  text-align: center;
}

.presetNameModal {
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5),
    0 0 40px var(--lumiverse-primary-020);
}

.presetNameHeader {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 20px 24px 14px;
  border-bottom: 1px solid var(--lumiverse-border);
  flex-shrink: 0;
}

.presetNameTitle {
  margin: 0;
  font-size: calc(15px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  color: var(--lumiverse-text);
  letter-spacing: -0.01em;
}

.presetNameBody {
  padding: 16px 24px 20px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.presetNameInput {
  width: 100%;
  padding: 12px 14px;
  border-radius: var(--lcs-radius-sm, 8px);
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-bg-dark);
  color: var(--lumiverse-text);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  line-height: 1.5;
  font-family: inherit;
  transition: border-color var(--lumiverse-transition-fast);
  box-sizing: border-box;
}

.presetNameInput::placeholder {
  color: var(--lumiverse-text-dim);
}

.presetNameInput:focus {
  outline: none;
  border-color: var(--lumiverse-primary-050, rgba(147, 112, 219, 0.5));
}

.presetNameActions {
  display: flex;
  align-items: center;
  gap: 8px;
  justify-content: flex-end;
}

.presetNameBtn {
  padding: 8px 18px;
  border-radius: var(--lcs-radius-sm, 8px);
  font-size: calc(12.5px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  cursor: pointer;
  border: 1px solid var(--lumiverse-border);
  transition: all var(--lumiverse-transition-fast);
}

.presetNameBtnCancel {
  background: transparent;
  color: var(--lumiverse-text-muted);
}

.presetNameBtnCancel:hover {
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.04));
  color: var(--lumiverse-text);
}

.presetNameBtnSubmit {
  background: var(--lumiverse-primary-015, rgba(147, 112, 219, 0.15));
  color: var(--lumiverse-primary-text, #c4b5fd);
  border-color: var(--lumiverse-primary-020, rgba(147, 112, 219, 0.2));
}

.presetNameBtnSubmit:hover {
  background: var(--lumiverse-primary-025, rgba(147, 112, 219, 0.25));
  border-color: var(--lumiverse-primary-050, rgba(147, 112, 219, 0.5));
}

.presetNameBtnSubmit:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

@media (max-width: 480px) {
  .presetManagerModal {
    min-height: 88vh;
    border-radius: 14px 14px 0 0;
  }

  .presetManagerHeader,
  .presetManagerToolbar,
  .presetManagerGrid {
    padding-left: 16px;
    padding-right: 16px;
  }

  .presetManagerBulkActions {
    width: 100%;
    margin-left: 0;
    justify-content: flex-start;
  }

  .presetManagerGrid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
  }

  .presetNameModal {
    border-radius: 14px 14px 0 0;
  }

  .searchBarRow {
    flex-direction: column;
    align-items: stretch;
    gap: 8px;
  }

  .searchMeta {
    white-space: normal;
  }

  .presetNameHeader {
    padding: 16px 18px 12px;
  }

  .presetNameBody {
    padding: 12px 18px 18px;
  }

  .presetNameActions {
    flex-direction: column-reverse;
  }

  .presetNameActions .presetNameBtn {
    width: 100%;
    text-align: center;
  }
}

@media screen and (max-width: 600px) {
  .searchInput {
    font-size: max(16px, calc(13px * var(--lumiverse-font-scale, 1)));
  }
}

/* ============================================================================
   ACTION BAR (bottom)
   ============================================================================ */

.actionBar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 10px 14px;
  border-top: 1px solid var(--lumiverse-border);
  justify-content: center;
  flex-shrink: 0;
  background: var(--lumiverse-fill-medium, rgba(0, 0, 0, 0.15));
  position: relative;
  z-index: 10;
  flex-wrap: wrap;
}

/* ============================================================================
   TRUNCATION TOOLTIP
   ============================================================================ */

.truncTooltip {
  position: relative;
}

.truncTooltip::after {
  content: attr(data-tooltip);
  position: absolute;
  left: 0;
  bottom: calc(100% + 6px);
  max-width: 320px;
  padding: 6px 10px;
  border-radius: 8px;
  background: var(--lumiverse-gradient-modal, linear-gradient(135deg, rgba(35, 30, 48, 0.98), rgba(20, 17, 28, 0.98)));
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 400;
  line-height: 1.45;
  white-space: pre-wrap;
  word-break: break-word;
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.3);
  z-index: 200;
  pointer-events: none;
  opacity: 0;
  transform: translateY(4px);
  transition: opacity 0.15s ease, transform 0.15s ease;
  transition-delay: 0s;
}

.truncTooltip:hover::after {
  opacity: 1;
  transform: translateY(0);
  transition-delay: 0.4s;
}

/* ============================================================================
   BLOCK CONTENT AREA
   ============================================================================ */

.blockContent {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.blockNameRow {
  display: flex;
  align-items: center;
  min-width: 0;
}

.blockName {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex: 1 1 auto;
  min-width: 0;
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  line-height: 1.3;
}

.blockNameText {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.blockNameIcon {
  flex-shrink: 0;
  opacity: 0.6;
}

.blockNameIconMuted {
  opacity: 0.4;
}

.blockMetaRow {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 4px;
  flex: 0 0 auto;
  flex-wrap: wrap;
  min-width: 0;
  align-self: center;
}

.triggerBadgeList {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  flex-wrap: wrap;
}

.blockPreview {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  opacity: 0.8;
}

/* ============================================================================
   INJECTION TRIGGERS (Block Editor)
   ============================================================================ */

.triggerLabel {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
  padding: 4px 8px;
  border-radius: 8px;
  transition: background var(--lumiverse-transition-fast);
}

.triggerLabel:hover {
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.04));
}

.triggerLabelActive {
  color: var(--lumiverse-text);
  background: var(--lumiverse-primary-light);
}

.triggerLabelInactive {
  color: var(--lumiverse-text-dim);
}

.triggerCheckbox {
  accent-color: var(--lumiverse-primary);
}

.tagTriggerField {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 10px;
  border-radius: 10px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-input-bg, rgba(0, 0, 0, 0.2));
}

.tagTriggerChip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 9px;
  border-radius: 999px;
  background: var(--lumiverse-primary-010);
  color: var(--lumiverse-primary);
  border: 1px solid var(--lumiverse-primary-020);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  line-height: 1;
}

.tagTriggerChipRemove {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  padding: 0;
  border: none;
  border-radius: 999px;
  background: transparent;
  color: inherit;
  cursor: pointer;
}

.tagTriggerChipRemove:hover {
  background: color-mix(in srgb, var(--lumiverse-primary) 14%, transparent);
}

.tagTriggerDraftRow {
  flex: 1 1 220px;
  min-width: 180px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.tagTriggerDraftInput {
  flex: 1;
  min-width: 0;
  border: none;
  background: transparent;
  color: var(--lumiverse-text);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  outline: none;
  padding: 4px 0;
}

.tagTriggerDraftInput::placeholder {
  color: var(--lumiverse-text-dim);
}

.tagTriggerDraftAdd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 8px;
  border: 1px solid var(--lumiverse-border);
  background: transparent;
  color: var(--lumiverse-text-muted);
  cursor: pointer;
  transition: background var(--lumiverse-transition-fast), color var(--lumiverse-transition-fast), opacity var(--lumiverse-transition-fast);
}

.tagTriggerDraftAdd:hover:not(:disabled) {
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.05));
  color: var(--lumiverse-text);
}

.tagTriggerDraftAdd:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

/* ============================================================================
   MACRO PREVIEW PANEL
   ============================================================================ */

.previewPanel {
  border: 1px solid var(--lumiverse-border);
  border-radius: 10px;
  background: var(--lumiverse-bg-elevated);
  overflow: hidden;
  margin-top: 4px;
}

.previewContent {
  padding: 12px;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-family: var(--lumiverse-font-mono, monospace);
  line-height: 1.6;
  color: var(--lumiverse-text-muted);
  white-space: pre-wrap;
  word-break: break-word;
  margin: 0;
  max-height: 200px;
  overflow-y: auto;
}

.previewDiagnostics {
  padding: 8px 12px;
  border-bottom: 1px solid var(--lumiverse-border);
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.previewDiagWarn {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-warning);
  display: flex;
  align-items: center;
  gap: 4px;
}

.previewDiagError {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-danger, #ef4444);
  display: flex;
  align-items: center;
  gap: 4px;
}

