.panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.reasoningContent,
.promptBehaviorContent {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.promptBehaviorContent {
  gap: 14px;
}

.bindingBanner {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 12px 14px;
  border-radius: 10px;
  border: 1px solid var(--lumiverse-primary-020);
  background: var(--lumiverse-primary-light);
}

.bindingBannerTitle {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-primary);
}

.bindingBannerText {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text);
}

.bindingBannerHint {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
}

.bindingBannerChanged {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.bindingBannerChanged .bindingBannerHint {
  flex: 1;
}

/* ── Quick preset buttons row ── */
.presetRow {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.presetBtn {
  padding: 6px 12px;
  border-radius: 6px;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  border: 1px solid var(--lumiverse-border);
  background: transparent;
  color: var(--lumiverse-text-muted);
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
}

.presetBtn:hover {
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text);
}

.presetBtnActive {
  background: var(--lumiverse-primary-light);
  border-color: var(--lumiverse-primary-020);
