}

/* ── Tag inputs row ── */
.tagRow {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.fieldGroup {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.fieldGroupDisabled {
