  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.customBodyDisabled {
  opacity: 0.45;
  pointer-events: none;
}

.jsonError {
  margin-top: 4px;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-error, #ef4444);
