.panel {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 4px 0;
}

.desc {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  line-height: 1.5;
  margin-bottom: 4px;
}

/* ── Toggle row ── */
.toggleRow {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 8px 0;
}

.toggleRowDisabled {
  opacity: 0.45;
  pointer-events: none;
}

.toggleLabel {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
  min-width: 0;
}

.toggleText {
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  color: var(--lumiverse-text);
}

.toggleHint {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  line-height: 1.4;
}

/* ── Collapsible content ── */
.collapsible {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 150ms ease;
}

.collapsibleOpen {
  grid-template-rows: 1fr;
}

.collapsibleInner {
  overflow: hidden;
}

/* ── Mode option ── */
.modeOption {
  padding: 0 0 4px;
}

/* ── Info box ── */
.infoBox {
  margin: 4px 0 8px;
  padding: 8px 12px;
  border-radius: var(--lumiverse-radius);
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
  line-height: 1.5;
}

.infoBoxMuted {
  opacity: 0.45;
}

.infoBoxHeader {
  display: flex;
  align-items: center;
  gap: 6px;
  font-weight: 600;
  margin-bottom: 4px;
  color: var(--lumiverse-text-dim);
}

.infoBoxList {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.infoBoxList li::before {
  content: '  ';
}

.infoBoxList code {
  padding: 1px 5px;
  border-radius: 3px;
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
  font-family: "SF Mono", "Fira Code", monospace;
  font-size: 0.9em;
  color: var(--lumiverse-primary-text);
}

.modeNote {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  font-style: italic;
  margin-top: 4px;
}

/* ── Behavioral Quirks ── */
.quirksSection {
  margin-top: 4px;
  padding: 8px 0;
  border-top: 1px solid var(--lumiverse-border);
}

.quirksSectionDisabled {
  opacity: 0.5;
}

.quirksHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.quirksHeaderLeft {
  display: flex;
  align-items: center;
  gap: 8px;
}

.quirksLabel {
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  color: var(--lumiverse-text);
}

.quirksHint {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  margin-top: 4px;
  line-height: 1.4;
}

.quirksHint code {
  padding: 1px 5px;
  border-radius: 3px;
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
  font-family: "SF Mono", "Fira Code", monospace;
  font-size: 0.9em;
  color: var(--lumiverse-primary-text);
}

/* .quirksEditBtn — migrated to shared Button component */

.quirksEdit {
  margin-top: 8px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.quirksTextarea {
  width: 100%;
  padding: 8px 10px;
  border-radius: var(--lumiverse-radius);
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-family: inherit;
  line-height: 1.5;
  resize: vertical;
  transition: border-color var(--lumiverse-transition-fast);
}

.quirksTextarea:focus {
  outline: none;
  border-color: var(--lumiverse-primary);
}

.quirksActions {
  display: flex;
  gap: 6px;
}

/* .quirksBtn, .quirksBtnPrimary — migrated to shared Button component */

.quirksPreview {
  margin-top: 6px;
  padding: 6px 10px;
  border-radius: var(--lumiverse-radius);
  background: var(--lumiverse-fill-subtle);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  line-height: 1.5;
  color: var(--lumiverse-text-muted);
  min-height: 28px;
}

.quirksEmpty {
  color: var(--lumiverse-text-dim);
  font-style: italic;
}

/* ── Selection buttons ── */
.selectionGroup {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-top: 4px;
}

.selectionGroupDisabled {
  opacity: 0.45;
  pointer-events: none;
}

.selectionBtn {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 8px 10px;
  border-radius: var(--lumiverse-radius);
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text);
  font-family: inherit;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  text-align: left;
  cursor: pointer;
  transition: background var(--lumiverse-transition-fast), border-color var(--lumiverse-transition-fast);
}

.selectionBtn:hover {
  background: var(--lumiverse-fill);
  border-color: var(--lumiverse-border-hover);
}

.selectionBtnDisabled {
  opacity: 0.45;
  pointer-events: none;
}

.selectionBtnIcon {
  color: var(--lumiverse-primary);
  flex-shrink: 0;
}

.selectionBtnLabel {
  flex: 1;
  font-weight: 500;
}

.selectionBtnBadge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  border-radius: 9px;
  background: var(--lumiverse-primary);
  color: var(--lumiverse-primary-contrast, #fff);
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  line-height: 1;
}

.selectionBtnChevron {
  color: var(--lumiverse-text-dim);
  flex-shrink: 0;
}

/* ── Filter items ── */
.filterItem {
  padding: 2px 0;
}

.filterSub {
  padding-left: 16px;
  border-left: 2px solid var(--lumiverse-border);
  margin-left: 4px;
}

.filterModeBlock {
  padding: 2px 0 8px;
}

.filterDepthRow {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 0 8px;
}

.filterDepthLabel {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
  flex: 1;
}

.filterDepthInput {
  width: 56px;
}

