// ============================================================================
// Public API — the shape BlockEditor already consumes.
// ============================================================================

export interface VariablesEditorProps {
  variables: PromptVariableDef[]
  onChange: (vars: PromptVariableDef[]) => void
  placementBinding?: PromptBlockPlacementBinding
  fallbackPlacement: PromptBlockPlacement
  onPlacementBindingChange: (binding: PromptBlockPlacementBinding | undefined) => void
  /** When provided, each variable row can open the native move-target picker. */
  moveTargets?: VariableMoveTarget[]
  onMoveToBlock?: (variableId: string, targetBlockId: string) => void
}

const TYPE_ACCENT_CLASS: Record<PromptVariableType, string> = {
  text: css.typeText,
  textarea: css.typeTextarea,
  number: css.typeNumber,
  slider: css.typeSlider,
  range: css.typeSlider,
  select: css.typeSelect,
  switch: css.typeSwitch,
  multiselect: css.typeMultiselect,
}

function makeNewVariable(): PromptVariableDef {
  return {
    id: generateUUID(),
    name: '',
    label: '',
    type: 'text',
    defaultValue: '',
  }
}

function makeNewOption(index: number): PromptVariableOption {
  return { id: generateUUID(), label: `Option ${index + 1}`, value: '' }
}

export function reorderPromptVariables(
  variables: PromptVariableDef[],
  activeId: string,
  overId: string | null,
): PromptVariableDef[] {
  if (!overId || activeId === overId) return variables

  const activeIndex = variables.findIndex((variable) => variable.id === activeId)
  const overIndex = variables.findIndex((variable) => variable.id === overId)
  if (activeIndex < 0 || overIndex < 0) return variables

  return arrayMove(variables, activeIndex, overIndex)
}

// Type-preserving migration. Swapping types shouldn't nuke the user's work —
// we coerce where possible and fall back to safe defaults when not.
function coerceVariableType(
  current: PromptVariableDef,
  nextType: PromptVariableType,
): PromptVariableDef {
  const base = {
    id: current.id,
    name: current.name,
    label: current.label,
    description: current.description,
  }
  switch (nextType) {
    case 'text':
      return {
        ...base,
        type: 'text',
        defaultValue:
          typeof current.defaultValue === 'string'
            ? current.defaultValue
            : String(current.defaultValue ?? ''),
      }
    case 'textarea':
      return {
        ...base,
        type: 'textarea',
        defaultValue:
          typeof current.defaultValue === 'string'
            ? current.defaultValue
            : String(current.defaultValue ?? ''),
        rows: (current as { rows?: number }).rows ?? 4,
      }
    case 'number': {
      const num =
        typeof current.defaultValue === 'number'
          ? current.defaultValue
          : Array.isArray(current.defaultValue) && typeof current.defaultValue[0] === 'number'
            ? current.defaultValue[0]
            : Number(current.defaultValue) || 0
      return {
        ...base,
        type: 'number',
        defaultValue: num,
        min: (current as { min?: number }).min,
        max: (current as { max?: number }).max,
        step: (current as { step?: number }).step ?? 1,
      }
    }
    case 'slider': {
      const num =
        typeof current.defaultValue === 'number'
          ? current.defaultValue
          : Array.isArray(current.defaultValue) && typeof current.defaultValue[0] === 'number'
            ? current.defaultValue[0]
            : Number(current.defaultValue) || 0
      const min =
        typeof (current as { min?: number }).min === 'number'
          ? (current as { min: number }).min
          : 0
      const max =
        typeof (current as { max?: number }).max === 'number'
          ? (current as { max: number }).max
          : 100
      return {
        ...base,
        type: 'slider',
        defaultValue: Math.min(Math.max(num, min), max),
        min,
        max,
        step: (current as { step?: number }).step ?? 1,
      }
    }
    case 'range': {
      const min = typeof (current as { min?: number }).min === 'number'
        ? (current as { min: number }).min
        : 0
      const max = typeof (current as { max?: number }).max === 'number'
        ? (current as { max: number }).max
        : 100
      const prior = Array.isArray(current.defaultValue)
        && current.defaultValue.length === 2
        && current.defaultValue.every((entry) => typeof entry === 'number')
        ? current.defaultValue as [number, number]
        : typeof current.defaultValue === 'number' && Number.isFinite(current.defaultValue)
          ? [current.defaultValue, max] as [number, number]
          : [min, max] as [number, number]
      const start = Math.min(max, Math.max(min, prior[0]))
      const end = Math.min(max, Math.max(min, prior[1]))
      return {
        ...base,
        type: 'range',
        defaultValue: start <= end ? [start, end] : [end, start],
        min,
        max,
        step: (current as { step?: number }).step ?? 1,
      }
    }
    case 'select': {
      const existing = (current as { options?: PromptVariableOption[] }).options ?? []
      const options = existing.length ? existing : [makeNewOption(0)]
      const validIds = new Set(options.map((o) => o.id))
      const candidate =
        typeof current.defaultValue === 'string' && validIds.has(current.defaultValue)
          ? current.defaultValue
          : options[0].id
      return {
        ...base,
        type: 'select',
        defaultValue: candidate,
        options,
      }
    }
    case 'switch': {
      // Accept anything truthy from prior types as a hint, but bias to 0.
      const dv = current.defaultValue as unknown
      const on =
        dv === 1 ||
        dv === '1' ||
        dv === true ||
        (typeof dv === 'string' && ['true', 'on', 'yes'].includes(dv.toLowerCase()))
      return {
        ...base,
        type: 'switch',
        defaultValue: on ? 1 : 0,
      }
    }
    case 'multiselect': {
      const existing = (current as { options?: PromptVariableOption[] }).options ?? []
      const options = existing.length ? existing : [makeNewOption(0)]
      const validIds = new Set(options.map((o) => o.id))
      const prior = current.defaultValue
      const def = Array.isArray(prior)
        ? prior.filter((id): id is string => typeof id === 'string' && validIds.has(id))
        : typeof prior === 'string' && validIds.has(prior)
        ? [prior]
        : []
      return {
        ...base,
        type: 'multiselect',
        defaultValue: def,
        options,
        separator: (current as { separator?: string }).separator ?? '\n\n',
      }
    }
  }
}

// ============================================================================
// VariablesEditor — accordion + list
// ============================================================================

export function VariablesEditor({
  variables,
  onChange,
  placementBinding,
  fallbackPlacement,
  onPlacementBindingChange,
  moveTargets,
  onMoveToBlock,
}: VariablesEditorProps) {
  const { t } = useTranslation('panels')
  const [expanded, setExpanded] = useState(variables.length > 0)
  const [moveVariable, setMoveVariable] = useState<PromptVariableDef | null>(null)
  const sensors = useSensors(
    useSensor(MouseSensor, { activationConstraint: { distance: 4 } }),
    useSensor(TouchSensor, { activationConstraint: { delay: 200, tolerance: 5 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates }),
  )

  const duplicateNames = useMemo(() => {
    const counts = new Map<string, number>()
    for (const v of variables) {
      const name = v.name?.trim()
      if (!name) continue
      counts.set(name, (counts.get(name) ?? 0) + 1)
    }
    return new Set(
      Array.from(counts.entries())
        .filter(([, n]) => n > 1)
        .map(([name]) => name),
    )
  }, [variables])

  const updateVar = (id: string, patch: Partial<PromptVariableDef>) => {
    onChange(
      variables.map((v) => (v.id === id ? ({ ...v, ...patch } as PromptVariableDef) : v)),
    )
  }

  const changeType = (id: string, nextType: PromptVariableType) => {
    onChange(variables.map((v) => (v.id === id ? coerceVariableType(v, nextType) : v)))
  }

  const removeVar = (id: string) => {
    onChange(variables.filter((v) => v.id !== id))
  }

  const addVar = () => {
    onChange([...variables, makeNewVariable()])
    setExpanded(true)
  }

  const handleDragEnd = useCallback(({ active, over }: DragEndEvent) => {
    const reordered = reorderPromptVariables(
      variables,
      String(active.id),
      over === null ? null : String(over.id),
    )
    if (reordered !== variables) onChange(reordered)
  }, [onChange, variables])

  return (
    <div className={css.root}>
      <div className={css.header}>
        <button
          type="button"
          className={css.headerToggle}
          onClick={() => setExpanded((v) => !v)}
          aria-expanded={expanded}
        >
          {expanded ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
          {t('promptVariablesEditor.title')}
          {variables.length > 0 && (
            <span className={css.headerCount}>({variables.length})</span>
          )}
        </button>
        <button type="button" className={css.addBtn} onClick={addVar}>
          <Plus size={12} /> {t('promptVariablesEditor.addVariable')}
        </button>
      </div>

      <p className={css.hint}>
        {t('promptVariablesEditor.hint', { varName: '{{var::name}}', multiselectName: '{{var::name::ison::keyA,keyB}}' })}
      </p>

      {expanded && (
        variables.length === 0 ? (
          <div className={css.empty}>{t('promptVariablesEditor.empty')}</div>
        ) : (
          <DndContext
            sensors={sensors}
            collisionDetection={closestCenter}
            onDragEnd={handleDragEnd}
          >
            <SortableContext items={variables.map((variable) => variable.id)} strategy={verticalListSortingStrategy}>
              <div className={css.list}>
                {variables.map((v, index) => (
                  <VariableRow
                    key={v.id}
                    variable={v}
                    index={index}
                    total={variables.length}
                    isDuplicate={Boolean(v.name?.trim()) && duplicateNames.has(v.name.trim())}
                    onUpdate={(patch) => updateVar(v.id, patch)}
                    onChangeType={(type) => changeType(v.id, type)}
                    onRemove={() => removeVar(v.id)}
                    canMove={Boolean(moveTargets?.length && onMoveToBlock)}
                    onOpenMovePicker={moveTargets?.length && onMoveToBlock
                      ? () => setMoveVariable(v)
                      : undefined}
                  />
                ))}
              </div>
            </SortableContext>
          </DndContext>
        )
      )}

      <PlacementBindingEditor
        variables={variables}
        binding={placementBinding}
        fallbackPlacement={fallbackPlacement}
        onChange={onPlacementBindingChange}
      />

      {moveVariable && moveTargets && onMoveToBlock && (
        <PromptVariableMoveModal
          variable={moveVariable}
          targets={moveTargets}
          onClose={() => setMoveVariable(null)}
          onMove={(targetBlockId) => {
            onMoveToBlock(moveVariable.id, targetBlockId)
            setMoveVariable(null)
          }}
        />
      )}
    </div>
  )
}

interface PlacementBindingEditorProps {
  variables: PromptVariableDef[]
  binding?: PromptBlockPlacementBinding
  fallbackPlacement: PromptBlockPlacement
  onChange: (binding: PromptBlockPlacementBinding | undefined) => void
}

function clonePlacement(placement: PromptBlockPlacement): PromptBlockPlacement {
  return { role: placement.role, position: placement.position, depth: placement.depth }
}

function buildPlacementBinding(
  variable: Extract<PromptVariableDef, { type: 'select' }>,
  fallbackPlacement: PromptBlockPlacement,
  existing?: PromptBlockPlacementBinding,
): PromptBlockPlacementBinding {
  return {
    variableId: variable.id,
    options: Object.fromEntries(
      variable.options.map((option) => [
        option.id,
        clonePlacement(existing?.options[option.id] ?? fallbackPlacement),
      ]),
    ),
  }
}

/** Creator-side configuration for a select variable that changes this block's placement. */
function PlacementBindingEditor({
  variables,
  binding,
  fallbackPlacement,
  onChange,
}: PlacementBindingEditorProps) {
  const { t } = useTranslation('panels')
  const blockEditor = (key: string) => t(`loomBuilder.blockEditor.${key}`)
  const selectors = variables.filter(
    (variable): variable is Extract<PromptVariableDef, { type: 'select' }> => (
      variable.type === 'select' && variable.name.trim().length > 0
    ),
  )
  const selected = selectors.find((variable) => variable.id === binding?.variableId) ?? null
  const selectorLabel = (variable: PromptVariableDef) => (
    variable.label.trim() || variable.name.trim()
  )

  const enable = () => {
    const selector = selectors[0]
    if (!selector) return
    onChange(buildPlacementBinding(selector, fallbackPlacement))
  }

  const changeSelector = (variableId: string) => {
    const selector = selectors.find((variable) => variable.id === variableId)
    if (!selector) return
    onChange(buildPlacementBinding(selector, fallbackPlacement, binding))
  }

  const updateOption = (optionId: string, patch: Partial<PromptBlockPlacement>) => {
    if (!selected || !binding) return
    const current = binding.options[optionId] ?? fallbackPlacement
    const next = { ...current, ...patch }
    const isAppend = next.role === 'user_append' || next.role === 'assistant_append'
    if (!isAppend && next.position !== 'in_history') next.depth = 0
    onChange({
      ...binding,
      options: { ...binding.options, [optionId]: next },
    })
  }

  return (
    <section className={css.placementBinding}>
      <div className={css.placementHeader}>
        <div>
          <div className={css.placementTitle}>{t('promptVariablesEditor.placementTitle')}</div>
          <p className={css.placementHint}>{t('promptVariablesEditor.placementHint')}</p>
        </div>
        <div className={css.placementEnable}>
          <span>{t('promptVariablesEditor.placementEnabled')}</span>
          <Toggle.Switch checked={!!selected} onChange={(enabled) => (enabled ? enable() : onChange(undefined))} disabled={selectors.length === 0} />
        </div>
      </div>

      {selectors.length === 0 ? (
        <p className={css.placementUnavailable}>{t('promptVariablesEditor.placementUnavailable')}</p>
      ) : selected && binding ? (
        <div className={css.placementBody}>
          <label className={css.field}>
            <span className={css.fieldLabel}>{t('promptVariablesEditor.placementVariable')}</span>
            <select className={css.select} value={selected.id} onChange={(event) => changeSelector(event.target.value)}>
              {selectors.map((variable) => (
                <option key={variable.id} value={variable.id}>
                  {selectorLabel(variable)}
                </option>
              ))}
            </select>
          </label>

          {selected.options.length === 0 ? (
            <p className={css.placementUnavailable}>{t('promptVariablesEditor.placementNoOptions')}</p>
          ) : (
            <div className={css.placementOptions}>
              <div className={css.placementProfilesHeader}>
                <span>{t('promptVariablesEditor.placementProfiles')}</span>
                <span>{t('promptVariablesEditor.placementProfilesHint')}</span>
              </div>
              {selected.options.map((option, index) => {
                const placement = binding.options[option.id] ?? fallbackPlacement
                const showDepth = placement.position === 'in_history' || placement.role === 'user_append' || placement.role === 'assistant_append'
                const roleLabel = blockEditor(`roles.${placement.role}`)
                const positionLabel = blockEditor(`positions.${placement.position}`)
                return (
                  <article key={option.id} className={css.placementOption}>
                    <div className={css.placementOptionHeader}>
                      <div>
                        <span className={css.placementOptionKicker}>{t('promptVariablesEditor.placementOption')}</span>
                        <div className={css.placementOptionName}>{option.label.trim() || option.id || t('promptVariablesEditor.placementOptionFallback', { index: index + 1 })}</div>
                      </div>
                      <span className={css.placementSummary}>
                        {roleLabel} · {positionLabel}{showDepth ? ` · ${blockEditor('depth')} ${placement.depth}` : ''}
                      </span>
                    </div>
                    <div className={css.placementFields}>
                      <label className={css.field}>
                        <span className={css.fieldLabel}>{blockEditor('role')}</span>
                        <select className={css.select} value={placement.role} onChange={(event) => updateOption(option.id, { role: event.target.value as PromptBlockPlacement['role'] })}>
                          <option value="system">{blockEditor('roles.system')}</option>
                          <option value="user">{blockEditor('roles.user')}</option>
                          <option value="assistant">{blockEditor('roles.assistant')}</option>
                          <option value="user_append">{blockEditor('roles.user_append')}</option>
                          <option value="assistant_append">{blockEditor('roles.assistant_append')}</option>
                        </select>
                      </label>
                      <label className={css.field}>
                        <span className={css.fieldLabel}>{blockEditor('position')}</span>
                        <select className={css.select} value={placement.position} onChange={(event) => updateOption(option.id, { position: event.target.value as PromptBlockPlacement['position'] })}>
                          <option value="pre_history">{blockEditor('positions.pre_history')}</option>
                          <option value="post_history">{blockEditor('positions.post_history')}</option>
                          <option value="in_history">{blockEditor('positions.in_history')}</option>
                        </select>
                      </label>
                      {showDepth && (
                      <label className={css.field}>
                        <span className={css.fieldLabel}>{blockEditor('depth')}</span>
                        <NumberStepper value={placement.depth} min={0} onChange={(value) => updateOption(option.id, { depth: value ?? 0 })} />
                      </label>
                      )}
                    </div>
                  </article>
                )
              })}
            </div>
          )}
        </div>
      ) : null}
    </section>
  )
}

// ============================================================================
// VariableRow — single card
// ============================================================================

interface VariableRowProps {
  variable: PromptVariableDef
  index: number
  total: number
  isDuplicate: boolean
  onUpdate: (patch: Partial<PromptVariableDef>) => void
  onChangeType: (type: PromptVariableType) => void
  onRemove: () => void
  canMove?: boolean
  onOpenMovePicker?: () => void
}

function VariableRow({
  variable,
  index,
  total,
  isDuplicate,
  onUpdate,
  onChangeType,
  onRemove,
  canMove,
  onOpenMovePicker,
}: VariableRowProps) {
  const { t } = useTranslation('panels')
  const sortingDisabled = total < 2
  const {
    attributes,
    listeners,
    setNodeRef: setSortableRef,
    setActivatorNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id: variable.id, disabled: sortingDisabled })
  const { setNodeRef, style } = useScaledSortableStyle({
    setNodeRef: setSortableRef,
    transform,
    transition,
    isDragging,
  })
  const handleRef = useRef<HTMLButtonElement>(null)
  const wasDraggingRef = useRef(false)
  useEffect(() => {
    if (wasDraggingRef.current && !isDragging) {
      handleRef.current?.blur()
    }
    wasDraggingRef.current = isDragging
  }, [isDragging])
  const setHandleRef = useCallback((node: HTMLButtonElement | null) => {
    handleRef.current = node
    setActivatorNodeRef(node)
  }, [setActivatorNodeRef])
  const typeOptions = useMemo(
    () =>
      (['text', 'textarea', 'number', 'slider', 'range', 'select', 'switch', 'multiselect'] as const).map((value) => ({
        value,
        label: t(`promptVariablesEditor.types.${value}`),
      })),
    [t],
  )
  const isNumeric = variable.type === 'number' || variable.type === 'slider' || variable.type === 'range'
  const isSlider = variable.type === 'slider'
  const isRange = variable.type === 'range'
  const isSelect = variable.type === 'select'
  const isMultiselect = variable.type === 'multiselect'
  const isSwitch = variable.type === 'switch'

  const sliderMin = isSlider || isRange ? (variable as { min: number }).min : 0
  const sliderMax = isSlider || isRange ? (variable as { max: number }).max : 100
  const sliderStep = isSlider || isRange ? (variable as { step?: number }).step ?? 1 : 1
  const position = index + 1
  const displayName = variable.name.trim() || variable.label.trim() || t('promptVariablesEditor.variableFallback', { position })

  return (
    <div
      ref={setNodeRef}
      style={style}
      className={clsx(css.card, TYPE_ACCENT_CLASS[variable.type], isDragging && css.cardDragging)}
    >
      {/* Row 1: handle · type · name · delete */}
      <div className={css.headerRow}>
        <button
          ref={setHandleRef}
          type="button"
          className={clsx(css.handle, sortingDisabled && css.handleDisabled)}
          aria-label={t('promptVariablesEditor.dragToReorder', { position, name: displayName })}
          title={t('promptVariablesEditor.dragToReorder', { position, name: displayName })}
          {...attributes}
          {...(sortingDisabled ? {} : listeners)}
          aria-disabled={sortingDisabled}
        >
          <GripVertical size={14} />
        </button>

        <div className={clsx(css.field, css.typeField)}>
          <label className={css.fieldLabel}>{t('promptVariablesEditor.type')}</label>
          <select
            className={css.select}
            value={variable.type}
            onChange={(e) => onChangeType(e.target.value as PromptVariableType)}
          >
            {typeOptions.map((opt) => (
              <option key={opt.value} value={opt.value}>
                {opt.label}
              </option>
            ))}
          </select>
        </div>

        <div className={css.nameField}>
          <label className={css.fieldLabel}>{t('promptVariablesEditor.name')}</label>
          <div className={css.nameRow}>
            <input
              className={clsx(css.input, css.inputMono)}
              value={variable.name}
              placeholder={t('promptVariablesEditor.namePlaceholder')}
              spellCheck={false}
              onChange={(e) => onUpdate({ name: e.target.value })}
            />
            {isDuplicate && (
              <span
                className={css.dupChip}
                title={t('promptVariablesEditor.duplicateTitle')}
              >
                <AlertTriangle size={10} />
                {t('promptVariablesEditor.shadowed')}
              </span>
            )}
          </div>
        </div>

        <div className={css.variableActions}>
          {canMove && onOpenMovePicker && (
            <button
              type="button"
              className={css.deleteBtn}
              onClick={(e) => {
                e.stopPropagation()
                onOpenMovePicker()
              }}
              aria-label={t('promptVariablesEditor.moveToBlock')}
              title={t('promptVariablesEditor.moveToBlock')}
            >
              <CornerDownRight size={13} />
            </button>
          )}

          <button
            type="button"
            className={css.deleteBtn}
            onClick={onRemove}
            aria-label={t('promptVariablesEditor.removeVariable')}
            title={t('promptVariablesEditor.removeVariable')}
          >
            <Trash2 size={13} />
          </button>
        </div>
      </div>

      {/* Row 2: label */}
      <div className={clsx(css.field, css.colFull)}>
        <label className={css.fieldLabel}>{t('promptVariablesEditor.label')}</label>
        <input
          className={css.input}
          value={variable.label}
          placeholder={t('promptVariablesEditor.labelPlaceholder')}
          onChange={(e) => onUpdate({ label: e.target.value })}
        />
      </div>

      {/* Row 3: default value — type-specific control.
          For select/multiselect the default is set via the options list below. */}
      {!isSelect && !isMultiselect && (
        <div className={clsx(css.field, isSlider || isRange ? css.colHalf : css.colFull)}>
          <label className={css.fieldLabel}>{t('promptVariablesEditor.default')}</label>
          {variable.type === 'textarea' ? (
            <textarea
              className={css.textarea}
              value={String(variable.defaultValue ?? '')}
              rows={3}
              placeholder={t('promptVariablesEditor.defaultTextareaPlaceholder')}
              onChange={(e) =>
                onUpdate({ defaultValue: e.target.value } as Partial<PromptVariableDef>)
              }
            />
          ) : variable.type === 'text' ? (
            <input
              className={css.input}
              value={String(variable.defaultValue ?? '')}
              placeholder={t('promptVariablesEditor.defaultTextPlaceholder')}
              onChange={(e) =>
                onUpdate({ defaultValue: e.target.value } as Partial<PromptVariableDef>)
              }
            />
          ) : isSwitch ? (
            <div className={css.switchToggleRow}>
              <Toggle.Switch
                checked={(variable as { defaultValue: 0 | 1 }).defaultValue === 1}
                onChange={(next) =>
                  onUpdate({ defaultValue: next ? 1 : 0 } as Partial<PromptVariableDef>)
                }
              />
              <span className={css.switchToggleLabel}>
                {(variable as { defaultValue: 0 | 1 }).defaultValue === 1 ? t('promptVariablesEditor.switchOn') : t('promptVariablesEditor.switchOff')}
              </span>
              <span className={css.switchToggleHint}>
                {t('promptVariablesEditor.switchHint')}
              </span>
            </div>
          ) : isRange ? (
            <div className={css.rangeDefaultRow}>
              <NumberStepper
                value={variable.defaultValue[0]}
                onChange={(next) => {
                  const start = Math.min(next ?? sliderMin, variable.defaultValue[1])
                  onUpdate({ defaultValue: [start, variable.defaultValue[1]] } as Partial<PromptVariableDef>)
                }}
                min={sliderMin}
                max={variable.defaultValue[1]}
                step={sliderStep}
              />
              <span aria-hidden="true">–</span>
              <NumberStepper
                value={variable.defaultValue[1]}
                onChange={(next) => {
                  const end = Math.max(next ?? sliderMax, variable.defaultValue[0])
                  onUpdate({ defaultValue: [variable.defaultValue[0], end] } as Partial<PromptVariableDef>)
                }}
                min={variable.defaultValue[0]}
                max={sliderMax}
                step={sliderStep}
              />
            </div>
          ) : (
            <NumberStepper
              value={
                Number((variable as { defaultValue?: unknown }).defaultValue) || 0
              }
              onChange={(n) =>
                onUpdate({ defaultValue: n ?? 0 } as Partial<PromptVariableDef>)
              }
              min={(variable as { min?: number }).min}
              max={(variable as { max?: number }).max}
              step={(variable as { step?: number }).step ?? 1}
            />
          )}
        </div>
      )}

      {/* Slider-only preview: what end-users will see. Lives beside the
          stepper so the creator can cross-check. */}
      {(isSlider || isRange) && (
        <div className={clsx(css.sliderPreview, css.colHalf)}>
          {isRange ? (
            <DualRangeSlider
              min={sliderMin}
              max={sliderMax}
              step={sliderStep}
              value={variable.defaultValue}
              onCommit={(next) => onUpdate({ defaultValue: next } as Partial<PromptVariableDef>)}
              startLabel={t('promptVariablesEditor.rangeStart')}
              endLabel={t('promptVariablesEditor.rangeEnd')}
            />
          ) : (
            <RangeSlider
              min={sliderMin}
              max={sliderMax}
              step={sliderStep}
              value={typeof variable.defaultValue === 'number' ? variable.defaultValue : sliderMin}
              onCommit={(next) => onUpdate({ defaultValue: next } as Partial<PromptVariableDef>)}
            />
          )}
          <div className={css.sliderPreviewScale}>
            <span>{sliderMin}</span>
            <span>{sliderMax}</span>
          </div>
        </div>
      )}

      {/* Options list — select & multiselect */}
      {(isSelect || isMultiselect) && (
        <OptionsListEditor
          variable={variable as Extract<PromptVariableDef, { type: 'select' | 'multiselect' }>}
          mode={isMultiselect ? 'multiple' : 'single'}
          onUpdate={onUpdate}
        />
      )}

      {/* Multiselect: separator */}
      {isMultiselect && (
        <div className={clsx(css.field, css.colFull)}>
          <label className={css.fieldLabel}>Separator (inserted between selected values)</label>
          <textarea
            className={css.textarea}
            rows={2}
            value={(variable as { separator?: string }).separator ?? '\n\n'}
            placeholder={'Two newlines by default'}
            onChange={(e) =>
              onUpdate({ separator: e.target.value } as Partial<PromptVariableDef>)
            }
          />
        </div>
      )}

      {/* Row 4 (numeric only): min / max / step as equal thirds */}
      {isNumeric && (
        <>
          <div className={clsx(css.field, css.colThird)}>
            <label className={css.fieldLabel}>{t('promptVariablesEditor.min')}</label>
            <NumberStepper
              value={
                typeof (variable as { min?: number }).min === 'number'
                  ? (variable as { min: number }).min
                  : null
              }
              onChange={(n) => {
                if (variable.type === 'range') {
                  const nextMin = Math.min(n ?? 0, variable.max)
                  const start = Math.min(variable.max, Math.max(nextMin, variable.defaultValue[0]))
                  const end = Math.min(variable.max, Math.max(start, variable.defaultValue[1]))
                  onUpdate({ min: nextMin, defaultValue: [start, end] } as Partial<PromptVariableDef>)
                  return
                }
                if (variable.type === 'slider') {
                  const nextMin = Math.min(n ?? 0, variable.max)
                  const clamped = Math.min(variable.max, Math.max(nextMin, variable.defaultValue))
                  onUpdate({ min: nextMin, defaultValue: clamped } as Partial<PromptVariableDef>)
                  return
                }
                onUpdate({ min: n ?? undefined } as Partial<PromptVariableDef>)
              }}
              allowEmpty={variable.type === 'number'}
            />
          </div>
          <div className={clsx(css.field, css.colThird)}>
            <label className={css.fieldLabel}>{t('promptVariablesEditor.max')}</label>
            <NumberStepper
              value={
                typeof (variable as { max?: number }).max === 'number'
                  ? (variable as { max: number }).max
                  : null
              }
              onChange={(n) => {
                if (variable.type === 'range') {
                  const nextMax = Math.max(n ?? 100, variable.min)
                  const end = Math.max(variable.min, Math.min(nextMax, variable.defaultValue[1]))
                  const start = Math.max(variable.min, Math.min(end, variable.defaultValue[0]))
                  onUpdate({ max: nextMax, defaultValue: [start, end] } as Partial<PromptVariableDef>)
                  return
                }
                if (variable.type === 'slider') {
                  const nextMax = Math.max(n ?? 100, variable.min)
                  const clamped = Math.max(variable.min, Math.min(nextMax, variable.defaultValue))
                  onUpdate({ max: nextMax, defaultValue: clamped } as Partial<PromptVariableDef>)
                  return
                }
                onUpdate({ max: n ?? undefined } as Partial<PromptVariableDef>)
              }}
              allowEmpty={variable.type === 'number'}
            />
          </div>
          <div className={clsx(css.field, css.colThird)}>
            <label className={css.fieldLabel}>{t('promptVariablesEditor.step')}</label>
            <NumberStepper
              value={
                typeof (variable as { step?: number }).step === 'number'
                  ? (variable as { step: number }).step
                  : 1
              }
              onChange={(n) =>
                onUpdate({ step: n ?? 1 } as Partial<PromptVariableDef>)
              }
              min={0}
            />
          </div>
        </>
      )}

      {/* Row 5: description — always last, soft hint copy */}
      <div className={clsx(css.field, css.colFull)}>
        <label className={css.fieldLabel}>{t('promptVariablesEditor.descriptionOptional')}</label>
        <input
          className={css.input}
          value={variable.description ?? ''}
          placeholder={t('promptVariablesEditor.descriptionPlaceholder')}
          onChange={(e) => onUpdate({ description: e.target.value || undefined })}
        />
      </div>
    </div>
  )
}

// ============================================================================
// OptionsListEditor — used by select + multiselect
// ============================================================================

interface OptionsListEditorProps {
  variable: Extract<PromptVariableDef, { type: 'select' | 'multiselect' }>
  mode: 'single' | 'multiple'
  onUpdate: (patch: Partial<PromptVariableDef>) => void
}

function OptionsListEditor({ variable, mode, onUpdate }: OptionsListEditorProps) {
  const options = variable.options ?? []
  const selectedIds = useMemo(() => {
    if (variable.type === 'multiselect') {
      return new Set(Array.isArray(variable.defaultValue) ? variable.defaultValue : [])
    }
    return new Set(typeof variable.defaultValue === 'string' ? [variable.defaultValue] : [])
  }, [variable])

  const patchOptions = (next: PromptVariableOption[]) => {
    if (variable.type === 'multiselect') {
      const validIds = new Set(next.map((o) => o.id))
      const filtered = (Array.isArray(variable.defaultValue) ? variable.defaultValue : []).filter(
        (id) => validIds.has(id),
      )
      onUpdate({ options: next, defaultValue: filtered } as Partial<PromptVariableDef>)
      return
    }
    // single-select: keep the previous default if still present; otherwise first option
    const validIds = new Set(next.map((o) => o.id))
    const currentDefault =
      typeof variable.defaultValue === 'string' && validIds.has(variable.defaultValue)
        ? variable.defaultValue
        : next[0]?.id ?? ''
    onUpdate({ options: next, defaultValue: currentDefault } as Partial<PromptVariableDef>)
  }

  const updateOption = (id: string, patch: Partial<PromptVariableOption>) => {
    patchOptions(options.map((o) => (o.id === id ? { ...o, ...patch } : o)))
  }

  const removeOption = (id: string) => {
    patchOptions(options.filter((o) => o.id !== id))
  }

  const addOption = () => {
    patchOptions([...options, makeNewOption(options.length)])
  }

  const setDefault = (id: string, checked: boolean) => {
    if (mode === 'single') {
      onUpdate({ defaultValue: id } as Partial<PromptVariableDef>)
      return
    }
    const prior = new Set(Array.isArray(variable.defaultValue) ? variable.defaultValue : [])
    if (checked) prior.add(id)
    else prior.delete(id)
    // Preserve declaration order so the persisted default matches option order.
    const ordered = options.filter((o) => prior.has(o.id)).map((o) => o.id)
    onUpdate({ defaultValue: ordered } as Partial<PromptVariableDef>)
  }

  return (
    <div className={css.optionsList}>
      <div className={css.optionsListHeader}>
        <span>
          Options{' '}
          <span style={{ fontWeight: 400, textTransform: 'none', letterSpacing: 0 }}>
            ({mode === 'single' ? 'pick one default' : 'pick the default selection'})
          </span>
        </span>
        <button type="button" className={css.optionAddBtn} onClick={addOption}>
          <Plus size={11} /> Add option
        </button>
      </div>

      {options.length === 0 ? (
        <div className={css.optionsEmpty}>No options yet — add one to give end users a choice.</div>
      ) : (
        options.map((opt) => (
          <div key={opt.id} className={css.optionRow}>
            <div className={css.optionDefaultCell}>
              <input
                type={mode === 'single' ? 'radio' : 'checkbox'}
                className={css.optionDefaultInput}
                name={mode === 'single' ? `default-${variable.id}` : undefined}
                checked={selectedIds.has(opt.id)}
                onChange={(e) => setDefault(opt.id, e.target.checked)}
                aria-label="Use as default"
                title="Use as default"
              />
            </div>
            <input
              className={css.optionLabelInput}
              value={opt.label}
              placeholder="Label shown to user"
              onChange={(e) => updateOption(opt.id, { label: e.target.value })}
            />
            <textarea
              className={css.optionValueInput}
              value={opt.value}
              rows={1}
              placeholder="Value substituted into the prompt"
              onChange={(e) => updateOption(opt.id, { value: e.target.value })}
            />
            <button
              type="button"
              className={css.optionDelete}
              onClick={() => removeOption(opt.id)}
              aria-label="Remove option"
              title="Remove option"
            >
              <Trash2 size={12} />
            </button>
          </div>
        ))
      )}
    </div>
  )
}

.panel {
  display: flex;
  flex-direction: column;
  gap: 8px;
  height: 100%;
}

.topBar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--lumiverse-border);
}

.topBarTitle {
  font-size: calc(14px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
}

.topBarActions {
  display: flex;
  gap: 4px;
}

.bulkModeButtonActive {
  color: var(--lumiverse-primary) !important;
  background: color-mix(in srgb, var(--lumiverse-primary) 12%, transparent) !important;
}


.scopeFilter {
  display: flex;
  gap: 4px;
}

.scopePill {
  padding: 4px 10px;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  border-radius: 12px;
  border: 1px solid var(--lumiverse-border);
  background: transparent;
  color: var(--lumiverse-text-dim);
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
}

.scopePill:hover {
  background: var(--lumiverse-surface-hover);
}

.scopePillActive {
  background: var(--lumiverse-primary);
  color: var(--lumiverse-primary-fg, #fff);
  border-color: var(--lumiverse-primary);
}

/* ── Bulk selection ───────────────────────────────── */

.bulkBar {
  display: flex;
  flex-direction: column;
  gap: 7px;
  padding: 8px;
  border: 1px solid color-mix(in srgb, var(--lumiverse-primary) 35%, var(--lumiverse-border));
  border-radius: 8px;
  background: color-mix(in srgb, var(--lumiverse-primary) 6%, var(--lumiverse-surface));
}

.bulkSummary {
  display: flex;
  align-items: center;
  gap: 8px;
}

.bulkSelectAll {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 0;
  border: none;
  background: transparent;
  color: var(--lumiverse-primary);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
}

.bulkCount {
  margin-left: auto;
  color: var(--lumiverse-text-dim);
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
}

.bulkActions {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 5px;
}

.bulkActionBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  min-width: 0;
  padding: 5px 6px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 6px;
  background: var(--lumiverse-bg);
  color: var(--lumiverse-text-dim);
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
  transition: background var(--lumiverse-transition-fast), color var(--lumiverse-transition-fast), border-color var(--lumiverse-transition-fast);
}

.bulkActionBtn:hover:not(:disabled) {
  color: var(--lumiverse-text);
  border-color: var(--lumiverse-primary);
  background: var(--lumiverse-surface-hover);
}

.bulkDeleteBtn:hover:not(:disabled) {
  color: var(--lumiverse-danger, #ef4444);
  border-color: color-mix(in srgb, var(--lumiverse-danger, #ef4444) 55%, var(--lumiverse-border));
}

.bulkSelectAll:disabled,
.bulkActionBtn:disabled {
  opacity: 0.45;
  cursor: default;
}

.scriptList {
  flex: 1;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.folderTools {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 6px 10px;
}

.folderSearchEmpty {
  margin: 0;
  color: var(--lumiverse-text-dim);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
}

.scriptRow {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  border-radius: 8px;
  cursor: pointer;
  transition: background var(--lumiverse-transition-fast);
}

.scriptRow:hover {
  background: var(--lumiverse-surface-hover);
}

.scriptRowSlow {
  background: color-mix(in srgb, var(--lumiverse-warning, #f59e0b) 10%, transparent);
  border: 1px solid color-mix(in srgb, var(--lumiverse-warning, #f59e0b) 35%, transparent);
}

.scriptRowSelected,
.scriptRowSelected:hover {
  background: color-mix(in srgb, var(--lumiverse-primary) 12%, var(--lumiverse-surface));
}

.scriptRowExpanded {
  background: var(--lumiverse-surface);
  border: 1px solid var(--lumiverse-border);
  border-bottom: none;
  border-radius: 8px 8px 0 0;
}

.scriptName {
  flex: 1;
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  min-width: 0;
}

.scriptNameDisabled {
  opacity: 0.5;
}

.deleteBtn {
  opacity: 0;
  transition: opacity var(--lumiverse-transition-fast);
}

.slowBadge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 6px;
  border-radius: 999px;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-warning, #f59e0b);
  background: color-mix(in srgb, var(--lumiverse-warning, #f59e0b) 12%, transparent);
  border: 1px solid color-mix(in srgb, var(--lumiverse-warning, #f59e0b) 30%, transparent);
}

.scriptRow:hover .deleteBtn {
  opacity: 1;
}

/* Touch-only devices have no hover, so reveal the row actions (bind/delete)
   permanently. `any-hover: none` matches only when NO input device supports
   hover (true phones/tablets), avoiding false matches on Windows touchscreen
   laptops where `hover: none` misfires in Firefox/Edge. */
@media (any-hover: none) {
  .deleteBtn {
    opacity: 1;
  }
}

/* ── Drag handle ─────────────────────────────────── */

.selectionBtn {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  margin: -3px -1px -3px -3px;
  padding: 0;
  border: none;
  border-radius: 4px;
  background: transparent;
  color: var(--lumiverse-primary);
  cursor: pointer;
}

.selectionBtn:hover {
  background: color-mix(in srgb, var(--lumiverse-primary) 12%, transparent);
}

.dragHandle {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  margin: -4px -2px -4px -4px;
  padding: 4px 2px;
  border: none;
  background: transparent;
  color: var(--lumiverse-text-dim);
  /* Always faintly visible so it's discoverable on touch devices (no hover). */
  opacity: 0.4;
  cursor: grab;
  border-radius: 4px;
  /* Prevent the browser from treating a drag on the grip as a scroll/pan. */
  touch-action: none;
  transition: opacity var(--lumiverse-transition-fast), color var(--lumiverse-transition-fast);
}

.dragHandle:active {
  cursor: grabbing;
}

.scriptRow:hover .dragHandle {
  opacity: 0.85;
}

.dragHandle:hover {
  opacity: 1;
  color: var(--lumiverse-text);
}

/* ── Inline Editor ─────────────────────────────────── */

.inlineEditor {
  padding: 10px 12px 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  background: var(--lumiverse-surface);
  border: 1px solid var(--lumiverse-border);
  border-top: none;
  border-radius: 0 0 8px 8px;
  margin-bottom: 4px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.warningBox {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 8px 10px;
  border-radius: 8px;
  color: var(--lumiverse-warning, #f59e0b);
  background: color-mix(in srgb, var(--lumiverse-warning, #f59e0b) 10%, transparent);
  border: 1px solid color-mix(in srgb, var(--lumiverse-warning, #f59e0b) 25%, transparent);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
}

/* Keeps a recovery action (e.g. clearing a quarantine) pinned to the trailing
   edge of a warning box so the explanatory text keeps the remaining width. */
.warningBoxAction {
  margin-left: auto;
  flex-shrink: 0;
}

.fieldRow {
  display: flex;
  gap: 16px;
}

.fieldRow .field {
  flex: 1;
  min-width: 0;
}

.fieldLabel {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  font-weight: 500;
  display: flex;
  align-items: baseline;
  gap: 6px;
}

.fieldHint {
  font-weight: 400;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  opacity: 0.7;
}

.fieldInput {
  padding: 6px 8px;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  border-radius: 6px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-bg);
  color: var(--lumiverse-text);
  outline: none;
  transition: border-color var(--lumiverse-transition-fast);
}

.fieldInput:focus {
  border-color: var(--lumiverse-primary);
}

.fieldTextarea {
  padding: 6px 8px;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-family: var(--lumiverse-mono, monospace);
  border-radius: 6px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-bg);
  color: var(--lumiverse-text);
  outline: none;
  resize: vertical;
  min-height: 40px;
  transition: border-color var(--lumiverse-transition-fast);
}

.fieldTextarea:focus {
  border-color: var(--lumiverse-primary);
}

/* ── Token bar for replace field ─────────────────── */

.tokenBar {
  display: flex;
  gap: 3px;
  flex-wrap: wrap;
  align-items: center;
}

.tokenChip {
  padding: 2px 7px;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-family: var(--lumiverse-mono, monospace);
  border-radius: 4px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-bg);
  color: var(--lumiverse-text-dim);
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
  line-height: 1.4;
}

.tokenChip:hover {
  background: var(--lumiverse-primary);
  color: var(--lumiverse-primary-fg, #fff);
  border-color: var(--lumiverse-primary);
}

.tokenChipHtml {
  color: var(--lumiverse-info, #6366f1);
  border-color: color-mix(in srgb, var(--lumiverse-info, #6366f1) 40%, transparent);
}

.tokenDivider {
  width: 1px;
  height: 14px;
  background: var(--lumiverse-border);
  margin: 0 2px;
}

.flagsRow {
  display: grid;
  grid-template-columns: repeat(4, max-content);
  gap: 4px 8px;
  align-items: center;
}

.flagCheck {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  cursor: pointer;
}

.flagCheck input {
  accent-color: var(--lumiverse-primary);
}

.placementRow {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.editModalLink {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-primary);
  cursor: pointer;
  align-self: flex-end;
  background: none;
  border: none;
  padding: 0;
}

.editModalLink:hover {
  text-decoration: underline;
}

.emptyState {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 40px 20px;
  color: var(--lumiverse-text-dim);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  text-align: center;
}

/* ── Folder Headers ──────────────────────────────── */

.folderHeader {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  padding: 6px 10px;
  margin-top: 4px;
  border: none;
  background: transparent;
  cursor: pointer;
  border-radius: 6px;
  transition: background var(--lumiverse-transition-fast);
  -webkit-touch-callout: none;
  user-select: none;
}

.folderHeader:hover {
  background: var(--lumiverse-surface-hover);
}

/* Highlight a folder header while a dragged regex hovers over it. */
.folderHeaderDropTarget {
  background: color-mix(in srgb, var(--lumiverse-primary) 16%, transparent);
  box-shadow: inset 0 0 0 1px var(--lumiverse-primary);
}

.folderChevron {
  color: var(--lumiverse-text-dim);
  flex-shrink: 0;
  transition: transform var(--lumiverse-transition-fast);
}

.folderChevronOpen {
  transform: rotate(90deg);
}

.folderName {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  color: var(--lumiverse-text-dim);
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.folderRename {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 1;
  min-width: 0;
}

.folderRenameInput {
  flex: 1;
  min-width: 0;
  padding: 3px 6px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 4px;
  background: var(--lumiverse-bg);
  color: var(--lumiverse-text);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  user-select: text;
}

.folderRenameBtn {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 3px;
  border: none;
  border-radius: 4px;
  background: transparent;
  color: var(--lumiverse-text-dim);
  cursor: pointer;
}

.folderRenameBtn:hover:not(:disabled) {
  color: var(--lumiverse-text);
  background: var(--lumiverse-surface-hover);
}

.folderRenameBtn:disabled {
  opacity: 0.45;
  cursor: default;
}

.folderVersionBadge {
  display: inline-flex;
  flex-shrink: 0;
  text-transform: none;
  letter-spacing: normal;
}

.folderCount {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  padding: 0 5px;
  border-radius: 8px;
  background: var(--lumiverse-surface);
  color: var(--lumiverse-text-dim);
}

.folderActions {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 4px;
}

.folderActionBtn {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 3px;
  border: none;
  background: transparent;
  color: var(--lumiverse-text-dim);
  cursor: pointer;
  border-radius: 4px;
  opacity: 0;
  transition: opacity var(--lumiverse-transition-fast), color var(--lumiverse-transition-fast), background var(--lumiverse-transition-fast);
}

.folderHeader:hover .folderActionBtn {
  opacity: 1;
}

/* Touch-only devices have no hover, so reveal the folder actions permanently
   (see note on .deleteBtn above for why `any-hover`). */
@media (any-hover: none) {
  .folderActionBtn {
    opacity: 1;
  }
}

@media (max-width: 480px) {
  .folderVersionBadge :global(span) {
    padding-inline: 4px;
    font-size: calc(9px * var(--lumiverse-font-scale, 1));
  }
}

.folderActionBtn:hover {
  color: var(--lumiverse-text);
  background: var(--lumiverse-surface-hover);
}

.folderDeleteBtn:hover {
  color: var(--lumiverse-danger, #ef4444);
}

.folderToggleActive {
  color: var(--lumiverse-success, #22c55e);
}

.folderToggleActive:hover {
  color: var(--lumiverse-success, #22c55e);
  background: color-mix(in srgb, var(--lumiverse-success, #22c55e) 12%, transparent);
}

/* ── Create Popover ──────────────────────────────── */

.createPopoverWrapper {
  position: relative;
}

.createPopover {
  position: absolute;
  top: calc(100% + 4px);
  right: 0;
  width: 160px;
  background: var(--lumiverse-bg);
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3);
  z-index: 50;
  padding: 4px;
}

.createPopoverOption {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  padding: 7px 10px;
  border: none;
  background: transparent;
  color: var(--lumiverse-text);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
  border-radius: 6px;
  text-align: left;
  transition: background var(--lumiverse-transition-fast);
}

.createPopoverOption:hover {
  background: var(--lumiverse-surface-hover);
}

.createPopoverFolder {
  border-top: 1px solid var(--lumiverse-border);
  border-radius: 0 0 6px 6px;
}

.createPopoverInput {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 4px 6px;
}

.createPopoverField {
  flex: 1;
  min-width: 0;
  padding: 4px 6px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 4px;
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  outline: none;
}

.createPopoverField:focus {
  border-color: var(--lumiverse-primary);
}

.createPopoverBtn {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 3px;
  border: none;
  background: transparent;
  color: var(--lumiverse-text-muted);
  cursor: pointer;
  border-radius: 3px;
}

.createPopoverBtn:hover {
  color: var(--lumiverse-text);
  background: var(--lumiverse-fill-subtle);
}

.createPopoverBtn:disabled {
  opacity: 0.4;
  cursor: default;
}

