.panel {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 4px 0;
}

.installRow {
  display: flex;
  gap: 8px;
}

.addMenuWrap {
  position: relative;
}

.installInput {
  flex: 1;
  padding: 8px 12px;
  border-radius: var(--lumiverse-radius);
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  outline: none;
  transition: border-color var(--lumiverse-transition-fast);
}

.installInput:focus {
  border-color: var(--lumiverse-primary);
}

.installInput::placeholder {
  color: var(--lumiverse-text-dim);
}

.installBtn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  border-radius: var(--lumiverse-radius);
  background: var(--lumiverse-primary);
  border: none;
  color: var(--lumiverse-primary-contrast, #fff);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  cursor: pointer;
  white-space: nowrap;
  transition: opacity var(--lumiverse-transition-fast);
}

.addMenu {
  position: fixed;
  max-width: calc(calc(100vw / var(--lumiverse-ui-scale, 1)) - 24px);
  padding: 10px;
  border-radius: 10px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-bg);
  box-shadow: var(--lumiverse-shadow-lg);
  display: flex;
  flex-direction: column;
  gap: 8px;
  z-index: 11000;
}

.menuActionBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  width: 100%;
  min-width: 0;
  padding: 8px 10px;
  border-radius: var(--lumiverse-radius);
  background: var(--lumiverse-primary);
  border: none;
  color: var(--lumiverse-primary-contrast, #fff);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  cursor: pointer;
}

.menuActionBtn svg {
  flex-shrink: 0;
}

.menuActionBtn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.menuDivider {
  height: 1px;
  background: var(--lumiverse-border);
}

.menuLabel {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--lumiverse-text-dim);
}

.installBtn:hover {
  opacity: 0.9;
}

.installBtn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.sectionLabel {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--lumiverse-text-dim);
}

.listHeaderRow {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
}

.listHeaderActions {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  flex: 0 0 auto;
  gap: 8px;
  margin-left: auto;
}

.updateAllBtn {
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
  gap: 6px;
  padding: 5px 10px;
  border-radius: var(--lumiverse-radius);
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text-muted);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
  white-space: nowrap;
}

.updateAllBtn:hover:not(:disabled) {
  color: var(--lumiverse-text);
  border-color: var(--lumiverse-border-hover);
  background: var(--lumiverse-fill);
}

.updateAllBtn:disabled {
  cursor: wait;
  color: var(--lumiverse-primary);
  border-color: var(--lumiverse-primary-020);
  background: var(--lumiverse-primary-010);
  opacity: 1;
}

.importSummary {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
}

.extensionList {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.statusFilters {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.statusFilterBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 34px;
  padding: 6px 12px;
  border: 1px solid var(--lumiverse-border);
  border-radius: var(--lumiverse-radius);
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text-muted);
  font: inherit;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  cursor: pointer;
  transition: background var(--lumiverse-transition-fast), color var(--lumiverse-transition-fast), border-color var(--lumiverse-transition-fast);
}

.statusFilterBtn:hover {
  background: var(--lumiverse-fill-hover);
  color: var(--lumiverse-text);
}

.statusFilterBtnActive,
.statusFilterBtnActive:hover {
  background: var(--lumiverse-primary-010);
  border-color: var(--lumiverse-primary-020);
  color: var(--lumiverse-primary);
}

.statusFilterBtn:focus-visible,
.showAllBtn:focus-visible {
  outline: 2px solid var(--lumiverse-primary);
  outline-offset: 2px;
}

.statusFilterCount {
  font-variant-numeric: tabular-nums;
  opacity: 0.75;
}

.statusFilterHint {
  flex-basis: 100%;
  color: var(--lumiverse-text-dim);
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
}

.showAllBtn {
  display: block;
  margin: 12px auto 0;
  padding: 6px 12px;
  border: 1px solid var(--lumiverse-border);
  border-radius: var(--lumiverse-radius);
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-primary);
  font: inherit;
  cursor: pointer;
}

.showAllBtn:hover {
  background: var(--lumiverse-fill-hover);
}

.extensionCard {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 12px;
  border-radius: var(--lumiverse-radius);
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
  container-type: inline-size;
  container-name: extCard;
}

.extensionHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.extensionInfo {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.extensionName {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: calc(14px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
}

.extensionMeta {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
}

.extensionDesc {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
  line-height: 1.4;
}

.extensionActions {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}

.updateNotificationBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  padding: 0;
  border-radius: 999px;
  border: 1px solid var(--lumiverse-border);
  background: transparent;
  color: var(--lumiverse-text-dim);
  cursor: pointer;
  transition:
    color var(--lumiverse-transition-fast),
    border-color var(--lumiverse-transition-fast),
    background var(--lumiverse-transition-fast);
}

.updateNotificationBtn:hover {
  color: var(--lumiverse-text);
  border-color: var(--lumiverse-border-hover);
  background: var(--lumiverse-fill-hover);
}

.updateNotificationBtnActive {
  color: var(--lumiverse-primary);
  border-color: var(--lumiverse-primary-020);
  background: var(--lumiverse-primary-010);
}

.updateIconWrap {
  position: relative;
  display: inline-flex;
  flex: 0 0 auto;
  overflow: visible !important;
}

.updateDot {
  position: absolute;
  top: -2px;
  right: -3px;
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: var(--lumiverse-warning);
  pointer-events: none;
}

.githubLink {
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--lumiverse-btn-icon);
  height: var(--lumiverse-btn-icon);
  border-radius: var(--lumiverse-radius);
  color: var(--lumiverse-text-muted);
  transition: color var(--lumiverse-transition-fast);
}

.githubLink:hover {
  color: var(--lumiverse-text);
}

.toggleBtn {
  position: relative;
  width: 36px;
  height: 20px;
  border-radius: 10px;
  border: none;
  cursor: pointer;
  transition: background var(--lumiverse-transition-fast);
  flex-shrink: 0;
}

.toggleBtn::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: white;
  transition: transform var(--lumiverse-transition-fast);
}

.toggleOn {
  background: var(--lumiverse-primary);
}

.toggleOn::after {
  transform: translateX(16px);
}

.toggleOff {
  background: var(--lumiverse-fill-hover);
}

.statusDot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
  background: var(--lumiverse-text-dim);
}

.statusRunning {
  background: var(--lumiverse-success);
}

.statusStopped {
  background: var(--lumiverse-text-dim);
}

.statusError {
  background: var(--lumiverse-danger);
}

.permissions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.permissionsBlock {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.permissionsHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
}

.permissionsLabel {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--lumiverse-text-dim);
}

.enableAllBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 28px;
  padding: 4px 10px;
  border-radius: 999px;
  background: transparent;
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text-muted);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  cursor: pointer;
  transition:
    background var(--lumiverse-transition-fast),
    color var(--lumiverse-transition-fast),
    border-color var(--lumiverse-transition-fast);
}

.enableAllBtn:hover:not(:disabled) {
  background: var(--lumiverse-fill-hover);
  color: var(--lumiverse-text);
  border-color: var(--lumiverse-border-hover);
}

.enableAllBtn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.permPill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 5px 11px;
  border-radius: 999px;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  letter-spacing: 0.01em;
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
  border: 1px solid var(--lumiverse-border);
}

.permPillActive {
  background: var(--lumiverse-primary-015);
  color: var(--lumiverse-primary);
  border-color: var(--lumiverse-primary-020);
}

.permPillInactive {
  background: var(--lumiverse-fill);
  color: var(--lumiverse-text-dim);
  border-color: var(--lumiverse-border);
}

.permPill:hover {
  transform: translateY(-1px);
}

.permPillInactive:hover {
  color: var(--lumiverse-text);
  border-color: var(--lumiverse-border-hover);
}

.emptyState {
  text-align: center;
  padding: 32px 16px;
  color: var(--lumiverse-text-dim);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
}

.installError {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-danger);
  padding: 4px 0;
}

/* ─── Branch badge on extension cards ─── */
.branchBadge {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  margin-left: 6px;
  padding: 1px 7px;
  border-radius: 999px;
  background: var(--lumiverse-primary-015);
  color: var(--lumiverse-primary);
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  vertical-align: middle;
}

/* ─── Branch switch dropdown ─── */
.branchMenu {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 6px;
  border-radius: var(--lumiverse-radius);
  background: var(--lumiverse-fill);
  border: 1px solid var(--lumiverse-border);
}

.branchMenuLoading {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  padding: 6px 8px;
}

.branchMenuItem {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  border-radius: var(--lumiverse-radius);
  background: transparent;
  border: none;
  color: var(--lumiverse-text-muted);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
  text-align: left;
}

.branchMenuItem:hover:not(:disabled) {
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text);
}

.branchMenuItemCurrent {
  color: var(--lumiverse-primary);
  font-weight: 600;
  cursor: default;
}

.branchCurrentLabel {
  margin-left: auto;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  color: var(--lumiverse-text-dim);
}

.actionBtnActive {
  background: var(--lumiverse-primary-015);
  color: var(--lumiverse-primary);
  border-color: var(--lumiverse-primary-020);
}

/* ─── Branch select in install menu ─── */
.branchSelect {
  display: flex;
  align-items: center;
  gap: 8px;
}

.branchSelectLabel {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text-dim);
  white-space: nowrap;
}

.branchSelectInput {
  flex: 1;
  padding: 6px 10px;
  border-radius: var(--lumiverse-radius);
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  outline: none;
}

.branchSelectInput:focus {
  border-color: var(--lumiverse-primary);
}

.branchFetchHint {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
}

/* ─── Operation status indicator ─── */
.operationStatus {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 10px;
  border-radius: var(--lumiverse-radius);
  background: var(--lumiverse-primary-010);
  color: var(--lumiverse-primary);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
}

/* ─── Permission pill toggling state ─── */
.permPillToggling {
  opacity: 0.65;
  cursor: wait;
}

/* ─── Action row: labeled primaries + small secondary icons ─── */
.actionRow {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 2px;
}

.primaryActions {
  flex: 1 1 auto;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
  min-width: 0;
}

@container extCard (min-width: 440px) {
  .primaryActions {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

.labeledBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-width: 0;
  padding: 0 10px;
  height: 32px;
  border-radius: var(--lumiverse-radius);
  background: transparent;
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text-muted);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  font-family: inherit;
  letter-spacing: 0.005em;
  cursor: pointer;
  white-space: nowrap;
  overflow: hidden;
  transition:
    background var(--lumiverse-transition-fast),
    color var(--lumiverse-transition-fast),
    border-color var(--lumiverse-transition-fast),
    transform var(--lumiverse-transition-fast);
}

.labeledBtn > svg {
  flex-shrink: 0;
}

.labeledBtn > span {
  overflow: hidden;
  text-overflow: ellipsis;
  min-width: 0;
}

.labeledBtn:hover:not(:disabled) {
  background: var(--lumiverse-fill-hover);
  color: var(--lumiverse-text);
  border-color: var(--lumiverse-border-hover);
}

.updateAvailableBtn,
.updateAvailableBtn:hover:not(:disabled) {
  background: var(--lumiverse-warning-015);
  color: var(--lumiverse-warning);
  border-color: var(--lumiverse-warning-050);
}

.labeledBtn:active:not(:disabled) {
  transform: translateY(1px);
}

.labeledBtn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.labeledBtnActive,
.labeledBtnActive:hover:not(:disabled) {
  background: var(--lumiverse-primary-015);
  color: var(--lumiverse-primary);
  border-color: var(--lumiverse-primary-020);
}

.secondaryActions {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding-left: 4px;
  position: relative;
}

.secondaryActions::before {
  content: '';
  position: absolute;
  left: -2px;
  top: 6px;
  bottom: 6px;
  width: 1px;
  background: var(--lumiverse-border);
  opacity: 0.7;
}

.iconBtnSmall {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  padding: 0;
  border-radius: 6px;
  background: transparent;
  border: none;
  color: var(--lumiverse-text-dim);
  cursor: pointer;
  text-decoration: none;
  font-family: inherit;
  transition:
    background var(--lumiverse-transition-fast),
    color var(--lumiverse-transition-fast);
}

.iconBtnSmall:hover:not(:disabled) {
  color: var(--lumiverse-text);
  background: var(--lumiverse-fill-hover);
}

.iconBtnSmall:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.iconBtnDanger:hover:not(:disabled) {
  color: var(--lumiverse-danger);
  background: var(--lumiverse-danger-015);
}

/* ─── Extension manager organization / density pass ─── */
.managementToolbar {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 8px;
}

.toolbarPrimaryRow {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: stretch;
  gap: 8px;
}

.toolbarPrimaryRow .addMenuWrap {
  display: flex;
  align-items: stretch;
}

.toolbarPrimaryRow .installBtn {
  min-height: 34px;
}

.searchField {
  width: 100%;
  min-width: 0;
  min-height: 34px;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 0 9px;
  border-radius: var(--lumiverse-radius);
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text-dim);
  transition: border-color var(--lumiverse-transition-fast), background var(--lumiverse-transition-fast);
}

.searchField:focus-within {
  border-color: var(--lumiverse-primary);
  background: var(--lumiverse-fill);
}

.searchField input {
  flex: 1;
  min-width: 0;
  padding: 7px 0;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--lumiverse-text);
  font: inherit;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
}

.searchField input::placeholder {
  color: var(--lumiverse-text-dim);
}

.searchField input::-webkit-search-cancel-button {
  display: none;
}

.searchClearBtn {
  width: 24px;
  height: 24px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: var(--lumiverse-text-dim);
  cursor: pointer;
}

.searchClearBtn:hover {
  background: var(--lumiverse-fill-hover);
  color: var(--lumiverse-text);
}

.toolbarActions {
  width: 100%;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  align-items: stretch;
  gap: 7px;
}

.viewToggle {
  width: 100%;
  display: inline-flex;
  align-items: center;
  padding: 2px;
  border: 1px solid var(--lumiverse-border);
  border-radius: var(--lumiverse-radius);
  background: var(--lumiverse-fill-subtle);
}

.viewToggleBtn {
  flex: 1 1 0;
  min-width: 0;
  min-height: 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 4px 8px;
  border: 0;
  border-radius: calc(var(--lumiverse-radius) - 2px);
  background: transparent;
  color: var(--lumiverse-text-dim);
  font-family: inherit;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  cursor: pointer;
  transition: background var(--lumiverse-transition-fast), color var(--lumiverse-transition-fast);
}

.viewToggleBtn:hover {
  color: var(--lumiverse-text);
}

.viewToggleBtnActive {
  background: var(--lumiverse-fill-hover);
  color: var(--lumiverse-primary);
}

.sortField {
  width: 100%;
  min-width: 0;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 34px;
  padding: 0 7px 0 9px;
  border: 1px solid var(--lumiverse-border);
  border-radius: var(--lumiverse-radius);
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text-dim);
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.sortField select {
  flex: 1 1 auto;
  min-width: 0;
  max-width: none;
  padding: 4px 22px 4px 5px;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--lumiverse-text);
  font-family: inherit;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  text-transform: none;
  letter-spacing: normal;
  cursor: pointer;
}

.sortField select option {
  background: var(--lumiverse-bg);
  color: var(--lumiverse-text);
}

.listHeaderMeta {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  margin-left: auto;
  color: var(--lumiverse-text-dim);
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
}

.extensionCard {
  position: relative;
}

.extensionCardManual {
  padding-left: 40px;
}

.dragHandle {
  position: absolute;
  left: 8px;
  top: 9px;
  width: 24px;
  height: 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: var(--lumiverse-text-dim);
  cursor: grab;
  touch-action: none;
  transition: background var(--lumiverse-transition-fast), color var(--lumiverse-transition-fast);
}

.dragHandle:hover {
  background: var(--lumiverse-fill-hover);
  color: var(--lumiverse-text);
}

.dragHandle:active {
  cursor: grabbing;
}

.extensionCardDragging {
  z-index: 5;
  box-shadow: var(--lumiverse-shadow-lg);
  border-color: var(--lumiverse-primary-020);
}

.extensionCardList {
  gap: 6px;
  padding: 8px 10px;
}

.extensionCardList.extensionCardManual {
  padding-left: 40px;
}

.extensionCardListExpanded {
  background: var(--lumiverse-fill-subtle);
}

.extensionCardList .extensionHeader {
  min-height: 28px;
  align-items: center;
}

.extensionCardList .extensionInfo {
  flex: 1 1 auto;
  flex-direction: row;
  align-items: center;
  gap: 10px;
  overflow: hidden;
}

.extensionCardList .extensionName {
  flex: 0 1 220px;
  min-width: 120px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.extensionCardList .extensionMeta {
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.expandRowBtn {
  width: 26px;
  height: 26px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  padding: 0;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: var(--lumiverse-text-dim);
  cursor: pointer;
  transition: background var(--lumiverse-transition-fast), color var(--lumiverse-transition-fast);
}

.expandRowBtn:hover {
  background: var(--lumiverse-fill-hover);
  color: var(--lumiverse-text);
}

.permissionsSummary {
  display: inline-flex;
  align-items: baseline;
  gap: 8px;
  min-width: 0;
}

.permissionsCount {
  color: var(--lumiverse-text-dim);
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-variant-numeric: tabular-nums;
}

.permissionsCountIncomplete {
  color: var(--lumiverse-warning);
}

.permissionHeaderActions {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
  flex-wrap: wrap;
}

.enableAllBtnProminent {
  background: var(--lumiverse-primary-015);
  color: var(--lumiverse-primary);
  border-color: var(--lumiverse-primary-020);
}

.enableAllBtnProminent:hover:not(:disabled) {
  background: var(--lumiverse-primary-020);
  color: var(--lumiverse-primary);
  border-color: var(--lumiverse-primary);
}

.permissionReviewBtn {
  min-height: 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 4px 9px;
  border-radius: 999px;
  background: transparent;
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text-dim);
  font-family: inherit;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  cursor: pointer;
  transition: background var(--lumiverse-transition-fast), color var(--lumiverse-transition-fast), border-color var(--lumiverse-transition-fast);
}

.permissionReviewBtn:hover {
  background: var(--lumiverse-fill-hover);
  color: var(--lumiverse-text);
  border-color: var(--lumiverse-border-hover);
}

@container extCard (max-width: 620px) {
  .extensionCardList .extensionInfo {
    flex-wrap: wrap;
    column-gap: 8px;
    row-gap: 1px;
  }

  .extensionCardList .extensionName {
    flex-basis: calc(100% - 4px);
  }
}

@media (max-width: 760px) {
  .toolbarPrimaryRow {
    gap: 7px;
  }
}

@media (max-width: 520px) {
  .viewToggleBtn span {
    display: none;
  }

  .sortField select {
    flex: 1;
    min-width: 0;
    width: 100%;
  }

  .updateAllBtn {
    padding-inline: 8px;
  }

  .installBtn {
    padding-inline: 10px;
  }

  .listHeaderActions {
    width: 100%;
  }

  .listHeaderMeta {
    flex: 1 1 auto;
    min-width: 0;
    margin-left: 0;
  }

  .extensionCardList .extensionMeta {
    max-width: 100%;
  }

  .permissionsHeader {
    align-items: flex-start;
  }

  .permissionHeaderActions {
    width: 100%;
    justify-content: flex-start;
  }
}

