.card {
  display: flex;
  flex-direction: column;
  border-radius: var(--lumiverse-radius);
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
  overflow: hidden;
}

.collapseHeader {
  width: 100%;
  min-height: 38px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 8px 12px;
  border: 0;
  background: transparent;
  color: var(--lumiverse-text-muted);
  cursor: pointer;
  text-align: left;
  font-family: inherit;
  transition: background var(--lumiverse-transition-fast), color var(--lumiverse-transition-fast);
}

.collapseHeader:hover {
  background: var(--lumiverse-fill-hover);
  color: var(--lumiverse-text);
}

.collapseTitle {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--lumiverse-text-dim);
}

.summary {
  flex-shrink: 0;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  text-transform: none;
  letter-spacing: normal;
  font-variant-numeric: tabular-nums;
}

.content {
  display: flex;
  flex-direction: column;
  gap: 0;
  border-top: 1px solid var(--lumiverse-border);
}

.setting {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 10px 12px;
}

.setting + .setting {
  border-top: 1px solid var(--lumiverse-border);
}

.headerRow {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
}

.label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--lumiverse-text-dim);
}

.inputGroup {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.segmented {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.segmentedBtn {
  padding: 6px 10px;
  border-radius: var(--lumiverse-radius);
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-bg);
  color: var(--lumiverse-text-muted);
  cursor: pointer;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  transition: border-color var(--lumiverse-transition-fast),
    background var(--lumiverse-transition-fast),
    color var(--lumiverse-transition-fast);
}

.segmentedBtn[data-active='true'] {
  border-color: var(--lumiverse-primary);
  background: color-mix(in srgb, var(--lumiverse-primary) 14%, var(--lumiverse-bg));
  color: var(--lumiverse-text);
}

.segmentedBtn:hover {
  color: var(--lumiverse-text);
}

.input {
  width: 64px;
  padding: 4px 8px;
  border-radius: var(--lumiverse-radius);
  background: var(--lumiverse-bg);
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  font-variant-numeric: tabular-nums;
  outline: none;
  transition: border-color var(--lumiverse-transition-fast);
}

.input:focus {
  border-color: var(--lumiverse-primary);
}

.input:disabled {
  opacity: 0.55;
  cursor: wait;
}

.suffix {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
}

.hint {
  margin: 0;
  max-width: 78ch;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  line-height: 1.45;
  color: var(--lumiverse-text-muted);
}

@media (max-width: 520px) {
  .summary {
    display: none;
  }

  .headerRow {
    align-items: flex-start;
  }
}

