/* ── Wrapper — always rendered, translates to open/close ── */

.wrapper {
  --drawer-tab-w: 48px;
  position: fixed;
  top: var(--app-interactive-safe-top, env(safe-area-inset-top, 0px));
  /* The `bottom: calc(0 - var(--ios-viewport-offset))` pattern used on pure
     backdrops (ModalShell, PackBrowser overlay, etc.) is defensive viewport
     overhang — harmless when the element is just a dimmed layer, but the
     drawer's wrapper IS the scrollable content container, so extending past
     the visible viewport puts the last ~safe-area-inset-top of .panelContent
     off-screen and makes the bottom of tab content unreachable on iPhone. */
  bottom: 0;
  z-index: 9992;
  display: flex;
  align-items: stretch;
  pointer-events: none;
  transition: transform 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}

.wrapperCompact {
  --drawer-tab-w: 32px;
}

.wrapperRight {
  right: 0;
  flex-direction: row;
  /* Shift by the actual wrapper width minus the exposed handle width so the
     tab stays flush even if viewport units and zoom compensation diverge. */
  transform: translateX(calc(100% - var(--drawer-tab-w)));
}

.wrapperLeft {
  left: 0;
  flex-direction: row-reverse;
  transform: translateX(calc(-100% + var(--drawer-tab-w)));
}

.wrapperOpen {
  transform: translateX(0);
}

.wrapper.wrapperPinned {
  position: absolute;
  right: auto;
  bottom: auto;
  transform: none;
  transition: none;
  min-width: 0;
  min-height: 0;
  overflow: clip;
}

.wrapperPinned .drawer {
  width: 100%;
  min-width: 0;
  box-shadow: none;
}

/* Slide the panel beyond the physical edge, including Duo's side status area.
   Moving the whole wrapper inward exposes a strip of the closed panel. Keep
   only its handle and the open panel's controls inside the safe area. */
:global(html[data-tauri-mobile='ios']) .wrapper:not(.wrapperPinned) .drawer {
  padding-left: calc(env(safe-area-inset-left, 0px) / var(--lumiverse-ui-scale, 1));
  padding-right: calc(env(safe-area-inset-right, 0px) / var(--lumiverse-ui-scale, 1));
}

:global(html[data-tauri-mobile='ios']) .wrapperRight:not(.wrapperOpen) .drawerTab {
  transform: translateX(calc(0px - env(safe-area-inset-right, 0px) / var(--lumiverse-ui-scale, 1)));
}

:global(html[data-tauri-mobile='ios']) .wrapperLeft:not(.wrapperOpen) .drawerTab {
  transform: translateX(calc(env(safe-area-inset-left, 0px) / var(--lumiverse-ui-scale, 1)));
}

/* ── Flush drawer tab ── */

.drawerTab {
  flex-shrink: 0;
  align-self: flex-start;
  width: var(--drawer-tab-w);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 16px 8px 20px;
  background: var(--lcs-glass-bg, var(--lumiverse-bg));
  border: 1px solid var(--lumiverse-border-hover);
  color: var(--lumiverse-text-muted);
  cursor: grab;
  pointer-events: auto;
  touch-action: none;
  user-select: none;
  transition: background 0.2s ease, border-color 0.2s ease, color 0.2s ease;
}

.drawerTabDragging {
  cursor: grabbing;
}

.wrapperRight .drawerTab {
  border-right: none;
  border-radius: 12px 0 0 12px;
}

.wrapperLeft .drawerTab {
  border-left: none;
  border-radius: 0 12px 12px 0;
}

.drawerTab:hover {
  background: var(--lumiverse-bg-hover, var(--lumiverse-bg));
  border-color: var(--lumiverse-primary-050);
  color: var(--lumiverse-text);
}

.wrapperLeft .drawerTab:hover {
  /* inherits from .drawerTab:hover */
}

.drawerTabActive {
  background: var(--lumiverse-bg-hover, var(--lumiverse-bg));
  border-color: var(--lumiverse-primary-050);
  color: var(--lumiverse-text);
}

.drawerTabCompact {
  padding: 8px 6px;
  gap: 0;
}

.tabIconBox {
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--lumiverse-primary);
}

.drawerTabCompact .tabIconBox {
  /* inherits */
}

/* ── Backdrop ── */

.backdrop {
  position: fixed;
  inset: 0;
  height: var(--app-scaled-viewport-height, calc(100vh / var(--lumiverse-ui-scale, 1)));
  width: var(--app-scaled-viewport-width, calc(100vw / var(--lumiverse-ui-scale, 1)));
  bottom: calc(0px - var(--ios-viewport-offset, 0px));
  z-index: 9991;
  background: var(--lumiverse-fill-heavy);
}

/* ── Drawer ── */

.drawer {
  position: relative;
  width: var(--drawer-panel-w);
  height: 100%;
  display: flex;
  background: var(--lumiverse-bg-deep);
  box-shadow: var(--lumiverse-shadow-xl);
  pointer-events: auto;
  /* Tabs own scrolling. Native focus must not scroll this frame and header. */
  overflow: clip;
  isolation: isolate;
}

.resizeHandle {
  position: absolute;
  inset-block: 0;
  width: 8px;
  z-index: 10;
  cursor: col-resize;
  touch-action: none;
  user-select: none;
}

.wrapperRight .resizeHandle { left: 0; }
.wrapperLeft .resizeHandle { right: 0; }

.resizeHandle:hover,
.resizeHandle:focus-visible {
  background: var(--lumiverse-primary-020);
  outline: none;
  box-shadow: inset 2px 0 var(--lumiverse-primary);
}

.wrapperRight .drawer {
  flex-direction: row;
}

.wrapperLeft .drawer {
  flex-direction: row-reverse;
}

/* ── Sidebar ── */

.sidebar {
  display: flex;
  flex-direction: column;
  width: 56px;
  flex-shrink: 0;
  background: color-mix(in srgb, var(--lumiverse-primary) 6%, var(--lumiverse-bg-deep));
  padding: 6px 0;
  gap: 4px;
  border-right: 1px solid var(--lumiverse-primary-020);
}

.wrapperLeft .sidebar {
  border-right: none;
  border-left: 1px solid var(--lumiverse-primary-020);
}

.tabListWrap {
  position: relative;
  flex: 1;
  min-height: 0;
  overflow: hidden;
}

.tabListWrap::before,
.tabListWrap::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  height: 24px;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.2s ease;
  z-index: 1;
}

.tabListWrap::before {
  top: 0;
  background: linear-gradient(to bottom, color-mix(in srgb, var(--lumiverse-primary) 6%, var(--lumiverse-bg-deep)), transparent);
}

.tabListWrap::after {
  bottom: 0;
  background: linear-gradient(to top, color-mix(in srgb, var(--lumiverse-primary) 6%, var(--lumiverse-bg-deep)), transparent);
}

.tabListScrollUp::before {
  opacity: 1;
}

.tabListScrollDown::after {
  opacity: 1;
}

.tabList {
  display: flex;
  flex-direction: column;
  gap: 2px;
  height: 100%;
  overflow-y: auto;
  scrollbar-width: none;
}

.tabList::-webkit-scrollbar {
  display: none;
}

.tabBtn {
  width: 100%;
  height: 48px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1px;
  border-radius: 8px;
  background: transparent;
  border: none;
  color: var(--lumiverse-text-muted);
  cursor: pointer;
  transition: all 0.2s ease;
}

.tabBtnLabeled {
  height: 56px;
}

.tabBtn:hover {
  background: var(--lumiverse-primary-015);
  color: var(--lumiverse-text);
}

.tabBtnActive {
  background: var(--lumiverse-primary-020);
  color: var(--lumiverse-primary);
  box-shadow: inset 3px 0 0 var(--lumiverse-primary);
  border-radius: 0 8px 8px 0;
}

.wrapperLeft .tabBtnActive {
  box-shadow: inset -3px 0 0 var(--lumiverse-primary);
  border-radius: 8px 0 0 8px;
}

/* ── Tab label ── */

.tabLabel {
  font-size: calc(9px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  line-height: 1;
  color: var(--lumiverse-text-dim);
  text-align: center;
  max-width: 48px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  margin-top: 1px;
}

.tabBtnActive .tabLabel {
  color: var(--lumiverse-primary);
}

/* ── Extension tab styles ── */

.tabDivider {
  height: 1px;
  margin: 4px 6px;
  background: var(--lumiverse-primary-020);
  flex-shrink: 0;
}

.tabBtnExtension {
  position: relative;
}

.tabBtnExtension::after {
  content: '';
  position: absolute;
  bottom: 4px;
  left: 50%;
  transform: translateX(-50%);
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--lumiverse-accent);
  opacity: 0.5;
}

.extIconSvg {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
}

.extIconSvg svg {
  width: 20px;
  height: 20px;
}

.extIconImg {
  width: 20px;
  height: 20px;
  border-radius: 4px;
  object-fit: contain;
}

.tabBadge {
  position: absolute;
  top: 4px;
  right: 4px;
  min-width: 12px;
  height: 12px;
  padding: 0 2px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 6px;
  background: var(--lumiverse-bg-panel, var(--lumiverse-bg));
  color: var(--lumiverse-text-dim);
  font-size: calc(8px * var(--lumiverse-font-scale, 1));
  font-weight: 650;
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

.sidebarBottom {
  padding-top: 8px;
  border-top: 1px solid var(--lumiverse-primary-020);
  margin-top: 8px;
}

/* ── Panel ── */

.panel {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  overflow: clip;
}

.panelHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  background: var(--lumiverse-primary-008, rgba(255, 255, 255, 0.02));
  border-bottom: 1px solid var(--lumiverse-primary-015);
  flex-shrink: 0;
  min-height: 48px;
}

.panelTitle {
  font-size: calc(15px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
}

.panelHeaderMain {
  display: flex;
  align-items: center;
  gap: 4px;

  min-width: 0;
}

.headerActions {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
  margin-left: auto;
}

.guideButton {
  width: 26px;
  height: 26px;
  flex-shrink: 0;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  padding: 0;

  border: 0;
  border-radius: 6px;
  background: transparent;

  color: var(--lumiverse-text-muted);
  opacity: 0.38;

  cursor: pointer;

  transition:
    opacity 0.15s ease,
    color 0.15s ease,
    background 0.15s ease;
}

.guideButton:hover {
  opacity: 0.82;
  color: var(--lumiverse-text);
  background: var(--lumiverse-fill-subtle);
}

.guideButton:focus-visible {
  opacity: 0.9;
  outline: 1px solid var(--lumiverse-primary-050);
  outline-offset: 1px;
}

.panelContent {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  overscroll-behavior-y: contain;
  -webkit-overflow-scrolling: touch;
  /* Keep the last list item clear of the home indicator / gesture bar. Any
     panel-specific bottom chrome (pagination bars, etc.) should add its own
     spacing rather than relying on this buffer. */
  padding: 12px 12px env(safe-area-inset-bottom, 0px);
  position: relative;
}

/* iOS PWA: the drawer doesn't resize when the keyboard opens (layout viewport
   stays full-screen). Add keyboard-height padding so the focusin handler can
   scroll inputs above the keyboard even when the panel's actual content is
   shorter than the container. */
:global(html[data-ios-pwa]) .panelContent {
  padding-bottom: calc(env(safe-area-inset-bottom, 0px) + var(--app-keyboard-inset-bottom, 0px));
}

.panelContentFull {
  padding: 0;
  overflow: clip;
}

.stubPanel {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 60px 20px;
  text-align: center;
  color: var(--lumiverse-text-muted);
  gap: 8px;
}

.stubPanel p {
  font-size: calc(16px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
}

.stubPanel span {
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
}

/* ── Mobile ── */

@media (max-width: 600px) {
  .wrapper {
    --drawer-panel-w: var(--app-scaled-viewport-width, calc(100vw / var(--lumiverse-ui-scale, 1))) !important;
    --drawer-tab-w: 40px;
  }

  .wrapperCompact {
    --drawer-tab-w: 28px;
  }

  .drawerTab {
    padding: 12px 6px 16px;
    gap: 6px;
  }

  .drawerTabCompact {
    padding: 6px 4px;
  }

  .drawer {
    width: var(--drawer-panel-w) !important;
    flex-direction: column !important;
  }

  .sidebar {
    width: 100%;
    flex-direction: row;
    align-items: center;
    border-right: none !important;
    border-left: none !important;
    border-bottom: 1px solid var(--lumiverse-primary-020);
    padding: 8px 8px;
    gap: 2px;
    flex-shrink: 0;
  }

  .tabListWrap {
    min-height: auto;
    flex: 1;
    min-width: 0;
  }

  .tabListWrap::before,
  .tabListWrap::after {
    display: none;
  }

  .tabList {
    flex-direction: row;
    height: auto;
    overflow-x: auto;
    overflow-y: hidden;
    gap: 2px;
    -webkit-overflow-scrolling: touch;
  }

  .tabBtn {
    width: 42px;
    height: 42px;
    flex-shrink: 0;
  }

  .tabBtnLabeled {
    width: 52px;
    height: 48px;
  }

  .tabBtnActive {
    box-shadow: inset 0 -3px 0 var(--lumiverse-primary) !important;
    border-radius: 8px 8px 0 0 !important;
  }

  .sidebarBottom {
    padding-top: 0;
    border-top: none;
    margin-top: 0;
    padding-left: 4px;
    margin-left: 4px;
    border-left: 1px solid var(--lumiverse-primary-020);
    display: flex;
    align-items: center;
  }

  .sidebarBottom .tabBtn {
    width: 42px;
    height: 42px;
  }

  .tabDivider {
    width: 1px;
    height: 28px;
    margin: 0 4px;
  }
}

/* ── Sidebar organization ── */

.folderSlot {
  display: contents;
}

.folderTabBtn {
  position: relative;
}

/* Keep canonical drawer_tab mount anchors alive for foldered tabs. Extensions
   may decorate their own sidebar button; organization must not turn that into
   a registration-order race just because the visible button became a folder. */
.organizedTabAnchors,
.organizedTabAnchor {
  display: none !important;
}

.folderPanel {
  display: flex;
  height: 100%;
  min-height: 0;
  flex-direction: column;
  gap: 8px;
}

.folderToolbar {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: space-between;
  min-height: 34px;
  padding: 0 2px 7px;
  border-bottom: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text-dim);
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
}

.folderToolbarActions {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.folderViewToggle {
  display: inline-flex;
  overflow: hidden;
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  background: transparent;
}

.folderViewButton {
  display: inline-flex;
  width: 28px;
  height: 27px;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 0;
  border-right: 1px solid var(--lumiverse-border);
  background: transparent;
  color: var(--lumiverse-text-dim);
  cursor: pointer;
}

.folderViewButton:last-child {
  border-right: 0;
}

.folderViewButton:hover,
.folderViewButtonActive {
  background: var(--lumiverse-primary-015);
  color: var(--lumiverse-primary);
}

.folderManageButton {
  flex: 0 0 auto;
  min-height: 28px;
  padding: 4px 8px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  background: transparent;
  color: var(--lumiverse-text-secondary);
  font: inherit;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 650;
  cursor: pointer;
}

.folderManageButton:hover {
  border-color: var(--lumiverse-border-hover);
  color: var(--lumiverse-text);
  background: var(--lumiverse-primary-015);
}

.folderList {
  display: flex;
  min-height: 0;
  flex-direction: column;
  border: 1px solid var(--lumiverse-border);
  border-radius: 11px;
  overflow-x: hidden;
  overflow-y: auto;
  background: color-mix(in srgb, var(--lumiverse-bg-panel, var(--lumiverse-bg)) 96%, white 4%);
}

.folderTile {
  display: grid;
  flex-shrink: 0;
  grid-template-columns: 32px minmax(0, 1fr) 14px;
  align-items: center;
  gap: 9px;
  min-height: 54px;
  padding: 7px 9px;
  border: 0;
  border-bottom: 1px solid var(--lumiverse-border);
  background: transparent;
  color: var(--lumiverse-text);
  text-align: left;
  cursor: pointer;
}

.folderTile:last-child {
  border-bottom: 0;
}

.folderTile:hover {
  background: var(--lumiverse-primary-008, rgba(255, 255, 255, 0.03));
}

.folderTileIcon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 9px;
  background: var(--lumiverse-primary-015);
  color: var(--lumiverse-primary);
}

.folderTileCopy {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.folderTileCopy strong {
  overflow: hidden;
  color: var(--lumiverse-text);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 650;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.folderTileCopy span {
  overflow: hidden;
  color: var(--lumiverse-text-dim);
  font-size: calc(9px * var(--lumiverse-font-scale, 1));
  line-height: 1.25;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.folderTileChevron {
  color: var(--lumiverse-text-dim);
  opacity: 0.7;
}

.folderGrid {
  display: grid;
  flex: 1 1 0;
  min-height: 0;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  /* Let the rows fill the available folder height. Cards stretch with the
     rows again, while their contents stay centered so grid mode reads like
     a dashboard instead of a stack of oversized list rows. */
  grid-auto-rows: minmax(160px, 1fr);
  gap: 8px;
  padding: 0;
  border: 0;
  border-radius: 0;
  overflow-y: auto;
  background: transparent;
}

.folderGrid .folderTile {
  display: flex;
  width: 100%;
  min-width: 0;
  height: 100%;
  min-height: 160px;
  align-self: stretch;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 10px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 11px;
  background: color-mix(in srgb, var(--lumiverse-bg-panel, var(--lumiverse-bg)) 96%, white 4%);
  text-align: center;
}

.folderGrid .folderTile:last-child {
  border-bottom: 1px solid var(--lumiverse-border);
}

.folderGrid .folderTile:hover {
  border-color: var(--lumiverse-border-hover);
  background: var(--lumiverse-primary-008, rgba(255, 255, 255, 0.03));
}

.folderGrid .folderTileIcon {
  width: 36px;
  height: 36px;
  border-radius: 10px;
}

.folderGrid .folderTileCopy {
  width: 100%;
  align-items: center;
}

.folderGrid .folderTileCopy strong {
  max-width: 100%;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
}

.folderGrid .folderTileCopy span {
  display: -webkit-box;
  max-width: 150px;
  overflow: hidden;
  line-height: 1.3;
  text-align: center;
  white-space: normal;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.folderGrid .folderTileChevron {
  display: none;
}

.folderPanelEmpty {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 90px;
  padding: 18px;
  border: 1px dashed var(--lumiverse-border);
  border-radius: 11px;
  color: var(--lumiverse-text-dim);
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  text-align: center;
}

