import { useState, useRef } from 'react'
import { useTranslation } from 'react-i18next'
import { createPortal } from 'react-dom'
import { X, Plus } from 'lucide-react'
import { Spinner } from '@/components/shared/Spinner'
import { CloseButton } from '@/components/shared/CloseButton'
import { charactersApi } from '@/api/characters'
import { useStore } from '@/store'
import type { TagCount } from '@/types/api'
import styles from './BulkTagsModal.module.css'

type Operation = 'add' | 'remove' | 'replace'

interface BulkTagsModalProps {
  isOpen: boolean
  selectedIds: string[]
  allTags: TagCount[]
  onClose: () => void
  onApplied: () => void
}

export default function BulkTagsModal({ isOpen, selectedIds, allTags, onClose, onApplied }: BulkTagsModalProps) {
  const { t } = useTranslation('panels')
  const addToast = useStore((s) => s.addToast)
  const [operation, setOperation] = useState<Operation>('add')
  const [staged, setStaged] = useState<string[]>([])
  const [draft, setDraft] = useState('')
  const [applying, setApplying] = useState(false)
  const mouseDownTargetRef = useRef<EventTarget | null>(null)

  if (!isOpen) return null

  const opLabelKey = (op: Operation) => `characterBrowser.bulkTags${op.charAt(0).toUpperCase()}${op.slice(1)}`
  const opHintKey = (op: Operation) => `${opLabelKey(op)}Hint`

  const addTag = (raw: string) => {
    const tag = raw.trim()
    if (!tag || staged.includes(tag)) return
    setStaged([...staged, tag])
    setDraft('')
  }
  const removeTag = (tag: string) => setStaged((prev) => prev.filter((t) => t !== tag))

  const handleApply = async () => {
    if (staged.length === 0 || selectedIds.length === 0 || applying) return
    setApplying(true)
    try {
      const result = await charactersApi.bulkUpdateTags(selectedIds, operation, staged)
      if (result.updated > 0) {
        addToast({ type: 'success', message: t('characterBrowser.bulkTagsApplied', { count: result.updated }) })
        setStaged([])
        setDraft('')
        setOperation('add')
        onApplied()
      } else {
        const zeroKey = operation === 'add'
          ? 'characterBrowser.bulkTagsAlreadyPresent'
          : operation === 'remove'
            ? 'characterBrowser.bulkTagsNoneToRemove'
            : 'characterBrowser.bulkTagsNoChange'
        addToast({ type: 'info', message: t(zeroKey, { count: selectedIds.length }) })
      }
    } catch (err) {
      let message: string | undefined
      if (err && typeof err === 'object' && 'body' in err) {
        const body = err.body
        if (body && typeof body === 'object' && 'error' in body) {
          const error = body.error
          message = typeof error === 'string' ? error : undefined
        }
      }
      addToast({ type: 'error', message: message || t('characterBrowser.bulkTagsFailed') })
    } finally {
      setApplying(false)
    }
  }

  const operations: Operation[] = ['add', 'remove', 'replace']
  const suggestions = allTags.map((tag) => tag.tag).filter((tag) => !staged.includes(tag)).slice(0, 20)

  return createPortal(
    <div
      className={styles.overlay}
      onMouseDown={(e) => { mouseDownTargetRef.current = e.target }}
      onClick={(e) => e.target === e.currentTarget && mouseDownTargetRef.current === e.currentTarget && !applying && onClose()}
    >
      <div className={styles.modal}>
        <div className={styles.header}>
          <h3 className={styles.title}>{t('characterBrowser.bulkTagsTitle')}</h3>
          <CloseButton onClick={onClose} />
        </div>
        <div className={styles.body}>
          <p className={styles.count}>{t('characterBrowser.bulkTagsCount', { count: selectedIds.length })}</p>
          <div className={styles.segmented}>
            {operations.map((op) => (
              <button
                key={op}
                type="button"
                className={`${styles.segBtn} ${operation === op ? styles.segBtnActive : ''}`}
                onClick={() => setOperation(op)}
                disabled={applying}
              >
                {t(opLabelKey(op))}
              </button>
            ))}
          </div>
          <p className={styles.hint}>{t(opHintKey(operation))}</p>
          <div className={styles.tagInputRow}>
            <input
              className={styles.tagInput}
              value={draft}
              onChange={(e) => setDraft(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && addTag(draft)}
              placeholder={t('characterBrowser.bulkTagsPlaceholder')}
              disabled={applying}
              autoFocus
            />
            <button type="button" className={styles.tagAddBtn} onClick={() => addTag(draft)} disabled={!draft.trim() || applying}>
              <Plus size={14} />
            </button>
          </div>
          {staged.length > 0 && (
            <div className={styles.stagedTags}>
              {staged.map((tag) => (
                <span key={tag} className={styles.tagChip}>
                  {tag}
                  <button type="button" className={styles.tagRemove} onClick={() => removeTag(tag)} disabled={applying}>
                    <X size={10} />
                  </button>
                </span>
              ))}
            </div>
          )}
          {suggestions.length > 0 && (
            <div className={styles.suggestions}>
              <span className={styles.suggestionsLabel}>{t('characterBrowser.bulkTagsSuggestions')}</span>
              <div className={styles.suggestionChips}>
                {suggestions.map((tag) => (
                  <button key={tag} type="button" className={styles.suggestionChip} onClick={() => addTag(tag)} disabled={applying}>
                    {tag}
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
        <div className={styles.actions}>
          <button type="button" className={styles.cancelBtn} onClick={onClose} disabled={applying}>
            {t('characterBrowser.bulkTagsCancel')}
          </button>
          <button
            type="button"
            className={styles.applyBtn}
            onClick={handleApply}
            disabled={staged.length === 0 || selectedIds.length === 0 || applying}
          >
            {applying ? <Spinner size={14} /> : null}
            {t('characterBrowser.bulkTagsApply')}
          </button>
        </div>
      </div>
    </div>,
    document.body,
  )
}

.card {
  position: relative;
  display: flex;
  flex-direction: column;
  aspect-ratio: 3 / 4;
  border-radius: 16px;
  overflow: hidden;
  cursor: pointer;
  background: var(--lumiverse-card-bg);
  border: 1px solid var(--lumiverse-border-neutral);
  box-shadow: var(--lumiverse-shadow-sm);
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1),
              border-color 0.3s cubic-bezier(0.4, 0, 0.2, 1),
              box-shadow 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  contain: layout style paint;
}

@media (hover: hover) and (pointer: fine) {
  .card:hover { will-change: transform; }
}

/* Gradient overlay at the card bottom that blends into the image for text
   contrast. Uses the main background color so it seamlessly adapts
   when CSS classes change with a new palette. */
.card::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 55%;
  pointer-events: none;
  background: linear-gradient(
    to top,
    var(--lumiverse-bg) 0%,
    color-mix(in srgb, var(--lumiverse-bg) 92%, transparent) 25%,
    color-mix(in srgb, var(--lumiverse-bg) 50%, transparent) 55%,
    transparent 100%
  );
  z-index: 1;
}

.card:hover {
  transform: translateY(-4px);
  border-color: var(--lumiverse-border-hover);
  box-shadow:
    var(--lumiverse-shadow-md),
    0 0 0 1px var(--lumiverse-primary-015);
}

.card:focus-visible {
  outline: 2px solid var(--lumiverse-primary);
  outline-offset: -2px;
}

.selected {
  border-color: rgba(100, 149, 237, 0.6);
  box-shadow:
    0 4px 16px rgba(100, 149, 237, 0.2),
    0 0 0 1px rgba(100, 149, 237, 0.3),
    inset 0 0 20px rgba(100, 149, 237, 0.05);
}

/* Cover image */
.imageWrap {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  background: var(--lumiverse-card-image-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.coverImg {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: contain;
  /* Sync image transform scale with the card's animation timing */
  --lazy-image-transform-transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.card:hover .coverImg {
  transform: scale(1.05);
}

.avatarFallback {
  font-size: calc(48px * var(--lumiverse-font-scale, 1));
  font-weight: 300;
  color: var(--lumiverse-primary-muted);
  user-select: none;
}

/* Overlay buttons */
.editBtn {
  position: absolute;
  top: 8px;
  left: 8px;
  width: var(--lumiverse-btn-icon);
  height: var(--lumiverse-btn-icon);
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  /* On-image overlay control: fixed dark scrim + light icon in BOTH themes.
     The theme fill/text tokens collapse to near-invisible in light mode
     (faint scrim + dark icon over imagery), so they must not be used here. */
  background: rgba(0, 0, 0, 0.5);
  border: 1px solid rgba(255, 255, 255, 0.15);
  color: #fff;
  cursor: pointer;
  opacity: 0;
  z-index: 2;
  transition: opacity 0.25s cubic-bezier(0.4, 0, 0.2, 1),
              background 0.25s cubic-bezier(0.4, 0, 0.2, 1),
              border-color 0.25s cubic-bezier(0.4, 0, 0.2, 1),
              color 0.25s cubic-bezier(0.4, 0, 0.2, 1),
              transform 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

.card:hover .editBtn {
  opacity: 1;
}

.editBtn:hover {
  background: rgba(0, 0, 0, 0.7);
  border-color: var(--lumiverse-primary-050);
  color: white;
  transform: scale(1.1);
}

.favBtn {
  position: absolute;
  top: 8px;
  right: 8px;
  width: var(--lumiverse-btn-icon);
  height: var(--lumiverse-btn-icon);
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  /* On-image overlay control: fixed dark scrim + light icon in BOTH themes.
     The theme fill/text tokens collapse to near-invisible in light mode
     (faint scrim + dark icon over imagery), so they must not be used here. */
  background: rgba(0, 0, 0, 0.5);
  border: 1px solid rgba(255, 255, 255, 0.15);
  color: #fff;
  cursor: pointer;
  opacity: 0;
  z-index: 2;
  transition: opacity 0.25s cubic-bezier(0.4, 0, 0.2, 1),
              background 0.25s cubic-bezier(0.4, 0, 0.2, 1),
              border-color 0.25s cubic-bezier(0.4, 0, 0.2, 1),
              color 0.25s cubic-bezier(0.4, 0, 0.2, 1),
              transform 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

.card:hover .favBtn,
.favBtnActive {
  opacity: 1;
}

.favBtn:hover {
  background: rgba(0, 0, 0, 0.7);
  border-color: rgba(255, 193, 7, 0.4);
  transform: scale(1.1);
}

.favBtnActive {
  background: linear-gradient(135deg, rgba(255, 193, 7, 0.9) 0%, rgba(255, 152, 0, 0.9) 100%);
  border-color: rgba(255, 193, 7, 0.6);
  box-shadow: 0 2px 12px rgba(255, 193, 7, 0.4);
  color: white;
}

.favBtn:hover {
  color: rgba(255, 193, 7, 0.9);
}

.favBtnActive:hover {
  color: white;
}

.checkbox {
  position: absolute;
  top: 8px;
  left: 8px;
  z-index: 2;
}

.checkbox input {
  width: 18px;
  height: 18px;
  cursor: pointer;
  accent-color: var(--lumiverse-primary);
}

/* Info section at bottom */
.info {
  position: relative;
  z-index: 2;
  margin-top: auto;
  padding: 12px 14px 14px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.name {
  font-size: calc(14px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
  letter-spacing: -0.2px;
  line-height: 1.3;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.creator {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tags {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
  overflow: hidden;
  margin-top: 2px;
  max-height: 22px;
}

.tag {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  padding: 2px 8px;
  border-radius: 6px;
  border: 1px solid;
  white-space: nowrap;
  line-height: 1.4;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 100px;
}

.tagOverflow {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  padding: 2px 6px;
  border-radius: 6px;
  color: var(--lumiverse-text-dim);
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
  white-space: nowrap;
  flex-shrink: 0;
}

/* Compact variant (used in FavoritesSlider) */
.compact {
  aspect-ratio: auto;
  flex-direction: row;
  align-items: center;
  min-height: 52px;
  padding: 8px 12px;
  gap: 10px;
  border-radius: 14px;
  background: linear-gradient(180deg, var(--lumiverse-fill-subtle) 0%, var(--lumiverse-fill) 100%);
  border: 1px solid var(--lumiverse-border-neutral);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
}

/* Compact cards don't use the image-fills-card layout or the gradient overlay */
.compact::after {
  display: none;
}

.compact:hover {
  transform: translateY(-1px);
  background: linear-gradient(180deg, var(--lumiverse-fill-hover) 0%, var(--lumiverse-fill) 100%);
  border-color: var(--lumiverse-border-hover);
  box-shadow: var(--lumiverse-shadow-sm);
}

.compact .imageWrap {
  position: relative;
  inset: auto;
  width: 36px;
  height: 36px;
  aspect-ratio: 1;
  border-radius: 12px;
  flex-shrink: 0;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.06);
}

.compact .coverImg {
  border-radius: 12px;
}

.compact .avatarFallback {
  font-size: calc(14px * var(--lumiverse-font-scale, 1));
}

.compact .info {
  margin-top: 0;
  padding: 0 22px 0 0;
  align-items: flex-start;
  justify-content: center;
  flex: 1;
  min-width: 0;
  gap: 2px;
}

.compact .name {
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  line-height: 1.25;
}

.compact .favBtn {
  top: 50%;
  right: 10px;
  width: 24px;
  height: 24px;
  background: transparent;
  border-color: transparent;
  /* Compact sits on the card surface (not over imagery), so restore the
     theme-aware icon color instead of the fixed white used for overlays. */
  color: var(--lumiverse-text);
  transform: translateY(-50%);
}

.compact .favBtn:hover {
  transform: translateY(-50%) scale(1.06);
}

.compact .tags,
.compact .creator {
  display: none;
}

import { memo } from 'react'
import { useTranslation } from 'react-i18next'
import { Star, Pencil } from 'lucide-react'
import { getCharacterAvatarThumbUrl, getCharacterAvatarLargeUrl } from '@/lib/avatarUrls'
import { getTagColor } from '@/lib/tagColors'
import LazyImage from '@/components/shared/LazyImage'
import { useSpindleComponentOverride } from '@/lib/spindle/use-spindle-component-override'
import type { Character, CharacterSummary } from '@/types/api'
import styles from './CharacterCard.module.css'
import clsx from 'clsx'

interface CharacterCardProps {
  character: Character | CharacterSummary
  isFavorite: boolean
  isSelected?: boolean
  batchMode?: boolean
  compact?: boolean
  /** Use the large image tier (~700px) instead of the small tier (~300px) */
  useLargeTier?: boolean
  onOpen: (character: Character | CharacterSummary) => void
  onEdit?: (id: string) => void
  onToggleFavorite: (id: string) => void
  onToggleBatch?: (id: string) => void
}

function CharacterCardNative({
  character,
  isFavorite,
  isSelected,
  batchMode,
  compact,
  useLargeTier,
  onOpen,
  onEdit,
  onToggleFavorite,
  onToggleBatch,
}: CharacterCardProps) {
  'use memo'

  const { t } = useTranslation('panels')
  const avatarUrl = (useLargeTier ? getCharacterAvatarLargeUrl(character) : getCharacterAvatarThumbUrl(character)) ?? ''
  const tags = character.tags?.slice(0, 3) || []
  const extraTagCount = (character.tags?.length || 0) - 3

  const handleClick = () => {
    if (batchMode && onToggleBatch) {
      onToggleBatch(character.id)
    } else {
      onOpen(character)
    }
  }

  return (
    <div
      className={clsx(styles.card, compact && styles.compact, isSelected && styles.selected)}
      onClick={handleClick}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => e.key === 'Enter' && handleClick()}
    >
      <div className={styles.imageWrap}>
        <LazyImage
          src={avatarUrl}
          alt={character.name}
          className={styles.coverImg}
          fallback={
            <div className={styles.avatarFallback}>
              {character.name[0]?.toUpperCase()}
            </div>
          }
        />
        {batchMode && (
          <div className={styles.checkbox}>
            <input
              type="checkbox"
              checked={isSelected}
              onChange={() => onToggleBatch?.(character.id)}
              onClick={(e) => e.stopPropagation()}
            />
          </div>
        )}
        {!batchMode && onEdit && (
          <button
            type="button"
            className={styles.editBtn}
            onClick={(e) => {
              e.stopPropagation()
              onEdit(character.id)
            }}
            title={t('characterBrowser.editCharacter')}
          >
            <Pencil size={13} />
          </button>
        )}
        {!batchMode && (
          <button
            type="button"
            className={clsx(styles.favBtn, isFavorite && styles.favBtnActive)}
            onClick={(e) => {
              e.stopPropagation()
              onToggleFavorite(character.id)
            }}
            title={isFavorite ? t('characterBrowser.removeFromFavorites') : t('characterBrowser.addToFavorites')}
          >
            <Star size={14} fill={isFavorite ? 'currentColor' : 'none'} />
          </button>
        )}
        <span data-spindle-mount="character_browser_card_actions" data-spindle-scope={`character-card:${character.id}:actions`} style={{ display: 'contents' }} />
      </div>
      <div className={styles.info}>
        <span className={styles.name}>{character.name}</span>
        {!compact && character.creator && (
          <span className={styles.creator}>{character.creator}</span>
        )}
        {!compact && tags.length > 0 && (
          <div className={styles.tags}>
            {tags.map((tag) => {
              const color = getTagColor(tag)
              return (
                <span
                  key={tag}
                  className={styles.tag}
                  style={{ background: color.bg, color: color.text, borderColor: color.border }}
                >
                  {tag}
                </span>
              )
            })}
            {extraTagCount > 0 && (
              <span className={styles.tagOverflow}>+{extraTagCount}</span>
            )}
          </div>
        )}
      </div>
    </div>
  )
}

function CharacterCard(props: CharacterCardProps) {
  return useSpindleComponentOverride('CharacterCard', CharacterCardNative, props)
}

export default memo(CharacterCard)

