.extensionGuideButton:hover {
  opacity: 1;
  color: var(--lumiverse-text);
  background: var(--lumiverse-fill-subtle);
}

/* Tab bar */
.tabBar {
  display: flex;
  gap: 4px;
  padding: 10px 20px;
  border-bottom: 1px solid var(--lumiverse-border);
  flex-shrink: 0;
  min-width: 0;
  max-width: 100%;
  overflow-x: auto;
  overflow-y: hidden;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior-x: contain;
  scrollbar-width: thin;
}

.tab {
  flex: 0 0 auto;
  padding: 6px 14px;
  border-radius: 20px;
  background: transparent;
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text-dim);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  cursor: pointer;
  white-space: nowrap;
  transition: all var(--lumiverse-transition-fast);
}

.tab:hover {
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text);
}

.tabActive {
  background: var(--lumiverse-primary);
  border-color: var(--lumiverse-primary);
  color: var(--lumiverse-primary-contrast, #fff);
}

.tabActive:hover {
  background: var(--lumiverse-primary);
  color: var(--lumiverse-primary-contrast, #fff);
}

/* Tab content */
.tabContent {
  flex: 1;
  overflow-y: auto;
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.fieldGroup {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.fieldLabelRow {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.fieldLabel {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
}

.perspectiveLayerGrid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin-top: 6px;
}

.perspectiveStackEditor {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 6px;
}

.perspectiveLayerList {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.perspectiveLayerRow {
  display: grid;
  grid-template-columns: 32px 72px minmax(0, 1fr);
  gap: 10px;
  align-items: stretch;
  padding: 8px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 12px;
  background: var(--lumiverse-fill-subtle);
  transition:
    border-color var(--lumiverse-transition-fast),
    background var(--lumiverse-transition-fast),
    box-shadow var(--lumiverse-transition-fast);
}

.perspectiveLayerDragging {
  border-color: var(--lumiverse-primary-050);
  background: var(--lumiverse-bg-elevated, var(--lumiverse-bg));
  box-shadow: 0 10px 24px rgba(0, 0, 0, 0.28);
  z-index: 2;
}

.perspectiveLayerDrag {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  border: 1px solid var(--lumiverse-border);
  border-radius: 9px;
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text-dim);
  cursor: grab;
}

.perspectiveLayerDrag:active {
  cursor: grabbing;
}

.perspectiveLayerDrag:disabled {
  opacity: 0.45;
  cursor: default;
}

.perspectiveLayerRowPreview {
  position: relative;
  overflow: hidden;
  min-height: 92px;
  border-radius: 10px;
  background: var(--lumiverse-bg-elevated, var(--lumiverse-bg));
}

.perspectiveLayerRowImg {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.perspectiveLayerRowBody {
  display: flex;
  flex-direction: column;
  gap: 9px;
  min-width: 0;
}

.perspectiveLayerRowTop {
  display: flex;
  align-items: center;
  gap: 8px;
}

.perspectiveLayerNameInput {
  flex: 1;
  min-width: 0;
  height: 30px;
  padding: 0 9px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  background: var(--lumiverse-bg-elevated, var(--lumiverse-bg));
  color: var(--lumiverse-text);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  outline: none;
}

.perspectiveLayerNameInput:focus {
  border-color: var(--lumiverse-primary-050);
}

.perspectiveLayerSliderRow {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.perspectiveLayerSliderHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
}

.perspectiveLayerEmptyState {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 80px;
  border: 1px dashed var(--lumiverse-border);
  border-radius: 12px;
  color: var(--lumiverse-text-dim);
  background: var(--lumiverse-fill-subtle);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
}

.perspectiveLayerAdd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 34px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 10px;
  background: var(--lumiverse-primary-010);
  color: var(--lumiverse-text-muted);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  cursor: pointer;
  transition:
    background var(--lumiverse-transition-fast),
    border-color var(--lumiverse-transition-fast),
    color var(--lumiverse-transition-fast);
}

.perspectiveLayerAdd:hover {
  border-color: var(--lumiverse-primary-050);
  background: var(--lumiverse-primary-015);
  color: var(--lumiverse-text);
}

.perspectiveLayerAdd:disabled {
  opacity: 0.55;
  cursor: default;
  pointer-events: none;
}

.perspectiveLayerCard {
  min-width: 0;
  overflow: hidden;
  border: 1px solid var(--lumiverse-border);
  border-radius: 12px;
  background: var(--lumiverse-fill-subtle);
}

.perspectiveLayerPreview {
  position: relative;
  aspect-ratio: 4 / 5;
  background:
    linear-gradient(135deg, var(--lumiverse-primary-010), transparent),
    var(--lumiverse-bg-elevated, var(--lumiverse-bg));
  overflow: hidden;
}

.perspectiveLayerImg {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.perspectiveLayerEmpty {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--lumiverse-text-dim);
}

.perspectiveLayerBusy {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--lumiverse-fill-heavy);
  color: var(--lumiverse-primary-contrast, #fff);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
}

.perspectiveLayerBody {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 9px;
}

.perspectiveLayerTitle {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 650;
  color: var(--lumiverse-text);
}

.perspectiveLayerHint {
  min-height: 28px;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  line-height: 1.35;
  color: var(--lumiverse-text-dim);
}

.perspectiveLayerActions {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 4px;
}

.perspectiveLayerUpload,
.perspectiveLayerRemove {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  min-height: 26px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text-muted);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
  transition:
    background var(--lumiverse-transition-fast),
    color var(--lumiverse-transition-fast),
    border-color var(--lumiverse-transition-fast);
}

.perspectiveLayerUpload {
  flex: 1;
  padding: 0 8px;
}

.perspectiveLayerRemove {
  width: 28px;
  padding: 0;
}

.perspectiveLayerUpload:hover,
.perspectiveLayerRemove:hover {
  border-color: var(--lumiverse-primary-050);
  background: var(--lumiverse-primary-010);
  color: var(--lumiverse-text);
}

.perspectiveLayerUpload:has(input:disabled),
.perspectiveLayerRemove:disabled {
  opacity: 0.55;
  cursor: default;
  pointer-events: none;
}

@media (max-width: 640px) {
  .perspectiveLayerGrid {
    grid-template-columns: 1fr;
  }
}

.fieldHelper {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  margin-bottom: 2px;
}

.creatorSourceRow {
  display: flex;
  align-items: center;
  gap: 6px;
}

.creatorSourceRow .fieldInput {
  min-width: 0;
}

.creatorSourceLink {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text-dim);
  transition:
    border-color var(--lumiverse-transition-fast),
    color var(--lumiverse-transition-fast),
    background var(--lumiverse-transition-fast);
}

.creatorSourceLink:hover {
  border-color: var(--lumiverse-primary);
  background: var(--lumiverse-primary-010);
  color: var(--lumiverse-primary);
}

.creatorSourceError {
  color: var(--lumiverse-error);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
}

.fieldTextarea {
  width: 100%;
  background: var(--lumiverse-bg);
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  padding: 10px 12px;
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text);
  resize: vertical;
  min-height: 80px;
  outline: none;
  font-family: inherit;
  line-height: 1.5;
  transition: border-color var(--lumiverse-transition-fast);
}

.fieldTextarea:focus {
  border-color: var(--lumiverse-primary);
}

.fieldInput {
  width: 100%;
  background: var(--lumiverse-bg);
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  padding: 8px 12px;
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text);
  outline: none;
  transition: border-color var(--lumiverse-transition-fast);
}

.fieldInput:focus {
  border-color: var(--lumiverse-primary);
}

/* Greetings list */
.greetingMetaRow {
  display: flex;
  align-items: flex-end;
  gap: 8px;
}

.greetingNameField {
  display: flex;
  flex: 1;
  min-width: 0;
  flex-direction: column;
  gap: 4px;
  color: var(--lumiverse-text-dim);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
}

.greetingNameInput {
  width: 100%;
  min-width: 0;
  height: 32px;
  padding: 6px 9px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 7px;
  outline: none;
  background: var(--lumiverse-bg);
  color: var(--lumiverse-text);
  font: inherit;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 400;
  transition: border-color var(--lumiverse-transition-fast);
}

.greetingNameInput:focus {
  border-color: var(--lumiverse-primary);
}

.greetingItem {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 10px;
  background: var(--lumiverse-fill-subtle);
  border-radius: 8px;
  border: 1px solid var(--lumiverse-border);
}

.greetingList {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.greetingItemSortable {
  position: relative;
}

.greetingItemSortable .greetingHeader {
  padding-left: 28px;
}

.greetingItemDragging {
  z-index: 30;
  border-color: var(--lumiverse-primary-050);
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.3);
}

.greetingDragHandle {
  position: absolute;
  top: 10px;
  left: 9px;
  display: inline-flex;
  width: 22px;
  height: 26px;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: var(--lumiverse-text-dim);
  cursor: grab;
  touch-action: none;
}

.greetingDragHandle:hover:not(:disabled) {
  background: var(--lumiverse-fill);
  color: var(--lumiverse-text);
}

.greetingDragHandle:active:not(:disabled) {
  cursor: grabbing;
}

.greetingDragHandle:disabled {
  opacity: 0.35;
  cursor: default;
}

.greetingHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
}

.greetingLabel {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text-dim);
}

.greetingActions {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-left: auto;
}

.greetingBackgroundControl {
  position: relative;
  flex-shrink: 0;
}

.greetingBackgroundButton {
  display: inline-flex;
  width: 28px;
  height: 28px;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  padding: 0;
  border: 1px solid var(--lumiverse-border);
  border-radius: 7px;
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text-dim);
  cursor: pointer;
  transition: border-color var(--lumiverse-transition-fast), color var(--lumiverse-transition-fast);
}

.greetingBackgroundButton:hover,
.greetingBackgroundButton[aria-expanded='true'] {
  border-color: var(--lumiverse-primary);
  color: var(--lumiverse-primary);
}

.greetingBackgroundButton img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.greetingBackgroundPopover {
  position: absolute;
  z-index: 20;
  top: calc(100% + 5px);
  right: 0;
  width: min(280px, 70vw);
  max-height: 240px;
  overflow-y: auto;
  padding: 8px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 9px;
  background: var(--lumiverse-surface, var(--lumiverse-bg));
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.35);
}

.greetingBackgroundGrid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(50px, 1fr));
  gap: 6px;
}

.greetingBackgroundItem {
  aspect-ratio: 1;
  overflow: hidden;
  padding: 0;
  border: 2px solid transparent;
  border-radius: 6px;
  background: var(--lumiverse-fill-subtle);
  cursor: pointer;
}

.greetingBackgroundItem:hover,
.greetingBackgroundItemActive {
  border-color: var(--lumiverse-primary);
}

.greetingBackgroundItem img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.greetingBackgroundClear {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 7px;
  padding: 4px 7px;
  border: 0;
  border-radius: 5px;
  background: color-mix(in srgb, var(--lumiverse-error) 12%, transparent);
  color: var(--lumiverse-error);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
}

.greetingBackgroundEmpty {
  display: block;
  padding: 8px 4px;
  color: var(--lumiverse-text-dim);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  line-height: 1.4;
  text-align: center;
}

.removeBtn {
  width: 22px;
  height: 22px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 4px;
  background: transparent;
  border: none;
  color: var(--lumiverse-text-dim);
  cursor: pointer;
  transition: color var(--lumiverse-transition-fast);
}

.removeBtn:hover {
  color: var(--lumiverse-error);
}

.addBtn {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 6px 14px;
  border-radius: 8px;
  background: transparent;
  border: 1px dashed var(--lumiverse-border);
  color: var(--lumiverse-text-dim);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
  align-self: flex-start;
}

.addBtn:hover {
  border-color: var(--lumiverse-primary);
  color: var(--lumiverse-primary);
}

/* Tags */
.tagPicker {
  position: relative;
  width: 220px;
  max-width: 100%;
}

.tagSuggestions {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  z-index: 2;
  width: 100%;
  max-height: 180px;
  overflow-y: auto;
  padding: 4px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  background: var(--lumiverse-bg);
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.25);
}

.tagSuggestion {
  display: block;
  width: 100%;
  padding: 7px 8px;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: var(--lumiverse-text);
  font: inherit;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  text-align: left;
  overflow-wrap: anywhere;
  cursor: pointer;
}

.tagSuggestion:hover,
.tagSuggestion[aria-selected="true"] {
  background: var(--lumiverse-primary-015);
}

.tagsList {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  align-items: center;
}

.tag {
  display: flex;
  align-items: center;
  gap: 3px;
  padding: 2px 8px;
  border-radius: 5px;
  background: var(--lumiverse-primary-010);
  border: 1px solid var(--lumiverse-primary-020);
  color: var(--lumiverse-primary-muted);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
}

.tagRemove {
  display: flex;
  background: transparent;
  border: none;
  color: inherit;
  cursor: pointer;
  padding: 0;
  opacity: 0.6;
}

.tagRemove:hover {
  opacity: 1;
}

.tagAdd {
  display: flex;
  align-items: center;
  gap: 2px;
}

.tagInput {
  width: 100px;
  background: var(--lumiverse-bg);
  border: 1px solid var(--lumiverse-border);
  border-radius: 5px;
  padding: 3px 6px;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text);
  outline: none;
}

.tagInput:focus {
  border-color: var(--lumiverse-primary);
}

.tagAddBtn {
  width: 22px;
  height: 22px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 5px;
  background: var(--lumiverse-primary);
  border: none;
  color: var(--lumiverse-primary-contrast, #fff);
  cursor: pointer;
  transition: opacity var(--lumiverse-transition-fast);
}

.tagAddBtn:hover {
  opacity: 0.9;
}

.tagAddBtn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* Gallery */
.galleryTab {
  display: flex;
  flex-direction: column;
  gap: 14px;
  flex: 1;
  min-height: 0;
}

.galleryHeader {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex-shrink: 0;
}

.galleryScrollArea {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  position: relative;
  overscroll-behavior-y: contain;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
  scrollbar-color: color-mix(in srgb, var(--lumiverse-border) 55%, transparent) transparent;
}

.galleryScrollArea::-webkit-scrollbar {
  width: 5px;
}

.galleryScrollArea::-webkit-scrollbar-track {
  background: transparent;
}

.galleryScrollArea::-webkit-scrollbar-thumb {
  background: color-mix(in srgb, var(--lumiverse-border) 55%, transparent);
  border-radius: 999px;
}

.galleryScrollArea::-webkit-scrollbar-thumb:hover {
  background: color-mix(in srgb, var(--lumiverse-text-muted) 65%, transparent);
}

.galleryVirtualContainer {
  position: relative;
  width: 100%;
}

.galleryGridRow {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  display: grid;
  box-sizing: border-box;
  contain: layout style;
}

@media (hover: none) and (pointer: coarse) {
  .galleryScrollArea {
    scrollbar-width: none;
    -ms-overflow-style: none;
  }

  .galleryScrollArea::-webkit-scrollbar {
    width: 0;
    height: 0;
  }

  .galleryGridRow {
    will-change: auto;
  }
}

.galleryItem {
  position: relative;
  aspect-ratio: 1;
  border-radius: 8px;
  overflow: hidden;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-bg-dark);
  cursor: zoom-in;
}

.galleryItem:focus-visible {
  outline: 2px solid var(--lumiverse-primary);
  outline-offset: 2px;
}

.galleryThumb {
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
}

.galleryThumbPlaceholder {
  width: 100%;
  height: 100%;
  background: var(--lumiverse-fill-subtle);
}

.galleryReferenceBadge {
  position: absolute;
  left: 5px;
  bottom: 5px;
  max-width: calc(100% - 10px);
  padding: 3px 6px;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--lumiverse-border) 65%, transparent);
  border-radius: 5px;
  background: color-mix(in srgb, var(--lumiverse-bg-dark) 86%, transparent);
  color: var(--lumiverse-text);
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
  pointer-events: none;
  backdrop-filter: blur(5px) var(--lcs-liquid-filter, );
}

.galleryRemoveBtn {
  position: absolute;
  top: 4px;
  right: 4px;
  width: 22px;
