  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  min-height: 0;
}

/* Suppress hover effects while scrolling — uses global selector
   because child items are from a different CSS module */
.scrollContainer[data-scrolling] :global(*) {
  pointer-events: none;
