}

import { useRef, useEffect } from 'react'
import { useVirtualizer } from '@tanstack/react-virtual'
import { useScrollGate } from '@/hooks/useScrollGate'
import { getCharacterAvatarThumbUrl } from '@/lib/avatarUrls'
import { useImagePrefetch } from '@/hooks/useImagePrefetch'
import CharacterRow from './CharacterRow'
import type { Character, CharacterSummary } from '@/types/api'
import styles from './CharacterList.module.css'

interface CharacterListProps {
  characters: (Character | CharacterSummary)[]
  favorites: string[]
  batchMode: boolean
  batchSelected: string[]
  onOpen: (character: Character | CharacterSummary) => void
  onEdit: (id: string) => void
  onToggleFavorite: (id: string) => void
  onToggleBatch: (id: string) => void
}

const ROW_HEIGHT = 74
const MINIMUM_VIEWPORT_HEIGHT = ROW_HEIGHT + 20

export default function CharacterList({
  characters,
  favorites,
  batchMode,
  batchSelected,
  onOpen,
  onEdit,
  onToggleFavorite,
  onToggleBatch,
}: CharacterListProps) {
  const parentRef = useRef<HTMLDivElement>(null)
  useScrollGate(parentRef)
  const prefetchImages = useImagePrefetch()

  const virtualizer = useVirtualizer({
    count: characters.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => ROW_HEIGHT,
    getItemKey: (index) => characters[index].id,
    overscan: 10,
    paddingStart: 10,
    paddingEnd: 10,
  })

  // Prefetch avatar images for rows near the visible viewport so they're
  // already decoded when the virtualizer scrolls them into view.
  const PREFETCH_ROWS = 10
  const virtualItems = virtualizer.getVirtualItems()
  const visStart = virtualItems.length > 0 ? virtualItems[0].index : -1
  const visEnd = virtualItems.length > 0 ? virtualItems[virtualItems.length - 1].index : -1

  useEffect(() => {
    if (visStart < 0 || characters.length === 0) {
      prefetchImages([])
      return
    }
    const startIdx = Math.max(0, visStart - PREFETCH_ROWS)
    const endIdx = Math.min(characters.length, visEnd + PREFETCH_ROWS + 1)
    const urls: string[] = []

    for (let i = startIdx; i < endIdx; i++) {
      const char = characters[i]
      if (!char) continue
      // CharacterList uses ThumbUrl via CharacterRow
      const url = getCharacterAvatarThumbUrl(char)
      if (url) urls.push(url)
    }

    prefetchImages(urls)
  }, [visStart, visEnd, characters, prefetchImages])

  if (characters.length === 0) return null

  return (
    <div
      ref={parentRef}
      className={styles.scrollContainer}
      // Keep the list equivalent of one complete row visible when several
      // expanded folders compete for the browser's available height.
      style={{ minHeight: MINIMUM_VIEWPORT_HEIGHT }}
    >
      <div
        style={{
          height: virtualizer.getTotalSize(),
          position: 'relative',
          overflowAnchor: 'none',
        }}
      >
        {virtualizer.getVirtualItems().map((virtualRow) => {
          const character = characters[virtualRow.index]
          return (
            <div
              key={virtualRow.key}
              data-index={virtualRow.index}
              ref={virtualizer.measureElement}
              style={{
                position: 'absolute',
                top: 0,
                left: 0,
                right: 0,
                transform: `translateY(${virtualRow.start}px)`,
              }}
            >
              <CharacterRow
                character={character}
                isFavorite={favorites.includes(character.id)}
                isSelected={batchSelected.includes(character.id)}
                batchMode={batchMode}
                onOpen={onOpen}
                onEdit={onEdit}
                onToggleFavorite={onToggleFavorite}
                onToggleBatch={onToggleBatch}
              />
            </div>
          )
        })}
      </div>
    </div>
  )
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { useTranslation } from 'react-i18next'
import { ExternalLink, Trash2 } from 'lucide-react'
import { charactersApi, type CharacterLoraBinding } from '@/api/characters'
import { imageGenConnectionsApi } from '@/api/image-gen-connections'
import { useStore } from '@/store'
import SearchableSelect from '@/components/shared/SearchableSelect'
import { Button } from '@/components/shared/FormComponents'
import ConfirmationModal from '@/components/shared/ConfirmationModal'
import { LoraDiscoveryStatus, useLoraDiscovery, type LoraModelLoader } from '../imageGenLoraEditor'
import styles from './CharacterEditorPage.module.css'

interface CharacterLoraTabProps {
  characterId: string
}

const loadCharacterLoraModels: LoraModelLoader = (id, subtype) => imageGenConnectionsApi.modelsBySubtype(id, subtype)



export default function CharacterLoraTab({ characterId }: CharacterLoraTabProps) {
  const { t } = useTranslation('panels')
  const imageGenProfiles = useStore((s) => s.imageGenProfiles)
  const activeImageGenConnectionId = useStore((s) => s.activeImageGenConnectionId)

  const activeConnection = useMemo(
    () => imageGenProfiles.find((p) => p.id === activeImageGenConnectionId) ?? null,
    [imageGenProfiles, activeImageGenConnectionId],
  )

  const loraDiscovery = useLoraDiscovery(
    activeConnection,
    loadCharacterLoraModels,
    t('imageGenPanel.fetchLorasFailed'),
  )
  const supportsLoraDiscovery = loraDiscovery.supportsDiscovery


  const [binding, setBinding] = useState<CharacterLoraBinding | null>(null)
  const [loraName, setLoraName] = useState('')
  const [weightModel, setWeightModel] = useState('1')
  const [weightClip, setWeightClip] = useState('1')
  const [baseTags, setBaseTags] = useState('')
  const [sourceUrl, setSourceUrl] = useState('')
  const [saving, setSaving] = useState(false)
  const [confirmClear, setConfirmClear] = useState(false)
  const [statusMessage, setStatusMessage] = useState<{ kind: 'ok' | 'error'; text: string } | null>(null)

  const lastLoadedCharacterId = useRef<string | null>(null)

  useEffect(() => {
    if (lastLoadedCharacterId.current === characterId) return
    lastLoadedCharacterId.current = characterId

    charactersApi
      .getImageGenLora(characterId)
      .then((res) => {
        const b = res.binding
        setBinding(b)
        setLoraName(b?.lora_name ?? '')
        setWeightModel(b ? String(b.weight_model) : '1')
        setWeightClip(b ? String(b.weight_clip) : '1')
        setBaseTags(b?.base_tags ?? '')
        setSourceUrl(b?.source_url ?? '')
      })
      .catch((err) => {
        console.warn('[character-lora] Failed to load binding:', err)
      })
  }, [characterId])


  const handleClear = useCallback(async () => {
    setSaving(true)
    setStatusMessage(null)
    try {
      await charactersApi.deleteImageGenLora(characterId)
      setBinding(null)
      setLoraName('')
      setWeightModel('1')
      setWeightClip('1')
      setBaseTags('')
      setSourceUrl('')
      setStatusMessage({ kind: 'ok', text: t('characterEditor.imageLora.cleared') })
    } catch (err: any) {
      setStatusMessage({ kind: 'error', text: err?.message || t('characterEditor.imageLora.clearFailed') })
    } finally {
      setSaving(false)
    }
  }, [characterId, t])

  const handleSave = useCallback(async () => {
    const trimmedName = loraName.trim()
    if (!trimmedName) {
      // If the user cleared the LoRA picker/filename, treat Save as a removal
      // so they don't get stuck with a binding they can't clear.
      await handleClear()
      return
    }
    const wm = Number(weightModel)
    const wc = Number(weightClip)
    if (!Number.isFinite(wm) || !Number.isFinite(wc)) {
      setStatusMessage({ kind: 'error', text: t('characterEditor.imageLora.weightsMustBeNumbers') })
      return
    }

    setSaving(true)
    setStatusMessage(null)
    try {
      const res = await charactersApi.setImageGenLora(characterId, {
        lora_name: trimmedName,
        weight_model: wm,
        weight_clip: wc,
        base_tags: baseTags.trim() || undefined,
        source_url: sourceUrl.trim() || undefined,
      })
      setBinding(res.binding)
      setStatusMessage({ kind: 'ok', text: t('characterEditor.imageLora.saved') })
    } catch (err: any) {
      setStatusMessage({ kind: 'error', text: err?.message || t('characterEditor.imageLora.saveFailed') })
    } finally {
      setSaving(false)
    }
  }, [characterId, loraName, weightModel, weightClip, baseTags, sourceUrl, t, handleClear])

  const loraOptions = useMemo(() => {
    const seen = new Set<string>()
    const out: { value: string; label: string; sublabel?: string }[] = []
    for (const lora of loraDiscovery.loras) {
      if (seen.has(lora.id)) continue
      seen.add(lora.id)
      out.push({ value: lora.id, label: lora.label, sublabel: lora.id })
    }
    if (loraName && !seen.has(loraName)) {
      out.unshift({
        value: loraName,
        label: loraName,
        sublabel: t('characterEditor.imageLora.savedValueSublabel'),
      })
    }
    return out
  }, [loraDiscovery.loras, loraName, t])

  return (
    <div className={styles.fieldGroup} style={{ gap: 16 }}>
      <div className={styles.fieldGroup}>
        <span className={styles.fieldLabel}>{t('characterEditor.imageLora.activeConnection')}</span>
        <span className={styles.fieldHelper}>{t('characterEditor.imageLora.activeConnectionHelper')}</span>
        <div className={styles.fieldHelper}>
          {activeConnection
            ? t('characterEditor.imageLora.connectionSummary', {
                name: activeConnection.name,
                provider: activeConnection.provider,
              })
            : t('characterEditor.imageLora.noConnectionSelected')}
        </div>
      </div>

