import { memo } from 'react'
import { useTranslation } from 'react-i18next'
import { Star, Pencil } from 'lucide-react'
import { getCharacterAvatarThumbUrl } from '@/lib/avatarUrls'
import { getTagColor } from '@/lib/tagColors'
import LazyImage from '@/components/shared/LazyImage'
import type { Character, CharacterSummary } from '@/types/api'
import styles from './CharacterRow.module.css'
import clsx from 'clsx'

interface CharacterRowProps {
  character: Character | CharacterSummary
  isFavorite: boolean
  isSelected?: boolean
  batchMode?: boolean
  onOpen: (character: Character | CharacterSummary) => void
  onEdit?: (id: string) => void
  onToggleFavorite: (id: string) => void
  onToggleBatch?: (id: string) => void
}

export default memo(function CharacterRow({
  character,
  isFavorite,
  isSelected,
  batchMode,
  onOpen,
  onEdit,
  onToggleFavorite,
  onToggleBatch,
}: CharacterRowProps) {
  const { t } = useTranslation('panels')
  const avatarUrl = getCharacterAvatarThumbUrl(character) ?? ''
  const tags = character.tags?.slice(0, 3) || []

  const handleClick = () => {
    if (batchMode && onToggleBatch) {
      onToggleBatch(character.id)
    } else {
      onOpen(character)
    }
  }

  return (
    <div
      className={clsx(styles.row, isSelected && styles.selected)}
      onClick={handleClick}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => e.key === 'Enter' && handleClick()}
    >
      {batchMode && (
        <input
          type="checkbox"
          className={styles.checkbox}
          checked={isSelected}
          onChange={() => onToggleBatch?.(character.id)}
          onClick={(e) => e.stopPropagation()}
        />
      )}
      <div className={styles.avatar}>
        <LazyImage
          src={avatarUrl}
          alt={character.name}
          fallback={
            <div className={styles.avatarFallback}>
              {character.name[0]?.toUpperCase()}
            </div>
          }
        />
      </div>
      <div className={styles.info}>
        <span className={styles.name}>{character.name}</span>
        {character.creator && (
          <span className={styles.creator}>{t('characterProfile.byCreator', { creator: character.creator })}</span>
        )}
        {tags.length > 0 && (
          <div className={styles.tags}>
            {tags.map((tag) => {
              const color = getTagColor(tag)
              return (
                <span
                  key={tag}
                  className={styles.tag}
                  style={{ background: color.bg, color: color.text, borderColor: color.border }}
                >
                  {tag}
                </span>
              )
            })}
          </div>
        )}
      </div>
      {!batchMode && onEdit && (
        <button
          type="button"
          className={styles.editBtn}
          onClick={(e) => {
            e.stopPropagation()
            onEdit(character.id)
          }}
          title={t('characterBrowser.editCharacter')}
        >
          <Pencil size={12} />
        </button>
      )}
      {!batchMode && (
        <button
          type="button"
          className={clsx(styles.favBtn, isFavorite && styles.favBtnActive)}
          onClick={(e) => {
            e.stopPropagation()
            onToggleFavorite(character.id)
          }}
          title={isFavorite ? t('characterBrowser.removeFromFavorites') : t('characterBrowser.addToFavorites')}
        >
          <Star size={14} fill={isFavorite ? 'currentColor' : 'none'} />
        </button>
      )}
    </div>
  )
})

import { useEffect, useId, useRef, useState } from 'react'
import { Plus } from 'lucide-react'
import type { TagCount } from '@/types/api'
import styles from './CharacterEditorPage.module.css'

/** Reuse the library's tags without changing how character tags are saved. */
export default function CharacterTagInput({ allTags, tags, onAdd, placeholder }: {
  allTags: TagCount[]
  tags: string[]
  onAdd: (tag: string) => void
  placeholder: string
}) {
  const [draft, setDraft] = useState('')
  const [open, setOpen] = useState(false)
  const [activeTag, setActiveTag] = useState<string | null>(null)
  const listId = useId()
  const listRef = useRef<HTMLDivElement>(null)
  const suggestions = allTags.filter(({ tag }) => !tags.includes(tag) && tag.toLowerCase().includes(draft.trim().toLowerCase()))
  const activeIndex = suggestions.findIndex(({ tag }) => tag === activeTag)
  const expanded = open && suggestions.length > 0

  useEffect(() => {
    if (expanded) {
      const target = activeIndex >= 0 ? listRef.current?.children[activeIndex] : listRef.current
      target?.scrollIntoView({ block: 'nearest' })
    }
  }, [activeIndex, expanded])

  const add = (raw: string) => {
    const tag = raw.trim()
    if (!tag || tags.includes(tag)) return
    onAdd(tag)
    setDraft('')
    setActiveTag(null)
    setOpen(false)
  }

  return <div className={styles.tagPicker} onBlur={event => {
    if (!event.currentTarget.contains(event.relatedTarget)) setOpen(false)
  }}>
    <div className={styles.tagAdd}>
      <input
        type="text"
        role="combobox"
        aria-label={placeholder}
        aria-autocomplete="list"
        aria-expanded={expanded}
        aria-controls={expanded ? listId : undefined}
        aria-activedescendant={expanded && activeIndex >= 0 ? `${listId}-${activeIndex}` : undefined}
        autoComplete="off"
        className={styles.tagInput}
        value={draft}
        placeholder={placeholder}
        onFocus={() => { setOpen(true); setActiveTag(null) }}
        onClick={() => setOpen(true)}
        onChange={event => { setDraft(event.target.value); setOpen(true); setActiveTag(null) }}
        onKeyDown={event => {
          if (event.nativeEvent.isComposing) return
          if (event.key === 'Escape') {
            if (open) { event.preventDefault(); event.stopPropagation(); setOpen(false); setActiveTag(null) }
          } else if ((event.key === 'ArrowDown' || event.key === 'ArrowUp') && suggestions.length) {
            event.preventDefault()
            const next = !expanded || activeIndex < 0
              ? event.key === 'ArrowDown' ? 0 : suggestions.length - 1
              : (activeIndex + (event.key === 'ArrowDown' ? 1 : -1) + suggestions.length) % suggestions.length
            setOpen(true)
            setActiveTag(suggestions[next].tag)
          } else if (event.key === 'Enter') {
            event.preventDefault()
            add(expanded && activeIndex >= 0 ? suggestions[activeIndex].tag : draft)
          }
        }}
      />
      <button type="button" className={styles.tagAddBtn} aria-label={placeholder} onClick={() => add(draft)} disabled={!draft.trim() || tags.includes(draft.trim())}>
        <Plus size={12} />
      </button>
    </div>
    {expanded && <div ref={listRef} id={listId} role="listbox" aria-label={placeholder} className={styles.tagSuggestions}>
      {suggestions.map(({ tag }, index) => <button
        key={tag}
        id={`${listId}-${index}`}
        type="button"
        role="option"
        tabIndex={-1}
        aria-selected={index === activeIndex}
        className={styles.tagSuggestion}
        onMouseDown={event => event.preventDefault()}
        onClick={() => add(tag)}
      >{tag}</button>)}
    </div>}
  </div>
}

