import { saveConnectionFolder } from '@/hooks/useConnectionLibrary'
import ConnectionFolderField, { useConnectionFolderDraft } from '@/components/panels/connection-manager/ConnectionFolderField'
import { useState, useCallback, useEffect, useMemo, useRef } from 'react'
import { useTranslation } from 'react-i18next'
import { decisionConnectionsApi } from '@/api/decision-connections'
import { buildOpenRouterOAuthCallbackUrl } from '@/api/openrouter'
import { buildNanoGptOAuthCallbackUrl } from '@/api/nanogpt'
import { startProviderOAuthPopup } from '@/lib/providerOAuthPopup'
import { FormField, TextInput, Select, Button } from '@/components/shared/FormComponents'
import { Toggle } from '@/components/shared/Toggle'
import ModelCombobox from '@/components/panels/connection-manager/ModelCombobox'
import type { DecisionProviderInfo, DecisionConnectionProfile, CreateDecisionConnectionInput, DecisionModelInfo } from '@/types/api'
import styles from '../ConnectionManager.module.css'

interface Props {
  providers: DecisionProviderInfo[]
  profile?: DecisionConnectionProfile
  onSave: (input: CreateDecisionConnectionInput, folderId?: string) => void | Promise<void>
  onCancel: () => void
  onOAuthComplete?: (profile: DecisionConnectionProfile, created: boolean) => void
}

export default function DecisionConnectionForm({ providers, profile, onSave, onCancel, onOAuthComplete }: Props) {
  const folder = useConnectionFolderDraft('decision', profile?.id)
  const { t } = useTranslation('panels')
  const [name, setName] = useState(profile?.name || '')
  const [provider, setProvider] = useState(profile?.provider || providers[0]?.id || 'openrouter')
  const [apiKey, setApiKey] = useState('')
  const [clearKey, setClearKey] = useState(false)
  const [apiUrl, setApiUrl] = useState(profile?.api_url || '')
  const [model, setModel] = useState(profile ? profile.model : providers[0]?.capabilities.suggestedModel || '~typesafe/jev-latest')
  const [isDefault, setIsDefault] = useState(profile?.is_default || false)
  const [models, setModels] = useState<DecisionModelInfo[]>([])
  const [modelsLoading, setModelsLoading] = useState(false)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const requestVersion = useRef(0)
  const oauthCleanup = useRef<(() => void) | null>(null)
  const mounted = useRef(true)
  const [oauthLoading, setOauthLoading] = useState(false)
  const [oauthStatus, setOauthStatus] = useState<string | null>(null)
  const [authenticatedProfile, setAuthenticatedProfile] = useState<DecisionConnectionProfile | null>(null)

  const capabilities = providers.find((p) => p.id === provider)?.capabilities
  const providerOptions = providers.map((p) => ({ value: p.id, label: p.name }))
  const keyProfile = authenticatedProfile || profile
  const normalizedUrl = (value: string) => (value.trim() || capabilities?.defaultUrl || '').replace(/\/+$/, '')
  const canReuseKey = keyProfile?.has_api_key && provider === keyProfile.provider
    && normalizedUrl(apiUrl) === normalizedUrl(keyProfile.api_url)
  const supportsSignIn = provider === 'openrouter' || provider === 'nanogpt'
  const defaultEndpoint = normalizedUrl(apiUrl) === normalizedUrl('')
  const savedTargetMatches = !profile || profile.provider === provider && normalizedUrl(profile.api_url) === normalizedUrl(apiUrl)
  const unsupported = models.some((option) => option.id === model && option.protocol === 'unsupported')
  const modelOptions = useMemo(() => {
    const options = models.filter((option) => option.protocol !== 'unsupported')
    if (model && !options.some((option) => option.id === model)) return [{ id: model, label: model }, ...options]
    return options
  }, [model, models])
  const modelIds = useMemo(() => modelOptions.map((option) => option.id), [modelOptions])
  const modelLabels = useMemo(() => Object.fromEntries(modelOptions.map((option) => [option.id, option.label])), [modelOptions])

  useEffect(() => {
    requestVersion.current += 1
    setModels([])
    setModelsLoading(false)
    setError(null)
    return () => { requestVersion.current += 1 }
  }, [provider, apiUrl, apiKey, clearKey, authenticatedProfile])

  useEffect(() => {
    mounted.current = true
    return () => { mounted.current = false; oauthCleanup.current?.() }
  }, [])

  useEffect(() => { setOauthStatus(null) }, [provider, apiUrl])

  const changeProvider = (next: string) => {
    requestVersion.current += 1
    setProvider(next)
    setApiUrl('')
    setApiKey('')
    setClearKey(false)
    setModel(providers.find((p) => p.id === next)?.capabilities.suggestedModel || '')
    setModels([])
    setAuthenticatedProfile(null)
  }

  const handleSignIn = async () => {
    if (!supportsSignIn || !defaultEndpoint || !savedTargetMatches || oauthLoading || saving || !name.trim() || !model.trim() || unsupported) return
    setOauthLoading(true)
    setOauthStatus(null)
    setError(null)
    try {
      const callbackUrl = provider === 'openrouter' ? buildOpenRouterOAuthCallbackUrl() : buildNanoGptOAuthCallbackUrl()
      const flow = startProviderOAuthPopup({
        provider,
        callbackUrl,
        initiate: () => decisionConnectionsApi.initiateAuth(provider, callbackUrl, profile
          ? { connection_id: profile.id }
          : { connection: { name: name.trim(), provider, api_url: apiUrl.trim(), model: model.trim(), is_default: isDefault } }),
      })
      oauthCleanup.current = flow.cancel
      const authorization = await flow.result
      if (!authorization || !mounted.current) return
      const result = await decisionConnectionsApi.completeAuth(authorization.sessionToken, authorization.code)
      if (!mounted.current) return
      setAuthenticatedProfile(result.profile)
      setApiKey('')
      setClearKey(false)
      setOauthStatus(t('decisionConnectionForm.signInSaved'))
      if (result.created) saveConnectionFolder('decision', result.profile.id, folder.value)
      onOAuthComplete?.(result.profile, result.created)
    } catch (err: any) {
      if (mounted.current) setError(err?.body?.error || err?.message || t('decisionConnectionForm.signInFailed'))
    } finally {
      oauthCleanup.current = null
      if (mounted.current) setOauthLoading(false)
    }
  }
  const fetchModels = useCallback(async () => {
    const version = ++requestVersion.current
    setModelsLoading(true)
    setError(null)
    try {
      const result = await decisionConnectionsApi.previewModels({
        connection_id: profile?.id,
        provider,
        api_url: apiUrl.trim(),
        api_key: clearKey ? '' : apiKey.trim() || undefined,
      })
      if (version !== requestVersion.current) return
      setModels(result.models)
      if (result.error) setError(result.error)
    } catch (err: any) {
      if (version === requestVersion.current) setError(err?.body?.error || err?.message || t('decisionConnectionForm.modelError'))
    } finally {
      if (version === requestVersion.current) setModelsLoading(false)
    }
  }, [apiKey, apiUrl, clearKey, profile?.id, provider, t])

  const handleSubmit = async () => {
    if (!name.trim() || !model.trim() || saving || oauthLoading || unsupported) return
    setSaving(true)
    setError(null)
    try {
      await onSave({
        name: name.trim(), provider, api_key: clearKey ? '' : apiKey.trim() || undefined,
        api_url: apiUrl.trim(), model: model.trim(), is_default: isDefault,
      }, folder.value)
    } catch (err: any) {
      setError(err?.body?.error || err?.message || t('decisionConnectionForm.saveFailed'))
    } finally { setSaving(false) }
  }

  return (
    <div className={styles.form}>
      <fieldset disabled={oauthLoading} className={styles.formFields}>
        <FormField label={t('decisionConnectionForm.name')} required>
          <TextInput value={name} onChange={setName} placeholder={t('decisionConnectionForm.connectionName')} autoFocus={!profile} />
        </FormField>
      <ConnectionFolderField kind="decision" {...folder} />
        <FormField label={t('decisionConnectionForm.provider')}>
          <Select value={provider} onChange={changeProvider} options={providerOptions} />
        </FormField>
        {supportsSignIn && (
          <FormField label={t('decisionConnectionForm.providerSignIn')} hint={t(!defaultEndpoint
            ? 'decisionConnectionForm.signInDefaultUrl'
            : !savedTargetMatches ? 'decisionConnectionForm.signInSaveFirst'
            : profile ? 'decisionConnectionForm.signInHintExisting' : 'decisionConnectionForm.signInHintCreate')}>
            <Button variant="secondary" size="sm" onClick={handleSignIn}
              disabled={oauthLoading || saving || !defaultEndpoint || !savedTargetMatches || !name.trim() || !model.trim() || unsupported}>
              {oauthLoading ? t('decisionConnectionForm.signingIn') : t('decisionConnectionForm.signIn', { provider: providers.find((p) => p.id === provider)?.name })}
            </Button>
            {oauthStatus && <span role="status">{oauthStatus}</span>}
          </FormField>
        )}
        <FormField label={t('decisionConnectionForm.apiKey')} hint={canReuseKey && !clearKey ? t('decisionConnectionForm.keySetHint') : undefined}>
          <TextInput value={apiKey} onChange={(value) => { setApiKey(value); setClearKey(false); setOauthStatus(null) }} placeholder={canReuseKey && !clearKey ? '••••••••' : t('decisionConnectionForm.enterApiKey')} type="password" />
          {keyProfile?.has_api_key && <Toggle.Checkbox checked={clearKey} onChange={(checked) => { setClearKey(checked); setOauthStatus(null); if (checked) setApiKey('') }} label={t('decisionConnectionForm.removeKey')} />}
        </FormField>
        <FormField label={t('decisionConnectionForm.apiUrl')} hint={t('decisionConnectionForm.apiUrlHint')}>
          <TextInput value={apiUrl} onChange={setApiUrl} placeholder={capabilities?.defaultUrl || 'https://.../v1'} />
        </FormField>
        <FormField label={t('decisionConnectionForm.model')} hint={t('decisionConnectionForm.modelHint')}>
          <ModelCombobox value={model} onChange={setModel} models={modelIds} modelLabels={modelLabels} loading={modelsLoading}
            onRefresh={fetchModels} autoRefreshOnFocus refreshKey={provider + ':' + apiUrl + ':' + (profile?.id || '')}
            appearance="standard" placeholder={t('decisionConnectionForm.modelPlaceholder')} emptyMessage={t('decisionConnectionForm.noModels')} />
        </FormField>
        {unsupported && <p role="alert">{t('decisionConnectionForm.unsupportedModel')}</p>}
        {error && <p role="alert">{error}</p>}
        <FormField label="">
          <Toggle.Checkbox checked={isDefault} onChange={setIsDefault} label={t('decisionConnectionForm.setDefault')} />
        </FormField>
      </fieldset>
      <div className={styles.formActions}>
        <Button variant="ghost" size="sm" onClick={onCancel} disabled={saving}>{t('decisionConnectionForm.cancel')}</Button>
        <Button variant="primary" size="sm" onClick={handleSubmit} disabled={!name.trim() || !model.trim() || saving || oauthLoading || unsupported}>
          {profile ? t('decisionConnectionForm.save') : t('decisionConnectionForm.create')}
        </Button>
      </div>
    </div>
  )
}

import type { ConnectionPlacement } from '@/lib/connectionPlacement'
import { useConnectionRow } from '@/components/panels/connection-manager/useConnectionRow'
import { saveConnectionFolder } from '@/hooks/useConnectionLibrary'
import { useState, useEffect, useCallback } from 'react'
import { useTranslation } from 'react-i18next'

import { Trash2, Edit3, Zap, Star, Copy, MoreVertical, GripVertical } from 'lucide-react'
import { decisionConnectionsApi } from '@/api/decision-connections'
import type { DecisionConnectionProfile, DecisionProviderInfo, CreateDecisionConnectionInput } from '@/types/api'
import DecisionConnectionForm from './DecisionConnectionForm'
import ContextMenu, { type ContextMenuEntry, type ContextMenuPos } from '@/components/shared/ContextMenu'
import ProviderIcon from '@/components/shared/ProviderIcon'
import styles from '../connection-manager/ConnectionItem.module.css'
import clsx from 'clsx'

interface Props {
  placement?: ConnectionPlacement
  profile: DecisionConnectionProfile
  providers: DecisionProviderInfo[]
  onUpdate: (profile: DecisionConnectionProfile) => void
  onDuplicate: () => void
  onDelete: () => void
}

export default function DecisionConnectionItem({
  placement = 'list', profile, providers, onUpdate, onDuplicate, onDelete }: Props) {
  const { t: tc } = useTranslation('common')
  const { t } = useTranslation('panels')
  const { editing, setEditing, isRecent, ...sortable } = useConnectionRow(profile.id, placement)
  const [testing, setTesting] = useState(false)
  const [sampling, setSampling] = useState(false)
  const [testResult, setTestResult] = useState<{ success: boolean; message: string } | null>(null)
  const [menuPos, setMenuPos] = useState<ContextMenuPos | null>(null)

  useEffect(() => {
    if (!testResult) return
    const timer = setTimeout(() => setTestResult(null), 5000)
    return () => clearTimeout(timer)
  }, [testResult])

  const handleTest = useCallback(async () => {
    setTesting(true)
    setTestResult(null)
    try {
      const result = await decisionConnectionsApi.test(profile.id)
      setTestResult({ success: result.success, message: result.message })
    } catch (err: any) {
      setTestResult({ success: false, message: err.message || t('connectionItem.connectionFailed') })
    } finally {
      setTesting(false)
    }
  }, [profile.id, t])

  const handleSample = useCallback(async () => {
    setSampling(true)
    setTestResult(null)
    try {
      const result = await decisionConnectionsApi.sample(profile.id)
      setTestResult({ success: result.success, message: result.message })
    } catch (err: any) {
      setTestResult({ success: false, message: err?.body?.error || err.message || t('connectionItem.connectionFailed') })
    } finally { setSampling(false) }
  }, [profile.id, t])

  const handleSaveEdit = useCallback(async (input: CreateDecisionConnectionInput, folderId = '') => {
    const updated = await decisionConnectionsApi.update(profile.id, input)
    saveConnectionFolder('decision', profile.id, folderId)
    onUpdate(updated)
    setEditing(false)
  }, [profile.id, onUpdate, setEditing])

  const { attributes, listeners, setNodeRef, style, isDragging, handleRef } = sortable

  return (
    <div ref={setNodeRef} style={style} data-dragging={isDragging || undefined} className={clsx(styles.item, isDragging && styles.itemDragging)}>
      {editing ? (
        <DecisionConnectionForm
          providers={providers}
          profile={profile}
          onSave={handleSaveEdit}
          onCancel={() => setEditing(false)}
          onOAuthComplete={(updated) => onUpdate(updated)}
        />
      ) : (
        <>
          <div className={styles.itemRow}>
            {!isRecent && <button
              ref={handleRef}
              type="button"
              className={styles.dragHandle}
              aria-label={t('connectionItem.dragToReorder')}
              title={t('connectionItem.dragToReorder')}
              {...attributes}
              {...listeners}
            >
              <GripVertical size={16} />
            </button>}
            <div className={styles.itemBtn} onMouseDown={event => listeners?.onMouseDown?.(event)} onTouchStart={event => listeners?.onTouchStart?.(event)} style={{ cursor: 'default' }}>
              <ProviderIcon kind="decision" provider={profile.provider} size={32} iconSize={16} className={styles.itemIcon} />
              <div className={styles.itemInfo}>
                <span className={styles.itemName}>
                  {profile.name}
                  {profile.is_default && <Star size={11} className={styles.defaultStar} fill="#f5a623" />}
                </span>
                <span className={styles.itemMeta}>
                  {profile.provider}
                  {profile.model ? ` / ${profile.model}` : ''}
                </span>
              </div>
            </div>
            <div className={styles.itemActions}>
              <button type="button" className={styles.actionBtn} onClick={() => setEditing(true)} title={tc('actions.edit')}>
                <Edit3 size={13} />
              </button>
              <button
                type="button"
                className={styles.actionBtn}
                onClick={(e) => {
                  const rect = e.currentTarget.getBoundingClientRect()
                  setMenuPos({ x: rect.right, y: rect.bottom + 4 })
                }}
                title={t('connectionItem.moreActions')}
              >
                <MoreVertical size={13} />
              </button>
              <ContextMenu
                position={menuPos}
                onClose={() => setMenuPos(null)}
                items={[
                  { key: 'test', label: testing ? t('connectionItem.testing') : t('connectionItem.testConnection'), icon: <Zap size={14} />, onClick: () => { setMenuPos(null); handleTest() }, disabled: testing },
                  { key: 'sample', label: sampling ? t('decisionConnectionForm.checking') : t('decisionConnectionForm.sample'), icon: <Zap size={14} />, onClick: () => { setMenuPos(null); handleSample() }, disabled: sampling || testing || !profile.has_api_key || !profile.model },
                  { key: 'duplicate', label: t('connectionItem.duplicate'), icon: <Copy size={14} />, onClick: () => { setMenuPos(null); onDuplicate() } },
                  { key: 'div', type: 'divider' as const },
                  { key: 'delete', label: t('connectionItem.delete'), icon: <Trash2 size={14} />, onClick: () => { setMenuPos(null); onDelete() }, danger: true },
                ] satisfies ContextMenuEntry[]}
              />
            </div>
          </div>
          {testResult && (
            <div className={clsx(styles.testMessage, testResult.success ? styles.testMessageSuccess : styles.testMessageFail)}>
              {testResult.message}
            </div>
          )}
        </>
      )}
    </div>
  )
}

import ConnectionCollection from '../connection-manager/ConnectionCollection'
import { useConnectionLibrary, saveConnectionFolder } from '@/hooks/useConnectionLibrary'
import { useState, useEffect, useCallback, useMemo } from 'react'
import { Plus } from 'lucide-react'
import { useTranslation } from 'react-i18next'
import { decisionConnectionsApi } from '@/api/decision-connections'
import { listAllConnections } from '@/api/listAllConnections'
import { useStore } from '@/store'
import ConfirmationModal from '@/components/shared/ConfirmationModal'
import DecisionConnectionForm from './DecisionConnectionForm'
import DecisionConnectionItem from './DecisionConnectionItem'
import type { DecisionConnectionProfile, CreateDecisionConnectionInput } from '@/types/api'
import styles from '../ConnectionManager.module.css'
import { normalizeConnectionsOrder } from '@/store/slices/connections-order-merge'

export default function DecisionConnectionManager() {
  const { t } = useTranslation('panels')
  const profiles = useStore((s) => s.decisionProfiles)
  const setProfiles = useStore((s) => s.setDecisionProfiles)
  const addProfile = useStore((s) => s.addDecisionProfile)
  const updateProfile = useStore((s) => s.updateDecisionProfile)
  const removeProfile = useStore((s) => s.removeDecisionProfile)
  const applyProfileOrder = useStore((s) => s.applyDecisionProfileOrder)
  const providers = useStore((s) => s.decisionProviders)
  const setProviders = useStore((s) => s.setDecisionProviders)
  const setSetting = useStore((s) => s.setSetting)
  const connectionsOrder = useStore((s) => s.connectionsOrder)

  const library = useConnectionLibrary('decision')

  const orderedProfiles = useMemo(() => {
    const decisionOrder = connectionsOrder?.decision ?? []
    if (decisionOrder.length === 0) return profiles
    const byId = new Map(profiles.map((p) => [p.id, p]))
    const ordered = decisionOrder.map((id) => byId.get(id)).filter((p): p is DecisionConnectionProfile => Boolean(p))
    const seen = new Set(ordered.map((p) => p.id))
    const missing = profiles.filter((p) => !seen.has(p.id))
    return [...ordered, ...missing]
  }, [profiles, connectionsOrder])

  const [loading, setLoading] = useState(false)
  const [creating, setCreating] = useState(false)
  const [deleteTarget, setDeleteTarget] = useState<DecisionConnectionProfile | null>(null)

  useEffect(() => {
    let cancelled = false

    const storeState = useStore.getState()
    const cacheHit = storeState.decisionProfiles.length > 0 && storeState.decisionProviders.length > 0

    async function init() {
      if (!cacheHit) setLoading(true)
      try {
        const [profilesResult, providersResult] = await Promise.allSettled([
          listAllConnections(decisionConnectionsApi),
          decisionConnectionsApi.providers(),
        ])

        if (cancelled) return

        if (profilesResult.status === 'fulfilled') {
          setProfiles(profilesResult.value.data)
        }

        if (providersResult.status === 'fulfilled') {
          setProviders(providersResult.value.providers)
        }
      } catch (err) {
        console.error('[DecisionConnectionManager] Init failed:', err)
      } finally {
        if (!cancelled && !cacheHit) setLoading(false)
      }
    }

    init()
    return () => { cancelled = true }
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  const handleCreate = useCallback(async (input: CreateDecisionConnectionInput, folderId = '') => {
    const profile = await decisionConnectionsApi.create(input)
    saveConnectionFolder('decision', profile.id, folderId)
    addProfile(profile)
    if (input.is_default) {
      profiles.forEach((p) => {
        if (p.id !== profile.id && p.is_default) updateProfile(p.id, { is_default: false })
      })
    }
    setCreating(false)
  }, [profiles, addProfile, updateProfile])

  const handleOAuthComplete = useCallback((profile: DecisionConnectionProfile) => {
    addProfile(profile)
    if (profile.is_default) {
      profiles.forEach((p) => {
        if (p.id !== profile.id && p.is_default) updateProfile(p.id, { is_default: false })
      })
    }
    setCreating(false)
  }, [profiles, addProfile, updateProfile])

  const handleUpdate = useCallback((updated: DecisionConnectionProfile) => {
    updateProfile(updated.id, updated)
    if (updated.is_default) {
      profiles.forEach((p) => {
        if (p.id !== updated.id && p.is_default) updateProfile(p.id, { is_default: false })
      })
    }
  }, [profiles, updateProfile])

  const handleDuplicate = useCallback(async (id: string) => {
    try {
      const duplicated = await decisionConnectionsApi.duplicate(id)
      addProfile(duplicated)
      library.copyFolder(id, duplicated.id)
    } catch (err) {
      console.error('[DecisionConnectionManager] Failed to duplicate:', err)
    }
  }, [addProfile, library])

  const handleDelete = useCallback(async () => {
    if (!deleteTarget) return
    try {
      await decisionConnectionsApi.delete(deleteTarget.id)
      removeProfile(deleteTarget.id)
      library.forget(deleteTarget.id)
      const normalizedOrder = normalizeConnectionsOrder(connectionsOrder)
      const nextOrder = normalizedOrder.decision.filter((id) => id !== deleteTarget.id)
      setSetting('connectionsOrder', { ...normalizedOrder, decision: nextOrder })
      setDeleteTarget(null)
    } catch (err) {
      console.error('[DecisionConnectionManager] Failed to delete:', err)
    }
  }, [deleteTarget, removeProfile, connectionsOrder, setSetting, library])

  const handleReorder = (ids: string[]) => {
    applyProfileOrder(ids)
    setSetting('connectionsOrder', { ...normalizeConnectionsOrder(useStore.getState().connectionsOrder), decision: ids })
  }

  if (loading) {
    return <div className={styles.loading}>{t('decisionConnectionManager.loading')}</div>
  }

  return (
    <div className={styles.manager}>
      <ConnectionCollection kind="decision" profiles={orderedProfiles} onReorder={handleReorder}
        actions={!creating && (
          <button type="button" className={styles.createBtn} onClick={() => setCreating(true)}>
            <Plus size={14} />
            <span>{t('decisionConnectionManager.newConnection')}</span>
          </button>
        )}
        editor={creating && (
          <DecisionConnectionForm
            providers={providers}
            onSave={handleCreate}
            onCancel={() => setCreating(false)}
            onOAuthComplete={handleOAuthComplete}
          />
        )}
        emptyMessage={creating ? '' : t('decisionConnectionManager.empty')}
        renderProfile={(profile, placement) => (
          <DecisionConnectionItem
            placement={placement}
            key={profile.id}
            profile={profile}
            providers={providers}
            onUpdate={handleUpdate}
            onDuplicate={() => handleDuplicate(profile.id)}
            onDelete={() => setDeleteTarget(profile)}
          />
        )} />

      {deleteTarget && (
        <ConfirmationModal
          title={t('decisionConnectionManager.deleteTitle')}
          message={t('decisionConnectionManager.deleteMessage', { name: deleteTarget.name })}
          isOpen={true}
          variant="danger"
          confirmText={t('decisionConnectionManager.deleteConfirm')}
          onConfirm={handleDelete}
          onCancel={() => setDeleteTarget(null)}
        />
      )}
    </div>
  )
}

