import ConnectionFolderField, { useConnectionFolderDraft } from '@/components/panels/connection-manager/ConnectionFolderField'
import { useEffect, useMemo, useState } from 'react'
import { uuidv4 } from '@/lib/uuid'
import { Button, FormField, Select, TextInput } from '@/components/shared/FormComponents'
import NumericInput from '@/components/shared/NumericInput'
import ModelCombobox from '@/components/panels/connection-manager/ModelCombobox'
import { embeddingsApi, type EmbeddingConnectionProfile, type EmbeddingDriverOption } from '@/api/embeddings'
import styles from '../ConnectionManager.module.css'

export interface EmbeddingConnectionDraft extends EmbeddingConnectionProfile {
  api_key?: string
}

interface Props {
  providers: EmbeddingDriverOption[]
  profile?: EmbeddingConnectionProfile
  onSave: (profile: EmbeddingConnectionDraft, folderId?: string) => void
  onCancel: () => void
}

const DEFAULTS: Record<string, { api_url: string; model: string }> = {
  'openai-compatible': { api_url: 'https://api.openai.com/v1/embeddings', model: 'text-embedding-3-small' },
  openai: { api_url: 'https://api.openai.com/v1/embeddings', model: 'text-embedding-3-small' },
  mistral: { api_url: 'https://api.mistral.ai/v1/embeddings', model: 'mistral-embed' },
  cohere: { api_url: 'https://api.cohere.com/v2/embed', model: 'embed-v4.0' },
  openrouter: { api_url: 'https://openrouter.ai/api/v1/embeddings', model: 'text-embedding-3-small' },
  electronhub: { api_url: 'https://api.electronhub.top/v1/embeddings', model: 'text-embedding-3-small' },
  bananabread: { api_url: 'http://localhost:8008/v1/embeddings', model: 'mixedbread-ai/mxbai-embed-large-v1' },
  nanogpt: { api_url: 'https://nano-gpt.com/api/v1/embeddings', model: 'text-embedding-3-small' },
  'nvidia-nim': { api_url: 'https://integrate.api.nvidia.com/v1/embeddings', model: 'nvidia/nemotron-3-embed-1b' },
  google_vertex: { api_url: 'https://aiplatform.googleapis.com', model: 'gemini-embedding-001' },
}

function displayName(id: string): string {
  return ({
    'openai-compatible': 'OpenAI Compatible',
    openai: 'OpenAI',
    mistral: 'Mistral',
    cohere: 'Cohere',
    openrouter: 'OpenRouter',
    electronhub: 'ElectronHub',
    bananabread: 'BananaBread',
    nanogpt: 'Nano-GPT',
    'nvidia-nim': 'NVIDIA NIM',
    google_vertex: 'Google Vertex AI',
  } as Record<string, string>)[id] ?? id
}

export default function EmbeddingConnectionForm({ providers, profile, onSave, onCancel }: Props) {
  const folder = useConnectionFolderDraft('embedding', profile?.id)
  const initialProvider = profile?.provider || providers[0]?.id || 'openai-compatible'
  const [name, setName] = useState(profile?.name || displayName(initialProvider))
  const [provider, setProvider] = useState(initialProvider)
  const [apiUrl, setApiUrl] = useState(profile?.api_url || DEFAULTS[initialProvider]?.api_url || '')
  const [apiKey, setApiKey] = useState('')
  const [model, setModel] = useState(profile?.model || DEFAULTS[initialProvider]?.model || '')
  const [dimensions, setDimensions] = useState<number | null>(profile?.dimensions ?? null)
  const [vertexRegion, setVertexRegion] = useState(profile?.vertex_region || 'global')
  const [vertexProject, setVertexProject] = useState(profile?.vertex_project || '')
  const [models, setModels] = useState<string[]>([])
  const [modelLabels, setModelLabels] = useState<Record<string, string>>({})
  const [modelsLoading, setModelsLoading] = useState(false)

  const providerOptions = useMemo(() => providers.map((entry) => ({
    value: entry.id,
    label: entry.name && entry.name !== entry.id ? entry.name : displayName(entry.id),
  })), [providers])

  useEffect(() => {
    setModels([])
    setModelLabels({})
  }, [provider, apiUrl])

  const changeProvider = (next: string) => {
    setProvider(next)
    setApiUrl(DEFAULTS[next]?.api_url || '')
    setModel(DEFAULTS[next]?.model || '')
    if (!profile || name === displayName(provider)) setName(displayName(next))
  }

  const fetchModels = async () => {
    setModelsLoading(true)
    try {
      const result = await embeddingsApi.previewModels({
        ...(profile ? { profile_id: profile.id } : {}),
        provider: provider as any,
        api_url: apiUrl || undefined,
        api_key: apiKey.trim() || undefined,
      })
      setModels(result.models || [])
      setModelLabels(result.model_labels || {})
    } catch {
      setModels([])
      setModelLabels({})
    } finally {
      setModelsLoading(false)
    }
  }

  const submit = () => {
    if (!name.trim() || !model.trim()) return
    onSave({
      id: profile?.id || uuidv4(),
      name: name.trim(),
      provider,
      api_url: apiUrl.trim() || DEFAULTS[provider]?.api_url || '',
      model: model.trim(),
      dimensions,
      enabled: profile?.enabled ?? true,
      ...(provider === 'google_vertex' ? {
        vertex_region: vertexRegion.trim() || 'global',
        vertex_project: vertexProject.trim() || undefined,
      } : {}),
      ...(apiKey.trim() ? { api_key: apiKey.trim() } : {}),
    }, folder.value)
  }

  return (
    <div className={styles.form}>
      <FormField label="Connection name" required>
        <TextInput value={name} onChange={setName} autoFocus placeholder="My embedding connection" />
      </FormField>
      <ConnectionFolderField kind="embedding" {...folder} />
      <FormField label="Provider" required>
        <Select value={provider} onChange={changeProvider} options={providerOptions} />
      </FormField>
      <FormField label="API key" hint={profile?.hasSecret ? 'A key is already configured. Leave blank to keep it.' : undefined}>
        <TextInput value={apiKey} onChange={setApiKey} type="password" placeholder={profile?.hasSecret ? '••••••••' : 'Enter API key'} />
      </FormField>
      {provider === 'google_vertex' ? (
        <>
          <FormField label="Vertex project">
            <TextInput value={vertexProject} onChange={setVertexProject} placeholder="Google Cloud project ID" />
          </FormField>
          <FormField label="Vertex region">
            <TextInput value={vertexRegion} onChange={setVertexRegion} placeholder="global" />
          </FormField>
        </>
      ) : (
        <FormField label="Embedding endpoint" hint="Use the provider's embeddings endpoint, not its chat-completions endpoint.">
          <TextInput value={apiUrl} onChange={setApiUrl} placeholder="https://…/v1/embeddings" />
        </FormField>
      )}
      <FormField label="Embedding model" required hint="Refresh to browse models exposed by this endpoint.">
        <ModelCombobox
          value={model}
          onChange={setModel}
          models={models}
          modelLabels={modelLabels}
          loading={modelsLoading}
          onRefresh={fetchModels}
          autoRefreshOnFocus
          refreshKey={`${provider}:${profile?.id || apiUrl}`}
          appearance="standard"
          placeholder="Embedding model ID"
          emptyMessage="No embedding models returned"
        />
      </FormField>
      <FormField label="Dimensions" hint="Optional. Leave blank to use the model's native dimensions.">
        <NumericInput value={dimensions} onChange={setDimensions} min={1} integer allowEmpty />
      </FormField>
      <div className={styles.formActions}>
        <Button variant="ghost" size="sm" onClick={onCancel}>Cancel</Button>
        <Button variant="primary" size="sm" onClick={submit} disabled={!name.trim() || !model.trim()}>
          {profile ? 'Save' : 'Create'}
        </Button>
      </div>
    </div>
  )
}

import type { ConnectionPlacement } from '@/lib/connectionPlacement'
import { useConnectionRow } from '@/components/panels/connection-manager/useConnectionRow'
import { saveConnectionFolder } from '@/hooks/useConnectionLibrary'
import { useTranslation } from 'react-i18next'
import { useEffect, useState } from 'react'
import { Edit3, Trash2, Zap, GripVertical } from 'lucide-react'
import clsx from 'clsx'
import ProviderIcon from '@/components/shared/ProviderIcon'
import { embeddingsApi, type EmbeddingConnectionProfile, type EmbeddingDriverOption } from '@/api/embeddings'
import EmbeddingConnectionForm, { type EmbeddingConnectionDraft } from './EmbeddingConnectionForm'
import styles from '../connection-manager/ConnectionItem.module.css'

interface Props {
  placement?: ConnectionPlacement
  profile: EmbeddingConnectionProfile
  providers: EmbeddingDriverOption[]
  onUpdate: (profile: EmbeddingConnectionDraft) => Promise<boolean>
  onDelete: () => void
  disabled?: boolean
}

export default function EmbeddingConnectionItem({ placement = 'list', profile, providers, onUpdate, onDelete, disabled }: Props) {
  const { t } = useTranslation('panels')
  const { editing, setEditing, isRecent, ...sortable } = useConnectionRow(profile.id, placement)
  const { setNodeRef, style } = sortable
  const [testing, setTesting] = useState(false)
  const [testResult, setTestResult] = useState<{ success: boolean; message: string } | null>(null)

  useEffect(() => {
    if (!testResult) return
    const timer = setTimeout(() => setTestResult(null), 5000)
    return () => clearTimeout(timer)
  }, [testResult])

  const test = async () => {
    setTesting(true)
    setTestResult(null)
    try {
      const result = await embeddingsApi.testConnection(profile.id)
      setTestResult({ success: result.success, message: result.dimension ? `Connection successful (${result.dimension} dimensions)` : result.message })
    } catch (err: any) {
      setTestResult({ success: false, message: err?.body?.message || err?.message || 'Connection failed' })
    } finally {
      setTesting(false)
    }
  }

  return (
    <div ref={setNodeRef} style={style} data-dragging={sortable.isDragging || undefined} className={clsx(styles.item, sortable.isDragging && styles.itemDragging)}>
      {editing ? (
        <EmbeddingConnectionForm
          providers={providers}
          profile={profile}
          onSave={async (next, folderId = '') => {
            if (await onUpdate(next)) {
              saveConnectionFolder('embedding', profile.id, folderId)
              setEditing(false)
            }
          }}
          onCancel={() => setEditing(false)}
        />
      ) : (
        <>
          <div className={styles.itemRow}>
            {!isRecent && <button type="button" className={styles.dragHandle} {...sortable.attributes} {...sortable.listeners}
              aria-label={t('connectionItem.dragToReorder')}><GripVertical size={16} /></button>}
            <div className={styles.itemBtn} onMouseDown={event => sortable.listeners?.onMouseDown?.(event)} onTouchStart={event => sortable.listeners?.onTouchStart?.(event)} style={{ cursor: 'default' }}>
              <ProviderIcon kind="embedding" provider={profile.provider} size={32} iconSize={16} className={styles.itemIcon} />
              <div className={styles.itemInfo}>
                <span className={styles.itemName}>{profile.name || profile.provider}</span>
                <span className={styles.itemMeta}>
                  {profile.provider} / {profile.model}{profile.dimensions ? ` / ${profile.dimensions}d` : ''}
                </span>
              </div>
            </div>
            <div className={styles.itemActions}>
              <button type="button" className={clsx(styles.actionBtn, testResult?.success && styles.testSuccess, testResult && !testResult.success && styles.testFail)} onClick={test} disabled={testing} title="Test connection">
                <Zap size={13} />
              </button>
              <button type="button" className={styles.actionBtn} onClick={() => setEditing(true)} disabled={disabled} title="Edit">
                <Edit3 size={13} />
              </button>
              <button type="button" className={styles.actionBtn} onClick={onDelete} disabled={disabled} title="Delete">
                <Trash2 size={13} />
              </button>
            </div>
          </div>
          {testResult && (
            <div className={clsx(styles.testMessage, testResult.success ? styles.testMessageSuccess : styles.testMessageFail)}>
              {testResult.message}
            </div>
          )}
        </>
      )}
    </div>
  )
}

import ConnectionCollection from '../connection-manager/ConnectionCollection'
import { useConnectionLibrary, saveConnectionFolder } from '@/hooks/useConnectionLibrary'
import { reorderProfiles } from '@/store/slices/connections-order-merge'
import { useCallback, useEffect, useState } from 'react'
import { useTranslation } from 'react-i18next'
import { Plus } from 'lucide-react'
import ConfirmationModal from '@/components/shared/ConfirmationModal'
import { buildEmbeddingConfigUpdate, embeddingsApi, type EmbeddingConfigWithProfiles, type EmbeddingConnectionProfile, type EmbeddingDriverOption } from '@/api/embeddings'
import EmbeddingConnectionForm, { type EmbeddingConnectionDraft } from './EmbeddingConnectionForm'
import EmbeddingConnectionItem from './EmbeddingConnectionItem'
import styles from '../ConnectionManager.module.css'

export const EMBEDDING_CONNECTIONS_CHANGED_EVENT = 'lumiverse:embedding-connections-changed'

export default function EmbeddingConnectionManager() {
  const { t } = useTranslation('panels')
  const library = useConnectionLibrary('embedding')
  const [config, setConfig] = useState<EmbeddingConfigWithProfiles | null>(null)
  const [providers, setProviders] = useState<EmbeddingDriverOption[]>([])
  const [loading, setLoading] = useState(true)
  const [creating, setCreating] = useState(false)
  const [deleteTarget, setDeleteTarget] = useState<EmbeddingConnectionProfile | null>(null)
  const [error, setError] = useState<string | null>(null)

  const load = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const [nextConfig, providerResult] = await Promise.all([
        embeddingsApi.getConfig(),
        embeddingsApi.providers(),
      ])
      setConfig(nextConfig)
      setProviders(providerResult.providers)
    } catch (err: any) {
      setError(err?.message || 'Failed to load embedding connections')
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => { load() }, [load])

  const persist = async (next: EmbeddingConfigWithProfiles, apiKeys: Record<string, string | undefined> = {}) => {
    setError(null)
    try {
      const saved = await embeddingsApi.updateConfig(buildEmbeddingConfigUpdate(next, apiKeys))
      setConfig(saved)
      window.dispatchEvent(new CustomEvent(EMBEDDING_CONNECTIONS_CHANGED_EVENT))
      return true
    } catch (err: any) {
      setError(err?.body?.error || err?.message || 'Failed to save embedding connection')
      return false
    }
  }

  const create = async (draft: EmbeddingConnectionDraft, folderId = '') => {
    if (!config) return
    const { api_key, ...profile } = draft
    const connectionProfiles = [...(config.connectionProfiles ?? []), profile]
    const firstProfile = connectionProfiles[0]
    const next = {
      ...config,
      connectionProfiles,
      primaryProfileId: config.primaryProfileId || profile.id,
      ...(config.primaryProfileId ? {} : {
        provider: firstProfile.provider as any,
        model: firstProfile.model,
        api_url: firstProfile.api_url,
        dimensions: firstProfile.dimensions,
      }),
    }
    if (await persist(next, { [profile.id]: api_key })) {
      saveConnectionFolder('embedding', profile.id, folderId)
      setCreating(false)
    }
  }

  const update = async (draft: EmbeddingConnectionDraft) => {
    if (!config) return false
    const { api_key, ...profile } = draft
    const connectionProfiles = (config.connectionProfiles ?? []).map((entry) => entry.id === profile.id ? profile : entry)
    const primary = connectionProfiles.find((entry) => entry.id === config.primaryProfileId)
    return persist({
      ...config,
      connectionProfiles,
      ...(primary ? {
        provider: primary.provider as any,
        model: primary.model,
        api_url: primary.api_url,
        dimensions: primary.dimensions,
      } : {}),
    }, { [profile.id]: api_key })
  }

  const remove = async () => {
    if (!config || !deleteTarget) return
    const connectionProfiles = (config.connectionProfiles ?? []).filter((entry) => entry.id !== deleteTarget.id)
    const fallbackProfileIds = (config.fallbackProfileIds ?? []).filter((id) => id !== deleteTarget.id)
    const primaryProfileId = config.primaryProfileId === deleteTarget.id
      ? connectionProfiles[0]?.id ?? null
      : config.primaryProfileId
    const primary = connectionProfiles.find((entry) => entry.id === primaryProfileId)
    const saved = await persist({
      ...config,
      connectionProfiles,
      primaryProfileId,
      fallbackProfileIds,
      ...(primary ? {
        provider: primary.provider as any,
        model: primary.model,
        api_url: primary.api_url,
        dimensions: primary.dimensions,
      } : {}),
    })
    if (saved) {
      library.forget(deleteTarget.id)
      setDeleteTarget(null)
    }
  }

  const orderedProfiles = reorderProfiles(config?.connectionProfiles ?? [], library.library.profileOrder)

  if (loading) return <div className={styles.loading}>Loading embedding connections…</div>
  if (!config) return <div className={styles.empty}>{error || 'Embedding connections are unavailable.'}</div>

  const inherited = !!config.inherited

  return (
    <div className={styles.manager}>
      {inherited && <div className={styles.bindingCardHint}>Embedding connections are managed by the server owner.</div>}
      {error && <div className={styles.bindingCardHint} style={{ color: 'var(--lumiverse-error)' }}>{error}</div>}
      <ConnectionCollection kind="embedding" profiles={orderedProfiles} onReorder={library.reorderProfiles}
        actions={!creating && !inherited && (
          <button type="button" className={styles.createBtn} onClick={() => setCreating(true)}>
            <Plus size={14} />
            <span>New Embedding Connection</span>
          </button>
        )}
        editor={creating && (
          <EmbeddingConnectionForm providers={providers} onSave={create} onCancel={() => setCreating(false)} />
        )}
        emptyMessage={creating ? '' : t('connections.noMatches')}
        renderProfile={(profile, placement) => <EmbeddingConnectionItem
                placement={placement}
          profile={profile} providers={providers} onUpdate={update}
          onDelete={() => setDeleteTarget(profile)} disabled={inherited}
        />} />

      {deleteTarget && (
        <ConfirmationModal
          title="Delete Embedding Connection"
          message={`Delete “${deleteTarget.name || deleteTarget.provider}”? This cannot be undone.`}
          isOpen
          variant="danger"
          confirmText="Delete"
          onConfirm={remove}
          onCancel={() => setDeleteTarget(null)}
        />
      )}
    </div>
  )
}

