import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { createPortal } from 'react-dom'
import { Check, Edit3, FileUp, RotateCcw, Save, Trash2, X } from 'lucide-react'
import { useTranslation } from 'react-i18next'
import { imageGenConnectionsApi } from '@/api/image-gen-connections'
import type {
  ComfyUIFieldMapping,
  ComfyUIMappedFieldSemantic,
  ComfyUIWorkflowConfig,
  ComfyUIWorkflowList,
} from '@/api/image-gen-connections'
import ConfirmationModal from '@/components/shared/ConfirmationModal'
import styles from './ComfyWorkflowEditor.module.css'

interface ComfyWorkflowEditorProps {
  connectionId: string
  config: ComfyUIWorkflowConfig | null
  error: string | null
  onImportWorkflow: (workflow: unknown) => Promise<ComfyUIWorkflowConfig | null>
  onUpdateMappings: (mappings: ComfyUIFieldMapping[]) => Promise<ComfyUIWorkflowConfig | null>
  onWorkflowActivated: (config: ComfyUIWorkflowConfig) => Promise<void> | void
  onConnectionRefresh?: () => Promise<void> | void
  onClose: () => void
}

type StandardSemantic = Exclude<ComfyUIMappedFieldSemantic, 'custom'>
type RoleGroup = 'core' | 'sampling' | 'model'

interface RoleDef {
  semantic: StandardSemantic
  group: RoleGroup
  required?: boolean
}

const ROLE_DEFS: readonly RoleDef[] = [
  { semantic: 'positive_prompt', group: 'core', required: true },
  { semantic: 'negative_prompt', group: 'core' },
  { semantic: 'init_image', group: 'core' },
  { semantic: 'seed', group: 'core' },
  { semantic: 'width', group: 'core' },
  { semantic: 'height', group: 'core' },
  { semantic: 'steps', group: 'sampling' },
  { semantic: 'cfg', group: 'sampling' },
  { semantic: 'denoise', group: 'sampling' },
  { semantic: 'sampler_name', group: 'sampling' },
  { semantic: 'scheduler', group: 'sampling' },
  { semantic: 'checkpoint', group: 'model' },
  { semantic: 'unet', group: 'model' },
]

const GROUP_ORDER: readonly RoleGroup[] = ['core', 'sampling', 'model']

interface FieldTarget {
  nodeId: string
  classType: string
  title: string
  fieldName: string
}

function enumerateTargets(api: Record<string, any> | null | undefined): FieldTarget[] {
  const out: FieldTarget[] = []
  for (const [nodeId, node] of Object.entries(api ?? {})) {
    if (!node || typeof node.inputs !== 'object') continue
    const classType = String(node.class_type ?? '')
    const title = String(node._meta?.title ?? '').trim()
    for (const [fieldName, value] of Object.entries(node.inputs as Record<string, unknown>)) {
      if (Array.isArray(value) && value.length === 2 && typeof value[0] === 'string') continue
      out.push({ nodeId, classType, title, fieldName })
    }
  }
  return out
}

function targetLabel(target: FieldTarget): string {
  const node = target.title || (target.classType ? `${target.classType} #${target.nodeId}` : `#${target.nodeId}`)
  return `${node} · ${target.fieldName}`
}

export function ComfyWorkflowEditor({
  connectionId,
  config,
  error,
  onImportWorkflow,
  onUpdateMappings,
  onWorkflowActivated,
  onConnectionRefresh,
  onClose,
}: ComfyWorkflowEditorProps) {
  const { t } = useTranslation('panels')
  const { t: tc } = useTranslation('common')
  const [replacing, setReplacing] = useState(false)
  const [pasted, setPasted] = useState('')
  const [importing, setImporting] = useState(false)
  const [busy, setBusy] = useState(false)
  const [localError, setLocalError] = useState<string | null>(null)
  const fileRef = useRef<HTMLInputElement>(null)

  const [library, setLibrary] = useState<ComfyUIWorkflowList | null>(null)
  const [saveName, setSaveName] = useState('')
  const [renamingId, setRenamingId] = useState<string | null>(null)
  const [renameValue, setRenameValue] = useState('')
  const [libraryBusy, setLibraryBusy] = useState(false)
  const [pendingAction, setPendingAction] = useState<{ type: 'load' | 'delete'; id: string } | null>(null)

  useEffect(() => {
    function onKey(e: KeyboardEvent) {
      if (e.key === 'Escape' && !pendingAction) onClose()
    }
    document.addEventListener('keydown', onKey)
    return () => document.removeEventListener('keydown', onKey)
  }, [onClose, pendingAction])

  useEffect(() => {
    let cancelled = false
    imageGenConnectionsApi.listComfyUIWorkflows(connectionId)
      .then((list) => { if (!cancelled) setLibrary(list) })
      .catch(() => { if (!cancelled) setLibrary(null) })
    return () => { cancelled = true }
  }, [connectionId])

  const targets = useMemo(() => enumerateTargets(config?.workflow_api_json), [config])
  const mappings = config?.field_mappings ?? []
  const hasPositive = mappings.some((m) => m.mappedAs === 'positive_prompt')
  const customMappings = mappings.filter((m) => m.mappedAs === 'custom')
  const customKeys = useMemo(
    () => new Set(customMappings.map((m) => `${m.nodeId} ${m.fieldName}`)),
    [customMappings],
  )
  const nodeCount = config?.workflow_api_json ? Object.keys(config.workflow_api_json).length : 0

  const showImport = !config || replacing
  const savedWorkflows = useMemo(() => library?.workflows ?? [], [library?.workflows])
  const activeEntry = savedWorkflows.find((w) => w.id === library?.active_id) ?? null
  const currentUnsaved = Boolean(config) && library !== null && !activeEntry
  const pendingEntry = pendingAction ? savedWorkflows.find((w) => w.id === pendingAction.id) ?? null : null

  const refreshConnection = useCallback(async () => {
    try {
      await onConnectionRefresh?.()
    } catch {
    }
  }, [onConnectionRefresh])

  const persist = useCallback(
    async (next: ComfyUIFieldMapping[]) => {
      try {
        setBusy(true)
        setLocalError(null)
        await onUpdateMappings(next)
      } catch (err: any) {
        setLocalError(err?.message ?? t('comfyWorkflowEditor.mapFailed'))
      } finally {
        setBusy(false)
      }
    },
    [onUpdateMappings, t],
  )

  function setRole(semantic: StandardSemantic, target: FieldTarget | null) {
    const base = mappings.filter((m) => m.mappedAs !== semantic)
    if (!target) {
      void persist(base)
      return
    }
    void persist([...base, { nodeId: target.nodeId, fieldName: target.fieldName, mappedAs: semantic }])
  }

  function addCustom(target: FieldTarget) {
    if (customKeys.has(`${target.nodeId} ${target.fieldName}`)) return
    void persist([...mappings, { nodeId: target.nodeId, fieldName: target.fieldName, mappedAs: 'custom' }])
  }

  function removeCustom(mapping: ComfyUIFieldMapping) {
    void persist(
      mappings.filter(
        (m) => !(m.mappedAs === 'custom' && m.nodeId === mapping.nodeId && m.fieldName === mapping.fieldName),
      ),
    )
  }

  function currentTarget(semantic: StandardSemantic): FieldTarget | null {
    const m = mappings.find((x) => x.mappedAs === semantic)
    if (!m) return null
    return targets.find((x) => x.nodeId === m.nodeId && x.fieldName === m.fieldName) ?? null
  }

  async function runImport(raw: string) {
    let parsed: unknown
    try {
      parsed = JSON.parse(raw)
    } catch {
      setLocalError(t('comfyWorkflowEditor.invalidJson'))
      return
    }
    try {
      setImporting(true)
      setLocalError(null)
      await onImportWorkflow(parsed)
      setPasted('')
      setReplacing(false)
      try {
        setLibrary(await imageGenConnectionsApi.listComfyUIWorkflows(connectionId))
      } catch {
      }
    } catch (err: any) {
      setLocalError(err?.message ?? t('comfyWorkflowEditor.importFailed'))
    } finally {
      setImporting(false)
    }
  }

  async function onFile(file: File) {
    try {
      await runImport(await file.text())
    } catch {
      setLocalError(t('comfyWorkflowEditor.importFailed'))
    }
  }

  const saveCurrent = useCallback(async () => {
    const name = saveName.trim()
    if (!name || libraryBusy) return
    try {
      setLibraryBusy(true)
      setLocalError(null)
      setLibrary(await imageGenConnectionsApi.saveComfyUIWorkflow(connectionId, name))
      setSaveName('')
      await refreshConnection()
    } catch (err: any) {
      setLocalError(err?.message ?? t('comfyWorkflowEditor.libraryFailed'))
    } finally {
      setLibraryBusy(false)
    }
  }, [connectionId, saveName, libraryBusy, refreshConnection, t])

  const commitRename = useCallback(async () => {
    const id = renamingId
    const name = renameValue.trim()
    setRenamingId(null)
    if (!id || !name) return
    if (savedWorkflows.find((w) => w.id === id)?.name === name) return
    try {
      setLibraryBusy(true)
      setLocalError(null)
      setLibrary(await imageGenConnectionsApi.renameComfyUIWorkflow(connectionId, id, name))
      await refreshConnection()
    } catch (err: any) {
      setLocalError(err?.message ?? t('comfyWorkflowEditor.libraryFailed'))
    } finally {
      setLibraryBusy(false)
    }
  }, [connectionId, renamingId, renameValue, savedWorkflows, refreshConnection, t])

  const loadWorkflow = useCallback(async (workflowId: string) => {
    try {
      setLibraryBusy(true)
      setLocalError(null)
      const response = await imageGenConnectionsApi.activateComfyUIWorkflow(connectionId, workflowId)
      setLibrary({ workflows: response.workflows, active_id: response.active_id })
      setReplacing(false)
      await onWorkflowActivated(response.config)
      await refreshConnection()
    } catch (err: any) {
      setLocalError(err?.message ?? t('comfyWorkflowEditor.libraryFailed'))
    } finally {
      setLibraryBusy(false)
    }
  }, [connectionId, onWorkflowActivated, refreshConnection, t])

  const deleteWorkflow = useCallback(async (workflowId: string) => {
    try {
      setLibraryBusy(true)
      setLocalError(null)
      setLibrary(await imageGenConnectionsApi.deleteComfyUIWorkflow(connectionId, workflowId))
      await refreshConnection()
    } catch (err: any) {
      setLocalError(err?.message ?? t('comfyWorkflowEditor.libraryFailed'))
    } finally {
      setLibraryBusy(false)
    }
  }, [connectionId, refreshConnection, t])

  function requestLoad(workflowId: string) {
    if (workflowId === library?.active_id) return
    if (currentUnsaved) {
      setPendingAction({ type: 'load', id: workflowId })
      return
    }
    void loadWorkflow(workflowId)
  }

  function selectValue(target: FieldTarget | null): string {
    if (!target) return ''
    return `${target.nodeId} ${target.fieldName}`
  }

  function targetFromValue(value: string): FieldTarget | null {
    if (!value) return null
    const [nodeId, fieldName] = value.split(' ')
    return targets.find((t) => t.nodeId === nodeId && t.fieldName === fieldName) ?? null
  }

  const librarySection = (savedWorkflows.length > 0 || config) && (
    <section className={styles.group}>
      <p className={styles.groupLabel}>{t('comfyWorkflowEditor.savedWorkflows')}</p>
      <p className={styles.groupHint}>{t('comfyWorkflowEditor.savedHint')}</p>
      {savedWorkflows.map((workflow) => {
        const isActiveEntry = workflow.id === library?.active_id
        return (
          <div key={workflow.id} className={styles.wfRow}>
            {renamingId === workflow.id ? (
              <input
                className={styles.textInput}
                value={renameValue}
                autoFocus
                disabled={libraryBusy}
                onChange={(e) => setRenameValue(e.target.value)}
                onBlur={() => void commitRename()}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') void commitRename()
                  if (e.key === 'Escape') { e.stopPropagation(); setRenamingId(null) }
                }}
              />
            ) : (
              <>
                <span className={styles.wfName} title={workflow.name}>{workflow.name}</span>
                <span className={styles.wfMeta}>{t('comfyWorkflowEditor.nodeCount', { count: workflow.node_count })}</span>
              </>
            )}
            <div className={styles.wfActions}>
              {isActiveEntry ? (
                <span className={styles.wfBadge}>{t('comfyWorkflowEditor.active')}</span>
              ) : (
                <button
                  type="button"
                  className={styles.ghostBtn}
                  disabled={libraryBusy}
                  onClick={() => requestLoad(workflow.id)}
                >
                  {t('comfyWorkflowEditor.load')}
                </button>
              )}
              <button
                type="button"
                className={styles.removeBtn}
                disabled={libraryBusy}
                title={t('comfyWorkflowEditor.rename')}
                onClick={() => { setRenamingId(workflow.id); setRenameValue(workflow.name) }}
              >
                <Edit3 size={13} />
              </button>
              <button
                type="button"
                className={styles.removeBtn}
                disabled={libraryBusy}
                title={t('comfyWorkflowEditor.deleteSaved')}
                onClick={() => setPendingAction({ type: 'delete', id: workflow.id })}
              >
                <Trash2 size={13} />
              </button>
            </div>
          </div>
        )
      })}
      {config && (
        <div className={styles.saveRow}>
          <input
            className={styles.textInput}
            value={saveName}
            disabled={libraryBusy}
            placeholder={t('comfyWorkflowEditor.saveNamePlaceholder')}
            onChange={(e) => setSaveName(e.target.value)}
            onKeyDown={(e) => { if (e.key === 'Enter') void saveCurrent() }}
          />
          <button
            type="button"
            className={styles.ghostBtn}
            disabled={libraryBusy || !saveName.trim()}
            onClick={() => void saveCurrent()}
          >
            <Save size={13} />
            {t('comfyWorkflowEditor.saveCurrent')}
          </button>
        </div>
      )}
      {currentUnsaved && savedWorkflows.length > 0 && (
        <p className={styles.groupHint}>{t('comfyWorkflowEditor.unsavedNotice')}</p>
      )}
    </section>
  )

  return createPortal(
    <div className={styles.overlay} onClick={onClose}>
      <div className={styles.modal} onClick={(e) => e.stopPropagation()}>
        <header className={styles.header}>
          <div>
            <p className={styles.eyebrow}>{t('comfyWorkflowEditor.eyebrow')}</p>
            <h3 className={styles.title}>{t('comfyWorkflowEditor.title')}</h3>
          </div>
          <div className={styles.headerActions}>
            {config && !replacing && (
              <button type="button" className={styles.ghostBtn} onClick={() => { setReplacing(true); setLocalError(null); setPasted('') }}>
                <RotateCcw size={13} />
                {t('comfyWorkflowEditor.replace')}
              </button>
            )}
            {config && replacing && (
              <button type="button" className={styles.ghostBtn} onClick={() => { setReplacing(false); setLocalError(null) }}>
                {tc('actions.cancel')}
              </button>
            )}
            {config && !replacing && (
              <button type="button" className={styles.primaryBtn} onClick={onClose}>
                <Check size={14} />
                {tc('actions.done')}
              </button>
            )}
            <button type="button" className={styles.closeBtn} onClick={onClose} aria-label={tc('actions.close')}>
              <X size={18} />
            </button>
          </div>
        </header>

        {showImport ? (
          <div className={styles.body}>
            {savedWorkflows.length > 0 && !replacing && librarySection}
            <p className={styles.lead}>{t('comfyWorkflowEditor.importLead')}</p>
            {replacing && activeEntry && (
              <div className={styles.notice}>
                {t('comfyWorkflowEditor.replaceUpdatesActive', { name: activeEntry.name })}
              </div>
            )}
            <ol className={styles.steps}>
              <li>{t('comfyWorkflowEditor.importStep1')}</li>
              <li>{t('comfyWorkflowEditor.importStep2')}</li>
              <li>{t('comfyWorkflowEditor.importStep3')}</li>
            </ol>
            <div className={styles.importRow}>
              <button
                type="button"
                className={styles.primaryBtn}
                disabled={importing}
                onClick={() => fileRef.current?.click()}
              >
                <FileUp size={14} />
                {importing ? t('comfyWorkflowEditor.importing') : t('comfyWorkflowEditor.chooseFile')}
              </button>
              <input
                ref={fileRef}
                type="file"
                accept="application/json"
                className={styles.fileInput}
                onChange={(e) => {
                  const file = e.target.files?.[0]
                  if (file) void onFile(file)
                  e.currentTarget.value = ''
                }}
              />
              <span className={styles.importOr}>{t('comfyWorkflowEditor.or')}</span>
            </div>
            <textarea
              className={styles.paste}
              rows={8}
              value={pasted}
              onChange={(e) => setPasted(e.target.value)}
              placeholder={t('comfyWorkflowEditor.pastePlaceholder')}
            />
            <div className={styles.importActions}>
              <button
                type="button"
                className={styles.ghostBtn}
                disabled={importing || !pasted.trim()}
                onClick={() => void runImport(pasted)}
              >
                {t('comfyWorkflowEditor.importPasted')}
              </button>
            </div>
          </div>
        ) : (
          <div className={styles.body}>
            <div className={hasPositive ? styles.statusReady : styles.statusBlocked}>
              <span className={styles.statusDot} />
              <span>
                {hasPositive
                  ? t('comfyWorkflowEditor.ready')
                  : t('comfyWorkflowEditor.needsPositive')}
              </span>
              <span className={styles.statusMeta}>
                {activeEntry
                  ? `${activeEntry.name} · ${t('comfyWorkflowEditor.nodeCount', { count: nodeCount })}`
                  : t('comfyWorkflowEditor.nodeCount', { count: nodeCount })}
              </span>
            </div>

            {config?.needs_reimport && (
              <div className={styles.notice}>{t('comfyWorkflowEditor.needsReimport')}</div>
            )}

            {config?.unknown_nodes && config.unknown_nodes.length > 0 && (
              <div className={styles.warning}>
                {t('comfyWorkflowEditor.unknownNodes', {
                  count: config.unknown_nodes.length,
                  nodes: config.unknown_nodes.join(', '),
                })}
              </div>
            )}

            {librarySection}

            {GROUP_ORDER.map((group) => {
              const roles = ROLE_DEFS.filter((r) => r.group === group)
              if (roles.length === 0) return null
              return (
                <section key={group} className={styles.group}>
                  <p className={styles.groupLabel}>{t(`comfyWorkflowEditor.group.${group}`)}</p>
                  {roles.map((role) => (
                    <label key={role.semantic} className={styles.row}>
                      <span className={styles.rowLabel}>
                        {t(`comfyWorkflowEditor.role.${role.semantic}`)}
                        {role.required && <span className={styles.req}>*</span>}
                      </span>
                      <select
                        className={styles.select}
                        disabled={busy}
                        value={selectValue(currentTarget(role.semantic))}
                        onChange={(e) => setRole(role.semantic, targetFromValue(e.target.value))}
                      >
                        <option value="">{t('comfyWorkflowEditor.notMapped')}</option>
                        {targets.map((target) => (
                          <option key={selectValue(target)} value={selectValue(target)}>
                            {targetLabel(target)}
                          </option>
                        ))}
                      </select>
                    </label>
                  ))}
                </section>
              )
            })}

            <section className={styles.group}>
              <p className={styles.groupLabel}>{t('comfyWorkflowEditor.group.custom')}</p>
              <p className={styles.groupHint}>{t('comfyWorkflowEditor.customHint')}</p>
              {customMappings.map((m) => {
                const target = targets.find((x) => x.nodeId === m.nodeId && x.fieldName === m.fieldName)
                return (
                  <div key={`${m.nodeId} ${m.fieldName}`} className={styles.customRow}>
                    <span className={styles.customLabel}>
                      {target ? targetLabel(target) : `#${m.nodeId} · ${m.fieldName}`}
                    </span>
                    <button type="button" className={styles.removeBtn} disabled={busy} onClick={() => removeCustom(m)}>
                      <X size={13} />
                    </button>
                  </div>
                )
              })}
              <select
                className={styles.select}
                disabled={busy}
                value=""
                onChange={(e) => {
                  const target = targetFromValue(e.target.value)
                  if (target) addCustom(target)
                }}
              >
                <option value="">{t('comfyWorkflowEditor.addCustom')}</option>
                {targets
                  .filter((target) => !customKeys.has(`${target.nodeId} ${target.fieldName}`))
                  .map((target) => (
                    <option key={selectValue(target)} value={selectValue(target)}>
                      {targetLabel(target)}
                    </option>
                  ))}
              </select>
            </section>
          </div>
        )}

        {(error || localError) && <div className={styles.error}>{error || localError}</div>}

        {pendingAction && pendingEntry && (
          <ConfirmationModal
            isOpen={true}
            zIndex={10006}
            variant={pendingAction.type === 'delete' ? 'danger' : 'safe'}
            title={pendingAction.type === 'delete'
              ? t('comfyWorkflowEditor.confirmDeleteTitle')
              : t('comfyWorkflowEditor.confirmLoadTitle')}
            message={pendingAction.type === 'delete'
              ? t('comfyWorkflowEditor.confirmDeleteMessage', { name: pendingEntry.name })
              : t('comfyWorkflowEditor.confirmLoadUnsaved', { name: pendingEntry.name })}
            confirmText={pendingAction.type === 'delete'
              ? t('comfyWorkflowEditor.deleteSaved')
              : t('comfyWorkflowEditor.load')}
            onConfirm={() => {
              const action = pendingAction
              setPendingAction(null)
              if (action.type === 'delete') void deleteWorkflow(action.id)
              else void loadWorkflow(action.id)
            }}
            onCancel={() => setPendingAction(null)}
          />
        )}
      </div>
    </div>,
    document.body,
  )
}

import ConnectionFolderField, { useConnectionFolderDraft } from '@/components/panels/connection-manager/ConnectionFolderField'
import { useState, useCallback, useEffect, useMemo } from 'react'
import { useTranslation } from 'react-i18next'
import { FormField, TextInput, Select, Button } from '@/components/shared/FormComponents'
import ModelCombobox from '../connection-manager/ModelCombobox'
import { Toggle } from '@/components/shared/Toggle'
import { imageGenConnectionsApi } from '@/api/image-gen-connections'
import type {
  ImageGenProviderInfo,
  ImageGenConnectionProfile,
  CreateImageGenConnectionInput,
} from '@/types/api'
import styles from '../ConnectionManager.module.css'

interface Props {
  providers: ImageGenProviderInfo[]
  profile?: ImageGenConnectionProfile
  onSave: (input: CreateImageGenConnectionInput, folderId?: string) => void
  onCancel: () => void
}

export default function ImageGenConnectionForm({ providers, profile, onSave, onCancel }: Props) {
  const folder = useConnectionFolderDraft('imageGen', profile?.id)
  const { t } = useTranslation('panels')
  const [name, setName] = useState(profile?.name || '')
  const [provider, setProvider] = useState(profile?.provider || providers[0]?.id || 'google_gemini')
  const [apiKey, setApiKey] = useState('')
  const [apiUrl, setApiUrl] = useState(profile?.api_url || '')
  const [model, setModel] = useState(profile?.model || '')
  const [isDefault, setIsDefault] = useState(profile?.is_default || false)
  const [novelAINonStreaming, setNovelAINonStreaming] = useState(profile?.metadata?.novelai?.nonStreaming === true)

  const [models, setModels] = useState<Array<{ id: string; label: string }>>([])
  const [modelsLoading, setModelsLoading] = useState(false)
  const [byopLoading, setByopLoading] = useState(false)
  const [byopStatus, setByopStatus] = useState<string | null>(null)

  const providerOptions = providers.map((p) => ({ value: p.id, label: p.name }))
  const selectedProvider = providers.find((p) => p.id === provider)
  const capabilities = selectedProvider?.capabilities
  const isPollinations = provider === 'pollinations'

  // Build model options from static list or fetched models
  const modelOptions = useMemo(() => {
    if (models.length > 0) return models
    return capabilities?.staticModels || []
  }, [models, capabilities?.staticModels])

  const modelIds = useMemo(() => modelOptions.map((m) => m.id), [modelOptions])
  const modelLabels = useMemo(() => {
    const labels: Record<string, string> = {}
    for (const m of modelOptions) labels[m.id] = m.label
    return labels
  }, [modelOptions])
  const isDynamicModelList = capabilities?.modelListStyle !== 'static'

  const fetchModels = useCallback(async () => {
    setModelsLoading(true)
    try {
      const result = await imageGenConnectionsApi.previewModels({
        connection_id: profile?.id,
        provider,
        api_url: apiUrl.trim() || undefined,
        api_key: apiKey.trim() || undefined,
      })
      if (result.models.length > 0) setModels(result.models)
    } catch {
      setModels([])
    } finally {
      setModelsLoading(false)
    }
  }, [apiKey, apiUrl, profile?.id, provider])

  useEffect(() => {
    if (profile?.id && capabilities?.modelListStyle !== 'static') {
      fetchModels()
    }
  }, [profile?.id, capabilities?.modelListStyle, fetchModels])

  useEffect(() => {
    if (!isPollinations) return

    const pendingRaw = sessionStorage.getItem('pollinations_byop_pending')
    if (!pendingRaw) return

    const hash = window.location.hash
    const params = new URLSearchParams(hash.startsWith('#') ? hash.slice(1) : hash)
    const returnedApiKey = params.get('api_key') || sessionStorage.getItem('pollinations_byop_returned_api_key')
    if (!returnedApiKey) return

    let pendingConnectionId: string | null = null
    let pendingTarget: string | null = null
    if (pendingRaw) {
      try {
        const parsed = JSON.parse(pendingRaw) as { connectionId?: string | null; target?: string | null }
        pendingConnectionId = parsed.connectionId || null
        pendingTarget = parsed.target || null
      } catch {
        pendingConnectionId = null
        pendingTarget = null
      }
    }

    if (pendingTarget && pendingTarget !== 'image-gen-connections') return

    const activeConnectionId = profile?.id || null
    if (pendingConnectionId && activeConnectionId && pendingConnectionId !== activeConnectionId) return

    const clearRedirectArtifacts = () => {
      window.history.replaceState({}, document.title, `${window.location.pathname}${window.location.search}`)
      sessionStorage.removeItem('pollinations_byop_pending')
      sessionStorage.removeItem('pollinations_byop_returned_api_key')
    }

    let cancelled = false
    const applyReturnedKey = async () => {
      setApiKey(returnedApiKey)

      if (activeConnectionId) {
        try {
          await imageGenConnectionsApi.setApiKey(activeConnectionId, returnedApiKey)
          if (!cancelled) setByopStatus(t('connectionForm.pollinationsSaved'))
        } catch {
          if (!cancelled) {
            setByopStatus(t('connectionForm.pollinationsAutoSaveFailed'))
          }
        }
      } else if (!cancelled) {
        setByopStatus(t('connectionForm.pollinationsCaptured'))
      }

      clearRedirectArtifacts()
    }

    void applyReturnedKey()
    return () => {
      cancelled = true
    }
  }, [isPollinations, profile?.id, t])

  const handlePollinationsSignIn = useCallback(async () => {
    setByopStatus(null)
    setByopLoading(true)
    try {
      const redirect_url = `${window.location.origin}${window.location.pathname}${window.location.search}`
      const result = await imageGenConnectionsApi.pollinationsAuthUrl({
        redirect_url,
        models: model.trim() || undefined,
      })
      sessionStorage.setItem(
        'pollinations_byop_pending',
        JSON.stringify({ connectionId: profile?.id || null, provider: 'pollinations', target: 'image-gen-connections' })
      )
      window.location.href = result.auth_url
    } catch (err: any) {
      const msg = String(err?.message || t('connectionForm.pollinationsStartFailed'))
      setByopStatus(msg)
      setByopLoading(false)
    }
  }, [model, profile?.id, t])

  const handleSubmit = useCallback(() => {
    if (!name.trim()) return
    onSave({
      name: name.trim(),
      provider,
      api_key: apiKey.trim() || undefined,
      api_url: apiUrl.trim(),
      model: model.trim() || undefined,
      is_default: isDefault,
      ...(provider === 'novelai' ? {
        metadata: {
          ...profile?.metadata,
          novelai: { ...profile?.metadata?.novelai, nonStreaming: novelAINonStreaming },
        },
      } : {}),
    }, folder.value)
  }, [name, provider, apiKey, apiUrl, model, isDefault, novelAINonStreaming, profile?.metadata, folder.value, onSave])

  return (
    <div className={styles.form}>
      <FormField label={t('connectionForm.name')} required>
        <TextInput value={name} onChange={setName} placeholder={t('connectionForm.connectionName')} autoFocus={!profile} />
      </FormField>
      <ConnectionFolderField kind="imageGen" {...folder} />

      <FormField label={t('connectionForm.provider')}>
        <Select value={provider} onChange={setProvider} options={providerOptions} />
      </FormField>

      {isPollinations && (
        <FormField label={t('connectionForm.pollinationsByop')} hint={t('connectionForm.pollinationsByopHint')}>
          <div className={styles.byopRow}>
            <Button
              variant="secondary"
              size="sm"
              onClick={handlePollinationsSignIn}
              disabled={byopLoading}
            >
              {byopLoading ? t('connectionForm.redirecting') : t('connectionForm.signInWithPollinations')}
            </Button>
            {byopStatus && <span className={styles.byopStatus}>{byopStatus}</span>}
          </div>
        </FormField>
      )}

      <FormField label={t('connectionForm.apiKey')} hint={profile?.has_api_key ? t('connectionForm.keyAlreadySet') : undefined}>
        <TextInput
          value={apiKey}
          onChange={setApiKey}
          placeholder={profile?.has_api_key ? '••••••••' : t('connectionForm.enterApiKey')}
          type="password"
        />
      </FormField>

      <FormField label={t('connectionForm.apiUrl')} hint={t('connectionForm.defaultApiUrlHint')}>
        <TextInput
          value={apiUrl}
          onChange={setApiUrl}
          placeholder={capabilities?.defaultUrl || 'https://...'}
        />
      </FormField>

      {provider === 'novelai' && (
        <FormField label="">
          <Toggle.Checkbox
            checked={novelAINonStreaming}
            onChange={setNovelAINonStreaming}
            label={t('imageGenConnectionForm.novelaiNonStreaming')}
            hint={t('imageGenConnectionForm.novelaiNonStreamingHint')}
          />
        </FormField>
      )}

      <FormField label={t('connectionForm.model')} hint={isDynamicModelList ? t('connectionForm.modelHint') : undefined}>
        <ModelCombobox
          value={model}
          onChange={setModel}
          models={modelIds}
          modelLabels={modelLabels}
          loading={modelsLoading}
          onRefresh={isDynamicModelList ? fetchModels : undefined}
          autoRefreshOnFocus={isDynamicModelList}
          refreshKey={`${provider}:${apiUrl}`}
          placeholder={t('imageGenConnectionForm.selectModel')}
          emptyMessage={isDynamicModelList ? t('imageGenConnectionForm.noModelsDynamic') : t('imageGenConnectionForm.noModelsStatic')}
          appearance="standard"
        />
      </FormField>

      <FormField label="">
        <Toggle.Checkbox checked={isDefault} onChange={setIsDefault} label={t('imageGenConnectionForm.setAsDefault')} />
      </FormField>

      <div className={styles.formActions}>
        <Button variant="ghost" size="sm" onClick={onCancel}>{t('connectionForm.cancel')}</Button>
        <Button variant="primary" size="sm" onClick={handleSubmit} disabled={!name.trim()}>
          {profile ? t('connectionForm.save') : t('connectionForm.create')}
        </Button>
      </div>
    </div>
  )
}

import type { ConnectionPlacement } from '@/lib/connectionPlacement'
import { useConnectionRow } from '@/components/panels/connection-manager/useConnectionRow'
import { saveConnectionFolder } from '@/hooks/useConnectionLibrary'
import { useState, useEffect, useCallback } from 'react'
import { useTranslation } from 'react-i18next'

import { Trash2, Edit3, Zap, Check, Star, Copy, MoreVertical, RefreshCw, Workflow, GripVertical } from 'lucide-react'
import { imageGenConnectionsApi } from '@/api/image-gen-connections'
import type { ComfyUIFieldMapping, ComfyUIWorkflowConfig } from '@/api/image-gen-connections'
import type { ImageGenConnectionProfile, ImageGenProviderInfo, CreateImageGenConnectionInput, NanoGptSubscriptionUsage } from '@/types/api'
import ImageGenConnectionForm from './ImageGenConnectionForm'
import { ComfyWorkflowEditor } from './ComfyWorkflowEditor'
import ContextMenu, { type ContextMenuEntry, type ContextMenuPos } from '@/components/shared/ContextMenu'
import { Spinner } from '@/components/shared/Spinner'
import ProviderIcon from '@/components/shared/ProviderIcon'
import styles from '../connection-manager/ConnectionItem.module.css'
import clsx from 'clsx'

const COMPACT_NUMBER_FORMATTER = new Intl.NumberFormat(undefined, {
  notation: 'compact',
  maximumFractionDigits: 1,
})

function formatCompactCount(value: number) {
  return COMPACT_NUMBER_FORMATTER.format(value)
}

function formatTimeUntil(resetAt: number | null, unknownLabel: string) {
  if (!resetAt) return unknownLabel

  const diffMs = Math.max(0, resetAt - Date.now())
  const totalMinutes = Math.floor(diffMs / 60000)
  const days = Math.floor(totalMinutes / (60 * 24))
  const hours = Math.floor((totalMinutes % (60 * 24)) / 60)
  const minutes = totalMinutes % 60

  if (days > 0) return `${days}d, ${hours}h`
  if (hours > 0) return `${hours}h, ${minutes}m`
  return `${minutes}m`
}

function isNanoGptSubscriptionInactive(usage: NanoGptSubscriptionUsage) {
  const state = usage.state?.toLowerCase()
  return !usage.active || state === 'disabled' || state === 'inactive' || state === 'canceled' || state === 'cancelled'
}

interface Props {
  placement?: ConnectionPlacement
  profile: ImageGenConnectionProfile
  isActive: boolean
  providers: ImageGenProviderInfo[]
  onSelect: () => void
  onUpdate: (profile: ImageGenConnectionProfile) => void
  onDuplicate: () => void
  onDelete: () => void
  nanoGptUsage: NanoGptSubscriptionUsage | null
  nanoGptUsageLoading: boolean
  onRefreshNanoGptUsage: () => void
}

export default function ImageGenConnectionItem({
  placement = 'list', profile, isActive, providers, onSelect, onUpdate, onDuplicate, onDelete,
  nanoGptUsage, nanoGptUsageLoading, onRefreshNanoGptUsage,
}: Props) {
  const { t: tc } = useTranslation('common')
  const { t } = useTranslation('panels')
  const { editing, setEditing, isRecent, ...sortable } = useConnectionRow(profile.id, placement)
  const [testing, setTesting] = useState(false)
  const [testResult, setTestResult] = useState<{ success: boolean; message: string } | null>(null)
  const [menuPos, setMenuPos] = useState<ContextMenuPos | null>(null)
  const [workflowEditorOpen, setWorkflowEditorOpen] = useState(false)
  const [workflowConfig, setWorkflowConfig] = useState<ComfyUIWorkflowConfig | null>(null)
  const [workflowError, setWorkflowError] = useState<string | null>(null)

  const isNanoGpt = profile.provider === 'nanogpt'
  const isComfyUI = profile.provider === 'comfyui'
  const showNanoGptUsage = isNanoGpt && isActive && profile.has_api_key && !editing
  const nanoGptSubscriptionInactive = nanoGptUsage ? isNanoGptSubscriptionInactive(nanoGptUsage) : false
  const nanoGptUsageRows = nanoGptUsage
    ? [
        { key: 'dailyImages', label: t('connectionItem.dailyImages'), window: nanoGptUsage.dailyImages },
      ].filter((entry): entry is typeof entry & { window: NonNullable<typeof entry.window> } => entry.window != null)
    : []

  useEffect(() => {
    if (!testResult) return
    const timer = setTimeout(() => setTestResult(null), 5000)
    return () => clearTimeout(timer)
  }, [testResult])

  const handleTest = useCallback(async () => {
    setTesting(true)
    setTestResult(null)
    try {
      const result = await imageGenConnectionsApi.test(profile.id)
      setTestResult({ success: result.success, message: result.message })
    } catch (err: any) {
      setTestResult({ success: false, message: err.message || t('connectionItem.connectionFailed') })
    } finally {
      setTesting(false)
    }
  }, [profile.id, t])

  const refreshComfyProfile = useCallback(async () => {
    try {
      onUpdate(await imageGenConnectionsApi.get(profile.id))
    } catch {
      // The workflow update already succeeded; stale list metadata is non-fatal.
    }
  }, [onUpdate, profile.id])

  const openWorkflowEditor = useCallback(async () => {
    if (!isComfyUI) return
    setMenuPos(null)
    setWorkflowEditorOpen(true)
    setWorkflowError(null)
    try {
      const configResponse = await imageGenConnectionsApi.getComfyUIWorkflowConfig(profile.id)
      setWorkflowConfig(configResponse.config)
    } catch (err: any) {
      setWorkflowError(err?.message || t('connectionItem.loadComfyWorkflowFailed'))
    }
  }, [isComfyUI, profile.id, t])

  const importComfyWorkflow = useCallback(async (workflow: unknown) => {
    const response = await imageGenConnectionsApi.importComfyUIWorkflow(profile.id, workflow)
    setWorkflowConfig(response.config)
    await refreshComfyProfile()
    return response.config
  }, [profile.id, refreshComfyProfile])

  const updateComfyMappings = useCallback(async (mappings: ComfyUIFieldMapping[]) => {
    const response = await imageGenConnectionsApi.updateComfyUIWorkflowMappings(profile.id, mappings)
    setWorkflowConfig(response.config)
    await refreshComfyProfile()
    return response.config
  }, [profile.id, refreshComfyProfile])

  const handleSaveEdit = useCallback(async (input: CreateImageGenConnectionInput, folderId = '') => {
    try {
      const updated = await imageGenConnectionsApi.update(profile.id, input)
      saveConnectionFolder('imageGen', profile.id, folderId)
      onUpdate(updated)
      setEditing(false)
    } catch (err) {
      console.error('[ImageGenConnectionItem] Failed to update:', err)
    }
  }, [profile.id, onUpdate, setEditing])

  const { attributes, listeners, setNodeRef, style, isDragging, handleRef } = sortable

  return (
    <div ref={setNodeRef} style={style} data-dragging={isDragging || undefined} className={clsx(styles.item, isDragging && styles.itemDragging, isActive && styles.itemActive)}>
      {editing ? (
        <ImageGenConnectionForm
          providers={providers}
          profile={profile}
          onSave={handleSaveEdit}
          onCancel={() => setEditing(false)}
        />
      ) : (
        <>
          <div className={styles.itemRow}>
            {!isRecent && <button
              ref={handleRef}
              type="button"
              className={styles.dragHandle}
              aria-label={t('connectionItem.dragToReorder')}
              title={t('connectionItem.dragToReorder')}
              {...attributes}
              {...listeners}
            >
              <GripVertical size={16} />
            </button>}
            <button type="button" className={styles.itemBtn} onMouseDown={event => listeners?.onMouseDown?.(event)} onTouchStart={event => listeners?.onTouchStart?.(event)} onClick={onSelect}>
              <ProviderIcon kind="imageGen" provider={profile.provider} size={32} iconSize={16} className={styles.itemIcon} />
              <div className={styles.itemInfo}>
                <span className={styles.itemName}>
                  {profile.name}
                  {profile.is_default && <Star size={11} className={styles.defaultStar} fill="#f5a623" />}
                </span>
                <span className={styles.itemMeta}>
                  {profile.provider}{profile.model ? ` / ${profile.model}` : ''}
                </span>
              </div>
              {isActive && <Check size={14} className={styles.activeCheck} />}
            </button>
            <div className={styles.itemActions}>
              <button type="button" className={styles.actionBtn} onClick={() => setEditing(true)} title={tc('actions.edit')}>
                <Edit3 size={13} />
              </button>
              <button
                type="button"
                className={styles.actionBtn}
                onClick={(e) => {
                  const rect = e.currentTarget.getBoundingClientRect()
                  setMenuPos({ x: rect.right, y: rect.bottom + 4 })
                }}
                title={t('connectionItem.moreActions')}
              >
                <MoreVertical size={13} />
              </button>
              <ContextMenu
                position={menuPos}
                onClose={() => setMenuPos(null)}
                items={[
                  { key: 'test', label: testing ? t('connectionItem.testing') : t('connectionItem.testConnection'), icon: <Zap size={14} />, onClick: () => { setMenuPos(null); handleTest() }, disabled: testing },
                  ...(isComfyUI ? [{ key: 'workflow', label: t('connectionItem.comfyWorkflow'), icon: <Workflow size={14} />, onClick: openWorkflowEditor }] : []),
                  { key: 'duplicate', label: t('connectionItem.duplicate'), icon: <Copy size={14} />, onClick: () => { setMenuPos(null); onDuplicate() } },
                  { key: 'div', type: 'divider' as const },
                  { key: 'delete', label: t('connectionItem.delete'), icon: <Trash2 size={14} />, onClick: () => { setMenuPos(null); onDelete() }, danger: true },
                ] satisfies ContextMenuEntry[]}
              />
            </div>
          </div>
          {testResult && (
            <div className={clsx(styles.testMessage, testResult.success ? styles.testMessageSuccess : styles.testMessageFail)}>
              {testResult.message}
            </div>
          )}
          {showNanoGptUsage && nanoGptUsage && (nanoGptUsageRows.length > 0 || nanoGptSubscriptionInactive) && (
            nanoGptUsageRows.length > 0
              ? nanoGptUsageRows.map(({ key, label, window: win }, idx) => (
                <div key={key} className={clsx(styles.creditsBar, styles.nanoGptUsageBar)}>
                  <div className={styles.creditCell}>
                    <span className={styles.creditLabel}>{label}</span>
                    <span className={styles.creditValue}>
                      {win.limit !== null
                        ? `${formatCompactCount(win.remaining)} / ${formatCompactCount(win.limit)}`
                        : formatCompactCount(win.remaining)}
                    </span>
                  </div>
                  <div className={styles.creditCell}>
                    <span className={styles.creditLabel}>{t('connectionItem.used')}</span>
                    <span className={styles.creditValue}>{formatCompactCount(win.used)}</span>
                  </div>
                  <div className={styles.creditCell}>
                    <span className={styles.creditLabel}>{nanoGptSubscriptionInactive ? t('connectionItem.status') : t('connectionItem.resetsIn')}</span>
                    <span className={styles.creditValue}>{nanoGptSubscriptionInactive ? t('connectionItem.inactive') : formatTimeUntil(win.resetAt, t('connectionItem.unknown'))}</span>
                  </div>
                  {idx === 0 && (
                    <button type="button" className={styles.creditsRefresh} onClick={onRefreshNanoGptUsage} disabled={nanoGptUsageLoading}>
                      {nanoGptUsageLoading ? <Spinner size={10} /> : <RefreshCw size={10} />}
                    </button>
                  )}
                </div>
              ))
              : (
                <div className={clsx(styles.creditsBar, styles.nanoGptUsageBar)}>
                  <div className={styles.creditCell}>
                    <span className={styles.creditLabel}>{t('connectionItem.status')}</span>
                    <span className={styles.creditValue}>{t('connectionItem.inactive')}</span>
                  </div>
                  <button type="button" className={styles.creditsRefresh} onClick={onRefreshNanoGptUsage} disabled={nanoGptUsageLoading}>
                    {nanoGptUsageLoading ? <Spinner size={10} /> : <RefreshCw size={10} />}
                  </button>
                </div>
              )
          )}
          {workflowEditorOpen && (
            <ComfyWorkflowEditor
              connectionId={profile.id}
              config={workflowConfig}
              error={workflowError}
              onImportWorkflow={importComfyWorkflow}
              onUpdateMappings={updateComfyMappings}
              onWorkflowActivated={setWorkflowConfig}
              onConnectionRefresh={refreshComfyProfile}
              onClose={() => setWorkflowEditorOpen(false)}
            />
          )}
        </>
      )}
    </div>
  )
}

import ConnectionCollection from '../connection-manager/ConnectionCollection'
import { useConnectionLibrary, saveConnectionFolder } from '@/hooks/useConnectionLibrary'
import { useConnectionAccount } from '@/hooks/useConnectionAccount'
import { useState, useEffect, useCallback, useMemo } from 'react'
import { Plus } from 'lucide-react'
import { useTranslation } from 'react-i18next'
import { imageGenConnectionsApi } from '@/api/image-gen-connections'
import { listAllConnections } from '@/api/listAllConnections'
import { useStore } from '@/store'
import ConfirmationModal from '@/components/shared/ConfirmationModal'
import ImageGenConnectionForm from './ImageGenConnectionForm'
import ImageGenConnectionItem from './ImageGenConnectionItem'
import type { ImageGenConnectionProfile, CreateImageGenConnectionInput } from '@/types/api'
import styles from '../ConnectionManager.module.css'
import { normalizeConnectionsOrder } from '@/store/slices/connections-order-merge'

export default function ImageGenConnectionManager() {
  const { t } = useTranslation('panels')
  const profiles = useStore((s) => s.imageGenProfiles)
  const setProfiles = useStore((s) => s.setImageGenProfiles)
  const addProfile = useStore((s) => s.addImageGenProfile)
  const updateProfile = useStore((s) => s.updateImageGenProfile)
  const removeProfile = useStore((s) => s.removeImageGenProfile)
  const applyProfileOrder = useStore((s) => s.applyImageGenProfileOrder)
  const activeId = useStore((s) => s.activeImageGenConnectionId)
  const setActive = useStore((s) => s.setActiveImageGenConnection)
  const providers = useStore((s) => s.imageGenProviders)
  const setProviders = useStore((s) => s.setImageGenProviders)
  const setSetting = useStore((s) => s.setSetting)
  const connectionsOrder = useStore((s) => s.connectionsOrder)

  const library = useConnectionLibrary('imageGen')
  const account = useConnectionAccount(profiles.find(profile => profile.id === activeId), 'imageGen')

  const orderedProfiles = useMemo(() => {
    const imageGenOrder = connectionsOrder?.imageGen ?? []
    if (imageGenOrder.length === 0) return profiles
    const byId = new Map(profiles.map((p) => [p.id, p]))
    const ordered = imageGenOrder.map((id) => byId.get(id)).filter((p): p is ImageGenConnectionProfile => Boolean(p))
    const seen = new Set(ordered.map((p) => p.id))
    const missing = profiles.filter((p) => !seen.has(p.id))
    return [...ordered, ...missing]
  }, [profiles, connectionsOrder])

  const [loading, setLoading] = useState(false)
  const [creating, setCreating] = useState(false)
  const [deleteTarget, setDeleteTarget] = useState<ImageGenConnectionProfile | null>(null)

  useEffect(() => {
    const returnedKey = sessionStorage.getItem('pollinations_byop_returned_api_key')
    const pendingRaw = sessionStorage.getItem('pollinations_byop_pending')
    if (!returnedKey || !pendingRaw) return

    try {
      const pending = JSON.parse(pendingRaw) as { target?: string; provider?: string; connectionId?: string | null }
      if (pending.target !== 'image-gen-connections') return
      if (pending.provider !== 'pollinations') return
      if (pending.connectionId) return
      setCreating(true)
    } catch {
      // ignore malformed pending state
    }
  }, [])

  // `useAppInit` preloads image-gen profiles + providers right after auth.
  // Only show the loading placeholder on a true cold mount (empty store);
  // otherwise render from the store and refresh silently in the background.
  useEffect(() => {
    let cancelled = false

    const storeState = useStore.getState()
    const cacheHit = storeState.imageGenProfiles.length > 0 && storeState.imageGenProviders.length > 0
    const expectedProfilesVersion = storeState.imageGenProfilesVersion

    async function init() {
      if (!cacheHit) setLoading(true)
      try {
        const [profilesResult, providersResult] = await Promise.allSettled([
          listAllConnections(imageGenConnectionsApi),
          imageGenConnectionsApi.providers(),
        ])

        if (cancelled) return

        if (profilesResult.status === 'fulfilled') {
          setProfiles(profilesResult.value.data, expectedProfilesVersion)
        }

        if (providersResult.status === 'fulfilled') {
          setProviders(providersResult.value.providers)
        }
      } catch (err) {
        console.error('[ImageGenConnectionManager] Init failed:', err)
      } finally {
        if (!cancelled && !cacheHit) setLoading(false)
      }
    }

    init()
    return () => { cancelled = true }
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  const handleCreate = useCallback(async (input: CreateImageGenConnectionInput, folderId = '') => {
    try {
      const profile = await imageGenConnectionsApi.create(input)
      saveConnectionFolder('imageGen', profile.id, folderId)
      addProfile(profile)
      if (input.is_default) {
        profiles.forEach((p) => {
          if (p.id !== profile.id && p.is_default) updateProfile(p.id, { is_default: false })
        })
      }
      setCreating(false)
    } catch (err) {
      console.error('[ImageGenConnectionManager] Failed to create:', err)
    }
  }, [profiles, addProfile, updateProfile])

  const handleUpdate = useCallback((updated: ImageGenConnectionProfile) => {
    updateProfile(updated.id, updated)
    if (updated.is_default) {
      profiles.forEach((p) => {
        if (p.id !== updated.id && p.is_default) updateProfile(p.id, { is_default: false })
      })
    }
  }, [profiles, updateProfile])

  const handleDuplicate = useCallback(async (id: string) => {
    try {
      const duplicated = await imageGenConnectionsApi.duplicate(id)
      addProfile(duplicated)
      library.copyFolder(id, duplicated.id)
    } catch (err) {
      console.error('[ImageGenConnectionManager] Failed to duplicate:', err)
    }
  }, [addProfile, library])

  const handleDelete = useCallback(async () => {
    if (!deleteTarget) return
    try {
      await imageGenConnectionsApi.delete(deleteTarget.id)
      removeProfile(deleteTarget.id)
      library.forget(deleteTarget.id)
      const normalizedOrder = normalizeConnectionsOrder(connectionsOrder)
      const nextOrder = normalizedOrder.imageGen.filter((id) => id !== deleteTarget.id)
      setSetting('connectionsOrder', { ...normalizedOrder, imageGen: nextOrder })
      setDeleteTarget(null)
    } catch (err) {
      console.error('[ImageGenConnectionManager] Failed to delete:', err)
    }
  }, [deleteTarget, removeProfile, connectionsOrder, setSetting, library])

  const handleReorder = (ids: string[]) => {
    applyProfileOrder(ids)
    setSetting('connectionsOrder', { ...normalizeConnectionsOrder(useStore.getState().connectionsOrder), imageGen: ids })
  }

  if (loading) {
    return <div className={styles.loading}>{t('imageGenConnectionManager.loading')}</div>
  }

  return (
    <div className={styles.manager}>
      <ConnectionCollection kind="imageGen" profiles={orderedProfiles} onReorder={handleReorder}
        actions={!creating && (
          <button type="button" className={styles.createBtn} onClick={() => setCreating(true)}>
            <Plus size={14} />
            <span>{t('imageGenConnectionManager.newConnection')}</span>
          </button>
        )}
        editor={creating && (
          <ImageGenConnectionForm
            providers={providers}
            onSave={handleCreate}
            onCancel={() => setCreating(false)}
          />
        )}
        emptyMessage={creating ? '' : t('imageGenConnectionManager.empty')}
        renderProfile={(profile, placement) => (
          <ImageGenConnectionItem
            placement={placement}
            key={profile.id}
            profile={profile}
            isActive={activeId === profile.id}
            providers={providers}
            nanoGptUsage={account.nanoGptUsage}
            nanoGptUsageLoading={account.loading}
            onRefreshNanoGptUsage={account.refresh}
            onSelect={() => setActive(profile.id)}
            onUpdate={handleUpdate}
            onDuplicate={() => handleDuplicate(profile.id)}
            onDelete={() => setDeleteTarget(profile)}
          />
        )} />

      {deleteTarget && (
        <ConfirmationModal
          title={t('imageGenConnectionManager.deleteTitle')}
          message={t('imageGenConnectionManager.deleteMessage', { name: deleteTarget.name })}
          isOpen={true}
          variant="danger"
          confirmText={t('imageGenConnectionManager.deleteConfirm')}
          onConfirm={handleDelete}
          onCancel={() => setDeleteTarget(null)}
        />
      )}
    </div>
  )
}

