.subsection {
  border-top: 1px solid var(--lumiverse-border);
}

.subsectionHeader {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
  background: var(--lumiverse-fill-subtle);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  cursor: pointer;
  color: var(--lumiverse-text);
  user-select: none;
}

.subsectionHeader:hover {
  background: color-mix(in srgb, var(--lumiverse-fill-subtle) 70%, var(--lumiverse-text-muted) 10%);
}

.subsectionTitle {
  flex: 1;
}

.countPill {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
  font-weight: 500;
  padding: 2px 8px;
  border-radius: 999px;
  background: var(--lumiverse-fill-strong, rgba(255, 255, 255, 0.04));
}

.subsectionBody {
  padding: 6px 0;
}

.emptyMessage {
  padding: 14px;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
  text-align: center;
  font-style: italic;
}

.row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 14px;
  border-top: 1px solid var(--lumiverse-border);
  transition: background var(--lumiverse-transition-fast);
}

.row:first-child {
  border-top: none;
}

.row:hover {
  background: var(--lumiverse-fill-subtle);
}

.rowMain {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.rowTitle {
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text);
  font-weight: 500;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.rowMeta {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.rowActions {
  display: flex;
  align-items: center;
  gap: 4px;
}

.rowBtn {
  background: transparent;
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text-muted);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  padding: 4px 8px;
  border-radius: 6px;
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
}

.rowBtn:hover {
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text);
  border-color: var(--lumiverse-text-muted);
}

.rowBtnDanger:hover {
  color: #ef4444;
  border-color: #ef4444;
}

.curatedBadge {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 2px 6px;
  border-radius: 4px;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  letter-spacing: 0.02em;
  background: color-mix(in srgb, var(--lumiverse-primary) 14%, transparent);
  color: var(--lumiverse-primary);
}

.statusPill {
  display: inline-flex;
  align-items: center;
  padding: 1px 6px;
  border-radius: 4px;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.statusActive { background: color-mix(in srgb, #4caf50 18%, transparent); color: #4caf50; }
.statusInactive,
.statusFormer,
.statusDormant { background: var(--lumiverse-fill-subtle); color: var(--lumiverse-text-muted); }
.statusBroken { background: color-mix(in srgb, #ef4444 18%, transparent); color: #ef4444; }

/* ── Add-relation toolbar ─────────────────────────────── */

.toolbarRow {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding: 6px 14px;
  border-top: 1px solid var(--lumiverse-border);
}

.toolbarBtn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  background: transparent;
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  padding: 4px 10px;
  border-radius: 6px;
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
}

.toolbarBtn:hover {
  background: var(--lumiverse-fill-subtle);
}

/* ── Modal contents ───────────────────────────────────── */

.iconBtn {
  background: transparent;
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text-muted);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  padding: 4px 8px;
  border-radius: 6px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  transition: all var(--lumiverse-transition-fast);
}

.iconBtn:hover {
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text);
  border-color: var(--lumiverse-text-muted);
}

.modalHeader {
  display: flex;
  align-items: center;
