  flex: 1;
}

.chatCortexToggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin: 12px 10px 0;
  padding: 10px 12px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  background: var(--lumiverse-fill-subtle);
}

.chatCortexToggleTitle {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
}

.chatCortexToggleHint {
  margin-top: 2px;
  font-size: calc(10.5px * var(--lumiverse-font-scale, 1));
  line-height: 1.35;
  color: var(--lumiverse-text-dim);
}

.toggleSwitch {
  width: 34px;
  height: 20px;
  padding: 2px;
  border: 0;
  border-radius: 999px;
  background: var(--lumiverse-border);
  cursor: pointer;
  transition: background 0.15s ease;
  flex-shrink: 0;
}

.toggleSwitchOn {
  background: var(--lumiverse-primary);
}

.toggleSwitch:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.toggleThumb {
  display: block;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: white;
  box-shadow: 0 1px 2px rgb(0 0 0 / 20%);
  transition: transform 0.15s ease;
}

.toggleSwitchOn .toggleThumb {
  transform: translateX(14px);
}

.statsGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  padding: 12px 10px;
  align-content: start;
}

.statCard {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 12px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  transition: border-color 0.15s ease;
}

.statCardClickable {
  cursor: pointer;
}

.statCard:hover {
  border-color: color-mix(in srgb, var(--lumiverse-primary) 25%, var(--lumiverse-border));
}

.statCardClickable:hover {
  background: var(--lumiverse-fill-subtle);
}

.statArrow {
  color: var(--lumiverse-text-dim);
  margin-left: auto;
  flex-shrink: 0;
  transition: transform 0.15s ease;
}

.statCardClickable:hover .statArrow {
  color: var(--lumiverse-primary);
  transform: translateX(2px);
}

.statTop {
  display: flex;
  align-items: flex-start;
  gap: 10px;
}

.statIcon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 8px;
  background: color-mix(in srgb, var(--lumiverse-primary) 10%, transparent);
  color: var(--lumiverse-primary);
  flex-shrink: 0;
}

.statContent {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.statValue {
  font-size: calc(18px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  color: var(--lumiverse-text);
  line-height: 1.1;
}

.statLabel {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  color: var(--lumiverse-text-muted);
  margin-top: 2px;
}

.statSub {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  margin-top: 1px;
}

.statDesc {
  font-size: calc(10.5px * var(--lumiverse-font-scale, 1));
  line-height: 1.5;
  color: var(--lumiverse-text-dim);
  border-top: 1px solid var(--lumiverse-border);
  padding-top: 8px;
}

/* ── Drill-down view ────────────────────────────────────────── */

.drillView {
  display: flex;
  flex-direction: column;
  height: 100%;
}

.drillBack {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 8px 10px;
  border: none;
  border-bottom: 1px solid var(--lumiverse-border);
  background: transparent;
  color: var(--lumiverse-primary);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  cursor: pointer;
  flex-shrink: 0;
  transition: background 0.15s ease;
}

.drillBack:hover {
  background: var(--lumiverse-fill-subtle);
}

.drillTitle {
  padding: 8px 12px;
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
  border-bottom: 1px solid var(--lumiverse-border);
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 8px;
}

.drillList {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 10px;
  overflow-y: auto;
  flex: 1;
  -webkit-overflow-scrolling: touch;
}

.drillRecord {
  display: flex;
  flex-direction: column;
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  flex-shrink: 0;
  overflow: hidden;
}

.drillLine {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 6px 12px;
  border-top: 1px solid color-mix(in srgb, var(--lumiverse-border) 50%, transparent);
}

.drillLine:first-child {
  border-top: none;
}

.drillContentLine {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 8px 12px;
  border-top: 1px solid color-mix(in srgb, var(--lumiverse-border) 50%, transparent);
}

.drillContentLine:first-child {
  border-top: none;
}

.drillLineLabel {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.3px;
  color: var(--lumiverse-text-dim);
  flex-shrink: 0;
}

.drillLineValue {
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text);
  text-align: right;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.drillLineContent {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  line-height: 1.5;
  color: var(--lumiverse-text-secondary);
  word-break: break-word;
}

.drillTags {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  padding: 6px 12px 8px;
  border-top: 1px solid color-mix(in srgb, var(--lumiverse-border) 50%, transparent);
}

/* ── Consolidation sections (arcs vs scenes) ──────────────── */

.drillSectionHeader {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--lumiverse-text-dim);
  padding: 8px 2px 4px;
  margin-top: 4px;
}

.drillSectionHeader:first-child {
  margin-top: 0;
}

.arcRecord {
  display: flex;
  flex-direction: column;
  border: 1px solid color-mix(in srgb, var(--lumiverse-primary) 25%, var(--lumiverse-border));
  border-radius: 8px;
  flex-shrink: 0;
  overflow: hidden;
  background: color-mix(in srgb, var(--lumiverse-primary) 3%, transparent);
}

.arcHeader {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  background: color-mix(in srgb, var(--lumiverse-primary) 8%, transparent);
}

.arcBadge {
  padding: 2px 7px;
  border-radius: 4px;
  background: color-mix(in srgb, var(--lumiverse-primary) 15%, transparent);
  border: 1px solid color-mix(in srgb, var(--lumiverse-primary) 25%, transparent);
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--lumiverse-primary);
  flex-shrink: 0;
}

.arcTitle {
  font-size: calc(12.5px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.arcSummary {
  padding: 10px 12px;
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
  line-height: 1.6;
  color: var(--lumiverse-text-secondary);
  word-break: break-word;
}

.summaryToggle {
  display: inline;
  margin-left: 5px;
  padding: 0;
  border: none;
  background: transparent;
  color: var(--lumiverse-primary);
  font: inherit;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
}

.summaryToggle:hover {
  text-decoration: underline;
}

.summaryToggle:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--lumiverse-primary) 55%, transparent);
  outline-offset: 2px;
  border-radius: 2px;
}

.arcMeta {
  display: flex;
  gap: 12px;
  padding: 6px 12px 8px;
  border-top: 1px solid color-mix(in srgb, var(--lumiverse-border) 50%, transparent);
}

.arcMetaItem {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
}

.arcMetaItem strong {
  color: var(--lumiverse-text-muted);
  font-weight: 600;
}

/* ── Heuristics Engine — Entity indicators ─────────────────── */

.provisionalBadge {
  padding: 1px 5px;
  border-radius: 3px;
  background: color-mix(in srgb, var(--lumiverse-text-dim) 15%, transparent);
  border: 1px solid color-mix(in srgb, var(--lumiverse-text-dim) 20%, transparent);
  font-size: calc(9px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.3px;
  color: var(--lumiverse-text-dim);
}

.entityCardProvisional {
  opacity: 0.65;
  border-style: dashed;
}

.factStatusBadge {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 1px 5px;
  border-radius: 3px;
  font-size: calc(9.5px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
}

.factStatusNever {
  background: color-mix(in srgb, #f59e0b 12%, transparent);
  border: 1px solid color-mix(in srgb, #f59e0b 25%, transparent);
  color: #d97706;
}

.factStatusEmpty {
  background: color-mix(in srgb, var(--lumiverse-danger, #e53e3e) 10%, transparent);
  border: 1px solid color-mix(in srgb, var(--lumiverse-danger, #e53e3e) 20%, transparent);
  color: var(--lumiverse-danger, #e53e3e);
}

/* ── Salience drill record ─────────────────────────────────── */

.salienceRecordHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 8px 12px;
  background: color-mix(in srgb, var(--lumiverse-fill-subtle) 60%, transparent);
}

.salienceScoreSection {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 1;
}

.salienceScoreBar {
  flex: 1;
  height: 6px;
  border-radius: 3px;
  background: color-mix(in srgb, var(--lumiverse-border) 60%, transparent);
  overflow: hidden;
  max-width: 120px;
}

.salienceScoreFill {
  height: 100%;
  border-radius: 3px;
  transition: width 0.3s ease;
}

.salienceScoreValue {
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  min-width: 32px;
  text-align: right;
}

.sourceBadge {
  padding: 2px 7px;
  border-radius: 4px;
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
  font-size: calc(9.5px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.3px;
  color: var(--lumiverse-text-dim);
  flex-shrink: 0;
}

.sourceBadgeSidecar {
  background: color-mix(in srgb, #8b5cf6 10%, transparent);
  border-color: color-mix(in srgb, #8b5cf6 25%, transparent);
  color: #8b5cf6;
}

.salienceSignals {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  padding: 6px 12px;
  border-top: 1px solid color-mix(in srgb, var(--lumiverse-border) 40%, transparent);
}

.signalActive {
  padding: 1px 6px;
  border-radius: 3px;
  background: color-mix(in srgb, var(--lumiverse-primary) 10%, transparent);
  border: 1px solid color-mix(in srgb, var(--lumiverse-primary) 20%, transparent);
  font-size: calc(9.5px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  color: var(--lumiverse-primary);
}

.signalDim {
  padding: 1px 6px;
  border-radius: 3px;
  font-size: calc(9.5px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
}

.salienceTagSection {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  padding: 4px 12px;
}

.emotionTagColored {
  padding: 2px 7px;
  border-radius: 4px;
  border: 1px solid;
  font-size: calc(10.5px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
}

.narrativeFlagTag {
  padding: 2px 7px;
  border-radius: 4px;
  background: color-mix(in srgb, #f59e0b 10%, transparent);
  border: 1px solid color-mix(in srgb, #f59e0b 25%, transparent);
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.3px;
  color: #d97706;
}

.saliencePreview {
  padding: 8px 12px;
  border-top: 1px solid color-mix(in srgb, var(--lumiverse-border) 40%, transparent);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  line-height: 1.55;
  color: var(--lumiverse-text-dim);
  font-style: italic;
  border-left: 2px solid color-mix(in srgb, var(--lumiverse-primary) 25%, transparent);
  margin: 0 8px 8px;
  border-radius: 0 0 4px 4px;
  background: color-mix(in srgb, var(--lumiverse-fill-subtle) 30%, transparent);
}

/* ── Relationship drill record ────────────────────────────── */

.relationHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 8px 12px;
  background: color-mix(in srgb, var(--lumiverse-fill-subtle) 60%, transparent);
}

.relationEdge {
  display: flex;
  align-items: center;
  gap: 6px;
  overflow: hidden;
}

.relationEntityName {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 100px;
}

.relationArrow {
  color: var(--lumiverse-text-dim);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  flex-shrink: 0;
}

.relationTypeBadge {
  padding: 2px 7px;
  border-radius: 4px;
  border: 1px solid;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.3px;
  flex-shrink: 0;
}

.relationBody {
  display: flex;
  flex-direction: column;
}

.relationFooter {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
  padding: 6px 12px 8px;
  border-top: 1px solid color-mix(in srgb, var(--lumiverse-border) 40%, transparent);
}

/* Sentiment gradient bar */
.sentimentBarContainer {
  display: flex;
  align-items: center;
  gap: 6px;
}

.sentimentTrack {
  position: relative;
  width: 60px;
  height: 4px;
  border-radius: 2px;
  background: linear-gradient(90deg,
    color-mix(in srgb, #ef4444 25%, transparent) 0%,
    color-mix(in srgb, var(--lumiverse-border) 60%, transparent) 50%,
    color-mix(in srgb, #22c55e 25%, transparent) 100%
  );
  flex-shrink: 0;
}

.sentimentCenter {
  position: absolute;
  left: 50%;
  top: -1px;
  width: 1px;
  height: 6px;
  background: var(--lumiverse-text-dim);
  opacity: 0.4;
}

.sentimentIndicator {
  position: absolute;
  top: -2px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  transform: translateX(-50%);
  border: 1.5px solid color-mix(in srgb, var(--lumiverse-bg) 80%, transparent);
  box-shadow: 0 0 3px rgba(0, 0, 0, 0.2);
}

.sentimentValue {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  font-family: monospace;
  min-width: 36px;
}

/* Salience breakdown — tiny 3-segment bar */

.salienceBar {
  display: flex;
  width: 48px;
  height: 4px;
  border-radius: 2px;
  overflow: hidden;
  background: color-mix(in srgb, var(--lumiverse-border) 50%, transparent);
  flex-shrink: 0;
}

.salienceBarSegment {
  height: 100%;
  min-width: 1px;
  transition: width 0.2s ease;
}

.salienceBarMention {
  background: var(--lumiverse-primary);
}

.salienceBarArc {
  background: #8b5cf6;
}

.salienceBarGraph {
  background: #06b6d4;
}

.salienceBarFloor {
  background: #f59e0b;
}

.salienceBarTooltip {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 6px 8px;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
}

.lastSeen {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
}

/* ── Heuristics Engine — Relation indicators ───────────────── */

.contradictionBadge {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 1px 6px;
  border-radius: 3px;
  font-size: calc(9.5px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.2px;
}

.contradictionComplex {
  background: color-mix(in srgb, #f59e0b 12%, transparent);
  border: 1px solid color-mix(in srgb, #f59e0b 25%, transparent);
  color: #d97706;
}

.contradictionSuspect {
  background: color-mix(in srgb, var(--lumiverse-danger, #e53e3e) 10%, transparent);
  border: 1px solid color-mix(in srgb, var(--lumiverse-danger, #e53e3e) 20%, transparent);
  color: var(--lumiverse-danger, #e53e3e);
}

.contradictionTemporal {
  background: color-mix(in srgb, var(--lumiverse-text-dim) 10%, transparent);
  border: 1px solid color-mix(in srgb, var(--lumiverse-text-dim) 20%, transparent);
  color: var(--lumiverse-text-dim);
  text-decoration: line-through;
}

.edgeSalienceBar {
  display: flex;
  align-items: center;
  gap: 4px;
}

.edgeSalienceTrack {
  width: 40px;
  height: 3px;
  border-radius: 1.5px;
  background: color-mix(in srgb, var(--lumiverse-border) 60%, transparent);
  overflow: hidden;
}

.edgeSalienceFill {
  height: 100%;
  border-radius: 1.5px;
  background: var(--lumiverse-primary);
  transition: width 0.2s ease;
}

.edgeSalienceLabel {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  min-width: 28px;
  text-align: right;
}

.sentimentRangeLabel {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  font-family: monospace;
}

.labelAliasList {
  display: flex;
  flex-wrap: wrap;
  gap: 3px;
}

.labelAlias {
  padding: 1px 5px;
  border-radius: 3px;
  background: var(--lumiverse-fill-subtle);
  font-size: calc(9.5px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
}

.relationMeta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding: 4px 12px 6px;
  border-top: 1px solid color-mix(in srgb, var(--lumiverse-border) 40%, transparent);
}

/* ══════════════════════════════════════════════════════════════
   Links Tab — Vault & Interlink management
   ══════════════════════════════════════════════════════════════ */

.linksContainer {
  display: flex;
  flex-direction: column;
  gap: 0;
  overflow-y: auto;
  flex: 1;
  -webkit-overflow-scrolling: touch;
}

.linksSection {
  flex: 1;
  min-height: 0;
}

.linksList {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 10px;
}

/* ── Link card ─────────────────────────────────────────────── */

.linkCard {
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr) auto;
  align-items: center;
  column-gap: 10px;
  row-gap: 4px;
  padding: 10px 12px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  border-left: 3px solid var(--lumiverse-border);
  transition: border-color 0.15s ease, opacity 0.15s ease;
}

.linkCardVault {
  border-left-color: #d97706;
}

.linkCardVault:hover {
  border-color: color-mix(in srgb, #d97706 30%, var(--lumiverse-border));
  border-left-color: #d97706;
}

.linkCardInterlink {
  border-left-color: #06b6d4;
}

.linkCardInterlink:hover {
  border-color: color-mix(in srgb, #06b6d4 30%, var(--lumiverse-border));
  border-left-color: #06b6d4;
}

.linkCardDisabled {
  opacity: 0.45;
}

.linkIcon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  border-radius: 7px;
  flex-shrink: 0;
}

.linkCardVault .linkIcon {
  background: color-mix(in srgb, #d97706 10%, transparent);
  color: #d97706;
}

.linkCardInterlink .linkIcon {
  background: color-mix(in srgb, #06b6d4 10%, transparent);
  color: #06b6d4;
}

.linkInfo {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
  min-width: 0;
}

.linkName {
  font-size: calc(12.5px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

