.panel {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
  overflow: hidden;
  container-type: inline-size;
}

/* Toolbar */
.toolbar {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 12px;
  border-bottom: 1px solid var(--lumiverse-border);
  flex-shrink: 0;
}

.searchBar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
  border-radius: 10px;
}

.searchIcon {
  color: var(--lumiverse-text-dim);
  flex-shrink: 0;
}

.searchInput {
  flex: 1;
  min-width: 0;
  background: transparent;
  border: none;
  color: var(--lumiverse-text);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  outline: none;
}

.searchInput::placeholder {
  color: var(--lumiverse-text-hint);
}

/* .iconBtn — migrated to shared Button component */

.filterTabs {
  display: flex;
  align-items: center;
  flex: 1;
  min-width: 0;
  background: var(--lumiverse-fill-subtle);
  border-radius: 6px;
  overflow: hidden;
  border: 1px solid var(--lumiverse-border);
}

.filterTab {
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 1;
  min-width: var(--lumiverse-btn-tab);
  height: var(--lumiverse-btn-tab);
  background: transparent;
  border: none;
  color: var(--lumiverse-text-dim);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
  transition: background var(--lumiverse-transition-fast), color var(--lumiverse-transition-fast);
}

.filterTab:hover {
  background: var(--lumiverse-fill-hover);
}

.filterTabActive {
  background: var(--lumiverse-primary-015);
  color: var(--lumiverse-primary-muted);
}

/* Grid — single column by default, switches to multi-column when panel is wide enough */
.grid {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 12px;
  min-height: 0;
  overflow-y: auto;
  flex: 1;
}

@container (min-width: 420px) {
  .grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
    align-items: start;
    align-content: start;
  }
}

/* Pack Card */
.card {
  min-width: 0;
  border-radius: 8px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-fill-subtle);
  cursor: pointer;
  overflow: clip;
  transition: all var(--lumiverse-transition-fast);
}

.card:hover {
  border-color: var(--lumiverse-primary);
  background: var(--lumiverse-fill);
}

.cardCover {
  position: relative;
  width: 100%;
  aspect-ratio: 3 / 4;
  overflow: clip;
  background: var(--lumiverse-border);
}

.cardCoverImg {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.cardCoverFallback {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: calc(28px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  color: var(--lumiverse-text-muted);
  background: var(--lumiverse-fill);
  text-transform: uppercase;
}

.cardBody {
  padding: 8px 10px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.cardName {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.cardAuthor {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.cardBadges {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 4px;
}

/* Detail View */
.detail {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  overflow: hidden;
}

.detailHeader {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px;
  border-bottom: 1px solid var(--lumiverse-border);
  flex-shrink: 0;
}

/* .backBtn — migrated to shared Button component */

.detailMeta {
  flex: 1;
  min-width: 0;
}

.detailName {
  font-size: calc(14px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.detailAuthor {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
}

.detailActions {
  display: flex;
  gap: 6px;
  flex-shrink: 0;
}

.detailBody {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* Section */
.section {
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  overflow: hidden;
  flex-shrink: 0;
}

.sectionHeader {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  background: var(--lumiverse-fill-subtle);
  cursor: pointer;
  user-select: none;
}

.sectionTitle {
  flex: 1;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
}

.sectionCount {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
}

.sectionAddBtn {
  display: flex;
  align-items: center;
  gap: 3px;
  padding: 2px 8px;
  border-radius: 4px;
  border: 1px solid var(--lumiverse-border);
  background: transparent;
  color: var(--lumiverse-text-dim);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
}

.sectionAddBtn:hover {
  background: var(--lumiverse-fill);
  color: var(--lumiverse-text);
}

.sectionContent {
  display: flex;
  flex-direction: column;
}

/* Lumia Item Card */
.lumiaCard {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  border-top: 1px solid var(--lumiverse-border);
  transition: background var(--lumiverse-transition-fast);
}

.lumiaCard:hover {
  background: var(--lumiverse-fill-subtle);
}

.lumiaAvatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  object-fit: cover;
  flex-shrink: 0;
}

.lumiaAvatarFallback {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--lumiverse-fill);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text-muted);
  flex-shrink: 0;
}

.lumiaInfo {
  flex: 1;
  min-width: 0;
}

.lumiaName {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  color: var(--lumiverse-text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.lumiaAuthor {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
}

.genderBadge {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  padding: 1px 5px;
  border-radius: 4px;
  background: var(--lumiverse-fill);
  color: var(--lumiverse-text-muted);
  border: 1px solid var(--lumiverse-border);
  flex-shrink: 0;
}

/* Loom Item Row */
.loomRow {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border-top: 1px solid var(--lumiverse-border);
  transition: background var(--lumiverse-transition-fast);
}

.loomRow:hover {
  background: var(--lumiverse-fill-subtle);
}

.loomName {
  flex: 1;
  min-width: 0;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.loomPreview {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 120px;
}

.categoryBadge {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  padding: 1px 6px;
  border-radius: 4px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-fill);
  color: var(--lumiverse-text-muted);
  flex-shrink: 0;
  white-space: nowrap;
}

/* Item actions */
.itemActions {
  display: flex;
  gap: 4px;
  flex-shrink: 0;
}

/* .itemActionBtn, .itemActionBtnDanger — migrated to shared Button component */

.itemActionBtnActive {
  background: rgba(139, 92, 246, 0.1);
  color: var(--lumiverse-primary);
}

/* Lumia entry wrapper (row + optional preview panel) */
.lumiaEntry {
  display: flex;
  flex-direction: column;
}

/* Lumia content preview panel */
.lumiaPreviewPanel {
  border-top: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-fill-subtle);
}

.lumiaPreviewTabs {
  display: flex;
  gap: 4px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--lumiverse-border);
}

.lumiaPreviewTab {
  padding: 3px 8px;
  border-radius: 4px;
  border: 1px solid var(--lumiverse-border);
  background: transparent;
  color: var(--lumiverse-text-muted);
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  letter-spacing: 0.5px;
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
}

.lumiaPreviewTabActive {
  background: rgba(139, 92, 246, 0.15);
  border-color: rgba(139, 92, 246, 0.4);
  color: var(--lumiverse-primary);
}

.lumiaPreviewContent {
  padding: 8px 12px;
  max-height: 150px;
  overflow-y: auto;
}

.lumiaPreviewText {
  margin: 0;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  line-height: 1.6;
  color: var(--lumiverse-text-muted);
  white-space: pre-wrap;
  word-break: break-word;
  font-family: inherit;
}

/* Empty state */
.emptyState {
  padding: 24px;
  text-align: center;
  color: var(--lumiverse-text-muted);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  grid-column: 1 / -1;
}

/* Modal overlay */
.overlay {
  position: fixed;
  inset: 0;
  height: var(--app-scaled-viewport-height, calc(100vh / var(--lumiverse-ui-scale, 1)));
  width: var(--app-scaled-viewport-width, calc(100vw / var(--lumiverse-ui-scale, 1)));
  bottom: calc(0px - var(--ios-viewport-offset, 0px));
  background: var(--lumiverse-fill-heavy);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10001;
  padding: 20px;
}

.modal {
  background: var(--lumiverse-bg);
  border: 1px solid var(--lumiverse-border);
  border-radius: 10px;
  width: 100%;
  max-width: 480px;
  display: flex;
  flex-direction: column;
  max-height: calc(90vh / var(--lumiverse-ui-scale, 1));
  overflow: hidden;
}

.modalLarge {
  max-width: 640px;
}

.modalHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px;
  border-bottom: 1px solid var(--lumiverse-border);
  flex-shrink: 0;
}

.modalTitle {
  font-size: calc(14px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
}

/* .modalCloseBtn — migrated to shared Button component */

.modalBody {
  padding: 16px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.modalFooter {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  padding: 12px 16px;
  border-top: 1px solid var(--lumiverse-border);
  flex-shrink: 0;
}

/* Form fields */
.fieldGroup {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.fieldLabel {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  color: var(--lumiverse-text-dim);
}

.fieldInput {
  padding: 7px 10px;
  border-radius: 6px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  outline: none;
  width: 100%;
  box-sizing: border-box;
}

.fieldInput:focus {
  border-color: var(--lumiverse-primary);
}

.fieldSelect {
  padding: 7px 10px;
  border-radius: 6px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  outline: none;
  width: 100%;
  box-sizing: border-box;
}

.fieldTextarea {
  padding: 7px 10px;
  border-radius: 6px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  outline: none;
  width: 100%;
  box-sizing: border-box;
  resize: vertical;
  min-height: 80px;
  font-family: inherit;
  line-height: 1.5;
}

.fieldTextarea:focus {
  border-color: var(--lumiverse-primary);
}

.charCount {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
  text-align: right;
}

/* .btnCancel, .btnSave — migrated to shared Button component */

/* Tabs in import modal */
.tabs {
  display: flex;
  border-bottom: 1px solid var(--lumiverse-border);
  padding: 0 16px;
  flex-shrink: 0;
}

.tab {
  padding: 10px 14px;
  border: none;
  border-bottom: 2px solid transparent;
  background: transparent;
  color: var(--lumiverse-text-muted);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
}

.tabActive {
  color: var(--lumiverse-primary);
  border-bottom-color: var(--lumiverse-primary);
}

.tabContent {
  padding-top: 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* Import status / error */
.importError {
  padding: 8px 12px;
  border-radius: 6px;
  background: var(--lumiverse-danger-015);
  border: 1px solid var(--lumiverse-danger-020);
  color: var(--lumiverse-error, #ef4444);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
}

.importStatus {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
  padding: 6px 0;
}

.importStatusWarn {
  color: rgb(234, 179, 8);
}

/* Lucid Cards header */
.lucidHeader {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 16px 12px;
  border-bottom: 1px solid var(--lumiverse-border);
  flex-shrink: 0;
}

.lucidHeaderIcon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: 10px;
  background: linear-gradient(135deg, var(--lumiverse-primary-020), var(--lumiverse-primary-010));
  color: var(--lumiverse-primary);
  flex-shrink: 0;
}

.lucidHeaderTitle {
  font-size: calc(14px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
}

.lucidHeaderSub {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
  margin-top: 2px;
}

/* Lucid Cards category tabs */
.lucidCategoryTabs {
  display: flex;
  gap: 0;
  padding: 0 12px;
  border-bottom: 1px solid var(--lumiverse-border);
  overflow-x: auto;
  flex-shrink: 0;
}

.lucidCategoryTab {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 10px 12px;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  color: var(--lumiverse-text-muted);
  background: transparent;
  border: none;
  border-bottom: 2px solid transparent;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.2s ease;
  flex-shrink: 0;
}

.lucidCategoryTab:hover {
  color: var(--lumiverse-text);
}

.lucidCategoryTabActive {
  color: var(--lumiverse-primary);
  border-bottom-color: var(--lumiverse-primary);
}

/* Lucid Cards scroll area */
.lucidScrollArea {
  flex: 1 1 auto;
  min-height: 0;
  max-height: 420px;
  overflow-y: auto;
  padding: 14px;
}

/* Lucid Cards pack grid — responsive, matches extension */
.lucidCardGrid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 14px;
}

/* Lucid Cards card */
.lucidCard {
  position: relative;
  background: var(--lumiverse-fill-hover);
  border-radius: 10px;
  border: 1px solid var(--lumiverse-border);
  overflow: hidden;
  cursor: pointer;
  transition: all 0.2s ease;
}

.lucidCard:hover {
  border-color: var(--lumiverse-primary);
}

.lucidCardSelected {
  border-color: var(--lumiverse-primary);
  box-shadow: 0 0 0 1px var(--lumiverse-primary);
}

.lucidCardImage {
  position: relative;
  aspect-ratio: 3 / 4;
  background: var(--lumiverse-fill-strong);
  display: flex;
  align-items: center;
  justify-content: center;
}

.lucidCardImg {
  width: 100%;
  height: 100%;
  overflow: hidden;
}

.lucidCardCheck {
  position: absolute;
  top: 7px;
  right: 7px;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--lumiverse-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--lumiverse-primary-contrast, #fff);
  opacity: 0;
  transform: scale(0.8);
  transition: all 0.2s ease;
}

.lucidCardCheckVisible {
  opacity: 1;
  transform: scale(1);
}

.lucidCardInfo {
  padding: 10px;
}

.lucidCardTitle {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
  margin-bottom: 3px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.lucidCardAuthor {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
  margin-bottom: 4px;
}

.lucidCardCounts {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-primary);
}

/* Lucid Cards state displays (loading, error, empty) */
.lucidStateCenter {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 40px 20px;
  color: var(--lumiverse-text-muted);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  text-align: center;
}

.lucidErrorText {
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
}

/* .lucidRetryBtn — migrated to shared Button component */

/* Lucid Cards footer */
.lucidFooter {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 14px;
  border-top: 1px solid var(--lumiverse-border);
  flex-shrink: 0;
}

.lucidFooterRight {
  display: flex;
  align-items: center;
  gap: 10px;
}

.lucidFooterLink {
  padding: 4px 8px;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  background: transparent;
  color: var(--lumiverse-text-muted);
  border: none;
  cursor: pointer;
  transition: color var(--lumiverse-transition-fast);
}

.lucidFooterLink:hover {
  color: var(--lumiverse-text);
}

.lucidSelectedCount {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
}

/* .lucidImportBtn — migrated to shared Button component */

/* Drop zone */
.dropZone {
  border: 2px dashed var(--lumiverse-border);
  border-radius: 8px;
  padding: 32px;
  text-align: center;
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
  color: var(--lumiverse-text-muted);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
}

.dropZone:hover,
.dropZoneActive {
  border-color: var(--lumiverse-primary);
  background: rgba(var(--lumiverse-primary-rgb, 139, 92, 246), 0.05);
}

.dropZoneText {
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  margin-bottom: 8px;
}

.dropZoneSub {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
}

/* Lucid cards grid */
.lucidGrid {
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 300px;
  overflow-y: auto;
}

.lucidItem {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 6px;
  background: var(--lumiverse-fill-subtle);
}

.lucidItemName {
  flex: 1;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  color: var(--lumiverse-text);
}

.lucidItemAuthor {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
}

.importBtn {
  padding: 4px 10px;
  border-radius: 5px;
  border: 1px solid var(--lumiverse-primary);
  background: transparent;
  color: var(--lumiverse-primary);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
  flex-shrink: 0;
}

.importBtn:hover {
  background: var(--lumiverse-primary);
  color: var(--lumiverse-primary-contrast, #fff);
}

.importBtn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

import { useState, useEffect, useCallback, useMemo } from 'react'
import { useTranslation } from 'react-i18next'
import { Plus, Upload, Search } from 'lucide-react'
import { Button } from '@/components/shared/FormComponents'
import { useStore } from '@/store'
import { packsApi } from '@/api/packs'
import type { Pack, PackWithItems } from '@/types/api'
import type { PackFilterTab } from '@/types/store'
import PackCard from './PackCard'
import PackDetailView from './PackDetailView'
import PackEditorModal from './PackEditorModal'
import ImportPackModal from './ImportPackModal'
import styles from './PackBrowser.module.css'
import clsx from 'clsx'

export default function PackBrowser() {
  const { t } = useTranslation('panels')
  const packs = useStore((s) => s.packs)
  const setPacks = useStore((s) => s.setPacks)
  const addPack = useStore((s) => s.addPack)
  const updatePackInStore = useStore((s) => s.updatePackInStore)
  const removePack = useStore((s) => s.removePack)
  const loadAvailableTools = useStore((s) => s.loadAvailableTools)
  const selectedPackId = useStore((s) => s.selectedPackId)
  const setSelectedPackId = useStore((s) => s.setSelectedPackId)
  const packSearchQuery = useStore((s) => s.packSearchQuery)
  const setPackSearchQuery = useStore((s) => s.setPackSearchQuery)
  const packFilterTab = useStore((s) => s.packFilterTab)
  const setPackFilterTab = useStore((s) => s.setPackFilterTab)

  const filterTabs = useMemo(() => [
    { id: 'all' as PackFilterTab, label: t('packBrowser.filterAll') },
    { id: 'custom' as PackFilterTab, label: t('packBrowser.filterCustom') },
    { id: 'downloaded' as PackFilterTab, label: t('packBrowser.filterDownloaded') },
  ], [t])

  const [detailPack, setDetailPack] = useState<PackWithItems | null>(null)
  const [showPackEditor, setShowPackEditor] = useState(false)
  const [editingPack, setEditingPack] = useState<Pack | null>(null)
  const [showImport, setShowImport] = useState(false)

  const loadPacks = useCallback(async () => {
    try {
      const res = await packsApi.list({ limit: 200 })
      setPacks(res.data)
    } catch {}
  }, [setPacks])

  useEffect(() => {
    loadPacks()
  }, [loadPacks])

  const loadDetail = useCallback(async (id: string) => {
    try {
      const pack = await packsApi.get(id)
      setDetailPack(pack)
      setSelectedPackId(id)
    } catch {}
  }, [setSelectedPackId])

  useEffect(() => {
    if (selectedPackId && !detailPack) {
      loadDetail(selectedPackId)
    }
  }, [selectedPackId, detailPack, loadDetail])

  const handleSelectPack = useCallback((pack: Pack) => {
    loadDetail(pack.id)
  }, [loadDetail])

  const handleBack = useCallback(() => {
    setDetailPack(null)
    setSelectedPackId(null)
  }, [setSelectedPackId])

  const handleCreatePack = useCallback(async (data: { name: string; author: string; cover_url: string }) => {
    try {
      const pack = await packsApi.create({ ...data, is_custom: true })
      addPack(pack)
      setShowPackEditor(false)
      handleSelectPack(pack)
    } catch {}
  }, [addPack, handleSelectPack])

  const handleUpdatePack = useCallback(async (data: { name: string; author: string; cover_url: string }) => {
    if (!editingPack) return
    try {
      const updated = await packsApi.update(editingPack.id, data)
      updatePackInStore(editingPack.id, updated)
      if (detailPack?.id === editingPack.id) {
        setDetailPack((prev) => prev ? { ...prev, ...updated } : null)
      }
      setEditingPack(null)
      setShowPackEditor(false)
    } catch {}
  }, [editingPack, updatePackInStore, detailPack])

  const handleDeletePack = useCallback(async (id: string) => {
    try {
      await packsApi.delete(id)
      void loadAvailableTools()
      removePack(id)
      if (selectedPackId === id) {
        setDetailPack(null)
        setSelectedPackId(null)
      }
    } catch {}
  }, [removePack, selectedPackId, setSelectedPackId, loadAvailableTools])

  const handleImportDone = useCallback((pack: PackWithItems) => {
    loadPacks()
    setShowImport(false)
    setDetailPack(pack)
    setSelectedPackId(pack.id)
  }, [loadPacks, setSelectedPackId])

  const handleDetailRefresh = useCallback(() => {
    if (selectedPackId) loadDetail(selectedPackId)
  }, [selectedPackId, loadDetail])

  const filteredPacks = packs.filter((p) => {
    if (packFilterTab === 'custom' && !p.is_custom) return false
    if (packFilterTab === 'downloaded' && p.is_custom) return false
    if (packSearchQuery) {
      const q = packSearchQuery.toLowerCase()
      return p.name.toLowerCase().includes(q) || p.author.toLowerCase().includes(q)
    }
    return true
  })

  if (detailPack) {
    return (
      <div className={styles.panel}>
        <PackDetailView
          pack={detailPack}
          onBack={handleBack}
          onEdit={() => {
            setEditingPack(detailPack)
            setShowPackEditor(true)
          }}
          onDelete={() => handleDeletePack(detailPack.id)}
          onRefresh={handleDetailRefresh}
        />
        {showPackEditor && editingPack && (
          <PackEditorModal
            initialData={editingPack}
            onSave={handleUpdatePack}
            onClose={() => { setShowPackEditor(false); setEditingPack(null) }}
          />
        )}
      </div>
    )
  }

  return (
    <div className={styles.panel}>
      <div className={styles.toolbar}>
        <div className={styles.searchBar}>
          <Search size={14} className={styles.searchIcon} />
          <input
            type="text"
            className={styles.searchInput}
            placeholder={t('packBrowser.searchPacks')}
            value={packSearchQuery}
            onChange={(e) => setPackSearchQuery(e.target.value)}
          />
          <Button
            size="icon"
            onClick={() => setShowImport(true)}
            title={t('packBrowser.importPack')}
            icon={<Upload size={14} />}
          />
          <Button
            size="icon"
            onClick={() => { setEditingPack(null); setShowPackEditor(true) }}
            title={t('packBrowser.newPack')}
            icon={<Plus size={14} />}
          />
        </div>
        <div className={styles.filterTabs}>
          {filterTabs.map((tab) => (
            <button
              key={tab.id}
              type="button"
              className={clsx(styles.filterTab, packFilterTab === tab.id && styles.filterTabActive)}
              onClick={() => setPackFilterTab(tab.id)}
            >
              {tab.label}
            </button>
          ))}
        </div>
      </div>

      <div className={styles.grid}>
        {filteredPacks.map((pack) => (
          <PackCard key={pack.id} pack={pack} onClick={handleSelectPack} />
        ))}
        {filteredPacks.length === 0 && (
          <div className={styles.emptyState}>{t('packBrowser.noPacksFound')}</div>
        )}
      </div>

      {showPackEditor && !editingPack && (
        <PackEditorModal
          onSave={handleCreatePack}
          onClose={() => setShowPackEditor(false)}
        />
      )}

      {showImport && (
        <ImportPackModal
          onImport={handleImportDone}
          onClose={() => setShowImport(false)}
        />
      )}
    </div>
  )
}

