          <Badge color={pack.is_custom ? 'primary' : 'success'} size="sm">
            {pack.is_custom ? t('packBrowser.packCard.badgeCustom') : t('packBrowser.packCard.badgeDownloaded')}
          </Badge>
          <Badge size="sm">v{pack.version}</Badge>
        </div>
      </div>
    </div>
  )
}

