import { useEffect, useId, useRef, useState } from 'react'
import { CheckSquare, FileUp, X } from 'lucide-react'
import { useTranslation } from 'react-i18next'
import clsx from 'clsx'
import type { WorldBook } from '@/types/api'
import styles from './PersonaBulkBar.module.css'

export type PersonaBulkAction =
  | 'move'
  | 'attachLorebook'
  | 'removeLorebook'
  | 'toggleNarrator'
  | 'import'
  | 'export'
  | 'delete'

interface PersonaBulkBarProps {
  selectedCount: number
  totalCount: number
  folders: string[]
  worldBooks: WorldBook[]
  busy: boolean
  onSelectAll: () => void
  onClearSelection: () => void
  onCancel: () => void
  onApply: (action: PersonaBulkAction, value?: string, file?: File) => Promise<boolean>
}

export default function PersonaBulkBar({
  selectedCount,
  totalCount,
  folders,
  worldBooks,
  busy,
  onSelectAll,
  onClearSelection,
  onCancel,
  onApply,
}: PersonaBulkBarProps) {
  const { t } = useTranslation('panels', { keyPrefix: 'personaManager.bulk' })
  const [action, setAction] = useState<PersonaBulkAction | ''>('')
  const [folder, setFolder] = useState('')
  const [worldBookId, setWorldBookId] = useState('')
  const [importFile, setImportFile] = useState<File | null>(null)
  const folderListId = useId()
  const importInputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    if (selectedCount === 0) {
      setAction((current) => current === 'import' ? current : '')
    }
  }, [selectedCount])

  const needsLorebook = action === 'attachLorebook'
  const isImport = action === 'import'
  const canApply = isImport
    ? !!importFile
    : selectedCount > 0 && !!action && (!needsLorebook || !!worldBookId)

  const apply = async () => {
    if (!action || !canApply || busy) return
    const value = action === 'move' ? folder : action === 'attachLorebook' ? worldBookId : undefined
    if (await onApply(action, value, importFile ?? undefined)) {
      setAction('')
      setFolder('')
      setWorldBookId('')
      setImportFile(null)
      if (importInputRef.current) importInputRef.current.value = ''
    }
  }

  return (
    <div className={styles.bar}>
      <div className={styles.summaryRow}>
        <span className={styles.info}>
          <CheckSquare size={14} />
          {t('selected', { selected: selectedCount, total: totalCount })}
        </span>
        <button
          type="button"
          className={styles.linkBtn}
          onClick={selectedCount === totalCount ? onClearSelection : onSelectAll}
          disabled={totalCount === 0 || busy}
        >
          {selectedCount === totalCount ? t('deselectAll') : t('selectAll')}
        </button>
        <button type="button" className={styles.closeBtn} onClick={onCancel} disabled={busy} title={t('exit')}>
          <X size={14} />
        </button>
      </div>

      <div className={styles.actionRow}>
        <select
          className={styles.select}
          value={action}
          onChange={(event) => {
            const nextAction = event.target.value as PersonaBulkAction | ''
            setAction(nextAction)
            if (nextAction !== 'import') {
              setImportFile(null)
              if (importInputRef.current) importInputRef.current.value = ''
            }
          }}
          disabled={busy}
          aria-label={t('action')}
        >
          <option value="">{t('action')}</option>
          <option value="move">{t('move')}</option>
          <option value="attachLorebook">{t('attachLorebook')}</option>
          <option value="removeLorebook">{t('removeLorebook')}</option>
          <option value="toggleNarrator">{t('toggleNarrator')}</option>
          <option value="import">{t('import')}</option>
          <option value="export">{t('export')}</option>
          <option value="delete">{t('delete')}</option>
        </select>

        {action === 'move' && (
          <>
            <input
              className={styles.targetInput}
              value={folder}
              onChange={(event) => setFolder(event.target.value)}
              placeholder={t('uncategorized')}
              list={folderListId}
              disabled={busy}
              aria-label={t('folder')}
            />
            <datalist id={folderListId}>
              {folders.map((name) => <option key={name} value={name} />)}
            </datalist>
          </>
        )}

        {needsLorebook && (
          <select
            className={styles.targetInput}
            value={worldBookId}
            onChange={(event) => setWorldBookId(event.target.value)}
            disabled={busy}
            aria-label={t('lorebook')}
          >
            <option value="">{t('chooseLorebook')}</option>
            {worldBooks.map((book) => <option key={book.id} value={book.id}>{book.name}</option>)}
          </select>
        )}

        {isImport && (
          <>
            <input
              ref={importInputRef}
              type="file"
              accept=".json,application/json"
              hidden
              onChange={(event) => setImportFile(event.target.files?.[0] ?? null)}
            />
            <button
              type="button"
              className={clsx(styles.targetInput, styles.fileBtn)}
              onClick={() => importInputRef.current?.click()}
              disabled={busy}
              title={importFile?.name || t('chooseFile')}
            >
              <FileUp size={13} />
              <span>{importFile?.name || t('chooseFile')}</span>
            </button>
          </>
        )}

        <button
          type="button"
          className={clsx(styles.applyBtn, action === 'delete' && styles.deleteBtn)}
          onClick={() => void apply()}
          disabled={!canApply || busy}
        >
          {busy ? t('working') : isImport ? t('import') : t('apply')}
        </button>
      </div>
    </div>
  )
}

