import ConnectionFolderField, { useConnectionFolderDraft } from '@/components/panels/connection-manager/ConnectionFolderField'
import { useState, useCallback, useEffect, useMemo } from 'react'
import { useTranslation } from 'react-i18next'
import { sttConnectionsApi } from '@/api/stt-connections'
import { FormField, TextInput, Select, Button } from '@/components/shared/FormComponents'
import { Toggle } from '@/components/shared/Toggle'
import ModelCombobox from '@/components/panels/connection-manager/ModelCombobox'
import type {
  SttProviderInfo,
  SttConnectionProfile,
  CreateSttConnectionInput,
} from '@/types/api'
import styles from '../ConnectionManager.module.css'

interface Props {
  providers: SttProviderInfo[]
  profile?: SttConnectionProfile
  onSave: (input: CreateSttConnectionInput, folderId?: string) => void
  onCancel: () => void
}

export default function STTConnectionForm({ providers, profile, onSave, onCancel }: Props) {
  const folder = useConnectionFolderDraft('stt', profile?.id)
  const { t } = useTranslation('panels')
  const [name, setName] = useState(profile?.name || '')
  const [provider, setProvider] = useState(profile?.provider || providers[0]?.id || 'openai')
  const [apiKey, setApiKey] = useState('')
  const [apiUrl, setApiUrl] = useState(profile?.api_url || '')
  const [model, setModel] = useState(profile?.model || '')
  const [isDefault, setIsDefault] = useState(profile?.is_default || false)
  const [models, setModels] = useState<Array<{ id: string; label: string }>>([])
  const [modelsLoading, setModelsLoading] = useState(false)

  const selectedProvider = providers.find((p) => p.id === provider)
  const capabilities = selectedProvider?.capabilities
  const providerOptions = providers.map((p) => ({ value: p.id, label: p.name }))

  const modelOptions = useMemo(() => {
    const options = models.length > 0 ? models : capabilities?.staticModels || []
    if (model && !options.some((option) => option.id === model)) {
      return [{ id: model, label: model }, ...options]
    }
    return options
  }, [capabilities?.staticModels, model, models])

  const modelIds = useMemo(() => modelOptions.map((option) => option.id), [modelOptions])

  const modelLabels = useMemo(() => {
    return Object.fromEntries(
      modelOptions
        .filter((option) => option.label && option.label !== option.id)
        .map((option) => [option.id, option.label])
    )
  }, [modelOptions])

  const fetchModels = useCallback(async () => {
    setModelsLoading(true)
    try {
      const result = await sttConnectionsApi.previewModels({
        connection_id: profile?.id,
        provider,
        api_url: apiUrl.trim() || undefined,
        api_key: apiKey.trim() || undefined,
      })
      setModels(result.models)
    } catch {
      setModels([])
    } finally {
      setModelsLoading(false)
    }
  }, [apiKey, apiUrl, profile?.id, provider])

  useEffect(() => {
    if (profile?.id && capabilities?.modelListStyle !== 'static') {
      fetchModels()
    }
  }, [profile?.id, capabilities?.modelListStyle, fetchModels])

  const handleSubmit = useCallback(() => {
    if (!name.trim()) return
    onSave({
      name: name.trim(),
      provider,
      api_key: apiKey.trim() || undefined,
      api_url: apiUrl.trim() || undefined,
      model: model.trim() || undefined,
      is_default: isDefault,
    }, folder.value)
  }, [name, provider, apiKey, apiUrl, model, isDefault, folder.value, onSave])

  return (
    <div className={styles.form}>
      <FormField label={t('sttConnectionForm.name')} required>
        <TextInput value={name} onChange={setName} placeholder={t('sttConnectionForm.connectionName')} autoFocus={!profile} />
      </FormField>
      <ConnectionFolderField kind="stt" {...folder} />

      <FormField label={t('sttConnectionForm.provider')}>
        <Select value={provider} onChange={setProvider} options={providerOptions} />
      </FormField>

      {capabilities?.apiKeyRequired && (
        <FormField label={t('sttConnectionForm.apiKey')} hint={profile?.has_api_key ? t('sttConnectionForm.keySetHint') : undefined}>
          <TextInput
            value={apiKey}
            onChange={setApiKey}
            placeholder={profile?.has_api_key ? '••••••••' : t('sttConnectionForm.enterApiKey')}
            type="password"
          />
        </FormField>
      )}

      <FormField label={t('sttConnectionForm.apiUrl')} hint={t('sttConnectionForm.apiUrlHint')}>
        <TextInput
          value={apiUrl}
          onChange={setApiUrl}
          placeholder={capabilities?.defaultUrl || 'https://...'}
        />
      </FormField>

      <FormField label={t('sttConnectionForm.model')} hint={t('sttConnectionForm.modelHint')}>
        <ModelCombobox
          value={model}
          onChange={setModel}
          models={modelIds}
          modelLabels={modelLabels}
          loading={modelsLoading}
          onRefresh={fetchModels}
          autoRefreshOnFocus
          refreshKey={`${provider}:${profile?.id || ''}`}
          appearance="standard"
          placeholder={t('sttConnectionForm.modelPlaceholder')}
          emptyMessage={t('sttConnectionForm.noModels')}
        />
      </FormField>

      <FormField label="">
        <Toggle.Checkbox checked={isDefault} onChange={setIsDefault} label={t('sttConnectionForm.setDefault')} />
      </FormField>

      <div className={styles.formActions}>
        <Button variant="ghost" size="sm" onClick={onCancel}>{t('sttConnectionForm.cancel')}</Button>
        <Button variant="primary" size="sm" onClick={handleSubmit} disabled={!name.trim()}>
          {profile ? t('sttConnectionForm.save') : t('sttConnectionForm.create')}
        </Button>
      </div>
    </div>
  )
}

import type { ConnectionPlacement } from '@/lib/connectionPlacement'
import { useConnectionRow } from '@/components/panels/connection-manager/useConnectionRow'
import { saveConnectionFolder } from '@/hooks/useConnectionLibrary'
import { useState, useEffect, useCallback } from 'react'
import { useTranslation } from 'react-i18next'

import { Trash2, Edit3, Zap, Star, Copy, MoreVertical, GripVertical } from 'lucide-react'
import { sttConnectionsApi } from '@/api/stt-connections'
import type { SttConnectionProfile, SttProviderInfo, CreateSttConnectionInput } from '@/types/api'
import STTConnectionForm from './STTConnectionForm'
import ContextMenu, { type ContextMenuEntry, type ContextMenuPos } from '@/components/shared/ContextMenu'
import ProviderIcon from '@/components/shared/ProviderIcon'
import styles from '../connection-manager/ConnectionItem.module.css'
import clsx from 'clsx'

interface Props {
  placement?: ConnectionPlacement
  profile: SttConnectionProfile
  providers: SttProviderInfo[]
  onUpdate: (profile: SttConnectionProfile) => void
  onDuplicate: () => void
  onDelete: () => void
}

export default function STTConnectionItem({
  placement = 'list', profile, providers, onUpdate, onDuplicate, onDelete }: Props) {
  const { t: tc } = useTranslation('common')
  const { t } = useTranslation('panels')
  const { editing, setEditing, isRecent, ...sortable } = useConnectionRow(profile.id, placement)
  const [testing, setTesting] = useState(false)
  const [testResult, setTestResult] = useState<{ success: boolean; message: string } | null>(null)
  const [menuPos, setMenuPos] = useState<ContextMenuPos | null>(null)

  useEffect(() => {
    if (!testResult) return
    const timer = setTimeout(() => setTestResult(null), 5000)
    return () => clearTimeout(timer)
  }, [testResult])

  const handleTest = useCallback(async () => {
    setTesting(true)
    setTestResult(null)
    try {
      const result = await sttConnectionsApi.test(profile.id)
      setTestResult({ success: result.success, message: result.message })
    } catch (err: any) {
      setTestResult({ success: false, message: err.message || t('connectionItem.connectionFailed') })
    } finally {
      setTesting(false)
    }
  }, [profile.id, t])

  const handleSaveEdit = useCallback(async (input: CreateSttConnectionInput, folderId = '') => {
    try {
      const updated = await sttConnectionsApi.update(profile.id, input)
      saveConnectionFolder('stt', profile.id, folderId)
      onUpdate(updated)
      setEditing(false)
    } catch (err) {
      console.error('[STTConnectionItem] Failed to update:', err)
    }
  }, [profile.id, onUpdate, setEditing])

  const { attributes, listeners, setNodeRef, style, isDragging, handleRef } = sortable

  return (
    <div ref={setNodeRef} style={style} data-dragging={isDragging || undefined} className={clsx(styles.item, isDragging && styles.itemDragging)}>
      {editing ? (
        <STTConnectionForm
          providers={providers}
          profile={profile}
          onSave={handleSaveEdit}
          onCancel={() => setEditing(false)}
        />
      ) : (
        <>
          <div className={styles.itemRow}>
            {!isRecent && <button
              ref={handleRef}
              type="button"
              className={styles.dragHandle}
              aria-label={t('connectionItem.dragToReorder')}
              title={t('connectionItem.dragToReorder')}
              {...attributes}
              {...listeners}
            >
              <GripVertical size={16} />
            </button>}
            <div className={styles.itemBtn} onMouseDown={event => listeners?.onMouseDown?.(event)} onTouchStart={event => listeners?.onTouchStart?.(event)} style={{ cursor: 'default' }}>
              <ProviderIcon kind="stt" provider={profile.provider} size={32} iconSize={16} className={styles.itemIcon} />
              <div className={styles.itemInfo}>
                <span className={styles.itemName}>
                  {profile.name}
                  {profile.is_default && <Star size={11} className={styles.defaultStar} fill="#f5a623" />}
                </span>
                <span className={styles.itemMeta}>
                  {profile.provider}
                  {profile.model ? ` / ${profile.model}` : ''}
                </span>
              </div>
            </div>
            <div className={styles.itemActions}>
              <button type="button" className={styles.actionBtn} onClick={() => setEditing(true)} title={tc('actions.edit')}>
                <Edit3 size={13} />
              </button>
              <button
                type="button"
                className={styles.actionBtn}
                onClick={(e) => {
                  const rect = e.currentTarget.getBoundingClientRect()
                  setMenuPos({ x: rect.right, y: rect.bottom + 4 })
                }}
                title={t('connectionItem.moreActions')}
              >
                <MoreVertical size={13} />
              </button>
              <ContextMenu
                position={menuPos}
                onClose={() => setMenuPos(null)}
                items={[
                  { key: 'test', label: testing ? t('connectionItem.testing') : t('connectionItem.testConnection'), icon: <Zap size={14} />, onClick: () => { setMenuPos(null); handleTest() }, disabled: testing },
                  { key: 'duplicate', label: t('connectionItem.duplicate'), icon: <Copy size={14} />, onClick: () => { setMenuPos(null); onDuplicate() } },
                  { key: 'div', type: 'divider' as const },
                  { key: 'delete', label: t('connectionItem.delete'), icon: <Trash2 size={14} />, onClick: () => { setMenuPos(null); onDelete() }, danger: true },
                ] satisfies ContextMenuEntry[]}
              />
            </div>
          </div>
          {testResult && (
            <div className={clsx(styles.testMessage, testResult.success ? styles.testMessageSuccess : styles.testMessageFail)}>
              {testResult.message}
            </div>
          )}
        </>
      )}
    </div>
  )
}

import ConnectionCollection from '../connection-manager/ConnectionCollection'
import { useConnectionLibrary, saveConnectionFolder } from '@/hooks/useConnectionLibrary'
import { useState, useEffect, useCallback, useMemo } from 'react'
import { Plus } from 'lucide-react'
import { useTranslation } from 'react-i18next'
import { sttConnectionsApi } from '@/api/stt-connections'
import { listAllConnections } from '@/api/listAllConnections'
import { useStore } from '@/store'
import ConfirmationModal from '@/components/shared/ConfirmationModal'
import STTConnectionForm from './STTConnectionForm'
import STTConnectionItem from './STTConnectionItem'
import type { SttConnectionProfile, CreateSttConnectionInput } from '@/types/api'
import styles from '../ConnectionManager.module.css'
import { normalizeConnectionsOrder } from '@/store/slices/connections-order-merge'

export default function STTConnectionManager() {
  const { t } = useTranslation('panels')
  const profiles = useStore((s) => s.sttProfiles)
  const setProfiles = useStore((s) => s.setSttProfiles)
  const addProfile = useStore((s) => s.addSttProfile)
  const updateProfile = useStore((s) => s.updateSttProfile)
  const removeProfile = useStore((s) => s.removeSttProfile)
  const applyProfileOrder = useStore((s) => s.applySttProfileOrder)
  const providers = useStore((s) => s.sttProviders)
  const setProviders = useStore((s) => s.setSttProviders)
  const setSetting = useStore((s) => s.setSetting)
  const connectionsOrder = useStore((s) => s.connectionsOrder)

  const library = useConnectionLibrary('stt')

  const orderedProfiles = useMemo(() => {
    const sttOrder = connectionsOrder?.stt ?? []
    if (sttOrder.length === 0) return profiles
    const byId = new Map(profiles.map((p) => [p.id, p]))
    const ordered = sttOrder.map((id) => byId.get(id)).filter((p): p is SttConnectionProfile => Boolean(p))
    const seen = new Set(ordered.map((p) => p.id))
    const missing = profiles.filter((p) => !seen.has(p.id))
    return [...ordered, ...missing]
  }, [profiles, connectionsOrder])

  const [loading, setLoading] = useState(false)
  const [creating, setCreating] = useState(false)
  const [deleteTarget, setDeleteTarget] = useState<SttConnectionProfile | null>(null)

  useEffect(() => {
    let cancelled = false

    const storeState = useStore.getState()
    const cacheHit = storeState.sttProfiles.length > 0 && storeState.sttProviders.length > 0

    async function init() {
      if (!cacheHit) setLoading(true)
      try {
        const [profilesResult, providersResult] = await Promise.allSettled([
          listAllConnections(sttConnectionsApi),
          sttConnectionsApi.providers(),
        ])

        if (cancelled) return

        if (profilesResult.status === 'fulfilled') {
          setProfiles(profilesResult.value.data)
        }

        if (providersResult.status === 'fulfilled') {
          setProviders(providersResult.value.providers)
        }
      } catch (err) {
        console.error('[STTConnectionManager] Init failed:', err)
      } finally {
        if (!cancelled && !cacheHit) setLoading(false)
      }
    }

    init()
    return () => { cancelled = true }
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  const handleCreate = useCallback(async (input: CreateSttConnectionInput, folderId = '') => {
    try {
      const profile = await sttConnectionsApi.create(input)
      saveConnectionFolder('stt', profile.id, folderId)
      addProfile(profile)
      if (input.is_default) {
        profiles.forEach((p) => {
          if (p.id !== profile.id && p.is_default) updateProfile(p.id, { is_default: false })
        })
      }
      setCreating(false)
    } catch (err) {
      console.error('[STTConnectionManager] Failed to create:', err)
    }
  }, [profiles, addProfile, updateProfile])

  const handleUpdate = useCallback((updated: SttConnectionProfile) => {
    updateProfile(updated.id, updated)
    if (updated.is_default) {
      profiles.forEach((p) => {
        if (p.id !== updated.id && p.is_default) updateProfile(p.id, { is_default: false })
      })
    }
  }, [profiles, updateProfile])

  const handleDuplicate = useCallback(async (id: string) => {
    try {
      const duplicated = await sttConnectionsApi.duplicate(id)
      addProfile(duplicated)
      library.copyFolder(id, duplicated.id)
    } catch (err) {
      console.error('[STTConnectionManager] Failed to duplicate:', err)
    }
  }, [addProfile, library])

  const handleDelete = useCallback(async () => {
    if (!deleteTarget) return
    try {
      await sttConnectionsApi.delete(deleteTarget.id)
      removeProfile(deleteTarget.id)
      library.forget(deleteTarget.id)
      const normalizedOrder = normalizeConnectionsOrder(connectionsOrder)
      const nextOrder = normalizedOrder.stt.filter((id) => id !== deleteTarget.id)
      setSetting('connectionsOrder', { ...normalizedOrder, stt: nextOrder })
      setDeleteTarget(null)
    } catch (err) {
      console.error('[STTConnectionManager] Failed to delete:', err)
    }
  }, [deleteTarget, removeProfile, connectionsOrder, setSetting, library])

  const handleReorder = (ids: string[]) => {
    applyProfileOrder(ids)
    setSetting('connectionsOrder', { ...normalizeConnectionsOrder(useStore.getState().connectionsOrder), stt: ids })
  }

  if (loading) {
    return <div className={styles.loading}>{t('sttConnectionManager.loading')}</div>
  }

  return (
    <div className={styles.manager}>
      <ConnectionCollection kind="stt" profiles={orderedProfiles} onReorder={handleReorder}
        actions={!creating && (
          <button type="button" className={styles.createBtn} onClick={() => setCreating(true)}>
            <Plus size={14} />
            <span>{t('sttConnectionManager.newConnection')}</span>
          </button>
        )}
        editor={creating && (
          <STTConnectionForm
            providers={providers}
            onSave={handleCreate}
            onCancel={() => setCreating(false)}
          />
        )}
        emptyMessage={creating ? '' : t('sttConnectionManager.empty')}
        renderProfile={(profile, placement) => (
          <STTConnectionItem
            placement={placement}
            key={profile.id}
            profile={profile}
            providers={providers}
            onUpdate={handleUpdate}
            onDuplicate={() => handleDuplicate(profile.id)}
            onDelete={() => setDeleteTarget(profile)}
          />
        )} />

      {deleteTarget && (
        <ConfirmationModal
          title={t('sttConnectionManager.deleteTitle')}
          message={t('sttConnectionManager.deleteMessage', { name: deleteTarget.name })}
          isOpen={true}
          variant="danger"
          confirmText={t('sttConnectionManager.deleteConfirm')}
          onConfirm={handleDelete}
          onCancel={() => setDeleteTarget(null)}
        />
      )}
    </div>
  )
}

