.picker {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.swatches {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  align-items: center;
  justify-content: center;
}

.swatch {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  border: 2px solid transparent;
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
  box-shadow: var(--lumiverse-shadow-sm);
}

.swatch:hover {
  transform: scale(1.15);
}

.swatch:disabled {
  opacity: 0.5;
  cursor: default;
  transform: none;
}

.swatchActive {
  border-color: var(--lumiverse-text);
  box-shadow: 0 0 0 2px var(--lumiverse-bg), 0 0 0 4px var(--lumiverse-text-dim);
}

.customBtn {
  padding: 4px 10px;
  border-radius: var(--lumiverse-radius-sm);
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text-dim);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
}

.customBtn:hover {
  background: var(--lumiverse-fill);
  color: var(--lumiverse-text-muted);
}

.customBtnActive {
  background: var(--lumiverse-primary-010);
  border-color: var(--lumiverse-primary);
  color: var(--lumiverse-primary);
}

.sliders {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px;
  border-radius: var(--lumiverse-radius);
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
}

.sliderRow {
  display: flex;
  align-items: center;
  gap: 8px;
}

.sliderLabel {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  color: var(--lumiverse-text-dim);
  width: 65px;
  flex-shrink: 0;
}

.sliderValue {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  color: var(--lumiverse-text-muted);
  width: 32px;
  text-align: right;
  flex-shrink: 0;
  font-variant-numeric: tabular-nums;
}

.hueSlider,
.satSlider,
.lumSlider {
  min-width: 0;
  flex: 1;
  outline: none;
}

.hueSlider:disabled,
.satSlider:disabled,
.lumSlider:disabled {
  opacity: 0.5;
  pointer-events: none;
}

.hueSlider::-webkit-slider-runnable-track,
.satSlider::-webkit-slider-runnable-track,
.lumSlider::-webkit-slider-runnable-track {
  height: 6px;
  border-radius: 3px;
}

.hueSlider::-moz-range-track,
.satSlider::-moz-range-track,
.lumSlider::-moz-range-track {
  height: 6px;
  border-radius: 3px;
}

.hueSlider::-webkit-slider-runnable-track {
  background: linear-gradient(
    to right,
    hsl(0, 70%, 60%),
    hsl(60, 70%, 60%),
    hsl(120, 70%, 60%),
    hsl(180, 70%, 60%),
    hsl(240, 70%, 60%),
    hsl(300, 70%, 60%),
    hsl(360, 70%, 60%)
  );
}

.hueSlider::-moz-range-track {
  background: linear-gradient(
    to right,
    hsl(0, 70%, 60%),
    hsl(60, 70%, 60%),
    hsl(120, 70%, 60%),
    hsl(180, 70%, 60%),
    hsl(240, 70%, 60%),
    hsl(300, 70%, 60%),
    hsl(360, 70%, 60%)
  );
}

.satSlider::-webkit-slider-runnable-track {
  background: linear-gradient(
    to right,
    hsl(0, 10%, 60%),
    var(--lumiverse-primary)
  );
}

.satSlider::-moz-range-track {
  background: linear-gradient(
    to right,
    hsl(0, 10%, 60%),
    var(--lumiverse-primary)
  );
}

.lumSlider::-webkit-slider-runnable-track {
  background: var(--lum-track-bg);
}

.lumSlider::-moz-range-track {
  background: var(--lum-track-bg);
}

.hueSlider::-webkit-slider-thumb,
.satSlider::-webkit-slider-thumb,
.lumSlider::-webkit-slider-thumb {
  background: #fff;
  border-color: var(--lumiverse-text-dim);
}

.hueSlider::-moz-range-thumb,
.satSlider::-moz-range-thumb,
.lumSlider::-moz-range-thumb {
  background: #fff;
  border-color: var(--lumiverse-text-dim);
}

import { useState, useRef, useCallback, useEffect } from 'react'
import { useTranslation } from 'react-i18next'
import styles from './AccentPicker.module.css'
import clsx from 'clsx'

interface AccentPickerProps {
  slidersLocked?: boolean
  hue: number
  saturation: number
  luminance: number
  onChange: (h: number, s: number, l: number) => void
}

const SWATCHES = [0, 30, 60, 120, 152, 200, 220, 263, 290, 340]

export default function AccentPicker({ hue, saturation, luminance, onChange, slidersLocked = false }: AccentPickerProps) {
  const { t } = useTranslation('panels', { keyPrefix: 'themePanel.accent' })
  const [customOpen, setCustomOpen] = useState(false)
  const [localHue, setLocalHue] = useState(hue)
  const [localSat, setLocalSat] = useState(saturation)
  const [localLum, setLocalLum] = useState(luminance)
  const debounceRef = useRef<ReturnType<typeof setTimeout>>(undefined)
  const rafRef = useRef<number>(undefined)

  // Sync local state when prop changes externally (e.g. preset selection)
  useEffect(() => {
    setLocalHue(hue)
    setLocalSat(saturation)
    setLocalLum(luminance)
  }, [hue, saturation, luminance])

  const debouncedOnChange = useCallback(
    (h: number, s: number, l: number) => {
      clearTimeout(debounceRef.current)
      debounceRef.current = setTimeout(() => onChange(h, s, l), 300)
    },
    [onChange]
  )

  const applyPreview = useCallback(
    (h: number, s: number, l: number) => {
      cancelAnimationFrame(rafRef.current!)
      rafRef.current = requestAnimationFrame(() => {
        document.documentElement.style.setProperty(
          '--lumiverse-primary',
          `hsla(${h}, ${s}%, ${l}%, 0.9)`
        )
      })
    },
    []
  )

  const handleHueSlider = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const h = Number(e.target.value)
      setLocalHue(h)
      applyPreview(h, localSat, localLum)
      debouncedOnChange(h, localSat, localLum)
    },
    [localSat, localLum, applyPreview, debouncedOnChange]
  )

  const handleSatSlider = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const s = Number(e.target.value)
      setLocalSat(s)
      applyPreview(localHue, s, localLum)
      debouncedOnChange(localHue, s, localLum)
    },
    [localHue, localLum, applyPreview, debouncedOnChange]
  )

  const handleLumSlider = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const l = Number(e.target.value)
      setLocalLum(l)
      applyPreview(localHue, localSat, l)
      debouncedOnChange(localHue, localSat, l)
    },
    [localHue, localSat, applyPreview, debouncedOnChange]
  )

  const isCustom = !SWATCHES.includes(hue)

  return (
    <div className={styles.picker}>
      <div className={styles.swatches}>
        {SWATCHES.map((h) => (
          <button
            key={h}
            type="button"
            disabled={slidersLocked}
            aria-label={t('hue') + ': ' + h}
            className={clsx(styles.swatch, hue === h && !customOpen && styles.swatchActive)}
            style={{ background: `hsl(${h}, ${saturation}%, 65%)` }}
            onClick={() => {
              setCustomOpen(false)
              onChange(h, saturation, luminance)
            }}
          />
        ))}
        <button
          type="button"
          className={clsx(styles.customBtn, (customOpen || isCustom) && styles.customBtnActive)}
          onClick={() => setCustomOpen(!customOpen)}
        >
          {t('custom')}
        </button>
      </div>

      {(customOpen || isCustom) && (
        <div className={styles.sliders}>
          <label className={styles.sliderRow}>
            <span className={styles.sliderLabel}>{t('hue')}</span>
            <input
              type="range"
              disabled={slidersLocked}
              min={0}
              max={360}
              value={localHue}
              onChange={handleHueSlider}
              className={styles.hueSlider}
            />
            <span className={styles.sliderValue}>{localHue}</span>
          </label>
          <label className={styles.sliderRow}>
            <span className={styles.sliderLabel}>{t('saturation')}</span>
            <input
              type="range"
              disabled={slidersLocked}
              min={10}
              max={100}
              value={localSat}
              onChange={handleSatSlider}
              className={styles.satSlider}
            />
            <span className={styles.sliderValue}>{localSat}%</span>
          </label>
          <label className={styles.sliderRow}>
            <span className={styles.sliderLabel}>{t('luminance')}</span>
            <input
              type="range"
              disabled={slidersLocked}
              min={30}
              max={80}
              value={localLum}
              onChange={handleLumSlider}
              className={styles.lumSlider}
              style={{
                '--lum-track-bg': `linear-gradient(to right, hsl(${localHue}, ${localSat}%, 30%), hsl(${localHue}, ${localSat}%, 55%), hsl(${localHue}, ${localSat}%, 80%))`,
              } as React.CSSProperties}
            />
            <span className={styles.sliderValue}>{localLum}%</span>
          </label>
        </div>
      )}
    </div>
  )
}

