.container {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* ── Color category swatches ── */

.swatchRow {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: center;
}

.swatchBtn {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px;
  border-radius: 8px;
  transition: all var(--lumiverse-transition-fast);
}

.swatchBtn:hover {
  background: var(--lumiverse-fill-subtle);
}

.swatchCircle {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  border: 2px solid transparent;
  transition: all var(--lumiverse-transition-fast);
  box-shadow: var(--lumiverse-shadow-sm);
}

.swatchBtnActive .swatchCircle {
  border-color: var(--lumiverse-text);
  box-shadow: 0 0 0 2px var(--lumiverse-bg), 0 0 0 4px var(--lumiverse-text-dim);
}

.swatchLabel {
  font-size: calc(9px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.3px;
  color: var(--lumiverse-text-dim);
  max-width: 56px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.swatchBtnActive .swatchLabel {
  color: var(--lumiverse-primary);
}

/* ── Editing label ── */

.editingLabel {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--lumiverse-text-dim);
}

.editingLabel span {
  color: var(--lumiverse-primary);
}

/* ── Saturation / Brightness canvas ── */

.canvasWrap {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  border-radius: var(--lumiverse-radius);
  overflow: hidden;
  cursor: crosshair;
  border: 1px solid var(--lumiverse-border);
  touch-action: none;
  user-select: none;
}

.canvas {
  display: block;
  width: 100%;
  height: 100%;
}

.canvasCursor {
  position: absolute;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  border: 2px solid #fff;
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.3), inset 0 0 0 1px rgba(0, 0, 0, 0.3);
  pointer-events: none;
  transform: translate(-50%, -50%);
}

/* ── Hue slider ── */

.hueSliderWrap {
  position: relative;
  height: 14px;
  border-radius: 7px;
  cursor: pointer;
  background: linear-gradient(
    to right,
    hsl(0, 100%, 50%),
    hsl(30, 100%, 50%),
    hsl(60, 100%, 50%),
    hsl(90, 100%, 50%),
    hsl(120, 100%, 50%),
    hsl(150, 100%, 50%),
    hsl(180, 100%, 50%),
    hsl(210, 100%, 50%),
    hsl(240, 100%, 50%),
    hsl(270, 100%, 50%),
    hsl(300, 100%, 50%),
    hsl(330, 100%, 50%),
    hsl(360, 100%, 50%)
  );
  border: 1px solid var(--lumiverse-border);
  touch-action: none;
  user-select: none;
}

.hueThumb {
  position: absolute;
  top: 50%;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #fff;
  border: 2px solid var(--lumiverse-fill-strong);
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.3);
  pointer-events: none;
  transform: translate(-50%, -50%);
}

/* ── Input row ── */

