.section {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.header {
  display: flex;
  align-items: center;
  gap: 6px;
}

.headerIcon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  color: var(--lumiverse-text-dim);
}

.headerLabel {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--lumiverse-text-dim);
}

.list {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.card {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border-radius: var(--lumiverse-radius);
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-primary-015);
  transition: all var(--lumiverse-transition-fast);
}

.card:hover {
  background: var(--lumiverse-fill);
  border-color: var(--lumiverse-primary-020);
}

.swatches {
  display: flex;
  gap: 2px;
  flex-shrink: 0;
}

.swatch {
  width: 10px;
  height: 22px;
  border-radius: 3px;
  border: 1px solid var(--lumiverse-swatch-border);
}

.swatch:first-child {
  border-radius: 5px 3px 3px 5px;
}

.swatch:last-child {
  border-radius: 3px 5px 5px 3px;
}

.info {
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
  flex: 1;
}

.name {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1.2;
}

.attribution {
  font-size: calc(9.5px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
