import ConnectionFolderField, { useConnectionFolderDraft } from '@/components/panels/connection-manager/ConnectionFolderField'
import { lazy, Suspense, useState, useCallback, useEffect, useMemo, useRef } from 'react'
import { useTranslation } from 'react-i18next'
import { FormField, TextInput, TextArea, Select, Button } from '@/components/shared/FormComponents'
import { Toggle } from '@/components/shared/Toggle'
import ModelCombobox from '@/components/panels/connection-manager/ModelCombobox'
import { VERTEX_REGIONS } from '@/components/panels/connection-manager/vertexConstants'
import { ttsConnectionsApi } from '@/api/tts-connections'
import { isQwenTtsProvider, QWEN_LANGUAGE_OPTIONS } from '@/lib/qwenTts'
import { getTtsVoiceLabel, getTtsVoiceSublabel } from '@/lib/ttsVoiceLabels'
import FishAudioSettings, { fishDictionaryError } from './FishAudioSettings'
import type {
  TtsProviderInfo,
  TtsConnectionProfile,
  CreateTtsConnectionInput,
  TtsVoice,
} from '@/types/api'
import styles from '../ConnectionManager.module.css'

const VoiceLibraryModal = lazy(() => import('@/components/modals/VoiceLibraryModal'))

interface Props {
  providers: TtsProviderInfo[]
  profile?: TtsConnectionProfile
  onSave: (input: CreateTtsConnectionInput, folderId?: string) => void
  onCancel: () => void
}

export default function TTSConnectionForm({ providers, profile, onSave, onCancel }: Props) {
  const folder = useConnectionFolderDraft('tts', profile?.id)
  const { t } = useTranslation('panels')
  const [name, setName] = useState(profile?.name || '')
  const [provider, setProvider] = useState(profile?.provider || providers[0]?.id || 'openai_tts')
  const [apiKey, setApiKey] = useState('')
  const [apiUrl, setApiUrl] = useState(profile?.api_url || '')
  const [model, setModel] = useState(profile?.model || '')
  const [voice, setVoice] = useState(profile?.voice || '')
  const [isDefault, setIsDefault] = useState(profile?.is_default || false)
  const [defaultParameters, setDefaultParameters] = useState<Record<string, any>>(profile?.default_parameters || {})

  const isVertex = provider === 'google_vertex_tts'
  const isGoogle = isVertex || provider === 'google_tts'
  const googleUseStreaming = defaultParameters.use_streaming_endpoint !== false
  const [vertexRegion, setVertexRegion] = useState(profile?.metadata?.vertex_region || 'us-central1')
  const [saFileName, setSaFileName] = useState<string | null>(profile?.metadata?.sa_file_name || null)
  const fileInputRef = useRef<HTMLInputElement>(null)

  const [voices, setVoices] = useState<TtsVoice[]>([])
  const [voicesLoading, setVoicesLoading] = useState(false)
  const [libraryOpen, setLibraryOpen] = useState(false)
  const voicesRequestRef = useRef<{ generation: number; controller?: AbortController }>({ generation: 0 })
  const [models, setModels] = useState<Array<{ id: string; label: string }>>([])
  const [modelsLoading, setModelsLoading] = useState(false)

  const providerOptions = providers.map((p) => ({ value: p.id, label: p.name }))
  const selectedProvider = providers.find((p) => p.id === provider)
  const capabilities = selectedProvider?.capabilities
  const libraryConnection = useMemo(() => ({
    connection_id: profile?.id,
    provider,
    api_url: apiUrl.trim() || undefined,
    api_key: apiKey.trim() || undefined,
  }), [profile?.id, provider, apiUrl, apiKey])
  useEffect(() => { setLibraryOpen(false) }, [provider, profile?.id])
  const supportsGeminiSpeechStyle = (isGoogle || provider === 'openrouter_tts')
    && /(?:^|\/)gemini-3\.8-flash(?:-lite)?-tts(?:$|[-:])/i.test(model.trim())
  const geminiSpeechStyle = typeof defaultParameters.speech_style === 'string'
    ? defaultParameters.speech_style
    : typeof defaultParameters.instructions === 'string'
      ? defaultParameters.instructions
      : capabilities?.parameters?.speech_style?.default || ''
  const isQwen = isQwenTtsProvider(provider)
  const isOpenVox = provider === 'openvox_tts'
  const fishDictionaryInvalid = provider === 'fish_audio' && !!fishDictionaryError(defaultParameters)
  const qwenLanguage = typeof defaultParameters.language === 'string'
    && QWEN_LANGUAGE_OPTIONS.some((option) => option.value === defaultParameters.language)
    ? defaultParameters.language
    : 'Auto'
  const qwenInstruct = typeof defaultParameters.instruct === 'string'
    ? defaultParameters.instruct
    : ''
  const qwenUseStreaming = defaultParameters.use_streaming_endpoint !== false

  const modelOptions = useMemo(() => {
    const options = models.length > 0 ? models : capabilities?.staticModels || []
    if (model && !options.some((option) => option.id === model)) {
      return [{ id: model, label: model }, ...options]
    }
    return options
  }, [capabilities?.staticModels, model, models])

  const modelIds = useMemo(() => modelOptions.map((option) => option.id), [modelOptions])

  const modelLabels = useMemo(() => {
    return Object.fromEntries(
      modelOptions
        .filter((option) => option.label && option.label !== option.id)
        .map((option) => [option.id, option.label])
    )
  }, [modelOptions])

  const voiceOptions = useMemo(() => {
    const options = voices.length > 0 ? voices : capabilities?.staticVoices || []
    if (voice && !options.some((option) => option.id === voice)) {
      return [{ id: voice, name: voice }, ...options]
    }
    return options
  }, [voices, capabilities?.staticVoices, voice])

  const voiceIds = useMemo(() => voiceOptions.map((option) => option.id), [voiceOptions])

  const voiceLabels = useMemo(() => {
    return Object.fromEntries(
      voiceOptions.map((option) => {
        const label = getTtsVoiceLabel(option)
        const sublabel = getTtsVoiceSublabel(option)
        return [option.id, sublabel ? `${label} — ${sublabel}` : label]
      })
    )
  }, [voiceOptions])

  // Handle service account JSON file upload
  const handleFileUpload = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return
    const reader = new FileReader()
    reader.onload = () => {
      try {
        const text = reader.result as string
        // Validate it's valid JSON with required fields
        const parsed = JSON.parse(text)
        if (!parsed.private_key || !parsed.client_email || !parsed.project_id) {
          alert(t('connectionForm.invalidServiceAccountMissingFields'))
          return
        }
        // Store the raw JSON as the "API key"
        setApiKey(text)
        setSaFileName(file.name)
      } catch {
        alert(t('connectionForm.invalidJsonFile'))
      }
    }
    reader.readAsText(file)
    // Reset file input so the same file can be re-selected
    e.target.value = ''
  }, [t])

  const fetchModels = useCallback(async () => {
    setModelsLoading(true)
    try {
      const metadata: Record<string, any> = { ...profile?.metadata }
      if (isVertex) {
        metadata.vertex_region = vertexRegion
      }
      const result = await ttsConnectionsApi.previewModels({
        connection_id: profile?.id,
        provider,
        api_url: isVertex ? undefined : (apiUrl.trim() || undefined),
        metadata: Object.keys(metadata).length > 0 ? metadata : undefined,
        api_key: apiKey.trim() || undefined,
      })
      setModels(result.models)
    } catch {
      setModels([])
    } finally {
      setModelsLoading(false)
    }
  }, [apiKey, apiUrl, isVertex, profile?.id, profile?.metadata, provider, vertexRegion])

  const cancelVoicesRequest = useCallback(() => {
    const request = voicesRequestRef.current
    request.controller?.abort()
    voicesRequestRef.current = { generation: request.generation + 1 }
  }, [])

  const fetchVoices = useCallback(async () => {
    const previousRequest = voicesRequestRef.current
    previousRequest.controller?.abort()
    const controller = new AbortController()
    const generation = previousRequest.generation + 1
    voicesRequestRef.current = { generation, controller }
    setVoicesLoading(true)
    try {
      const metadata: Record<string, any> = { ...profile?.metadata }
      if (isVertex) {
        metadata.vertex_region = vertexRegion
      }
      const result = await ttsConnectionsApi.previewVoices(
        {
          connection_id: profile?.id,
          provider,
          api_url: isVertex ? undefined : (apiUrl.trim() || undefined),
          metadata: Object.keys(metadata).length > 0 ? metadata : undefined,
          api_key: apiKey.trim() || undefined,
          model: model.trim() || undefined,
        },
        { signal: controller.signal },
      )
      if (voicesRequestRef.current.generation !== generation) return
      setVoices(result.voices)
    } catch {
      if (voicesRequestRef.current.generation !== generation) return
      setVoices([])
    } finally {
      if (voicesRequestRef.current.generation === generation) {
        voicesRequestRef.current = { generation }
        setVoicesLoading(false)
      }
    }
  }, [apiKey, apiUrl, isVertex, model, profile?.id, profile?.metadata, provider, vertexRegion])

  const handleModelChange = useCallback((nextModel: string) => {
    setModel(nextModel)
    if (isOpenVox && nextModel !== model) {
      cancelVoicesRequest()
      setVoicesLoading(false)
      setVoice('')
      setVoices([])
      setDefaultParameters((prev) => {
        const updated = { ...prev }
        delete updated.language
        return updated
      })
    }
  }, [cancelVoicesRequest, isOpenVox, model])

  const handleVoiceChange = useCallback((nextVoice: string) => {
    setVoice(nextVoice)
    if (!isOpenVox) return

    const selectedVoice = voiceOptions.find((option) => option.id === nextVoice)
    if (!selectedVoice?.language) return
    setDefaultParameters((prev) => ({
      ...prev,
      language: selectedVoice.language,
    }))
  }, [isOpenVox, voiceOptions])

  useEffect(() => {
    if (profile?.id && capabilities?.voiceListStyle === 'dynamic') {
      void fetchVoices()
    }
    return cancelVoicesRequest
  }, [profile?.id, capabilities?.voiceListStyle, fetchVoices, cancelVoicesRequest])

  useEffect(() => {
    if (profile?.id && capabilities?.modelListStyle === 'dynamic') {
      fetchModels()
    }
  }, [profile?.id, capabilities?.modelListStyle, fetchModels])

  const setQwenLanguage = useCallback((next: string) => {
    setDefaultParameters((prev) => {
      const updated = { ...prev }
      if (!next || next === 'Auto') {
        delete updated.language
      } else {
        updated.language = next
      }
      return updated
    })
  }, [])

  const setQwenInstruct = useCallback((next: string) => {
    setDefaultParameters((prev) => {
      const updated = { ...prev }
      if (!next.trim()) {
        delete updated.instruct
      } else {
        updated.instruct = next
      }
      return updated
    })
  }, [])

  const setGoogleUseStreaming = useCallback((next: boolean) => {
    setDefaultParameters((prev) => {
      const updated = { ...prev }
      if (next) {
        delete updated.use_streaming_endpoint
      } else {
        updated.use_streaming_endpoint = false
      }
      return updated
    })
  }, [])

  const setQwenUseStreaming = useCallback((next: boolean) => {
    setDefaultParameters((prev) => {
      const updated = { ...prev }
      if (next) {
        delete updated.use_streaming_endpoint
      } else {
        updated.use_streaming_endpoint = false
      }
      return updated
    })
  }, [])

  const handleSubmit = useCallback(() => {
    if (!name.trim()) return
    const metadata: Record<string, any> = { ...profile?.metadata }
    if (isVertex) {
      metadata.vertex_region = vertexRegion
      if (saFileName) metadata.sa_file_name = saFileName
    } else {
      delete metadata.vertex_region
      delete metadata.sa_file_name
    }
    const qwenDefaults: Record<string, any> = {}
    if (isQwen && typeof defaultParameters.language === 'string' && defaultParameters.language) {
      qwenDefaults.language = defaultParameters.language
    }
    if (isQwen && typeof defaultParameters.instruct === 'string' && defaultParameters.instruct.trim()) {
      qwenDefaults.instruct = defaultParameters.instruct.trim()
    }
    if (isQwen && defaultParameters.use_streaming_endpoint === false) {
      qwenDefaults.use_streaming_endpoint = false
    }
    const googleDefaults: Record<string, any> = { ...defaultParameters }
    if (defaultParameters.use_streaming_endpoint === false) {
      googleDefaults.use_streaming_endpoint = false
    } else {
      delete googleDefaults.use_streaming_endpoint
    }
    const openVoxDefaults: Record<string, any> = {}
    if (isOpenVox && typeof defaultParameters.language === 'string' && defaultParameters.language.trim()) {
      openVoxDefaults.language = defaultParameters.language.trim()
    }
    onSave({
      name: name.trim(),
      provider,
      api_key: apiKey.trim() || undefined,
      api_url: isVertex ? undefined : (apiUrl.trim() || undefined),
      model: model.trim() || undefined,
      voice: voice.trim() || undefined,
      is_default: isDefault,
      default_parameters: isQwen
        ? qwenDefaults
        : isGoogle
          ? (Object.keys(googleDefaults).length > 0 ? googleDefaults : undefined)
          : provider === 'openrouter_tts' && Object.keys(defaultParameters).length > 0
            ? defaultParameters
            : isOpenVox && Object.keys(openVoxDefaults).length > 0
              ? openVoxDefaults
              : Object.keys(defaultParameters).length > 0
                ? defaultParameters
                : undefined,
      metadata: Object.keys(metadata).length > 0 ? metadata : undefined,
    }, folder.value)
  }, [name, provider, apiKey, apiUrl, model, voice, isDefault, isQwen, isGoogle, isOpenVox, defaultParameters, folder.value, onSave, isVertex, vertexRegion, saFileName, profile?.metadata])

  return (
    <div className={styles.form}>
      <FormField label={t('ttsConnectionForm.name')} required>
        <TextInput value={name} onChange={setName} placeholder={t('ttsConnectionForm.connectionName')} autoFocus={!profile} />
      </FormField>
      <ConnectionFolderField kind="tts" {...folder} />

      <FormField label={t('ttsConnectionForm.provider')}>
        <Select value={provider} onChange={setProvider} options={providerOptions} />
      </FormField>

      {isVertex ? (
        <>
          <FormField
            label={t('connectionForm.serviceAccountJson')}
            hint={
              profile?.has_api_key
                ? t('connectionForm.credentialsLoaded', { file: saFileName ? ` (${saFileName})` : '' })
                : t('connectionForm.uploadServiceAccount')
            }
          >
            <div className={styles.fileUploadRow}>
              <Button
                variant="secondary"
                size="sm"
                onClick={() => fileInputRef.current?.click()}
              >
                {apiKey ? t('connectionForm.fileLoaded') : t('connectionForm.chooseFile')}
              </Button>
              {(saFileName || apiKey) && (
                <span className={styles.fileUploadName}>
                  {saFileName || t('connectionForm.serviceAccountFilename')}
                </span>
              )}
              <input
                ref={fileInputRef}
                type="file"
                accept=".json,application/json"
                onChange={handleFileUpload}
                style={{ display: 'none' }}
              />
            </div>
          </FormField>
          <FormField label={t('connectionForm.region')} hint={t('connectionForm.vertexRegionHint')}>
            <Select
              value={vertexRegion}
              onChange={setVertexRegion}
              options={VERTEX_REGIONS.map((r) => ({ value: r, label: r }))}
            />
          </FormField>
        </>
      ) : (
        <>
          {capabilities?.apiKeyRequired && (
            <FormField label={t('ttsConnectionForm.apiKey')} hint={profile?.has_api_key ? t('ttsConnectionForm.keySetHint') : undefined}>
              <TextInput
                value={apiKey}
                onChange={setApiKey}
                placeholder={profile?.has_api_key ? '••••••••' : t('ttsConnectionForm.enterApiKey')}
                type="password"
              />
            </FormField>
          )}

          <FormField label={t('ttsConnectionForm.apiUrl')} hint={t('ttsConnectionForm.apiUrlHint')}>
            <TextInput
              value={apiUrl}
              onChange={setApiUrl}
              placeholder={capabilities?.defaultUrl || 'https://...'}
            />
          </FormField>
        </>
      )}

      <FormField label={t('ttsConnectionForm.model')} hint={capabilities?.modelListStyle === 'dynamic' ? t('ttsConnectionForm.refreshHint') : undefined}>
        <ModelCombobox
          value={model}
          onChange={handleModelChange}
          models={modelIds}
          modelLabels={modelLabels}
          loading={modelsLoading}
          onRefresh={capabilities?.modelListStyle === 'dynamic' ? fetchModels : undefined}
          autoRefreshOnFocus={capabilities?.modelListStyle === 'dynamic'}
          refreshKey={`${provider}:${profile?.id || ''}:models`}
          appearance="standard"
          placeholder={t('ttsConnectionForm.modelPlaceholder')}
          emptyMessage={t('ttsConnectionForm.noTtsModels')}
        />
      </FormField>

      <FormField label={t('ttsConnectionForm.voice')} hint={capabilities?.voiceListStyle === 'dynamic' ? t('ttsConnectionForm.refreshHint') : undefined}>
        <ModelCombobox
          value={voice}
          onChange={handleVoiceChange}
          models={voiceIds}
          modelLabels={voiceLabels}
          loading={voicesLoading}
          onRefresh={capabilities?.voiceListStyle === 'dynamic' ? fetchVoices : undefined}
          autoRefreshOnFocus={capabilities?.voiceListStyle === 'dynamic'}
          refreshKey={`${provider}:${profile?.id || ''}:${model}:voices`}
          disabled={isOpenVox && !model.trim()}
          appearance="standard"
          placeholder={isQwen ? t('ttsConnectionForm.qwenVoicePlaceholder') : t('ttsConnectionForm.voicePlaceholder')}
          emptyMessage={t('ttsConnectionForm.noVoices')}
        />
      </FormField>

      {capabilities?.supportsVoiceLibrary && <Button size="sm" onClick={() => setLibraryOpen(true)}>{t('shared:voicePicker.voiceLibrary')}</Button>}
      {libraryOpen && capabilities?.supportsVoiceLibrary && <Suspense fallback={null}><VoiceLibraryModal
        connection={libraryConnection}
        value={voice}
        onClose={() => setLibraryOpen(false)}
        onSelect={(selected) => {
          setVoices((previous) => [...previous.filter((item) => item.id !== selected.id), selected])
          handleVoiceChange(selected.id)
        }}
      /></Suspense>}

      {supportsGeminiSpeechStyle && (
        <FormField label={t('ttsConnectionForm.geminiSpeechStyle')} hint={t('ttsConnectionForm.geminiSpeechStyleHint')}>
          <TextArea
            value={geminiSpeechStyle}
            onChange={(speech_style) => setDefaultParameters((previous) => ({ ...previous, speech_style }))}
            aria-label={t('ttsConnectionForm.geminiSpeechStyle')}
            rows={2}
          />
        </FormField>
      )}

      {provider === 'fish_audio' && capabilities && (
        <FishAudioSettings model={model} schema={capabilities.parameters} values={defaultParameters} onChange={setDefaultParameters} />
      )}

      {isGoogle && (
        <FormField label="">
          <Toggle.Checkbox
            checked={googleUseStreaming}
            onChange={setGoogleUseStreaming}
            label={t('ttsConnectionForm.qwenUseStreaming')}
            hint={t('ttsConnectionForm.qwenUseStreamingHint')}
          />
        </FormField>
      )}

      {isQwen && (
        <>
          <FormField label={t('ttsConnectionForm.qwenLanguage')} hint={t('ttsConnectionForm.qwenLanguageHint')}>
            <Select
              value={qwenLanguage}
              onChange={setQwenLanguage}
              options={QWEN_LANGUAGE_OPTIONS.map((option) => ({
                value: option.value,
                label: option.value === 'Auto' ? t('ttsConnectionForm.qwenLanguageAuto') : option.label,
              }))}
            />
          </FormField>

          <FormField label={t('ttsConnectionForm.qwenInstruct')} hint={t('ttsConnectionForm.qwenInstructHint')}>
            <TextArea
              value={qwenInstruct}
              onChange={setQwenInstruct}
              placeholder={t('ttsConnectionForm.qwenInstructPlaceholder')}
              rows={3}
            />
          </FormField>

          <FormField label="">
            <Toggle.Checkbox
              checked={qwenUseStreaming}
              onChange={setQwenUseStreaming}
              label={t('ttsConnectionForm.qwenUseStreaming')}
              hint={t('ttsConnectionForm.qwenUseStreamingHint')}
            />
          </FormField>

          <div className={styles.bindingCard}>
            <div className={styles.bindingCardTitle}>{t('ttsConnectionForm.qwenCloneTitle')}</div>
            <div className={styles.bindingCardHint}>
              {profile
                ? t('ttsConnectionForm.qwenCloneHintSaved')
                : t('ttsConnectionForm.qwenCloneHintUnsaved')}
            </div>
          </div>
        </>
      )}

      <FormField label="">
        <Toggle.Checkbox checked={isDefault} onChange={setIsDefault} label={t('ttsConnectionForm.setDefault')} />
      </FormField>

      <div className={styles.formActions}>
        <Button variant="ghost" size="sm" onClick={onCancel}>{t('ttsConnectionForm.cancel')}</Button>
        <Button variant="primary" size="sm" onClick={handleSubmit} disabled={!name.trim() || fishDictionaryInvalid}>
          {profile ? t('ttsConnectionForm.save') : t('ttsConnectionForm.create')}
        </Button>
      </div>
    </div>
  )
}

import type { ConnectionPlacement } from '@/lib/connectionPlacement'
import { useConnectionRow } from '@/components/panels/connection-manager/useConnectionRow'
import { saveConnectionFolder } from '@/hooks/useConnectionLibrary'
import { useState, useEffect, useCallback } from 'react'
import { useTranslation } from 'react-i18next'

import { Trash2, Edit3, Zap, Star, Copy, MoreVertical, Volume2, GripVertical } from 'lucide-react'
import { ttsConnectionsApi } from '@/api/tts-connections'
import { formatTtsConnectionVoiceLabel, isQwenTtsProvider } from '@/lib/qwenTts'
import { useStore } from '@/store'
import type { TtsConnectionProfile, TtsProviderInfo, CreateTtsConnectionInput } from '@/types/api'
import TTSConnectionForm from './TTSConnectionForm'
import ContextMenu, { type ContextMenuEntry, type ContextMenuPos } from '@/components/shared/ContextMenu'
import ProviderIcon from '@/components/shared/ProviderIcon'
import styles from '../connection-manager/ConnectionItem.module.css'
import clsx from 'clsx'

interface Props {
  placement?: ConnectionPlacement
  profile: TtsConnectionProfile
  providers: TtsProviderInfo[]
  onUpdate: (profile: TtsConnectionProfile) => void
  onDuplicate: () => void
  onDelete: () => void
}

export default function TTSConnectionItem({
  placement = 'list', profile, providers, onUpdate, onDuplicate, onDelete }: Props) {
  const { t: tc } = useTranslation('common')
  const { t } = useTranslation('panels')
  const openModal = useStore((s) => s.openModal)
  const { editing, setEditing, isRecent, ...sortable } = useConnectionRow(profile.id, placement)
  const [testing, setTesting] = useState(false)
  const [testResult, setTestResult] = useState<{ success: boolean; message: string } | null>(null)
  const [menuPos, setMenuPos] = useState<ContextMenuPos | null>(null)
  const isQwen = isQwenTtsProvider(profile.provider)
  const voiceLabel = formatTtsConnectionVoiceLabel(profile)

  useEffect(() => {
    if (!testResult) return
    const timer = setTimeout(() => setTestResult(null), 5000)
    return () => clearTimeout(timer)
  }, [testResult])

  const handleTest = useCallback(async () => {
    setTesting(true)
    setTestResult(null)
    try {
      const result = await ttsConnectionsApi.test(profile.id)
      setTestResult({ success: result.success, message: result.message })
    } catch (err: any) {
      setTestResult({ success: false, message: err.message || t('connectionItem.connectionFailed') })
    } finally {
      setTesting(false)
    }
  }, [profile.id, t])

  const handleSaveEdit = useCallback(async (input: CreateTtsConnectionInput, folderId = '') => {
    try {
      const updated = await ttsConnectionsApi.update(profile.id, input)
      saveConnectionFolder('tts', profile.id, folderId)
      onUpdate(updated)
      setEditing(false)
    } catch (err) {
      console.error('[TTSConnectionItem] Failed to update:', err)
    }
  }, [profile.id, onUpdate, setEditing])

  const { attributes, listeners, setNodeRef, style, isDragging, handleRef } = sortable

  return (
    <div ref={setNodeRef} style={style} data-dragging={isDragging || undefined} className={clsx(styles.item, isDragging && styles.itemDragging)}>
      {editing ? (
        <TTSConnectionForm
          providers={providers}
          profile={profile}
          onSave={handleSaveEdit}
          onCancel={() => setEditing(false)}
        />
      ) : (
        <>
          <div className={styles.itemRow}>
            {!isRecent && <button
              ref={handleRef}
              type="button"
              className={styles.dragHandle}
              aria-label={t('connectionItem.dragToReorder')}
              title={t('connectionItem.dragToReorder')}
              {...attributes}
              {...listeners}
            >
              <GripVertical size={16} />
            </button>}
            <div className={styles.itemBtn} onMouseDown={event => listeners?.onMouseDown?.(event)} onTouchStart={event => listeners?.onTouchStart?.(event)} style={{ cursor: 'default' }}>
              <ProviderIcon kind="tts" provider={profile.provider} size={32} iconSize={16} className={styles.itemIcon} />
              <div className={styles.itemInfo}>
                <span className={styles.itemName}>
                  {profile.name}
                  {profile.is_default && <Star size={11} className={styles.defaultStar} fill="#f5a623" />}
                </span>
                <span className={styles.itemMeta}>
                  {profile.provider}
                  {profile.model ? ` / ${profile.model}` : ''}
                  {voiceLabel ? ` / ${voiceLabel}` : ''}
                </span>
              </div>
            </div>
            <div className={styles.itemActions}>
              <button type="button" className={styles.actionBtn} onClick={() => setEditing(true)} title={tc('actions.edit')}>
                <Edit3 size={13} />
              </button>
              <button
                type="button"
                className={styles.actionBtn}
                onClick={(e) => {
                  const rect = e.currentTarget.getBoundingClientRect()
                  setMenuPos({ x: rect.right, y: rect.bottom + 4 })
                }}
                title={t('connectionItem.moreActions')}
              >
                <MoreVertical size={13} />
              </button>
              <ContextMenu
                position={menuPos}
                onClose={() => setMenuPos(null)}
                items={[
                  { key: 'test', label: testing ? t('connectionItem.testing') : t('connectionItem.testConnection'), icon: <Zap size={14} />, onClick: () => { setMenuPos(null); handleTest() }, disabled: testing },
                  ...(isQwen
                    ? [{
                        key: 'qwen-clones',
                        label: t('qwenCustomVoiceManager.menuAction'),
                        icon: <Volume2 size={14} />,
                        onClick: () => {
                          setMenuPos(null)
                          openModal('qwenCustomVoice', { connectionId: profile.id })
                        },
                      }]
                    : []),
                  { key: 'duplicate', label: t('connectionItem.duplicate'), icon: <Copy size={14} />, onClick: () => { setMenuPos(null); onDuplicate() } },
                  { key: 'div', type: 'divider' as const },
                  { key: 'delete', label: t('connectionItem.delete'), icon: <Trash2 size={14} />, onClick: () => { setMenuPos(null); onDelete() }, danger: true },
                ] satisfies ContextMenuEntry[]}
              />
            </div>
          </div>
          {testResult && (
            <div className={clsx(styles.testMessage, testResult.success ? styles.testMessageSuccess : styles.testMessageFail)}>
              {testResult.message}
            </div>
          )}
        </>
      )}
    </div>
  )
}

import ConnectionCollection from '../connection-manager/ConnectionCollection'
import { useConnectionLibrary, saveConnectionFolder } from '@/hooks/useConnectionLibrary'
import { useState, useEffect, useCallback, useMemo } from 'react'
import { Plus } from 'lucide-react'
import { useTranslation } from 'react-i18next'
import { ttsConnectionsApi } from '@/api/tts-connections'
import { listAllConnections } from '@/api/listAllConnections'
import { useStore } from '@/store'
import ConfirmationModal from '@/components/shared/ConfirmationModal'
import TTSConnectionForm from './TTSConnectionForm'
import TTSConnectionItem from './TTSConnectionItem'
import type { TtsConnectionProfile, CreateTtsConnectionInput } from '@/types/api'
import styles from '../ConnectionManager.module.css'
import { normalizeConnectionsOrder } from '@/store/slices/connections-order-merge'

export default function TTSConnectionManager() {
  const { t } = useTranslation('panels')
  const profiles = useStore((s) => s.ttsProfiles)
  const setProfiles = useStore((s) => s.setTtsProfiles)
  const addProfile = useStore((s) => s.addTtsProfile)
  const updateProfile = useStore((s) => s.updateTtsProfile)
  const removeProfile = useStore((s) => s.removeTtsProfile)
  const applyProfileOrder = useStore((s) => s.applyTtsProfileOrder)
  const providers = useStore((s) => s.ttsProviders)
  const setProviders = useStore((s) => s.setTtsProviders)
  const setSetting = useStore((s) => s.setSetting)
  const connectionsOrder = useStore((s) => s.connectionsOrder)

  const library = useConnectionLibrary('tts')

  const orderedProfiles = useMemo(() => {
    const ttsOrder = connectionsOrder?.tts ?? []
    if (ttsOrder.length === 0) return profiles
    const byId = new Map(profiles.map((p) => [p.id, p]))
    const ordered = ttsOrder.map((id) => byId.get(id)).filter((p): p is TtsConnectionProfile => Boolean(p))
    const seen = new Set(ordered.map((p) => p.id))
    const missing = profiles.filter((p) => !seen.has(p.id))
    return [...ordered, ...missing]
  }, [profiles, connectionsOrder])

  const [loading, setLoading] = useState(false)
  const [creating, setCreating] = useState(false)
  const [deleteTarget, setDeleteTarget] = useState<TtsConnectionProfile | null>(null)

  // `useAppInit` preloads TTS profiles + providers right after auth. Only
  // show the loading placeholder on a true cold mount (empty store);
  // otherwise render from the store and refresh silently in the background.
  useEffect(() => {
    let cancelled = false

    const storeState = useStore.getState()
    const cacheHit = storeState.ttsProfiles.length > 0 && storeState.ttsProviders.length > 0

    async function init() {
      if (!cacheHit) setLoading(true)
      try {
        const [profilesResult, providersResult] = await Promise.allSettled([
          listAllConnections(ttsConnectionsApi),
          ttsConnectionsApi.providers(),
        ])

        if (cancelled) return

        if (profilesResult.status === 'fulfilled') {
          setProfiles(profilesResult.value.data)
        }

        if (providersResult.status === 'fulfilled') {
          setProviders(providersResult.value.providers)
        }
      } catch (err) {
        console.error('[TTSConnectionManager] Init failed:', err)
      } finally {
        if (!cancelled && !cacheHit) setLoading(false)
      }
    }

    init()
    return () => { cancelled = true }
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  const handleCreate = useCallback(async (input: CreateTtsConnectionInput, folderId = '') => {
    try {
      const profile = await ttsConnectionsApi.create(input)
      saveConnectionFolder('tts', profile.id, folderId)
      addProfile(profile)
      if (input.is_default) {
        profiles.forEach((p) => {
          if (p.id !== profile.id && p.is_default) updateProfile(p.id, { is_default: false })
        })
      }
      setCreating(false)
    } catch (err) {
      console.error('[TTSConnectionManager] Failed to create:', err)
    }
  }, [profiles, addProfile, updateProfile])

  const handleUpdate = useCallback((updated: TtsConnectionProfile) => {
    updateProfile(updated.id, updated)
    if (updated.is_default) {
      profiles.forEach((p) => {
        if (p.id !== updated.id && p.is_default) updateProfile(p.id, { is_default: false })
      })
    }
  }, [profiles, updateProfile])

  const handleDuplicate = useCallback(async (id: string) => {
    try {
      const duplicated = await ttsConnectionsApi.duplicate(id)
      addProfile(duplicated)
      library.copyFolder(id, duplicated.id)
    } catch (err) {
      console.error('[TTSConnectionManager] Failed to duplicate:', err)
    }
  }, [addProfile, library])

  const handleDelete = useCallback(async () => {
    if (!deleteTarget) return
    try {
      await ttsConnectionsApi.delete(deleteTarget.id)
      removeProfile(deleteTarget.id)
      library.forget(deleteTarget.id)
      const normalizedOrder = normalizeConnectionsOrder(connectionsOrder)
      const nextOrder = normalizedOrder.tts.filter((id) => id !== deleteTarget.id)
      setSetting('connectionsOrder', { ...normalizedOrder, tts: nextOrder })
      setDeleteTarget(null)
    } catch (err) {
      console.error('[TTSConnectionManager] Failed to delete:', err)
    }
  }, [deleteTarget, removeProfile, connectionsOrder, setSetting, library])

  const handleReorder = (ids: string[]) => {
    applyProfileOrder(ids)
    setSetting('connectionsOrder', { ...normalizeConnectionsOrder(useStore.getState().connectionsOrder), tts: ids })
  }

  if (loading) {
    return <div className={styles.loading}>{t('ttsConnectionManager.loading')}</div>
  }

  return (
    <div className={styles.manager}>
      <ConnectionCollection kind="tts" profiles={orderedProfiles} onReorder={handleReorder}
        actions={!creating && (
          <button type="button" className={styles.createBtn} onClick={() => setCreating(true)}>
            <Plus size={14} />
            <span>{t('ttsConnectionManager.newConnection')}</span>
          </button>
        )}
        editor={creating && (
          <TTSConnectionForm
            providers={providers}
            onSave={handleCreate}
            onCancel={() => setCreating(false)}
          />
        )}
        emptyMessage={creating ? '' : t('ttsConnectionManager.empty')}
        renderProfile={(profile, placement) => (
          <TTSConnectionItem
            placement={placement}
            key={profile.id}
            profile={profile}
            providers={providers}
            onUpdate={handleUpdate}
            onDuplicate={() => handleDuplicate(profile.id)}
            onDelete={() => setDeleteTarget(profile)}
          />
        )} />

      {deleteTarget && (
        <ConfirmationModal
          title={t('ttsConnectionManager.deleteTitle')}
          message={t('ttsConnectionManager.deleteMessage', { name: deleteTarget.name })}
          isOpen={true}
          variant="danger"
          confirmText={t('ttsConnectionManager.deleteConfirm')}
          onConfirm={handleDelete}
          onCancel={() => setDeleteTarget(null)}
        />
      )}
    </div>
  )
}

