}

.entryMetaItem {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
  padding: 1px 6px;
  border-radius: 4px;
  background: var(--lumiverse-fill-medium, var(--lumiverse-fill-strong));
  line-height: 1.5;
  white-space: nowrap;
}

.entryToggle {
  accent-color: var(--lumiverse-primary);
  cursor: pointer;
  flex-shrink: 0;
}

.entryDeleteBtn {
  width: 20px;
  height: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 4px;
  background: transparent;
  border: none;
  color: var(--lumiverse-text-dim);
  cursor: pointer;
  opacity: 0;
  flex-shrink: 0;
  margin-right: -6px;
  transition: all var(--lumiverse-transition-fast);
}

.entryRow:hover .entryDeleteBtn {
  opacity: 1;
}

.entryDeleteBtn:hover {
  color: var(--lumiverse-error);
}

/* ── Empty state ── */
.emptyState {
  padding: 24px 12px;
  text-align: center;
  color: var(--lumiverse-text-dim);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
