.root {
  z-index: 40;
  pointer-events: auto;
}

.root[data-opaque-backdrop='1'] {
  isolation: isolate;
}

.root[data-opaque-backdrop='1']::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background: var(--quick-toolbar-backdrop-color, var(--lumiverse-bg-opaque));
}

.root[data-opaque-backdrop='1'] > * {
  position: relative;
  z-index: 1;
}

/*
 * The rect *is* the toolbar's box. The rendered box, the persisted value and the
 * eight resize handles therefore agree by construction — the previous rule sized
 * an invisible `fit-content` container and centred the nav inside it, so
 * dragging a handle grew the container and re-centred the toolbar. It moved; it
 * never resized. Same CSS-variable pattern as `ResizablePanelFrame`.
 */
.rootFree {
  position: fixed;
  left: var(--quick-toolbar-x, 0px);
  top: var(--quick-toolbar-y, 0px);
  width: var(--quick-toolbar-width, auto);
  height: var(--quick-toolbar-height, max-content);
  z-index: var(--z-quick-toolbar-floating, 10005);
  display: flex;
  /* Moved off `.toolbar` so the grip and all eight handles rotate *with* the
     toolbar instead of detaching from it. */
  transform: rotate(var(--quick-toolbar-rotation, 0deg));
  transform-origin: center;
  user-select: none;
}

/*
 * `justify-content: center` is load-bearing, not decoration. The dock stretches
 * this root across the whole chat column (`ChatView.module.css`
 * `.topDockToolbarSlot > * { flex: 1 1 auto }`), so a content-width strip inside
 * it would otherwise pin to the left edge. Centring here means the confirmed
 * design holds whether or not the dock is ever relaxed.
 */
.rootAnchored {
  position: relative;
  display: flex;
  flex: 0 0 auto;
  width: auto;
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  align-items: center;
  justify-content: center;
  align-self: center;
}

/* V1 docked: fill the rail so the icon group centres as a unit and expands symmetrically. */
.rootAnchored[data-quick-toolbar-variant='v1'] {
  flex: 1 1 auto;
  align-self: stretch;
  width: 100%;
  height: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
}

.rootAnchored[data-quick-toolbar-variant='v1'] .toolbarHorizontal {
  width: auto;
  max-width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  margin-inline: auto;
}

/* Docked V2 uses the leftover flex column; never the full chatToolbar width. */
.rootAnchored[data-quick-toolbar-placement='chat_top_dock'][data-quick-toolbar-variant='v2'] {
  flex: 1 1 auto;
  min-width: 0;
  width: auto;
  max-width: 100%;
}

/* Option B: Container Proportional Fill (Bounded to Column Width, Zero Trailing Waste) */
.rootAnchored[data-quick-toolbar-placement='chat_top_dock'][data-quick-toolbar-variant='v2'] {
  flex: 1 1 auto;
  width: 100%;
  min-width: 0;
  justify-content: flex-start !important;
  align-self: stretch !important;
}

.rootAnchored[data-quick-toolbar-placement='chat_top_dock'][data-quick-toolbar-variant='v2'] .cardStrip {
  width: 100%;
  flex: 1 1 auto;
  justify-content: flex-start;
  align-self: stretch;
}

.rootAnchored[data-quick-toolbar-placement='chat_top_dock'][data-quick-toolbar-variant='v2'] .cardScroller {
  width: 100% !important;
  max-width: 100% !important;
  display: flex !important;
  justify-content: stretch !important;
  align-items: center !important;
  box-sizing: border-box !important;
  padding: 0 !important;
  margin: 0 !important;
  gap: 6px !important;
}

.rootAnchored[data-quick-toolbar-placement='chat_top_dock'][data-quick-toolbar-variant='v2'] .cardSlot {
  width: 100% !important;
  min-width: 0 !important;
  max-width: 100% !important;
  flex: 1 1 0px !important;
  display: flex !important;
  align-items: center !important;
  gap: 6px !important;
  box-sizing: border-box !important;
  overflow: visible !important;
  padding: 0 !important;
  margin: 0 !important;
}

.rootAnchored[data-quick-toolbar-placement='chat_top_dock'][data-quick-toolbar-variant='v2'] .cardSlot .card,
.rootAnchored[data-quick-toolbar-placement='chat_top_dock'][data-quick-toolbar-variant='v2'] .cardSlot button,
.rootAnchored[data-quick-toolbar-placement='chat_top_dock'][data-quick-toolbar-variant='v2'] .cardSlot a,
.rootAnchored[data-quick-toolbar-placement='chat_top_dock'][data-quick-toolbar-variant='v2'] .cardSlot [role='button'] {
  width: 100% !important;
  max-width: none !important;
  flex: 1 1 auto !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  min-width: 0 !important;
  padding: 2px 6px !important;
  gap: 4px !important;
  box-sizing: border-box !important;
  white-space: nowrap !important;
  text-overflow: ellipsis !important;
  text-align: center !important;
}

.rootAnchored[data-quick-toolbar-placement='chat_top_dock'][data-quick-toolbar-variant='v2'] .cardSlot button span,
.rootAnchored[data-quick-toolbar-placement='chat_top_dock'][data-quick-toolbar-variant='v2'] .cardSlot a span,
.rootAnchored[data-quick-toolbar-placement='chat_top_dock'][data-quick-toolbar-variant='v2'] .cardSlot [role='button'] span {
  text-align: center !important;
}

.fillDockSpacer {
  display: none !important;
  width: 0 !important;
  height: 0 !important;
  flex: 0 0 0 !important;
  min-width: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
}

/* Option A: Full-Screen Breakout Proportional Fill (Zero Edge Waste) */
.rootFree[data-fill-screen='1'] {
  position: fixed !important;
  top: 0 !important;
  left: 0 !important;
  width: 100% !important;
  max-width: 100% !important;
  z-index: var(--z-quick-toolbar-floating, 10005) !important;
  background: var(--lcs-glass-bg, rgba(24, 24, 27, 0.94)) !important;
  backdrop-filter: blur(12px) var(--lcs-liquid-filter, ) !important;
  border-bottom: 1px solid var(--lumiverse-border, rgba(255, 255, 255, 0.12)) !important;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.45) !important;
  box-sizing: border-box !important;
  padding: 0 4px !important;
  margin: 0 !important;
  --quick-toolbar-x: 0px;
}

.rootFree[data-fill-screen='1'] .cardScroller {
  width: 100% !important;
  max-width: 100% !important;
  display: flex !important;
  justify-content: stretch !important;
  align-items: center !important;
  box-sizing: border-box !important;
  padding: 0 !important;
  margin: 0 !important;
  gap: 6px !important;
}

.rootFree[data-fill-screen='1'] .cardSlot {
  width: 100% !important;
  min-width: 0 !important;
  max-width: 100% !important;
  flex: 1 1 0px !important;
  display: flex !important;
  align-items: center !important;
  gap: 6px !important;
  box-sizing: border-box !important;
  overflow: visible !important;
  padding: 0 !important;
  margin: 0 !important;
}

.rootFree[data-fill-screen='1'] .cardSlot .card,
.rootFree[data-fill-screen='1'] .cardSlot button {
  width: 100% !important;
  max-width: none !important;
  flex: 1 1 auto !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  min-width: 0 !important;
  padding: 0 8px !important;
  box-sizing: border-box !important;
  white-space: nowrap !important;
  text-overflow: ellipsis !important;
  text-align: center !important;
}

.rootFree[data-fill-screen='1'] .cardSlot .card span,
.rootFree[data-fill-screen='1'] .cardSlot button span {
  text-align: center !important;
}

.rootFree[data-autofit='1']:not([data-fill-screen='1']) {
  width: max-content !important;
  max-width: 100%;
  margin: 0 !important;
}

.rootFree[data-autofit='1']:not([data-fill-screen='1']) > .toolbar {
  width: max-content !important;
  max-width: 100%;
  justify-content: flex-start;
}

.rootFree .cardStrip {
  justify-content: flex-start;
}

.root[data-quick-toolbar-placement='chat_top_dock'] {
  flex: 1 1 auto;
  width: 100%;
  max-width: 100%;
  margin: 0;
}

.root[data-quick-toolbar-placement='chat_top_dock'] > .toolbar {
  width: 100%;
  justify-content: flex-start;
}

/* Keep the explicit opt-out meaningful after the top-dock host stretch rule
   above. Fill-on owns the rail; fill-off owns only the packed card width. */
.root[data-quick-toolbar-placement='chat_top_dock'][data-fill-top-dock='0'] {
  flex: 0 0 auto;
  width: max-content;
  max-width: 100%;
}

.root[data-quick-toolbar-placement='chat_top_dock'][data-fill-top-dock='0'] > .toolbar {
  width: max-content;
  max-width: 100%;
  justify-content: flex-start;
}

.toolbar {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  gap: calc(var(--quick-toolbar-gap, 6px) * var(--quick-toolbar-scale, 1));
  padding: calc(var(--quick-toolbar-padding-block, 4px) * var(--quick-toolbar-scale, 1)) calc(var(--quick-toolbar-padding-inline, 10px) * var(--quick-toolbar-scale, 1));
  border: 1px solid var(--lumiverse-border, rgba(148, 163, 184, 0.28));
  border-radius: 13px;
  /* One rung BELOW `.card`, which stays on `--lumiverse-surface-raised`. The two
     used to name the same token, so a card was literally the same colour as the
     container it sat in and its edges vanished. */
  background: color-mix(in srgb, var(--lumiverse-surface) 88%, transparent);
  box-shadow:
    0 16px 38px rgba(0, 0, 0, 0.34),
    inset 0 1px 0 rgba(255, 255, 255, 0.05);
  backdrop-filter: blur(18px) var(--lcs-liquid-filter, );
  opacity: var(--quick-toolbar-opacity, 1);
  transform-origin: center;
  /* `hidden`, never `auto`: `overflow-x: auto` with the other axis `visible`
     computes to `auto` on *both* axes, which is where the stray scrollbars came
     from. The buttons absorb slack instead — see `.item`'s `flex: 1 1 auto`. */
  overflow: hidden;
}

/* Hug the icon row by default. Stretch height only when TSX paints a pinned
   `--quick-toolbar-nav-height: 100%` after the user grew N/S chrome. */
.rootFree .toolbar {
  width: 100%;
  height: var(--quick-toolbar-nav-height, auto);
  align-items: center;
}

/* One synchronous frame-less read of the nav's *natural* extent. The component
   sets `data-measuring`, calls `getBoundingClientRect()` (which flushes layout)
   and removes the attribute again, so this never paints. */
.rootFree[data-measuring='true'] .toolbar {
  width: max-content;
  height: max-content;
  flex: 0 0 auto;
  align-self: flex-start;
}

.toolbarHorizontal {
  flex-direction: row;
}

.toolbarVertical {
  flex-direction: column;
}

/* Promoted from the removed V3 variant — the one rule of the four worth
   keeping. Framing the toolbar on hover is what makes the handles discoverable. */
.rootFree:hover .toolbarFree,
.rootFree:focus-within .toolbarFree {
  border-color: color-mix(in srgb, var(--lumiverse-primary, #6366f1) 65%, transparent);
  box-shadow:
    0 16px 38px rgba(0, 0, 0, 0.34),
    0 0 0 1px color-mix(in srgb, var(--lumiverse-primary, #6366f1) 45%, transparent),
    inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

.rootFree:hover .resizeHandle::after,
.rootFree:focus-within .resizeHandle::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 7px;
  height: 7px;
  transform: translate(-50%, -50%);
  border-radius: 999px;
  background: var(--lumiverse-primary, #6366f1);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--lumiverse-bg, #0b0d12) 72%, transparent);
}

.toolbarFree.toolbarVertical {
  align-items: stretch;
}

/*
 * Anchored (V2 top-dock): the nav is a bare rail, NOT a surface.
 *
 * Every control in the dock row is its own free-standing bordered box — each
 * `.card`, the trailing `.cardStripSettings` gear, and ChatView's two
 * `.topDockActions` buttons. A bordered, padded container around only *some* of
 * them is what made the row read as "a group plus two strays": the container's
 * own inline padding was added to the row gap, so the gear sat further from the
 * first dock button than the cards sit from each other. No border, no
 * background, no shadow and — critically — no padding here means one rhythm
 * across the whole row and a row that is genuinely centred, because there is no
 * invisible padding on one end to offset it.
 *
 * `.toolbarFree` deliberately KEEPS all of that: a floating toolbar has to stay
 * legible over arbitrary chat content, so its border/background/shadow are
 * load-bearing there.
 *
 * The gap is deliberately not restated: this class is only ever applied together
 * with `.cardStrip`, which owns the row's single 6px gap.
 */
.toolbarAnchored {
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  backdrop-filter: none;
  transform: none;
}

.toolbarAnchored .item {
  /* V2's customize button is chrome beside the cards, not a slack-absorbing
     toolbar button, so it keeps its intrinsic size. Everything else it used to
     set here — the 30x26 box, the padding, the 5px radius — moved to
     `.cardStripSettings`, where it can track the icon-size slider. */
  flex: 0 0 auto;
}

/* ── V2 settings-adjacent: context cards from the confirmed design ── */
.cardStrip {
  /* The dock row's ONE gap. `ChatView.module.css` restates the same 6px on
     `.chatToolbar[data-dock-mode='strip']` and on `.topDockActions`, so cards,
     the gear and the two dock buttons are all exactly 6px apart. Nothing in this
     row may add padding or margin on top of it. */
  gap: var(--quick-toolbar-gap, 6px);
  width: auto;
  flex: 0 0 auto;
  min-width: 0;
  max-width: 100%;
  /* The content-width cap, mirroring `LoreIndicator.module.css`'s `.strip`.
     Written as the logical property so the `max-width: 100%` above survives
     verbatim; both resolve to the same computed property and the later
     declaration wins. */
  max-inline-size: 100%;
  justify-content: center;
  /* No `padding-inline`. It used to reserve room for the unconditional mask
     ramp below, at the cost of 12px of dead space between the gear and the first
     dock button — and 12px of it on the leading edge only, which pushed the
     visible row 6px off the centre it claims to hold. The ramp is conditional
     now, so nothing needs reserving. */
  flex-wrap: nowrap;
  position: relative;
  overflow: hidden;
  /* Unmasked while everything fits — an always-on ramp faded the leading card
     and the trailing gear even when there was nothing to scroll to, and clipped
     their focus rings. `QuickToolbar` publishes `data-overflow` below. */
}

.cardScroller {
  display: flex;
  min-width: 0;
  width: auto;
  max-width: 100%;
  flex: 1 1 auto;
  gap: var(--quick-toolbar-gap, 6px);
  overflow: hidden;
  scrollbar-width: none;
}

/* Fill-on owns only the rail; cards and slots retain intrinsic widths so
   heterogeneous content remains visibly heterogeneous. */

/* The strip owns the available dock rail. The scroller may clip only inside
   that rail; overflow and customize stay fixed trailing siblings. */
.root[data-quick-toolbar-placement='chat_top_dock'][data-fill-top-dock='1'] .cardStrip {
  width: 100%;
  min-width: 0;
  flex: 1 1 auto;
  justify-content: flex-start;
}

.root[data-quick-toolbar-placement='chat_top_dock'][data-fill-top-dock='1'] .cardScroller {
  flex: 1 1 auto;
  min-width: 0;
  width: auto;
}

/* In fill modes (Option A & B), card slots and buttons expand proportionally to consume the rail */
.root[data-fill-screen='1'] .cardSlot,
.root[data-fill-top-dock='1'] .cardSlot {
  width: 100% !important;
  min-width: 0 !important;
  max-width: 100% !important;
  flex: 1 1 0px !important;
  display: flex !important;
  align-items: center !important;
  gap: 6px !important;
  box-sizing: border-box !important;
  overflow: visible !important;
  padding: 0 !important;
  margin: 0 !important;
}

.root[data-fill-screen='1'] .cardSlot .card,
.root[data-fill-top-dock='1'] .cardSlot .card {
  width: var(--quick-toolbar-card-width, 100%) !important;
  max-width: var(--quick-toolbar-card-max-width, none) !important;
  flex: 1 1 auto !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  min-width: var(--quick-toolbar-card-min-width, 0) !important;
  padding: 2px var(--quick-toolbar-card-padding-inline, 6px) !important;
  gap: var(--quick-toolbar-card-gap, 4px) !important;
  box-sizing: border-box !important;
  white-space: nowrap !important;
  text-overflow: ellipsis !important;
  text-align: center !important;
}

.cardScroller:empty {
  display: none;
}

.cardSlot {
  display: inline-flex;
  flex: 0 0 auto;
  width: max-content;
  min-width: 0;
  transition: transform 160ms ease;
}

/* Keep the slot in flow so neighbors slide; lift lives on the card transform. */
.cardSlot[data-dragging],
.cardSlot:has([data-dragging]) {
  position: relative;
  z-index: 8;
}

.measureRail {
  position: absolute;
  top: 0;
  left: 0;
  display: flex;
  width: max-content;
  height: 0;
  overflow: visible;
  visibility: hidden;
  pointer-events: none;
}

.measureRail > span {
  display: inline-flex;
  flex: 0 0 auto;
  margin-right: var(--quick-toolbar-gap, 6px);
}

/* Pending only reports that a fresh measurement is in flight. The previously
   accepted fit stays painted until that measurement can replace it. */

/*
 * Honest overflow, the `GroupChatMemberBar` way: a side only fades when content
 * is actually hidden on that side. `data-overflow` is written by `QuickToolbar`
 * from `scrollLeft` / `clientWidth` / `scrollWidth` — all layout px, so the
 * `body > * { zoom }` layer cancels out of the comparison.
 */
.card {
  display: inline-flex;
  /* Don't grow, DON'T SHRINK, basis auto.
     The shrink flag is the whole fix. With more cards than the row can hold,
     `flex-shrink: 1` distributes the *deficit* proportionally, so every card
     lands at nearly the same width and the strip reads as an undifferentiated
     rank — the reported "all the icons look the same". Cards now keep the width
     their content asks for and the strip scrolls instead, which is what the
     `mask-image` above has always been there to announce. */
  flex: 0 0 auto;
  width: var(--quick-toolbar-card-width, max-content);
  align-items: center;
  gap: var(--quick-toolbar-card-gap, 8px);
  min-width: var(--quick-toolbar-card-min-width, calc(var(--quick-toolbar-icon-size, 28px) + 24px));
  max-width: var(--quick-toolbar-card-max-width, 190px);
  min-height: calc(var(--quick-toolbar-icon-size, 28px) + 20px);
  padding: 5px var(--quick-toolbar-card-padding-inline, 9px) 5px var(--quick-toolbar-card-padding-inline, 6px);
  border: 1px solid var(--lumiverse-border-hover);
  /* Never a literal: `theme/engine.ts` recomputes every radius token from the
     user's radius-scale, so the old `11px` silently opted out of that setting
     (and matched nothing else in the app). */
  border-radius: var(--lumiverse-radius-md);
  /* One rung ABOVE `.toolbar`. Both used to read `--lumiverse-surface-raised`. */
  background: color-mix(in srgb, var(--lumiverse-surface-raised) 92%, transparent);
  color: var(--lumiverse-text-muted);
  cursor: pointer;
  text-align: left;
  transition:
    background var(--lumiverse-transition-fast, 120ms),
    border-color var(--lumiverse-transition-fast, 120ms),
    color var(--lumiverse-transition-fast, 120ms),
    transform 160ms ease,
    box-shadow 160ms ease;
}

/*
 * Three real states, where there used to be one four-selector rule that made
 * hovered, keyboard-focused and *open* pixel-identical — and suppressed the
 * app's global focus ring on top.
 */
.card:hover {
  border-color: var(--lumiverse-border-hover);
  background: var(--lumiverse-fill-hover);
  color: var(--lumiverse-text);
}

/* Open: the app's canonical selected-chip recipe, shared with
   `.toolbarBtnActive` in the same dock row and `GroupChatMemberBar`'s items. */
.cardActive,
.card[aria-pressed="true"] {
  border-color: var(--lumiverse-primary-050);
  background: var(--lumiverse-primary-015);
  color: var(--lumiverse-text);
}

/* Keyboard focus lets the global ring through instead of repainting the border,
   so focus is never mistaken for "this surface is open". */
.card:focus-visible {
  outline: 1.5px solid var(--lumiverse-primary-050);
  outline-offset: 2px;
}

.cardIcon {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  width: calc(var(--quick-toolbar-icon-size, 28px) + 8px);
  height: calc(var(--quick-toolbar-icon-size, 28px) + 8px);
  border: 1px solid var(--lumiverse-border);
  border-radius: var(--lumiverse-radius);
  background: color-mix(in srgb, var(--lumiverse-primary) 14%, transparent);
  color: var(--lumiverse-primary-text, var(--lumiverse-primary));
}

.cardIconOnly {
  min-width: 0;
  max-width: none;
  padding: 3px;
  gap: 0;
}

.cardStrip .card {
  min-width: var(--quick-toolbar-card-min-width, 0);
  width: var(--quick-toolbar-card-width, max-content);
  max-width: var(--quick-toolbar-card-max-width, 190px);
  /* V2 owns a compact rail at the 16px minimum, but the setting's full
     16-36px range must remain real. Growing the pill with its glyph prevents
     a larger SVG from bleeding outside the card or clipping against the dock. */
  min-height: max(32px, calc(var(--quick-toolbar-icon-size, 16px) + 12px));
  height: max(32px, calc(var(--quick-toolbar-icon-size, 16px) + 12px));
  padding: 3px var(--quick-toolbar-card-padding-inline, 8px);
  gap: var(--quick-toolbar-card-gap, 6px);
  border-radius: 8px;
}

.cardStrip .cardIcon {
  width: var(--quick-toolbar-icon-size, 16px);
  height: var(--quick-toolbar-icon-size, 16px);
  border-color: transparent;
  border-radius: 5px;
}

/* Lucide's `size` prop writes presentation attributes. Explicit dimensions on
   the SVG keep that intrinsic size from escaping a card when the V2 slider is
   changed after mount. */
.cardStrip .cardIcon > svg {
  display: block;
  width: 100%;
  height: 100%;
  max-width: 100%;
  max-height: 100%;
}

.cardStrip .cardCopy {
  flex-direction: row;
  align-items: baseline;
  gap: 4px;
}

.cardStrip .cardTitle,
.cardStrip .cardValue {
  max-width: 118px;
  font-size: var(--quick-toolbar-label-size, 11px);
  line-height: 1.1;
}

.cardPortrait {
  width: 100%;
  height: 100%;
  border-radius: inherit;
  object-fit: cover;
}

/* The avatar is the Profile action's primary identifier. It receives the
   maximum useful space inside the 32px pill while the text stays compact. */
.cardStrip .cardProfile {
  gap: 4px;
  padding: 1px 5px 1px 2px;
}

.cardStrip .cardIconPortrait {
  width: max(28px, var(--quick-toolbar-icon-size, 16px));
  height: max(28px, var(--quick-toolbar-icon-size, 16px));
  border: 0;
  border-radius: 6px;
}

.cardStrip .cardCopyProfile {
  gap: 0;
}

.cardStrip .cardCopyProfile .cardTitle,
.cardStrip .cardCopyProfile .cardValue {
  max-width: 64px;
  font-size: max(9px, calc(var(--quick-toolbar-label-size, 11px) - 1px));
}

.cardCopy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 1px;
}

.cardTitle {
  overflow: hidden;
  color: var(--lumiverse-text, #f8fafc);
  font-size: var(--quick-toolbar-label-size, 11px);
  font-weight: 600;
  line-height: 1.25;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cardValue {
  overflow: hidden;
  /* With "Show labels" off this is the card's *only* copy, so the dim rung was
     the wrong one: 0.4 alpha multiplied by the user's opacity setting is what
     the low-contrast report was actually describing. */
  color: var(--lumiverse-text-muted);
  font-size: calc(var(--quick-toolbar-label-size, 11px) - 0.5px);
  line-height: 1.25;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cardChevron {
  flex: 0 0 auto;
  color: var(--lumiverse-text-dim, rgba(226, 232, 240, 0.5));
  transition: transform var(--lumiverse-transition-fast, 120ms);
}

/* The chevron points up while the card's surface is open, so the "press it
   again to close" behaviour is visible rather than a hidden trick. */
.cardChevronOpen {
  transform: rotate(180deg);
}

/*
 * ── Density (V2 only) ───────────────────────────────────────────────────────
 * `comfortable` is the confirmed two-line card and needs no override; `compact`
 * folds the copy onto one line and tightens the box. Every rule keys off the
 * element that carries `.cardStrip`, sits at column 0 and is un-nested, because
 * the test helpers parse this sheet with a flat `^selector\s*\{([^}]*)\}`.
 */
.cardStrip[data-density='compact'] .card {
  gap: var(--quick-toolbar-card-gap, 6px);
  width: var(--quick-toolbar-card-width, max-content);
  max-width: var(--quick-toolbar-card-max-width, 170px);
  min-height: max(32px, calc(var(--quick-toolbar-icon-size, 16px) + 12px));
  height: max(32px, calc(var(--quick-toolbar-icon-size, 16px) + 12px));
  padding: 3px var(--quick-toolbar-card-padding-inline, 8px);
}

.cardStrip[data-density='compact'] .cardIcon {
  border-color: transparent;
  border-radius: 5px;
}

/* Title and value share one line; the title keeps its weight so the two are
   still told apart, and both keep ellipsing. */
.cardStrip[data-density='compact'] .cardCopy {
  flex-direction: row;
  align-items: baseline;
  gap: 5px;
}

.cardStrip[data-density='compact'] .cardTitle,
.cardStrip[data-density='compact'] .cardValue {
  min-width: 0;
}

.cardStrip[data-density='compact'] .cardStripSettings {
  padding: 0;
}

.cardStrip[data-density='compact'] .cardProfile {
  gap: 4px;
  padding: 1px 5px 1px 2px;
}

.cardStrip[data-density='compact'] .cardIconPortrait {
  border: 0;
  border-radius: 6px;
}

/*
 * `z-index: 4` — above `.resizeHandle`'s 3. `.resize_n` used to sit at
 * `top: -4px; height: 8px` with a higher z-index and stole the grip's lower
 * ~7px in both orientations.
 */
.dragHandle {
  position: absolute;
  left: 50%;
  top: -15px;
  z-index: 4;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: calc(32px * var(--quick-toolbar-scale, 1));
  height: calc(18px * var(--quick-toolbar-scale, 1));
  padding: 0;
  transform: translateX(-50%);
  border: 1px solid var(--lumiverse-border, rgba(148, 163, 184, 0.28));
  border-radius: 7px;
  background: var(--lumiverse-surface-raised, #20242c);
  color: var(--lumiverse-text-muted, rgba(226, 232, 240, 0.76));
  cursor: grab;
  touch-action: none;
}

/*
 * QT-3: a vertical toolbar puts the grip on its left edge instead of leaving it
 * on top, where — whatever the mechanism — it ends up over a button. Outside the
 * box on the cross axis, so it can never cover one.
 */
.dragHandleVertical {
  left: -15px;
  top: 50%;
  width: calc(18px * var(--quick-toolbar-scale, 1));
  height: calc(32px * var(--quick-toolbar-scale, 1));
  transform: translateY(-50%);
}

.dragHandle:active {
  cursor: grabbing;
}

.item {
  /* Shrink-to-content: no artificial min box and no slack-absorbing grow. */
  flex: 0 0 auto;
  min-width: 0;
  min-height: 0;
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  padding: 2px 6px;
  border: 1px solid transparent;
  border-radius: 9px;
  background: transparent;
  color: var(--lumiverse-text-muted, rgba(226, 232, 240, 0.76));
  cursor: pointer;
  font-size: var(--quick-toolbar-label-size, 11px);
  transition:
    background var(--lumiverse-transition-fast, 120ms),
    border-color var(--lumiverse-transition-fast, 120ms),
    color var(--lumiverse-transition-fast, 120ms),
    transform var(--lumiverse-transition-fast, 120ms);
}

.itemLabel {
  max-width: 88px;
  overflow: hidden;
  line-height: 1.1;
  text-align: center;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.item:hover,
.item:focus-visible,
.itemActive {
  background: var(--lumiverse-surface-hover, rgba(148, 163, 184, 0.14));
  border-color: var(--lumiverse-border-subtle, rgba(148, 163, 184, 0.18));
  color: var(--lumiverse-text, #f8fafc);
  outline: none;
  transform: translateY(-1px);
}

.toolbarVertical .item:hover,
.toolbarVertical .item:focus-visible {
  transform: translateX(1px);
}

[data-toolbar-item-drag-handle] {
  cursor: grab;
}

[data-toolbar-item-drag-handle]:active:not([data-dragging]) {
  transform: scale(0.97);
}

.card[data-dragging],
.item[data-dragging],
.item[data-dragging]:hover,
.item[data-dragging]:focus-visible,
.toolbarVertical .item[data-dragging],
.toolbarVertical .item[data-dragging]:hover,
.toolbarVertical .item[data-dragging]:focus-visible,
.cardSlot[data-dragging] .card,
.root[data-dragging-action] [data-dragging] {
  z-index: 100;
  cursor: grabbing;
  transform: scale(1.05) translateY(-2px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  outline: 2px solid var(--lumiverse-primary);
  transition: transform 160ms ease, box-shadow 160ms ease;
}

.root[data-dragging-action],
.root[data-dragging-action] * {
  cursor: grabbing;
}

button[aria-label='Customize toolbar'],
.cardStripSettings {
  cursor: pointer !important;
}

/*
 * The trailing gear, promoted to a card-height bordered sibling as the confirmed
 * design shows. It used to be a 26px transparent glyph with a 5px radius next to
 * ~48px bordered cards, wired to a different sizing system entirely — so it did
 * not track the icon-size slider the way every card does.
 *
 * Placed AFTER every `.item` rule on purpose: it shares `.item`'s specificity
 * (0,1,0), so source order is the only thing that lets it win.
 */
.cardStripSettings {
  box-sizing: border-box;
  flex: 0 0 auto;
  width: max(36px, calc(var(--quick-toolbar-icon-size, 16px) + 8px));
  min-width: max(36px, calc(var(--quick-toolbar-icon-size, 16px) + 8px));
  /* Height includes the 1px border. Same formula as `.cardStrip .card`. */
  height: max(32px, calc(var(--quick-toolbar-icon-size, 16px) + 12px));
  min-height: max(32px, calc(var(--quick-toolbar-icon-size, 16px) + 12px));
  padding: 0;
  /* No `margin-inline-start`. The 2px it used to add made the card→gear gap 8px
     against 6px everywhere else in the row; the gear is a sibling of the cards,
     not a separate cluster, so it takes the row's gap and nothing more. */
  border-color: var(--lumiverse-border-hover);
  border-radius: var(--lumiverse-radius-md);
  color: var(--lumiverse-text-muted);
  /* Strip / toolbar stay `overflow: hidden`; chrome must not clip its own glyph. */
  overflow: visible;
}

.overflowButton {
  box-sizing: border-box;
  width: auto;
  min-width: 0;
  flex-direction: row;
  align-items: center;
  gap: 4px;
  padding: 0 8px;
  font-size: 11px;
  overflow: visible;
}

/* Same clamp as `.cardStrip .cardIcon > svg`. Lucide `size` is presentational. */
.cardStripSettings > svg {
  display: block;
  width: var(--quick-toolbar-icon-size, 16px);
  height: var(--quick-toolbar-icon-size, 16px);
  max-width: 100%;
  max-height: 100%;
  flex: 0 0 auto;
}

.overflowButton > span {
  flex: 0 0 auto;
  line-height: 1;
}

.overflowPopover {
  position: fixed;
  z-index: var(--z-quick-toolbar-popover, 10014);
  display: flex;
  flex-direction: column;
  min-width: 0;
  max-width: calc(100vw - 20px);
  min-height: 0;
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  background: color-mix(in srgb, var(--lumiverse-surface-raised) 96%, transparent);
  box-shadow: 0 22px 52px rgba(0, 0, 0, 0.42);
