.resize_ne { top: 0; right: 0; cursor: nesw-resize; }
.resize_nw { top: 0; left: 0; cursor: nwse-resize; }
.resize_se { bottom: 0; right: 0; cursor: nwse-resize; }
.resize_sw { bottom: 0; left: 0; cursor: nesw-resize; }

/*
