  background: color-mix(in srgb, var(--lumiverse-surface-raised) 94%, transparent);
  color: var(--lumiverse-text-muted);
  cursor: pointer;
  opacity: 0.72;
  transition: opacity var(--lumiverse-transition-fast, 120ms);
