.container {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.headerRow {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.heading {
  font-size: calc(15px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
}

.headerActions {
  display: flex;
  gap: 6px;
}

.actionBtn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  border-radius: 6px;
  border: 1px solid var(--lumiverse-border);
  background: transparent;
  color: var(--lumiverse-text-dim);
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
}

.actionBtn:hover {
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text);
}

.actionBtn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.copyBtn {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  border-radius: 6px;
  border: 1px solid var(--lumiverse-border);
  background: transparent;
  color: var(--lumiverse-text-muted);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
}

.copyBtn:hover {
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text);
}

.copyBtnDone {
  border-color: rgba(76, 175, 80, 0.4);
  color: #4caf50;
}

/* Section */

.section {
  border: 1px solid var(--lumiverse-border);
  border-radius: 10px;
  overflow: hidden;
}

.sectionHeader {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
  background: var(--lumiverse-fill-subtle);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
}

/* Grid of info rows */

.grid {
  display: flex;
  flex-direction: column;
}

.infoRow {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 14px;
  border-top: 1px solid var(--lumiverse-border);
}

.infoLabel {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  color: var(--lumiverse-text-muted);
}

.infoValue {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text);
  text-align: right;
  max-width: 60%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Feature tags */

.featureRow {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 10px 14px;
  border-top: 1px solid var(--lumiverse-border);
}

.featureLabel {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  color: var(--lumiverse-text-muted);
}

.featureTags {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

.featureTag {
  padding: 2px 8px;
  border-radius: 4px;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
}

.featureOk {
  background: rgba(76, 175, 80, 0.1);
  color: #4caf50;
  border: 1px solid rgba(76, 175, 80, 0.25);
}

.featureMissing {
  background: rgba(255, 152, 0, 0.1);
  color: #ff9800;
  border: 1px solid rgba(255, 152, 0, 0.25);
}

/* Extensions list */

.extList {
  display: flex;
  flex-direction: column;
}

.extRow {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  border-top: 1px solid var(--lumiverse-border);
}

.extName {
  flex: 1;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  color: var(--lumiverse-text);
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.extVersion {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  flex-shrink: 0;
}

.extStatus {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 4px;
  flex-shrink: 0;
}

.extEnabled {
  background: rgba(76, 175, 80, 0.1);
  color: #4caf50;
  border: 1px solid rgba(76, 175, 80, 0.25);
}

.extDisabled {
  background: rgba(128, 128, 128, 0.1);
  color: var(--lumiverse-text-dim);
  border: 1px solid rgba(128, 128, 128, 0.2);
}

/* Maintenance action rows */

.maintenanceRow {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 14px;
  border-top: 1px solid var(--lumiverse-border);
}

.maintenanceDesc {
  flex: 1;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
  line-height: 1.4;
  min-width: 0;
}

.maintenanceResult {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: #4caf50;
  white-space: nowrap;
  flex-shrink: 0;
}

/* Loading / Error / Empty */

.loadingRow {
  padding: 16px 14px;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  border-top: 1px solid var(--lumiverse-border);
}

.errorRow {
  padding: 10px 14px;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: #ff6b6b;
  border-top: 1px solid var(--lumiverse-border);
  background: rgba(255, 107, 107, 0.06);
}

.emptyRow {
  padding: 16px 14px;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  border-top: 1px solid var(--lumiverse-border);
}

