.container {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

/* ── Section cards (matches Diagnostics pattern) ─────────────────── */

.section {
  border: 1px solid var(--lumiverse-border);
  border-radius: 10px;
  overflow: hidden;
}

.sectionHeader {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
  background: var(--lumiverse-fill-subtle);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
}

.sectionHeaderActions {
  margin-left: auto;
  display: flex;
  gap: 6px;
}

/* ── Info rows inside sections ───────────────────────────────────── */

.grid {
  display: flex;
  flex-direction: column;
}

.infoRow {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 14px;
  border-top: 1px solid var(--lumiverse-border);
}

.infoLabel {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  color: var(--lumiverse-text-muted);
}

.infoValue {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text);
  display: flex;
  align-items: center;
  gap: 6px;
}

/* ── Status badge (green dot / dim dot) ──────────────────────────── */

.statusDot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
}

.statusActive {
  background: #4caf50;
  box-shadow: 0 0 6px rgba(76, 175, 80, 0.4);
}

.statusInactive {
  background: var(--lumiverse-text-dim);
  opacity: 0.4;
}

/* ── Toggle rows inside sections ─────────────────────────────────── */

.toggleRow {
  padding: 9px 14px;
  border-top: 1px solid var(--lumiverse-border);
  transition: background var(--lumiverse-transition-fast);
}

.toggleRow:hover {
  background: var(--lumiverse-fill-subtle);
