.container {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

/* ── Status Section ──────────────────────────────────────────────────────── */

.statusGrid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 10px;
}

.statusCard {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 10px 12px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  background: var(--lumiverse-fill-subtle);
}

.statusLabel {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  color: var(--lumiverse-text-dim);
  text-transform: uppercase;
  letter-spacing: 0.3px;
}

.statusValue {
  font-size: calc(14px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
  font-variant-numeric: tabular-nums;
}

.updateBadge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border-radius: 10px;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  background: rgba(255, 183, 77, 0.15);
  color: #ffb74d;
  text-decoration: none;
  cursor: pointer;
}

.updateBadge:hover {
  background: rgba(255, 183, 77, 0.24);
}

.updateBadge:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 2px;
}

.ipcBadge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border-radius: 10px;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
}

.ipcAvailable {
  background: rgba(76, 175, 80, 0.12);
  color: #66bb6a;
}

.ipcUnavailable {
  background: rgba(255, 152, 0, 0.12);
  color: #ffa726;
}

/* ── Section ─────────────────────────────────────────────────────────────── */

.section {
  border: 1px solid var(--lumiverse-border);
  border-radius: 10px;
  overflow: hidden;
}

.sectionHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  background: var(--lumiverse-fill-subtle);
  border-bottom: 1px solid var(--lumiverse-border);
}

.sectionTitle {
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
}

.sectionBody {
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.dbInfoGrid {
  display: grid;
  gap: 10px;
}

.dbInfoBlock {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.dbMono {
  font-family: 'JetBrains Mono', 'SF Mono', 'Fira Code', 'Cascadia Code', monospace;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
  word-break: break-all;
}

.dbInlineText {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
}

.tuningGrid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 12px;
}

.thumbnailQueue {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 12px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  background: var(--lumiverse-fill-subtle);
}

.thumbnailQueueHeader {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
}

.thumbnailQueueTitle {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  color: var(--lumiverse-text-dim);
  text-transform: uppercase;
  letter-spacing: 0.3px;
}

.thumbnailQueueCounts {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--lumiverse-text);
}

.thumbnailQueueTrack {
  height: 6px;
  overflow: hidden;
  border-radius: 999px;
  background: var(--lumiverse-border);
}

.thumbnailQueueFill {
  height: 100%;
  width: 0;
  border-radius: inherit;
  background: #64b5f6;
  transition: width 0.2s ease;
}

.thumbnailQueueFillActive {
  background-image: linear-gradient(
    90deg,
    #64b5f6 0%,
    #90caf9 50%,
    #64b5f6 100%
  );
  background-size: 200% 100%;
  animation: thumbnailQueueSweep 1.4s linear infinite;
}

.thumbnailQueueHint {
  margin: 0;
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
  line-height: 1.4;
  color: var(--lumiverse-text-dim);
}

@keyframes thumbnailQueueSweep {
  from { background-position: 100% 0; }
  to { background-position: -100% 0; }
}


.fieldGroup {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.fieldLabel {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
}

.fieldInput {
  width: 100%;
  padding: 8px 10px;
  border-radius: 6px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
}

.fieldInput:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.fieldHint {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  line-height: 1.45;
}

.toggleRow {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.toggleGrid {
  display: grid;
  gap: 10px;
}

.toggleRowCompact {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 12px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  background: var(--lumiverse-fill-subtle);
}

/* ── Controls ────────────────────────────────────────────────────────────── */

.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.controlBtn {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 7px 14px;
  border-radius: 6px;
  border: 1px solid var(--lumiverse-border);
  background: transparent;
  color: var(--lumiverse-text-muted);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
}

.controlBtn:hover:not(:disabled) {
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text);
}

.controlBtn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.controlBtnDanger {
  composes: controlBtn;
  border-color: rgba(239, 83, 80, 0.3);
  color: #ef5350;
}

.controlBtnDanger:hover:not(:disabled) {
  background: rgba(239, 83, 80, 0.08);
  color: #ef5350;
}

.controlBtnPrimary {
  composes: controlBtn;
  border-color: rgba(100, 181, 246, 0.3);
  color: #64b5f6;
}

.controlBtnPrimary:hover:not(:disabled) {
  background: rgba(100, 181, 246, 0.08);
  color: #64b5f6;
}

/* ── Remote Mode ─────────────────────────────────────────────────────────── */

.remoteRow {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.remoteInfo {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.remoteLabel {
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  color: var(--lumiverse-text);
}

.remoteHint {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
}

/* ── Log Viewer ──────────────────────────────────────────────────────────── */

.logContainer {
  position: relative;
  border: 1px solid var(--lumiverse-border);
  border-radius: 6px;
  background: var(--lumiverse-bg-deeper, #0d0d0d);
  overflow: hidden;
}

.logScroll {
  max-height: 350px;
  overflow-y: auto;
  padding: 8px 10px;
  font-family: 'JetBrains Mono', 'SF Mono', 'Fira Code', 'Cascadia Code', monospace;
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
  line-height: 1.55;
}

.logEntry {
  white-space: pre-wrap;
  word-break: break-all;
}

.logTimestamp {
  color: var(--lumiverse-text-dim);
  margin-right: 6px;
  opacity: 0.6;
}

.logStdout {
  color: var(--lumiverse-text-muted);
}

.logStderr {
  color: #ef5350;
}

.logEmpty {
  padding: 24px;
  text-align: center;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
}

.logControls {
  display: flex;
  align-items: center;
  gap: 8px;
}

.logBufferControl {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
}

.logBufferInput {
  width: 60px;
  padding: 3px 6px;
  border-radius: 4px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  text-align: center;
}

.logClearBtn {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 4px 10px;
  border-radius: 4px;
  border: 1px solid var(--lumiverse-border);
  background: transparent;
  color: var(--lumiverse-text-dim);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
}

.logClearBtn:hover {
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text);
}

/* ── Busy State ──────────────────────────────────────────────────────────── */

.busyOverlay {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
  border-radius: 8px;
  background: rgba(100, 181, 246, 0.08);
  border: 1px solid rgba(100, 181, 246, 0.2);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  color: #64b5f6;
}

.warningBanner {
  padding: 10px 12px;
  border-radius: 8px;
  border: 1px solid rgba(255, 183, 77, 0.28);
  background: rgba(255, 183, 77, 0.08);
  color: #ffb74d;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  line-height: 1.5;
}

.disabledHint {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  font-style: italic;
}

/* ── SMART Disk Health ──────────────────────────────────────────────────── */

.smartAvailability {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
}

.smartAvailabilityDot {
  width: 8px;
  height: 8px;
  flex: 0 0 auto;
  border-radius: 50%;
}

.smartDriveList {
  display: grid;
  gap: 10px;
}

.smartDrive {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 12px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  background: var(--lumiverse-fill-subtle);
}

.smartDriveHeader {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.smartDriveName {
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
}

.smartBadge {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  min-height: 22px;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
}

.smartOk {
  background: rgba(76, 175, 80, 0.14);
  color: #66bb6a;
}

.smartWarning {
  background: rgba(255, 183, 77, 0.16);
  color: #ffb74d;
}

.smartFailing {
  background: rgba(239, 83, 80, 0.16);
  color: #ef5350;
}

.smartUnavailable {
  background: rgba(158, 158, 158, 0.14);
  color: var(--lumiverse-text-dim);
}

.smartAvailabilityDot.smartOk,
.smartAvailabilityDot.smartUnavailable {
  padding: 0;
}

.smartMetrics {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: 8px;
}

.smartMetric {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.smartMetric > span {
  font-size: calc(10.5px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  text-transform: uppercase;
  letter-spacing: 0.2px;
}

.smartMetric > strong {
  overflow: hidden;
  color: var(--lumiverse-text);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-variant-numeric: tabular-nums;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ── Reconnect / Shutdown Banners ────────────────────────────────────────── */

.reconnectBanner {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
  border-radius: 8px;
  background: rgba(255, 183, 77, 0.08);
  border: 1px solid rgba(255, 183, 77, 0.25);
  color: #ffb74d;
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  animation: reconnectPulse 2s ease-in-out infinite;
}

@keyframes reconnectPulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.7; }
}

.shutdownBanner {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 18px;
  border-radius: 8px;
  background: rgba(239, 83, 80, 0.08);
  border: 1px solid rgba(239, 83, 80, 0.25);
  color: #ef5350;
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
}

/* ── Trusted Hosts ───────────────────────────────────────────────────────── */

.hostChipGroup {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.hostChip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 4px 3px 10px;
  border-radius: 999px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text);
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
  font-variant-numeric: tabular-nums;
}

.hostChipBaseline {
  composes: hostChip;
  opacity: 0.75;
  padding-right: 10px;
}

.hostChipSuggested {
  composes: hostChip;
  padding: 4px 10px;
  cursor: pointer;
  border-style: dashed;
  color: var(--lumiverse-text-muted);
  transition: all var(--lumiverse-transition-fast);
}

.hostChipSuggested:hover:not(:disabled) {
  background: rgba(100, 181, 246, 0.08);
  border-color: rgba(100, 181, 246, 0.4);
  color: #64b5f6;
}

.hostChipSuggested:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.hostChipSource {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  opacity: 0.6;
  text-transform: uppercase;
  letter-spacing: 0.3px;
}

.hostChipRemove {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  border-radius: 999px;
  border: none;
  background: transparent;
  color: var(--lumiverse-text-dim);
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
}

.hostChipRemove:hover:not(:disabled) {
  background: rgba(239, 83, 80, 0.15);
  color: #ef5350;
}

.hostInputRow {
  display: flex;
  gap: 8px;
  align-items: center;
}

.hostInput {
  flex: 1;
  padding: 8px 10px;
  border-radius: 6px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
}

.hostEmpty {
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  font-style: italic;
}

