.policyHint {
  margin: 0;
  color: var(--lumiverse-text-muted);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  overflow-wrap: anywhere;
}

.error {
  padding: 8px;
  border-radius: 4px;
  background: var(--lumiverse-error-010);
  color: var(--lumiverse-error);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  overflow-wrap: anywhere;
}

.kvList {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.kvRow {
  display: flex;
  gap: 6px;
  align-items: center;
}

.kvRow > input {
  flex: 1;
  min-width: 0;
}

.kvRemove {
  flex-shrink: 0;
  width: 24px;
  height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: none;
  background: transparent;
