import { useState } from 'react'
import { useTranslation } from 'react-i18next'

import {
  Plug, PlugZap, Unplug, RefreshCw, Trash2, Pencil,
  ChevronDown, ChevronRight, TestTube, Terminal, Globe, Radio,
} from 'lucide-react'
import type { McpServerProfile, McpServerStatus, McpServerTestResult, CreateMcpServerInput } from '@/api/mcp-servers'
import McpServerForm from './McpServerForm'
import styles from './McpServerItem.module.css'

const TRANSPORT_LABELS: Record<string, { label: string; icon: typeof Globe }> = {
  streamable_http: { label: 'HTTP', icon: Globe },
  sse: { label: 'SSE', icon: Radio },
  stdio: { label: 'Stdio', icon: Terminal },
}

interface McpServerItemProps {
  server: McpServerProfile
  status?: McpServerStatus
  onUpdate: (id: string, input: Partial<CreateMcpServerInput>) => Promise<void>
  onDelete: () => void
  onConnect: () => void
  onDisconnect: () => void
  onTest: () => Promise<McpServerTestResult>
}

export default function McpServerItem({
  server,
  status,
  onUpdate,
  onDelete,
  onConnect,
  onDisconnect,
  onTest,
}: McpServerItemProps) {
  const { t } = useTranslation('settings')
  const { t: tc } = useTranslation('common')
  const [editing, setEditing] = useState(false)
  const [expanded, setExpanded] = useState(false)
  const [testing, setTesting] = useState(false)
  const [testResult, setTestResult] = useState<McpServerTestResult | null>(null)
  const [connecting, setConnecting] = useState(false)

  const isConnected = status?.connected ?? false
  const transport = TRANSPORT_LABELS[server.transport_type] || TRANSPORT_LABELS.streamable_http
  const TransportIcon = transport.icon

  const handleTest = async () => {
    setTesting(true)
    setTestResult(null)
    try {
      const result = await onTest()
      setTestResult(result)
      setTimeout(() => setTestResult(null), 5000)
    } catch {
      setTestResult({ success: false, message: t('mcp.testRequestFailed'), tools: [] })
      setTimeout(() => setTestResult(null), 5000)
    } finally {
      setTesting(false)
    }
  }

  const handleConnect = async () => {
    setConnecting(true)
    try {
      await onConnect()
    } finally {
      setConnecting(false)
    }
  }

  const handleDisconnect = async () => {
    setConnecting(true)
    try {
      await onDisconnect()
    } finally {
      setConnecting(false)
    }
  }

  if (editing) {
    return (
      <McpServerForm
        initial={{
          name: server.name,
          transport_type: server.transport_type,
          url: server.url,
          command: server.command,
          args: server.args,
          is_enabled: server.is_enabled,
          auto_connect: server.auto_connect,
        }}
        onSave={async (input) => {
          await onUpdate(server.id, input)
          setEditing(false)
        }}
        onCancel={() => setEditing(false)}
      />
    )
  }

  const hasTools = (status?.tool_count ?? 0) > 0

  return (
    <div className={styles.item}>
      <div className={styles.header}>
        <div className={styles.info}>
          <div className={styles.statusDot} data-connected={isConnected} data-error={!!server.last_error && !isConnected} />
          <span className={styles.name}>{server.name}</span>
          <span className={styles.badge}>
            <TransportIcon size={10} />
            {transport.label}
          </span>
          {isConnected && hasTools && (
            <span className={styles.toolBadge}>
              {t('mcp.toolCount', { count: status!.tool_count })}
            </span>
          )}
          {!server.is_enabled && (
            <span className={styles.disabledBadge}>{t('mcp.disabled')}</span>
          )}
        </div>

        <div className={styles.actions}>
          {testResult && (
            <span className={styles.testResult} data-success={testResult.success}>
              {testResult.success ? t('mcp.testPass') : t('mcp.testFail')}
            </span>
          )}
          <button
            className={styles.actionBtn}
            onClick={handleTest}
            disabled={testing}
            title={t('mcp.testConnection')}
          >
            <TestTube size={14} />
          </button>
          {isConnected ? (
            <button
              className={styles.actionBtn}
              onClick={handleDisconnect}
              disabled={connecting}
              title={t('mcp.disconnect')}
            >
              <Unplug size={14} />
            </button>
          ) : (
            <button
              className={styles.actionBtn}
              onClick={handleConnect}
              disabled={connecting}
              title={t('mcp.connect')}
            >
              <PlugZap size={14} />
            </button>
          )}
          <button
            className={styles.actionBtn}
            onClick={() => setEditing(true)}
            title={tc('actions.edit')}
          >
            <Pencil size={14} />
          </button>
          <button
            className={styles.actionBtn}
            onClick={onDelete}
            title={tc('actions.delete')}
            data-danger
          >
            <Trash2 size={14} />
          </button>
        </div>
      </div>

      {server.last_error && !isConnected && (
        <div className={styles.error}>{server.last_error}</div>
      )}

      {isConnected && hasTools && (
        <div className={styles.toolsSection}>
          <button
            className={styles.toolsToggle}
            onClick={() => setExpanded(!expanded)}
          >
            {expanded ? <ChevronDown size={12} /> : <ChevronRight size={12} />}
            {t('mcp.discoveredTools')}
          </button>
          {expanded && (
            <div className={styles.toolsList}>
              {status!.tools.map((tool) => (
                <div key={tool.name} className={styles.toolItem}>
                  <span className={styles.toolName}>{tool.name}</span>
                  {tool.description && (
                    <span className={styles.toolDesc}>{tool.description}</span>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  )
}

import { useState, useEffect, useCallback } from 'react'
import { useTranslation } from 'react-i18next'
import { Plus } from 'lucide-react'
import { mcpServersApi } from '@/api/mcp-servers'
import type { McpServerProfile, CreateMcpServerInput } from '@/api/mcp-servers'
import { useStore } from '@/store'
import ConfirmationModal from '@/components/shared/ConfirmationModal'
import McpServerForm from './McpServerForm'
import McpServerItem from './McpServerItem'
import styles from '../../panels/ConnectionManager.module.css'

export default function McpServerSettings() {
  const { t } = useTranslation('settings')
  const { t: tc } = useTranslation('common')
  const servers = useStore((s) => s.mcpServers)
  const setServers = useStore((s) => s.setMcpServers)
  const addServer = useStore((s) => s.addMcpServer)
  const updateServer = useStore((s) => s.updateMcpServer)
  const removeServer = useStore((s) => s.removeMcpServer)
  const statuses = useStore((s) => s.mcpServerStatuses)
  const setStatus = useStore((s) => s.setMcpServerStatus)

  const [loading, setLoading] = useState(false)
  const [creating, setCreating] = useState(false)
  const [deleteTarget, setDeleteTarget] = useState<McpServerProfile | null>(null)

  useEffect(() => {
    let cancelled = false

    async function init() {
      setLoading(true)
      try {
        const [serversResult, statusResult] = await Promise.allSettled([
          mcpServersApi.list({ limit: 100 }),
          mcpServersApi.allStatus(),
        ])

        if (cancelled) return

        if (serversResult.status === 'fulfilled') {
          setServers(serversResult.value.data)
        }

        if (statusResult.status === 'fulfilled') {
          for (const s of statusResult.value.servers) {
            setStatus(s.id, s)
          }
        }
      } catch (err) {
        console.error('[McpServerSettings] Init failed:', err)
      } finally {
        if (!cancelled) setLoading(false)
      }
    }

    init()
    return () => { cancelled = true }
  }, [setServers, setStatus])

  const handleCreate = useCallback(async (input: CreateMcpServerInput) => {
    const server = await mcpServersApi.create(input)
    addServer(server)
    setCreating(false)
  }, [addServer])

  const handleUpdate = useCallback(async (id: string, input: Partial<CreateMcpServerInput>) => {
    const server = await mcpServersApi.update(id, input)
    updateServer(id, server)
  }, [updateServer])

  const confirmDelete = useCallback(async () => {
    if (!deleteTarget) return
    try {
      await mcpServersApi.delete(deleteTarget.id)
      removeServer(deleteTarget.id)
    } catch (err) {
      console.error('[McpServerSettings] Delete failed:', err)
    } finally {
      setDeleteTarget(null)
    }
  }, [deleteTarget, removeServer])

  const handleConnect = useCallback(async (id: string) => {
    try {
      const status = await mcpServersApi.connect(id)
      setStatus(id, status)
    } catch (err) {
      console.error('[McpServerSettings] Connect failed:', err)
    }
  }, [setStatus])

  const handleDisconnect = useCallback(async (id: string) => {
    try {
      await mcpServersApi.disconnect(id)
      setStatus(id, { id, connected: false, tool_count: 0, tools: [] })
    } catch (err) {
      console.error('[McpServerSettings] Disconnect failed:', err)
    }
  }, [setStatus])

  const handleTest = useCallback(async (id: string) => {
    const result = await mcpServersApi.test(id)
    return result
  }, [])

  if (loading) {
    return <div className={styles.loading}>{t('mcp.loading')}</div>
  }

  return (
    <div className={styles.manager}>
      <button
        className={styles.createBtn}
        onClick={() => setCreating(true)}
        disabled={creating}
      >
        <Plus size={14} />
        {t('mcp.addServer')}
      </button>

      {creating && (
        <McpServerForm
          onSave={handleCreate}
          onCancel={() => setCreating(false)}
        />
      )}

      {servers.length === 0 && !creating && (
        <div className={styles.empty}>
          <div>{t('mcp.noServers')}</div>
          <div className={styles.emptyHint}>{t('mcp.noServersHint')}</div>
        </div>
      )}

      <div className={styles.list}>
        {servers.map((server) => (
          <McpServerItem
            key={server.id}
            server={server}
            status={statuses[server.id]}
            onUpdate={handleUpdate}
            onDelete={() => setDeleteTarget(server)}
            onConnect={() => handleConnect(server.id)}
            onDisconnect={() => handleDisconnect(server.id)}
            onTest={() => handleTest(server.id)}
          />
        ))}
      </div>

      {deleteTarget && (
        <ConfirmationModal
          title={t('mcp.deleteTitle')}
          message={t('mcp.deleteMessage', { name: deleteTarget.name })}
          isOpen={true}
          variant="danger"
          confirmText={tc('actions.delete')}
          onConfirm={confirmDelete}
          onCancel={() => setDeleteTarget(null)}
        />
      )}
    </div>
  )
}

