.titlebar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: env(titlebar-area-height, 32px);
  z-index: 90;
  display: none;
  /* The visual bar must not claim the native window controls that sit above
     it. Only the explicit drag region below receives pointer input. */
  pointer-events: none;
  cursor: default;
  /* Keep the chrome quiet: the active scene and app surfaces should carry
     the visual identity, while this reads as one restrained native layer. */
  background: color-mix(in srgb, var(--lumiverse-bg-deep) 86%, transparent);
  border-bottom: 1px solid var(--lumiverse-border);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--lumiverse-text) 4%, transparent);
  backdrop-filter: blur(20px) saturate(1.08) var(--lcs-liquid-filter, );
  -webkit-backdrop-filter: blur(20px) saturate(1.08) var(--lcs-liquid-filter, );
}

/* The Tauri shell is frameless; the frontend supplies its complete title bar. */
:global(html[data-tauri-desktop]) .titlebar {
  display: block;
  height: var(--app-desktop-titlebar-height, 36px);
  border-radius: var(--desktop-window-corner-radius) var(--desktop-window-corner-radius) 0 0;
  overflow: hidden;
  z-index: var(--app-window-chrome-z-index, 12000);
}

:global(html[data-tauri-desktop]) .dragRegion {
  position: absolute;
  /* Keep the native resize target unclaimed. The drag-region handler starts
     a window move on mouse-down, so covering even the top edge would steal
     its 1px resize hit area. */
  /* Let the drag surface fill the rest of the custom titlebar. The controls
     are a higher-z-index sibling, so they remain clickable without creating
     broad dead gutters around the centered title. */
  inset: 1px 1px 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 0;
  color: var(--lumiverse-text-muted);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.02em;
  user-select: none;
  -webkit-user-select: none;
  pointer-events: auto;
  cursor: grab;
}

:global(html[data-tauri-desktop]) .brandMark {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--lumiverse-primary) 72%, var(--lumiverse-text));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--lumiverse-primary) 10%, transparent);
}

:global(html[data-tauri-desktop]) .title {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  opacity: 0.78;
}

.windowControls {
  position: absolute;
  top: 4px;
  right: 8px;
  height: 28px;
  display: flex;
  align-items: stretch;
  gap: 4px;
  pointer-events: auto;
  /* This only orders the controls above the sibling drag region. The
     titlebar itself owns the application-wide chrome layer. */
  z-index: 1;
}

.windowControl {
  width: 28px;
  border: 0;
  border-radius: 6px;
  display: grid;
  place-items: center;
  padding: 0;
  color: var(--lumiverse-text-muted);
  background: transparent;
  cursor: pointer;
  transition: background 120ms ease, color 120ms ease;
}

.windowControl:hover {
  color: color-mix(in srgb, var(--lumiverse-text) 90%, var(--lumiverse-primary));
  background: color-mix(in srgb, var(--lumiverse-text) 7%, transparent);
}

.windowControl:focus-visible {
  outline: 2px solid var(--lumiverse-primary);
  outline-offset: -2px;
}

.closeControl:hover {
  color: color-mix(in srgb, #f7c7c4 84%, var(--lumiverse-text));
  background: color-mix(in srgb, #d95d5d 17%, transparent);
}

@media (display-mode: window-controls-overlay) {
  .titlebar {
    display: block;
    height: var(--app-window-controls-overlay-top, 32px);
  }

  /* Browser PWAs keep their host-provided window-control buttons. */
  .windowControls {
    display: none;
  }

  /* macOS: the OS draws traffic lights in the top-left of the overlay.
     The lights are taller than the generic 32px fallback, so raise the
     minimum height to keep them from overhanging into the app content.
     Keep the titlebar background uniform so the lights don't sit on a
     darker patch, and nudge the drag region past the light cluster. */
  :global(html[data-platform="macos"]) .titlebar {
    background: color-mix(in srgb, var(--lumiverse-bg-deep) 86%, transparent);
  }

  :global(html[data-platform="macos"]) .dragRegion {
    top: max(env(titlebar-area-y, 0px), 6px);
    left: max(env(titlebar-area-x, 78px), 78px);
    width: calc(100% - max(env(titlebar-area-x, 78px), 78px));
    height: calc(var(--app-window-controls-overlay-top, 40px) - max(env(titlebar-area-y, 0px), 6px));
    padding-left: 12px;
    justify-content: center;
  }

  .dragRegion {
    position: absolute;
    top: env(titlebar-area-y, 0px);
    left: env(titlebar-area-x, 0px);
    width: env(titlebar-area-width, 100%);
    height: env(titlebar-area-height, 32px);
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 0 14px;
    color: var(--lumiverse-text-muted);
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 0.02em;
    user-select: none;
    -webkit-user-select: none;
    pointer-events: auto;
    cursor: grab;
  }

  .brandMark {
    width: 8px;
    height: 8px;
    border-radius: 999px;
    background: var(--lumiverse-primary);
    box-shadow: 0 0 12px var(--lumiverse-primary-050);
  }

  .title {
    opacity: 0.9;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
}

import { hasTauriDesktopBridge } from '@/lib/desktopWebView'
import type { MouseEvent } from 'react'
import { useTranslation } from 'react-i18next'
import { Minus, Square, X } from 'lucide-react'
import { getCurrentWindow } from '@tauri-apps/api/window'
import { useContextualTitle } from '@/hooks/useContextualTitle'
import styles from './DesktopPwaTitlebar.module.css'

export default function DesktopPwaTitlebar() {
  const { t } = useTranslation('common')
  const context = useContextualTitle()
  const title = context || t('appName')
  const isTauriDesktop = hasTauriDesktopBridge()

  const startDragging = (event: MouseEvent<HTMLDivElement>) => {
    // Own the gesture explicitly instead of combining Tauri's injected drag
    // attribute handler with React's double-click handler. The second press of
    // a double-click is reserved for toggleMaximize below.
    if (!isTauriDesktop || event.button !== 0 || event.detail !== 1) return
    event.preventDefault()
    void getCurrentWindow().startDragging().catch((error) => console.warn('[titlebar] drag failed:', error))
  }

  // These controls are deliberately first-party rather than theme-supplied.
  // A theme can style the buttons, but cannot gain native-window authority.
  const minimize = () => {
    if (!isTauriDesktop) return
    void getCurrentWindow().minimize().catch((error) => console.warn('[titlebar] minimize failed:', error))
  }

  const toggleMaximize = () => {
    if (!isTauriDesktop) return
    void getCurrentWindow().toggleMaximize().catch((error) => console.warn('[titlebar] toggle maximize failed:', error))
  }

  const close = () => {
    if (!isTauriDesktop) return
    // The desktop host intercepts CloseRequested and hides this window back
    // to the tray, so this does not terminate the companion application.
    void getCurrentWindow().close().catch((error) => console.warn('[titlebar] close failed:', error))
  }

  return (
    <div className={styles.titlebar} data-component="DesktopPwaTitlebar">
      <div
        className={styles.dragRegion}
        data-part="drag-region"
        onMouseDown={startDragging}
        onDoubleClick={toggleMaximize}
      >
        <div className={styles.brandMark} />
        <span className={styles.title}>{title}</span>
      </div>
      {isTauriDesktop && (
        <div className={styles.windowControls} data-part="window-controls" aria-label="Window controls">
          <button type="button" className={styles.windowControl} data-part="minimize" onClick={minimize} aria-label="Minimize window" title="Minimize">
            <Minus size={15} strokeWidth={2} />
          </button>
          <button type="button" className={styles.windowControl} data-part="maximize" onClick={toggleMaximize} aria-label="Maximize or restore window" title="Maximize or restore">
            <Square size={12} strokeWidth={2} />
          </button>
          <button type="button" className={`${styles.windowControl} ${styles.closeControl}`} data-part="close" onClick={close} aria-label="Close window" title="Close to tray">
            <X size={15} strokeWidth={2} />
          </button>
        </div>
      )}
    </div>
  )
}

sources.src/components/shared/EmbeddingConnectio:
import { rememberConnection, useConnectionRecents } from '@/hooks/useConnectionRecents'
import { useEffect, useState } from 'react'
import { embeddingsApi, type EmbeddingConnectionProfile } from '@/api/embeddings'
import ModelCombobox from '@/components/panels/connection-manager/ModelCombobox'
import styles from './SidecarConnectionPicker.module.css'
import SearchableSelect from './SearchableSelect'
import ProviderIcon from './ProviderIcon'
import { useConnectionLibrary } from '@/hooks/useConnectionLibrary'
import { reorderProfiles } from '@/store/slices/connections-order-merge'

interface Props {
  label: string
  ariaLabel?: string
  profiles: EmbeddingConnectionProfile[]
  connectionProfileId: string | null
  model: string | null
  onConnectionChange: (id: string | null) => void
  onModelChange: (model: string | null) => void
  onRemove?: () => void
  disabled?: boolean
  testId?: string
}

export default function EmbeddingConnectionPicker({
  label,
  ariaLabel,
  profiles,
  connectionProfileId,
  model,
  onConnectionChange,
  onModelChange,
  onRemove,
  disabled,
  testId,
}: Props) {
  const library = useConnectionLibrary('embedding')
  const recentIds = useConnectionRecents('embedding')
  const [models, setModels] = useState<string[]>([])
  const [modelLabels, setModelLabels] = useState<Record<string, string>>({})
  const [loading, setLoading] = useState(false)
  const selected = profiles.find((profile) => profile.id === connectionProfileId)

  useEffect(() => {
    setModels([])
    setModelLabels({})
  }, [connectionProfileId])

  const refresh = async () => {
    if (!connectionProfileId) return
    setLoading(true)
    try {
      const result = await embeddingsApi.previewModels({ profile_id: connectionProfileId })
      setModels(result.models || [])
      setModelLabels(result.model_labels || {})
    } catch {
      setModels([])
      setModelLabels({})
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className={styles.pickerStack} data-testid={testId}>
      <div className={styles.pickerHeader}>
        <span className={styles.pickerLabel}>{label}</span>
        {onRemove && (
          <button type="button" className={styles.tagRemove} onClick={onRemove} aria-label="Remove fallback">&times;</button>
        )}
      </div>
      <div className={styles.pickerControl}>
        <SearchableSelect
          value={connectionProfileId || ''}
          onChange={value => {
            const id = value || null
            onConnectionChange(id)
            if (id) rememberConnection('embedding', id)
            const profile = profiles.find(entry => entry.id === id)
            if (profile) onModelChange(profile.model || null)
          }}
          options={reorderProfiles(profiles, library.library.profileOrder).map(profile => ({
            value: profile.id, label: profile.name || profile.provider,
            sublabel: `${profile.provider} / ${profile.model}`, group: library.folderName(profile.id),
            leading: <ProviderIcon kind="embedding" provider={profile.provider} fill />,
          }))}
          groupOrder={library.folders.map(folder => folder.name)}
          recentValues={recentIds}
          forceSearch
          clearable
          ariaLabel={ariaLabel || label}
          disabled={disabled}
        />
        {selected && (
          <ModelCombobox
            value={model || selected.model || ''}
            onChange={(value) => onModelChange(value || null)}
            models={models}
            modelLabels={modelLabels}
            loading={loading}
            onRefresh={refresh}
            autoRefreshOnFocus
            refreshKey={selected.id}
            appearance="standard"
            placeholder="Embedding model ID"
            emptyMessage="No embedding models returned"
            disabled={disabled}
          />
        )}
      </div>
      {profiles.length === 0 && (
        <p className={styles.pickerHint}>Add an Embedding Models connection in the Connections tab first.</p>
      )}
    </div>
  )
}

.controls, .fields { display: flex; flex-direction: column; gap: 8px; min-width: 0; padding: 0; color: var(--lumiverse-text); }
.fields { display: grid; grid-template-columns: minmax(0, .7fr) minmax(0, 1fr) auto; border: 0; border-bottom: 1px solid var(--lumiverse-border); border-radius: 0; padding: 0 0 10px; margin: 0; }
.fields > .chips { grid-column: 1 / -1; }
.fields > button { align-self: end; }
.fields legend { font-weight: 600; color: var(--lumiverse-text-muted); font-size: calc(11.5px * var(--lumiverse-font-scale, 1)); padding-bottom: 6px; }
.controls label, .fields label, .dialog label { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.controls input, .controls select, .fields input, .dialog input, .dialog select { width: 100%; min-width: 0; box-sizing: border-box; background: var(--lumiverse-bg); color: var(--lumiverse-text); border: 1px solid var(--lumiverse-border); border-radius: 6px; padding: 8px; }
.controls button, .fields button, .dialog button { min-height: 36px; padding: 6px 10px; background: var(--lumiverse-bg-elevated); color: var(--lumiverse-text); border: 1px solid var(--lumiverse-border); border-radius: 6px; cursor: pointer; }
.controls button:disabled, .fields button:disabled, .dialog button:disabled { opacity: .5; cursor: default; }
.controls button:focus-visible, .fields button:focus-visible, .dialog button:focus-visible { outline: 2px solid var(--lumiverse-primary); outline-offset: 2px; }
.root { min-height: 0; padding: 0; display: flex; flex-direction: column; gap: 8px; }
.folderRow {
  width: 100%;
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr) auto 16px;
  align-items: center;
  gap: 10px;
  min-height: 48px;
  padding: 10px 12px;
