  color: var(--lumiverse-text);
  border: 1px solid var(--lumiverse-border);
  border-radius: 10px;
  cursor: pointer;
  transition: border-color var(--lumiverse-transition-fast), background var(--lumiverse-transition-fast);
}
.folderRow:hover { background: var(--lumiverse-fill-hover); border-color: color-mix(in srgb, var(--lumiverse-primary) 18%, transparent); }
.folderRow:focus-visible { outline: 2px solid var(--lumiverse-primary); outline-offset: 2px; }
.folderRow span { min-width: 0; overflow-wrap: anywhere; }
.folderRow b { min-width: 28px; padding: 2px 6px; text-align: center; border-radius: 5px; background: var(--lumiverse-fill-hover); font-size: calc(11px * var(--lumiverse-font-scale, 1)); font-weight: 500; font-variant-numeric: tabular-nums; color: var(--lumiverse-text-muted); }
.folderIcon, .folderChevron { color: var(--lumiverse-text-muted); }
.folderChevron { opacity: .65; }
.row, .chips { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; min-width: 0; }
.chips button { max-width: 100%; overflow-wrap: anywhere; white-space: normal; }
.row select { flex: 1; width: auto; }
.dialog { margin: auto; width: min(440px, calc(90vw / var(--lumiverse-ui-scale, 1))); max-height: calc(85dvh / var(--lumiverse-ui-scale, 1)); overflow-y: auto; box-sizing: border-box; padding: 18px; border: 1px solid var(--lumiverse-border); border-radius: 12px; background: var(--lumiverse-bg); color: var(--lumiverse-text); }
.dialog::backdrop { background: rgba(0, 0, 0, .6); }
.dialog form { display: flex; flex-direction: column; gap: 12px; }
.dialog h3 { margin: 0; }
.dialog p { margin: 0; overflow-wrap: anywhere; }
.error { color: var(--lumiverse-danger, #e89090); overflow-wrap: anywhere; }
.badges { display: inline; color: var(--lumiverse-text-muted); font-size: .85em; overflow-wrap: anywhere; }

.fields input { padding: 5px 8px; font-size: calc(12px * var(--lumiverse-font-scale, 1)); height: 30px; }
.fields label { font-size: calc(11.5px * var(--lumiverse-font-scale, 1)); color: var(--lumiverse-text-muted); }
.fields button { min-height: 30px; padding: 4px 8px; font-size: calc(12px * var(--lumiverse-font-scale, 1)); }


.fields { padding: 8px; border: 1px solid var(--lumiverse-border); border-radius: 7px; background: var(--world-book-detail-bg, var(--lumiverse-bg-deep, var(--lumiverse-bg))); }
.fields legend { float: left; width: 100%; grid-column: 1 / -1; padding: 0 0 6px; }

.controls { margin-bottom: 12px; }
.controls[hidden] { display: none; }
