/* ── Full-screen expanded text editor modal ── */

.overlay {
  --expanded-editor-keyboard-space: 0px;
  position: fixed;
  inset: 0;
  height: calc(var(--app-fullscreen-height, var(--app-shell-height, 100dvh)) / var(--lumiverse-ui-scale, 1));
  width: var(--app-scaled-viewport-width);
  background: var(--lumiverse-fill-deepest);
  z-index: 10010;
  overflow: hidden;
  overscroll-behavior: none;
}

/* Desktop dialogs fit the visual viewport. Mobile fullscreen editors keep
   their shell geometry and reveal the caret through internal scrolling. */
.viewport {
  position: absolute;
  top: calc(var(--app-visual-viewport-offset-top) / var(--lumiverse-ui-scale, 1));
  left: calc(var(--app-visual-viewport-offset-left) / var(--lumiverse-ui-scale, 1));
  height: calc(var(--app-visual-viewport-height) / var(--lumiverse-ui-scale, 1));
  width: calc(var(--app-visual-viewport-width) / var(--lumiverse-ui-scale, 1));
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  pointer-events: none;
}

:global([data-glass]) .overlay {
  background: var(--lumiverse-modal-backdrop, rgba(0, 0, 0, 0.6));
  backdrop-filter: blur(var(--lcs-glass-soft-blur, 6px)) var(--lcs-liquid-filter, );
}

.dialog {
  pointer-events: auto;
  background: var(--lumiverse-bg, #0f0d15);
  border: 1px solid var(--lumiverse-border);
  border-radius: 16px;
  display: flex;
  flex-direction: column;
  width: 100%;
  max-width: clamp(340px, calc(94vw / var(--lumiverse-ui-scale, 1)), min(900px, var(--lumiverse-content-max-width, 900px)));
  height: calc(80vh / var(--lumiverse-ui-scale, 1));
  max-height: 100%;
  box-shadow: var(--lumiverse-shadow-md, 0 8px 24px rgba(0, 0, 0, 0.4)), 0 0 1px var(--lumiverse-primary-020);
  overflow: hidden;
  overscroll-behavior: none;
}

:global([data-glass]) .dialog {
  box-shadow: 0 32px 80px rgba(0, 0, 0, 0.6), 0 0 1px var(--lumiverse-primary-020);
}

/* ── Inline variant (renders in-flow below the field) ── */

.inlineDialog {
  --expanded-editor-keyboard-space: 0px;
  background: var(--lumiverse-bg, #0f0d15);
  border: 1px solid var(--lumiverse-primary);
  border-radius: 12px;
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 380px;
  overflow: hidden;
}

/* ── Header ── */

.header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 18px;
  border-bottom: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-bg-elevated);
  flex-shrink: 0;
}

.headerContent {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.title {
  margin: 0;
  font-size: calc(15px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.toolbar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
}

.toolbarBtn {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 4px 10px;
  border-radius: 6px;
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.04));
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text-dim);
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
  transition: all 0.15s ease;
  align-self: flex-start;
}

.toolbarBtn:hover,
.toolbarBtnActive {
  border-color: var(--lumiverse-primary);
  color: var(--lumiverse-primary);
}

.toolbarBtnActive {
  background: var(--lumiverse-primary-010);
}

.closeBtn {
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: transparent;
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text-muted);
  cursor: pointer;
  flex-shrink: 0;
  transition: all 0.15s ease;
}

.closeBtn:hover {
  background: var(--lumiverse-fill-hover);
  color: var(--lumiverse-text);
}

/* ── Find and replace ── */

.findPanel {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-bg-elevated);
  flex-shrink: 0;
}

.findRow,
.replaceRow {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.findIcon {
  flex-shrink: 0;
  color: var(--lumiverse-text-dim);
}

.findInput {
  flex: 1;
  min-width: 80px;
  height: 30px;
  padding: 4px 8px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 6px;
  outline: none;
  background: var(--lumiverse-input-bg, rgba(0, 0, 0, 0.2));
  color: var(--lumiverse-text);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
}

.findInput:focus {
  border-color: var(--lumiverse-primary);
}

.matchCount {
  min-width: 46px;
  color: var(--lumiverse-text-dim);
  font-family: var(--lumiverse-font-mono, monospace);
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  text-align: center;
}

.findIconBtn,
.replaceBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  min-height: 28px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 6px;
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text-dim);
  cursor: pointer;
}

.findIconBtn {
  width: 28px;
  padding: 0;
}

.replaceBtn {
  padding: 4px 10px;
  color: var(--lumiverse-text);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
}

.findIconBtn:hover:not(:disabled),
.replaceBtn:hover:not(:disabled) {
  border-color: var(--lumiverse-primary);
  color: var(--lumiverse-primary);
}

.findIconBtn:disabled,
.replaceBtn:disabled {
  opacity: 0.4;
  cursor: default;
}

/* ── Body ── */

.body {
  flex: 1;
  display: flex;
  min-height: 0;
  overflow: hidden;
}

.editorArea {
  --expanded-editor-tab-size: 4;
  flex: 1;
  min-width: 0;
  /* min-height:0 lets this flex child shrink below its (very tall) content so
     the inner scroll box engages. Without it, on mobile the body switches to a
     column flex and this item's default min-height:auto balloons to the full
     <pre> height, overflowing the clipped body and killing scroll. */
  min-height: 0;
  display: flex;
  flex-direction: column;
  position: relative;
}

.markdownPreview {
  flex: 1;
  min-height: 0;
  overflow: auto;
  padding: 16px;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
}

/* ── Plain textarea (no highlighting) ── */

.textarea {
  width: 100%;
  height: 100%;
  padding: 16px;
  margin: 0;
  border: none;
  outline: none;
  resize: none;
  background: transparent;
  color: var(--lumiverse-text);
  caret-color: var(--lumiverse-text);
  font-family: inherit;
  font-size: calc(14px * var(--lumiverse-font-scale, 1));
  line-height: 1.6;
  tab-size: var(--expanded-editor-tab-size);
  -moz-tab-size: var(--expanded-editor-tab-size);
  white-space: pre-wrap;
  word-break: break-word;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
  box-sizing: border-box;
}

.textarea::placeholder {
  color: var(--lumiverse-text-dim);
}

/* The textarea is viewport-sized and owns native scrolling. A passive <pre>
   shares its grid cell and mirrors scroll offsets, but cannot grow the field
   to document height or move its caret. Keep grid stacking (not absolute
   positioning) so both boxes round identically under fractional UI zoom. */

.highlightContainer {
  flex: 1;
  min-height: 0;
  display: flex;
  overflow: clip;
}

.highlightContainer[hidden] {
  display: none;
}

.highlightInner {
  flex: 1;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: minmax(0, 1fr);
  min-height: 0;
  min-width: 0;
}

.textarea,
.textareaHighlighted,
.highlightPre {
  grid-area: 1 / 1;
  min-width: 0;
  min-height: 0;
  width: 100%;
  height: 100%;
  /* Reserve identical wrapping width with classic as well as overlay
     scrollbars, including when the content fits without scrolling. */
  scrollbar-gutter: stable;
  overflow-anchor: none;
}

.highlightPre {
  /* WebKit does not reserve a stable gutter with overflow:hidden. Match the
     textarea's overflow so larger fonts cannot wrap the two layers differently.
     This mirror remains inert and follows only the textarea's scroll offsets. */
  overflow-x: hidden;
  overflow-y: auto;
  margin: 0;
  padding: 16px;
  font-family: var(--lumiverse-font-mono, monospace);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  line-height: 1.6;
  white-space: pre-wrap;
  overflow-wrap: break-word;
  word-break: normal;
  tab-size: var(--expanded-editor-tab-size);
  -moz-tab-size: var(--expanded-editor-tab-size);
  color: var(--lumiverse-text);
  pointer-events: none;
  box-sizing: border-box;
}

.highlightPre::-webkit-scrollbar-thumb {
  background: transparent;
}

.textareaHighlighted {
  padding: 16px;
  margin: 0;
  border: none;
  outline: none;
  resize: none;
  overflow-x: hidden;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
  background: transparent;
  color: transparent;
  caret-color: var(--lumiverse-text);
  font-family: var(--lumiverse-font-mono, monospace);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  line-height: 1.6;
  white-space: pre-wrap;
  overflow-wrap: break-word;
  word-break: normal;
  tab-size: var(--expanded-editor-tab-size);
  -moz-tab-size: var(--expanded-editor-tab-size);
  -webkit-text-fill-color: transparent;
  box-sizing: border-box;
}

/* Plain fields still provide a non-painted measurement mirror for caret
   visibility. Keep their proportional font and wrapping, not macro metrics. */
.highlightPlain {
  visibility: hidden;
  font-family: inherit;
  font-size: calc(14px * var(--lumiverse-font-scale, 1));
  word-break: break-word;
}

.textareaHighlighted::placeholder {
  color: var(--lumiverse-text-dim);
  -webkit-text-fill-color: var(--lumiverse-text-dim);
}

/* Lock every text metric across BOTH layers so the caret (which lives in the
   <textarea>) and the visible glyphs (in the <pre>) never drift apart. Under
   UI zoom, even small UA-default differences between form controls and block
   text compound into visible x/y offset by the time a line wraps. Keep these
   selectors grouped and layout-neutral: color/background-only highlighting,
   no font-weight/style changes, and identical shaping/wrapping rules. */
.textarea,
.highlightPre,
.textareaHighlighted {
  /* Matching scroll clearance lets even the final line clear an overlaid
     keyboard, without moving the fullscreen frame or changing selection. */
  padding-bottom: calc(16px + var(--expanded-editor-keyboard-space, 0px));
  font-weight: 400;
  font-style: normal;
  letter-spacing: 0;
  word-spacing: 0;
  text-indent: 0;
  text-transform: none;
  font-kerning: none;
  font-variant-ligatures: none;
  font-variant-numeric: normal;
  font-feature-settings: "liga" 0, "calt" 0;
  font-synthesis: none;
  text-rendering: auto;
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}

/* ── Syntax highlight tokens ── */

.hlBracket {
  color: #c792ea;
}

.hlMacroName {
  color: var(--lumiverse-primary, #9370db);
}

.hlSep {
  color: var(--lumiverse-text-dim, #666);
  opacity: 0.6;
}

.hlXmlTag {
  color: #82aaff;
}

.hlMdDelim {
  color: var(--lumiverse-text-dim, #666);
  opacity: 0.55;
}

.hlMdCode {
  color: #c3e88d;
}

.hlMdHeader {
  color: #f78c6c;
}

.findMatch,
.findMatchCurrent {
  padding: 0;
  border-radius: 2px;
  color: inherit;
}

.findMatch {
  background: color-mix(in srgb, var(--lumiverse-warning, #f5b942) 42%, transparent);
}

.findMatchCurrent {
  background: color-mix(in srgb, var(--lumiverse-primary, #9370db) 72%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, white 52%, transparent);
}

/* ── Macro sidebar ── */

.macroSidebar {
  width: 260px;
  flex-shrink: 0;
  border-right: 1px solid var(--lumiverse-border);
  display: flex;
  flex-direction: column;
  background: var(--lumiverse-fill-subtle, rgba(0, 0, 0, 0.06));
  overflow-x: hidden;
}

.macroList {
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  -webkit-overflow-scrolling: touch;
}

.macroSearch {
  padding: 8px;
  border-bottom: 1px solid var(--lumiverse-border);
}

.macroSearchInner {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 10px;
  background: var(--lumiverse-input-bg, rgba(0, 0, 0, 0.2));
  border-radius: 8px;
  border: 1px solid transparent;
  transition: border-color 0.15s ease;
}

.macroSearchInner:focus-within {
  border-color: var(--lumiverse-primary-020);
}

.macroSearchInput {
  border: none;
  padding: 2px;
  background: transparent;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  width: 100%;
  color: var(--lumiverse-text);
  outline: none;
}

.macroSearchClear {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  padding: 0;
  border: none;
  border-radius: 5px;
  background: transparent;
  color: var(--lumiverse-text-dim);
  cursor: pointer;
}

.macroSearchClear:hover {
  background: var(--lumiverse-fill-hover);
  color: var(--lumiverse-text);
}

.macroGroup {
  padding: 6px 0;
}

.macroGroupTitle {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text-dim);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 4px 12px;
}

.macroItem {
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding: 5px 12px;
  cursor: pointer;
  border-radius: 6px;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  margin: 0 4px;
  transition: background 0.15s ease;
  min-width: 0;
  overflow: hidden;
}

.macroItem:hover {
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.05));
}

.macroSyntax {
  font-family: var(--lumiverse-font-mono, monospace);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
  flex-shrink: 1;
}

.macroDesc {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ── Expandable textarea wrapper ── */

.textareaWrapper {
  position: relative;
  width: 100%;
}

.textareaWrapper > textarea {
  width: 100%;
  box-sizing: border-box;
}

.expandBtn {
  position: absolute;
  top: 5px;
  right: 5px;
  width: var(--lumiverse-btn-icon-sm);
  height: var(--lumiverse-btn-icon-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 5px;
  background: var(--lumiverse-bg, #0f0d15);
  border: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text-dim);
  cursor: pointer;
  opacity: 0;
  transition: all 0.15s ease;
  z-index: 1;
}

.textareaWrapper:hover .expandBtn,
.textareaWrapper:focus-within .expandBtn {
  opacity: 1;
}

.expandBtn:hover {
  color: var(--lumiverse-primary);
  border-color: var(--lumiverse-primary);
}

.expandBtn:disabled {
  cursor: not-allowed;
  opacity: 0.25;
}

/* ── Mobile ── */

@media (max-width: 600px) {
  .overlay {
    --expanded-editor-keyboard-space: max(0px, calc((var(--app-fullscreen-height, var(--app-shell-height, 100dvh)) - var(--app-visual-viewport-height) - var(--app-visual-viewport-offset-top)) / var(--lumiverse-ui-scale, 1)));
  }

  .viewport {
    top: 0;
    height: 100%;
    padding: 0;
  }

  .dialog {
    max-width: 100%;
    max-height: 100%;
    height: 100%;
    border-radius: 0;
    padding-top: calc(var(--app-interactive-safe-top, env(safe-area-inset-top, 0px)) / var(--lumiverse-ui-scale, 1));
  }

  .body {
    flex-direction: column;
  }

  .header {
    padding: 10px 12px;
  }

  .findPanel {
    padding: 8px;
  }

  .findRow,
  .replaceRow {
    flex-wrap: wrap;
  }

  .findInput {
    font-size: 16px;
  }

  .replaceRow .findInput {
    flex-basis: calc(100% - 24px);
  }

  .textarea {
    font-size: calc(16px * var(--lumiverse-font-scale, 1)); /* Prevent iOS/Android auto-zoom on focus */
  }

  .textareaHighlighted,
  .highlightPre {
    /* Mirror the global reset's mobile form-control rule
       (`input,textarea,select { font-size: max(16px, 1em) !important }`, which
       blocks iOS focus auto-zoom). The reset can't target the <pre>, so the two
       overlay layers would otherwise diverge whenever --lumiverse-font-scale ≠ 1
       (the textarea gets forced to max(16px,1em) while the <pre> keeps the module
       value). Using the identical formula keeps both at ONE font-size for every
       scale — 1em resolves to the same inherited size for each, so the caret and
       the highlighted glyphs stay aligned. */
    font-size: max(16px, 1em);
  }

  .macroSidebar {
    width: 100%;
    max-height: 320px;
    border-right: none;
    border-bottom: 1px solid var(--lumiverse-border);
    flex-shrink: 0;
  }
}

/* Touch-only devices have no hover, so reveal the expand button permanently.
   Uses `any-hover: none` so it only matches when NO input device supports hover
   (true phones/tablets). `hover: none` incorrectly matches on Windows touchscreen
   laptops in Firefox/Edge. */
@media (any-hover: none) {
  .expandBtn {
    opacity: 0.7;
  }
}

