  border-radius: 8px;
  color: var(--lumiverse-text);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  font-family: inherit;
  appearance: none;
  cursor: pointer;
  transition: border-color var(--lumiverse-transition-fast);
}

.select:focus {
  border-color: var(--lumiverse-primary-muted);
  outline: none;
}

.selectChevron {
  position: absolute;
  right: 12px;
  top: 50%;
  transform: translateY(-50%);
  pointer-events: none;
  color: var(--lumiverse-text-muted);
}

/* ── Buttons ── */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 14px;
  border-radius: var(--lumiverse-radius, 8px);
  border: 1px solid var(--lumiverse-border);
  background: transparent;
  color: var(--lumiverse-text-muted);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  font-family: inherit;
  cursor: pointer;
  white-space: nowrap;
  transition:
    background var(--lumiverse-transition-fast),
    color var(--lumiverse-transition-fast),
    border-color var(--lumiverse-transition-fast);
}

.btn:hover {
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text);
}

.btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.btnPrimary {
  background: var(--lumiverse-primary);
  color: var(--lumiverse-primary-contrast, #fff);
  border-color: var(--lumiverse-primary);
}

.btnPrimary:hover {
  background: var(--lumiverse-primary-hover);
  color: var(--lumiverse-primary-contrast, #fff);
}

.btnDanger {
  background: var(--lumiverse-danger);
  color: #fff;
  border-color: var(--lumiverse-danger);
}

.btnDanger:hover {
  background: var(--lumiverse-danger-hover);
}

.btnGhost {
  border-color: transparent;
}

.btnGhost:hover {
  background: var(--lumiverse-fill-subtle);
  border-color: transparent;
}

.btnSm {
  padding: 5px 10px;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
}

.btnIcon {
  width: 32px;
  height: 32px;
  padding: 0;
  border-color: transparent;
}

.btnIconSm {
  width: 28px;
  height: 28px;
  padding: 0;
  border-color: transparent;
  border-radius: 6px;
}

.btnDangerGhost {
  border-color: transparent;
  color: var(--lumiverse-text-dim);
}

.btnDangerGhost:hover {
  color: var(--lumiverse-danger, #ef4444);
  background: var(--lumiverse-danger-015);
  border-color: transparent;
}

.btnSpinner {
  width: 14px;
  height: 14px;
  border: 2px solid currentColor;
  border-top-color: transparent;
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

.imageInput {}

.imageInputRow {
  display: flex;
  gap: 10px;
  align-items: flex-start;
}

.imageInputField {
  flex: 1;
}

.imagePreview {
  width: 40px;
  height: 40px;
  border-radius: 6px;
  overflow: hidden;
  border: 1px solid var(--lumiverse-border);
  flex-shrink: 0;
  background: var(--lumiverse-fill-subtle);
}

.imagePreviewImg {
  width: 100%;
  height: 100%;
  object-fit: cover;
  animation: lumiverseFadeIn 0.2s ease;
}

.imagePlaceholder {
  width: 40px;
  height: 40px;
  border-radius: 6px;
  border: 1px dashed var(--lumiverse-border);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--lumiverse-text-dim);
}

