  display: none;
}

.prose
  :global(.guide-content-tab-panel > :first-child) {
  margin-top: 0;
}

.prose
  :global(.guide-content-tab-panel > :last-child) {
  margin-bottom: 0;
}

@media (max-width: 600px) {
  .body {
    padding: 14px 14px 20px;
  }
}

