.modal {
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5),
    0 0 40px var(--lumiverse-primary-020);
}

.header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 20px 24px 14px;
  border-bottom: 1px solid var(--lumiverse-border);
  flex-shrink: 0;
}

.title {
  margin: 0;
  font-size: calc(15px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  color: var(--lumiverse-text);
  letter-spacing: -0.01em;
}

.attribution {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
  margin: 0;
}

.subtitle {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim);
  margin: 0;
  padding: 0 24px;
  padding-top: 12px;
  line-height: 1.5;
}

.body {
  padding: 12px 24px 20px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.textarea {
  width: 100%;
  min-height: 100px;
  max-height: 200px;
  padding: 12px 14px;
  border-radius: var(--lcs-radius-sm, 8px);
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-bg-dark);
  color: var(--lumiverse-text);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  line-height: 1.5;
  resize: vertical;
  font-family: inherit;
  transition: border-color var(--lumiverse-transition-fast);
}

.textarea::placeholder {
  color: var(--lumiverse-text-dim);
}

.textarea:focus {
  outline: none;
  border-color: var(--lumiverse-primary-050, rgba(147, 112, 219, 0.5));
}

.input {
  width: 100%;
  padding: 12px 14px;
  border-radius: var(--lcs-radius-sm, 8px);
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-bg-dark);
  color: var(--lumiverse-text);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  line-height: 1.5;
  font-family: inherit;
  transition: border-color var(--lumiverse-transition-fast);
}

.input::placeholder {
  color: var(--lumiverse-text-dim);
}

.input:focus {
  outline: none;
  border-color: var(--lumiverse-primary-050, rgba(147, 112, 219, 0.5));
}

.actions {
  display: flex;
  align-items: center;
  gap: 8px;
  justify-content: flex-end;
}

.btn {
  padding: 8px 18px;
  border-radius: var(--lcs-radius-sm, 8px);
  font-size: calc(12.5px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  cursor: pointer;
  border: 1px solid var(--lumiverse-border);
  transition: all var(--lumiverse-transition-fast);
}

.btnCancel {
  background: transparent;
  color: var(--lumiverse-text-muted);
}

.btnCancel:hover {
  background: var(--lumiverse-fill-subtle, rgba(255, 255, 255, 0.04));
  color: var(--lumiverse-text);
}

.btnSecondary {
  background: var(--lumiverse-bg-dark);
  color: var(--lumiverse-text-dim);
}

.btnSecondary:hover {
  background: var(--lumiverse-bg-darker);
  color: var(--lumiverse-text);
}

.btnSubmit {
  background: var(--lumiverse-primary-015, rgba(147, 112, 219, 0.15));
  color: var(--lumiverse-primary-text, #c4b5fd);
  border-color: var(--lumiverse-primary-020, rgba(147, 112, 219, 0.2));
}

.btnSubmit:hover {
  background: var(--lumiverse-primary-025, rgba(147, 112, 219, 0.25));
  border-color: var(--lumiverse-primary-050, rgba(147, 112, 219, 0.5));
}

.btnSubmit:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

@media (max-width: 480px) {
  .modal {
    border-radius: 14px 14px 0 0;
  }

  .header {
    padding: 16px 18px 12px;
  }

  .subtitle {
    padding: 10px 18px 0;
  }

  .body {
    padding: 10px 18px 18px;
  }

  .textarea {
    min-height: 80px;
  }

  .actions {
    flex-direction: column-reverse;
  }

  .actions .btn {
    width: 100%;
    text-align: center;
  }
}

sources.src/components/shared/InputPromptModal.t:
import { useEffect, useRef, useState } from 'react'
import { useTranslation } from 'react-i18next'
import { ModalShell } from '@/components/shared/ModalShell'
import css from './InputPromptModal.module.css'

interface InputPromptModalProps {
  isOpen: boolean
  title: string
  message?: string
  placeholder?: string
  defaultValue?: string
  submitLabel?: string
  cancelLabel?: string
  /** Optional middle button (e.g. "Skip" in regen feedback) */
  secondaryLabel?: string
  onSubmit: (value: string) => void
  onCancel: () => void
  onSecondary?: () => void
  /** Use textarea instead of single-line input */
  multiline?: boolean
  /** Icon component to show in the header */
  icon?: React.ReactNode
  zIndex?: number
  /** Attribution line below the title (e.g. extension name) */
  attribution?: string
  /** Optional content rendered between the input and the action buttons */
  footer?: React.ReactNode
}

export function InputPromptModal({
  isOpen,
  title,
  message,
  placeholder,
  defaultValue = '',
  submitLabel,
  cancelLabel,
  secondaryLabel,
  onSubmit,
  onCancel,
  onSecondary,
  multiline = false,
  icon,
  zIndex,
  attribution,
  footer,
}: InputPromptModalProps) {
  const { t } = useTranslation('shared', { keyPrefix: 'inputPrompt' })
  const { t: tc } = useTranslation('common')
  const resolvedSubmitLabel = submitLabel ?? t('submit')
  const resolvedCancelLabel = cancelLabel ?? tc('actions.cancel')
  const [value, setValue] = useState(defaultValue)
  const inputRef = useRef<HTMLTextAreaElement | HTMLInputElement>(null)

  useEffect(() => {
    if (isOpen) {
      setValue(defaultValue)
      requestAnimationFrame(() => inputRef.current?.focus())
    }
  }, [isOpen, defaultValue])

  const canSubmit = value.trim().length > 0

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if ((e.ctrlKey || e.metaKey) && e.key === 'Enter' && canSubmit) {
      e.preventDefault()
      onSubmit(value)
      return
    }
    if (!multiline && e.key === 'Enter' && canSubmit) {
      e.preventDefault()
      onSubmit(value)
    }
  }

  return (
    <ModalShell
      mobilePresentation="dialog"
      isOpen={isOpen}
      onClose={onCancel}
      maxWidth="clamp(320px, 90vw, min(520px, var(--lumiverse-content-max-width, 520px)))"
      className={css.modal}
      zIndex={zIndex}
    >
      <div className={css.header}>
        {icon}
        <div>
          <h3 className={css.title}>{title}</h3>
          {attribution && <p className={css.attribution}>{attribution}</p>}
        </div>
      </div>

      {message && <p className={css.subtitle}>{message}</p>}

      <div className={css.body}>
        {multiline ? (
          <textarea
            ref={inputRef as React.RefObject<HTMLTextAreaElement>}
            className={css.textarea}
            placeholder={placeholder}
            value={value}
            onChange={(e) => setValue(e.target.value)}
            onKeyDown={handleKeyDown}
          />
        ) : (
          <input
            ref={inputRef as React.RefObject<HTMLInputElement>}
            type="text"
            className={css.input}
            placeholder={placeholder}
            value={value}
            onChange={(e) => setValue(e.target.value)}
            onKeyDown={handleKeyDown}
          />
        )}

        {footer}

        <div className={css.actions}>
          <button
            type="button"
            className={`${css.btn} ${css.btnCancel}`}
            onClick={onCancel}
          >
            {resolvedCancelLabel}
          </button>

          {secondaryLabel && onSecondary && (
            <button
              type="button"
              className={`${css.btn} ${css.btnSecondary}`}
              onClick={onSecondary}
            >
              {secondaryLabel}
            </button>
          )}

          <button
            type="button"
            className={`${css.btn} ${css.btnSubmit}`}
            disabled={!canSubmit}
            onClick={() => onSubmit(value)}
          >
            {resolvedSubmitLabel}
          </button>
        </div>
      </div>
    </ModalShell>
  )
}

