.pickerStack {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 14px;
  border-top: 1px solid var(--lumiverse-border);
}

.pickerHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.pickerLabel {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  color: var(--lumiverse-text-muted);
}

.addFallbackRow {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
  border-top: 1px solid var(--lumiverse-border);
}

.addFallbackRow .addBtn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.pickerControl {
  width: 100%;
  min-width: 0;
}

.pickerHint {
  margin: 0;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  line-height: 1.5;
  color: var(--lumiverse-text-dim);
}

.addBtn {
  padding: 6px 14px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 6px;
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  cursor: pointer;
  transition: all var(--lumiverse-transition-fast);
}

.addBtn:hover:not(:disabled) {
  background: var(--lumiverse-fill);
  border-color: var(--lumiverse-text-muted);
}

.addBtn:disabled {
  opacity: 0.4;
  cursor: default;
}

.tagRemove {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 14px;
  height: 14px;
  border: none;
  background: transparent;
  color: var(--lumiverse-text-muted);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
  border-radius: 2px;
  padding: 0;
  line-height: 1;
}

.tagRemove:hover {
  background: var(--lumiverse-danger, #e53e3e);
  color: white;
}

import ConnectionSelect from '@/components/shared/ConnectionSelect'
import { useTranslation } from 'react-i18next'
import styles from './SidecarConnectionPicker.module.css'

export interface SidecarConnectionPickerProps {
  label?: string
  ariaLabel?: string
  connectionProfileId: string | null
  model: string | null
  onConnectionChange: (profileId: string | null) => void
  onModelChange: (model: string | null) => void
  placeholder?: string
  hint?: string | null
  onRemove?: () => void
  removeLabel?: string
  removeTestId?: string
  testId?: string
  disabled?: boolean
}

export default function SidecarConnectionPicker({
  label = 'Connection',
  ariaLabel,
  connectionProfileId,
  model,
  onConnectionChange,
  onModelChange,
  placeholder,
  hint,
  onRemove,
  removeLabel,
  removeTestId,
  testId,
  disabled = false,
}: SidecarConnectionPickerProps) {
  const { t } = useTranslation('settings')
  const empty = placeholder ?? t('memoryCortex.connectionNone')
  return (
    <div className={styles.pickerStack} data-testid={testId}>
      <div className={styles.pickerHeader}>
        <span className={styles.pickerLabel}>{label}</span>
        {onRemove ? (
          <button
            type="button"
            className={styles.tagRemove}
            onClick={onRemove}
            aria-label={removeLabel ?? t('memoryCortex.removeFallback', { defaultValue: 'Remove fallback' })}
            data-testid={removeTestId}
          >
            &times;
          </button>
        ) : null}
      </div>
      <div className={styles.pickerControl}>
        <ConnectionSelect
          kind="llm"
          value={connectionProfileId || ''}
          onChange={(value) => onConnectionChange(value || null)}
          withModel
          seedDefaultModel={false}
          modelValue={model || ''}
          onModelChange={(value) => onModelChange(value || null)}
          clearable
          clearLabel={empty}
          placeholder={empty}
          searchPlaceholder={t('memoryCortex.searchConnections', { defaultValue: 'Search connections…' })}
          emptyMessage={t('memoryCortex.noConnections', { defaultValue: 'No LLM connections configured' })}
          ariaLabel={ariaLabel ?? label}
          modelPlaceholder={t('memoryCortex.modelPlaceholder')}
          modelEmptyMessage={t('memoryCortex.noModels')}
          modelNoConnectionMessage={t('memoryCortex.selectConnectionFirst', { defaultValue: 'Select a connection first' })}
          modelAppearance="standard"
