.entryListHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.entryListHeaderMobile {
  flex-wrap: wrap;
  align-items: center;
}

.entryListTitle {
  font-size: calc(12.5px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
}

.toolbarActions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.toolbarActionsMobile {
  margin-left: auto;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.toolbarBtn,
.newEntryBtn,
.bulkActionBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 6px 10px;
  border-radius: 8px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text);
  cursor: pointer;
  transition: border-color var(--lumiverse-transition-fast), background var(--lumiverse-transition-fast), opacity var(--lumiverse-transition-fast);
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
}

.toolbarBtn:hover,
.newEntryBtn:hover,
.bulkActionBtn:hover {
  border-color: var(--lumiverse-primary);
}

.toolbarBtnActive {
  border-color: var(--lumiverse-primary);
  background: var(--lumiverse-primary-015);
  color: var(--lumiverse-primary);
}

.newEntryBtn {
  background: var(--lumiverse-primary);
  border-color: transparent;
  color: var(--lumiverse-primary-contrast, #fff);
}

.entrySortRow {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 8px;
}

.entrySortRowMobile {
  flex-wrap: wrap;
  padding: 10px 12px;
  border-radius: 10px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-fill-subtle);
}

.entrySortRowMobile .entrySortSelect {
  flex: 1 1 100%;
}

.entrySortRowMobile .entryPageSizeSelect {
  flex: 1 1 132px;
  min-width: 0;
}

.entrySortSelect,
.entryPageSizeSelect,
.entrySortDirBtn,
.quickSelect {
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text);
  border-radius: 8px;
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
}

.entrySortSelect {
  flex: 1;
  min-width: 0;
  padding: 6px 8px;
}

.entryPageSizeSelect {
  min-width: 116px;
  padding: 6px 8px;
}

.entrySortDirBtn {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 6px 8px;
  cursor: pointer;
}

.entrySearchRow {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 8px;
}

.entrySearchRowMobile {
  flex-wrap: wrap;
}

.entrySearch {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 1 1 220px;
  min-width: 0;
  padding: 7px 10px;
  border-radius: 8px;
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
}

.entrySearch:focus-within {
  border-color: var(--lumiverse-primary);
}

.entrySearchIcon {
  color: var(--lumiverse-text-dim);
  flex-shrink: 0;
}

.entrySearchInput {
  flex: 1;
  min-width: 0;
  background: transparent;
  border: none;
  color: var(--lumiverse-text);
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  outline: none;
}

.entrySearchInput::-webkit-search-cancel-button {
  display: none;
}

.entrySearchCount {
  flex-shrink: 0;
  color: var(--lumiverse-text-dim);
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-variant-numeric: tabular-nums;
}

.entrySearchClear {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 22px;
  height: 22px;
  padding: 0;
  border: none;
  border-radius: 5px;
  background: transparent;
  color: var(--lumiverse-text-dim);
  cursor: pointer;
}

.entrySearchClear:hover {
  background: var(--lumiverse-fill-hover);
  color: var(--lumiverse-text);
}

.entryTypeFilters {
  display: flex;
  gap: 6px;
  margin-top: 8px;
  overflow-x: auto;
  scrollbar-width: none;
}

.entryTypeFilters::-webkit-scrollbar {
  display: none;
}

.entryTypeFilter {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex: 0 0 auto;
  min-height: 28px;
  padding: 4px 9px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 999px;
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text-muted);
  cursor: pointer;
  font-size: calc(10.5px * var(--lumiverse-font-scale, 1));
}

.entryTypeFilter b {
  color: var(--lumiverse-text-dim);
  font-size: calc(9.5px * var(--lumiverse-font-scale, 1));
  font-variant-numeric: tabular-nums;
}

.entryTypeFilter:hover,
.entryTypeFilterActive {
  border-color: var(--lumiverse-primary);
  color: var(--lumiverse-text);
}

.entryTypeFilterActive {
  background: var(--lumiverse-primary-015);
  box-shadow: inset 0 0 0 1px var(--lumiverse-primary);
}

.entryTypeFilter_constant {
  color: var(--lumiverse-warning, #f5a623);
}

.entryTypeFilter_vector {
  color: var(--lumiverse-success, #4ade80);
}

.listOptionsToggle {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  max-width: 100%;
  min-height: 36px;
  padding: 6px 10px;
  border-radius: 8px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text);
  cursor: pointer;
  transition: border-color var(--lumiverse-transition-fast), background var(--lumiverse-transition-fast), color var(--lumiverse-transition-fast);
}

.listOptionsToggle:hover {
  border-color: var(--lumiverse-primary);
}

.listOptionsToggleActive {
  border-color: var(--lumiverse-primary);
  background: var(--lumiverse-primary-015);
  color: var(--lumiverse-primary);
}

.listOptionsSummary {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
}

.listOptionsChevron {
  flex-shrink: 0;
  transition: transform var(--lumiverse-transition-fast);
}

.listOptionsChevronOpen {
  transform: rotate(180deg);
}

.customSortHint,
.bulkBar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: 8px;
  padding: 10px 12px;
  border-radius: 10px;
  border: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-fill-subtle);
}

.customSortHint {
  justify-content: flex-start;
  color: var(--lumiverse-text-dim);
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
}

.bulkLeft,
.bulkActions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.bulkToggle,
.enableToggle,
.selectionToggle,
.inlineToggle {
  accent-color: var(--lumiverse-primary);
  cursor: pointer;
}

.bulkCount {
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text);
}

.bulkDeleteBtn {
  color: var(--lumiverse-error);
}

.section {
  padding: 0;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.sectionStandaloneScroll {
  flex: 1 1 auto;
}

.sectionSharedScroll {
  flex: 0 0 auto;
}

.sectionMobile {
  padding: 0;
}

.entryScroll {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  padding-bottom: calc(12px + var(--app-keyboard-inset-bottom, 0px));
  scroll-padding-block: 10px calc(96px + var(--app-keyboard-inset-bottom, 0px));
  overscroll-behavior-y: contain;
  -webkit-overflow-scrolling: touch;
}

.entryScrollShared {
  flex: 0 0 auto;
  overflow: visible;
  padding-bottom: 0;
  scroll-padding-block: 0;
  overscroll-behavior: auto;
  -webkit-overflow-scrolling: auto;
}

.entryList {
  position: relative;
  margin-top: 10px;
}

.entryListItem {
  padding-bottom: 8px;
}

.entryPagination {
  position: sticky;
  bottom: 0;
  z-index: 10;
  flex-shrink: 0;
  margin-top: 8px;
  padding: 8px 0 12px;
  background: var(--lumiverse-bg-deep);
  border-top: 1px solid color-mix(in srgb, var(--lumiverse-border) 55%, transparent);
  overflow-x: auto;
  overscroll-behavior-x: contain;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}

.entryPagination::-webkit-scrollbar {
  display: none;
}

.entryPaginationControls {
  width: max-content;
  max-width: 100%;
  margin: 0 auto;
}

.entryPaginationDocked {
  width: max-content;
  max-width: 100%;
  margin: 0 auto;
}

@media (max-height: 860px) and (min-width: 720px) {
  .section {
    padding: 0 8px;
  }

  .entryListHeader {
    gap: 8px;
  }

  .toolbarActions {
    gap: 6px;
  }

  .toolbarBtn,
  .newEntryBtn,
  .bulkActionBtn {
    padding: 5px 9px;
  }

  .entrySearchRow,
  .entrySortRow {
    margin-top: 6px;
  }

  .entrySearch {
    padding: 5px 9px;
  }

  .entrySortSelect,
  .entryPageSizeSelect,
  .entrySortDirBtn {
    padding-block: 5px;
  }

  .customSortHint,
  .bulkBar {
    margin-top: 6px;
    padding: 8px 10px;
  }

  .entryList {
    margin-top: 8px;
  }

  .entryListItem {
    padding-bottom: 6px;
  }
}

.rowDragging {
  z-index: 2;
}

.entryRow {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 12px;
  border-radius: 10px;
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
  transition: border-color var(--lumiverse-transition-fast), background var(--lumiverse-transition-fast), opacity var(--lumiverse-transition-fast);
}

.entryRow:hover {
  border-color: color-mix(in srgb, var(--lumiverse-primary) 18%, transparent);
}

.entryRowActive {
  box-shadow: inset 2px 0 var(--lumiverse-primary);
  background: var(--lumiverse-fill-hover);
}

.entryRowDisabled {
  opacity: 0.6;
}

.entryRowSelected {
  border-color: var(--lumiverse-border);
  box-shadow: inset 2px 0 var(--lumiverse-primary);
  background: color-mix(in srgb, var(--lumiverse-primary) 8%, var(--lumiverse-bg));
}

.entryHeader {
  display: flex;
  align-items: flex-start;
  gap: 10px;
}

.entryLeading {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.dragHandle,
.moreBtn,
.expandBtn,
.typeBadgeBtn,
.positionBadgeBtn {
  width: 24px;
  height: 24px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--lumiverse-text-dim);
  cursor: pointer;
}

.dragHandle:hover,
.moreBtn:hover,
.expandBtn:hover,
.typeBadgeBtn:hover,
.positionBadgeBtn:hover {
  border-color: var(--lumiverse-border);
  color: var(--lumiverse-text);
}

.typeBadgeBtn {
  width: auto;
  height: auto;
  padding: 2px 8px;
  gap: 4px;
  border-color: var(--lumiverse-border);
  font-weight: 600;
  cursor: pointer;
}

.typeBadgeBtn span {
  white-space: nowrap;
}

.positionBadgeBtn {
  width: auto;
  height: auto;
  padding: 2px 8px;
  gap: 4px;
  border-color: var(--lumiverse-border);
  cursor: pointer;
}

.positionBadgeBtn span {
  white-space: nowrap;
}

.expandBtn {
  width: auto;
  padding: 0 8px;
  gap: 4px;
  border-color: var(--lumiverse-border);
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text);
  font-size: calc(10.5px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
}

.expandBtn span {
  white-space: nowrap;
}

.dragHandleDisabled {
  opacity: 0.35;
  cursor: default;
}

.entryIdentity {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.entryComment {
  font-size: calc(12.5px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.retainedEntryLabel {
  width: fit-content;
  color: var(--lumiverse-primary);
  font-size: calc(9px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.entrySearchContext {
  display: flex;
  align-items: baseline;
  gap: 6px;
  min-width: 0;
  color: var(--lumiverse-text-dim);
  font-size: calc(10.5px * var(--lumiverse-font-scale, 1));
  line-height: 1.4;
}

.entrySearchContext b {
  flex: 0 0 auto;
  color: var(--lumiverse-text-muted);
  font-size: calc(9px * var(--lumiverse-font-scale, 1));
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.entrySearchContext > span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.entrySearchMark {
  padding: 0 1px;
  border-radius: 2px;
  background: color-mix(in srgb, var(--lumiverse-primary) 32%, transparent);
  color: inherit;
}

.entrySearchMarkFuzzy {
  text-decoration: underline dotted;
  text-underline-offset: 2px;
}

.entryMeta {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: nowrap;
  min-width: 0;
  overflow-x: auto;
  scrollbar-width: none;
}

.entryMeta::-webkit-scrollbar {
  display: none;
}

.entryBadge,
.entryMetaItem {
  padding: 2px 7px;
  border-radius: 999px;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  line-height: 1.45;
  white-space: nowrap;
}

.entryBadge {
  font-weight: 600;
}

.badgeConstant {
  background: var(--lumiverse-warning-020, rgba(245, 158, 11, 0.2));
  color: var(--lumiverse-warning, #f5a623);
}

.badgeVector {
  background: var(--lumiverse-success-020, rgba(34, 197, 94, 0.2));
  color: var(--lumiverse-success, #4ade80);
}

.badgeTrigger,
.entryMetaItem {
  background: var(--lumiverse-fill-medium, var(--lumiverse-fill-strong));
  color: var(--lumiverse-text-muted);
}

.orderBadge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-variant-numeric: tabular-nums;
}

.orderInput {
  width: 7ch;
  min-width: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  font-variant-numeric: tabular-nums;
}

.orderInput:focus-visible {
  outline: 2px solid var(--lumiverse-primary);
  outline-offset: 2px;
  border-radius: 2px;
}

.orderBadge svg {
  flex-shrink: 0;
}

.tokenCell {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 4px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--lumiverse-text-dim);
  cursor: pointer;
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-variant-numeric: tabular-nums;
}

.tokenCell:hover:not(:disabled),
.tokenCell:focus-visible {
  background: var(--lumiverse-fill-medium, var(--lumiverse-fill-strong));
  color: var(--lumiverse-text-muted);
  outline: none;
}

.tokenCell:disabled {
  cursor: default;
  opacity: 0.55;
}

.tokenCell svg {
  flex-shrink: 0;
}

.entryActions {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}

.quickControls {
  display: flex;
  align-items: flex-end;
  flex-wrap: wrap;
  gap: 10px 12px;
  padding-top: 2px;
}

.quickField,
.quickFieldStepper,
.quickFieldToggle {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.quickField {
  min-width: 116px;
}

.quickFieldStepper {
  min-width: 92px;
}

.quickFieldToggle {
  min-width: 68px;
  align-items: flex-start;
}

.quickLabel {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--lumiverse-text-muted);
}

.quickSelect {
  min-height: 32px;
  padding: 6px 8px;
}

.emptyState {
  padding: 24px 12px;
  text-align: center;
  color: var(--lumiverse-text-dim);
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  font-style: italic;
}

.emptyStateActions {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 10px;
}

.emptyStateActions button {
  padding: 5px 9px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 7px;
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text);
  cursor: pointer;
  font: inherit;
  font-style: normal;
}

.emptyStateActions button:hover {
  border-color: var(--lumiverse-primary);
