            sort_dir: entrySortBy === 'custom' ? 'asc' : entrySortDir,
            folder: entryFolder,
            tag: entryTags,
            type: entryTypeFilter === 'all' ? undefined : entryTypeFilter,
          }, { signal: controller.signal }), worldBooksApi.getEntryOrganization(bookId)])
