              setBulkPosition(0)
              setBulkDepth('4')
              setPositionState({ entryIds: selectedIds })
            },
          },
          {
            key: 'activation',
            label: te('setActivation'),
            icon: <Zap size={14} />,
            onClick: () => {
              setBulkActionsMenu(null)
              setBulkActivation('trigger')
              setActivationState({ entryIds: selectedIds })
            },
          },
        ]}
        onClose={() => setBulkActionsMenu(null)}
      />

      {selectedBook && (
        <WorldBookTokenReportModal
          isOpen={showTokenReport}
          onClose={() => setShowTokenReport(false)}
          bookId={selectedBook.id}
          bookName={selectedBook.name}
        />
      )}

      {deleteState && (
        <ConfirmationModal
          isOpen={true}
          title={deleteState.title}
          message={deleteState.message}
          variant="danger"
          confirmText={tc('actions.delete')}
          onConfirm={async () => {
            setPendingAction(true)
            try {
              await handleDeleteEntries(deleteState.entryIds)
              setDeleteState(null)
            } finally {
              setPendingAction(false)
            }
          }}
          onCancel={() => !pendingAction && setDeleteState(null)}
        />
      )}

      {moveCopyState && (
        <ModalPresentation
          isOpen={true}
          onClose={() => !pendingAction && setMoveCopyState(null)}
          maxWidth="clamp(320px, 90vw, min(520px, var(--lumiverse-content-max-width, 520px)))"
          closeOnBackdrop={!pendingAction}
          closeOnEscape={!pendingAction}
          title={moveCopyState.title}
          subtitle={selectedBook ? te('moveCopyFrom', { name: selectedBook.name }) : undefined}
          footer={(
            <>
              <Button variant="ghost" onClick={() => setMoveCopyState(null)} disabled={pendingAction}>{tc('actions.cancel')}</Button>
              <Button variant="primary" onClick={() => void handleMoveOrCopy()} disabled={pendingAction || !moveTargetBookId}>
                {moveCopyState.confirmText}
              </Button>
            </>
          )}
        >
          <FormField label={te('targetWorldBook')} className={styles.dialogFormField}>
            <SearchableSelect
              value={moveTargetBookId}
              onChange={(value) => setMoveTargetBookId(value || '')}
              options={availableTargetBooks}
              placeholder={te('chooseWorldBook')}
              searchPlaceholder={t('searchWorldBooks')}
              emptyMessage={te('noOtherBooks')}
              portal
            />
          </FormField>
        </ModalPresentation>
      )}
      {dockedPagination}

      {renumberState && (
        <ModalPresentation
          isOpen={true}
          onClose={() => !pendingAction && setRenumberState(null)}
          maxWidth="clamp(320px, 90vw, min(520px, var(--lumiverse-content-max-width, 520px)))"
          closeOnBackdrop={!pendingAction}
          closeOnEscape={!pendingAction}
          title={te('renumberTitle')}
          subtitle={te('renumberHint')}
          footer={(
            <>
              <Button variant="ghost" onClick={() => setRenumberState(null)} disabled={pendingAction}>{tc('actions.cancel')}</Button>
              <Button variant="primary" onClick={() => void handleBulkRenumber()} disabled={pendingAction}>{tc('actions.apply')}</Button>
            </>
          )}
        >
          <div className={styles.dialogGrid}>
            <FormField label={te('startNumber')} className={styles.dialogFormField}>
              <TextInput
                type="number"
                value={renumberStart}
                onChange={setRenumberStart}
                placeholder={te('startNumberPlaceholder')}
              />
            </FormField>
            <FormField label={te('step')} className={styles.dialogFormField}>
              <TextInput type="number" min={1} value={renumberStep} onChange={setRenumberStep} />
            </FormField>
            <FormField label={te('direction')} className={styles.dialogFormField}>
              <Select
                value={renumberDirection}
                onChange={(value) => setRenumberDirection(value as 'asc' | 'desc')}
                options={[
                  { value: 'asc', label: te('sortAsc') },
                  { value: 'desc', label: te('sortDesc') },
                ]}
              />
            </FormField>
          </div>
        </ModalPresentation>
      )}

      {keywordState && (
        <ModalPresentation
          isOpen={true}
          onClose={() => !pendingAction && setKeywordState(null)}
          maxWidth="clamp(320px, 90vw, min(520px, var(--lumiverse-content-max-width, 520px)))"
          closeOnBackdrop={!pendingAction}
          closeOnEscape={!pendingAction}
          title={te('keywordTitle')}
          footer={(
            <>
              <Button variant="ghost" onClick={() => setKeywordState(null)} disabled={pendingAction}>{tc('actions.cancel')}</Button>
              <Button variant="primary" onClick={() => void handleBulkKeyword()} disabled={pendingAction || !keywordValue.trim()}>{tc('actions.add')}</Button>
            </>
          )}
        >
          <div className={styles.dialogGrid}>
            <FormField label={te('keyword')} className={styles.dialogFormField}>
              <TextInput
                value={keywordValue}
                onChange={setKeywordValue}
                placeholder={te('keywordPlaceholder')}
              />
            </FormField>
            <FormField label={te('keywordList')} className={styles.dialogFormField}>
              <Select
                value={keywordTarget}
                onChange={(value) => setKeywordTarget(value as 'primary' | 'secondary')}
                options={[
                  { value: 'primary', label: te('keywordPrimary') },
                  { value: 'secondary', label: te('keywordSecondary') },
                ]}
              />
            </FormField>
          </div>
        </ModalPresentation>
      )}

      {positionState && (
        <ModalPresentation
          isOpen={true}
          onClose={() => !pendingAction && setPositionState(null)}
          maxWidth="clamp(320px, 90vw, min(520px, var(--lumiverse-content-max-width, 520px)))"
          closeOnBackdrop={!pendingAction}
          closeOnEscape={!pendingAction}
          title={te('setPositionTitle')}
          footer={(
            <>
              <Button variant="ghost" onClick={() => setPositionState(null)} disabled={pendingAction}>{tc('actions.cancel')}</Button>
              <Button variant="primary" onClick={() => void handleBulkSetPosition()} disabled={pendingAction}>{tc('actions.apply')}</Button>
            </>
          )}
        >
          <div className={styles.dialogGrid}>
            <FormField label={te('position')} className={styles.dialogFormField}>
              <Select
                value={String(bulkPosition)}
                onChange={(value) => setBulkPosition(Number(value))}
                options={labels.positionOptions.map((opt) => ({
                  value: String(opt.value),
                  label: opt.label,
                }))}
              />
            </FormField>
            {bulkPosition === 4 && (
              <FormField label={te('depth')} className={styles.dialogFormField}>
                <TextInput type="number" min={0} value={bulkDepth} onChange={setBulkDepth} />
              </FormField>
            )}
          </div>
        </ModalPresentation>
      )}

      {activationState && (
        <ModalPresentation
          isOpen={true}
          onClose={() => !pendingAction && setActivationState(null)}
          maxWidth="clamp(320px, 90vw, min(520px, var(--lumiverse-content-max-width, 520px)))"
          closeOnBackdrop={!pendingAction}
          closeOnEscape={!pendingAction}
          title={te('setActivationTitle')}
          subtitle={te('setActivationHint', { count: activationState.entryIds.length })}
          footer={(
            <>
              <Button variant="ghost" onClick={() => setActivationState(null)} disabled={pendingAction}>{tc('actions.cancel')}</Button>
              <Button variant="primary" onClick={() => void handleBulkSetActivation()} disabled={pendingAction}>{tc('actions.apply')}</Button>
            </>
          )}
        >
          <FormField label={te('activationMethod')} className={styles.dialogFormField}>
            <Select
              value={bulkActivation}
              onChange={(value) => setBulkActivation(value as 'trigger' | 'constant' | 'vector')}
              options={labels.typeOptions}
            />
          </FormField>
        </ModalPresentation>
      )}
      </>}
      </div>
      {presentation === 'workspace' && !isMobile && !navigatorCollapsed && <WorldBookColumnHandle label="Resize entries column" width={navigatorWidth} defaultWidth={300} min={200} max={420} collapseBelow={140} onResize={setNavigatorWidth} onCollapse={() => { setNavigatorCollapsed(true); scheduleMicrotask(() => navigatorToggleRef.current?.focus()) }} />}
      {presentation === 'workspace' && <div className={styles.editorWorkspace} hidden={isMobile && (mobileBrowsing || !detailEntry)}>
        {!detailEntry && <p className={styles.workspaceEmpty}>Open an entry to start editing.</p>}
        {tabs.map(entry => {
          const visible = entry.id === selectedEntryId || (!isMobile && entry.id === splitEntryId)
          return <section key={entry.id} ref={entry.id === selectedEntryId ? detailViewportRef : undefined} className={styles.workspaceDetail} style={{ order: entry.id === selectedEntryId ? 0 : 1 }} hidden={!visible} role="tabpanel" id={`entry-panel-${entry.id}`} aria-labelledby={!isMobile ? `entry-tab-${entry.id}` : undefined} aria-label="Entry detail">
            <header className={styles.detailHeader} hidden={isMobile}>
              {!isMobile && entry.id === selectedEntryId && <button ref={detailBackRef} type="button" className={styles.toolbarBtn} onClick={backToEntries}>‹ Entries</button>}
              <strong>{entry.comment || '(unnamed)'}</strong>
              <button type="button" className={styles.moreBtn} aria-label="Entry detail actions" onClick={event => { const rect = event.currentTarget.getBoundingClientRect(); setContextMenu({ entryId: entry.id, position: { x: rect.right, y: rect.bottom } }) }}><MoreVertical size={14} /></button>
            </header>
            <WorldBookEntryEditor entry={entry} density={editorDensity} onUpdate={debouncedUpdateEntry} onImmediateUpdate={updateEntry} conflict={entryConflicts[entry.id]} onRetryConflict={() => retryConflict(entry.id)} onUseServerConflict={() => acceptServerConflict(entry.id)} />
          </section>
        })}
      </div>}
      </div>
    </div>
  )
}

sources.src/components/shared/WorldBookEntryEdit:
/* ── Entry editor ── */
.entryEditor {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 14px;
  margin-top: 0;
  --world-book-detail-bg: color-mix(in srgb, var(--lumiverse-bg-deep, var(--lumiverse-bg)) 65%, transparent);
  container-type: inline-size;
  container-name: wbEntryEditor;
  background: var(--lumiverse-fill-subtle);
  border: 1px solid var(--lumiverse-border);
  border-radius: 10px;
}

.compactEntryEditor {
  gap: 8px;
  padding: 10px;
  flex: 1 1 auto;
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  container-type: inline-size;
  container-name: wbEntryEditor wbEntryEditorCompact;
}

/* WebKit omits trailing padding from this contained flex scroller's scroll
   range. A non-shrinking spacer keeps the final fields reachable instead. */
.compactEntryEditor::after {
  content: '';
  flex: 0 0 var(--worldbook-keyboard-clearance, 0px);
  margin-top: -8px; /* cancel the final flex gap when no keyboard is present */
}

.compactEntryEditor.parentScrollEditor {
  flex: 0 0 auto;
  overflow: visible;
  overscroll-behavior: auto;
}

.compactEntryEditor.parentScrollEditor .identityContentSection,
.compactEntryEditor.parentScrollEditor .contentField {
  flex: 0 0 auto;
}

.compactEntryEditor .entryFieldGroup {
  gap: 6px;
}

.compactEntryEditor .entryFieldRow {
  gap: 6px;
}

.compactEntryEditor .entryInput,
.compactEntryEditor .entrySelect,
.compactEntryEditor .entryTextarea,
.compactEntryEditor .readOnlyValue {
  min-width: 0;
  max-width: 100%;
  box-sizing: border-box;
}

.identityContentSection {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
}

.entryEditor:not(.compactEntryEditor) .identityContentSection {
  gap: 0;
}

.entryEditor:not(.compactEntryEditor) .identityContentSection > .sectionHeading {
  margin-bottom: 12px;
}

.entryEditor:not(.compactEntryEditor) .identityFields + .contentField {
  margin-top: 8px;
}

.identityFields {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  min-width: 0;
}

.contentField {
  min-width: 0;
}

.compactEntryEditor .identityContentSection {
  flex: 1 1 auto;
  min-height: 0;
}

.compactEntryEditor .identityFields {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  flex: 0 0 auto;
}

.compactEntryEditor .contentField {
  flex: 1 1 240px;
  min-height: 180px;
}

.compactEntryEditor .contentField > div:not(.fieldLabelRow) {
  display: flex;
  flex: 1 1 auto;
  min-height: 0;
}

.compactEntryEditor .contentField .entryTextarea {
  flex: 1 1 auto;
  width: 100%;
  height: 100%;
  min-height: 180px;
  overflow: auto;
}

.sectionHeading {
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text-muted);
  padding-bottom: 6px;
  border-bottom: 1px solid var(--lumiverse-border);
}

.entryFieldGroup {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.entryFieldRow {
  display: flex;
  gap: 8px;
  align-items: flex-start;
  flex-wrap: wrap;
}

.entryField {
  display: flex;
  flex-direction: column;
  gap: 3px;
  flex: 1;
  min-width: 0;
}

.entryFieldSmall {
  flex: 1 1 80px;
}

.fieldLabel {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 500;
  color: var(--lumiverse-text-muted);
}

.fieldLabelRow {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.disclosureSection {
  min-width: 0;
}

.disclosurePanel {
  margin-top: 6px;
}
.fieldHint {
  color: var(--lumiverse-text-muted);
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
  margin: 4px 0 0;
}

.entryInput {
  background: var(--lumiverse-bg);
  border: 1px solid var(--lumiverse-border);
  border-radius: 6px;
  padding: 5px 8px;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text);
  outline: none;
  transition: border-color var(--lumiverse-transition-fast);
}

.entryInput:focus {
  border-color: var(--lumiverse-primary);
}


.entryTextarea {
  background: var(--lumiverse-bg);
  border: 1px solid var(--lumiverse-border);
  border-radius: 6px;
  padding: 6px 10px;
  font-size: calc(12.5px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text);
  outline: none;
  font-family: inherit;
  resize: vertical;
  min-height: 60px;
  transition: border-color var(--lumiverse-transition-fast);
}

.entryTextarea:focus {
  border-color: var(--lumiverse-primary);
}

.entrySelect {
  background: var(--lumiverse-bg);
  border: 1px solid var(--lumiverse-border);
  border-radius: 6px;
  padding: 5px 8px;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text);
  outline: none;
  cursor: pointer;
}

.toggleRow {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 10px;
  align-items: start;
}

.vectorStatusRow {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.vectorStatusBadge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 22px;
  padding: 0 10px;
  border-radius: 999px;
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  letter-spacing: 0.02em;
}

.vectorStatusNotEnabled {
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text-muted);
}

.vectorStatusPending {
  background: var(--lumiverse-warning-015);
  color: var(--lumiverse-warning);
}

.vectorStatusIndexed {
  background: var(--lumiverse-success-015);
  color: var(--lumiverse-success);
}

.vectorStatusError {
  background: var(--lumiverse-danger-015);
  color: var(--lumiverse-danger);
}

.vectorStatusText {
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted);
  line-height: 1.45;
  flex: 1;
  min-width: 180px;
}

.inactiveNote {
  padding: 8px 10px;
  border: 1px solid var(--lumiverse-primary-020);
  border-radius: 6px;
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text-muted);
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
  line-height: 1.45;
}

/* ── Collapsible group ── */
.groupToggle {
  display: flex;
  align-items: center;
  gap: 5px;
  width: 100%;
  min-width: 0;
  padding: 0;
  background: none;
  border: none;
  color: var(--lumiverse-text-muted);
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  text-transform: none;
  letter-spacing: normal;
  cursor: pointer;
  transition: color var(--lumiverse-transition-fast);
}

.groupToggleLabel {
  flex: 0 1 auto;
  min-width: 0;
  overflow-wrap: anywhere;
  text-align: left;
}

.groupToggleSummary {
  min-width: 0;
  overflow: hidden;
  color: var(--lumiverse-text-dim);
  font-size: calc(10.5px * var(--lumiverse-font-scale, 1));
  font-weight: 400;
  text-align: left;
  text-overflow: ellipsis;
  text-transform: none;
  white-space: nowrap;
}

.groupToggle:hover {
  color: var(--lumiverse-text);
}

.groupToggleIcon {
  transition: transform var(--lumiverse-transition-fast);
}

.groupToggleOpen {
  transform: rotate(90deg);
}

.vectorStatusTrigger {
  margin-left: auto;
  flex: 0 0 auto;
  max-width: 45%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

@container wbEntryEditorCompact (max-width: 440px) {
  .compactEntryEditor .identityFields {
    grid-template-columns: minmax(0, 1fr);
  }

  .compactEntryEditor .injectionRow {
    display: grid;
    grid-template-columns: minmax(0, 1.3fr) minmax(0, 1fr) 64px;
  }

  .compactEntryEditor .activationRow {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .compactEntryEditor .activationRow > .entryField:last-child {
    grid-column: 1 / -1;
  }

  .compactEntryEditor .injectionRow > .entryField,
  .compactEntryEditor .activationRow > .entryField {
    min-width: 0;
  }

  .compactEntryEditor .groupToggle {
    align-items: flex-start;
  }

  .compactEntryEditor .groupToggleSummary {
    white-space: normal;
  }
}

/* ── Read-only value ── */
.readOnlyValue {
  font-size: calc(11.5px * var(--lumiverse-font-scale, 1));
  font-family: 'SF Mono', 'Fira Code', monospace;
  color: var(--lumiverse-text-dim);
  padding: 5px 8px;
  background: var(--lumiverse-bg);
  border: 1px solid var(--lumiverse-border);
  border-radius: 6px;
  user-select: all;
}

.contentField .entryTextarea { min-height: 140px; }

.matchingRules { display: flex; flex-direction: column; gap: 6px; }
.entryFieldRow > .entryField { min-width: 80px; }
.entryFieldRow > .entryField:has(.entrySelect) { flex-basis: 120px; }
.readOnlyValue { overflow-wrap: anywhere; }

.timingRow { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); }
.timingRow > .entryField { min-width: 0; }
@container wbEntryEditor (max-width: 480px) { .timingRow { grid-template-columns: repeat(2, minmax(0, 1fr)); } }

.groupRow { display: grid; grid-template-columns: minmax(0, 1fr) 90px; }
.groupRow > .entryField { min-width: 0; }

.toggleRow > label { min-width: 0; font-size: calc(12px * var(--lumiverse-font-scale, 1)); }
.toggleRow > label > span { min-width: 0; overflow-wrap: anywhere; }

.disclosureSection, .identityContentSection { padding: 8px; border: 1px solid var(--lumiverse-border); border-radius: 7px; background: var(--world-book-detail-bg); }
.disclosureSection > .sectionHeading { display: block; margin-bottom: 8px; }
.metadataRow { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); }
.metadataRow > .entryField { min-width: 0; }
.metadataRow .entryInput { width: 100%; height: 30px; box-sizing: border-box; }

.matchingRules .toggleRow { display: flex; flex-wrap: wrap; gap: 8px 18px; }
@container wbEntryEditor (max-width: 440px) { .matchingRules .toggleRow { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; } }

import { useState, useEffect, useRef, useCallback, useId, type ReactNode } from 'react'
import { useTranslation } from 'react-i18next'
import { ChevronRight } from 'lucide-react'
import { Toggle } from '@/components/shared/Toggle'
import { ExpandableTextarea } from '@/components/shared/ExpandedTextEditor'
import TokenCountButton from '@/components/shared/TokenCountButton'
import clsx from 'clsx'
import type { WorldBookEntry } from '@/types/api'
import { getVectorIndexStatusDescription, getVectorIndexStatusLabel } from '@/lib/worldBookVectorization'
import { useWorldBookEntryLabels } from '@/lib/i18n/worldBookEntryLabels'
import { useLoomOptionLabels } from '@/lib/i18n/loomOptionLabels'
import NumberStepper from './NumberStepper'
import EntryOrganizationFields from './EntryOrganizationFields'
import styles from './WorldBookEntryEditor.module.css'

export interface EntryEditorConflictState {
  kind: 'conflict' | 'malformed-precondition'
  current?: WorldBookEntry | null
  message?: string
}

export interface EntryEditorProps {
  density?: 'default' | 'compact'
  scrollMode?: 'self' | 'parent'
  entry: WorldBookEntry
  onUpdate: (id: string, updates: Record<string, any>) => void
  onImmediateUpdate: (id: string, updates: Record<string, any>) => void
  conflict?: EntryEditorConflictState | null
  onRetryConflict?: () => void
  onUseServerConflict?: () => void
}

interface DisclosureSectionProps {
  id: string
  label: string
  summary?: string
  open: boolean
  onToggle: () => void
  trailing?: ReactNode
  collapsible?: boolean
  children: ReactNode
}

function DisclosureSection({ id, label, summary, open, onToggle, trailing, collapsible = true, children }: DisclosureSectionProps) {
  const triggerRef = useRef<HTMLButtonElement>(null)
  const panelRef = useRef<HTMLDivElement>(null)
  const triggerId = `${id}-trigger`

  const handleToggle = () => {
    const restoreFocus = open && panelRef.current?.contains(document.activeElement)
    onToggle()
    if (restoreFocus) triggerRef.current?.focus()
  }

  if (!collapsible) {
    return (
      <section className={styles.disclosureSection}>
        <span className={styles.sectionHeading}>{label}</span>
        {children}
      </section>
    )
  }

  return (
    <section className={styles.disclosureSection} data-entry-disclosure={id}>
      <button
        ref={triggerRef}
        id={triggerId}
        type="button"
        className={styles.groupToggle}
        aria-expanded={open}
        aria-controls={id}
        onClick={handleToggle}
      >
        <ChevronRight
          size={12}
          className={clsx(styles.groupToggleIcon, open && styles.groupToggleOpen)}
        />
        <span className={styles.groupToggleLabel}>{label}</span>
        {summary && <span className={styles.groupToggleSummary}>{summary}</span>}
        {trailing}
      </button>
      <div
        ref={panelRef}
        id={id}
        className={styles.disclosurePanel}
        role="group"
        aria-labelledby={triggerId}
        hidden={!open}
      >
        {children}
      </div>
    </section>
  )
}

export default function WorldBookEntryEditor({ entry, density = 'default', scrollMode = 'self', onUpdate, onImmediateUpdate, conflict, onRetryConflict, onUseServerConflict }: EntryEditorProps) {
  const { t } = useTranslation('panels', { keyPrefix: 'worldBookPanel.entryEditor' })
  const { positionOptions, roleOptions, selectiveLogicOptions } = useWorldBookEntryLabels()
  const { addableMarkers, markerLabel, markerSectionLabel } = useLoomOptionLabels()

  const [injectionOpen, setInjectionOpen] = useState(density !== 'compact')
  const [activationOpen, setActivationOpen] = useState(density !== 'compact')
  const [groupOpen, setGroupOpen] = useState(false)
  const [timingOpen, setTimingOpen] = useState(false)
  const [recursionOpen, setRecursionOpen] = useState(false)
  const [metadataOpen, setMetadataOpen] = useState(false)
  const recursionInvalidated = entry.vectorized
  const vectorStatusClass =
    entry.vector_index_status === 'indexed'
      ? styles.vectorStatusIndexed
      : entry.vector_index_status === 'error'
        ? styles.vectorStatusError
        : entry.vector_index_status === 'pending'
          ? styles.vectorStatusPending
          : styles.vectorStatusNotEnabled

  // Local state for text fields to prevent prop-sync from overwriting in-progress edits
  const [content, setContent] = useState(entry.content)
  const [comment, setComment] = useState(entry.comment)
  const [outletName, setOutletName] = useState(entry.outlet_name || '')
  const [wiMarker, setWiMarker] = useState(entry.wi_marker || '')
  const [wiMarkerSide, setWiMarkerSide] = useState(entry.wi_marker_side || 'after')
  const [primaryKeys, setPrimaryKeys] = useState(entry.key.join(', '))
  const [secondaryKeys, setSecondaryKeys] = useState(entry.keysecondary.join(', '))
  const [groupName, setGroupName] = useState(entry.group_name)
  const [automationId, setAutomationId] = useState(entry.automation_id || '')
  const disclosureId = useId()
  const lastSyncedId = useRef<string | null>(null)
  const dirtyFields = useRef<Set<string>>(new Set())

  const markDirty = useCallback((field: string) => {
    dirtyFields.current.add(field)
  }, [])

  const applyServerEntry = useCallback((serverEntry: WorldBookEntry) => {
    dirtyFields.current.clear()
    setContent(serverEntry.content)
    setComment(serverEntry.comment)
    setOutletName(serverEntry.outlet_name || '')
    setWiMarker(serverEntry.wi_marker || '')
    setWiMarkerSide(serverEntry.wi_marker_side || 'after')
    setPrimaryKeys(serverEntry.key.join(', '))
    setSecondaryKeys(serverEntry.keysecondary.join(', '))
    setGroupName(serverEntry.group_name)
    setAutomationId(serverEntry.automation_id || '')
  }, [])

  const handleUseServerConflict = useCallback(() => {
    if (conflict?.current) applyServerEntry(conflict.current)
    onUseServerConflict?.()
  }, [applyServerEntry, conflict, onUseServerConflict])

  useEffect(() => {
    if (lastSyncedId.current !== entry.id) {
      lastSyncedId.current = entry.id
      dirtyFields.current.clear()
      setContent(entry.content)
      setComment(entry.comment)
      setOutletName(entry.outlet_name || '')
      setWiMarker(entry.wi_marker || '')
      setWiMarkerSide(entry.wi_marker_side || 'after')
      setPrimaryKeys(entry.key.join(', '))
      setSecondaryKeys(entry.keysecondary.join(', '))
      setGroupName(entry.group_name)
      setAutomationId(entry.automation_id || '')
      return
    }
    if (!dirtyFields.current.has('content')) setContent(entry.content)
    if (!dirtyFields.current.has('comment')) setComment(entry.comment)
    if (!dirtyFields.current.has('outlet_name')) setOutletName(entry.outlet_name || '')
    if (!dirtyFields.current.has('wi_marker')) setWiMarker(entry.wi_marker || '')
    if (!dirtyFields.current.has('wi_marker_side')) setWiMarkerSide(entry.wi_marker_side || 'after')
    if (!dirtyFields.current.has('key')) setPrimaryKeys(entry.key.join(', '))
    if (!dirtyFields.current.has('keysecondary')) setSecondaryKeys(entry.keysecondary.join(', '))
    if (!dirtyFields.current.has('group_name')) setGroupName(entry.group_name)
    if (!dirtyFields.current.has('automation_id')) setAutomationId(entry.automation_id || '')
  }, [entry])

  const handleContentChange = useCallback(
    (v: string) => {
      markDirty('content')
      setContent(v)
      onUpdate(entry.id, { content: v })
    },
    [entry.id, markDirty, onUpdate]
  )

  const handleCommentChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      markDirty('comment')
      setComment(e.target.value)
      onUpdate(entry.id, { comment: e.target.value })
    },
    [entry.id, markDirty, onUpdate]
  )

  const handleOutletNameChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const nextValue = e.target.value
      markDirty('outlet_name')
      setOutletName(nextValue)
      onUpdate(entry.id, { outlet_name: nextValue || null })
    },
    [entry.id, markDirty, onUpdate]
  )
  const handleWiMarkerChange = useCallback(
    (e: React.ChangeEvent<HTMLSelectElement>) => {
      const value = e.target.value
      markDirty('wi_marker')
      setWiMarker(value)
      onImmediateUpdate(entry.id, { wi_marker: value || null })
    },
    [entry.id, markDirty, onImmediateUpdate]
  )

  const handleWiMarkerSideChange = useCallback(
    (e: React.ChangeEvent<HTMLSelectElement>) => {
      const value = e.target.value as 'before' | 'after'
      markDirty('wi_marker_side')
      setWiMarkerSide(value)
      onImmediateUpdate(entry.id, { wi_marker_side: value })
    },
    [entry.id, markDirty, onImmediateUpdate]
  )

  const handlePrimaryKeysChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      markDirty('key')
      setPrimaryKeys(e.target.value)
      onUpdate(entry.id, { key: e.target.value.split(',').map((k) => k.trim()).filter(Boolean) })
    },
    [entry.id, markDirty, onUpdate]
  )

  const handleSecondaryKeysChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      markDirty('keysecondary')
      setSecondaryKeys(e.target.value)
      onUpdate(entry.id, { keysecondary: e.target.value.split(',').map((k) => k.trim()).filter(Boolean) })
    },
    [entry.id, markDirty, onUpdate]
  )
  const markerGroups = (() => {
    const groups: Array<{ section: string; items: string[] }> = []
    let current: { section: string; items: string[] } | null = null
    for (const item of addableMarkers) {
      if (typeof item === 'object' && 'section' in item) {
        current = { section: item.section, items: [] }
        groups.push(current)
      } else if (current) {
        current.items.push(item)
      }
    }
    return groups
  })()
  const positionLabel = positionOptions.find((option) => option.value === entry.position)?.label ?? String(entry.position)
  const roleLabel = roleOptions.find((option) => option.value === (entry.role || 'system'))?.label ?? (entry.role || 'system')
  const injectionSummary = [
    positionLabel,
    entry.position === 4 ? `${t('fields.depth')}: ${entry.depth}` : null,
    entry.position === 7 && wiMarker ? `${t('markerTarget')}: ${markerLabel(wiMarker)}` : null,
    entry.position === 7 && wiMarker
      ? `${t('markerSideLabel')}: ${wiMarkerSide === 'before' ? t('markerSideBefore') : t('markerSideAfter')}`
      : null,
    roleLabel,
    `${t('fields.order')}: ${entry.order_value}`,
  ].filter((value): value is string => Boolean(value)).join(', ')
  const activationSummary = [
    entry.selective && t('toggles.selective'),
    entry.constant && t('toggles.constant'),
    entry.disabled && t('toggles.disabled'),
    entry.case_sensitive && t('toggles.caseSensitive'),
    entry.match_whole_words && t('toggles.matchWholeWords'),
    entry.use_regex && t('toggles.useRegex'),
    entry.use_probability && t('toggles.useProbability'),
    entry.vectorized && t('toggles.vectorized'),
  ].filter((value): value is string => Boolean(value)).join(', ')

  return (
    <div
      className={clsx(styles.entryEditor, density === 'compact' && styles.compactEntryEditor, scrollMode === 'parent' && styles.parentScrollEditor)}
      data-world-book-entry-editor="true"
      data-density={density}
      data-editor-scroll-owner={density === 'compact' && scrollMode === 'self' ? 'true' : undefined}
    >
      <span data-spindle-mount="world_book_entry_editor" data-spindle-scope={`world-book-entry:${entry.id}:editor`} style={{ display: 'contents' }} />
      {conflict && (
        <div className={styles.entryFieldGroup} role="alert" data-entry-conflict={conflict.kind}>
          <strong>{conflict.kind === 'conflict' ? 'Entry changed on the server' : 'Invalid revision precondition'}</strong>
          {conflict.message && <span>{conflict.message}</span>}
          {conflict.kind === 'conflict' && (
            <div>
              <button type="button" onClick={onRetryConflict}>Retry with server revision</button>
              <button type="button" onClick={handleUseServerConflict}>Use server version</button>
            </div>
          )}
        </div>
      )}
      <EntryOrganizationFields key={entry.id} bookId={entry.world_book_id} folder={entry.folder ?? ''} tags={entry.tags ?? []} onChange={updates => onImmediateUpdate(entry.id, updates)} />
      {/* Identity & Content */}
      <section className={styles.identityContentSection} data-world-book-identity-content="true">
        <span className={styles.sectionHeading}>{t('sections.identity')}</span>
        <div className={styles.identityFields}>
          <div className={styles.entryField}>
            <label className={styles.fieldLabel}>{t('fields.comment')}</label>
            <input
              type="text"
              className={styles.entryInput}
              value={comment}
              onChange={handleCommentChange}
            />
          </div>
          <div className={styles.entryField}>
            <label className={styles.fieldLabel}>{t('fields.outletName')}</label>
            <input
              type="text"
              className={styles.entryInput}
              value={outletName}
              onChange={handleOutletNameChange}
              placeholder={t('outletPlaceholder')}
            />
          </div>
          <div className={styles.entryField}>
            <label className={styles.fieldLabel}>{t('fields.primaryKeys')}</label>
            <input
              type="text"
              className={styles.entryInput}
              value={primaryKeys}
              onChange={handlePrimaryKeysChange}
            />
          </div>
          <div className={styles.entryField}>
            <label className={styles.fieldLabel}>{t('fields.secondaryKeys')}</label>
            <input
              type="text"
              className={styles.entryInput}
              value={secondaryKeys}
              onChange={handleSecondaryKeysChange}
            />
          </div>
        </div>
        <div className={clsx(styles.entryField, styles.contentField)} data-content-flex-region="true">
          <div className={styles.fieldLabelRow}>
            <label className={styles.fieldLabel}>{t('fields.content')}</label>
            <TokenCountButton text={content} entryId={entry.id} extensions={entry.extensions} />
          </div>
          <ExpandableTextarea
            className={styles.entryTextarea}
            value={content}
            onChange={handleContentChange}
            title={comment || t('entryContentTitle')}
            rows={4}
          />
        </div>
      </section>

      {/* Injection */}
      <DisclosureSection
        id={`${disclosureId}-injection`}
        label={t('sections.injection')}
        summary={injectionSummary}
        open={injectionOpen}
        onToggle={() => setInjectionOpen((open) => !open)}
        collapsible={density === 'compact'}
      >
        <div className={styles.entryFieldGroup}>
        <div className={clsx(styles.entryFieldRow, styles.injectionRow)}>
          <div className={styles.entryField}>
            <label className={styles.fieldLabel}>{t('fields.position')}</label>
            <select
              className={styles.entrySelect}
              value={entry.position}
              onChange={(e) => onImmediateUpdate(entry.id, { position: Number(e.target.value) })}
            >
              {positionOptions.map((opt) => (
                <option key={opt.value} value={opt.value}>
                  {opt.label}
                </option>
              ))}
            </select>
          </div>
          {entry.position === 4 && (
            <div className={clsx(styles.entryField, styles.entryFieldSmall)}>
              <label className={styles.fieldLabel}>{t('fields.depth')}</label>
              <NumberStepper
                value={entry.depth}
                min={0}
                onChange={(v) => onImmediateUpdate(entry.id, { depth: v ?? 0 })}
              />
            </div>
          )}
          <div className={styles.entryField}>
            <label className={styles.fieldLabel}>{t('fields.role')}</label>
            <select
              className={styles.entrySelect}
              value={entry.role || 'system'}
              onChange={(e) => onImmediateUpdate(entry.id, { role: e.target.value })}
            >
              {roleOptions.map((opt) => (
                <option key={opt.value} value={opt.value}>
                  {opt.label}
                </option>
              ))}
            </select>
          </div>
          <div className={clsx(styles.entryField, styles.entryFieldSmall)}>
            <label className={styles.fieldLabel}>{t('fields.order')}</label>
            <NumberStepper
              value={entry.order_value}
              onChange={(v) => onImmediateUpdate(entry.id, { order_value: v ?? 0 })}
            />
          </div>
        </div>
        {entry.position === 8 && !(entry.outlet_name || '').trim() && (
          <p className={styles.fieldHint}>{t('outletOnlyHint')}</p>
        )}
        {entry.position === 7 && (
          <div className={styles.entryFieldRow}>
            <div className={styles.entryField}>
              <label className={styles.fieldLabel}>{t('markerTarget')}</label>
              <select
                className={styles.entrySelect}
                value={wiMarker}
                onChange={handleWiMarkerChange}
              >
                <option value="">{t('markerTargetNone')}</option>
                {markerGroups.map((group) => (
                  <optgroup key={group.section} label={markerSectionLabel(group.section)}>
                    {group.items.map((marker) => (
                      <option key={marker} value={marker}>
                        {markerLabel(marker)}
                      </option>
                    ))}
                  </optgroup>
                ))}
              </select>
            </div>
            {wiMarker && (
              <div className={styles.entryField}>
                <label className={styles.fieldLabel}>{t('markerSideLabel')}</label>
                <select
                  className={styles.entrySelect}
                  value={wiMarkerSide}
                  onChange={handleWiMarkerSideChange}
                >
                  <option value="before">{t('markerSideBefore')}</option>
                  <option value="after">{t('markerSideAfter')}</option>
                </select>
              </div>
            )}
          </div>
        )}
        </div>
      </DisclosureSection>

      {/* Activation */}
      <DisclosureSection
        id={`${disclosureId}-activation`}
        label={t('sections.activation')}
        summary={activationSummary}
        open={activationOpen}
        onToggle={() => setActivationOpen((open) => !open)}
        collapsible={density === 'compact'}
        trailing={entry.vectorized &&
          <span className={clsx(styles.vectorStatusBadge, styles.vectorStatusTrigger, vectorStatusClass)}>
            {getVectorIndexStatusLabel(entry.vector_index_status)}
          </span>
        }
      >
        <div className={styles.entryFieldGroup}>
        <div className={clsx(styles.entryFieldRow, styles.activationRow)}>
          <label className={styles.entryField}>
            <span className={styles.fieldLabel}>{t('fields.activationMethod', { defaultValue: 'Activation method' })}</span>
            <select className={styles.entrySelect} aria-label="Activation method"
              value={entry.constant && entry.vectorized ? 'combined' : entry.constant ? 'constant' : entry.vectorized ? 'vector' : 'trigger'}
              onChange={(event) => onImmediateUpdate(entry.id, {
                constant: event.target.value === 'constant' || event.target.value === 'combined',
                vectorized: event.target.value === 'vector' || event.target.value === 'combined',
              })}>
              <option value="trigger">{t('activation.trigger', { defaultValue: 'Key match' })}</option>
              <option value="constant">{t('toggles.constant')}</option>
              <option value="vector">{t('toggles.vectorized')}</option>
              {entry.constant && entry.vectorized && <option value="combined">{t('activation.combined', { defaultValue: 'Constant + vector' })}</option>}
            </select>
          </label>
          <label className={styles.entryField}>
            <span className={styles.fieldLabel}>{t('fields.status', { defaultValue: 'Status' })}</span>
            <select className={styles.entrySelect} aria-label="Entry status" value={entry.disabled ? 'disabled' : 'enabled'}
              onChange={(event) => onImmediateUpdate(entry.id, { disabled: event.target.value === 'disabled' })}>
              <option value="enabled">{t('activation.enabled', { defaultValue: 'Enabled' })}</option>
              <option value="disabled">{t('toggles.disabled')}</option>
            </select>
          </label>
          <label className={styles.entryField}>
            <span className={styles.fieldLabel}>{t('fields.probability')}</span>
            <select className={styles.entrySelect} aria-label="Probability mode" value={entry.use_probability ? 'chance' : 'always'}
              onChange={(event) => onImmediateUpdate(entry.id, { use_probability: event.target.value === 'chance' })}>
              <option value="always">{t('activation.always', { defaultValue: 'Always' })}</option>
              <option value="chance">{t('activation.chance', { defaultValue: 'Use chance' })}</option>
            </select>
          </label>
        </div>
        <div className={styles.matchingRules}>
          <span className={styles.fieldLabel}>{t('fields.matchingRules', { defaultValue: 'Matching rules' })}</span>
          <div className={styles.toggleRow}>
            <Toggle.Checkbox checked={entry.selective}
              onChange={() => onImmediateUpdate(entry.id, { selective: !entry.selective })}
              label={t('toggles.selective')} />
            <Toggle.Checkbox checked={entry.case_sensitive}
              onChange={() => onImmediateUpdate(entry.id, { case_sensitive: !entry.case_sensitive })}
              label={t('toggles.caseSensitive')} />
            <Toggle.Checkbox checked={entry.match_whole_words}
              onChange={() => onImmediateUpdate(entry.id, { match_whole_words: !entry.match_whole_words })}
              label={t('toggles.matchWholeWords')} />
            <Toggle.Checkbox checked={entry.use_regex}
              onChange={() => onImmediateUpdate(entry.id, { use_regex: !entry.use_regex })}
              label={t('toggles.useRegex')} />
          </div>
        </div>
        {(entry.vectorized || entry.vector_index_status === 'error' || entry.vector_index_status === 'pending') && <div className={styles.vectorStatusRow}>
          <span className={clsx(styles.vectorStatusBadge, vectorStatusClass)}>
            {getVectorIndexStatusLabel(entry.vector_index_status)}
          </span>
          <span className={styles.vectorStatusText}>
            {getVectorIndexStatusDescription(entry)}
          </span>
        </div>}
        <div className={styles.entryFieldRow}>
          {entry.use_probability && <div className={clsx(styles.entryField, styles.entryFieldSmall)}>
            <label className={styles.fieldLabel}>{t('fields.probability')}</label>
            <NumberStepper
              value={entry.probability}
              min={0}
              max={100}
              onChange={(v) => onImmediateUpdate(entry.id, { probability: v ?? 0 })}
            />
          </div>}
          <div className={clsx(styles.entryField, styles.entryFieldSmall)}>
            <label className={styles.fieldLabel}>{t('fields.scanDepth')}</label>
            <NumberStepper
              value={entry.scan_depth}
              min={0}
              allowEmpty
              onChange={(v) => onImmediateUpdate(entry.id, { scan_depth: v })}
            />
          </div>
          {entry.selective && (
            <div className={styles.entryField}>
              <label className={styles.fieldLabel}>{t('fields.selectiveLogic')}</label>
              <select
                className={styles.entrySelect}
                value={entry.selective_logic}
                onChange={(e) => onImmediateUpdate(entry.id, { selective_logic: Number(e.target.value) })}
              >
                {selectiveLogicOptions.map((opt) => (
                  <option key={opt.value} value={opt.value}>
                    {opt.label}
                  </option>
                ))}
              </select>
            </div>
          )}
        </div>
        </div>
      </DisclosureSection>

      {/* Group (collapsible) */}
      <DisclosureSection
        id={`${disclosureId}-group`}
        label={t('sections.group')}
        open={groupOpen}
        onToggle={() => setGroupOpen((open) => !open)}
      >
        <div className={styles.entryFieldGroup}>
          <div className={clsx(styles.entryFieldRow, styles.groupRow)}>
            <div className={styles.entryField}>
              <label className={styles.fieldLabel}>{t('fields.groupName')}</label>
              <input
                type="text"
                className={styles.entryInput}
                value={groupName}
                onChange={(e) => {
                  markDirty('group_name')
                  setGroupName(e.target.value)
                  onUpdate(entry.id, { group_name: e.target.value })
                }}
              />
            </div>
            <div className={clsx(styles.entryField, styles.entryFieldSmall)}>
              <label className={styles.fieldLabel}>{t('fields.weight')}</label>
              <NumberStepper
                value={entry.group_weight}
                onChange={(v) => onImmediateUpdate(entry.id, { group_weight: v ?? 0 })}
              />
            </div>
          </div>
          <Toggle.Checkbox
            checked={entry.group_override}
            onChange={() => onImmediateUpdate(entry.id, { group_override: !entry.group_override })}
            label={t('toggles.groupOverride')}
          />
        </div>
      </DisclosureSection>

      {/* Timing (collapsible) */}
      <DisclosureSection
        id={`${disclosureId}-timing`}
        label={t('sections.timing')}
        open={timingOpen}
        onToggle={() => setTimingOpen((open) => !open)}
      >
        <div className={styles.entryFieldGroup}>
          <div className={clsx(styles.entryFieldRow, styles.timingRow)}>
            <div className={clsx(styles.entryField, styles.entryFieldSmall)}>
              <label className={styles.fieldLabel}>{t('fields.priority')}</label>
              <NumberStepper
                value={entry.priority}
                onChange={(v) => onImmediateUpdate(entry.id, { priority: v ?? 0 })}
              />
            </div>
            <div className={clsx(styles.entryField, styles.entryFieldSmall)}>
              <label className={styles.fieldLabel}>{t('fields.sticky')}</label>
              <NumberStepper
                value={entry.sticky}
                min={0}
                onChange={(v) => onImmediateUpdate(entry.id, { sticky: v ?? 0 })}
              />
            </div>
            <div className={clsx(styles.entryField, styles.entryFieldSmall)}>
              <label className={styles.fieldLabel}>{t('fields.cooldown')}</label>
              <NumberStepper
                value={entry.cooldown}
                min={0}
                onChange={(v) => onImmediateUpdate(entry.id, { cooldown: v ?? 0 })}
              />
            </div>
            <div className={clsx(styles.entryField, styles.entryFieldSmall)}>
              <label className={styles.fieldLabel}>{t('fields.delay')}</label>
              <NumberStepper
                value={entry.delay}
                min={0}
                onChange={(v) => onImmediateUpdate(entry.id, { delay: v ?? 0 })}
              />
            </div>
          </div>
        </div>
      </DisclosureSection>

      {/* Recursion (collapsible) */}
      <DisclosureSection
        id={`${disclosureId}-recursion`}
        label={`${t('sections.recursion')}${recursionInvalidated ? t('sections.recursionInactiveSuffix') : ''}`}
        open={recursionOpen}
        onToggle={() => setRecursionOpen((open) => !open)}
      >
        <div className={styles.entryFieldGroup}>
          {recursionInvalidated && (
            <div className={styles.inactiveNote}>
              {t('recursionInactiveNote')}
            </div>
          )}
          <div className={styles.toggleRow}>
            <Toggle.Checkbox
              checked={entry.prevent_recursion}
              onChange={() => onImmediateUpdate(entry.id, { prevent_recursion: !entry.prevent_recursion })}
              label={t('toggles.preventRecursion')}
              disabled={recursionInvalidated}
            />
            <Toggle.Checkbox
              checked={entry.exclude_recursion}
              onChange={() => onImmediateUpdate(entry.id, { exclude_recursion: !entry.exclude_recursion })}
              label={t('toggles.excludeRecursion')}
              disabled={recursionInvalidated}
            />
            <Toggle.Checkbox
              checked={entry.delay_until_recursion}
              onChange={() => onImmediateUpdate(entry.id, { delay_until_recursion: !entry.delay_until_recursion })}
              label={t('toggles.delayUntilRecursion')}
              disabled={recursionInvalidated}
            />
          </div>
        </div>
      </DisclosureSection>

      {/* Metadata (collapsible) */}
      <DisclosureSection
        id={`${disclosureId}-metadata`}
        label={t('sections.metadata')}
        open={metadataOpen}
        onToggle={() => setMetadataOpen((open) => !open)}
      >
        <div className={clsx(styles.entryFieldRow, styles.metadataRow)}>
          <div className={styles.entryField}>
            <label className={styles.fieldLabel}>{t('fields.uid')}</label>
            <input aria-label="Entry UID" readOnly className={clsx(styles.entryInput, styles.readOnlyValue)} value={entry.uid} />
          </div>
          <div className={styles.entryField}>
            <label className={styles.fieldLabel}>{t('fields.automationId')}</label>
            <input
              type="text"
              className={styles.entryInput}
              value={automationId}
              onChange={(e) => {
                markDirty('automation_id')
                setAutomationId(e.target.value)
                onUpdate(entry.id, { automation_id: e.target.value || null })
              }}
            />
          </div>
        </div>
      </DisclosureSection>
      <span data-spindle-mount="world_book_entry_toolbar" data-spindle-scope={`world-book-entry:${entry.id}:toolbar`} style={{ display: 'contents' }} />
    </div>
  )
}

