.tick {
  width: 13px;
  height: 3px;
  border-radius: 1px;
  background: rgba(255, 255, 255, 0.1);
}
.ticksWrapCompact .tick {
  width: 9px;
  gap: 2px;
}
.tickDone {
  background: color-mix(in srgb, var(--lumiverse-primary, #9370db) 55%, transparent);
}
.tickActive {
  background: var(--lumiverse-primary, #9370db);
}
.ticksStretch {
  display: flex;
  width: 100%;
  align-items: stretch;
}
.ticksStretch .ticks {
  display: flex;
  width: 100%;
}
.ticksStretch .tick {
  flex: 1;
  width: auto;
}
.ticksWord {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--lumiverse-text-dim, rgba(255, 255, 255, 0.4));
}
.ticksWordOn {
  color: var(--lumiverse-primary-text, rgba(186, 135, 255, 0.92));
}

.kindChip {
  display: inline-flex;
  align-items: center;
  flex: none;
  height: 16px;
  padding: 0 7px;
  border-radius: 999px;
  border: 1px solid var(--lumiverse-border-light, rgba(255, 255, 255, 0.075));
  background: rgba(255, 255, 255, 0.04);
