}
.loreRow {
  display: grid;
  grid-template-columns: minmax(120px, 168px) auto minmax(0, 1fr);
  gap: 12px;
  align-items: center;
  width: 100%;
  padding: 10px 6px;
  border: none;
  border-bottom: 1px solid var(--lumiverse-border-light, rgba(255, 255, 255, 0.075));
  background: transparent;
  font-family: inherit;
