}
.loreRow:hover {
  background: var(--lumiverse-bg-hover, rgba(147, 112, 219, 0.06));
}
.loreName {
  font-size: calc(13px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text, rgba(255, 255, 255, 0.92));
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.loreChipCell {
  display: inline-flex;
  justify-self: start;
  min-width: 0;
  max-width: 130px;
  overflow: hidden;
}
.loreLine {
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim, rgba(255, 255, 255, 0.4));
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.personRow {
  display: grid;
  grid-template-columns: 24px minmax(110px, 150px) auto minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  width: 100%;
  min-height: 38px;
  padding: 5px 6px;
  border-bottom: 1px solid var(--lumiverse-border-light, rgba(255, 255, 255, 0.075));
}
.personRow:last-child {
  border-bottom-color: transparent;
}
.personActions {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  justify-self: end;
}
.personWeave {
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid var(--lumiverse-border-light, rgba(255, 255, 255, 0.075));
}
@media (max-width: 720px) {
  .personRow {
    grid-template-columns: 24px minmax(0, 1fr) auto;
  }
  .personRow .loreChipCell,
  .personRow .loreLine {
    display: none;
  }
}

.headSep {
  flex: none;
  width: 1px;
  height: 18px;
  background: var(--lumiverse-border-light, rgba(255, 255, 255, 0.075));
  margin: 0 2px;
}
.liveDot {
  flex: none;
  width: 5px;
  height: 5px;
  border-radius: 999px;
  background: var(--lumiverse-primary, #9370db);
  animation: wv-pulse 2s ease infinite;
}
@keyframes wv-pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.35;
  }
}

@media (prefers-reduced-motion: reduce) {
  .shell,
  .workMain,
  .placeholder {
    animation: none;
  }
  .liveDot {
    animation: none;
  }
}

.cardPane {
  max-width: 760px;
  width: 100%;
  margin: 0 auto;
}
.cardPaneHead {
  display: flex;
  align-items: center;
  gap: 10px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--lumiverse-border-light, rgba(255, 255, 255, 0.075));
}
.cardPaneTitle {
  font-size: calc(15px * var(--lumiverse-font-scale, 1));
  font-weight: 600;
  color: var(--lumiverse-text, rgba(255, 255, 255, 0.92));
}
.cardPaneCount {
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-hint, rgba(255, 255, 255, 0.3));
}
.cardProv {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 10px 2px;
  border-bottom: 1px solid var(--lumiverse-border-light, rgba(255, 255, 255, 0.075));
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted, rgba(255, 255, 255, 0.65));
}
.cardProv svg {
  color: var(--lumiverse-text-dim, rgba(255, 255, 255, 0.4));
  flex: none;
}
.cardProvDim {
  color: var(--lumiverse-text-hint, rgba(255, 255, 255, 0.3));
}
.cardField {
  display: grid;
  grid-template-columns: 132px minmax(0, 1fr) auto;
  gap: 16px;
  align-items: baseline;
  padding: 12px 2px;
  border-bottom: 1px solid var(--lumiverse-border-light, rgba(255, 255, 255, 0.075));
  cursor: pointer;
  transition: background 150ms ease;
}
.cardFieldRight {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  min-width: 52px;
}
.cardField .cardFieldRight :global(button) {
  opacity: 0;
  transition: opacity 150ms ease;
}
.cardField:hover .cardFieldRight :global(button),
.cardField:focus-within .cardFieldRight :global(button) {
  opacity: 1;
}
@media (hover: none) {
  .cardField .cardFieldRight :global(button) {
    opacity: 1;
  }
}
.cardFieldEdit {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
}
.cardFieldArea {
  width: 100%;
  min-height: 84px;
  resize: vertical;
}
.cardFieldEditActions {
  display: flex;
  gap: 8px;
}

/* Persona review */
.personaIdRow {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr);
  gap: 16px;
}
.personaPronouns {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}
.personaSection {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 12px;
}
.personaSection .field {
  min-height: 72px;
  resize: vertical;
}
.personaDepthRow {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 12px;
  margin-top: 10px;
  border: 1px solid var(--lumiverse-border-light, rgba(255, 255, 255, 0.075));
  border-radius: var(--lumiverse-radius, 8px);
}
.personaDepthRow .field {
  min-height: 60px;
  resize: vertical;
}
.personaDepthHead {
  display: flex;
  align-items: center;
  gap: 8px;
}
.personaDepthHead .field {
  min-height: 0;
  flex: 1;
}
@media (max-width: 600px) {
  .personaIdRow {
    grid-template-columns: 1fr;
  }
}
.cardField:hover {
  background: var(--lumiverse-bg-hover, rgba(255, 255, 255, 0.04));
}
.cardFieldLabel {
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: var(--lumiverse-text-dim, rgba(255, 255, 255, 0.4));
}
.cardFieldText {
  font-size: calc(12.5px * var(--lumiverse-font-scale, 1));
  line-height: 1.5;
  color: var(--lumiverse-text-muted, rgba(255, 255, 255, 0.65));
  white-space: pre-wrap;
}
.cardFieldClamp {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.cardFieldEmpty {
  color: var(--lumiverse-text-hint, rgba(255, 255, 255, 0.3));
}
.cardFieldCount {
  font-family: var(--lumiverse-font-mono, monospace);
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-hint, rgba(255, 255, 255, 0.3));
  text-align: right;
}
@media (max-width: 720px) {
  .cardField {
    grid-template-columns: minmax(0, 1fr) 44px;
  }
  .cardFieldLabel {
    grid-column: 1 / -1;
  }
}

.tieBand {
  flex: none;
  display: flex;
  align-items: center;
  gap: 9px;
  min-height: 38px;
  padding: 0 20px;
  border-bottom: 1px solid var(--lumiverse-border, rgba(147, 112, 219, 0.12));
  background: var(--lumiverse-primary-010, rgba(147, 112, 219, 0.1));
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-muted, rgba(255, 255, 255, 0.65));
}
.tieBand svg {
  color: var(--lumiverse-primary-text, rgba(196, 181, 253, 0.95));
