}
.tieBandDim {
  color: var(--lumiverse-text-hint, rgba(255, 255, 255, 0.3));
}
.tieBandOpen {
  margin-left: auto;
}

@keyframes weaverSurfaceEnter {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes weaverPaneSwap {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
.surfaceEnter {
  animation: weaverSurfaceEnter 180ms ease-out;
}
.dashPane > * {
  animation: weaverPaneSwap 150ms ease;
}
@media (prefers-reduced-motion: reduce) {
  .surfaceEnter,
  .dashPane > * {
    animation: none;
  }
}

.stageSwap {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  animation: weaverPaneSwap 150ms ease;
}
@media (prefers-reduced-motion: reduce) {
  .stageSwap {
    animation: none;
  }
}

