}
.tuningInput::-webkit-outer-spin-button,
.tuningInput::-webkit-inner-spin-button {
  appearance: none;
  margin: 0;
}
.tuningInput::placeholder {
  font-family: var(--lumiverse-font-family, sans-serif);
  text-align: right;
}
.tuningSet {
  border-color: var(--lumiverse-primary-020, rgba(147, 112, 219, 0.2));
}
.tuningSaved {
  align-self: center;
  font-size: calc(12px * var(--lumiverse-font-scale, 1));
  color: var(--lumiverse-text-dim, rgba(255, 255, 255, 0.4));
}
@media (max-width: 560px) {
  .tuningRow {
    grid-template-columns: 1fr;
    gap: 8px;
  }
  .tuningInput {
    width: 100%;
    text-align: left;
  }
  .tuningInput::placeholder {
    text-align: left;
  }
}

@media (max-width: 600px) {
  .overlay {
    align-items: stretch;
    padding:
      var(--weaver-safe-top)
      var(--weaver-safe-right)
      var(--weaver-safe-bottom)
      var(--weaver-safe-left);
  }
  .shell {
    --weaver-safe-top: 0px;
    --weaver-safe-right: 0px;
    --weaver-safe-bottom: 0px;
    --weaver-safe-left: 0px;
    width: 100%;
    max-width: 100%;
    height: 100%;
    max-height: none;
    border-radius: 0;
    border-left: none;
    border-right: none;
  }
  .panel {
    --weaver-panel-pad-top: 16px;
    --weaver-panel-pad-right: 16px;
    --weaver-panel-pad-left: 16px;
  }
  .footer {
    --weaver-footer-pad-top: 12px;
    --weaver-footer-pad-right: 16px;
    --weaver-footer-pad-bottom: 12px;
    --weaver-footer-pad-left: 16px;
    flex-wrap: wrap;
  }
  .stageHead {
    gap: 12px;
    margin-bottom: 14px;
  }

  /* Interview / bible / render: answer area first, progress rail below it. */
  .work {
    grid-template-columns: 1fr;
    gap: 20px;
  }
  .workMain {
    order: 1;
  }
  .workRail {
    order: 2;
    position: static;
    padding-right: 0;
    margin-right: 0;
    border-right: none;
    padding-top: 18px;
    border-top: 1px solid var(--lumiverse-border-light, rgba(255, 255, 255, 0.075));
  }

  .dreamScroll {
    display: block;
  }
  .dreamWrap {
    display: block;
    height: auto;
    flex: none;
  }
  .dreamGrid {
    display: block;
  }
  .dreamEdit {
    display: block;
    min-width: 0;
  }
  .dreamEdit .field {
    flex: none;
    min-height: 180px;
  }
  .dreamRail {
    padding-left: 0;
    margin-left: 0;
    border-left: none;
    margin-top: 24px;
    padding-top: 22px;
    border-top: 1px solid var(--lumiverse-border-light, rgba(255, 255, 255, 0.075));
  }
}

