/*
 * The workspace is a query container so the panes react to the width of the
 * editor itself — the thing the user actually drags — instead of the viewport.
 * Dragging a divider used to leave the layout untouched and simply produce
 * sideways scrolling.
 *
 * Two hazards worth naming:
 *  - `container-name` is a GLOBAL identifier. CSS Modules does not scope it, so
 *    `lbWorkspace` is deliberately unlikely to collide with another stylesheet.
 *  - `container-type: inline-size` implies `contain: layout`, which makes this
 *    element a containing block for any `position: fixed` DESCENDANT. Nothing in
 *    this subtree is fixed today: `ExpandedTextEditor` and `SearchableSelect`
 *    both `createPortal` to `document.body`, and `.halfScreenHost`'s fixed
 *    full-bleed rule is on an *ancestor*. Any future non-portaled popover
 *    rendered inside the editor would be trapped here.
 * The inline size is definite (`width: 100%` of a sized host), never
 * content-sized, so `contain: inline-size` cannot collapse it.
 */
.workspace {
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  color: var(--lumiverse-text);
  background: var(--lumiverse-bg);
  isolation: isolate;
  container-type: inline-size;
  container-name: lbWorkspace;
}

.workspaceHeader,
.paneTitle,
.headerIdentity,
.headerActions,
.searchField,
.listActions,
.displayToggle {
  display: flex;
  align-items: center;
}

.workspaceHeader {
  position: relative;
  z-index: 2;
  flex-shrink: 0;
  flex-wrap: wrap;
  min-height: 58px;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--lumiverse-border);
  background: color-mix(in srgb, var(--lumiverse-bg) 92%, transparent);
}

.headerIdentity {
  flex: 1 1 12rem;
  gap: 10px;
  min-width: 0;
}

.headerIdentity div {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.headerIdentity strong {
  font-size: calc(15px * var(--lumiverse-font-scale, 1));
}

.headerIdentity span {
  overflow: hidden;
  color: var(--lumiverse-text-muted);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
  text-overflow: ellipsis;
  white-space: nowrap;
}

.headerActions {
  flex: 1 1 auto;
  justify-content: flex-end;
  gap: 8px;
  flex-wrap: wrap;
}

.headerActions button,
.headerActions select,
.bulkBar button,
.bulkBar input,
.bulkBar select,
.listActions button,
.halfBookPickerTrigger {
  min-height: 30px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 7px;
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text);
  font-size: calc(11px * var(--lumiverse-font-scale, 1));
}

.headerActions button,
.bulkBar button,
.listActions button {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 9px;
  cursor: pointer;
}

.headerActions .primaryButton {
  border-color: transparent;
  background: var(--lumiverse-primary);
  color: var(--lumiverse-primary-contrast, #fff);
}

.displayToggle {
  gap: 6px;
  color: var(--lumiverse-text-muted);
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
}

.displayToggle select {
  padding: 4px 7px;
}

.panes {
  position: relative;
  z-index: 1;
  display: flex;
  flex: 1 1 auto;
  width: 100%;
  min-width: 0;
  min-height: 0;
}

.booksPane,
.entriesPane,
.inspectorPane {
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: var(--lumiverse-bg);
}

.booksPane {
  width: var(--lorebook-books-width);
  min-width: 140px;
  flex: 0 1 var(--lorebook-books-width);
}

.entriesPane {
  width: var(--lorebook-entries-width);
  min-width: 200px;
  flex: 0 1 var(--lorebook-entries-width);
}

/* The pane clips; the entry editor inside owns its own scrolling so the content
   field can flex-fill whatever height is left over. Grow into leftover row
   space with a hard 280px floor so a stored --lorebook-inspector-width cannot
   collapse this pane to an empty void on typical desktop / half widths. */
.inspectorPane {
  flex: 1 1 auto;
  min-width: 280px;
  overflow: hidden;
}

.inspectorBody {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  overflow: auto;
}

.splitter {
  position: relative;
  width: 7px;
  flex: 0 0 7px;
  cursor: col-resize;
  border-inline: 1px solid var(--lumiverse-border);
  background: var(--lumiverse-fill-subtle);
}

.splitter::after {
  content: "";
  position: absolute;
  inset: 42% 2px;
  border-radius: 999px;
  background: var(--lumiverse-text-dim);
  opacity: 0.45;
}

.paneTitle {
  min-height: 34px;
  gap: 8px;
  justify-content: space-between;
  padding: 6px 10px;
  border-bottom: 1px solid var(--lumiverse-border);
  color: var(--lumiverse-text-muted);
  font-size: calc(10px * var(--lumiverse-font-scale, 1));
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.paneTitleLabel {
  flex: 0 0 auto;
}

.paneTitleCount {
  min-width: 0;
  overflow: hidden;
  color: var(--lumiverse-primary);
  letter-spacing: 0.02em;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.selectAllBox {
  flex: 0 0 auto;
  margin: 0;
  accent-color: var(--lumiverse-primary);
}

.paneTitleActions {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
}

.entriesToolbar {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  padding: 7px 10px 0;
}

.entriesToolbar .searchField {
  flex: 1 1 auto;
  min-width: 0;
  margin: 0;
}

/*
 * The picker still yields the row's slack to the entry-search field
 * (`flex: 0 1 …; min-width: 0`), but 120px was not enough to read a book name:
 * the trigger spends ~38px on padding, gap and chevron, leaving ~11 characters.
 * 170px leaves ~130px of label, which fits a typical "Worldbuilding Notes".
 */
.entriesToolbar .halfBookPicker {
  flex: 0 1 170px;
  min-width: 0;
  margin: 0;
}

.toolbarToggle {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  width: 30px;
  min-height: 30px;
  padding: 0;
  border: 1px solid var(--lumiverse-border);
  border-radius: 7px;
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text-muted);
  cursor: pointer;
}

.toolbarToggleActive {
  border-color: var(--lumiverse-primary-050);
  background: var(--lumiverse-primary-015);
  color: var(--lumiverse-primary);
}

.typeFilterRow {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  padding: 7px 10px;
}

.typeFilterChip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 7px;
  border: 1px solid transparent;
  border-radius: 999px;
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text-muted);
  font-size: calc(9.5px * var(--lumiverse-font-scale, 1));
  cursor: pointer;
}

.typeFilterChip b {
  font-variant-numeric: tabular-nums;
  opacity: 0.75;
}

.typeFilterChipActive {
  border-color: currentcolor;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, currentcolor 30%, transparent);
}

.typeFilterChipActive:not(.trigger_constant):not(.trigger_keyword):not(.trigger_vector) {
  background: var(--lumiverse-primary-015);
  color: var(--lumiverse-primary);
}

.paneTitleActions button {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 6px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 5px;
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text-muted);
  font: inherit;
  cursor: pointer;
  text-transform: none;
  letter-spacing: normal;
}

.searchField {
  gap: 7px;
  margin: 10px;
  padding: 7px 9px;
  border: 1px solid var(--lumiverse-border);
  border-radius: 8px;
  background: var(--lumiverse-fill-subtle);
  color: var(--lumiverse-text-dim);
}

.searchField:focus-within {
  border-color: color-mix(in srgb, var(--lumiverse-primary) 65%, var(--lumiverse-border));
  box-shadow: 0 0 0 2px var(--lumiverse-primary-015);
}

