/*
 * Scoped to `.entriesToolbar` so it wins deterministically over
 * `SearchableSelect.module.css`'s own `.trigger { padding: 7px 10px }`
 * regardless of which stylesheet the bundler emits first — both are
 * single-class selectors otherwise. `min-height: 30px` (shared control chrome
 * above) is what actually sets the height, matching the toolbar's other controls.
 */
.entriesToolbar .halfBookPickerTrigger {
  padding: 4px 8px;
}

/*
 * `.halfScreenHost`, `.halfResizeHandle` and the `@media (max-width: 900px)`
 * full-bleed override for the host now live in `LorebookHalfScreenEditor.module.css`.
 * They dress the chat-row host element, not the workspace this stylesheet owns.
 *
 * Every pane rule that used to sit in that viewport query has moved to the
 * `@container lbWorkspace` ladder below, because a viewport query cannot see the
 * one dimension the user is changing: the width of the editor itself.
 */

/*
 * Empty mount is `display: contents` so it does not become a flex item. Once
 * the suite injects its two-column grid, collapse the box so it cannot steal
 * width from `.panes` (cards-left / empty-right).
 */
.spindleWorkspaceMount:empty {
  display: contents;
}

.spindleWorkspaceMount:not(:empty) {
  position: absolute;
  width: 0;
  height: 0;
  overflow: hidden;
  pointer-events: none;
  flex: 0 0 0;
}

/*
 * The pane ladder, keyed on `.workspace`'s own inline size.
 *
 * | tier     | inline size | what collapses                          |
 * |----------|-------------|-----------------------------------------|
 * | wide     | >= 1040     | nothing — books + entries + inspector    |
 * | standard | 520-1039    | books pane hidden; entries + inspector   |
 * | stacked  | < 520       | splitter hidden, panes 50/50             |
 *
 * Desktop half (~720) and windowed full (~560+) stay side-by-side. Stacking
 * at 759 used to hide the inspector under the list on those widths.
 *
 * Tiers are cumulative, exactly like nested media queries.
 *
 * Every selector is written as `.workspace X` rather than bare `X` so it matches
 * the specificity of the `.halfWorkspace X` overrides above and wins on source
 * order. A bare `.entriesPane` here (0,1,0) would silently lose to
 * `.halfWorkspace .entriesPane` (0,2,0) and the half editor would never stack.
 *
 * Collapse is purely presentational: `width: 100%` simply stops the stored
 * `--lorebook-entries-width` from being consulted. The user's dragged px value is
 * untouched and is restored verbatim the moment the container grows back — no
 * state machine, no "remembered width" field.
 */
@container lbWorkspace (max-width: 1039px) {
  .workspace .booksPane,
  .workspace .booksPane + .splitter {
    display: none;
  }

  .workspace .workspaceHeader {
    align-items: flex-start;
  }

  .workspace .headerActions {
    justify-content: flex-end;
  }

  .workspace .inspectorPane,
  .workspace.halfWorkspace .inspectorPane {
    flex: 1 1 auto;
    min-width: 280px;
  }
}

@container lbWorkspace (max-width: 519px) {
  .workspace .panes {
    flex-direction: column;
  }

  /* No splitter, so a drag can never produce a width that is meaningless in the
     collapsed layout. */
  .workspace .splitter {
    display: none;
  }

  /* The 200/280px floors exist to stop the splitter dragging a pane to nothing.
     With the splitter gone they only force the horizontal overflow this whole
     ladder exists to remove. */
  .workspace .entriesPane,
  .workspace .inspectorPane,
  .workspace.halfWorkspace .inspectorPane {
    width: 100%;
    min-width: 0;
    flex: 1 1 50%;
  }

  .workspace .workspaceHeader {
    min-height: 44px;
    gap: 6px;
    padding: 6px 8px;
  }

  .workspace .headerActions {
    gap: 4px;
  }
}

