type WorkspaceVariant = 'full' | 'half'

export interface LorebookEditorWorkspaceProps {
  variant: WorkspaceVariant
  initialBookId?: string | null
  initialEntryId?: string | null
  onClose?: () => void
  onOpenFullEditor?: (bookId: string | null, entryId: string | null) => void
  onImportRequest?: () => void
  fullscreen?: boolean
  onToggleFullscreen?: () => void
}

interface EntryConflictState {
  server: WorldBookEntry
  draft: Partial<WorldBookEntry>
}

/** Stages of one bulk request: a failed re-read is not a failed write. */
type BulkRunOutcome =
  | { status: 'completed' }
  | { status: 'conflict'; conflictCount: number }
  | { status: 'refresh-failed' }

/** Persistent notices the entries pane shows after a non-successful outcome. */
type BulkNotice =
  | { kind: 'conflict'; conflictCount: number }
  | { kind: 'refresh-failed' }
  /** A request whose outcome is unknown: it may or may not have been written. */
  | { kind: 'unconfirmed' }

type BulkMutationInput = WorldBookEntryBulkActionInput extends infer Input
  ? Input extends WorldBookEntryBulkActionInput
    ? Omit<Input, 'expected_revisions'>
    : never
  : never

function expectedRevisionMap(entries: WorldBookEntry[], ids: string[]): Record<string, number> {
  const wanted = new Set(ids)
  return Object.fromEntries(
    entries.filter((entry) => wanted.has(entry.id)).map((entry) => [entry.id, entry.revision]),
  )
}

function conflictPayload(error: unknown): WorldBookEntryConflictPayload | null {
  if (!(error instanceof ApiError) || error.status !== 409) return null
  if (error.body?.error !== 'world_book_entry_conflict' || !Array.isArray(error.body?.conflicts)) return null
  return error.body as WorldBookEntryConflictPayload
}

/** Server-supplied reason for a rejected bulk request, when its body carries one. */
function apiErrorMessage(error: ApiError): string | null {
  const body = error.body
  if (body && typeof body === 'object' && 'error' in body) {
    const message = body.error
    if (typeof message === 'string' && message.length > 0) return message
  }
  return error.statusText || null
}

export default function LorebookEditorWorkspace({
  variant,
  initialBookId,
  initialEntryId,
  onClose,
  onOpenFullEditor,
  onImportRequest,
  fullscreen = false,
  onToggleFullscreen,
}: LorebookEditorWorkspaceProps) {
  const { settings, updateSettings } = useLorebookEditorLayoutSettings()
  const addToast = useStore((state) => state.addToast)
  const [books, setBooks] = useState<WorldBook[]>([])
  const [entries, setEntries] = useState<WorldBookEntry[]>([])
  const entriesRef = useRef<WorldBookEntry[]>([])
  const [bookSearch, setBookSearch] = useState('')
  const [entrySearch, setEntrySearch] = useState('')
  const [selectedBookId, setSelectedBookId] = useState<string | null>(initialBookId ?? null)
  const [selectedEntryId, setSelectedEntryId] = useState<string | null>(initialEntryId ?? null)
  const [selectedIds, setSelectedIds] = useState<string[]>([])
  const [loading, setLoading] = useState(false)
  const [entriesComplete, setEntriesComplete] = useState(false)
  const [reordering, setReordering] = useState(false)
  const [savedAt, setSavedAt] = useState<number | null>(null)
  const [conflicts, setConflicts] = useState<Record<string, EntryConflictState>>({})
  const [bulkNotice, setBulkNotice] = useState<BulkNotice | null>(null)
  // While a bulk request is in flight its write may already be on the server, so
  // Apply stays shut until the reload has reconciled.
  const [bulkPending, setBulkPending] = useState(false)
  // Every bulk control starts in an explicit "leave as is" state, so only the
  // controls the user sets reach the wire. See `lib/lorebookBulkPatch.ts`.
  const [bulkPriority, setBulkPriority] = useState(EMPTY_BULK_FIELD_FORM.priority)
  const [bulkDepth, setBulkDepth] = useState(EMPTY_BULK_FIELD_FORM.depth)
  const [bulkPosition, setBulkPosition] = useState<BulkPositionSelection>(EMPTY_BULK_FIELD_FORM.position)
  const [bulkTrigger, setBulkTrigger] = useState<BulkTriggerSelection>(EMPTY_BULK_FIELD_FORM.trigger)
  const [bulkEnabled, setBulkEnabled] = useState<BulkEnabledSelection>(EMPTY_BULK_FIELD_FORM.enabled)
  const [bulkVisible, setBulkVisible] = useState(false)
  const [typeFilter, setTypeFilter] = useState<'all' | TriggerType>('all')
  const entrySearchInputRef = useRef<HTMLInputElement | null>(null)
  const pendingDrafts = useRef<Record<string, Partial<WorldBookEntry>>>({})
  const saveQueues = useRef<Record<string, Promise<void>>>({})
  const debounceTimers = useRef<Record<string, ReturnType<typeof setTimeout>>>({})
  const splitterDrag = useRef<{ pane: 'books' | 'entries'; startX: number; startWidth: number } | null>(null)
  const panesRef = useRef<HTMLDivElement | null>(null)
  // `initialEntryId` is an *opening* instruction, not a standing preference. The
  // store never clears it (`store/slices/world-info.ts` keeps `entryId` after
  // close) and the Lore Indicator seeds it with a real id, so honouring it on
  // every load made Refresh — and every bulk action, which ends in `loadEntries`
  // — snap the selection back to whatever the editor was opened with, discarding
  // the row the user had actually clicked. Consume it exactly once.
  const pendingInitialEntryId = useRef<string | null>(initialEntryId ?? null)

  useEffect(() => {
    const next = initialEntryId ?? null
    pendingInitialEntryId.current = next
    if (!next) return
    // Re-opening onto a different entry while the book is already loaded fires no
    // load at all, so apply it here and consume the pin immediately — otherwise it
    // would sit armed and hijack the next unrelated Refresh.
    if (entriesRef.current.some((entry) => entry.id === next)) {
      pendingInitialEntryId.current = null
      setSelectedEntryId(next)
    }
  }, [initialEntryId])

  const commitEntries = useCallback((
    update: WorldBookEntry[] | ((current: WorldBookEntry[]) => WorldBookEntry[]),
  ) => {
    const next = typeof update === 'function' ? update(entriesRef.current) : update
    entriesRef.current = next
    setEntries(next)
  }, [])


  // The book whose entries have most recently been *requested*, plus a monotonic
  // sequence for the requests themselves.
  //
  // Two independent paths ask for the opening book's entries: the mount effect
  // below, which can start immediately because `selectedBookId` is seeded from
  // `initialBookId`, and `loadBooks`, which starts it the instant the book list
  // names a book. The id latch is what keeps that one round trip instead of two;
  // the sequence is what stops a slow answer from overwriting a newer one.
  const selectedBookIdRef = useRef<string | null>(selectedBookId)
  selectedBookIdRef.current = selectedBookId
  const requestedEntriesBookId = useRef<string | null>(null)
  const entriesRequestSeq = useRef(0)
  const entriesAbortRef = useRef<AbortController | null>(null)

  useEffect(() => () => entriesAbortRef.current?.abort(), [])

  useEffect(() => {
    setSavedAt(null)
    setEntrySearch('')
    setTypeFilter('all')
  }, [selectedBookId])

  const loadEntries = useCallback((bookId: string, preserveSelection = true): Promise<void> => {
    requestedEntriesBookId.current = bookId
    const seq = ++entriesRequestSeq.current
    entriesAbortRef.current?.abort()
    const controller = new AbortController()
    entriesAbortRef.current = controller
    setLoading(true)
    setEntriesComplete(false)
    return (async () => {
      try {
        const result = await worldBooksApi.listAllEntries(bookId, { signal: controller.signal })
        // A newer request started while this one was in flight — a book switch,
        // Refresh, or the reload that ends every bulk action. That answer is the
        // current one, so this older payload is dropped rather than committed
        // over the top of it.
        if (seq !== entriesRequestSeq.current) return
        commitEntries(result)
        setEntriesComplete(true)
        setSelectedEntryId((current) => {
          const pending = pendingInitialEntryId.current
          if (pending && result.some((entry) => entry.id === pending)) {
            pendingInitialEntryId.current = null
            return pending
          }
          if (preserveSelection && current && result.some((entry) => entry.id === current)) return current
          return result[0]?.id ?? null
        })
        setSelectedIds((current) => current.filter((id) => result.some((entry) => entry.id === id)))
      } catch (error) {
        if (!controller.signal.aborted) throw error
      } finally {
        if (entriesAbortRef.current === controller) entriesAbortRef.current = null
        // Only the newest request owns the spinner; a superseded one clearing it
        // would report "loaded" while the current fetch is still out.
        if (seq === entriesRequestSeq.current) setLoading(false)
      }
    })()
    // The opening entry id is carried by a ref, not a dep: keeping it here also
    // churned `loadEntries`' identity and re-fired the mount effects below.
  }, [commitEntries])

  const loadBooks = useCallback(async () => {
    const result = await worldBooksApi.list({ limit: 1000 })
    setBooks(result.data)
    // The same precedence as the state update on the next line, resolved from a
    // ref so the entries request can be issued in this tick. Waiting for
    // `setSelectedBookId` to commit and the selection effect to fire costs an
    // entire render of the books pane before the request the user is actually
    // waiting on is even sent — that is the whole of the open waterfall on the
    // path where no book was passed in.
    //
    // Reading the ref rather than the updater's `current` is what makes it a
    // read: at worst it is one commit stale, which can only mean picking the book
    // the selection effect is about to ask for anyway — and the latch below makes
    // the loser of that race a no-op rather than a second fetch.
    const resolved = selectedBookIdRef.current ?? initialBookId ?? result.data[0]?.id ?? null
    setSelectedBookId((current) => current ?? initialBookId ?? result.data[0]?.id ?? null)
    if (resolved && requestedEntriesBookId.current !== resolved) void loadEntries(resolved, false)
  }, [initialBookId, loadEntries])

  useEffect(() => {
    return wsClient.on(EventType.WORLD_BOOK_LIBRARY_CHANGED, () => {
      void loadBooks()
    })
  }, [loadBooks])

  // The two opening requests, issued in the same tick.
  //
  // `selectedBookId` is seeded from `initialBookId`, and every call site that
  // opens this editor passes a book, so the entries request — the one that
  // decides when the first row appears — must not queue behind a 209-row book
  // list. Issuing it here, ahead of `loadBooks`, makes that a stated guarantee
  // rather than an accident of effect-declaration order. With no book known yet
  // there is nothing to request, and `loadBooks` covers that case itself.
  useEffect(() => {
    const openingBookId = selectedBookIdRef.current
    if (openingBookId && requestedEntriesBookId.current !== openingBookId) {
      void loadEntries(openingBookId, false)
    }
    void loadBooks()
  }, [loadBooks, loadEntries])

  useEffect(() => {
    if (!selectedBookId) {
      // Never blank a list a parallel load has already filled: `loadBooks` can
      // resolve the book and start its entries fetch a commit before its
      // `setSelectedBookId` lands here.
      if (requestedEntriesBookId.current !== null) return
      commitEntries([])
      return
    }
    // Already asked for, by the mount effect or by `loadBooks`. Re-issuing it
    // here is exactly the double fetch the latch exists to prevent.
    if (requestedEntriesBookId.current === selectedBookId) return
    void loadEntries(selectedBookId, false)
  }, [commitEntries, loadEntries, selectedBookId])

  useEffect(() => {
    const handleMove = (event: PointerEvent) => {
      const drag = splitterDrag.current
      if (!drag) return
      const delta = event.clientX - drag.startX
      if (drag.pane === 'books') {
        const panesWidth = panesRef.current?.getBoundingClientRect().width ?? window.innerWidth
        const maxBooksWidth = Math.max(180, panesWidth - settings.entriesPaneWidth - 340)
        updateSettings({ booksPaneWidth: Math.max(180, Math.min(maxBooksWidth, drag.startWidth + delta)) })
      } else {
        const panesWidth = panesRef.current?.getBoundingClientRect().width ?? window.innerWidth
        const reservedWidth = variant === 'full' ? settings.booksPaneWidth + 14 : 7
        const maxEntriesWidth = Math.max(280, panesWidth - reservedWidth - 280)
        const width = Math.max(280, Math.min(maxEntriesWidth, drag.startWidth + delta))
        updateSettings(variant === 'half' ? { halfEntriesPaneWidth: width } : { entriesPaneWidth: width })
      }
    }
    const handleUp = () => {
      splitterDrag.current = null
    }
    window.addEventListener('pointermove', handleMove)
    window.addEventListener('pointerup', handleUp)
    return () => {
      window.removeEventListener('pointermove', handleMove)
      window.removeEventListener('pointerup', handleUp)
    }
  }, [settings.booksPaneWidth, settings.entriesPaneWidth, updateSettings, variant])

  // Name + folder, via the shared module the half editor's picker also agrees
  // with. This widens the Books pane search from name-only — intended, so the
  // two surfaces cannot answer the same query differently.
  const filteredBooks = useMemo(() => filterBooks(books, bookSearch), [bookSearch, books])

  /**
   * One index for the life of the workspace. It memoises normalized authored
   * fields and source offsets per entry object, checking its authored values for
   * edits. It must not be rebuilt when the query changes — rebuilding it per
   * keystroke would restore the very cost it exists to remove.
   */
  const entrySearchIndex = useMemo(() => createEntrySearchIndex(), [])

  const entrySearchResults = useMemo(
    () => searchEntriesByQuery(entries, entrySearch, entrySearchIndex),
    [entries, entrySearch, entrySearchIndex],
  )
  const searchActive = entrySearchResults !== null
  const queryEntries = useMemo(
    () => entrySearchResults?.map((result) => result.entry) ?? entries,
    [entries, entrySearchResults],
  )
  const entrySearchResultsById = useMemo(
    () => new Map(entrySearchResults?.map((result) => [result.entry.id, result]) ?? []),
    [entrySearchResults],
  )
  const filteredEntries = useMemo(
    () => typeFilter === 'all'
      ? queryEntries
      : queryEntries.filter((entry) => getTriggerType(entry) === typeFilter),
    [queryEntries, typeFilter],
  )

  // `listAllEntries` always requests `sort_by: 'order'`, which is this editor's
  // custom-order view. There is no alternate sort control in this workspace.
  const reorderEnabled = !loading
    && !reordering
    && entriesComplete
    && entrySearch.trim() === ''
    && typeFilter === 'all'

  // Background token counting. Everything it produces is client-only: it reaches
  // the Tokens column through a module-level cache and `useSyncExternalStore`,
  // never through the entry object, so no prefetch can trigger a save, bump
  // `revision`, flash "Saved", or remount the inspector mid-edit.
  const {
    resolveTokenCount,
    handleEntryPointerEnter,
    handleEntryPointerLeave,
  } = useLorebookTokenCounts(filteredEntries, true)

  const typeCounts = useMemo(() => ({
    constant: queryEntries.filter((entry) => getTriggerType(entry) === 'constant').length,
    keyword: queryEntries.filter((entry) => getTriggerType(entry) === 'keyword').length,
    vector: queryEntries.filter((entry) => getTriggerType(entry) === 'vector').length,
  }), [queryEntries])

  const handleWorkspaceKeyDown = useCallback((event: ReactKeyboardEvent<HTMLElement>) => {
    if (event.defaultPrevented || event.altKey || event.shiftKey) return
    if (!(event.ctrlKey || event.metaKey) || event.key.toLowerCase() !== 'f') return
    event.preventDefault()
    event.stopPropagation()
    entrySearchInputRef.current?.focus()
    entrySearchInputRef.current?.select()
  }, [])

  const selectedEntry = entries.find((entry) => entry.id === selectedEntryId) ?? null
  const selectedBook = books.find((book) => book.id === selectedBookId) ?? null
  const showTokens = settings.visibleEntryMetadata.includes('tokens')

  const visibleColumns = useMemo(
    () => resolveVisibleColumns(settings.visibleEntryMetadata),
    [settings.visibleEntryMetadata],
  )
  const entryGridTemplate = useMemo(() => buildEntryGridTemplate(visibleColumns), [visibleColumns])
  const entryTableMinWidth = useMemo(() => buildEntryTableMinWidth(visibleColumns), [visibleColumns])

  // Stored arrays are replaced wholesale rather than merged, so a column added to
  // the defaults would stay invisible on every install that already persisted this
  // setting. Backfill once, recording the version so a later untick sticks.
  useEffect(() => {
    const storedVersion = settings.entryMetadataVersion ?? 0
    if (storedVersion >= ENTRY_METADATA_VERSION) return
    updateSettings({
      visibleEntryMetadata: backfillEntryMetadata(settings.visibleEntryMetadata, storedVersion),
      entryMetadataVersion: ENTRY_METADATA_VERSION,
    })
  }, [settings.entryMetadataVersion, settings.visibleEntryMetadata, updateSettings])

  const allFilteredSelected = filteredEntries.length > 0
    && filteredEntries.every((entry) => selectedIds.includes(entry.id))

  // Reveal the bulk bar when a selection appears and collapse it when the
  // selection is cleared, while still letting the toolbar button override in
  // between. Deriving visibility from the selection instead made the button a
  // no-op whenever anything was selected.
  const hasSelection = selectedIds.length > 0
  useEffect(() => {
    setBulkVisible(hasSelection)
  }, [hasSelection])

  const toggleTokenColumn = useCallback(() => {
    const visibleEntryMetadata = showTokens
      ? settings.visibleEntryMetadata.filter((item) => item !== 'tokens')
      : [...settings.visibleEntryMetadata, 'tokens']
    updateSettings({ visibleEntryMetadata })
  }, [settings.visibleEntryMetadata, showTokens, updateSettings])

  const applyConflict = useCallback((
    payload: WorldBookEntryConflictPayload,
    drafts: Record<string, Partial<WorldBookEntry>>,
  ) => {
    commitEntries((current) => {
      const currentMap = new Map(payload.conflicts.map((conflict) => [conflict.id, conflict.current]))
      return current.map((entry) => currentMap.get(entry.id) ?? entry).filter(Boolean) as WorldBookEntry[]
    })
    setConflicts((current) => {
      const next = { ...current }
      for (const conflict of payload.conflicts) {
        if (!conflict.current) continue
        next[conflict.id] = {
          server: conflict.current,
          draft: drafts[conflict.id] ?? pendingDrafts.current[conflict.id] ?? {},
        }
      }
      return next
    })
  }, [commitEntries])

  const reorderEntries = useCallback(async (activeId: string, overId: string) => {
    if (!selectedBookId || !reorderEnabled || activeId === overId) return
    const reorderBookId = selectedBookId
    const currentEntries = entriesRef.current
    const oldIndex = currentEntries.findIndex((entry) => entry.id === activeId)
    const newIndex = currentEntries.findIndex((entry) => entry.id === overId)
    if (oldIndex < 0 || newIndex < 0) return

    const orderedEntries = arrayMove(currentEntries, oldIndex, newIndex)
    const orderedIds = orderedEntries.map((entry) => entry.id)
    const expectedRevisions = expectedRevisionMap(currentEntries, orderedIds)
    setReordering(true)
    commitEntries(orderedEntries)
    try {
      await runLorebookReorderIfCurrent({
        bookId: reorderBookId,
        getCurrentBookId: () => selectedBookIdRef.current,
        reorder: () => worldBooksApi.reorderEntries(reorderBookId, {
          ordered_ids: orderedIds,
          expected_revisions: expectedRevisions,
        }).then(() => undefined),
        refresh: () => loadEntries(reorderBookId),
        onSaved: () => setSavedAt(Date.now()),
      })
    } catch (error) {
      if (selectedBookIdRef.current !== reorderBookId) return
      const payload = conflictPayload(error)
      if (payload) applyConflict(payload, {})
      await loadEntries(reorderBookId)
    } finally {
      setReordering(false)
    }
  }, [applyConflict, commitEntries, loadEntries, reorderEnabled, selectedBookId])

  const saveEntry = useCallback((entryId: string, updates: Partial<WorldBookEntry>) => {
    pendingDrafts.current[entryId] = { ...pendingDrafts.current[entryId], ...updates }
    commitEntries((current) => current.map((entry) => (
      entry.id === entryId ? { ...entry, ...updates } : entry
    )))

    const previous = saveQueues.current[entryId] ?? Promise.resolve()
    const next = previous.then(async () => {
      if (!selectedBookId) return
      const draft = pendingDrafts.current[entryId]
      if (!draft || Object.keys(draft).length === 0) return
      delete pendingDrafts.current[entryId]
      const current = entriesRef.current.find((entry) => entry.id === entryId)
      if (!current) return
      try {
        const updated = await worldBooksApi.updateEntry(selectedBookId, entryId, {
          ...draft,
          expected_revision: current.revision,
        })
        commitEntries((items) => items.map((entry) => entry.id === entryId ? updated : entry))
        setConflicts((state) => {
          if (!state[entryId]) return state
          const nextState = { ...state }
          delete nextState[entryId]
          return nextState
        })
        setSavedAt(Date.now())
      } catch (error) {
        const payload = conflictPayload(error)
        if (payload) {
          applyConflict(payload, { [entryId]: draft })
          return
        }
        pendingDrafts.current[entryId] = { ...draft, ...pendingDrafts.current[entryId] }
        throw error
      }
    })
    saveQueues.current[entryId] = next.catch(() => {})
    return next
  }, [applyConflict, commitEntries, selectedBookId])

  const debouncedSaveEntry = useCallback((entryId: string, updates: Partial<WorldBookEntry>) => {
    pendingDrafts.current[entryId] = { ...pendingDrafts.current[entryId], ...updates }
    commitEntries((current) => current.map((entry) => (
      entry.id === entryId ? { ...entry, ...updates } : entry
    )))
    clearTimeout(debounceTimers.current[entryId])
    debounceTimers.current[entryId] = setTimeout(() => {
      const draft = pendingDrafts.current[entryId] ?? {}
      void saveEntry(entryId, draft)
    }, 450)
  }, [commitEntries, saveEntry])

  const resolveConflict = useCallback(async (entryId: string, reapply: boolean) => {
    const conflict = conflicts[entryId]
    if (!conflict || !selectedBookId) return
    if (!reapply) {
      setConflicts((current) => {
        const next = { ...current }
        delete next[entryId]
        return next
      })
      return
    }
    pendingDrafts.current[entryId] = { ...conflict.draft }
    commitEntries((current) => current.map((entry) => (
      entry.id === entryId ? { ...conflict.server, ...conflict.draft } : entry
    )))
    await saveEntry(entryId, conflict.draft)
  }, [commitEntries, conflicts, saveEntry, selectedBookId])

  /**
   * Shared by Apply (`set_fields`), Duplicate (`copy`) and Delete (`delete`).
   * A rejected POST still throws, and copy/delete keep rejecting when the list
   * cannot be re-read, so only `set_fields` reports the refresh stage back.
   */
  const runBulk = useCallback(async (input: BulkMutationInput): Promise<BulkRunOutcome | null> => {
    if (!selectedBookId) return null
    const bookId = selectedBookId
    const ids = input.entry_ids
    const drafts = Object.fromEntries(ids.map((id) => [id, pendingDrafts.current[id] ?? {}]))
    try {
      await worldBooksApi.bulkEntryAction(bookId, {
        ...input,
        expected_revisions: expectedRevisionMap(entriesRef.current, ids),
      } as WorldBookEntryBulkActionInput)
    } catch (error) {
      const payload = conflictPayload(error)
      if (payload) {
        applyConflict(payload, drafts)
        return { status: 'conflict', conflictCount: payload.conflicts.length }
      }
      throw error
    }
    try {
      await loadEntries(bookId)
    } catch (error) {
      // Only the field bar needs the write and the reload told apart; Delete
      // must still clear the selection only after a successful refresh.
      if (input.action !== 'set_fields') throw error
      return { status: 'refresh-failed' }
    }
    setSavedAt(Date.now())
    return { status: 'completed' }
  }, [applyConflict, loadEntries, selectedBookId])

  const bulkForm = useMemo<BulkFieldForm>(() => ({
    priority: bulkPriority,
    depth: bulkDepth,
    position: bulkPosition,
    trigger: bulkTrigger,
    enabled: bulkEnabled,
  }), [bulkDepth, bulkEnabled, bulkPosition, bulkPriority, bulkTrigger])

  const bulkHasMutation = useMemo(() => hasBulkFieldMutation(bulkForm), [bulkForm])

  // One rule gates every entry point into Apply, and both readers of the toolbar
  // prop below share it: `applyBulk` refuses for the same reasons, so the button
  // cannot be live while the handler would no-op. A non-null notice means the
  // previous write was not confirmed, so this stays shut until the reload that
  // reconciles it runs — the toolbar prop carries that shut state to the button.
  const bulkApplyEnabled = isBulkApplyEnabled({
    bookId: selectedBookId,
    selectedCount: selectedIds.length,
    hasMutation: bulkHasMutation,
    noticesReconciliation: bulkNotice !== null,
    pending: bulkPending,
  })

  const applyBulk = useCallback(async () => {
    if (!bulkApplyEnabled || bulkPending) return
    // Sparse by construction: a key the user never set is never sent, and the
    // server only writes columns it receives.
    const patch = buildBulkFieldPatch(bulkForm)
    // Nothing touched. The server answers an empty set_fields with a 400, so this
    // must not reach the wire.
    if (Object.keys(patch).length === 0) return
    // This attempt owns its outcome; the retained form is the retry.
    setSavedAt(null)
    setBulkNotice(null)
    setBulkPending(true)
    let outcome: BulkRunOutcome | null = null
    try {
      outcome = await runBulk({ action: 'set_fields', entry_ids: selectedIds, fields: patch })
    } catch (error) {
      // The write was not acknowledged. A 4xx rejection proved the request never
      // landed, so the retained form may be retried once the entries are re-read;
      // anything else (5xx, a lost connection, or a rejection with no reason
      // attached) may already have written. Both report the same way, and neither
      // may claim the write succeeded.
      const rejected = error instanceof ApiError && error.status < 500
      const reason = rejected ? apiErrorMessage(error) : null
      addToast({
        type: 'error',
        message: reason
          ? `Bulk update rejected: ${reason}`
          : 'Bulk update could not be confirmed. Reload the entries before applying again.',
      })
      setBulkNotice({ kind: 'unconfirmed' })
      return
    } finally {
      setBulkPending(false)
    }
    if (!outcome) return
    // Every member of `BulkRunOutcome` is handled; the remaining `unconfirmed`
    // notice is raised on the throw path above, not here.
    switch (outcome.status) {
      case 'completed':
        break
      case 'conflict':
        setBulkNotice({ kind: 'conflict', conflictCount: outcome.conflictCount })
        break
      case 'refresh-failed':
        setBulkNotice({ kind: 'refresh-failed' })
        addToast({
          type: 'warning',
          message: 'Bulk update was saved, but the entries list could not be refreshed. Reload before applying again.',
        })
        break
      default:
        // Exhaustiveness guard: a new outcome must be handled here rather than
        // silently ignored.
        outcome satisfies never
    }
  }, [addToast, bulkApplyEnabled, bulkForm, bulkPending, runBulk, selectedIds])

  /**
   * Manual reconcile from the notice: re-read current revisions, then clear the
   * notice. Only an acknowledged POST may claim "Saved"; a conflict never wrote
   * anything, so it leaves "Saved" alone.
   */
  const reloadBulkEntries = useCallback(async (notice: BulkNotice) => {
    if (!selectedBookId) return
    const bookId = selectedBookId
    let requestSeq: number
    try {
      const reload = loadEntries(bookId)
      requestSeq = entriesRequestSeq.current
      await reload
    } catch {
      addToast({ type: 'error', message: 'Entries could not be reloaded. Use Reload entries to retry.' })
      return
    }
    // Cancelled and superseded loads resolve without committing entries. Only
    // the current request for the selected book may release the Apply gate.
    if (requestSeq !== entriesRequestSeq.current || selectedBookIdRef.current !== bookId) return
    setBulkNotice(null)
    if (notice.kind === 'refresh-failed') setSavedAt(Date.now())
  }, [addToast, loadEntries, selectedBookId])

  /**
   * The toolbar Refresh is the same reconcile the notice prescribes, so it
   * closes the notice too — otherwise the gate would stay shut after the user
   * had already done the thing the notice asked for.
   */
  const refreshEntries = useCallback(async () => {
    if (!selectedBookId) return
    if (bulkNotice) {
      await reloadBulkEntries(bulkNotice)
      return
    }
    await loadEntries(selectedBookId)
  }, [bulkNotice, loadEntries, reloadBulkEntries, selectedBookId])

  const createBook = useCallback(async () => {
    const book = await worldBooksApi.create({ name: 'New Lorebook' })
    setBooks((current) => [book, ...current])
    setSelectedBookId(book.id)
  }, [])

  const createEntry = useCallback(async () => {
    if (!selectedBookId) return
    const entry = await worldBooksApi.createEntry(selectedBookId, {
      comment: 'New Entry',
      key: [],
      content: '',
    })
    commitEntries((current) => [entry, ...current])
    setSelectedEntryId(entry.id)
  }, [commitEntries, selectedBookId])

  const duplicateSelected = useCallback(async () => {
    if (!selectedBookId || selectedIds.length === 0) return
    await runBulk({ action: 'copy', entry_ids: selectedIds, target_book_id: selectedBookId })
  }, [runBulk, selectedBookId, selectedIds])

  const deleteSelected = useCallback(async () => {
    if (selectedIds.length === 0) return
    await runBulk({ action: 'delete', entry_ids: selectedIds })
    setSelectedIds([])
  }, [runBulk, selectedIds])

  /**
   * Duplicate/Delete report their rejection here instead of leaving it
   * unhandled: the shared runner rethrows so a failed reload keeps the
   * selection, and the retry is always the user's next click.
   */
  const reportBulkActionFailure = useCallback((action: 'duplicate' | 'delete') => {
    const label = action === 'delete' ? 'Delete' : 'Duplicate'
    addToast({ type: 'error', message: `${label} failed. Reload the entries before trying again.` })
  }, [addToast])

  const toggleEntrySelection = (entryId: string) => {
    setSelectedIds((current) => current.includes(entryId)
      ? current.filter((id) => id !== entryId)
      : [...current, entryId])
  }

  const toggleSelectAll = () => {
    const filteredIds = filteredEntries.map((entry) => entry.id)
    setSelectedIds((current) => allFilteredSelected
      ? current.filter((id) => !filteredIds.includes(id))
      : [...new Set([...current, ...filteredIds])])
  }

  return (
    <section
      className={clsx(styles.workspace, variant === 'half' && styles.halfWorkspace)}
      onKeyDownCapture={handleWorkspaceKeyDown}
      style={{
        '--lorebook-books-width': `${settings.booksPaneWidth}px`,
        '--lorebook-entries-width': `${variant === 'half' ? settings.halfEntriesPaneWidth : settings.entriesPaneWidth}px`,
        '--lorebook-inspector-width': `${settings.inspectorPaneWidth}px`,
      } as React.CSSProperties}
      data-density={settings.rowDensity}
      data-component="LorebookEditorWorkspace"
    >
      <header className={styles.workspaceHeader}>
        <div className={styles.headerIdentity}>
          <BookOpen size={18} />
          <div>
            <strong>World Book Editor</strong>
            <span>{selectedBook?.name ?? 'Select a lorebook'}</span>
          </div>
        </div>
        <div className={styles.headerActions}>
          <label className={styles.displayToggle}>
            <span>Trigger display</span>
            <select
              value={settings.triggerDisplay}
              onChange={(event) => updateSettings({ triggerDisplay: event.target.value as 'words' | 'icons' })}
            >
              <option value="words">Words</option>
              <option value="icons">Icons</option>
            </select>
          </label>
          {onImportRequest && (
            <button type="button" onClick={onImportRequest} title="Import a lorebook" aria-label="Import a lorebook">
              <Upload size={14} />
              {variant === 'full' && 'Import'}
            </button>
          )}
          {variant === 'half' && (
            <button
              type="button"
              onClick={() => onOpenFullEditor?.(selectedBookId, selectedEntryId)}
              title="Full-Screen Lorebook Editor"
              aria-label="Full-Screen Lorebook Editor"
            >
              <ExternalLink size={14} />
            </button>
          )}
          {onToggleFullscreen && (
            <button
              type="button"
              onClick={onToggleFullscreen}
              title={fullscreen ? 'Restore editor' : 'Fullscreen editor'}
              aria-label={fullscreen ? 'Restore editor' : 'Fullscreen editor'}
            >
              {fullscreen ? <Minimize2 size={14} /> : <Maximize2 size={14} />}
            </button>
          )}
          <button
            type="button"
            className={styles.primaryButton}
            onClick={() => void createEntry()}
            disabled={!selectedBookId}
            title="New entry"
          >
            <Plus size={14} />
            {variant === 'full' && 'New Entry'}
          </button>
          {onClose && (
            <button type="button" onClick={onClose} title="Close editor" aria-label="Close editor">
              <X size={14} />
              {variant === 'full' && 'Close'}
            </button>
          )}
        </div>
      </header>
      <span
        data-spindle-mount="lorebook_workspace"
        data-spindle-scope={`lorebook:${selectedBookId ?? 'none'}:workspace`}
        className={styles.spindleWorkspaceMount}
      />

      <div className={styles.panes} ref={panesRef}>
        {variant === 'full' && (
          <>
            <aside className={styles.booksPane}>
              <div className={styles.paneTitle}><span>Books</span><span>{books.length}</span></div>
              <label className={styles.searchField}>
                <Search size={14} />
                <input value={bookSearch} onChange={(event) => setBookSearch(event.target.value)} placeholder="Search books..." />
              </label>
              <div className={styles.scrollList}>
                {filteredBooks.map((book) => (
                  <button
                    type="button"
                    key={book.id}
                    className={clsx(styles.bookRow, book.id === selectedBookId && styles.activeRow)}
                    onClick={() => setSelectedBookId(book.id)}
                  >
                    <BookOpen size={14} />
                    <span>{book.name}</span>
                  </button>
                ))}
              </div>
              <button type="button" className={styles.bottomAction} onClick={() => void createBook()}>
                <Plus size={14} /> New Book
              </button>
            </aside>
            <div
              className={styles.splitter}
              onPointerDown={(event) => {
                splitterDrag.current = { pane: 'books', startX: event.clientX, startWidth: settings.booksPaneWidth }
              }}
            />
          </>
        )}

        <div className={styles.entriesPane}>
          <div className={styles.paneTitle}>
            <input
              type="checkbox"
              className={styles.selectAllBox}
              checked={allFilteredSelected}
              onChange={toggleSelectAll}
              disabled={filteredEntries.length === 0}
              aria-label="Select all listed entries"
              title="Select all listed entries"
            />
            <span className={styles.paneTitleLabel}>Entries</span>
            {selectedIds.length > 0 && <span className={styles.paneTitleCount}>{selectedIds.length} selected</span>}
            <div className={styles.paneTitleActions}>
              <span>{filteredEntries.length === entries.length ? entries.length : `${filteredEntries.length}/${entries.length}`}</span>
              <button
                type="button"
                onClick={toggleTokenColumn}
                title={showTokens ? 'Hide token column' : 'Show token column'}
                aria-label={showTokens ? 'Hide token column' : 'Show token column'}
              >
                {showTokens ? <Eye size={13} /> : <EyeOff size={13} />}
                Tokens
              </button>
            </div>
          </div>

          <EntriesToolbar
            variant={variant}
            books={books}
            selectedBookId={selectedBookId}
            setSelectedBookId={setSelectedBookId}
            onCreateBook={() => void createBook()}
            entrySearch={entrySearch}
            setEntrySearch={setEntrySearch}
            entrySearchInputRef={entrySearchInputRef}
            searchActive={searchActive}
            matchCount={filteredEntries.length}
            totalEntryCount={entries.length}
            bulkVisible={bulkVisible}
            setBulkVisible={setBulkVisible}
            entryCount={queryEntries.length}
            typeCounts={typeCounts}
            typeFilter={typeFilter}
            setTypeFilter={setTypeFilter}
            selectedIds={selectedIds}
            bulkPriority={bulkPriority}
            setBulkPriority={setBulkPriority}
            bulkPosition={bulkPosition}
            setBulkPosition={setBulkPosition}
            bulkDepth={bulkDepth}
            setBulkDepth={setBulkDepth}
            bulkTrigger={bulkTrigger}
            setBulkTrigger={setBulkTrigger}
            bulkEnabled={bulkEnabled}
            setBulkEnabled={setBulkEnabled}
            // The toolbar's `bulkHasMutation` prop is the button's `disabled`
            // contract, so the reconciliation gate is folded into it here rather
            // than by adding a prop. False also hides the "Set at least one field"
            // title, which is only accurate while the notice is absent.
            bulkHasMutation={bulkApplyEnabled}
            applyBulk={applyBulk}
          />

          {bulkNotice && (
            <div className={styles.conflictBanner} role="alert" data-bulk-notice={bulkNotice.kind}>
              <strong>
                {bulkNotice.kind === 'conflict'
                  ? 'Bulk update conflicted.'
                  : 'Bulk update could not be confirmed.'}
              </strong>
              <span>
                {bulkNotice.kind === 'conflict'
                  ? `${bulkNotice.conflictCount} selected ${bulkNotice.conflictCount === 1 ? 'entry has' : 'entries have'} a newer server revision, so nothing from this Apply was written. Reload the entries, keep the bulk fields, then Apply again.`
                  : bulkNotice.kind === 'refresh-failed'
                    ? 'Your changes are on the server. Reload the entries before the next Apply so it is not built from stale revisions.'
                    : 'The request may or may not have been written. Reload the entries before applying again so nothing is applied against stale revisions.'}
              </span>
              <button type="button" onClick={() => void reloadBulkEntries(bulkNotice)}>Reload entries</button>
            </div>
          )}

          <EntryTable
            bookId={selectedBookId}
            entries={entries}
            filteredEntries={filteredEntries}
            searchResultsById={entrySearchResultsById}
            searchActive={searchActive}
            searchQuery={entrySearch}
            typeFilter={typeFilter}
            onClearSearch={() => setEntrySearch('')}
            onClearTypeFilter={() => setTypeFilter('all')}
            loading={loading}
            reorderEnabled={reorderEnabled}
            onReorder={reorderEntries}
            visibleColumns={visibleColumns}
            entryGridTemplate={entryGridTemplate}
            entryTableMinWidth={entryTableMinWidth}
            selectedEntryId={selectedEntryId}
            setSelectedEntryId={setSelectedEntryId}
            selectedIds={selectedIds}
            toggleEntrySelection={toggleEntrySelection}
            triggerDisplay={settings.triggerDisplay}
            saveEntry={saveEntry}
            onEntryPointerEnter={handleEntryPointerEnter}
            onEntryPointerLeave={handleEntryPointerLeave}
            resolveTokenCount={resolveTokenCount}
          />
          <div className={styles.listActions}>
            <button type="button" onClick={() => void duplicateSelected().catch(() => reportBulkActionFailure('duplicate'))} disabled={selectedIds.length === 0}><Copy size={13} /> Duplicate</button>
            <button type="button" onClick={() => void deleteSelected().catch(() => reportBulkActionFailure('delete'))} disabled={selectedIds.length === 0}><Trash2 size={13} /> Delete</button>
            <button type="button" onClick={() => selectedBookId && void refreshEntries()}><RefreshCw size={13} /> Refresh</button>
          </div>
        </div>

        <div
          className={styles.splitter}
          onPointerDown={(event) => {
            splitterDrag.current = {
              pane: 'entries',
              startX: event.clientX,
              startWidth: variant === 'half' ? settings.halfEntriesPaneWidth : settings.entriesPaneWidth,
            }
          }}
        />

        <aside className={styles.inspectorPane}>
          <div className={styles.paneTitle}>
            <span>Editing Entry</span>
            <span>{savedAt ? 'Saved' : ''}</span>
          </div>
          <div className={styles.inspectorBody}>
            {selectedEntry ? (
              <>
                {conflicts[selectedEntry.id] && (
                  <div className={styles.conflictBanner} role="alert">
                    <strong>Newer server revision detected.</strong>
                    <span>Your unsaved draft is preserved.</span>
                    <button type="button" onClick={() => void resolveConflict(selectedEntry.id, true)}>Reapply draft</button>
                    <button type="button" onClick={() => void resolveConflict(selectedEntry.id, false)}>Use server version</button>
                  </div>
                )}
                {/* Keyed on id + conflict state only. Including the revision remounted
                    the editor on every background save — including the automatic token
                    estimate — which reset local field state mid-edit. */}
                <WorldBookEntryEditor
                  key={`${selectedEntry.id}:${conflicts[selectedEntry.id] ? 'conflict' : 'clean'}`}
                  entry={selectedEntry}
                  onUpdate={debouncedSaveEntry}
                  onImmediateUpdate={saveEntry}
                  density="compact"
                />
              </>
            ) : (
              <div className={styles.empty}>Select an entry to edit.</div>
            )}
          </div>
        </aside>
      </div>
    </section>
  )
}

/*
 * Chrome for the half-screen editor's host element only. The workspace it wraps
 * is dressed by `LorebookEditorLayout.module.css`; these rules were split out of
 * that file so the host and the workspace can be worked on independently.
 */

/*
 * Sits in the chat flex row. It must never claim more than the row can give,
 * or the editor is pushed past the viewport and clipped on both edges — the
 * `min-width` used to win over the row and force exactly that.
 *
 * The real clamp is `resolveHalfEditorLayout` in JS, which measures
 * `.chatColumn + this host` and knows the user's configured `minChatWidth`.
 * `max-width` here is only the backstop for the frame between a layout change and
 * the ResizeObserver callback.
 *
 * It is a **percentage**, not `calc(100vw - …)`. `vw` is viewport-relative and
 * completely unaffected by `body > * { zoom: var(--lumiverse-ui-scale) }`
 * (`theme/reset.css`), so the old `calc(100vw - 240px)` was too permissive by the
 * whole scale factor and measured a box this element does not live in. A
 * percentage resolves against the containing block — the chat flex row — which is
 * both the correct box and zoom-proof.
 */
.halfScreenHost {
  position: relative;
  width: var(--lorebook-half-width, 720px);
  min-width: 0;
  max-width: min(
    var(--lorebook-half-width, 720px),
    calc(100% - var(--lorebook-min-chat-width, 420px))
  );
  height: 100%;
  flex: 0 1 auto;
  border-left: 1px solid var(--lumiverse-border);
  overflow: hidden;
}

/*
 * Overlay: the row is narrower than `minChatWidth + minEditorPaneWidth`, so a
 * usable chat and a usable editor cannot coexist. The editor takes the whole row
 * deliberately and says so, rather than squeezing chat to a sliver with nothing on
 * screen explaining why.
 *
 * There is no scrim element: at this size the chat column has been reduced to zero
 * width, so there is nothing left underneath to scrim. What distinguishes the state
 * instead is the raised shadow (the panel reads as *over* the chat rather than
 * beside it) and the removal of the resize handle — the row cannot be split, so
 * offering a splitter would be a control that cannot do anything.
 */
.halfScreenHost[data-layout='overlay'] {
  /* `width` deliberately still comes from the resolved var — it is the measured
     row, whereas `100%` here would be `.body`, which also spans the portrait
     panels. Only the cap has to go. */
  max-width: 100%;
  box-shadow: -18px 0 42px rgb(0 0 0 / 42%);
}

.halfScreenHost[data-layout='overlay'] .halfResizeHandle {
  display: none;
}

.halfResizeHandle {
  position: absolute;
  inset: 0 auto 0 0;
  z-index: 4;
  width: 7px;
  cursor: col-resize;
  touch-action: none;
}

.halfResizeHandle::after {
  content: "";
  position: absolute;
  inset: 42% 2px;
  border-radius: 999px;
  background: var(--lumiverse-primary);
  opacity: 0.55;
}

/*
 * Free-floating mode (`halfEditorMode: 'floating'`).
 *
 * `ResizablePanelFrame` is `position: fixed`, so the host leaves the flex row
 * entirely and the chat column reclaims the full width — which is why floating mode
 * needs no width reservation at all. The frame's own z-index is 50, inside
 * `.body`'s (`z-index: 2`) stacking context; the composer's `.container` is 20 and
 * `.chatToolbar` is 8 in that same context, so 60 here clears both with headroom
 * without escaping the chat surface.
 *
 * The selector is doubled on purpose. `.frame` and this class have identical
 * specificity and live in different CSS Modules, so which one wins would be
 * decided by stylesheet injection order — which is not something a component may
 * rely on. Repeating the class makes the override deterministic.
 */
.halfFloatingFrame.halfFloatingFrame {
  z-index: 10006;
}

/*
 * Mobile last resort only. The pane ladder lives in the workspace stylesheet as a
 * container query, because a viewport query cannot see the one dimension the user
 * is changing: the width of the editor itself. This rule stays a viewport query
 * because going full-bleed is a property of the host, not of its content.
 *
 * The rung has to clear `--z-quick-toolbar-floating` (10005): at this size the host
 * owns the entire viewport, and the toolbar is portaled to `document.body`, so at
 * the old 10000 it floated over a surface that had taken the whole screen. The
 * toolbar's own "hide while a modal is up" guard keys on the store's `activeModal`,
 * and the half editor is tracked in `lorebookHalfEditor` instead — it never trips
 * that guard, so the ordering has to be settled here.
 * It stays UNDER LoreIndicator floating (10010), the toolbar customizer popover
 * (10014) and the command palette (10020), which are still reachable over it.
 * `10012` is asserted forbidden by tests/lore-indicator.test.ts.
 */
@media (max-width: 768px) {
  .halfScreenHost {
    position: relative;
    inset: auto;
    z-index: 10006;
    width: 100% !important;
    max-width: 100%;
    min-width: 0;
    flex: 0 0 100%;
    height: 100%;
    max-height: 100%;
    overflow-y: auto;
    border-top: 1px solid var(--lumiverse-border);
    box-shadow: 0 -4px 20px rgba(0, 0, 0, 0.4);
  }

  .halfScreenHost[data-force-half-screen='true'] {
    position: relative;
    inset: auto;
    z-index: 10006;
    width: 100% !important;
    max-width: 100%;
  }

  /*
   * Scoped to this breakpoint on purpose. Clearing the floating toolbar (10005)
   * necessarily clears the modal layer too — SettingsModal is 10001 and ModalShell
   * 10002, so no rung satisfies both. `onOpenFullEditor` promotes this pane to the
   * extension-owned enhanced workspace without leaving the half host over it.
   * Wide layouts must NOT get this rule: there the pane is a flex sibling of the
   * message list, so `display: none` would reflow and re-anchor that list while a
   * backdrop hides the change, and again on close. There it simply paints under
   * the modal, which is already correct.
   */
  .halfScreenHost[data-modal-open='true'] {
    display: none;
  }
}

import { useCallback, useEffect, useRef, useState, type CSSProperties } from 'react'
import { ResizablePanelFrame } from '@/components/shared/ResizablePanelFrame'
import {
  DEFAULT_MIN_CHAT_WIDTH,
  DEFAULT_MIN_EDITOR_PANE_WIDTH,
  resolveHalfEditorLayout,
} from '@/lib/lorebookEditorGeometry'
import { getUiScale as readUiScale } from '@/lib/uiScale'
import type { SurfaceRectPrefs } from '@/types/store'
import LorebookEditorWorkspace from './LorebookEditorWorkspace'
import { useLorebookEditorLayoutSettings } from './useLorebookEditorLayoutSettings'
import styles from './LorebookHalfScreenEditor.module.css'

/**
 * Measures the row the docked editor actually shares with the chat, in layout px.
 *
 * Three things were wrong with the `window.innerWidth` listener this replaces:
 *
 *  1. `window.innerWidth` is the *viewport*, not the row. `.app` reserves the
 *     spindle dock insets (`App.module.css`), so the row is already narrower.
 *  2. It is device px. Under `body > * { zoom: var(--lumiverse-ui-scale) }` the
 *     row's layout width is `viewport / scale`, so at scale 1.25 the clamp was
 *     comparing a number 25% too large against a layout-px width — it permitted
 *     exactly the overrun it existed to prevent.
 *  3. A `resize` listener never fires for a portrait panel opening or a spindle
 *     dock appearing, both of which change the row without changing the window.
 *
 * The observed box is deliberately **`.chatColumn` + the host**, not `.body`:
 * `.body` also contains the portrait side panels and `PortraitDock`
 * (`ChatView.tsx`), which are siblings of both and are never subtracted, so
 * measuring `.body` would let the editor eat the chat's reservation whenever a
 * portrait panel was open.
 *
 * `getBoundingClientRect() / readUiScale()` rather than `entry.contentBoxSize`:
 * whether `contentBoxSize` reports pre- or post-`zoom` units is not something this
 * codebase has verified, and guessing wrong reproduces the bug at every UI scale
 * other than 1 while passing every test at scale 1.
 *
 * The sum cannot oscillate. The chat column is `flex: 1 1 auto` and the host
 * `flex: 0 1 auto`, so the two always partition the same row: changing the host's
 * width moves pixels between the two terms and leaves the total identical.
 */
export function findHalfEditorChatColumn(host: HTMLElement): HTMLElement | null {
  let parent = host.parentElement
  while (parent) {
    const chatColumn = parent.querySelector<HTMLElement>('[data-lumiverse-surface="chat-column"]')
    if (chatColumn) return chatColumn
    parent = parent.parentElement
  }
  return null
}

export function measureHalfEditorRowWidth(
  host: HTMLElement,
  chatColumn: HTMLElement | null,
  scale: number,
): number {
  const normalizedScale = scale || 1
  const hostWidth = host.getBoundingClientRect().width
  const chatWidth = chatColumn?.getBoundingClientRect().width ?? 0
  return Math.round((hostWidth + chatWidth) / normalizedScale)
}

function useRowWidth(
  hostRef: React.RefObject<HTMLElement | null>,
  active: boolean,
): number {
  const [rowWidth, setRowWidth] = useState(0)

  useEffect(() => {
    if (!active) return
    const host = hostRef.current
    if (!host) return
    // ChatView tags the column `data-lumiverse-surface="chat-column"` precisely so
    // this lookup does not depend on sibling order: its class name is
    // CSS-Module-hashed and therefore unqueryable, and matching on
    // `previousElementSibling` alone breaks silently the moment anyone reorders
    // `.body`'s children. The climb is required because the extension mount root
    // and the per-surface React root remain real DOM ancestors even when their CSS
    // uses `display: contents`. `previousElementSibling` remains a legacy fallback.
    const chatColumn = findHalfEditorChatColumn(host)
      ?? (host.previousElementSibling instanceof HTMLElement ? host.previousElementSibling : null)

    const measure = () => {
      setRowWidth(measureHalfEditorRowWidth(host, chatColumn, readUiScale()))
    }

    measure()
    if (typeof ResizeObserver === 'undefined') {
      window.addEventListener('resize', measure)
      return () => window.removeEventListener('resize', measure)
    }
    const observer = new ResizeObserver(measure)
    observer.observe(host)
    if (chatColumn) observer.observe(chatColumn)
    return () => observer.disconnect()
  }, [active, hostRef])

  return rowWidth
}

export interface LorebookHalfScreenEditorProps {
  readonly open: boolean
  readonly bookId?: string | null
  readonly entryId?: string | null
  readonly forceHalfScreen?: boolean
  readonly onClose: () => void
  readonly onOpenFullEditor: (bookId: string | null, entryId: string | null) => void
}

export default function LorebookHalfScreenEditor({
  open,
  bookId = null,
  entryId = null,
  forceHalfScreen = false,
  onClose,
  onOpenFullEditor,
}: LorebookHalfScreenEditorProps) {
  // Only consumed by the <=900px full-bleed rule. At that width this host takes
  // the whole viewport at a rung above the floating toolbar (10006), which puts it
  // above the modal layer too — `onOpenFullEditor` promotes this pane to the
  // extension-owned enhanced workspace. Wide layouts deliberately keep rendering:
  // this pane shares a flex row with the message list, and collapsing it would
  // reflow (and re-anchor) that list behind the backdrop.
  const { settings, updateSettings } = useLorebookEditorLayoutSettings()
  const hostRef = useRef<HTMLElement | null>(null)
  const dragCleanupRef = useRef<(() => void) | null>(null)

  useEffect(() => () => {
    dragCleanupRef.current?.()
    dragCleanupRef.current = null
  }, [])

  const floating = !forceHalfScreen && settings.halfEditorMode === 'floating'
  const minChatWidth = settings.minChatWidth ?? DEFAULT_MIN_CHAT_WIDTH
  const minEditorWidth = settings.minEditorPaneWidth ?? DEFAULT_MIN_EDITOR_PANE_WIDTH

  // The rendered width is derived, so a resize only needs to trigger a re-render.
  // Persisting the clamped value here would quietly shrink the remembered width
  // whenever the editor was opened in a narrow window: a drag is stored *intent*
  // and only a drag may overwrite it.
  const rowWidth = useRowWidth(hostRef, open && !floating)

  const commitWidth = useCallback((width: number) => {
    if (settings.halfRect.width === width) return
    updateSettings({ halfRect: { ...settings.halfRect, width } })
  }, [settings.halfRect, updateSettings])

  const commitRect = useCallback((halfRect: SurfaceRectPrefs) => {
    updateSettings({ halfRect })
  }, [updateSettings])

  if (!open) return null

  const workspace = (
    <LorebookEditorWorkspace
      variant="half"
      initialBookId={bookId}
      initialEntryId={entryId}
      onClose={onClose}
      onOpenFullEditor={onOpenFullEditor}
    />
  )

  if (floating) {
    // Free-floating mode reads the whole `halfRect`, which is what makes the
    // height/X/Y settings mean something. `usePersistentRect` inside the frame is
    // already scale-aware, so there is deliberately no zoom compensation here.
    return (
      <ResizablePanelFrame
        rect={settings.halfRect}
        bounds={{ minWidth: minEditorWidth, minHeight: 260 }}
        onCommit={commitRect}
        showHeader={false}
        aria-label="Lorebook editor"
        className={styles.halfFloatingFrame}
      >
        {workspace}
      </ResizablePanelFrame>
    )
  }

  // A remembered width from a wider window must never push the host past the row —
  // that clipped the editor against both viewport edges. Below
  // `minChatWidth + minEditorPaneWidth` the row cannot hold both, so the editor
  // says so (`overlay`) instead of silently squeezing chat to a sliver.
  const availableWidth = rowWidth || settings.halfRect.width + minChatWidth
  const defaultHalfWidth = Math.max(1, Math.round(availableWidth / 2))
  const requestedWidth = forceHalfScreen && settings.halfRect.width === 720
    ? defaultHalfWidth
    : settings.halfRect.width
  const layout = resolveHalfEditorLayout({
    requestedWidth,
    availableWidth,
    minChatWidth: forceHalfScreen ? 0 : minChatWidth,
    minEditorWidth,
  })

  return (
    <aside
      ref={hostRef}
      className={styles.halfScreenHost}
      data-layout={layout.mode}
      data-force-half-screen={forceHalfScreen || undefined}
      style={{
        '--lorebook-half-width': `${layout.width}px`,
        '--lorebook-min-chat-width': `${forceHalfScreen ? 0 : minChatWidth}px`,
      } as CSSProperties}
      data-component="LorebookHalfScreenEditor"
    >
      <div
        className={styles.halfResizeHandle}
        role="separator"
        aria-label="Resize lorebook editor"
        onPointerDown={(event) => {
          event.preventDefault()
          dragCleanupRef.current?.()
          const startX = event.clientX
          const startWidth = layout.width
          const move = (moveEvent: PointerEvent) => {
            // `clientX` is device px while `startWidth` is layout px, so only the
            // *delta* may be added — and only after the `body > *` zoom is divided
            // out, or the handle travels `scale`x the cursor.
            const scale = readUiScale() || 1
            const requestedWidth = startWidth + (startX - moveEvent.clientX) / scale
            // Only a live drag may persist a clamp: this is the one place a width
            // is the user's intent rather than a consequence of the window size.
            commitWidth(resolveHalfEditorLayout({
              requestedWidth,
              availableWidth: rowWidth || requestedWidth + minChatWidth,
              minChatWidth,
              minEditorWidth,
            }).width)
          }
          const up = () => {
            window.removeEventListener('pointermove', move)
            window.removeEventListener('pointerup', up)
            hostRef.current?.removeEventListener('pointercancel', up)
            if (dragCleanupRef.current === up) dragCleanupRef.current = null
          }
          dragCleanupRef.current = up
          window.addEventListener('pointermove', move)
          window.addEventListener('pointerup', up)
          hostRef.current?.addEventListener('pointercancel', up)
        }}
      />
      {workspace}
    </aside>
  )
}

