import { useStore } from '@/store'
import type { SurfaceRectPrefs } from '@/types/store'

export interface LorebookEditorLayoutSettings {
  defaultVariant: 'full' | 'half'
  triggerDisplay: 'words' | 'icons'
  halfButtonEnabled: boolean
  loreIndicatorActionEnabled: boolean
  allowSimultaneousEditors: boolean
  halfEditorMode: 'docked' | 'floating'
  fullRect: SurfaceRectPrefs
  halfRect: SurfaceRectPrefs
  minChatWidth: number
  minEditorPaneWidth: number
  halfEntriesPaneWidth: number
  booksPaneWidth: number
  entriesPaneWidth: number
  inspectorPaneWidth: number
  rowDensity: 'compact' | 'balanced' | 'spacious'
  visibleEntryMetadata: string[]
  entryMetadataVersion?: number
}

export function getLorebookEditorLayoutSettings(): LorebookEditorLayoutSettings {
  return useStore.getState().lorebookEditorSettings as unknown as LorebookEditorLayoutSettings
}

export function updateLorebookEditorLayoutSettings(patch: Partial<LorebookEditorLayoutSettings>): void {
  const current = useStore.getState().lorebookEditorSettings
  useStore.getState().setSetting('lorebookEditorSettings', {
    ...current,
    ...patch,
    ...(patch.fullRect ? { fullRect: { ...patch.fullRect } } : {}),
    ...(patch.halfRect ? { halfRect: { ...patch.halfRect } } : {}),
    ...(patch.visibleEntryMetadata ? { visibleEntryMetadata: [...patch.visibleEntryMetadata] } : {}),
  } as typeof current)
}

export function useLorebookEditorLayoutSettings() {
  const settings = useStore((state) => state.lorebookEditorSettings as unknown as LorebookEditorLayoutSettings)
  return { settings, updateSettings: updateLorebookEditorLayoutSettings }
}

import { useCallback, useSyncExternalStore } from 'react'
import { useActiveTokenizerModel, useTokenCountSweep } from '@/hooks/useTokenCounts'
import {
  getTokenCountCacheVersion,
  makeTokenCountCacheKey,
  peekTokenCountByKey,
  subscribeTokenCountCache,
} from '@/lib/tokenCountCache'
import { readStoredTokenCount } from '@/lib/storedTokenCount'
import { estimateTokens } from '@/lib/tokenEstimate'
import type { WorldBookEntry } from '@/types/api'

export interface LorebookResolvedTokenCount {
  value: number
  exact: boolean
}

export function useLorebookTokenCounts(entries: readonly WorldBookEntry[], enabled: boolean) {
  const model = useActiveTokenizerModel()
  useTokenCountSweep(entries, enabled)
  useSyncExternalStore(subscribeTokenCountCache, getTokenCountCacheVersion, getTokenCountCacheVersion)

  const resolveTokenCount = useCallback((entry: WorldBookEntry): LorebookResolvedTokenCount => {
    const content = entry.content ?? ''
    if (!model) return { value: estimateTokens(content), exact: false }
    const stored = readStoredTokenCount(entry.extensions, model, content)
    if (stored.exact && stored.count != null) return { value: stored.count, exact: true }
    const cached = peekTokenCountByKey(makeTokenCountCacheKey(model, content))
    if (cached && !cached.approximate) return { value: cached.count, exact: true }
    if (stored.count != null) return { value: stored.count, exact: false }
    if (cached) return { value: cached.count, exact: false }
    return { value: estimateTokens(content), exact: false }
  }, [model])

  return {
    resolveTokenCount,
    handleEntryPointerEnter: (_entryId: string) => undefined,
    handleEntryPointerLeave: (_entryId: string) => undefined,
  }
}

