import type { ThemePack } from './themePack'

const MAX_OVERRIDE_SOURCE_LENGTH = 50_000

const FORBIDDEN_PATTERNS: Array<{ pattern: RegExp; message: string }> = [
  { pattern: /\b(?:window|globalThis|document|ownerDocument|defaultView)\b/, message: 'Global DOM access is not allowed in component overrides.' },
  { pattern: /\b(?:fetch|XMLHttpRequest|WebSocket|EventSource|navigator|sendBeacon)\b/, message: 'Network APIs are not allowed in component overrides.' },
  { pattern: /\b(?:localStorage|sessionStorage|indexedDB|caches|cookie)\b/, message: 'Storage and cookie access are not allowed in component overrides.' },
  { pattern: /\b(?:Function|eval|importScripts|Worker|SharedWorker|ServiceWorker|WebAssembly)\b/, message: 'Dynamic code execution APIs are not allowed in component overrides.' },
  { pattern: /\b(?:postMessage|setTimeout|setInterval|requestAnimationFrame|location|history)\b/, message: 'Navigation and global async APIs are not allowed in component overrides.' },
  { pattern: /\b__proto__\b/, message: 'Prototype escape hatches are not allowed in component overrides.' },
  { pattern: /\.\s*(?:constructor|prototype)\b/, message: 'Constructor and prototype access are not allowed in component overrides.' },
  { pattern: /\[\s*["'](?:constructor|prototype|__proto__)["']\s*\]/, message: 'Constructor and prototype access are not allowed in component overrides.' },
  { pattern: /\b(?:cloneElement|createPortal|findDOMNode)\b/, message: 'DOM manipulation helpers are not allowed in component overrides.' },
  { pattern: /javascript:/i, message: 'javascript: URLs are not allowed in component overrides.' },
  { pattern: /<(?:script|iframe|object|embed)\b/i, message: 'Dangerous HTML tags are not allowed in component overrides.' },
]

export function validateComponentOverrideSource(source: string): { valid: boolean; error?: string } {
  if (source.length > MAX_OVERRIDE_SOURCE_LENGTH) {
    return { valid: false, error: `Override source is too large (max ${MAX_OVERRIDE_SOURCE_LENGTH.toLocaleString()} characters).` }
  }

  for (const { pattern, message } of FORBIDDEN_PATTERNS) {
    if (pattern.test(source)) {
      return { valid: false, error: message }
    }
  }

  return { valid: true }
}

export function disableImportedThemePackTsx(pack: ThemePack): { pack: ThemePack; disabledCount: number } {
  let disabledCount = 0
  const components = Object.fromEntries(
    Object.entries(pack.components).map(([name, override]) => {
      const hasTsx = !!override.tsx.trim()
      if (hasTsx && override.enabled) disabledCount += 1
      return [name, {
        ...override,
        enabled: hasTsx ? false : override.enabled,
      }]
    }),
  ) as ThemePack['components']

  return {
    pack: { ...pack, components },
    disabledCount,
  }
}

sources.src/lib/componentOverrides.ts:
/**
 * Component Override System
 *
 * Provides the infrastructure for users to replace built-in components
 * with custom TSX implementations.  Each interpreted override receives a
 * stable flattened props contract. Callback props may only be used as
 * allowlisted symbolic event bindings such as onClick={actions.copy}.
 *
 * Rich/interactive content (formatted markdown, reasoning, attachments) is not
 * exposed as a string — the sandbox forbids dangerouslySetInnerHTML. Instead,
 * overrides render it through built-in slot tags (`<Content />`, `<Reasoning />`,
 * `<Attachments />`) which the runtime fills with the real host components.
 */

export interface ComponentOverride {
  css: string
  tsx: string
  enabled: boolean
}

// ── Props contracts ─────────────────────────────────────────────────

/** sm (~300px) / lg (~700px) / full (original resolution) variants of one image. */
export interface OverrideAvatarTiers {
  sm: string | null
  lg: string | null
  full: string | null
}

/**
 * Both avatar variants at every size tier, so themes can pick exactly what they
 * need: a `cropped` 1:1 square (good for round/square frames) or the `original`
 * uploaded aspect ratio (good for full-bleed portraits).
 */
export interface OverrideAvatar {
  /** User-cropped 1:1 square variant (falls back to the original when no crop exists). */
  cropped: OverrideAvatarTiers
  /** Original uploaded image at its native aspect ratio. */
  original: OverrideAvatarTiers
}

export interface OverrideMessageInfo {
  id: string
  index: number
  sendDate: number
  isUser: boolean
  displayName: string
  /** First character of `displayName`, uppercased ('?' when empty). Handy for avatar fallbacks — the AST sandbox cannot slice strings itself. */
  initial: string
  /**
   * Convenience source selected by the active layout. This is normally the
   * cropped sm/lg tier, but follows that layout's "Use full-size avatars"
   * preference and becomes the original full-resolution source when enabled.
   * See `avatar` for an explicit variant and tier.
   */
  avatarUrl: string | null
  /** Convenience: original aspect ratio at full resolution. See `avatar` for an explicit tier. */
  fullAvatarUrl: string | null
  /** Cropped/original avatar URLs across all size tiers. */
  avatar: OverrideAvatar
  isHidden: boolean
  isContextAnchor: boolean
  isStreaming: boolean
  isLastMessage: boolean
  tokenCount: number | null
}

export interface OverrideContent {
  /**
   * Raw markdown source. To render the fully-formatted message (markdown, code
   * highlighting, macros, interactivity) place the `<Content />` slot tag
   * instead — it renders the real built-in content component.
   */
  raw: string
}

export interface OverrideReasoning {
  raw: string
  duration: number | null
  isStreaming: boolean
}

export interface OverrideSwipes {
  current: number
  total: number
}

export interface OverrideAttachment {
  type: 'image' | 'audio'
  imageId: string
  mimeType: string
  filename: string
}

export interface OverrideEditing {
  active: boolean
  content: string
  reasoning: string
  setContent: (s: string) => void
  setReasoning: (s: string) => void
  save: () => void
  cancel: () => void
}

export interface OverrideActions {
  copy: () => void
  edit: () => void
  delete: () => void
  toggleHidden: () => void
  toggleContextAnchor: () => void
  fork: () => void
  promptBreakdown: () => void
  swipeLeft: () => void
  swipeRight: () => void
}

/** Full props contract for BubbleMessage / MinimalMessage overrides. */
export interface MessageOverrideProps {
  message: OverrideMessageInfo
  content: OverrideContent
  reasoning: OverrideReasoning | null
  swipes: OverrideSwipes
  attachments: OverrideAttachment[]
  editing: OverrideEditing
  actions: OverrideActions
  /** CSS module class names from the original component */
  styles: Record<string, string>
}

