## `src/backend.ts`

```ts
declare const spindle: import('lumiverse-spindle-types').SpindleAPI

spindle.onFrontendMessage(async (payload: any, userId) => {
  if (payload.type === 'fetch_external') {
    try {
      const result = await spindle.cors(payload.url, {
        method: 'GET',
        headers: { 'Accept': 'application/json' },
      })
      spindle.sendToFrontend({
        type: 'external_result',
        requestId: payload.requestId,
        data: result,
      }, userId)
    } catch (err: any) {
      spindle.sendToFrontend({
        type: 'external_error',
        requestId: payload.requestId,
        error: err.message,
      }, userId)
    }
  }
})

spindle.log.info('API Bridge loaded!')
```

## `src/frontend.ts`

```ts
import type { SpindleFrontendContext } from 'lumiverse-spindle-types'

export function setup(ctx: SpindleFrontendContext) {
  const removeStyle = ctx.dom.addStyle(`
    .api-bridge-panel {
      padding: 12px;
      background: var(--lumiverse-fill-subtle);
      border-radius: var(--lumiverse-radius);
      margin: 8px;
    }
    .api-bridge-panel input {
      width: 100%;
      padding: 6px 10px;
      background: var(--lumiverse-fill);
      border: 1px solid var(--lumiverse-border);
      border-radius: var(--lumiverse-radius);
      color: var(--lumiverse-text);
      margin-bottom: 8px;
    }
    .api-bridge-result {
      font-size: 12px;
      color: var(--lumiverse-text-muted);
      white-space: pre-wrap;
      max-height: 200px;
      overflow-y: auto;
    }
  `)

  ctx.dom.inject('body', `
    <div class="api-bridge-panel">
      <input class="api-bridge-input" placeholder="Enter URL to fetch..." />
      <div class="api-bridge-result">Results appear here</div>
    </div>
  `)

  const input = ctx.dom.query('.api-bridge-input') as HTMLInputElement
  const result = ctx.dom.query('.api-bridge-result')

  if (input) {
    input.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' && input.value.trim()) {
        ctx.sendToBackend({
          type: 'fetch_external',
          url: input.value.trim(),
          requestId: crypto.randomUUID(),
        })
        if (result) result.textContent = 'Loading...'
      }
    })
  }

  const unsub = ctx.onBackendMessage((payload: any) => {
    if (result && payload.type === 'external_result') {
      result.textContent = JSON.stringify(payload.data, null, 2)
    } else if (result && payload.type === 'external_error') {
      result.textContent = `Error: ${payload.error}`
    }
  })

  return () => {
    unsub()
    removeStyle()
    ctx.dom.cleanup()
  }
}
```

## How It Works

1. **Frontend** injects a panel with a URL input and result display area
2. When the user presses Enter, the frontend sends a `fetch_external` message to the backend with a unique request ID
3. **Backend** receives the message, uses the CORS proxy to fetch the URL, and sends the result back
4. **Frontend** displays the JSON response or error message
5. Both modules coordinate via the `type` field in messages

docs.developer-docs/examples/prompt-intercept:
# Prompt Interceptor Extension

An extension that prepends a tone directive to every generation, configurable from the frontend.

## `spindle.json`

```json
{
  "version": "1.0.0",
  "name": "Tone Adjuster",
  "identifier": "tone_adjuster",
  "author": "Dev",
  "github": "https://github.com/dev/tone-adjuster",
  "homepage": "https://github.com/dev/tone-adjuster",
  "permissions": ["interceptor"],
  "entry_backend": "dist/backend.js"
}
```

## `src/backend.ts`

```ts
declare const spindle: import('lumiverse-spindle-types').SpindleAPI

// Load saved tone from storage, default to 'neutral'
let currentTone = 'neutral'

;(async () => {
  try {
    currentTone = await spindle.storage.read('tone.txt')
  } catch {
    // File doesn't exist yet, use default
  }
})()

spindle.registerInterceptor(async (messages, context) => {
  if (currentTone === 'neutral') return messages

  const injected = {
    role: 'system' as const,
    content: `[Tone directive] Respond in a ${currentTone} tone.`,
  }

  // Prepend a system instruction about tone and expose it in Prompt Breakdown
  return {
    messages: [injected, ...messages],
    breakdown: [
      {
        messageIndex: 0,
        name: 'Tone Directive',
      },
    ],
  }
}, 10) // Low priority = runs early

// Listen for tone changes from the frontend
spindle.onFrontendMessage(async (payload: any, userId) => {
  if (payload.type === 'set_tone') {
    currentTone = payload.tone
    await spindle.storage.write('tone.txt', currentTone)
    spindle.sendToFrontend({ type: 'tone_updated', tone: currentTone }, userId)
    spindle.log.info(`Tone set to: ${currentTone}`)
  }
})

spindle.log.info('Tone Adjuster loaded!')
```

## How It Works

1. Loads the saved tone preference from storage on startup
2. Registers an interceptor with priority `10` (runs early in the chain)
3. If tone is not `neutral`, prepends a system message with the tone directive
4. Marks that injected message as a Prompt Breakdown block so users can see it in dry-run and saved breakdown views
5. Listens for `set_tone` messages from the frontend to update the tone
6. Persists the tone choice to storage so it survives restarts

---

# Structured Prefill Interceptor

An extension that injects `response_format` into the user's normal chat generation to enforce structured output via an interceptor.

## `spindle.json`

```json
{
  "version": "1.0.0",
  "name": "Structured Prefill",
  "identifier": "structured_prefill",
  "author": "Dev",
  "github": "https://github.com/dev/structured-prefill",
  "homepage": "https://github.com/dev/structured-prefill",
  "permissions": ["interceptor", "generation_parameters"],
  "entry_backend": "dist/backend.js"
}
```

## `src/backend.ts`

```ts
declare const spindle: import('lumiverse-spindle-types').SpindleAPI

spindle.registerInterceptor(async (messages, context) => {
  // Look for an assistant prefill at the end of the prompt
  const last = messages[messages.length - 1]
  if (!last || last.role !== 'assistant') {
    // No prefill — pass through unchanged
    return messages
  }

  const prefillText = last.content

  // Remove the prefill message from the prompt
  const filtered = messages.slice(0, -1)

  // Inject a json_schema that forces the model to start with the prefill text
  return {
    messages: filtered,
    parameters: {
      response_format: {
        type: 'json_schema',
        json_schema: {
          name: 'prefilled_response',
          strict: true,
          schema: {
            type: 'object',
            properties: {
              text: {
                type: 'string',
                pattern: `^${escapeRegex(prefillText)}`,
              },
            },
            required: ['text'],
          },
        },
      },
    },
  }
}, 200) // High priority number = runs late, after other interceptors

function escapeRegex(str: string): string {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

spindle.log.info('Structured Prefill loaded!')
```

## How It Works

1. Registers an interceptor with priority `200` (runs late so other interceptors process first)
2. Checks if the last message is an assistant-role prefill
3. If found, removes the prefill message and returns an `InterceptorResultDTO` with a `response_format` parameter that forces the LLM output to begin with the prefill text
4. The `generation_parameters` permission allows the `parameters` field to be merged into the outgoing request
5. Works with any OpenAI-compatible provider that supports `response_format: { type: "json_schema" }`

docs.developer-docs/frontend-api/composer.md:
# Chat composer

`ctx.composer` reads and writes the draft in the chat composer (the message input of the open chat) and sends it through the host's own send path. Use it for dictation, quick-insert tools and voice commands instead of editing the textarea through the DOM.

Feature-detect both the optional API and the `composer-v1` host capability for compatibility with older hosts:

```ts
import type { SpindleFrontendContext } from 'lumiverse-spindle-types'

export function setup(ctx: SpindleFrontendContext) {
  const composer = ctx.composer
  if (!composer || !(ctx.host.capabilities['composer-v1'] >= 1)) return

  const stop = composer.onChange((state) => {
    if (state.mounted) console.log(`draft for ${state.chatId}: ${state.text.length} chars`)
  })

  // Later, for example after speech-to-text:
  if (composer.getState().mounted) {
    composer.insertText('She nods slowly. ')
    composer.focus()
  }
}
```

| Member | Permission | Behavior |
|--------|-----------|----------|
| `getState()` | Free | `{ mounted, chatId, text }`. Returns `{ mounted: false, chatId: null, text: '' }` when no composer is on screen. |
| `onChange(handler)` | Free | Calls `handler` with the new state after the draft, the chat or the mounted state changes (typing, host actions, other extensions). Changes in the same task are delivered once. Returns an unsubscribe function. |
| `setText(text)` | Free | Replaces the draft. |
| `insertText(text, { at })` | Free | `at: 'caret'` (default) replaces the current selection and puts the caret after the new text; `'end'` appends. The text is inserted as is: add spaces or line breaks yourself. |
| `focus()` | Free | Focuses the composer textarea. |
| `send()` | `generation` | Does what the Send button does (see below). |

`setText` and `insertText` apply synchronously: `getState()` and `send()` right after them see the new draft. Editing the draft is free because nothing leaves the browser until the user (or a `generation`-gated `send()`) sends it. When the user has draft saving on, the host saves the new draft like a typed one.

### Calling from React effects

The synchronous writes use [React's `flushSync`](https://react.dev/reference/react-dom/flushSync). Call `setText` and `insertText` from event handlers, asynchronous callbacks, or `onChange` handlers. When calling from a React effect or lifecycle callback, defer the write and any dependent reads or sends to a microtask, after React has finished committing:

```tsx
useEffect(() => {
  let active = true
  queueMicrotask(() => {
    if (active && composer.getState().mounted) {
      composer.setText(transcript)
      // getState() or send() here sees the updated draft.
    }
  })
  return () => { active = false }
}, [composer, transcript])
```

Calling a synchronous write directly inside an effect produces a React warning; the new draft is applied on a later render, so an immediate read or send can still use the previous draft.

## Sending

`send()` runs the host's send path for the open chat, the same one as the Send button and Enter:

- the message uses the active persona's name and id (none in temporary chats), and includes pending attachments;
- in group chats, `@mentions` pick and queue the responding members, as when typing;
- in multiplayer rooms, turn and freeform-window rules apply;
- an empty draft without attachments asks for a fresh reply, like an empty Send.

It resolves when the host has created the message and started the generation. It rejects with `COMPOSER_BUSY` if a send or a generation is already running in this chat. Host-side failures (for example, the provider rejects the request) are shown to the user as toasts, as for the Send button, and do not reject.

## Errors

- `setText`, `insertText`, `focus` and `send` throw `COMPOSER_UNAVAILABLE` when no composer is mounted (for example, outside a chat page, or while an extension replaces the `InputArea` component). `getState()` never throws for this; check `mounted`.
- `send()` rejects with `PERMISSION_DENIED:generation` without the `generation` permission.
- Calls after frontend unload throw `SPINDLE_FRONTEND_INACTIVE`. `onChange` subscriptions end when the frontend unloads.

docs.developer-docs/frontend-api/message-prev:
# Message previews

Mount Lumiverse's native message renderer in an extension-owned UI root to preview a stored swipe or a source range. This includes display preprocessing, the active chat's display resolver, display regex, Markdown, and sanitized HTML islands. The preview follows host formatting and theme settings.

```ts
const supported = ctx.components.listHostSurfaces().some(surface => surface.id === 'message_preview')
if (supported) {
  const preview = ctx.components.mountHostSurface(container, 'message_preview', {
    chatId,
    messageId,
    swipeIndex: 1,
    start: islandStart,
    end: islandEnd,
  })
  // Replace the complete props object when selecting another source.
  preview.update({ chatId, messageId, swipeIndex: 0 })
  // Destroy when the containing preview closes.
  preview.destroy()
}
```

`chatId` and `messageId` are required and must identify a message loaded in the active chat. `swipeIndex` defaults to the message's active swipe. `start` defaults to zero; `end` defaults to the source length. Offsets use JavaScript UTF-16 string indices and describe a half-open range `[start, end)`. Choose complete resolver envelopes or HTML islands when previewing a fragment: display rules run against the selected source range, so rules anchored to a complete message can produce different output for a fragment.

The caller cannot provide arbitrary HTML or another chat's content. The host reads its current canonical source. If the loaded message has a light swipe projection, the host fetches that message's complete swipe set without changing chat state. Pending requests are ignored after navigation, source changes, or unmount. Missing messages, stale/out-of-bounds ranges, or chat navigation display an unavailable notice. If the message changes while a preview is open, its current source is used; saving an extension's edited result still needs its own revision checks.

The surface has no additional permission requirement beyond mounting within the caller's live UI root. It uses the existing host-component ownership and teardown rules, including update/destroy and extension unload. Tag interceptors are not delivered, shared message widgets are not mounted, regex send/append/effects actions do not activate, and long-message expansion does not alter the original chat's state. Disclosure controls, code copying, image viewing, and the normal display-resolution callbacks retain their existing presentation behavior. This is a display preview, not a sandbox for executing scripts or a guarantee that a third-party display resolver is side-effect-free.

Feature-detect this surface before mounting it on older hosts. Its props are JSON-only and use the existing `mountHostSurface` interface; no private frontend imports are needed.

docs.developer-docs/frontend-api/speech-to-te:
# Speech-to-text

`ctx.stt` exposes Lumiverse's speech stack to frontend extensions. Choose `whistle`
for transcription entirely on the device, `webspeech` for the browser's Web Speech
API, or `connection` for a configured STT connection. Omitting `provider` uses the
user's current Voice & Speech selection. These calls do not change that selection.

Whistle's model and runtime ship with Lumiverse. They download from the current
Lumiverse instance and share the same cache and worker used by chat. No API key,
external service, or separate model installation is needed for Whistle.

## Availability and permission

Feature-detect `ctx.stt` and `ctx.host.capabilities['speech-to-text-v1'] >= 1`.
`lumiverse-spindle-types` 0.6.39 declares the optional API and exports its options,
session, transcript, provider, PCM, audio frame, and status types. It remains
optional for compatibility with older hosts and API mocks. Version 0.6.55 declares
`keywords`, `words`, `onHostActivity`, and `isHostCapturing`; feature-detect them with the
`speech-to-text-options-v1` capability.

Declare `"media"` in `spindle.json`. `listProviders()` is free; `prepare()`,
`start()`, and `transcribe()` require that permission. Recording also uses the
browser or desktop webview's normal microphone permission. Provider discovery
and preparation never request microphone access. Microphone access remains
disabled inside sandboxed extension iframes; call the host API from the extension
frontend and forward the resulting text to the iframe when needed.

```ts
const stt = ctx.stt;
if (!stt || (ctx.host.capabilities['speech-to-text-v1'] ?? 0) < 1) return;

const whistle = stt.listProviders().find((provider) => provider.id === 'whistle');
if (!whistle?.available) return;

// Optional: prepare while the extension UI is idle, without opening the microphone.
void stt.prepare({ provider: 'whistle' }).catch(showError);

let session: ReturnType<typeof stt.start> | undefined;
recordButton.addEventListener('click', () => {
  try {
    session = stt.start({
      provider: 'whistle',
      language: 'en',
      continuous: true,
      onStatus: (status) => updateStatus(status.phase, status.progress),
      onAudioFrame: (frame) => updateMeter(frame.amplitude),
    });
    void session.ready.catch(showError);
    void session.result.then(({ text }) => updateInput(text)).catch((error) => {
      if (error.name !== 'AbortError') showError(error);
    });
  } catch (error) { showError(error); }
});
stopButton.addEventListener('click', () => { void session?.stop().catch(showError); });
cancelButton.addEventListener('click', () => session?.cancel());
```

Call `start()` directly in the user's button handler so audio startup keeps the
browser's user gesture. Microphone capture begins independently of Whistle model
preparation, preserving opening speech while the model loads. A slow or missing
AudioWorklet uses the same fallback capture as chat.

## API

| Method | Behavior |
| --- | --- |
| `listProviders()` | Returns fresh provider descriptors: `id`, `name`, `onDevice`, `available`, optional `unavailableReason` and `languages`, and `supportsAudioTranscription`. Availability describes microphone capture with current settings; explicit connection overrides and supplied audio are validated separately. |
| `prepare(options?)` | Prepares Whistle's shared runtime/model without a microphone request. Other providers validate availability and require no model preparation. |
| `start(options?)` | Starts capture immediately and returns a session with `provider`, `ready`, `result`, `stop()`, and `cancel()`. |
| `transcribe(audio, options?)` | Transcribes supplied audio without a microphone request. Whistle accepts a browser-decodable `Blob` or `{ samples: Float32Array, sampleRate: number }` mono PCM. Connections accept a `Blob`. Web Speech does not support supplied audio. |
| `onHostActivity(listener)` | Free. Calls `listener(true)` when the chat composer's own microphone session starts and `listener(false)` when it ends. Returns an unsubscribe function. Available with `speech-to-text-options-v1`. |
| `isHostCapturing()` | Free. `true` while the chat composer's own microphone session is active. Available with `speech-to-text-options-v1`. |

All processing methods accept `provider`, `language`, `connectionId`, `signal`,
and `onStatus`. Language and connection default to the user's Voice settings.
Whistle supports `en`, `de`, `fr`, `es`, `it`, `nl`, and `pl`; locale suffixes such
as `en-US` are normalized; `auto` and unsupported languages use automatic detection.

Capture also accepts `continuous`, `interimResults`, `onResult`, and
`onAudioFrame`. `continuous` defaults to `false`, finishing after confirmed speech
followed by silence. Set it to `true` for explicit stop-button recording.
`interimResults` defaults to the user's preference. `onResult` delivers engine
segments: append final segments and replace the pending segment on each interim
update. `session.result` assembles the complete transcript for you. Status phases
are `loading`, `listening`, and `processing`; loading may include progress from
zero to one. Transcripts contain `text`, `provider`, and optional `language`.

```ts
const transcript = await ctx.stt!.transcribe(audioBlob, {
  provider: 'whistle',
  language: 'en',
  signal: abortController.signal,
});

// PCM is copied/resampled; the caller's buffer is never transferred or detached.
const fromPcm = await ctx.stt!.transcribe({
  samples: monoSamples,
  sampleRate: 48000,
}, { provider: 'whistle' });
```

### Keywords and word timings

With `ctx.host.capabilities['speech-to-text-options-v1'] >= 1`, `transcribe()` also
accepts two options:

- `keywords`: names and words to favour, such as character names. Up to 500 entries,
  each 1-100 characters after trimming, without line breaks or NUL characters.
  Other values reject with `STT_OPTIONS_INVALID`.
- `words: true`: the transcript also has `words`, a list of `{ word, start, end, probability }`.
  `start` and `end` are seconds from the start of the supplied audio, `probability` is the
  decoder's confidence from 0 to 1. Words keep their punctuation (`"one."`).

Only Whistle uses these options. STT connections ignore `keywords` and return no `words`;
check `transcript.words` before using it. Capture with `start()` does not take them.

```ts
const transcript = await ctx.stt!.transcribe(audioBlob, {
  provider: 'whistle',
  language: 'en',
  keywords: ['Lumi', 'Seo-yeon'],
  words: true,
});
const unsure = transcript.words?.filter((word) => word.probability < 0.5) ?? [];
```

Whistle supplied audio is limited to ten minutes and 64 MiB for encoded input.
PCM sample rates must be between 8 kHz and 192 kHz. Long audio uses sequential
bounded windows with overlap. Encoded format support follows the host's audio
decoder. Whistle processes audio locally; STT connections send audio to the
configured provider and Web Speech's processing location depends on the browser.

## Cleanup and cancellation

`stop()` is idempotent: it stops capture and waits for the final transcript.
Stopping during startup finishes immediately after the microphone becomes ready.
`cancel()` releases capture immediately, discards pending results, and rejects
pending session promises with `AbortError`. An `AbortSignal` cancels the local
operation without cancelling another consumer's shared Whistle preparation.

Only one extension recording session can own the microphone in a document at a
time; another start fails with `STT_BUSY`. The chat composer's microphone button does
not take part in this lock. An extension that listens all the time can pause while
the user dictates with it:

```ts
const unsubscribe = ctx.stt?.onHostActivity?.((active) => {
  if (active) pauseListening();
  else resumeListening();
});
```

The composer session counts as active from the button press until its final
transcription finishes. Recordings started by extensions with `start()` are not
reported. Unload removes the listener. Supplied-audio transcription does not
claim microphone ownership. Unload, reload, tab takeover, and `media` permission
revocation cancel pending operations and suppress late transcripts. Retained
API references from an unloaded extension reject with `SPINDLE_FRONTEND_INACTIVE`.

This API is frontend-only. Backend extension workers can communicate with their
frontend using the existing frontend messaging API when they need transcripts.

docs.developer-docs/frontend-api/system-audio:
# System audio

`ctx.systemAudio` gives a frontend extension a live **spectrum and loudness** of the sound the device is playing, so it can draw music visualisers or react to what the user is listening to. It is analysis only: an extension never receives samples, a `MediaStream`, or anything else that could be used to record or reconstruct what was played.

This is the user's desktop audio, not the microphone and not a tab they share. A web page cannot hear it: browsers expose only the microphone, or a tab or screen the user shares each time. The API therefore works only where the host has a native system-audio adapter: today that is the Lumiverse desktop client on Windows, macOS 14.2+ and Linux with PulseAudio or PipeWire, once the owner has switched it on in the tray (see [Native adapters](#native-adapters)). Everywhere else `isAvailable()` reports `unsupported`, and extensions should treat that as a normal state.

## Availability and permission

Feature-detect `ctx.systemAudio` and `ctx.host.capabilities['system-audio-v1'] >= 1`. `lumiverse-spindle-types` 0.6.43 declares the optional API; 0.6.46 adds the stereo option and channel frame type. The API remains optional for compatibility with older hosts and API mocks.

Declare `"system_audio"` in `spindle.json`. It is a privileged permission and is never auto-granted. `isAvailable()` is free; `start()` requires the permission.

```ts
const audio = ctx.systemAudio;
if (!audio || (ctx.host.capabilities['system-audio-v1'] ?? 0) < 1) return;

const { available, unavailableReason } = audio.isAvailable();
if (!available) {
  showHint(unavailableReason === 'disabled'
    ? 'Tick "Let Extensions Analyse System Audio" in the Lumiverse tray menu to use this.'
    : 'System audio needs the Lumiverse desktop client.');
  return;
}

let session: ReturnType<typeof audio.start> | undefined;
button.addEventListener('click', () => {
  try {
    session = audio.start({
      bands: 32,
      maxFps: 30,
      onFrame: ({ frequencies, amplitude, peak }) => drawBars(frequencies, amplitude, peak),
      onEnd: (reason) => showStopped(reason),
    });
    void session.ready.catch((error) => {
      if (error.name === 'NotAllowedError') showHint('No problem: nothing was started.');
      else if (error.name !== 'AbortError') showError(error);
    });
  } catch (error) { showError(error); }
});
stopButton.addEventListener('click', () => session?.stop());
```

For the first start, call `start()` from a user gesture such as a button handler. If the user explicitly remembers approval in Lumiverse, later starts can reuse it, including after an extension or page reload. An extension may remember whether its visualiser should run, but Lumiverse owns the consent decision.

## API

| Member | Behavior |
| --- | --- |
| `isAvailable()` | Returns `{ available: true }`, or `{ available: false, unavailableReason }` where the reason is `unsupported` (no adapter on this host or device) or `disabled` (an adapter exists, but the user has not switched it on in the desktop client's tray menu). Updated desktop builds also report `stereoSupported: true`, including while disabled. Free. Never prompts and never opens a device. |
| `start(options)` | Requires `system_audio`. Returns a session with `ready` and `stop()`. |

`start()` options:

| Option | Meaning |
| --- | --- |
| `onFrame(frame)` | Required. Receives `{ amplitude, peak, frequencies }`. |
| `bands` | Entries in `frequencies`: 8 to 64 (default 32). Out-of-range values are clamped. |
| `maxFps` | Most frames per second: 1 to 30 (default 30). The host drops frames above this rate. |
| `stereo` | Optional boolean, default `false`. Adds `frame.stereo.left` and `frame.stereo.right`, each with its own `amplitude`, `peak` and `frequencies`. Requires a stereo-capable native build. |
| `signal` | An `AbortSignal` that ends the session (and closes the prompt, if it is still open). |
| `onEnd(reason)` | Called once if the **host** ends a running session: `revoked` (permission withdrawn), `user-stopped` (the user pressed Stop on the host's indicator), `source-lost` (the device went away) or `host-disabled`. Not called after your own `stop()`. |

Every number in a frame is between 0 and 1. `frequencies` holds `bands` log-spaced magnitudes from roughly 40 Hz to 14 kHz, lowest first. `amplitude` is the overall level and `peak` the loudest recent level.

### Optional stereo

Check both the host contract and the native build. The host capability indicates that the frontend understands the option; `stereoSupported` indicates that the installed desktop client implements it. An older desktop client may load a newer frontend. Requesting unsupported stereo rejects `ready` with `NotSupportedError` before prompting or opening a device.

```ts
const stereo = (ctx.host.capabilities['system-audio-stereo-v1'] ?? 0) >= 1
  && audio.isAvailable().stereoSupported === true;
const session = audio.start({
  stereo,
  bands: 32,
  onFrame(frame) {
    if (frame.stereo) {
      drawLeft(frame.stereo.left.frequencies, frame.stereo.left.amplitude);
      drawRight(frame.stereo.right.frequencies, frame.stereo.right.amplitude);
    } else {
      drawCombined(frame.frequencies, frame.amplitude);
    }
  },
});
void session.ready.catch(showError);
```

The existing top-level fields always retain their combined mono meaning. Left and right are analysed independently before mono downmixing, so opposite-phase content can remain visible in both channels while the combined output is silent. All three spectra have the requested `bands` count and share the `maxFps` limit. Mono consumers receive the original frame shape, even while sharing capture with a stereo consumer. A genuinely mono output is duplicated to both sides.

Windows surround outputs are downmixed using `WAVEFORMATEXTENSIBLE` speaker positions: centre and side/back speakers contribute to their corresponding sides, with a shared gain normalisation to prevent clipping. LFE is omitted from the stereo view and remains included in the original combined mean. Unknown multichannel layouts cannot start stereo capture; Lumiverse does not guess speaker positions. macOS preserves the OS-provided stereo tap, including planar buffers. Linux requests an explicit `front-left,front-right` map from the output monitor.

Stereo uses the same permission, remembered approval, indicator and Stop controls as mono. No audio samples cross IPC.

`session.ready` resolves when the user has approved and analysis has begun. It rejects with a `NotAllowedError` `DOMException` if the user declines, `NotSupportedError` if nothing can provide audio, and `AbortError` if the session was stopped or aborted first.

## What the user sees

- **Explicit consent.** By default, `start()` shows the host's own confirmation, titled with your extension's name. The user can select **Remember my approval for this extension on this device**, unchecked by default. Approval is local to the signed-in account and installed extension on this device; it is not shared with another account, device or reinstallation. A declined or cancelled prompt saves nothing. The user can revoke approval in the extension's permissions area, which also stops an active session. Revoking `system_audio` or uninstalling the extension clears its remembered approval.
- **An indicator for as long as it runs.** The host draws a persistent "*name* is analysing system audio" pill with a **Stop** button outside any extension's DOM, so an extension can neither hide nor restyle it. Pressing Stop ends the session immediately (`onEnd('user-stopped')`). The user can minimise the pill to a small ♪ chip when it is in the way; the chip is never removed while a session runs, Stop is one click from it, and each new session starts expanded. Only the user's own click on the host's component can do this, never an extension.
- **Analysis only.** Lumiverse passes spectrum and loudness to the extension, rebinned and rate-limited. It does not record or transmit audio samples.

Pressing the host indicator's **Stop** pauses future starts for that extension, even if approval was remembered. Calls to `start()` then reject with `NotAllowedError` without opening another prompt or a device. This pause survives reloads. The user must select **Allow requests again** in the extension's permissions area before a new start can proceed; that control permits requests and does not start capture itself. An extension's own `session.stop()` does not pause future starts. Remembered approval does not bypass the `system_audio` permission, the desktop tray switch, or OS permissions.

## Limits and cleanup

- One session per extension at a time; a second `start()` throws `SYSTEM_AUDIO_BUSY` until the first ends.
- `stop()` is idempotent and releases the device at once, including while the device is still starting.
- Revoking `system_audio`, unloading or reloading the extension, aborting the `signal`, the indicator's Stop button and the source going away all end the session. After revocation `start()` throws `PERMISSION_DENIED:system_audio` while `isAvailable()` keeps working. Retained references from an unloaded extension reject with `SPINDLE_FRONTEND_INACTIVE`.
- A frame that arrives after the permission was withdrawn is dropped and ends the session rather than being delivered.
- A throwing `onFrame` is logged and does not stop the session.

This API is frontend-only. Backend workers can receive what you derive from it through the existing frontend messaging API.

## Native adapters

The frontend reaches the device through a small host-internal contract in `frontend/src/lib/spindle/system-audio-source.ts`. A native adapter registers a `SystemAudioSource` with `registerSystemAudioSource()`; extensions cannot reach this registry. A source reports `availability()` cheaply and with no side effects, and `start(handlers, { maxFps, stereo })` begins capture and delivers **analysis frames** (`amplitude`, `peak`, any number of log-spaced bands, plus optional left/right analysis) to `handlers.onFrame`, calling `handlers.onEnd` if it stops on its own. The hints let a source avoid unrequested analysis.

The contract carries analysis only, so audio samples never enter the JavaScript realm the extension shares. An adapter is responsible for:

- applying the platform's own consent (and a clear off switch in the client), in addition to the host's prompt, and reporting `disabled` until the user has turned it on;
- doing the analysis natively and never exposing samples, file paths or device identifiers across IPC;
- stopping on session lock, sleep, sign-out or device loss;
- doing no work while nothing is audible or nobody is looking;
- being tested on a real device: CI cannot validate loopback devices, drivers, or lock behaviour.

### The desktop client's adapter

The Lumiverse desktop client (Tauri) includes an adapter for Windows, macOS and Linux. A browser never registers one.

| | Windows | macOS | Linux |
| --- | --- | --- | --- |
| Source | WASAPI shared-mode loopback on the default output | Core Audio process tap on everything the device plays | The monitor of the default output, read through `parec` |
| Needs | Windows 10 or later | macOS 14.2 or later | `parec` in `/usr/bin`, `/bin`, `/usr/local/bin` or `/run/current-system/sw/bin` (`pulseaudio-utils`, or `pipewire-pulse` on PipeWire) |
| OS permission | None | **System Audio Recording** (not Screen Recording), asked by macOS on first use | None |
| Reports `unsupported` when | Never | Older than 14.2 | `parec` is not installed (for example inside a Flatpak or Snap) |
| Lock | Read from the session's state | Notification | Best effort: asks logind (`LockedHint`) every few seconds |
| Sleep | Power notification | Notification | Exact: uptime runs ahead of the monotonic clock |
| Default output changes | Followed | Followed | Looked up again after ten seconds of quiet |
| Hidden window | Packets drained and discarded | The tap's IO is stopped | The `parec` process is killed and restarted when the window returns |
| Verified on hardware | Yes | **Not yet** | **Not yet** |

**Turning it on.** The feature is off until the owner switches it on in the tray menu with **Let Extensions Analyse System Audio**, which explains what it does and asks first. The choice is remembered. Until then `isAvailable()` reports `disabled`. While an extension is analysing, the tray item reads **Extension Is Analysing System Audio** and the tray icon's tooltip says so; unchecking the item ends every session at once (`onEnd('host-disabled')`). This native switch is the guarantee that listening is never silent: extension code shares the frontend's JavaScript realm, so the web layer's per-start prompt cannot by itself stop a forged call to the native command.

**What crosses IPC.** Native code accepts "start at *n* fps", the optional stereo boolean, and "stop", with an opaque key identifying the adapter installation so late cleanup cannot stop a newer session. Nothing the page sends can pick a device or an arbitrary format. Mono frames retain the original little-endian `f32` layout (`[kind=0, amplitude, peak, 64 bands]`, 268 bytes). Stereo frames use kind 3 followed by the combined, left and right analysis blocks, each with amplitude, peak and 64 bands (796 bytes total). Terminal kinds 1 and 2 keep the original layout. Samples, device names and paths never leave the capture thread, and every platform uses the shared analyser (`analyzer.rs`).

**Who may call it.** Only the primary `frontend` window can start or stop a session (`desktop-system-audio-session`). Only the bundled tray host can flip the switch (`desktop-system-audio-controls`, checked again in Rust against the window label and URL). Floating-widget windows, which host extension pages, receive no grant. A session also ends when the page reloads or the window is destroyed, since nothing is left to receive frames.

Device opening is part of the native session: stop, reload and disable also cancel an opening device, and a late handle is released. Removing the frontend adapter ends its subscribers and stops its own native session. Shared analysis follows the fastest remaining subscriber's frame rate in both directions and enables stereo only while a stereo subscriber exists. On Windows, the default endpoint identity is checked every half second even when the old endpoint is still connected. On macOS, the aggregate includes only the process tap; physical microphone inputs are excluded, and callback buffers are validated before copying complete frames into the ring.

**What ends a session.** The owner unchecking the tray item (`host-disabled`); the session locking, the machine going to sleep, or the output device going away and not coming back within about three seconds (`source-lost`).

**Cost.** Hardware use is the design constraint, not an afterthought, and the pacing is one shared engine (`engine.rs`) rather than per-platform code:

- Silence costs almost nothing. After half a second without sound the adapter sends one zero frame, drops its analysis, and wakes ten times a second just to look for new audio. (On Windows a loopback stream delivers no packets at all while nothing plays. macOS keeps delivering short callbacks of zeros, and a Linux monitor stream may keep delivering silence; both are discarded without analysis.)
- Active cost is one FFT per emitted mono frame, or three while stereo is requested: one combined transform and independent left/right transforms. Each transform is 2048 points at 44.1/48 kHz and larger at higher sample rates so low bands stay resolved. Stereo buffers are allocated only for stereo sessions. Several extensions share one native session at the fastest requested rate, and the session ends when the last one leaves.
- A hidden or minimised frontend window pauses analysis, as the table shows.
- No adapter uses event handles, MMCSS or a raised system timer resolution, which would cost every process on the machine power.
- Measured on Windows 11 with a release build at 30 fps with audio playing: about 0.1 % of one core.

For a reproducible analyser benchmark, run from the repository root:

```sh
rustc --edition=2021 -O desktop/tests/system-audio-benchmark.rs -o /tmp/lumiverse-audio-bench
/tmp/lumiverse-audio-bench
```

This compares mono and stereo sample ingestion, analysis and IPC encoding at 48/96/192 kHz. It reports microseconds per frame and the equivalent share of one core at 30 fps; it excludes OS capture and frontend rendering.

**Limits.** One native capture at a time (extensions share it). Windows does not read packed 24-bit mix formats; the shared-mode mix format is almost always 32-bit float. Starting needs an output device; without one `start()` rejects. On macOS a refused permission makes `start()` reject with instructions; a revoked one later can show as silence.

### On-device acceptance

CI can compile every platform and run the engine, analyser and pipe logic, but it cannot exercise a device, a lock screen or the tray. Windows has been run against real hardware; macOS and Linux have **not**, so they need the full list before release. On a physical session of each OS:

1. With the tray item off, `isAvailable()` is `disabled` and `start()` is refused. Turn it on, start a session, then turn it off while the session runs: the extension gets `host-disabled`.
2. Start from an extension and confirm the host prompt, the in-app indicator, the tray text and the tooltip. Play music: bars follow it. Pause it: frames stop within about a second after one zero frame. Activity Monitor, Task Manager or `top` shows no measurable CPU at idle.
3. Minimise or hide the window: CPU drops to idle (on Linux, `pgrep parec` finds nothing). Restore it: frames resume.
4. Lock the session, sleep and resume, switch the default output device, and reload the frontend: the session ends (or, for a device change, follows the new device) and no tray "in use" text is left behind.
5. Two extensions listening at once share one session; stopping one leaves the other running; stopping both returns the tray to idle.
6. From a floating widget window, attempt `window.__TAURI_INTERNALS__.invoke('desktop_system_audio_start', …)`: it is denied. Attempt it from the main frontend with the tray item off: it is refused.
7. **macOS:** the first start shows the System Audio Recording prompt (and no Screen Recording prompt); refusing it makes `start()` reject with the Settings instructions; granting it makes bars move; the menu bar shows the audio-recording indicator only while a session runs. Test on 14.2, the latest release, Apple silicon and Intel.
8. **Linux:** test on PulseAudio and on PipeWire; with `parec` uninstalled `isAvailable()` is `unsupported`; the monitor of the *output* is recorded, never the microphone (play silence while speaking: the bars must stay flat).
9. **Stereo:** play left-only and right-only tones, then different tones on each side and opposite-phase tones. Check independent spectra, zero cross-channel leakage and unchanged combined fields. Test mono output and Windows 5.1/7.1 layouts, then switch output devices mid-session.
10. Run one mono extension and one stereo extension together. Stopping the stereo extension restores mono analysis without ending the mono consumer. Verify remembered approval, Stop, permission revocation and tray disable with stereo active. An older native build must reject a stereo request with `NotSupportedError` while still accepting mono.

docs.developer-docs/frontend-api/ui-events-he:
# UI Events Helper

The `ctx.ui.events` object provides reactive subscriptions to Lumiverse UI state (keyboard, drawer, settings) and a generic DOM event delegation helper. This is particularly useful for tracking mobile keyboard dimensions and for binding interactions on extension-injected or mounted DOM elements without leaking global event listeners.

## Keyboard State
Access the virtual keyboard presence and safe-area inset (especially on iOS PWA or Android Chrome where the window resizing or visual viewport varies).

```ts
export interface SpindleUIKeyboardState {
  /** True when the host believes a virtual keyboard is currently visible. */
  visible: boolean;
  /** Safe bottom inset in CSS pixels that keeps content above the keyboard. */
  insetBottom: number;
  /** Current visual viewport width in CSS pixels. */
  viewportWidth: number;
  /** Current visual viewport height in CSS pixels. */
  viewportHeight: number;
}
```

```ts
export function setup(ctx: SpindleFrontendContext) {
  // Read synchronously
  const state = ctx.ui.events.getKeyboardState()

  // Subscribe to changes (returns an unsubscribe function)
  const unsub = ctx.ui.events.onKeyboardChange((newState) => {
    if (newState.visible) {
      console.log(`Keyboard opened. Safe inset bottom: ${newState.insetBottom}px`)
    }
  })
}
```

## Drawer State
Track when the side portrait drawer is opened, closed, or switched to a different tab.

```ts
export interface SpindleUIDrawerState {
  open: boolean;
  tabId: string | null;
}
```

```ts
export function setup(ctx: SpindleFrontendContext) {
  const unsub = ctx.ui.events.onDrawerChange(({ open, tabId }) => {
    if (open && tabId === 'my-extension-tab') {
      console.log('User opened my drawer tab!')
    }
  })
}
```

## Settings State
Track when the settings modal is opened, closed, or switched to a different view.

```ts
export interface SpindleUISettingsState {
  open: boolean;
  view: string;
}
```

```ts
export function setup(ctx: SpindleFrontendContext) {
  const unsub = ctx.ui.events.onSettingsChange(({ open, view }) => {
    if (open && view === 'my-extension-settings') {
      console.log('User opened my extension settings panel!')
    }
  })
}
```

## DOM Action Delegation
`bindActionHandlers` is a helper for binding generic interaction events (click, pointer down, etc.) onto extension-owned DOM, such as elements injected via `ctx.dom.inject()`, mounted via `ctx.ui.mount()`, or returned by `ctx.ui.showModal()`.

Instead of adding dozens of individual `.addEventListener()` calls, you can define a dictionary of action handlers. The helper binds a single delegating event listener to the root container and maps events back to your callbacks.

### Usage

```ts
export function setup(ctx: SpindleFrontendContext) {
  // 1. Create your extension-owned DOM
  const root = ctx.ui.mount('sidebar')
  root.innerHTML = `
    <div id="btn-approve" class="btn">Approve</div>
    <div id="btn-reject" class="btn">Reject</div>
  `

  // 2. Bind action handlers
  // The dictionary keys map to the "id" attribute of descendants by default.
  const unbind = ctx.ui.events.bindActionHandlers(root, {
    'btn-approve': (detail) => {
      console.log('Approved!', detail.element, detail.originalEvent)
    },
    'btn-reject': () => {
      console.log('Rejected!')
    }
  })
}
```

### Advanced Binding
You can override the matching attribute and listen to different pointer events.

```ts
const root = ctx.dom.inject('body', `
  <button data-action="swipe-left">Left</button>
  <button data-action="swipe-right">Right</button>
`)

const unbind = ctx.ui.events.bindActionHandlers(root, {
  'swipe-left': (detail) => { /* ... */ },
  'swipe-right': (detail) => { /* ... */ }
}, {
  attribute: 'data-action',
  events: ['pointerdown', 'pointerup']
})
```

*Note: The binding target may be the owned placement root or any owned descendant inside a registered placement root (for example, a mounted action container). The helper throws if you target system UI or another extension's DOM.*

The target must be connected and live when binding. `detail.root` (the `event.root` value) is the exact target supplied to `bindActionHandlers`, while liveness, permission, and revocation follow its nearest registered owner root. Removing or revoking that owner root automatically unbinds the listener; the returned unbind function remains safe to call after automatic cleanup.

docs.developer-docs/frontend-api/uuid.md:
# UUIDs

`ctx.uuid` generates UUID strings synchronously using Lumiverse's existing frontend UUID helper. It needs no permission, backend module, or network request.

`crypto.randomUUID()` is unavailable in insecure browser contexts, such as a Lumiverse instance opened over plain HTTP on a remote host. This helper uses `crypto.getRandomValues()`, which is available in those contexts.

`frontend-uuid-v1` advertises this frontend API. The backend capability `uuid-v1` does not imply that `ctx.uuid` exists. Feature-detect both the frontend capability and the member when supporting older hosts:

```ts
import type { SpindleFrontendContext } from 'lumiverse-spindle-types'

export function setup(ctx: SpindleFrontendContext) {
  if (!ctx.uuid || (ctx.host.capabilities['frontend-uuid-v1'] ?? 0) < 1) {
    throw new Error('This extension requires frontend-uuid-v1. Update Lumiverse.')
  }

  const randomId = ctx.uuid.v4()
  const orderedId = ctx.uuid.v7()
  // Both values are strings immediately; no await is needed.
}
```

| Method | Returns | Description |
|--------|---------|-------------|
| `v4()` | `string` | Random UUID with 122 random bits |
| `v7()` | `string` | Timestamp-ordered UUID using the frontend clock and shared helper counter |

Both methods return lowercase UUID strings in `8-4-4-4-12` hexadecimal format. Existing stored IDs do not need to change. Calls throw for an inactive or unloaded frontend context, including captured method references.

Frontend v7 calls share the core helper's counter within the same frontend runtime. They do not share the backend counter or establish ordering across browser tabs, devices, or server processes. Use [the backend UUID API](../backend-api/uuid.md) when generation should belong to the backend; its methods return `Promise<string>`.

